import { ColumnInfo, SortControl } from "@codesight/codesight-controller-proto/controller_proto/v1/issues_service_pb";
import { LocalizeFunc, loadMessageBundle } from "vscode-nls";

const localize: LocalizeFunc = loadMessageBundle();
export class NewIssueSortState {
    isDefaultSortAscending: boolean;
    isAscending: boolean;
    id: string;
    sortName: string;

    constructor(columnInfo: ColumnInfo, isAscending: boolean) {
        this.id = columnInfo.getId();
        this.sortName = columnInfo.getName();
        this.isAscending = isAscending;
        this.isDefaultSortAscending = this.getDefaultSortOrder();
    }

    getDisplayString(): string {
        return `${this.sortName} (${this.getOrderingDisplayString()})`;
    }

    getDefaultSortOrder(): boolean {
        switch (this.id) {
            case 'severity':
                return false;
            default:
                return true;
        }
    }

    getOrderingDisplayString() {
        switch (this.id) {
            case 'location':
                return this.isAscending ? localize("sort.order.ascending", "Ascending") : localize("sort.order.descending", "Descending");
            case 'severity':
                return this.isAscending ? localize("sort.order.low.to.high", "Low to High") : localize("sort.order.high.to.low", "High to Low");
            case 'type':
            default:
                return this.isAscending ? localize("sort.order.a.to.z", "A-Z") : localize("sort.order.z.to.a", "Z-A");
        }
    }

    toProtoClass(): SortControl {
        let sortControl = new SortControl();
        sortControl.setSortdirection(this.isAscending ? SortControl.SortOrder.ASCENDING : SortControl.SortOrder.DESCENDING);
        sortControl.setSortfield(this.id);
        return sortControl;
    }
}

export function getDefaultNewSortState(): NewIssueSortState {
    let columnInfo = new ColumnInfo();
    columnInfo.setId('severity');
    columnInfo.setName('Severity');
    return new NewIssueSortState(columnInfo, false);
}