import { ConfiguredSource, IssueSource, ReferenceInfo, RemoteReference } from "@codesight/codesight-controller-proto/controller_proto/v0/config_pb";
import { ScanConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/scan_config_pb";
import { ServerType } from "@codesight/codesight-controller-proto/controller_proto/v0/server_info_pb";
import { GetIssueSourceRequest, GetIssueSourceStructureRequest, GetIssueSourceStructureResponse, PageControl } from "@codesight/codesight-controller-proto/controller_proto/v1/issues_service_pb";
import * as vscode from 'vscode';
import { TEAM_VIEW_SERVER_TYPE_SUPPORTS_MARKERS_AND_ACTIVE_FILE_FILTER, TEAM_VIEW_SERVERS } from "../utils/constants";
import { getLogger } from "../utils/logger";
import { getSourceDisplayString } from "../utils/typeUtils";
import { AnalysisContextService } from "./analysisContextService";
import { AuthenticationService } from "./authenticationService";
import { ConfigurationService } from "./configurationService";
import { ControllerClientService } from "./controllerClientService";
import { getService, ServiceId } from "./serviceContainer";

export const ISSUE_SOURCE_SELECTED_CONTEXT = "codesight.issueSourceSelected";
export const TEAM_VIEW_SERVER_TYPE_SUPPORTS_ACTIVE_FILE_FILTER_CONTEXT = "codesight.teamViewServerTypeSupportsActiveFileFilter";

export interface RemoteIssueSource {
    sourceID: string;
    sourceName: string;
    serverType: ServerType;
    sourceRef: ConfiguredSource;
    fullDisplayString: string;
}

export class SourceType {
    private serverType: ServerType | undefined;
    private scanType: ScanConfig.ScanType | undefined;
    private context: GetIssueSourceStructureRequest.Context;

    constructor(serverType?: ServerType, scanType?: ScanConfig.ScanType, context = GetIssueSourceStructureRequest.Context.REMOTE) {
        this.serverType = serverType;
        this.scanType = scanType;
        this.context = context;
    }

    getServerType(): ServerType | undefined {
        return this.serverType;
    }

    getScanType(): ScanConfig.ScanType | undefined {
        return this.scanType;
    }

    getContext(): GetIssueSourceStructureRequest.Context {
        return this.context;
    }
}

/**
 * Defines a service meant for handling issue source configuration
 */
export abstract class IssueSourceConfigService {
    static readonly id: ServiceId<IssueSourceConfigService> = { id: IssueSourceConfigService.name };

    /**
     * Fetches a list of issue sources that are available in the server
     * @param sourceType type of the sourceType to fetch the sources from
     * @param remoteReference referenceInfo of a selected source from issue source configuration view
     */
    abstract fetchIssueSourceList(sourceType: SourceType, remoteReference?: RemoteReference): Promise<RemoteReference[]>;

    /**
     * Saves configured source from issue source configuration view
     */
    abstract configureSource(serverType: ServerType, source: RemoteReference): Promise<void>;

    /**
     * Retrieves the cached list of configured issue sources
     * @param shouldRefresh if set, fetches the list directly from controller
     */
    abstract getConfiguredIssueSourceList(shouldRefresh?: boolean): Promise<RemoteIssueSource[]>;

    /**
     * Refreshes the cached list of configured issue sources
     */
    abstract refreshConfiguredSourceList(): Promise<void>;

    /**
     * Saves the source selected from the view
     */
    abstract setSelectedSource(source: RemoteIssueSource): Promise<void>;

    /**
     * Returns the source selected from the view
     */
    abstract getSelectedSource(): RemoteIssueSource | undefined;

    /**
     * Retrieves the steps required to show for issue source configuration
     */
    abstract getSourceStructureForServer(sourceType: SourceType): Promise<GetIssueSourceStructureResponse>;

    abstract addListener(listener: IssueSourceConfigServiceListener): void;
    abstract removeListener(listener: IssueSourceConfigServiceListener): void;
}

export abstract class IssueSourceConfigServiceListener {
    abstract onSelectedSourceChanged(): Promise<void>;
    abstract onIssueSourceListUpdated(): Promise<void>;
}

export class IssueSourceConfigServiceImpl implements IssueSourceConfigService {
    protected issueSourceConfigListeners: IssueSourceConfigServiceListener[];
    private selectedSource: RemoteIssueSource | undefined;
    private configuredSourceList: RemoteIssueSource[] = [];

    constructor() {
        this.issueSourceConfigListeners = [];
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        this.updateIssueSourceSelectedContext();
    }

    async setSelectedSource(remoteSource: RemoteIssueSource): Promise<void> {
        try {
            let response = await getService(ConfigurationService.id).updateActiveIssueSource(remoteSource.sourceRef.getId());
            if (response && response.getErrorList().length !== 0) {
                getLogger().warn(`Error while trying to configure sources, err=${response.getErrorList().toString()}`);
            } else {
                this.selectedSource = remoteSource;
            }
        } catch (error) {
            getLogger().warn(`setSelectedSource failed with error: ${error}`);
            this.selectedSource = undefined;
        }

        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        this.updateIssueSourceSelectedContext();
        await this.notifyListenersOfIssueSourceChanged();
    }

    getSelectedSource(): RemoteIssueSource | undefined {
        return this.selectedSource;
    }

    async getConfiguredIssueSourceList(shouldRefresh?: boolean): Promise<RemoteIssueSource[]> {
        if (this.configuredSourceList.length === 0 || shouldRefresh) {
            await this.refreshConfiguredSourceList();
        }

        return this.configuredSourceList;
    }

    async configureSource(serverType: ServerType, source: RemoteReference) {
        let issueSource = new IssueSource();
        issueSource.setServer(getService(AuthenticationService.id).getServerInfo(serverType));
        issueSource.setServertype(serverType);
        issueSource.setReference(source);

        try {
            let response = await getService(ConfigurationService.id).configureNewIssueSource(issueSource);
            if (response && response.getErrorList().length !== 0) {
                getLogger().warn(`Error while trying to configure sources, err=${response.getErrorList().toString()}`);
                return Promise.reject(response.getErrorList()[0]);
            }
            await this.refreshConfiguredSourceList();
        } catch (error) {
            getLogger().warn(`configureSource failed with error: ${error}`);
        }

        return this.notifyListenersOfIssueSourceListUpdate();
    }

    async refreshConfiguredSourceList(): Promise<void> {
        let configResponse = await getService(ConfigurationService.id).getConfiguration();
        let issueSourceConfig = configResponse.getWorkspaceconfig()?.getIssuesourceconfig();
        const logger = getLogger();
        if (!issueSourceConfig) {
            logger.warn("refreshConfiguredSourceList(): issueSourceConfig was undefined");
            return;
        }

        let issueSourceList = issueSourceConfig?.getConfiguredsourcesList();
        if (!issueSourceList) {
            logger.warn("refreshConfiguredSourceList(): issueSourceList was undefined");
            return;
        }

        let activeSourceID: string | undefined = issueSourceConfig.getActivesourceid();
        let activeSource: RemoteIssueSource | undefined;
        let serverTypeToSources = new Map<ServerType, RemoteIssueSource[]>();

        TEAM_VIEW_SERVERS.forEach(server => {
            serverTypeToSources.set(server, []);
        });

        issueSourceList.forEach(source => {
            let serverType = source.getSource()?.getServertype() ?? ServerType.UNKNOWNSERVERTYPE;
            let remoteIssueSource = {
                sourceID: source.getId(),
                sourceName: source.getSource()?.getReference()?.getInfo()?.getDisplayname() ?? "unnamed source",
                serverType: serverType,
                sourceRef: source,
                fullDisplayString: getSourceDisplayString(source),
            };

            serverTypeToSources.get(serverType)?.push(remoteIssueSource);

            // keep track of the active source
            if (remoteIssueSource.sourceID === activeSourceID) {
                activeSource = remoteIssueSource;
            }
        });
        
        //stored activeSourceID doesn't match any existing sources, clear activeSourceID so it defaults to the first source in the list
        if (activeSourceID && !activeSource) {
            activeSourceID = undefined;
        }

       let fullSourceList: RemoteIssueSource[] = [];
       for (const sources of serverTypeToSources.values()) {
            fullSourceList = fullSourceList.concat(sources);
        }

        this.configuredSourceList = fullSourceList;

        // set active source
        if (activeSourceID && !activeSource && this.selectedSource?.serverType) {
            const selectedServerType = serverTypeToSources.get(this.selectedSource?.serverType);
            // overwrite the selected source based on server type
            if (selectedServerType && selectedServerType.length > 0) {
                await this.setSelectedSource(selectedServerType[0]);
            }
        } else if (!activeSourceID && fullSourceList.length !== 0) {
            // select the first source from the list
            await this.setSelectedSource(fullSourceList[0]);
        } else {
            this.selectedSource = activeSource;
        }
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        this.updateIssueSourceSelectedContext();
    }
   
    async fetchIssueSourceList(sourceType: SourceType, issueReference?: RemoteReference): Promise<RemoteReference[]> {
        let pageControl = new PageControl();
        pageControl.setSelection(PageControl.Selection.RESET);

        let request = new GetIssueSourceRequest();
        request.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        request.setPagecontrol(pageControl);
        if (sourceType.getServerType()) {
            request.setServertype(sourceType.getServerType()!);
        }

        if (sourceType.getScanType()) {
            request.setScantype(sourceType.getScanType()!);
        }

        let filter = new GetIssueSourceRequest.SourceFilter();
        filter.setContext(sourceType.getContext());
        if (issueReference) {    
            filter.setSearch(issueReference);
        }
        request.setFilter(filter);

        const issuesService = await getService(ControllerClientService.id).getIssuesServiceClient();
        let response = await issuesService.getIssueSource(request);
        let error = response.getError();
        if (error) {
            return Promise.reject(error);
        }

        let referenceInfoList: ReferenceInfo[] = response.getSourceList();
        let hasNextPage = response.getPageinfo()?.getHasnextpage();
        while (hasNextPage) {
            pageControl.setSelection(PageControl.Selection.NEXT);
            request.setPagecontrol(pageControl);
            let newResponse = await issuesService.getIssueSource(request);
            referenceInfoList = referenceInfoList.concat(newResponse.getSourceList());
            hasNextPage = newResponse.getPageinfo()?.getHasnextpage() ?? false;
        }

        let result: RemoteReference[] = [];
        let parentReference = response.getParent();
        referenceInfoList.forEach(referenceInfo => {
            let remoteReference = new RemoteReference();
            remoteReference.setInfo(referenceInfo);
            remoteReference.setParent(parentReference);
            result.push(remoteReference);
        });

        return result;
    }

    async getSourceStructureForServer(sourceType: SourceType): Promise<GetIssueSourceStructureResponse> {
        let request = new GetIssueSourceStructureRequest();
        request.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        if (sourceType.getServerType()) {
            request.setServertype(sourceType.getServerType()!);
        }

        if (sourceType.getScanType()) {
            request.setScantype(sourceType.getScanType());
        }

        if (sourceType.getContext()) {
            request.setContext(sourceType.getContext());
        }

        const issuesServiceClient = await getService(ControllerClientService.id).getIssuesServiceClient();
        return issuesServiceClient.getIssueSourceStructure(request);
    }

    addListener(listener: IssueSourceConfigServiceListener): void {
        this.issueSourceConfigListeners.push(listener);
    }

    removeListener(listener: IssueSourceConfigServiceListener): void {
        let index = this.issueSourceConfigListeners.indexOf(listener);
        if (index >= 0) {
            this.issueSourceConfigListeners.splice(index, 1);
        }
    }

    private updateIssueSourceSelectedContext(): void {
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        vscode.commands.executeCommand("setContext", ISSUE_SOURCE_SELECTED_CONTEXT, this.selectedSource !== undefined);
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        vscode.commands.executeCommand("setContext", TEAM_VIEW_SERVER_TYPE_SUPPORTS_ACTIVE_FILE_FILTER_CONTEXT, this.selectedSource?.serverType !== undefined && TEAM_VIEW_SERVER_TYPE_SUPPORTS_MARKERS_AND_ACTIVE_FILE_FILTER.includes(this.selectedSource?.serverType));
    }

    private async notifyListenersOfIssueSourceChanged() {
        let promises: Promise<void>[] = [];
        this.issueSourceConfigListeners.forEach(listener => {
            promises.push(listener.onSelectedSourceChanged());
        });

        await Promise.all(promises);   
    }

    private async notifyListenersOfIssueSourceListUpdate() {
        let promises: Promise<void>[] = [];
        this.issueSourceConfigListeners.forEach(listener => {
            promises.push(listener.onIssueSourceListUpdated());
        });

        await Promise.all(promises);   
    }
}