import { Webview } from "vscode";
import { LocalizeFunc, loadMessageBundle } from "vscode-nls";
import { ServiceId } from "../../services/serviceContainer";
import { getViewSpinnerCSS, getViewSpinnerHTML } from "../../utils/components/spinnerComponents";
import { getWebviewHead } from "../../utils/webviewUtils";
import { WebviewProvider } from "../webviewProvider";
const localize: LocalizeFunc = loadMessageBundle();

export abstract class ScanConfigViewProvider extends WebviewProvider {
    static readonly id: ServiceId<ScanConfigViewProvider> = { id: ScanConfigViewProvider.name };

    abstract initHtml(): void;
    abstract initLoading(): void;
}

export class ScanConfigViewProviderImpl extends ScanConfigViewProvider {
    constructor() {
        super();
    }

    initLoading(): void {
        let text = localize("react.webview.loading", "Loading...");
            let textTabTitle = localize('webview.scan.config.title', 'Scan Configuration');
            let html = /*html*/`<html class="sc-html">
                            <head>
                                ${this.head}
                            </head>       
                            <style>
                                ${this.style}
                                ${getViewSpinnerCSS()}
                            </style>
                            <body>
                            ${getViewSpinnerHTML(text)}
                            </body>
                        </html>`;
    
            this.webviewPanel!.title = textTabTitle;
            this.webviewPanel!.webview.html = html;
    }

    public initHtml(): void {
        let html = /*html*/`<html class="sc-html">
                    <head>
                        ${this.head}
                    </head>
                    <style>
                        ${this.style}
                    </style>
                    <body>
                        <div id="root"></div>
                    </body>
                    ${this.sharedScripts}
                    </html>
        `;

        this.webviewPanel!.webview.html = html;
    }

    protected getHead(webview: Webview): string {
        return getWebviewHead(localize('webview.scan.config.title', 'Scan Configuration'), webview);
    }

    // CSS should be handled in webview-ui
    protected getStyle(): string {
        return '';
    }

    // CSS should be handled in webview-ui
    protected supportsCollapsibleSections(): boolean {
        return false;
    }
}
