import { AuthenticationMethod, ServerType } from "@codesight/codesight-controller-proto/controller_proto/v0/server_info_pb";
import { TextEncoder } from "util";

export class AuthModel {
    private userName: string;
    private url: string;
    private password: Uint8Array;
    private authkey: string;
    private authMethod: AuthenticationMethod;
    private serverType: ServerType;

    constructor() {
        this.userName = "";
        this.url = "";
        this.password = new Uint8Array();
        this.authkey = "";
        this.authMethod = AuthenticationMethod.UNKNOWNAUTHENTICATIONMETHOD;
        this.serverType = ServerType.UNKNOWNSERVERTYPE;
    }

    public getUserName(): string {
        return this.userName;
    }

    public getUrl(): string {
        return this.url;
    }

    public getPassword(): Uint8Array {
        return this.password;
    }

    public getAuthkey(): string {
        return this.authkey;
    }

    public getAuthMethod(): AuthenticationMethod {
        return this.authMethod;
    }

    public getServerType(): ServerType {
        return this.serverType;
    }

    public setUserName(userName: string): AuthModel {
        this.userName = userName;
        return this;
    }

    public setUrl(url: string): AuthModel {
        this.url = url;
        return this;
    }

    public setPassword(password: string): AuthModel {
        let enc = new TextEncoder();
        this.password = enc.encode(password);
        return this;
    }

    public setAuthkey(authkey: string): AuthModel {
        this.authkey = authkey;
        return this;
    }

    public setAuthMethod(authMethod: AuthenticationMethod): AuthModel {
        this.authMethod = authMethod;
        return this;
    }

    public setServerType(serverType: ServerType): AuthModel {
        this.serverType = serverType;
        return this;
    }
}