import { homedir } from "os";
import { basename, dirname, join } from "path";
import { Uri, commands, window, workspace } from "vscode";
import { LocalizeFunc, loadMessageBundle } from "vscode-nls";
import { getLogger } from "../utils/logger";
import { ExportScanResultsService } from "./exportScanResultsService";
import { LocalViewIssuesListService } from "./issuesService";
import { ScanService } from "./scanService";
import { ServiceId, getService } from "./serviceContainer";
import { VscodeContextService } from "./vscodeContextService";

const localize: LocalizeFunc = loadMessageBundle();

const CONTEXT_KEY_HAS_EXPORTABLE_RESULTS = 'codesight.hasExportableResultsFile';
const CONTEXT_KEY_IS_SCAN_TYPE_SUPPORTED = 'codesight.isScanTypeSupported';

export abstract class ScanResultsExportService {
    static readonly id: ServiceId<ScanResultsExportService> = { id: ScanResultsExportService.name };

    abstract exportCurrentScanResults(): Promise<void>;
    abstract updateExportAvailability(): Promise<void>;
}

export class ScanResultsExportServiceImpl extends ScanResultsExportService {
    async exportCurrentScanResults(): Promise<void> {
        try {
            const { selectedScanType } = await getService(LocalViewIssuesListService.id).getAvailableScanInfos();
            
            if (!selectedScanType) {
                await window.showInformationMessage(localize('localview.export.no.results', 'No scan results available to export.'));
                return;
            }

            const resultsInfo = await getService(ExportScanResultsService.id).getScanResultsInfo(selectedScanType);
            const scanResultsUri = Uri.file(resultsInfo.scanResultsFilePath);
            const exportFileName = resultsInfo.exportFileName;

            try {
                await workspace.fs.stat(scanResultsUri);
            } catch (error) {
                await window.showErrorMessage(localize('localview.export.file.not.found', 'Scan results file not found: {0}', resultsInfo.scanResultsFilePath));
                getLogger().error('Scan results file not found', error);
                return;
            }

            // Use last export location if available, otherwise default to Desktop
            const contextService = getService(VscodeContextService.id);
            const lastExportDir = contextService.getPreservedExportDirectory();
            const defaultDir = lastExportDir || join(homedir(), 'Desktop');
            const defaultSavePath = join(defaultDir, exportFileName);

            const exportUri = await window.showSaveDialog({
                defaultUri: Uri.file(defaultSavePath),
                saveLabel: localize('localview.export.save.label', 'Export'),
                filters: {
                    'JSON Files': ['json']
                }
            });

            if (!exportUri) {
                // User cancelled the dialog
                return;
            }

            const exportPath = dirname(exportUri.fsPath);
            const selectedFileName = basename(exportUri.fsPath);

            const success = await getService(ExportScanResultsService.id).exportScanResults(
                selectedScanType, 
                exportPath, 
                selectedFileName
            );

            if (!success) {
                await window.showErrorMessage(localize('localview.export.error', 'Failed to export scan results'));
                return;
            }

            await contextService.preserveExportDirectory(exportPath);

            const action = await window.showInformationMessage(
                localize('localview.export.success', 'Scan results exported successfully to {0}', exportUri.fsPath),
                localize('localview.export.open.file', 'Open File')
            );

            if (action) {
                await commands.executeCommand('vscode.open', exportUri);
            }
        } catch (error) {
            getLogger().error('Failed to export scan results', error);
            await window.showErrorMessage(localize('localview.export.error', 'Failed to export scan results: {0}', String(error)));
        }
    }

    async updateExportAvailability(): Promise<void> {
        try {
            const { selectedScanType, selectedScanInfo } = await getService(LocalViewIssuesListService.id).getAvailableScanInfos();
            
            if (!selectedScanType) {
                await commands.executeCommand('setContext', CONTEXT_KEY_HAS_EXPORTABLE_RESULTS, false);
                await commands.executeCommand('setContext', CONTEXT_KEY_IS_SCAN_TYPE_SUPPORTED, false);
                return;
            }

            // Check if scan type is supported for export
            const scanTypeObj = selectedScanType;
            const isScanTypeSupported = getService(ExportScanResultsService.id).isScanTypeSupported(scanTypeObj.getType());
            await commands.executeCommand('setContext', CONTEXT_KEY_IS_SCAN_TYPE_SUPPORTED, isScanTypeSupported);

            // Check if currently viewing results from a running scan
            const scanService = getService(ScanService.id);
            const isLocalViewScanRunning = scanService.isLocalViewScanRunning();
            const runningScanId = scanService.getLocalViewLastScanId();
            const selectedScanId = selectedScanInfo?.getScanid();
            
            // Disable export if:
            // 1. A scan is running AND
            // 2. We're viewing results from that running scan (scan IDs match)
            const isViewingRunningScan = isLocalViewScanRunning && runningScanId && selectedScanId && runningScanId === selectedScanId;

            // Only check for results if the scan type is supported and not viewing running scan
            if (isScanTypeSupported && !isViewingRunningScan) {
                const resultsExist = await getService(ExportScanResultsService.id).checkScanResultsExist(selectedScanType);
                await commands.executeCommand('setContext', CONTEXT_KEY_HAS_EXPORTABLE_RESULTS, resultsExist);
            } else {
                await commands.executeCommand('setContext', CONTEXT_KEY_HAS_EXPORTABLE_RESULTS, false);
            }
        } catch (error) {
            getLogger().error('Failed to check exportable results file', error);
            await commands.executeCommand('setContext', CONTEXT_KEY_HAS_EXPORTABLE_RESULTS, false);
            await commands.executeCommand('setContext', CONTEXT_KEY_IS_SCAN_TYPE_SUPPORTED, false);
        }
    }
}
