import { TrustCertificateResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/configuration_service_pb";
import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { Disposable, WebviewPanel } from "vscode";
import { LocalizeFunc, loadMessageBundle } from "vscode-nls";
import { ConfigurationService } from "../../services/configurationService";
import { getService } from "../../services/serviceContainer";
import { getLogger } from "../../utils/logger";
import { getCertPEMFormat, getHost } from "../../utils/notificationMessageUtils";
import { WebviewPresenter } from "../../views/webviewPresenter";
import { UntrustedCertCommandId, UntrustedCertMessageViewProvider } from "./untrustedCertMessageViewProvider";

const localize: LocalizeFunc = loadMessageBundle();

export class UntrustedCertMessageViewPresenter implements WebviewPresenter {
    private readonly panel: WebviewPanel;
    private view: UntrustedCertMessageViewProvider;
    private onMessageFromWebviewDisposable: Disposable | undefined;
    private notificationMessage: NotificationMessage;

    constructor(notificationMessage: NotificationMessage, panel: WebviewPanel) {
        this.panel = panel;
        this.notificationMessage = notificationMessage;
        this.view = getService(UntrustedCertMessageViewProvider.id);
        this.view.initView(this.panel);

        this.onMessageFromWebviewDisposable = this.view.onMessageFromWebview(async message => {
            const logger = getLogger();
            let cert = getCertPEMFormat(notificationMessage);
            let host = getHost(notificationMessage);
            switch (message.command) {
                case UntrustedCertCommandId.ACCEPT_BUTTON:
                    await this.sendRequest(cert, host, true);
                    break;
                case UntrustedCertCommandId.REJECT_BUTTON:
                    await this.sendRequest(cert, host, false);
                    break;
                default:
                    logger.warn(`Received unexpected message ${ message.command }`);
                    break;
            }

            return Promise.resolve();
        });
    }

    public async handleResponse(trust: boolean, response?: TrustCertificateResponse) {
        if (response) {
            if (trust && !response.getSuccess()) {
                this.view.postMessageToWebview({
                    command: UntrustedCertCommandId.STATUS_FAILED,
                    message: response.getMessage()
                });
            } else {
                await this.view.dispose();
            }
        }
    }

    private async sendRequest(cert: string, host: string, trust: boolean) {
        this.view.postMessageToWebview({
            command: UntrustedCertCommandId.STATUS_IN_PROGRESS
        });

        let response = await getService(ConfigurationService.id).trustCertificate(cert, host, trust);
        await this.handleResponse(trust, response);
    }

    public async initView(): Promise<void> {
        this.view.initHtml(this.notificationMessage);        
    }

    public async parseNotification(message: NotificationMessage): Promise<void> {
        // no-op
    }

    public dispose(): void {
        this.onMessageFromWebviewDisposable?.dispose();
    }
}