import { Comparable } from "../utils/interfaces";

export function nullableComparison<T extends Comparable<T>>(a: T | undefined, b: T | undefined): boolean {
    if (a === undefined && b === undefined) {
        return true;
    } else if (a === undefined && b !== undefined) {
        return false;
    } else if (a !== undefined && b === undefined) {
        return false;
    } else if (a !== undefined && b !== undefined) {
        return a.equals(b);
    }

    return false;
}

