import { CheckLicenseResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/license_service_pb";
import { Timestamp } from "google-protobuf/google/protobuf/timestamp_pb";
import { getElapsedTimeSinceDate, getPrettyLocalDateString } from "../utils/dateUtils";
import { Comparable } from "../utils/interfaces";

export class CsseLicenseInfo implements Comparable<CsseLicenseInfo> {
    _isTrial: boolean;
    isEntitled: boolean;
    expiry: Timestamp | undefined;
    licenseState: CsseLicenseState;

    constructor(isTrial: boolean, isEntitled: boolean, isExpired: Timestamp | undefined, licenseState: CheckLicenseResponse.LicenseState) {
        this._isTrial = isTrial;
        this.isEntitled = isEntitled;
        this.expiry = isExpired;
        this.licenseState = convertLicenseState(licenseState);
    }

    getState(): CsseLicenseState {
        return this.licenseState;
    }

    getExpiry(): Timestamp | undefined {
        return this.expiry;
    }

    getExpiryDateString(): string {
        let timestamp = this.expiry;
        if (timestamp) {
            let date = timestamp.toDate();
            return getElapsedTimeSinceDate(date);
        }
        return "";
    }

    getExpiredDateString(): string {
        let timestamp = this.expiry;
        if (timestamp) {
            let date = timestamp.toDate();
            return getPrettyLocalDateString(date);
        }

        return "";
    }

    isTrial(): boolean {
        return this._isTrial;
    }

    isEntitledToCSSE(): boolean {
        return this.isEntitled;
    }

    equals(obj: CsseLicenseInfo): boolean {
        return (obj.isTrial() === this.isTrial() &&
            obj.isEntitledToCSSE() === this.isEntitledToCSSE() &&
            obj.getExpiry() === this.getExpiry() &&
            obj.getState() === this.getState());
    }
}

export enum CsseLicenseState {
    Unknown,
    Valid,
    Expired,
    InvalidKey,
    InvalidFile,
    CouldNotVerify,
    EmailVerificationRequired,
    NoLicense
}

function convertLicenseState(licenseState: CheckLicenseResponse.LicenseState): CsseLicenseState {
    switch (licenseState) {
        case CheckLicenseResponse.LicenseState.UNKNOWN:
            return CsseLicenseState.Unknown;
        case CheckLicenseResponse.LicenseState.VALID:
            return CsseLicenseState.Valid;
        case CheckLicenseResponse.LicenseState.EXPIRED:
            return CsseLicenseState.Expired;
        case CheckLicenseResponse.LicenseState.INVALIDKEY:
            return CsseLicenseState.InvalidKey;
        case CheckLicenseResponse.LicenseState.INVALIDFILE:
            return CsseLicenseState.InvalidFile;
        case CheckLicenseResponse.LicenseState.COULDNOTVERIFY:
            return CsseLicenseState.CouldNotVerify;
        case CheckLicenseResponse.LicenseState.EMAILVERIFICATIONREQUIRED:
            return CsseLicenseState.EmailVerificationRequired;
        case CheckLicenseResponse.LicenseState.NOLICENSE:
            return CsseLicenseState.NoLicense;
    }
}
