import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { WebviewPanel } from "vscode";
import { getService } from "../../services/serviceContainer";
import { WebviewPresenter } from "../webviewPresenter";
import { DownloadViewProvider } from "./downloadViewProvider";

export class DownloadViewPresenter implements WebviewPresenter {
    private readonly panel: WebviewPanel;
    private view: DownloadViewProvider;

    constructor(panel: WebviewPanel) {
        this.panel = panel;
        this.view = getService(DownloadViewProvider.id);
        this.view.initView(this.panel);
    }

    public async parseNotification(message: NotificationMessage) {
        let additionalContentList = message.getAdditionalcontentList();

        if (additionalContentList.length === 0) {
            return;
        }

        let additionalContent = message.getAdditionalcontentList()[0];

        this.view.postMessageToWebview({
            command: "update-progress",
            title: additionalContent.getTitle(),
            content: additionalContent.getContent(),
        });

    }

    public async initView() {
        this.view.reloadHtml();
    }

    public dispose() {
        // Nothing to dispose
    }
}