import { ServerInfo } from "@codesight/codesight-controller-proto/controller_proto/v0/server_info_pb";
import { Error } from "@codesight/codesight-controller-proto/controller_proto/v0/tool_service_pb";
import { Semaphore } from "prex";
import * as vscode from 'vscode';
import { Event, EventEmitter, ProviderResult, TreeItem } from "vscode";
import { LocalizeFunc, loadMessageBundle } from "vscode-nls";
import { NewIssue } from "../../models/newIssue";
import { IssueSourceConfigService, RemoteIssueSource } from "../../services/issueSourceConfigService";
import { IssuesListIdentifier, PageControls } from "../../services/issuesService";
import { getService } from "../../services/serviceContainer";
import { COMMAND_OPEN_TEAM_VIEW_FILTER_VIEW__FILTERS_APPLIED, COMMAND_OPEN_TEAM_VIEW_ISSUE_SOURCE_VIEW, COMMAND_SHOW_ISSUE_SOURCE_SERVER_CONFIG, ThemeIconId } from '../../utils/constants';
import { ButtonNode, DescriptionNode, IssueListLoadingNode, IssueNode, IssueSourceSelectionNode, PagerNode, ReloadableTreeDataProvider, SeparatorNode, Status, StatusNode, TreeNodeProvider } from "../../utils/issuePresenterUtils";
import { getLogger } from "../../utils/logger";
import { isTeamViewFilteringSupported } from "../../utils/typeUtils";
import { COMMAND_SHOW_REMOTE_ISSUE_LIST_ERROR, COMMAND_TEAM_VIEW_RESTORE_FULL_LIST, REFRESH_REMOTE_ISSUES } from "./teamViewPresenter";

const localize: LocalizeFunc = loadMessageBundle();

export interface TeamViewTreeProvider extends ReloadableTreeDataProvider<TreeNodeProvider> {
    reloadView(state: TeamViewIssueFoundTreeState): Promise<void>;
    reloadViewSimple(issuesList: NewIssue[], totalIssueCount: number | undefined, pageControls: PageControls, baseState: TeamViewIssueFoundTreeState): Promise<void>;
    isShowingIssues(): boolean;
}

export class TeamViewTreeProviderImpl implements TeamViewTreeProvider {
    private _onDidChangeTreeData: EventEmitter<TreeNodeProvider | null> = new EventEmitter<TreeNodeProvider | null>();
    readonly onDidChangeTreeData: Event<TreeNodeProvider | null> = this._onDidChangeTreeData.event;
    protected viewLock = new Semaphore(0, 1);

    private root_nodes: TreeNodeProvider[];
    private pageControls: PageControls;
    private issuesShown: boolean;

    constructor(pageControls: PageControls) {
        this.pageControls = pageControls;
        this.issuesShown = false;
        this.root_nodes = [];
        this.viewLock.release();
    }

    isShowingIssues(): boolean {
        return this.issuesShown;
    }
    
    getTreeItem(node: TreeNodeProvider): TreeItem | Thenable<TreeItem> {
        return node.getTreeItem();
    }

    getChildren(node?: TreeNodeProvider): ProviderResult<TreeNodeProvider[]> {
        if (!node) {
            return this.root_nodes;
        }
        return node?.getChildren();
    }

    getParent(element: TreeNodeProvider): ProviderResult<TreeNodeProvider> {
        return element.getParent();
    }
    
    async reloadNode(node: TreeNodeProvider | null) {
        this._onDidChangeTreeData.fire(node);
    }


     async reloadViewSimple(issuesList: NewIssue[], totalIssueCount: number | undefined, pageControls: PageControls, baseState: TeamViewIssueFoundTreeState) {
        const singleIssueState = {
            ...baseState,
            loading: false,
            issuesList: issuesList,
            viewMoreIssues: true,
        };

        await this.reloadView(singleIssueState);
    }

    async reloadView(state: TeamViewIssueFoundTreeState) {
        this.issuesShown = false;

        try {
            await this.viewLock.wait();
            this.root_nodes = [];

            if (state.availableServers.length === 0) {
                let errorNode = this.buildNoServerErrorNode();
                this.root_nodes = errorNode;
                return this.reloadNode(null);
            }

            const separator = new SeparatorNode(); // separator initialized beforehand to be able to update the issues list id
            this.root_nodes.push(new IssueSourceSelectionNode(state.availableServers, state.sourceList, state.selectedSource));
            this.root_nodes.push(separator);

            if (state.loading) {
                this.root_nodes = this.root_nodes.concat(new IssueListLoadingNode());
                return this.reloadNode(null);
            }

            if (!state.selectedSource) {
                let noSourceSelectedNode = this.buildNoSourceSelectedNode();
                this.root_nodes = this.root_nodes.concat(noSourceSelectedNode);
                return this.reloadNode(null);
            }

            let pagingError = this.pageControls.pagingError();

            if (pagingError) {
                let issueLoadingErrorNode = this.buildPagingErrorNode(pagingError);
                this.root_nodes = this.root_nodes.concat(issueLoadingErrorNode);
                return this.reloadNode(null);
            }

            if (state.issuesList.length === 0) {
                let emptyIssuesNode = this.buildEmptyIssuesNode();
                this.root_nodes = this.root_nodes.concat(emptyIssuesNode);
                return this.reloadNode(null);
            }

            // show issues
            separator.setIssueListIdFor(IssuesListIdentifier.TeamViewIssuesList);
            this.issuesShown = true;
            state.issuesList.forEach(issue => {
                this.root_nodes.push(new IssueNode(IssuesListIdentifier.TeamViewIssuesList, issue, undefined, undefined, false));
            });
            if (state.viewMoreIssues) {
                this.root_nodes.push(
                    new ButtonNode(localize('team.view.issues.children.load.view.more.label', 'Back to Issues'),
                                            COMMAND_TEAM_VIEW_RESTORE_FULL_LIST, {themeIconId: ThemeIconId.arrowCircleLeft}));
            } else if (this.pageControls.hasMorePages()) {
                const pagerNode: PagerNode = new PagerNode(() => this.reloadNode(pagerNode), this.pageControls.loadNext);
                this.root_nodes.push(pagerNode);
            }
            await this.reloadNode(null);
        } catch(e) {
            getLogger().info('Unexpected error occurred while reloading Team view\nException: ', e);
        } finally {
            this.viewLock.release();   
        } 
    }

    private buildEmptyIssuesNode(): TreeNodeProvider[] {
        let emptyIssuesNode: TreeNodeProvider[] = [];
        const message = localize('team.view.empty.issues.node.text', 'No Results Found');
        emptyIssuesNode.push(new StatusNode(Status.Info, message));

        const serverType = getService(IssueSourceConfigService.id).getSelectedSource()?.serverType;
        if (serverType === undefined || (serverType !== undefined && !isTeamViewFilteringSupported(serverType))) {
            return emptyIssuesNode;
        }

        const filterMessage = localize('team.view.empty.issues.node.desc', 'Try updating your filter settings or refreshing the list');
        emptyIssuesNode.push(new DescriptionNode(filterMessage));
        emptyIssuesNode.push(new ButtonNode(localize('team.view.empty.issues.node.button.text', 'Filter Settings'), COMMAND_OPEN_TEAM_VIEW_FILTER_VIEW__FILTERS_APPLIED));
        return emptyIssuesNode;
    }

    private buildNoSourceSelectedNode(): TreeNodeProvider[] {
        let emptyIssuesNode: TreeNodeProvider[] = [];
        const message = localize('team.view.no.source.node.text', 'Configure a source to view results');
        const notConfiguredText = localize('team.view..issue.presenter.not.configured.text', 'Click to configure');


        emptyIssuesNode.push(new StatusNode(Status.Info, message));
        emptyIssuesNode.push(new ButtonNode(notConfiguredText, COMMAND_OPEN_TEAM_VIEW_ISSUE_SOURCE_VIEW));
        return emptyIssuesNode;
    }

    private buildNoServerErrorNode(): TreeNodeProvider[] {
        let errorNode: TreeNodeProvider[] = [];

        const errorMessage = localize('team.view.noserver.error.node.text', 'Team view disabled');
        const errorDesc = localize('team.view.noserver.error.node.desc', 'Please authenticate to a server to view results');
        const buttonText = localize('team.view.connect.server.button.node.text', 'Add Server');
        
        errorNode.push(new StatusNode(Status.Error, errorMessage));
        errorNode.push(new DescriptionNode(errorDesc));
        errorNode.push(new ButtonNode(buttonText, COMMAND_SHOW_ISSUE_SOURCE_SERVER_CONFIG, { themeIconId: ThemeIconId.add }));
        
        return errorNode;
    }
    
    private buildPagingErrorNode(error: Error): TreeNodeProvider[] {
        let errorNode: TreeNodeProvider[] = [];
        
        const errorMessage = localize('team.view.load.error.node.text', 'Failed to load data');
        const errorDesc = localize('team.view.load.error.node.desc', 'Click the refresh button to retry');

        errorNode.push(new StatusNode(Status.Error, errorMessage, COMMAND_SHOW_REMOTE_ISSUE_LIST_ERROR, error));
        errorNode.push(new DescriptionNode(errorDesc));
        errorNode.push(new ButtonNode(localize('team.view.issues.children.load.view.refresh.label', 'Refresh results'), REFRESH_REMOTE_ISSUES, { themeIconId: ThemeIconId.refresh }));
        errorNode.push(new ButtonNode(localize('team.view.issues.children.load.view.error.label', 'View Error'), COMMAND_SHOW_REMOTE_ISSUE_LIST_ERROR, {commandArgs: [error], themeIconId: ThemeIconId.goToFile }));

        return errorNode;
    }
}

export interface TeamViewIssueFoundTreeState {
    issuesList: NewIssue[];
    availableServers: ServerInfo[];
    sourceList: RemoteIssueSource[];
    selectedSource: RemoteIssueSource | undefined;
    viewMoreIssues?: boolean;
    loading?: boolean;
}