import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { AuthModel } from "../../models/authModel";
import { ServiceId } from "../../services/serviceContainer";
import { ENV_CODESIGHT_DEFAULT_POLARIS_URL } from "../../utils/constants";
import { getEnvVar } from "../../utils/environmentUtils";
import { getServerName } from "../../utils/typeUtils";
import { SingleStepAuthViewProviderBase, SingleStepAuthViewProviderBaseImpl } from "./singleStepAuthViewProviderBase";

const localize: LocalizeFunc = loadMessageBundle();

export abstract class PolarisSingleStepAuthViewProvider extends SingleStepAuthViewProviderBase {
    static readonly id: ServiceId<PolarisSingleStepAuthViewProvider> = { id: PolarisSingleStepAuthViewProvider.name };
}

export class PolarisSingleStepAuthViewProviderImpl extends SingleStepAuthViewProviderBaseImpl implements PolarisSingleStepAuthViewProvider {
    defaultUrl = getEnvVar(ENV_CODESIGHT_DEFAULT_POLARIS_URL) ?? "https://polaris.blackduck.com";

    protected urlRowForServer(model: AuthModel) {
        let url = model.getUrl();
        let serverName = getServerName(model.getServerType());
        
        return /*html*/`
            <input style="grid-column: col / span 2; grid-row: row 2;" id="url" type="url" ${!url || url === this.defaultUrl ? "disabled" : ""} value="${url ? url : this.defaultUrl}" name="url"/>
            <div style="grid-column: col 3; grid-row: row 2;" class="vertical">
            </div>
            <div style="grid-column: col 4; grid-row: row 2;">
                <input id="defaultServerUrl" type="checkbox" ${!url || url === this.defaultUrl ? "checked" : ""} onchange="handleCheckboxChange(this);"/>
            </div>
            <div style="grid-column: col 5; grid-row: row 2;">
                ${localize('auth.single.step.defaulturl.label', 'Use default {0} URL', serverName)}
            </div>`;
    }

    protected tokenDescForServer(): string {
        return `${localize('auth.token.polaris.generate.desc', 'To generate a token, open Polaris in a web browser: User Profile > Account > Access Tokens > Create Token. Name your token, copy and paste it into the token credential field.')}`;
    }

 }