import { ServiceId } from "./serviceContainer";

export abstract class ProxyEventListener {
    abstract onProxyInformationUpdated(): void;
}

export abstract class ProxyEventService {
    static readonly id: ServiceId<ProxyEventService> = { id: ProxyEventService.name };

    abstract emitChanges(): void;

    abstract addListener(listener: ProxyEventListener): void;

    abstract removeListener(listener: ProxyEventListener): void;
}

export class ProxyEventServiceImpl extends ProxyEventService {
    private listeners: ProxyEventListener[] = [];

    emitChanges(): void {
        this.listeners.forEach((listener) => {
            listener.onProxyInformationUpdated();
        });
    }

    addListener(listener: ProxyEventListener): void {
        this.listeners.push(listener);
    }

    removeListener(listener: ProxyEventListener): void {
        let index = this.listeners.indexOf(listener);
        if (index >= 0) {
            this.listeners.splice(index, 1);
        }
    }
}