import { RefreshStatus } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_service_pb";
import { LicensedToolsConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/licensed_tools_config_pb";
import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { ScanConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/scan_config_pb";
import { SetupToolRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/tool_service_pb";
import { commands, Disposable, env, Uri, ViewColumn, WebviewPanel, window, workspace } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { AnalysisContextService } from "../../services/analysisContextService";
import { CsBrowserService } from "../../services/browserService";
import { InfoMessageService, WarningMessageService } from "../../services/extensionMessageService";
import { ScanStatusCoordinator, ScanStatusCoordinatorListener } from "../../services/scanStatusCoordinator";
import { getService } from "../../services/serviceContainer";
import { SetupService } from "../../services/setupService";
import { ToolStateService, ToolTypeEnum } from "../../services/toolStateService";
import { SUPPORT_ADDRESS } from "../../utils/constants";
import { getLogger } from "../../utils/logger";
import { COMMUNITY_PORTAL_REMEDIATION_ID, CONTACT_SUPPORT_REMEDIATION_ID, DO_INSTALL_REMEDIATION_ID, DO_UPDATE_REMEDIATION_ID, getAssociatedFilePath, getProjectCoverityConfLocation, getToolType, getUserCoverityConfLocation, isBlackduckMessage, isCoverityMessage, isSigmaMessage, OPEN_DETECT_CONFIG_REMEDIATION_ID, OPEN_PROJECT_COVERITY_CONF_REMEDIATION_ID, OPEN_USER_COVERITY_CONF_REMEDIATION_ID, REAUTHENTICATE_BLACK_DUCK_REMEDIATION_ID, RETRY_DOWNLOAD_REMEDIATION_ID, SKIP_DOWNLOAD_REMEDIATION_ID, USE_LOCAL_BINARY_REMEDIATION_ID } from "../../utils/notificationMessageUtils";
import { EXPORT_LOGS_BUTTON_ID, handleExportLogsButtonClicked, handleOpenLogsFolderClicked, OPEN_LOGS_FOLDER_BUTTON_ID } from "../../views/exportLogs/exportLogsViewComponent";
import { WebviewCoordinator } from "../../views/webviewCoordinator";
import { WebviewPresenter } from "../webviewPresenter";
import { LocalViewScanDetailsProvider } from "./localViewScanDetailsProvider";
import { NotificationViewProvider } from "./notificationViewProvider";
import { NotificationViewCommandIds, NotificationViewProviderBase } from "./notificationViewProviderBase";

const localize: LocalizeFunc = loadMessageBundle();

export class NotificationViewPresenter implements WebviewPresenter, ScanStatusCoordinatorListener {
    private readonly panel: WebviewPanel;
    private view: NotificationViewProviderBase;
    private userConfigLocation: string;
    private projectConfigLocation: string;
    private modelMessage?: NotificationMessage;
    private onMessageFromWebviewDisposable: Disposable | undefined;
    private isLocalView: boolean | undefined;

    private scanDetailsViewType?: LicensedToolsConfig.ToolDomainType;

    constructor(panel: WebviewPanel, scanDetailsViewType?: LicensedToolsConfig.ToolDomainType, isLocalView?: boolean) {
        this.panel = panel;
        this.userConfigLocation = "";
        this.projectConfigLocation = "";
        this.scanDetailsViewType = scanDetailsViewType;
        this.isLocalView = isLocalView;
        getService(ScanStatusCoordinator.id).addListener(this);

        if (isLocalView) {
            this.view = getService(LocalViewScanDetailsProvider.id);
        } else {
            this.view = getService(NotificationViewProvider.id);
        }
        
        this.view.initView(this.panel);
    }

    public async loadContent(message?: NotificationMessage) {
        if (message === undefined) {
            // load just the scan details
            return this.view.reloadHtml();
        }

        // load message content
        let userConfigLocation = getUserCoverityConfLocation(message);
        let projectConfigLocation = getProjectCoverityConfLocation(message);
        this.modelMessage = message;
        if (userConfigLocation !== "") {
            this.userConfigLocation = userConfigLocation;
        }
        if (projectConfigLocation !== "") {
            this.projectConfigLocation = projectConfigLocation;
        }

        await this.view.reloadHtml(message);
    }

    public async parseNotification(message: NotificationMessage) {
        // no-op
        // use loadContent() instead
    }

    async onScanResultReceived(notificationStatus: RefreshStatus): Promise<void> {
        try {
            const domain = notificationStatus.getDomain();
            if (domain !== this.scanDetailsViewType && !this.isLocalView) {
                return;
            }

            await this.view.reloadHtml(this.modelMessage);
        } catch (e) {
            getLogger().error(`Error reloading notification view on scan result: ${e}`);
        }
    }

    public async initView() {
        const logger = getLogger();
        this.onMessageFromWebviewDisposable = this.view.onMessageFromWebview(async message => {
            let setupRequest = new SetupToolRequest();
            let analysisContextService = getService(AnalysisContextService.id);

            setupRequest.setContextid(analysisContextService.getAnalysisContextId());
            setupRequest.setProjectrootpath(analysisContextService.getContextRoot());

            switch (message.command) {
                case DO_UPDATE_REMEDIATION_ID:
                    {
                        if (this.modelMessage && isSigmaMessage(this.modelMessage)) {
                            // eslint-disable-next-line @typescript-eslint/no-floating-promises
                            getService(SetupService.id).installOrUpdateTool(ToolTypeEnum.Sigma, true);
                        } else if (this.modelMessage && isBlackduckMessage(this.modelMessage)) {
                            // eslint-disable-next-line @typescript-eslint/no-floating-promises
                            getService(SetupService.id).installOrUpdateTool(ToolTypeEnum.Blackduck, true);
                        } else if (this.modelMessage && isCoverityMessage(this.modelMessage)) {
                            // eslint-disable-next-line @typescript-eslint/no-floating-promises
                            getService(SetupService.id).installOrUpdateTool(ToolTypeEnum.Coverity, true);
                        }
                    }
                    break;
                case DO_INSTALL_REMEDIATION_ID:
                // fallthrough
                case RETRY_DOWNLOAD_REMEDIATION_ID:
                    {
                        getService(SetupService.id).retryDownloadClicked();

                        // Update if we have tools, setup if we do not
                        if (this.modelMessage && isSigmaMessage(this.modelMessage)) {
                            let shouldUpdate = getService(ToolStateService.id).isSigmaInstalled();
                            await getService(SetupService.id).installOrUpdateTool(ToolTypeEnum.Sigma, shouldUpdate);
                        } else if (this.modelMessage && isBlackduckMessage(this.modelMessage)) {
                            let shouldUpdate = getService(ToolStateService.id).isBlackduckInstalled();
                            await getService(SetupService.id).installOrUpdateTool(ToolTypeEnum.Blackduck, shouldUpdate);
                        } else if (this.modelMessage && isCoverityMessage(this.modelMessage)) {
                            let shouldUpdate = getService(ToolStateService.id).isCoverityInstalled();
                            await getService(SetupService.id).installOrUpdateTool(ToolTypeEnum.Coverity, shouldUpdate);
                        }
                    }
                    break;
                case SKIP_DOWNLOAD_REMEDIATION_ID:
                    {
                        await getService(SetupService.id).skipDownloadClicked();
                    }
                    break;
                case OPEN_PROJECT_COVERITY_CONF_REMEDIATION_ID:
                    try {
                        let doc = await workspace.openTextDocument(this.projectConfigLocation);
                        await window.showTextDocument(doc, ViewColumn.One);
                    } catch (error) {
                        logger.warn(`Could not open file ${this.projectConfigLocation}, error: ${error}`);
                    }
                    break;
                case OPEN_USER_COVERITY_CONF_REMEDIATION_ID:
                    try {
                        let doc = await workspace.openTextDocument(this.userConfigLocation);
                        await window.showTextDocument(doc, ViewColumn.One);
                    } catch (error) {
                        logger.warn(`Could not open file ${this.userConfigLocation}, error: ${error}`);
                    }
                    break;
                case CONTACT_SUPPORT_REMEDIATION_ID:
                    await getService(CsBrowserService.id).openLink(SUPPORT_ADDRESS);
                    break;
                case OPEN_DETECT_CONFIG_REMEDIATION_ID:
                    await getService(WebviewCoordinator.id).showDetectConfigView();
                    break;
                case EXPORT_LOGS_BUTTON_ID:
                    await handleExportLogsButtonClicked(this.view, this.modelMessage ? getAssociatedFilePath(this.modelMessage) : "");
                    break;
                case OPEN_LOGS_FOLDER_BUTTON_ID:
                    await handleOpenLogsFolderClicked(this.view);
                    break;
                case NotificationViewCommandIds.OPEN_SCAN_LOG_FOLDER:
                    await this.openScanLogFolder(message.logPath);
                    break;
                case NotificationViewCommandIds.OPEN_SCAN_LOG_FILE:
                    await this.openScanLogFile(message.logPath);
                    break;
                case NotificationViewCommandIds.COPY_TO_CLIPBOARD:
                    env.clipboard.writeText(message.logPath).then((value) => {
                        let successMessage = localize('info.message.text.copy.to.clipboard.success', "Scan log path copied to clipboard!");
                        // eslint-disable-next-line @typescript-eslint/no-floating-promises
                        getService(InfoMessageService.id).copyToClipboardSuccess(successMessage);
                      },
                      (reason) => {
                        // eslint-disable-next-line @typescript-eslint/no-floating-promises
                        getService(WarningMessageService.id).copyToClipboardFailed();
                      });
                    break;
                case COMMUNITY_PORTAL_REMEDIATION_ID:
                    await getService(CsBrowserService.id).openLink(SUPPORT_ADDRESS);
                    break;
                case USE_LOCAL_BINARY_REMEDIATION_ID:
                    if(this.modelMessage) {
                        await getService(SetupService.id).useLocalBinaryClicked(getToolType(this.modelMessage));
                    }
                    break;
                case REAUTHENTICATE_BLACK_DUCK_REMEDIATION_ID:
                    await getService(WebviewCoordinator.id).showEditBlackDuckServerConfiguration(true);
                    break;
                default:
                    logger.error("Error responding to view message. No handler for command " + message.command);
            }

        });
    }

    async openScanLogFolder(logPath: string) {
        if (logPath) {
            await commands.executeCommand("revealFileInOS", Uri.file(logPath));
        }
    }

    async openScanLogFile(logPath: string) {
        if (logPath) {
            try {
                const document = await workspace.openTextDocument(Uri.file(logPath));
                await window.showTextDocument(document, {
                    viewColumn: ViewColumn.One,
                    preview: true,
                    preserveFocus: false
                });
            } catch (error) {
                getLogger().warn(`Could not open scan log file ${logPath}, error: ${error}`);
            }
        }
    }

    public dispose() {
        getService(ScanStatusCoordinator.id).removeListener(this);
        this.onMessageFromWebviewDisposable?.dispose();
    }
}