import { RefreshResultsRequest, RefreshStatus } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_service_pb";
import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { ScanConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/scan_config_pb";
import { ServerType } from "@codesight/codesight-controller-proto/controller_proto/v0/server_info_pb";
import { Filter, FilterValue, Modifier, NamedFilter, SelectionState } from "@codesight/codesight-controller-proto/controller_proto/v1/issues_service_pb";
import { FilterViewType } from "@webview-model/models/components/FilterViewModel";
import { Disposable, WebviewPanel } from "vscode";
import { LocalViewIssueListFilterService } from "../../services/filterService";
import { LocalViewIssuesListService, ScanResultTypeSelectionListener } from "../../services/issuesService";
import { ScanConfigurationService, ScanConfigurationServiceListener } from "../../services/scanConfigurationService";
import { ScanMode, ScanStatusCoordinator } from "../../services/scanStatusCoordinator";
import { getService } from "../../services/serviceContainer";
import { UserService } from "../../services/userService";
import { getScanStatus } from "../../utils/fileScanInfoUtils";
import { getLogger } from "../../utils/logger";
import { isLocalViewFilteringSupported, isLocalViewOwnerFilteringSupported } from "../../utils/typeUtils";
import { addDelay } from "../../utils/webviewUtils";
import { WebviewPresenter } from "../webviewPresenter";
import { LocalViewFilterViewProvider } from "./localViewFilterViewProvider";
const COMPONENT_NAME = "Filter";


export class LocalViewFilterViewPresenter implements WebviewPresenter, ScanResultTypeSelectionListener, ScanConfigurationServiceListener {
    private readonly panel: WebviewPanel;
    private view: LocalViewFilterViewProvider;
    private onMessageFromWebviewDisposable: Disposable | undefined;
    private viewType: FilterViewType | undefined;
    private scanType: ScanConfig.ScanType.Type | undefined;
    private filterList: NamedFilter | undefined;
    private serverType: ServerType | undefined;
    private isAutoMode: boolean;

    constructor(panel: WebviewPanel) {
        this.panel = panel;
        this.view = getService(LocalViewFilterViewProvider.id);
        this.view.initView(this.panel);
        this.viewType = FilterViewType.LOCAL_VIEW;
        this.isAutoMode = false;
        getService(LocalViewIssuesListService.id).addScanResultTypeListener(this);
        getService(ScanConfigurationService.id).addListener(this);
    }

    public async parseNotification(message: NotificationMessage) {
    }

    public async initView() {
        this.view.initLoading();
        this.isAutoMode = getService(ScanStatusCoordinator.id).getCurrentScanMode() === ScanMode.Auto;
        let selectedScanType = await getService(LocalViewIssuesListService.id).getSelectedResultScanType(ScanMode.Manual);
        if (!selectedScanType) {
            getLogger().warn("Filter view initialized without a selected source or scan type");
            return;
        }
        
        let errorMessage = "";
        let currentUserOptions:{ value: string, label: string}[] = [];
        if (isLocalViewFilteringSupported(selectedScanType.getType(), this.isAutoMode)) {
            const response = await getService(LocalViewIssueListFilterService.id).getIssueFiltersAsync();
            if (response.getError() !== undefined) {
                errorMessage = `${response.getError()?.getCode()} ${response.getError()?.getMessage()}`;
            }
            this.filterList = response.getFiltersList()[0];
            this.serverType = response.getServertype();
        }

        if (isLocalViewOwnerFilteringSupported(selectedScanType.getType())) {
            const currentUserResponse = await getService(UserService.id).getCurrentUser(this.serverType);
            if (currentUserResponse.getError() !== undefined) {
                errorMessage = `${currentUserResponse.getError()?.getCode()} ${currentUserResponse.getError()?.getMessage()}`;
            }

            const currentUser = currentUserResponse.getCurrentuserinfo();
            if (currentUser !== undefined) {
                currentUserOptions = [{ value: currentUser.getId(), label: currentUser.getDisplayname()}];
            }
        }

        this.onMessageFromWebviewDisposable = this.view.onObjectMessageFromWebview(async message => {
            switch (message.command) {
                case 'init':
                    if (errorMessage === "") {
                        let scanType = await getService(LocalViewIssuesListService.id).getSelectedResultScanType(ScanMode.Manual);
                        this.scanType = scanType?.getType();
                        // eslint-disable-next-line @typescript-eslint/no-floating-promises
                        this.view.postObjectMessageToWebview({
                            command: 'loadComponent',
                            component: COMPONENT_NAME,
                            props: {
                                scanType: this.scanType,
                                isAutoScanMode: this.isAutoMode,
                                namedFilter: this.filterList?.toObject(),
                                currentUser: currentUserOptions,
                                errorMessage: errorMessage,
                                viewType: this.viewType,
                            }
                        });
                    } else {
                        // eslint-disable-next-line @typescript-eslint/no-floating-promises
                        this.view.postObjectMessageToWebview({
                            command: 'loadComponent',
                            component: "Error",
                            props: {
                                title: "Local View Filters",
                                errorDetails: "Code Sight was unable to load the data from the server. Please check the server connection and try again. If the problem persists, collect the export logs and contact support.",
                                errorMessage: errorMessage,
                                viewType: this.viewType,
                            }
                        });
                    }
                    break;
                case 'apply':
                    // eslint-disable-next-line @typescript-eslint/no-floating-promises
                    this.onApplyButtonClicked(message);
                    break;
                case "userSearch": {
                    let userSearchError = "";
                    const response = await getService(UserService.id).getUsers(message.searchValue, this.serverType);
                    if (response.getError() !== undefined) {
                        userSearchError = `${response.getError()?.getCode()} ${response.getError()?.getMessage()}`;
                    }
                    const userInfos = response.getUsersList();
                    const options = userInfos.map(userInfo => {
                        return {value: userInfo.getId(), label: userInfo.getDisplayname()};
                    });

                    await this.view.postObjectMessageToWebview({
                        command: 'userSearchResults',
                        options: options,
                        searchError: userSearchError,
                        viewType: this.viewType,
                    });
                    break;
                }
            }
        });

        this.view.initHtml();
    }

    setCheckedState(filter: FilterValue[], id: string, checked: boolean) {
        filter.forEach(filterValue => {
            if (id === `${filterValue.getId()}-${filterValue.getValue()}`) {
                filterValue.setState(checked ? SelectionState.SELECTED : SelectionState.UNSELECTED);
                return;
            }

            if (filterValue.getChildrenList().length > 0) {
                this.setCheckedState(filterValue.getChildrenList(), id, checked);
            }
        });
    }

    setSelectionState(filter: FilterValue[], id: string, state: SelectionState){
        filter.forEach(filterValue => {
            if (id === `${filterValue.getId()}-${filterValue.getValue()}`) {
                filterValue.setState(state);
                return;
            }
        })
    }

    setModifierState(modifiers: Modifier[], id: string, state: SelectionState) {
        modifiers.forEach(modifier => {
            if (id === `${modifier.getId()}-${modifier.getDisplayname()}`) {
                modifier.setState(state);
                return;
            }
        });
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    async onApplyButtonClicked(message: { 
        command: string, 
        multiSelected: { checked: boolean, id: string }[], 
        user: any, 
        textSearchValues: { id: string, value: string }[],
        multiSelectedSearch: { state: SelectionState, id: string, value: string }[]
        modifiers: { state: SelectionState, id: string, value: string }[]  
    }): Promise<void> {
        const logger = getLogger();
        let { selectedScanInfo } = await getService(LocalViewIssuesListService.id).getAvailableScanInfos();
        const lastScanStatus = getScanStatus(selectedScanInfo);
        // handle the case where the last scan in Local View was Cancelled or Failed
        if (lastScanStatus === RefreshStatus.Status.CANCELLED || lastScanStatus === RefreshStatus.Status.FAILED) {
            logger.warn("onApplyButtonClicked: Cancelled or failed scan detected, not applying filters");
            // eslint-disable-next-line @typescript-eslint/no-floating-promises
            this.view.postObjectMessageToWebview({
                command: "updateStatus",
                message: "Problem occurred while applying filters. Please ensure the scan is successful before applying filters.",
                state: "error",
                viewType: this.viewType,
            });
            return;
        }
        if (!this.filterList) {
            logger.warn("onApplyButtonClicked: Filter list is empty");
            // eslint-disable-next-line @typescript-eslint/no-floating-promises
            this.view.postObjectMessageToWebview({
                command: "updateStatus",
                message: "Problem occurred while applying filters. Please contact support if the problem persists.",
                state: "error",
                viewType: this.viewType,
            });
            return;
        }

        // set selections
        this.filterList.getFiltersList().forEach(filter => {
            switch(filter.getFilterkind()) {
                case Filter.FilterKind.TEXT:
                    message.textSearchValues.forEach(textValue => {
                        if (filter.getId() === textValue.id) {
                            if (textValue.value === "") {
                                filter.clearFiltervalueList();
                            } else {
                                let filterValue;
                                if (filter.getFiltervalueList().length > 0) {
                                    filterValue = filter.getFiltervalueList()[0];
                                } else {
                                    filterValue = new FilterValue();
                                    filter.addFiltervalue(filterValue);
                                }
                                filterValue.setDisplayvalue(textValue.value);
                                filterValue.setValue(textValue.value);
                                filterValue.setId(filter.getId());
                            }
                        }
                    });
                    break;
                case Filter.FilterKind.MULTISELECT:
                    message.multiSelected.forEach(item => {
                        this.setCheckedState(filter.getFiltervalueList(), item.id, item.checked);
                    });
                    break;
                case Filter.FilterKind.USER:
                    if (message.user === null) {
                        filter.clearFiltervalueList();
                    } else {
                        let filterValue;
                        if (filter.getFiltervalueList().length > 0) {
                            filterValue = filter.getFiltervalueList()[0];
                        } else {
                            filterValue = new FilterValue();
                            filter.addFiltervalue(filterValue);
                        }
                        filterValue.setDisplayvalue(message.user.label);
                        filterValue.setValue(message.user.value);
                        filterValue.setId(filter.getId());
                    }
                    break;
                case Filter.FilterKind.MULTISELECTWITHSEARCH:
                    if (message.multiSelectedSearch.length > 0) {
                        message.multiSelectedSearch.forEach(value => {
                            let id = `${value.id}-${value.value}`;
                           this.setSelectionState(filter.getFiltervalueList(), id, value.state);
                        });
                    }
                    if (message.modifiers.length > 0) {
                        message.modifiers.forEach(value => {
                            let id = `${value.id}-${value.value}`;
                            this.setModifierState(filter.getModifierList(), id, value.state);
                        });
                    }
                    break;
                default:
                    logger.warn("unsupported filter kind found");
            }
        });

        // store filters for Local View
        const selectedScanType = await getService(LocalViewIssuesListService.id).getSelectedResultScanType(ScanMode.Manual);
        let response = await getService(LocalViewIssueListFilterService.id).storeIssueFilters([this.filterList], selectedScanType);
        if (response.getError() !== undefined) {
            let errorMessage = `${response.getError()?.getCode()} ${response.getError()?.getMessage()}`;
            // eslint-disable-next-line @typescript-eslint/no-floating-promises
            this.view.postObjectMessageToWebview({
                command: 'updateStatus',
                message: errorMessage,
                state: "error",
                viewType: this.viewType,
            });
            return;
        }

        // show success message and reload filters
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        this.view.postObjectMessageToWebview({
            command: 'updateStatus',
            message: "Filters have been successfully applied",
            state: "success",
            viewType: this.viewType,
        });
        await addDelay(1000);
        await this.reloadComponent();
    }

    private async reloadComponent() {
        const scanType = await getService(LocalViewIssuesListService.id).getSelectedResultScanType(ScanMode.Manual);
        const response = await getService(LocalViewIssueListFilterService.id).getIssueFiltersAsync();
        let errorMessage = "";
        if (response.getError() !== undefined) {
            errorMessage = `${response.getError()?.getCode()} ${response.getError()?.getMessage()}`;
            // eslint-disable-next-line @typescript-eslint/no-floating-promises
            this.view.postObjectMessageToWebview({
                command: 'reloadComponent',
                scanType: scanType?.getType(),
                isAutoScanMode: this.isAutoMode,
                viewType: this.viewType,
            });
            // eslint-disable-next-line @typescript-eslint/no-floating-promises
            this.view.postObjectMessageToWebview({
                command: 'updateStatus',
                message: errorMessage,
                state: "error",
                viewType: this.viewType,
            });
            return;
        }

        // reload with new data
        this.filterList = response.getFiltersList()[0];
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        this.view.postObjectMessageToWebview({
            command: 'reloadComponent',
            scanType: scanType?.getType(),
            isAutoScanMode: this.isAutoMode,
            namedFilter: this.filterList.toObject(),
            viewType: this.viewType,
        });
    }

    async onResultTypeChanged(): Promise<void> {
        // This method is called when the result type changes in local view
        await this.initView();
    }

    async onScanModeChanged(scanMode: ScanMode): Promise<void> {
        await this.initView();
    }

    async onScanFileScopeChanged(scanFileScope: RefreshResultsRequest.Tier): Promise<void> {
        // no-op
    }

    async onSelectedReferenceBranchChanged(): Promise<void> {
        //no-op
    }

    onSelectedScanConfigChanged(): Promise<void> {
        return Promise.resolve();
    }

    public dispose() {
        this.onMessageFromWebviewDisposable?.dispose();
        getService(LocalViewIssuesListService.id).removeScanResultTypeListener(this);
    }
}