export interface PanelPresenterContainer {
    panel: WebviewPanel;
    presenter: WebviewPresenter|undefined;
}

export class WebviewMap {
    webviewMap: Map<PanelType, PanelPresenterContainer | undefined>;

    constructor() {
        this.webviewMap = new Map<PanelType, PanelPresenterContainer | undefined>();
    }

    set(panelType: PanelType, container?: PanelPresenterContainer) {
        // Dispose of previous presenter so its listeners don't linger
        let oldContainer = this.webviewMap.get(panelType);
        if (oldContainer && oldContainer.presenter !== container?.presenter) {
            oldContainer.presenter?.dispose();
        }

        this.webviewMap.set(panelType, container);
    }

    get(panelType: PanelType): PanelPresenterContainer | undefined {
        return this.webviewMap.get(panelType);
    }

}

