    async showNotification(message: NotificationMessage): Promise<WebviewPresenter> {
        this.lastOpenedNotification = message;

        if (isScanningToolAvailableMessage(message)) {
            return this.showDefaultNotification(message);
        } else if (isSetupMessage(message) && isDownloadRelatedSetupMessage(message)) {
            return this.showDownloadNotification(message);
        } else if (isCoverityAuthMessage(message)) {
            return this.showEditCoverityServerConfiguration(true);
        } else if (isBlackduckAuthMessage(message)) {
            return this.showEditBlackDuckServerConfiguration();
        } else if (isWelcomeMessage(message)) {
            return this.showWelcomeMessage();
        } else if (isInstalledToolsMessage(message)) {
            return this.showInstalledToolsMessage();
        }

        return this.showDefaultNotification(message);
    }

