    async showScanConfig(scanMode: ScanMode): Promise<WebviewPresenter | undefined> {
        let isAutoScan = scanMode === ScanMode.Auto;
        let panelType = isAutoScan ? PanelType.AutoScanConfig : PanelType.ScanConfig;
        let container = this.webviewMap.get(panelType);

        let webview;

        if (!container) {
            webview = this.createScanConfigPanel(isAutoScan);
        } else {
            webview = container.panel;
        }

        let currentPresenter = isAutoScan ? new AutoScanConfigViewPresenter(webview) : new ScanConfigViewPresenter(webview);


        this.webviewMap.set(panelType, {
            panel: webview,
            presenter: currentPresenter,
        });

        await currentPresenter.initView();

        webview?.reveal(ViewColumn.Beside, true);

        return currentPresenter;
    }

