    // Cannot reliably open webviews in tests
    protected createPanel(viewType: string, title: string, webviewType: PanelType, viewColumn?: ViewColumn): WebviewPanel {
        const panel = window.createWebviewPanel(
            viewType,
            title,
            {
                viewColumn: viewColumn || ViewColumn.One,
                preserveFocus: true // Do not steal focus from active pane
            }, {
            retainContextWhenHidden: true
        }
        );

        return this.setupPanel(panel, webviewType);
    }

    private setupPanel(panel: WebviewPanel, webviewType: PanelType): WebviewPanel {
        let extensionPath = getService(VscodeContextService.id).getExtensionPath();
        let nodeModules = join(extensionPath, 'node_modules');
        let resourceDir = join(extensionPath, 'resources');
        let webviewUi = join(extensionPath, 'dist');

        panel.webview.options = {
            // Enable javascript in the webview
            enableScripts: true,

            // And restrict the webview to only loading content from the resource directory
            localResourceRoots: [Uri.file(resourceDir), Uri.file(nodeModules), Uri.file(webviewUi)]
        };

        // Set dummy html with a content security policy to avoid warnings from VSCode
        panel.webview.html = '<html><head><meta http-equiv="Content-Security-Policy" content="default-src "none"/></head></html>';
        panel.iconPath = {
            light: getService(VscodeContextService.id).getIconPathUri("blackduck-logo-light.svg", "general"),
            dark: getService(VscodeContextService.id).getIconPathUri("blackduck-logo-dark.svg", "general"),
        };

        let disposables: Disposable[] = [];
        // Clear the webview set in the map on dispose
        panel.onDidDispose(() => {
            this.webviewMap.set(webviewType, undefined);
            panel.dispose();

            while (disposables.length) {
                const x = disposables.pop();
                if (x) {
                    x.dispose();
                }
            }
        }, null, disposables);

        return panel;
    }

    /**
     * This method is called when the user chooses to close the authentication view
     */
    private closeAuthPanel(): void {
        let setupContainer = this.webviewMap.get(PanelType.Notifications);

        // Panels are not actually created in tests
        if (setupContainer) {
            let presenter = setupContainer.presenter;
            if (presenter instanceof AuthenticationViewPresenter) {
                if (setupContainer.panel) {
                    setupContainer.panel.dispose();
                }
                this.webviewMap.set(PanelType.Notifications, undefined);
            }
        }
    }
