import { RefreshResultsRequest, RefreshStatus } from '@codesight/codesight-controller-proto/controller_proto/v0/analysis_service_pb';
import { ConfigId, IssueSource, RemoteReference } from '@codesight/codesight-controller-proto/controller_proto/v0/config_pb';
import { DeleteScanConfigResponse, GetScanTypesResponse, SetSelectedScanConfigResponse } from '@codesight/codesight-controller-proto/controller_proto/v0/configuration_service_pb';
import { ScanConfig } from '@codesight/codesight-controller-proto/controller_proto/v0/scan_config_pb';
import { ConfigSource, GetDiffSourceRequest, IssueDiffValue, StoreDiffSourceRequest } from '@codesight/codesight-controller-proto/controller_proto/v1/issues_service_pb';
import * as vscode from 'vscode';
import { getLogger } from '../utils/logger';
import { convertToConfigSource } from '../utils/protoUtils';
import { getRemoteReferenceDisplayString } from '../utils/typeUtils';
import { AnalysisContextService } from './analysisContextService';
import { ConfigurationService } from './configurationService';
import { ControllerClientService } from './controllerClientService';
import { EntitlementService, EntitlementServiceListener } from './entitlementService';
import { LocalViewIssueListFilterService } from './filterService';
import { LocalViewIssuesListService } from './issuesService';
import { ScanMode, ScanStatusCoordinator, ScanStatusCoordinatorListener } from './scanStatusCoordinator';
import { ServiceId, getService } from "./serviceContainer";

export const SCAN_CONFIG_SELECTED_CONTEXT = "codesight.scanConfigSelected";

export interface ScanConfiguration {
    name: string;
    configId: ConfigId;
    scope: ScanConfig.ScanMode.Mode;
    scanType: ScanConfig.ScanType;
    supportsDiffing: boolean;
    scanConfigRef: ScanConfig;
}

export interface ReferenceBranch {
    name: string;
    diffSourceRef: IssueSource | undefined;
}

/**
 * Defines a service meant for handling scan configuration for Local View
 */
export abstract class ScanConfigurationService {
    static readonly id: ServiceId<ScanConfigurationService> = { id: ScanConfigurationService.name };

    abstract init(): Promise<void>;

    /**
     * Saves the scan config selected from the view
     */
    abstract setSelectedScanConfig(configName: string): Promise<void>;

    /**
     * Returns the scan config selected from the view
    */
   abstract getSelectedScanConfig(): ScanConfiguration | undefined;
   
    /**
     * Deletes the specified scan configuration. If the currently selected scan configuration matches the one being deleted, it also deselects it.
     */
   abstract deleteScanConfiguration(deletedId: ConfigId): Promise<SetSelectedScanConfigResponse | DeleteScanConfigResponse>;
    /**
     * Saves the selected reference branch in Local View
     */
    abstract setSelectedReferenceBranch(referenceBranch: RemoteReference): Promise<void>;

    /**
     * Returns selected reference branch in Local View
     */
    abstract getSelectedReferenceBranch(): ReferenceBranch | undefined;

    /**
     * Refreshes the cached scan type list in scan config dialog
     */
    abstract refreshScanTypeList(): Promise<void>;

    /**
     * Returns the cached scan type response
     */
    abstract getScanTypes(): GetScanTypesResponse | undefined;

    abstract notifyListenersOfScanModeChanged(scanMode: ScanMode): Promise<void>;

    abstract notifyListenersOfScanFileScopeChanged(scanFileScope: RefreshResultsRequest.Tier): Promise<void>;

    abstract addListener(listener: ScanConfigurationServiceListener): void;
    abstract removeListener(listener: ScanConfigurationServiceListener): void;
}

export abstract class ScanConfigurationServiceListener {
    abstract onSelectedScanConfigChanged(): Promise<void>;
    abstract onSelectedReferenceBranchChanged(): Promise<void>;
    abstract onScanModeChanged(scanMode: ScanMode): Promise<void>;
    abstract onScanFileScopeChanged(scanFileScope: RefreshResultsRequest.Tier): Promise<void>;
}

export class ScanConfigurationServiceImpl implements ScanConfigurationService, ScanStatusCoordinatorListener, EntitlementServiceListener {
    protected scanConfigListeners: ScanConfigurationServiceListener[];
    protected selectedScanConfig: ScanConfiguration | undefined;
    protected selectedRemoteReferenceBranch: ReferenceBranch | undefined;
    protected searchFilter: string | undefined;
    protected scanTypeListResponse: GetScanTypesResponse | undefined;

    constructor() {
        this.scanConfigListeners = [];
        getService(ScanStatusCoordinator.id).addListener(this);
        getService(EntitlementService.id).addListener(this);
    }

    dispose(): void {
        getService(ScanStatusCoordinator.id).removeListener(this);
        getService(EntitlementService.id).removeListener(this);
    }

    async init() {
        await this.loadSelectedScanConfig();
        await this.refreshStoredDiffSource();
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        this.refreshScanTypeList();
    }

    async loadSelectedScanConfig() {
        let response = await getService(ConfigurationService.id).getScanConfigurationList();
        if (response.getError()) {
            // TODO: handle response error
            return;
        }
        let selectedConfig = response.getSelected();
        if (selectedConfig) {
            await this.setSelectedScanConfig(selectedConfig, false);
        } else {
            this.selectedScanConfig = undefined;
        }
        
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        this.updateScanConfigSelectedContext();
    }

    async setSelectedScanConfig(configName: string, markAsSelected: boolean = true) {
        const configService = getService(ConfigurationService.id);
        let response = await configService.getScanConfiguration(configName);
        const scanConfig = response.getScanconfig();
        if (!scanConfig) {
            // TODO: handle response error
            return;
        }
        this.selectedScanConfig = {
            name: scanConfig.getConfigid()?.getName()!,
            configId: scanConfig.getConfigid()!,
            scope: scanConfig.getScanmode()?.getMode()!,
            scanType: scanConfig.getScantype()!,
            supportsDiffing: scanConfig.getScantype()?.getSupportsdiffing()!,
            scanConfigRef: scanConfig!,
        };
        if (markAsSelected) {
            let setConfigResponse = await configService.setSelectedScanConfig(this.selectedScanConfig.configId);
            if (setConfigResponse.getError()) {
                // TODO: handle response error
            }
        }
        await this.notifyListenersOfScanConfigSelected();
    }

    getSelectedScanConfig() {
        return this.selectedScanConfig;
    }

    async deleteScanConfiguration(deleted: ConfigId): Promise<SetSelectedScanConfigResponse | DeleteScanConfigResponse> {
        const configService = getService(ConfigurationService.id);
        const response = await configService.deleteScanConfiguration(deleted);

        if (response.hasError()) {
            return response;
        } else if (this.selectedScanConfig?.configId.getId() === deleted.getId()) {
            const unsetResponse = await configService.setSelectedScanConfig(undefined);
            await this.loadSelectedScanConfig();
            await this.notifyListenersOfScanConfigSelected();
            return unsetResponse;
        }

        return response;
    }

    async refreshScanTypeList(): Promise<void> {
        this.scanTypeListResponse = await getService(ConfigurationService.id).getScanTypes();
    }

    getScanTypes(): GetScanTypesResponse | undefined {
        return this.scanTypeListResponse;
    }

    addListener(listener: ScanConfigurationServiceListener): void {
        this.scanConfigListeners.push(listener);
    }

    removeListener(listener: ScanConfigurationServiceListener): void {
        let index = this.scanConfigListeners.indexOf(listener);
        if (index >= 0) {
            this.scanConfigListeners.splice(index, 1);
        }
    }

    private updateScanConfigSelectedContext(): void {
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        vscode.commands.executeCommand("setContext", SCAN_CONFIG_SELECTED_CONTEXT, this.selectedScanConfig !== undefined);
    }

    async setSelectedReferenceBranch(referenceBranch: RemoteReference) {
        const previousRefName = this.selectedRemoteReferenceBranch?.name;
        const selectedResultType = await getService(LocalViewIssuesListService.id).getSelectedResultScanType();
        if (!selectedResultType) {
            // TODO: handle error
            getLogger().warn(`setSelectedReferenceBranch error: Scan type not set for the selected result scan type ${this.selectedScanConfig?.name}`);
            return;
        }

        let request = new StoreDiffSourceRequest();

        let diffSource = new IssueSource();
        diffSource.setReference(referenceBranch);
        request.setDiffsource(diffSource);

        let configSource = new ConfigSource();
        configSource.setScantype(selectedResultType);
        request.setConfigsource(configSource);

        this.selectedRemoteReferenceBranch = {
            name: getRemoteReferenceDisplayString(referenceBranch),
            diffSourceRef: diffSource
        };

        const issuesServiceClient = await getService(ControllerClientService.id).getIssuesServiceClient();
        const contextId = getService(AnalysisContextService.id).getAnalysisContextId();
        request.setContextid(contextId);
        
        request.setConfigsource(convertToConfigSource(ScanMode.Manual, selectedResultType));
        await issuesServiceClient.storeDiffSource(request);

        if (previousRefName !== this.selectedRemoteReferenceBranch?.name) {
            await this.notifyListenersOfReferenceBranchChanged();
        }
    }

    getSelectedReferenceBranch() {
        return this.selectedRemoteReferenceBranch;
    }

    async refreshStoredDiffSource() {
        const selectedScanType = await getService(LocalViewIssuesListService.id).getSelectedResultScanType();
        if (!selectedScanType?.getSupportsdiffing()) {
            return;
        }

        const issuesServiceClient = await getService(ControllerClientService.id).getIssuesServiceClient();
        let request = new GetDiffSourceRequest();
        const contextId = getService(AnalysisContextService.id).getAnalysisContextId();
        request.setContextid(contextId);
        request.setConfigsource(convertToConfigSource(ScanMode.Manual, selectedScanType));

        let response = await issuesServiceClient.getDiffSource(request);
        let diffSource = response.getDiffsource();
        if (!diffSource?.getReference()) {
            this.selectedRemoteReferenceBranch = undefined;
            // reset diff filters
            await getService(LocalViewIssueListFilterService.id).persistDiffSourceFilter(IssueDiffValue.ALL, selectedScanType.getType());
        } else if (diffSource) {
            this.selectedRemoteReferenceBranch = {
                name: getRemoteReferenceDisplayString(diffSource.getReference()),
                diffSourceRef: diffSource
            };
        }
    }

    private async notifyListenersOfScanConfigSelected() {
        let promises: Promise<void>[] = [];
        this.scanConfigListeners.forEach(listener => {
            promises.push(listener.onSelectedScanConfigChanged());
        });

        await Promise.all(promises);   
    }

    public async notifyListenersOfScanModeChanged(scanMode: ScanMode) {
        let promises: Promise<void>[] = [];
        this.scanConfigListeners.forEach(listener => {
            promises.push(listener.onScanModeChanged(scanMode));
        });

        await Promise.all(promises);   
    }

    public async notifyListenersOfScanFileScopeChanged(scanFileScope: RefreshResultsRequest.Tier) {
        let promises: Promise<void>[] = [];
        this.scanConfigListeners.forEach(listener => {
            promises.push(listener.onScanFileScopeChanged(scanFileScope));
        });

        await Promise.all(promises);   
    }

    public async notifyListenersOfReferenceBranchChanged() {
        let promises: Promise<void>[] = [];
        this.scanConfigListeners.forEach(listener => {
            promises.push(listener.onSelectedReferenceBranchChanged());
        });

        await Promise.all(promises);   
    }

    async onScanResultReceived(notificationStatus: RefreshStatus): Promise<void> {
        const scanType = notificationStatus.getScantype();
        if (scanType?.getSupportsdiffing()) {
            return this.refreshStoredDiffSource();
        }
    }

    async onEntitlementsChanged(): Promise<void> {
        await this.refreshScanTypeList();
    }
}