import { RemoteReference } from "@codesight/codesight-controller-proto/controller_proto/v0/config_pb";
import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { ServerType } from "@codesight/codesight-controller-proto/controller_proto/v0/server_info_pb";
import { Disposable, WebviewPanel } from "vscode";
import { LocalizeFunc, loadMessageBundle } from "vscode-nls";
import { AuthenticationService, AuthenticationServiceListener } from "../../services/authenticationService";
import { IssueSourceConfigService, RemoteIssueSource, SourceType } from "../../services/issueSourceConfigService";
import { getService } from "../../services/serviceContainer";
import { TEAM_VIEW_SERVERS } from "../../utils/constants";
import { getLogger } from "../../utils/logger";
import { SourcePicker } from "../../utils/sourcePicker";
import { WebviewCoordinator } from "../webviewCoordinator";
import { WebviewPresenter } from "../webviewPresenter";
import { TeamViewIssueSourceCommandIds, TeamViewIssueSourceViewProvider } from "./teamViewIssueSourceProvider";

const localize: LocalizeFunc = loadMessageBundle();
export class TeamViewIssueSourceViewPresenter implements WebviewPresenter, AuthenticationServiceListener {
    private readonly panel: WebviewPanel;
    private view: TeamViewIssueSourceViewProvider;
    private onMessageFromWebviewDisposable: Disposable | undefined;
    private sourcePicker: SourcePicker = new SourcePicker(localize('team.view.issue.source.view.config.menu.title', 'Result Source'), async (sourceType: SourceType, remoteReference: RemoteReference) => {
        await getService(IssueSourceConfigService.id).configureSource(sourceType.getServerType()!, remoteReference);
        await this.initView();
    });

    constructor(panel: WebviewPanel) {
        this.panel = panel;
        this.view = getService(TeamViewIssueSourceViewProvider.id);
        this.view.initView(this.panel);

        getService(AuthenticationService.id).addListener(this);

        this.onMessageFromWebviewDisposable = this.view.onMessageFromWebview(async message => {
            const logger = getLogger();
            switch (message.command) {
                case TeamViewIssueSourceCommandIds.EDIT_SOURCES:
                    await this.sourcePicker.showConfigurationMenu(new SourceType(+message.serverType));
                    break;
                case TeamViewIssueSourceCommandIds.CONNECT_POLARIS:
                    await getService(WebviewCoordinator.id).showEditPolarisServerConfiguration();
                    break;
                case TeamViewIssueSourceCommandIds.CONNECT_SRM:
                    await getService(WebviewCoordinator.id).showEditSRMServerConfiguration();
                    break;
                case TeamViewIssueSourceCommandIds.CONNECT_COVERITY:
                    await getService(WebviewCoordinator.id).showEditCoverityServerConfiguration();
                    break;
                default:
                    logger.warn(`Received unexpected message ${ message.command }`);
                    break;
            }

            return Promise.resolve();
        });
    }

    public async initView(): Promise<void> {
        this.view.initLoading();
        const authenticationService = getService(AuthenticationService.id);
        let data: IssueSourceTableRow[] = [];
        let serverTypeToSources = new Map<ServerType, RemoteIssueSource[]>();
        TEAM_VIEW_SERVERS.forEach(server => {
            serverTypeToSources.set(server, []);
        });
        let configuredSourceList = await getService(IssueSourceConfigService.id).getConfiguredIssueSourceList(true);
        configuredSourceList.forEach(source => {
            serverTypeToSources.get(source.serverType)?.push(source);
        });

        for (let [serverType, issueSources] of serverTypeToSources) {
            const serverInfo = await authenticationService.fetchServerInfo(serverType);
            if (serverInfo) {
                let serverName = serverInfo.getHumanreadableservername();
                const serverUrl = serverInfo.getUrl();
                if (serverUrl) {
                    serverName += ` (${serverUrl})`;
                }
                data.push({
                    id: serverType,
                    serverName: serverName,
                    sourceReferenceDisplayText: this.joinSourceList(issueSources),
                    configuredSourceList: issueSources
                });
            }
        }

        this.view.initHtml(data);
    }

    private joinSourceList(configuredSources: RemoteIssueSource[]): string {
        if (configuredSources.length === 0) {
            return "";
        }

        let sourceStrings: string[] = [];
        configuredSources.forEach(source => {
            sourceStrings.push(source.fullDisplayString);
        });
        return sourceStrings.join("; ");
    }

    public async parseNotification(message: NotificationMessage): Promise<void> {
        // no-op
    }

    async onAuthenticated(serverType: ServerType): Promise<void> {
        if (TEAM_VIEW_SERVERS.includes(serverType)) {
            await this.initView();
        }
    }


    public dispose(): void {
        getService(AuthenticationService.id).removeListener(this);
        this.onMessageFromWebviewDisposable?.dispose();
    }
}


export interface IssueSourceTableRow {
    id: number;
    serverName: string;
    sourceReferenceDisplayText: string;
    configuredSourceList: RemoteIssueSource[];
}
