const localize: LocalizeFunc = loadMessageBundle();

export enum DisplayType {
    ISSUE, LICENSE, MARKER
}

export enum IssueStatus {
    EXISTING, NEW, ABSENT
}

const markerDescriptionKey = "description";
const markerNewIssueKey = "new-issue";
const policyViolationShieldIcon = "policy-violation-shield";
export class NewIssue implements Copyable {
    private model: issue_pb_v1.IssueListItem;
    private columnsList: issue_pb_v1.ColumnInfo[];
    private columnNamesMap: Map<string, string>;
    private columnValuesMap: Map<string, string>;
    private details: IssueDetails | undefined;
    private eventInfo: EventInfo | undefined; 
    private displayType: DisplayType;
    private adjustedLineNumber: number;
    private description: string;
    private issueStatus;

    constructor(model: issue_pb_v1.IssueListItem, columnsList: issue_pb_v1.ColumnInfo[], displayType: DisplayType, issueType: IssueStatus = IssueStatus.EXISTING) {
        this.model = model;
        this.columnNamesMap = new Map();
        this.columnValuesMap = new Map();
        this.columnsList = columnsList;
        this.displayType = displayType;
        this.adjustedLineNumber = (model.getFilelocation()?.getLinenumber() ?? 0) - 1;
        this.description = model.getValuesMap().get(markerDescriptionKey) ?? "";
        this.issueStatus = model.getValuesMap().get(markerNewIssueKey) === "true" ? IssueStatus.NEW : issueType;
        columnsList.forEach(k => {
            let key = k.getId();
            let name = k.getName();
            let val = model.getValuesMap().get(key);
            if (val) {
                this.columnNamesMap.set(key, name);
                this.columnValuesMap.set(key, val);
            }   
        });
    }

    getIssueId(): string {
        return this.model.getId()?.getId() ?? "";
    }

    getExternalIssueId(): string {
        return this.model.getId()?.getExternalid() ?? "";
    }

    getColumnNamesMap(): Map<string, string> {
        return this.columnNamesMap;
    }

    getValuesMap(): Map<string, string> {
        return this.columnValuesMap;
    }

    getDisplayString(): string {
        const type = this.getType()
        if (type) {
            return type;
        }
        const component = this.getComponent();
        if (component) {
            return component;
        }
        const licenseName = this.getLicenseName();
        if (licenseName) {
            return licenseName;
        }
        const licenseFamily = this.getLicenseFamily();
        if (licenseFamily) {
            return licenseFamily;
        }
        return "";
    }

    getComponent(): string {
        return this.getValuesMap().get("component") ?? "";
    }

    getType(): string {
        return this.getValuesMap().get("type") ?? "";
    }

    getLicenseName(): string {
        return this.getValuesMap().get("licenseName") ?? "";
    }

    getLicenseFamily(): string {
        return this.getValuesMap().get("licenseFamily") ?? "";
    }

    getLocation() {
        return this.getValuesMap().get("location") ?? "";
    }

    /**
     * Gets the description text for this issue.
     * @returns The issue description, or empty string if no description is available
     */
    getDescription() {
        return this.description;
    }

    isNewIssue(): boolean {
        return this.issueStatus === IssueStatus.NEW;
    }

    isAbsentIssue(): boolean {
        return this.issueStatus === IssueStatus.ABSENT;
    }

    getFilePath(): string | undefined{
        return this.model.getFilelocation()?.getPath();
    }

    getOriginalLineNumber(): number {
        return this.model.getFilelocation()?.getLinenumber() ?? -1;
    }

    getLineNumber(): number {
        return this.adjustedLineNumber;
    }

    isLicenseAnalysisIssue(): boolean {
        return this.displayType === DisplayType.LICENSE;
    }

    isMarkerIssue(): boolean {
        return this.displayType === DisplayType.MARKER;
    }

    getDisplayType(): DisplayType {
        return this.displayType;
    }

    getSeverity(): Severity {
        let severity = this.getValuesMap().get("severity");

        switch (severity?.toLowerCase()) {
            case "info":
                return Severity.INFO;
            case "audit":
                return Severity.AUDIT;
            case "critical":
                return Severity.CRITICAL;
            case "high":
                return Severity.HIGH;
            case "medium":
                return Severity.MEDIUM;
            case "low":
                return Severity.LOW;
            case "unspecified":
                return Severity.UNSPECIFIED;
        }

        return Severity.UNKNOWN;
    }

    getIconPathForSeverity(): string {
        let contextService = getService(VscodeContextService.id);
        let severityText = getSeverityText(this.getSeverity()).toLowerCase();
        return contextService.getIconPath(severityText + ".svg", "impact");
    }

    getDetails(): IssueDetails | undefined {
        return this.details;
    }

    setDetails(details: IssueDetails) {
        this.details = details;        
    }

    getEventInfo(): EventInfo | undefined {
        return this.eventInfo;
    }

    setEventInfo(eventInfo: EventInfo | undefined) {
        this.eventInfo = eventInfo;
    }


    equals(other: NewIssue | undefined): boolean {
        if (other === null) {
            return false;
        }
        if (!(other instanceof NewIssue)) {
            return false;
        }

        return this.getIssueId() === other.getIssueId();
    }

    getCopyText(): string {
        let copyText = `Issue ID: ${this.getIssueId()} |\t`;
        this.columnValuesMap.forEach ((value: string, key: string) => {
            let columnName = this.columnNamesMap.get(key);
            copyText += `${columnName}: ${value} |\t`;
        });
        return copyText;
    }

    getIconPathForPolicyViolations(): string {
        let contextService = getService(VscodeContextService.id);
        return contextService.getIconPath(policyViolationShieldIcon + ".svg", "general");
    }

    getFixBy(): Date | undefined {
        return this.model.getFixby()?.toDate();
    }

    isPolicyViolationDetected(): boolean {
        return this.model.getViolationsList().length > 0;
    }

    getCoverityCID(): string | undefined {
        return this.getValuesMap().get("cid");
    }
}

export class EventInfo {
    private error: ControllerError | undefined;
    private contributingDetails: ContributingDetail[] = [];
    private sectionHeader: string = "";
    private contributingDetailDisplayText: string = "";

    constructor(model: issue_pb_v1.GetIssueEventInformationResponse, parent: NewIssue) {
        this.sectionHeader = model.getSectionheader();
        this.error = model.getError();
        this.contributingDetailDisplayText = model.getContributingdetaildisplaytext();

        let occurrences: ContributingDetail[] = [];
        model.getDetailsList().forEach((issueDetail, i) => {
            occurrences.push(new ContributingDetail(parent, issueDetail, i));
        });
        this.contributingDetails = occurrences;
        
    }

    getSectionHeader() {
        return this.sectionHeader;
    }

    getContributingDetailDisplayText() {
        if (!this.contributingDetailDisplayText) {
            return localize('event.info.display.text.default', 'Contributing detail');
        }
        return this.contributingDetailDisplayText;
    }

    getContributingDetails(): ContributingDetail[] {
        return this.contributingDetails;
    }

    getEventList(occurrenceIndex: number): NewEvent[] {
        return this.getSelectedContributingDetail(occurrenceIndex)?.getEventList() ?? [];
    }

    getMainEvent(occurrenceIndex: number): NewEvent | undefined {
        return this.getSelectedContributingDetail(occurrenceIndex).getMainEvent();
    }

    getSelectedContributingDetail(occurrenceIndex: number): ContributingDetail {
        if (occurrenceIndex < 0 || occurrenceIndex >= this.contributingDetails.length) {
            throw new Error(`Contributing detail index ${occurrenceIndex} out of bounds: ${occurrenceIndex} >= ${this.contributingDetails.length}`);
        }
        return this.contributingDetails[occurrenceIndex];
    }

    getError(): ControllerError | undefined {
        return this.error;
    }

    hasError(): boolean {
        return this.error !== undefined;
    }
}

export class ContributingDetail {
    private contributingDetail: issue_pb_v1.ContributingIssueDetail;
    private parent: NewIssue;
    private events: NewEvent[];
    private contributingDetailIndex: number;

    constructor(parent: NewIssue, contributingDetail: issue_pb_v1.ContributingIssueDetail, index: number) {
        this.parent = parent;
        this.contributingDetail = contributingDetail;
        this.events = [];
        this.contributingDetailIndex = index;
        this.events = this.buildEvents(contributingDetail.getEventsList());
    }

    private buildEvents(events: issue_pb_v1.ContributingIssueDetail.Event[]): NewEvent[] {
        let newEvents: NewEvent[] = [];
        events.forEach((event, i) => {
            newEvents.push(new NewEvent(this, event, i));
        });

        return newEvents;
    }

    getOccurrenceId(): string {
        return this.contributingDetail.getOccurrenceid();
    }
    
    getMainEvent(): NewEvent | undefined {
        for (let event of this.events) {
            let eventType = event.getEventType();
            if (Event.Type.MAINEVENT === eventType) {
                return event;
            }
        }
        return; // do not return an exception so that code execution can proceed even when no main event (SCA issues)
    }

    getMainEventFilePath(): string | undefined {
        return this.getMainEvent()?.getFilePath();
    }

    getMainEventLineNumber(): number | undefined {
        return this.getMainEvent()?.getLineNumber();
    }

    getParentIssue(): NewIssue {
        return this.parent;
    }

    isFilePathFound(): boolean {
        return this.contributingDetail.getLocation()?.getPathfound() ?? false;
    }

    getFilePath(): string | undefined {
        return this.getLocation()?.getPath();
    }

    getLineNumber(): number | undefined {
        return this.getLocation()?.getLinenumber();
    }

    getLocation(): Location | undefined {
        return this.contributingDetail.getLocation();
    }

    getCwe() {
        return this.contributingDetail.getCwe();
    }

    getCveList(): issue_pb_v1.Relationship[] {
        return this.contributingDetail.getCvesList();
    }

    getMetadata(): issue_pb_v1.GetIssueDetailsResponse.Data[] {
        return this.contributingDetail.getMetadataList();
    }

    getDetailsTitle(): string {
        return this.contributingDetail.getDetailstitle();
    }

    getContributingDetailIndex(): number {
        return this.contributingDetailIndex;
    }

    getIdentifier(): string {
        return `${this.getParentIssue().getIssueId()} contributing detail ${this.getContributingDetailIndex()}`;
    }

    getEventList(): NewEvent[] {
        return this.events;
    }
}

export class EventRemediation {
    type: Event.Type;
    description: string;
    eventNumber: number;
    filePath: string | undefined;
    lineNumber: number | undefined;
    private remediation: Component.Remediation;

    constructor(eventType: Event.Type, eventDescription: string, remediation: Component.Remediation, eventNumber: number, eventFilePath: string | undefined, eventLineNumber: number | undefined) {
        this.type = eventType;
        this.description = eventDescription;
        this.eventNumber = eventNumber;
        this.filePath = eventFilePath;
        this.lineNumber = eventLineNumber
        this.remediation = remediation;
    }

    getShortTermUpgradeGuidance(): UpgradeGuidance | undefined {
        let suggestedUpgrade = this.remediation?.getSuggestedupgrade();
        if (suggestedUpgrade) {
            return new UpgradeGuidance(suggestedUpgrade);
        }
        return undefined;
    }

    getLongTermUpgradeGuidance(): UpgradeGuidance | undefined {
        let latest = this.remediation?.getLatest();
        if (latest) {
            return new UpgradeGuidance(latest);
        }
        return undefined;
    }
}

export class NewEvent {
    private event: issue_pb_v1.ContributingIssueDetail.Event;
    private eventIndex: number;
    private parentContributingDetail: ContributingDetail;
    private remediation: EventRemediation | undefined;
    private children: NewEvent[] = [];

    constructor(parentContributingDetail: ContributingDetail, event: issue_pb_v1.ContributingIssueDetail.Event, eventIndex: number) {
        this.parentContributingDetail = parentContributingDetail;
        this.event = event;
        this.eventIndex = eventIndex;
        let remediation = this.event.getRemediation();

        if (remediation) {
            let eventType = this.getEventType();
            let eventDescription = this.getEventDescription();
            let eventNumber = this.getEventNumber();
            let eventFile = this.getFilePath();
            let eventLine = this.getLineNumber();
            this.remediation = new EventRemediation(eventType, eventDescription, remediation, eventNumber, eventFile, eventLine);
        }
        this.children = event.getEventsList().map((childEvent, i) => {
            return new NewEvent(parentContributingDetail, childEvent, i);
        });
    }

    getParentContributingDetail() {
        return this.parentContributingDetail;
    }

    getEventDescription(): string {
        return this.event.getDescription();
    }

    getEventType(): Event.Type {
        return this.event.getEventtype();
    }

    getFilePath(): string | undefined {
        return this.getLocation()?.getPath();
    }

    getLineNumber(): number | undefined {
        return this.getLocation()?.getLinenumber();
    }

    getLocation(): Location | undefined {
        return this.event.getLocation();
    }

    getRange(): Range | undefined {
        return this.event.getLocation()?.getRange();
    }

    getEventNumber() {
        return this.event.getEventnumber();
    }

    getRemediations(): EventRemediation[] {
        const remediations: EventRemediation[] = [];
        if (this.remediation) {
            remediations.push(this.remediation);
        }

        this.children.forEach(child => {
            remediations.push(...child.getRemediations());
        })

        return remediations;
    }


    getParentIssue(): NewIssue {
        return this.parentContributingDetail.getParentIssue();
    }

    getChildren(): NewEvent[] {
        return this.children;
    }

    getIdentifier(): string {
        return `${this.getParentContributingDetail().getIdentifier()} event ${this.getEventNumber()} index ${this.eventIndex} line ${this.getLineNumber()} desc ${this.getEventDescription()}`;
    }
}

export class IssueDetails {
    protected model: issue_pb_v1.GetIssueDetailsResponse;
    protected additionalFields: AdditionalField[] = [];
    protected additionalGroups: AdditionalGroup[] = [];

    constructor(model: issue_pb_v1.GetIssueDetailsResponse) {
        this.model = model;
        model.getAdditionalfieldsList().forEach(field => {
            this.additionalFields.push(new AdditionalField(field));
        });

        model.getAdditionaldatagroupsList().forEach(group => {
            this.additionalGroups.push(new AdditionalGroup(group));
        });
    }

    getIssueType(): string {
        return this.model.getIssuetype();
    }

    getSeverity(): Severity {
        return this.model.getSeverity();
    }

    getScanTool(): string {
        return this.model.getScantool();
    }

    getScandate(): Date | undefined {
        return this.model.getScandate()?.toDate();
    }

    getRelationshipFields(): issue_pb_v1.Relationship[] {
        return this.model.getRelationshipsList();
    }
    
    getAdditionalfields(): AdditionalField[] {
        return this.additionalFields;
    }

    getAdditionalGroups(): AdditionalGroup[] {
        return this.additionalGroups;
    }

    getPolicyViolations(): string[] {
        return this.model.getPolicyviolationsList();
    }

    getStandardsViolations(): issue_pb_v1.TreeNode[] {
        return this.model.getStandardviolationsList();
    }

    getPolarisPolicyViolations(): Violation[] {
        // return policy violations for polaris issues
        return this.model.getViolationsList();
    }

    getServerDisplayName(): string {
        if (this.model.hasServerinfo()) {
            return this.model.getServerinfo()!.getHumanreadableservername();
        }
        return "";
    }

    getServerShortName(): string {
        let shortName = "";
        if (this.model.hasServerinfo()) {
            shortName = this.model.getServerinfo()!.getShortname();
            if (shortName === "") {
                shortName = this.getServerDisplayName();
            }
        }
        return shortName;
    }

    hasServerLink(): boolean {
        return this.model.hasServerlink();
    }

    getServerLink(): string {
        if (this.hasServerLink()) {
            return this.model.getServerlink()!.getLinkurl();
        }
        return "";
    }

    getRemediation(): Component.Remediation | undefined {
        return this.model.getRemediation();
    }

    getShortTermUpgradeGuidance(): UpgradeGuidance | undefined {
        let remediation = this.getRemediation();
        if (remediation && remediation.getSuggestedupgrade()) {
            return new UpgradeGuidance(remediation.getSuggestedupgrade()!);
        }
        return undefined;
    }

    getLongTermUpgradeGuidance(): UpgradeGuidance | undefined {
        let remediation = this.getRemediation();
        let latest = remediation?.getLatest();
        if (latest) {
            return new UpgradeGuidance(latest);
        }
        return undefined;
    }

    getIsBlackDuckAssistAvailable(): boolean {
        return this.model.getBlackduckassistinfoavailable();
    }

    getError(): ControllerError | undefined {
        return this.model.getError();
    }

    hasError(): boolean {
        return this.model.getError() !== undefined;
    }
}

