export class AdditionalGroup {
    protected model: issue_pb_v1.GetIssueDetailsResponse.DataGroup;
    private additionalFields: AdditionalField[] = [];
    private children: AdditionalGroup[] = [];

    constructor(model: issue_pb_v1.GetIssueDetailsResponse.DataGroup) {
        this.model = model;
        model.getDataList().forEach(field => {
            this.additionalFields.push(new AdditionalField(field));
        });
        model.getChildrenList().forEach(child => {
            this.children.push(new AdditionalGroup(child));
        })
    }

    getId(): string {
        return this.model.getId();
    }
    
    getDisplayName(): string {
        return this.model.getDisplayname();
    }

    getChildrenList(): AdditionalGroup[] {
        return this.children;
    }

    getCanCollapse(): boolean {
        return this.model.getCancollapse()
    }

    getExpandedByDefault(): boolean {
        return this.model.getExpandedbydefault()
    }

    getSeverity(): Severity {
        return this.model.getSeverity()
    }

    getAdditionalFields(): AdditionalField[] {
        return this.additionalFields;
    }
}

export class UpgradeGuidance {
    protected version: string;
    protected criticalVulnCount: number;
    protected highVulnCount: number;
    protected mediumVulnCount: number;
    protected lowVulnCount: number;
    protected infoVulnCount: number;

    constructor(upgradeOption: Component.Remediation.UpgradeOption) {
            this.version = upgradeOption.getVersion();
            this.criticalVulnCount = upgradeOption.getCriticalvulncount();
            this.highVulnCount = upgradeOption.getHighvulncount();
            this.mediumVulnCount = upgradeOption.getMediumvulncount();
            this.lowVulnCount = upgradeOption.getLowvulncount();
            this.infoVulnCount = upgradeOption.getInfovulncount();
    }

    getVersion(): string {
        return this.version;
    }

    getCriticalVulnCount(): number {
        return this.criticalVulnCount;
    }

    getHighVulnCount(): number {
        return this.highVulnCount;
    }

    getMediumVulnCount(): number {
        return this.mediumVulnCount;
    }

    getLowVulnCount(): number {
        return this.lowVulnCount;
    }

    getInfoVulnCount(): number {
        return this.infoVulnCount;
    }
}
