import { CollectLogsRequest, CollectLogsResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/collect_logs_pb";
import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { commands, Disposable, Uri, WebviewPanel } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { AnalysisContextService } from "../../services/analysisContextService";
import { ControllerClientService } from "../../services/controllerClientService";
import { ExtensionConfigService } from "../../services/extensionConfigService";
import { getService } from "../../services/serviceContainer";
import { WebviewPresenter } from "../webviewPresenter";
import { EXPORT_LOGS_BUTTON_ID, EXPORT_LOGS_RESPONSE_FAILURE_ID, EXPORT_LOGS_RESPONSE_LOADING_ID, EXPORT_LOGS_RESPONSE_SUCCESS_ID, OPEN_LOGS_FOLDER_BUTTON_ID } from "./exportLogsViewComponent";
import { ExportLogsViewProvider } from "./exportLogsViewProvider";

const localize: LocalizeFunc = loadMessageBundle();

export class ExportLogsViewPresenter implements WebviewPresenter {
    private readonly panel: WebviewPanel;
    private view: ExportLogsViewProvider;
    private onMessageFromWebviewDisposable: Disposable | undefined;

    constructor(panel: WebviewPanel) {
        this.panel = panel;
        this.view = getService(ExportLogsViewProvider.id);
        this.view.initView(this.panel);
    }

    public async parseNotification(message: NotificationMessage) { // not needed for export logs
    }

    public async initView() {

        this.view.initHtml();
        let latestArchivePath: string | undefined;
        this.onMessageFromWebviewDisposable = this.view.onMessageFromWebview(async message => {
            switch (message.command) {

                case EXPORT_LOGS_BUTTON_ID:
                    this.view.postMessageToWebview({
                        command: EXPORT_LOGS_RESPONSE_LOADING_ID
                    });
                    let response = await this.exportLogs();
                    let collectLogsStatus: CollectLogsResponse.Status = response.getStatus();
                    if (collectLogsStatus === CollectLogsResponse.Status.SUCCESS) {
                        let archivePath = response.getArchivelocation();
                        latestArchivePath = archivePath;
                        this.view.postMessageToWebview({
                            command: EXPORT_LOGS_RESPONSE_SUCCESS_ID,
                            text: localize('export.logs.success.text', "Saved: {0}", archivePath),
                        });
                    } else {
                        let errorMessage = response.getMessage();
                        this.view.postMessageToWebview({
                            command: EXPORT_LOGS_RESPONSE_FAILURE_ID,
                            text: localize('export.logs.failure.text', "Failed: {0}", errorMessage),
                        });
                    }

                    break;
                case OPEN_LOGS_FOLDER_BUTTON_ID:
                    if (latestArchivePath) {
                        await this.openLogsFolder(latestArchivePath);
                    }
                    break;

            }
        });
    }

    private async exportLogs() {
        let diagnosticsService = await getService(ControllerClientService.id).getDiagnosticsServiceClient();
        let request = new CollectLogsRequest();
        request.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        let extensionLogDir = await getService(ExtensionConfigService.id).getExtensionLogPath();
        request.addAdditionallocations(extensionLogDir);
        return diagnosticsService.collectLogs(request);
    }

    private async openLogsFolder(logsArchivePath: string) {
        return commands.executeCommand("revealFileInOS", Uri.file(logsArchivePath));
    }

    public dispose() {
        this.onMessageFromWebviewDisposable?.dispose();
    }
}