export abstract class SetupServiceListener {
    abstract onOnboardingComplete(): Promise<void>;
}

export abstract class RegistrationListener {
    abstract onRegistrationComplete(): Promise<void>;
}

export enum FlowTypeEnum {
    None,
    Initializing,
    StandardEdition,
    InstalledTools_StandardEdition,
}

export enum SetupStep {
    Unset,
    Download,
    DownloadError,
    PreparingToolDownloadOrUpdate,
    Registration
}

/**
 * A service to handle the control of the onboarding flow, and tool install/update
 */
export abstract class SetupService {
    static readonly id: ServiceId<SetupService> = { id: SetupService.name };

    abstract addListener(listener: SetupServiceListener): void;
    abstract removeListener(listener: SetupServiceListener): void;

    abstract addRegistrationListener(listener: RegistrationListener): void;
    abstract removeRegistrationListener(listener: RegistrationListener): void;
    abstract notifyRegistrationListeners(): Promise<void>;

    /**
     * Takes the user through the setup flow
     * Checks if the user has tools installed, and is licensed to use Code Sight
     * If tools are missing or licensing is needed, takes the user through the appropriate onboarding flow
     */
    abstract beginOnboarding(): Promise<void>;

    /**
     * Requests the install or update of a given tool
     * If the given tool is not installed, or an update is available, takes the user through the install flow for that tool
     * 
     * No-op during setup
     * 
     * @param toolType 
     */
    abstract installOrUpdateTool(toolType: ToolTypeEnum, update?: boolean): Promise<void>;

    /**
     * Takes the user through new user specific onboarding flow
     * Called when start trial button is pressed
     */
    abstract beginStandardEditionFlow(): Promise<void>;

    /**
     * Downloads Standard Edition tools outside onboarding
     * Called when start trial button is pressed (navigated from Installed Tools page)
     */
    abstract beginEnableStandardEditionFlow(): Promise<void>;
    
    /**
     * Takes the user through coverity specific onboarding flow
     * Called when start trial button is pressed
     */
    abstract beginCoverityUserFlow(): Promise<void>;

    /**
     * Takes the user through polaris specific onboarding flow
     * Called when "Connect to Polaris" is pressed
     */
    abstract beginPolarisUserFlow(): Promise<void>;

    /**
     * Takes the user through SRM specific onboarding flow
     * Called when "Connect to Software Risk Manager" is pressed
     */
    abstract beginSRMUserFlow(): Promise<void>;

    /**
     * Takes the user through signal specific onboarding flow
     * Called when "Validate LLM Key" is pressed
     */
    abstract beginSignalUserFlow(): Promise<void>;

    /**
     * Takes the user through black duck specific onboarding flow
     * Called when start trial button is pressed
     */
    abstract beginBlackDuckUserFlow(): Promise<void>;

    /**
     * Parses notification message state from controller, and 
     * determines correct state for onboarding flow
     * @param message sent from controller
     */
    abstract parseNotificationMessage(message: NotificationMessage): Promise<void>;

    /**
     * Updates the state of tool install when retry button is pressed during onboarding
     */
    abstract retryDownloadClicked(): void;
    
    /**
     * Updates the state of tool install when use local binary is pressed during onboarding
     */
    abstract useLocalBinaryClicked(toolType:ToolTypeEnum|undefined): Promise<void>;
     
    /**
     * Handles previous button click for different onboarding states
    */
    abstract authPreviousClicked(): Promise<void>;
    
    /**
     * Changes the setup step to the value provided and displays the new webview
     */
    abstract showSetupStep(step: SetupStep): Promise<void>;
    
    /**
     * Displays the webview associated with the current setup step
     */
    abstract showCurrentSetupStep(): Promise<void>;
    
    /**
     * Continues tool download depending on which flow we're currently at
     */
    abstract continueFlow(): Promise<void>;

    /**
     * Updates the state of tool install when skip button is pressed during onboarding
     */
    abstract skipDownloadClicked(): Promise<void>;

    /**
     * Returns whether we are currently onboarding
     */
    abstract currentlyOnboarding(): boolean;

    /**
     * Makes a request to setup tools for the current analysis context.
     */
    abstract setupCoverityTool(isDryRun?: boolean): Promise<void>;
}

export const EXTENSION_CONTEXT_SETUP_COMPLETE = "codesight.setupComplete";
export class SetupServiceImpl implements SetupService {

    private listeners: SetupServiceListener[];
    private registrationListeners: RegistrationListener[];
    private standardEditionFlowIterator: AsyncGenerator | undefined;
    private currentlyDownloadingTool: ToolTypeEnum | undefined;
    private lastDownloadNotification: NotificationMessage | undefined;
    private lastErrorNotification: NotificationMessage | undefined;
    protected currentFlowType: FlowTypeEnum;
    protected currentSetupStep: SetupStep;

    constructor() {
        this.listeners = [];
        this.registrationListeners = [];
        this.currentSetupStep = SetupStep.Unset;
        this.currentFlowType = FlowTypeEnum.None;
    }

    addListener(listener: SetupServiceListener): void {
        this.listeners.push(listener);
    }

    removeListener(listener: SetupServiceListener): void {
        let index = this.listeners.indexOf(listener);
        if (index >= 0) {
            this.listeners.splice(index, 1);
        }
    }

    addRegistrationListener(listener: RegistrationListener): void {
        this.registrationListeners.push(listener);
    }

    removeRegistrationListener(listener: RegistrationListener): void {
        let index = this.registrationListeners.indexOf(listener);
        if (index >= 0) {
            this.registrationListeners.splice(index, 1);
        }
    }

    async notifyRegistrationListeners(): Promise<void> {
        const listenerPromises: Promise<void>[] = [];
        this.registrationListeners.forEach(listener => {
            listenerPromises.push(listener.onRegistrationComplete());
        });

        await Promise.all(listenerPromises);
    }

    async beginOnboarding(): Promise<void> {
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        commands.executeCommand("setContext", EXTENSION_CONTEXT_SETUP_COMPLETE, false);
        this.currentFlowType = FlowTypeEnum.Initializing;
        // Update the setup view to show that we are loading
        const setupTreePresenter = getService(ViewProviderService.id).getOrCreateSetupPresenter();
        setupTreePresenter.showInitialLoadingState();

        try {
            const configClient = await getService(ControllerClientService.id).getConfigurationServiceClient();
            const useBdForContextRequest = new UseBdSaasForContextRequest();
            useBdForContextRequest.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
            await configClient.useBdSaasForContext(useBdForContextRequest);
    
            // check license status
            await getService(ToolStateService.id).refreshToolsFromController(false);
        } catch (error) {
            getLogger().warn(`Error occurred during onboarding: ${error}`);
            setupTreePresenter.showErrorMessage();
            return;
        }

        const entitlementService = getService(EntitlementService.id);
        const entitlements = entitlementService.getCachedProductEntitlement();
        let hasCsseLicense = entitlements.hasCsseLicense();
        let hasCoverityEntitlement = entitlements.isCoverityEntitled();
        let hasBlackduckEntitlement = entitlements.isBlackDuckEntitled();
        let hasPolarisEntitlement = entitlements.isPolarisEntitled();
        let hasSignalEntitlement = entitlements.isSignalEntitled();
        let hasSRMEntitlement = entitlements.isSRMEntitled();

        getService(ProgressNotificationService.id).updateSetupProgress(true);

        if (!hasCsseLicense && !hasCoverityEntitlement && !hasBlackduckEntitlement && !hasPolarisEntitlement && !hasSignalEntitlement && !hasSRMEntitlement) {
            await this.flowShowRegistration();
            return;
        } else if (hasCsseLicense) {
            const toolStateService = getService(ToolStateService.id);
            const sigmaInstalled = toolStateService.isSigmaInstalled();
            const blackduckInstalled = toolStateService.isBlackduckInstalled();

            // always download CSSE tools if not skipped
            if ((!sigmaInstalled && !this.hasUserSkippedTool(ToolTypeEnum.Sigma)) || (!blackduckInstalled && !this.hasUserSkippedTool(ToolTypeEnum.Blackduck))) {
                return this.beginStandardEditionFlow();
            }
        }
        
        // no onboarding needed, complete setup
        await this.showWelcomeMessageOnUpgrade();
        return this.completeSetup();
    }

    async beginStandardEditionFlow(): Promise<void> {
        this.standardEditionFlowIterator = this.standardEditionFlow();
        await this.standardEditionFlowIterator.next();
    }

    async* standardEditionFlow() {
        this.currentFlowType = FlowTypeEnum.StandardEdition;
        await this.updateSetupTreeView();

        const toolStateService = getService(ToolStateService.id);
        const shouldInstallSigma = !toolStateService.isSigmaInstalled() && !this.hasUserSkippedTool(ToolTypeEnum.Sigma);
        const shouldInstallBlackduck = !toolStateService.isBlackduckInstalled() && !this.hasUserSkippedTool(ToolTypeEnum.Blackduck);

        // download sigma
        if (shouldInstallSigma) {
            await this.flowDownloadTool(ToolTypeEnum.Sigma);
            yield;
        }
        await this.flowDownloadToolFinished();

        // download blackduck
        if (shouldInstallBlackduck) {
            await this.flowDownloadTool(ToolTypeEnum.Blackduck);
            yield;
        }
        await this.flowDownloadToolFinished();

        // complete setup workflow
        await this.flowCompleteSetup();
    }
    
    async beginCoverityUserFlow(): Promise<void> {
        await getService(WebviewCoordinator.id).showEditCoverityServerConfiguration();
        await this.completeSetup();
    }

    async beginEnableStandardEditionFlow(): Promise<void> {
        this.standardEditionFlowIterator = this.enableStandardEditionFlow();
        await this.standardEditionFlowIterator.next();
    }

    async* enableStandardEditionFlow() {
        this.currentFlowType = FlowTypeEnum.InstalledTools_StandardEdition;
        const toolStateService = getService(ToolStateService.id);

        // download sigma
        if (!toolStateService.isSigmaInstalled()) {
            await this.flowDownloadTool(ToolTypeEnum.Sigma);
            yield;
        }
        await this.flowDownloadToolFinished();

        // download blackduck
        if (!toolStateService.isBlackduckInstalled()) {
            await this.flowDownloadTool(ToolTypeEnum.Blackduck);
            yield;
        }
        await this.flowDownloadToolFinished();

        // complete setup workflow
        this.currentSetupStep = SetupStep.Unset;
        this.resetFlowState();
        await getService(WebviewCoordinator.id).showInstalledToolsMessage();
    }

    resetFlowState() {
        this.standardEditionFlowIterator = undefined;
        this.currentFlowType = FlowTypeEnum.None;
    }

    async beginSignalUserFlow(): Promise<void> {
        await getService(WebviewCoordinator.id).showSignalAuthView();
        await this.completeSetup();
    }

    async beginPolarisUserFlow(): Promise<void> {
        await getService(WebviewCoordinator.id).showEditPolarisServerConfiguration();
        await this.completeSetup();
    }

    async beginSRMUserFlow(): Promise<void> {    
        await getService(WebviewCoordinator.id).showEditSRMServerConfiguration();
        await this.completeSetup();
    }

    async beginBlackDuckUserFlow(): Promise<void> {
        await getService(WebviewCoordinator.id).showEditBlackDuckServerConfiguration();
        await this.completeSetup();
    }

    async updateSetupTreeView(downloadError?:ToolTypeEnum) {
        if (!this.currentlyOnboarding()) {
            return;
        }

        const toolStateService = getService(ToolStateService.id);
        const setupTreePresenter = getService(ViewProviderService.id).getOrCreateSetupPresenter();
       
        let sigmaSetupStatus = SetupStepStatus.Unstarted;
        if(toolStateService.isSigmaInstalled()){
            sigmaSetupStatus = SetupStepStatus.Success;
        } else if(downloadError === ToolTypeEnum.Sigma){
            sigmaSetupStatus = SetupStepStatus.Failed;
        } else if(this.currentlyDownloadingTool === ToolTypeEnum.Sigma){
            sigmaSetupStatus = SetupStepStatus.Installing;
        } else if(this.hasUserSkippedTool(ToolTypeEnum.Sigma)){
            sigmaSetupStatus = SetupStepStatus.Skipped;
        }

        let bdSetupStatus = SetupStepStatus.Unstarted;
        if(toolStateService.isBlackduckInstalled()){
            bdSetupStatus = SetupStepStatus.Success;
        } else if(downloadError === ToolTypeEnum.Blackduck){
            bdSetupStatus = SetupStepStatus.Failed;
        } else if(this.currentlyDownloadingTool === ToolTypeEnum.Blackduck){
            bdSetupStatus = SetupStepStatus.Installing;
        } else if(this.hasUserSkippedTool(ToolTypeEnum.Blackduck)){
            bdSetupStatus = SetupStepStatus.Skipped;
        }
        
        let coveritySetupStatus = SetupStepStatus.Unstarted;
        if(toolStateService.isCoverityInstalled()){
            coveritySetupStatus = SetupStepStatus.Success;
        } else if(downloadError === ToolTypeEnum.Coverity){
            coveritySetupStatus = SetupStepStatus.Failed;
        } else if(this.currentlyDownloadingTool === ToolTypeEnum.Coverity){
            coveritySetupStatus = SetupStepStatus.Installing;
        } else if(this.hasUserSkippedTool(ToolTypeEnum.Coverity)){
            coveritySetupStatus = SetupStepStatus.Skipped;
        }

        switch(this.currentFlowType) {
            case FlowTypeEnum.StandardEdition:
                return setupTreePresenter.showSetupStatusFlow({
                    createTrialAccount: SetupStepStatus.Success,
                    downloadSigma: sigmaSetupStatus,
                    connectToBlackduckServer: SetupStepStatus.NotApplicable,
                    downloadBlackduck: bdSetupStatus,
                    connectToCoverityServer: SetupStepStatus.NotApplicable,
                    downloadCoverity: SetupStepStatus.NotApplicable,
                });
        }
    }
    
    private async flowDownloadTool(tool: ToolTypeEnum) {
        this.currentlyDownloadingTool = tool;
        await this.updateSetupTreeView();
        await this.installOrUpdateTool(tool);
        await this.showSetupStep(SetupStep.Download);
    }
    
    private async flowDownloadToolFinished() {
        this.currentlyDownloadingTool = undefined;
        await this.updateSetupTreeView();
    }
    
    private async flowCompleteSetup() {
        await getService(ToolStateService.id).refreshToolsFromController(true);
        await getService(WebviewCoordinator.id).showWelcomeMessage();
        
        this.standardEditionFlowIterator = undefined;
      
        await addDelay(2000); // 2 second delay
        return this.completeSetup();
    }
    
    private async flowShowRegistration() {
        const setupTreePresenter = getService(ViewProviderService.id).getOrCreateSetupPresenter();
        
        // prompt user to start trial
        setupTreePresenter.showSetupNeededMessage();

        // open registration webview
        return this.showSetupStep(SetupStep.Registration);
    }

    async installOrUpdateTool(toolType: ToolTypeEnum, update?: boolean): Promise<void> {
        if (!this.currentlyOnboarding()) {
            this.currentSetupStep = SetupStep.PreparingToolDownloadOrUpdate;
        }

        if (update) {
            await this.startToolUpdate(toolType);
            return;
        }
        
        switch (toolType) {
            case ToolTypeEnum.Sigma:
                await this.setupSigma();
                break;
            case ToolTypeEnum.Blackduck:
                await this.setupBlackduck();
                break;
            case ToolTypeEnum.Coverity:
                await this.setupCoverityTool();
                break;
        }
    }

    async startToolUpdate(tool: ToolTypeEnum) {
        let setupRequest = new SetupToolRequest();
        let analysisContextService = getService(AnalysisContextService.id);
        setupRequest.setContextid(analysisContextService.getAnalysisContextId());
        setupRequest.setProjectrootpath(analysisContextService.getContextRoot());
        
        switch (tool) {
            case ToolTypeEnum.Sigma:
                setupRequest.addTool(LicensedToolsConfig.Type.SIGMA);
                break;
            case ToolTypeEnum.Coverity:
                setupRequest.addTool(LicensedToolsConfig.Type.COVERITY);
                break;
            case ToolTypeEnum.Blackduck:
                setupRequest.addTool(LicensedToolsConfig.Type.BLACKDUCK);
        }

        let toolClient = await getService(ControllerClientService.id).getToolServiceClient();
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        toolClient.updateTools(setupRequest);
    }
    
    async updateOnboardingToolDownloadState(message: NotificationMessage) {
        getService(ProgressNotificationService.id).updateSetupProgress(false, message);
        
        let isSuccessState: boolean = false;
        if (isSetupErrorState(message)) {
            isSuccessState = false;
        } else if (isSetupSuccessState(message)) {
            isSuccessState = true;
        } else {
            return;
        }

        if (isSigmaMessage(message) && this.currentlyDownloadingTool === ToolTypeEnum.Sigma) {
            if (isSuccessState) {
                await this.continueFlow();
            } else if (this.currentlyOnboarding()) {
                await this.updateSetupTreeView(ToolTypeEnum.Sigma);
            } else {
                this.resetFlowState();
            }
        } else if (isBlackduckMessage(message) && this.currentlyDownloadingTool === ToolTypeEnum.Blackduck) {
            if (isSuccessState) {
                await this.continueFlow();
            } else if (this.currentlyOnboarding()) {
                await this.updateSetupTreeView(ToolTypeEnum.Blackduck);
            } else {
                this.resetFlowState();
            }
        } else if (isCoverityMessage(message) && this.currentlyDownloadingTool === ToolTypeEnum.Coverity) {
            if (isSuccessState) {
                await this.continueFlow();
            } else if (this.currentlyOnboarding()) {
                await this.updateSetupTreeView(ToolTypeEnum.Coverity);
            } else {
                this.resetFlowState();
            }
        }
    }

    async continueFlow() {
        if (this.currentFlowType === FlowTypeEnum.StandardEdition || this.currentFlowType === FlowTypeEnum.InstalledTools_StandardEdition) {
            await this.standardEditionFlowIterator?.next();
        }
    }

    public retryDownloadClicked() {
        return this.updateSetupTreeView();
    }
    
    public async useLocalBinaryClicked(toolType:ToolTypeEnum|undefined): Promise<void> {
        switch(toolType){
            case ToolTypeEnum.Sigma:
                return this.handleBrowseForSigma();
            case ToolTypeEnum.Blackduck:
                return this.handleBrowseForBlackduck();
            default:
                getLogger().warn(`Use local binary selected for incompatible tool type ${toolType}`);
                return;
        }
    }

    public async authPreviousClicked() {
        await this.showSetupStep(SetupStep.Unset); // show installed tools
    }

    public skipDownloadClicked() {
        if(this.currentlyDownloadingTool === undefined) {
            return Promise.resolve();
        }
        // preserve that the tool has been skipped
        getService(VscodeContextService.id).preserveToolInstallSkipped(this.currentlyDownloadingTool, true);
        return this.continueFlow();
    }

    public currentlyOnboarding() : boolean {
        return this.currentFlowType === FlowTypeEnum.Initializing || this.currentFlowType === FlowTypeEnum.StandardEdition;
    }

    private hasUserSkippedTool(toolType: ToolTypeEnum): boolean {
        return getService(VscodeContextService.id).getPreservedToolInstallSkipped(toolType);
    }

    private async completeSetup() {
        getService(ProgressNotificationService.id).hideSetupProgress();
        this.currentFlowType = FlowTypeEnum.None;
        this.currentSetupStep = SetupStep.Unset;
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        commands.executeCommand("setContext", EXTENSION_CONTEXT_SETUP_COMPLETE, true);

        const logger = getLogger();
        const listenerPromises: Promise<void>[] = [];
        logger.info("onboarding complete, notifying listeners");
        this.listeners.forEach(listener => {
            listenerPromises.push(listener.onOnboardingComplete());
        });
        await Promise.all(listenerPromises);
    }
    
    public async parseNotificationMessage(message: NotificationMessage) {
        // don't parse license state messages
        if (isCsseLicenseStateMessage(message)) {
            await getService(EntitlementService.id).checkEntitlements();
            return;
        }

        // don't parse auto install tool (bridge, signal) setup messages
        if (isAutoInstallToolSetupMessage(message)) {
            return;
        }

        await this.updateOnboardingToolDownloadState(message);        
        if (isSetupMessage(message)) {
            await this.handleSetupMessage(message);
        }
    }
    
    private async handleSetupMessage(message: NotificationMessage) {
        if (!hasState(message)) {
            getLogger().info("State was empty for a tool setup message");
            return;
        }

        if (isSetupErrorState(message)) {
            await this.handleSetupErrorMessage(message);
        } else if (isSetupSuccessState(message) || isNoToolMatchState(message) || isUpdateMessage(message)) {
            await this.handleSetupSuccessMessage(message);
        } else if (isDownloadRelatedSetupMessage(message)) {
            await this.handleDownloadStatusMessage(message);
        }
        
        if(!getService(ToolStateService.id).isToolStateLoading()){
            // add a welcome message if a tool exists
            if (getService(ToolStateService.id).isAnyToolInstalled()) {
                await getService(ViewProviderService.id).getOrCreateExtensionStatusPresenter().parseNotificationMessage(createWelcomeMessage());
            }
        }
    }

    private async handleSetupErrorMessage(message: NotificationMessage) {
        if (!isAuthenticationError(message)) {
            if (this.currentSetupStep === SetupStep.Download || this.currentSetupStep === SetupStep.DownloadError || this.currentSetupStep === SetupStep.PreparingToolDownloadOrUpdate) {
                // handled cases: we have hit download error and download screen is visible, we hit error while trying to install a tool,
                // we hit another error while trying to resolve an older error
                this.currentSetupStep = SetupStep.DownloadError;
                this.lastErrorNotification = message;
                await getService(WebviewCoordinator.id).showDefaultNotification(message);
            }
        }
    }

    private async handleSetupSuccessMessage(message: NotificationMessage) {        
        // show installed tools message only after download step
        if (this.currentSetupStep === SetupStep.Download && isSetupSuccessState(message) && this.currentFlowType === FlowTypeEnum.None) {
            await getService(WebviewCoordinator.id).showInstalledToolsMessage();
            // Reset to initial
            this.currentSetupStep = SetupStep.Unset;
            this.lastDownloadNotification = undefined;
        }
    }
    
    private async handleDownloadStatusMessage(message: NotificationMessage) {

        this.currentSetupStep = SetupStep.Download;
        this.lastDownloadNotification = message;

        // parse, but do not force show, the download message
        await getService(WebviewCoordinator.id).showDownloadNotification(message, false);
    }
    
    /**
     * Shows the current setup step (defaults to installed tools message).
     */
    async showCurrentSetupStep(): Promise<void> {
        switch (this.currentSetupStep) {
            case SetupStep.Download:
                await getService(WebviewCoordinator.id).showDownloadNotification(this.lastDownloadNotification);
                break;
            case SetupStep.DownloadError:
                if (this.lastErrorNotification) {
                    await getService(WebviewCoordinator.id).showDefaultNotification(this.lastErrorNotification);
                }
                break;
            case SetupStep.Registration:
                await getService(WebviewCoordinator.id).showRegistrationForm();
                break;
            case SetupStep.PreparingToolDownloadOrUpdate:
                // intentional fallthrough
            default:
                await getService(WebviewCoordinator.id).showInstalledToolsMessage();
                break;
        }
    }

    async showSetupStep(step: SetupStep) : Promise<void> {
        this.currentSetupStep = step;
        await this.showCurrentSetupStep();
    }

    private async setupBlackduck(): Promise<void> {
        let toolService = await getService(ControllerClientService.id).getToolServiceClient();
        let contextService = getService(AnalysisContextService.id);
        let setupToolRequest = new SetupToolRequest();
        setupToolRequest.setContextid(contextService.getAnalysisContextId());
        setupToolRequest.setProjectrootpath(contextService.getContextRoot());
        setupToolRequest.addTool(LicensedToolsConfig.Type.BLACKDUCK);

        await toolService.setupTools(setupToolRequest);
    }

    async setupCoverityTool(isDryRun?: boolean): Promise<void> {
        let toolService = await getService(ControllerClientService.id).getToolServiceClient();
        let contextService = getService(AnalysisContextService.id);
        let setupToolRequest = new SetupToolRequest();
        isDryRun = isDryRun ?? false;
        setupToolRequest.setIsdryrun(isDryRun);
        setupToolRequest.setContextid(contextService.getAnalysisContextId());
        setupToolRequest.setProjectrootpath(contextService.getContextRoot());
        setupToolRequest.addTool(LicensedToolsConfig.Type.COVERITY);

        await toolService.setupTools(setupToolRequest);
    }

    async setupSigma(): Promise<void> {
        let controllerToolService = await getService(ControllerClientService.id).getToolServiceClient();
        let contextService = getService(AnalysisContextService.id);
        let contextId = contextService.getAnalysisContextId();

        let setupRequest = new SetupToolRequest();

        setupRequest.setContextid(contextId);
        setupRequest.setProjectrootpath(contextService.getContextRoot());
        setupRequest.setToolList([LicensedToolsConfig.Type.SIGMA]);
        await controllerToolService.setupTools(setupRequest);
        return;
    }

    private async handleBrowseForSigma() : Promise<void>{
        await getService(WebviewCoordinator.id).showSigmaInstallLocationView(this.currentlyOnboarding());
    }

    private async handleBrowseForBlackduck() : Promise<void> {
        let chosenFile = await getService(VsCodeInputService.id).showOpenDialog({
            canSelectFolders:false,
            canSelectMany:false,
            filters: {
                "Zips" : ["zip"]
            },
            title: localize('browse.for.detect.key', 'Location of downloaded detect zip')
        });
        if(!chosenFile || chosenFile.length < 1){
            getLogger().debug("No file selected from detect selection browser");
            return;
        }

        await this.updateSetupTreeView(); // update status view so that it shows loading while we evaluate the selected file
        const toolService = await getService(ControllerClientService.id).getToolServiceClient();
        const addToolRequest = new ModifyToolInstallationsRequest();
        addToolRequest.setAction(ModifyToolInstallationsRequest.Action.ADD);
        const licensedToolConfig = new LicensedToolsConfig();
        let path = normalizeDriveLetter(chosenFile[0].fsPath);
        licensedToolConfig.setInstallpath(path);
        licensedToolConfig.setType(LicensedToolsConfig.Type.BLACKDUCK);
        addToolRequest.setToolconfig(licensedToolConfig);
        const addToolResponse = await toolService.modifyToolInstallations(addToolRequest);
        let err = addToolResponse.getError();
        if(err){
            await this.updateSetupTreeView(ToolTypeEnum.Blackduck);
            // eslint-disable-next-line @typescript-eslint/no-floating-promises -- no-floating-promises Do not wait, so this returns before the popup is closed 
            getService(WarningMessageService.id).invalidDetectZipSelected(err.getMessage());
        } else {
            // the following call takes >1 second, so remove the error message from the webview while we wait
            await getService(WebviewCoordinator.id).showDownloadNotification(undefined, false);
            await getService(ToolStateService.id).refreshToolsFromController(true);
            await this.updateSetupTreeView();
            // remove setup error messages from notifications list since tool setup was successful
            await getService(ViewProviderService.id).getOrCreateExtensionStatusPresenter().removeSetupErrorNotification(ToolTypeEnum.Blackduck);
            if (this.currentFlowType === FlowTypeEnum.None) {
                await getService(WebviewCoordinator.id).showInstalledToolsMessage();
            } else {
                return this.continueFlow();
            }
        }
    } 

    private async showWelcomeMessageOnUpgrade() {
        // update extension version if there's a mismatch
        let oldExtensionVersion = getService(VscodeContextService.id).getPreservedCodeSightVersion();
        let currentExtensionVersion = getService(ExtensionService.id).getCodeSightVersion();
        if (currentExtensionVersion !== oldExtensionVersion) {
            // Update the stored extension version
            getService(VscodeContextService.id).preserveCodeSightVersion(currentExtensionVersion);
            let skipOnboardingMessages = isFeatureFlagEnabled(ENV_CODESIGHT_DESKTOP_TEST_SKIP_ONBOARDING_POPUP_MESSAGES);
            if (!skipOnboardingMessages) {
                await getService(WebviewCoordinator.id).showWelcomeMessage();
            }
        }
    }
}
