import { Severity } from "@codesight/codesight-controller-proto/controller_proto/v0/severity_pb";
import { Webview } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { ServiceId } from "../../services/serviceContainer";
import { debounce } from "../../utils/timingUtils";
import * as webviewUtils from "../../utils/webviewUtils";
import { WebviewProvider } from "../webviewProvider";

const localize: LocalizeFunc = loadMessageBundle();

export namespace IssueDetailsCommandIds {
    export const COPY_TO_CLIPBOARD = "copy-to-clipboard";
}

export abstract class IssueDetailsProviderBase extends WebviewProvider {

    static readonly id: ServiceId<IssueDetailsProviderBase> = { id: IssueDetailsProviderBase.name };

    abstract initNoIssueSelectedHtml(): void;


    addHeaderWithText(header: string, text: string | undefined, sameLine: boolean, boldedHeader: boolean = true) {
        if (text === "" || text === undefined) {
            return "";
        }
        if (sameLine) {
            return `<div class="margin-left vertical-less-margin center-flex">
                             <div>${boldedHeader ? `<span class="text-bold">${header}</span>` : header}</div>
                            <span style="margin-left:5px;text-transform:capitalize;">${text}</span>
                        </div>`;
        }
        return `<div class="margin-left vertical-margin">
                    <div>${boldedHeader ? `<span class="text-bold">${header}</span>` : header}</div>
                    <div class="margin-spaced-text">${text}</div>
                </div>`;

    }

    addOrHideComponent(html: string | undefined): string {
        let classHeader = "margin-left vertical-margin";
        if (html === "" || html === undefined) {
            classHeader = "hidden";
        }
        return `<div class='${classHeader}'>
                    ${html}
                </div>`;
    }

    getSeverityIconId(severity: Severity): string {
        switch (severity) {
            case Severity.LOW:
                return "low-icon";
            case Severity.MEDIUM:
                return "medium-icon";
            case Severity.HIGH:
                return "high-icon";
            case Severity.CRITICAL:
                return "critical-icon";
            case Severity.AUDIT:
                return "audit-icon";
            case Severity.INFO:
                return "info-icon";
            case Severity.UNSPECIFIED:
                return "unspecified-icon";
        }
        return "";
    }
}

export abstract class IssueDetailsProviderBaseImpl extends IssueDetailsProviderBase {

    abstract getTitleHtml(): string;
    abstract getBodyHtml(showAIInsights: boolean): string;
    abstract getTabTitle(): string | undefined;
    abstract getScript(): string;
    abstract getIssueDetailsStyle(): string;
    horizontalRow = `<hr class="hr-style" style="margin-top:15px;">`;


    initNoIssueSelectedHtml(): void {
        let text = localize("issue.details.view.no.issue.selected", "Select an issue to view details here");
        let textTabTitle = localize("issue.details.view.no.issue.selected.title", "Issue Details: No issue selected");
        let html = `<html>
                        <head>
                            ${this.head}
                        </head>       
                        <style>
                            ${this.style}
                        </style>
                        <body>
                            <div class="no-issue-selected-text text-bold">${text}</div>
                        </body>
                    </html>`;

        this.webviewPanel!.title = textTabTitle;
        this.updateWebviewHtml(this.webviewPanel!.webview, html);
    }

    initIssueDetails(showAIInsights: boolean = false): void {
        let html = `<html>
                        <head>
                            ${this.head}
                        </head>
                        <style>
                            ${this.style}
                        </style>
                        <body>
                            <script>
                                const vscode = acquireVsCodeApi();
                                ${this.getScript()}
                            </script>
                            <div>
                                ${this.getTitleHtml()}
                            </div>
                            ${this.getBodyHtml(showAIInsights)}
                        </body>
                    </html>`;

        let tabTitle = this.getTabTitle();
        this.webviewPanel!.title = tabTitle ?
            `${localize('webview.issue.details.partial.title', 'Issue Details')}: ${tabTitle}` :
            localize('webview.issue.details.title', 'Code Sight Issue Details');
        this.updateWebviewHtml(this.webviewPanel!.webview, html);
    }

    //fast updates to the webview can cause the results to not be rendered, we will debounce only the latest request 
    //to the webview will be rendered in a 100ms period, this might result in the loading screen being skipped for local issues
    protected updateWebviewHtml = debounce((webview: Webview, html: string) => {
            webview.html = html;
    }, 100);

    protected getHead(webview: Webview): string {
        return webviewUtils.getWebviewHead("Issue Details", webview);
    }

    protected getStyle(): string {
        return /*css*/`
            body {
                min-width: 300px;
            }

            .indented-text {
                padding-left: 1rem;
            }

            .center-flex {
                display: flex;
                align-items: center;
                flex-direction: row;
            }

            .button-img {
                cursor: pointer;
            }

            .margin-left{
                margin-left: 3px;
            }

            .margin-left-10 {
                margin-left: 10px;
            }

            .vertical-margin {
                margin-top: 15px;
                margin-bottom: 15px;
            }

            .vertical-less-margin {
                margin-top: 5px;
                margin-bottom: 5px;
            }

            .hr-style {
                border: 1px solid var(--vscode-editorRuler-foreground);
            }

            .occurrence-style {
                margin-top: 5px;
                margin-bottom: 5px;
            }

            .severity-icon {
                max-width: 20px;
                min-width: 20px;
                margin-right: 8px;
            }

            .label-toggle {
                display: flex;
                align-items: center;
            }

            .label-toggle::after {
                margin-left: auto;
            }

            .issue-selected-icon, .issue-selected-dismissed-icon, .event-icon , .event-dismissed-icon{
                margin-right: 7px;
            }

            .occurrence-count {
                display: flex;
                align-items: center;
                flex: 1;
            }

            .title-section {
                display: flex;
                justify-content: space-between;
                align-items: start;
            }

            .fix-it-button-text {
                margin: 0 auto;
                padding-left: 5px;
                padding-right: 5px;
            }

            .back-button-div {
                display: flex;
                margin-right: 4px;
                margin-top: 3px;
            }

            .copy-to-clipboard-icon {
                border: none;
                background-color: transparent;
                padding: 7px !important;
                min-width: unset !important;
                max-height: 5px !important;
            }

            .thumbs-up-icon, .thumbs-down-icon {
                border: none;
                background-color: transparent;
                padding: 5px !important;
                min-width: unset !important;
                max-height: 15px !important;
            }

            .margin-spaced-text{
                margin-top: 5px;
                margin-bottom: 5px;
                margin-left: 10px;
                overflow-wrap: anywhere;
            }

            .hidden {
                display: none
            }

            .issue-label-overflow-ellipsis{
                overflow:hidden;
                text-overflow:ellipsis;
                white-space:nowrap;
                max-width:150px;
            }

            .dropdown {
                background-color: var(--vscode-settings-dropdownBackground);
                color: var(--vscode-settings-dropdownForeground);
                border-color: var(--vscode-settings-dropdownBorder);
            }
            
            ${webviewUtils.HOVER_STYLING}

            ${webviewUtils.BUTTON_STYLING}
            
            ${this.getIssueDetailsStyle()}
            `;
    }

    protected supportsCollapsibleSections(): boolean {
        return true;
    }

    dispose(): Promise<void> {
        return this.webviewPanel?.dispose();
    }
}
