import { ToolTypeEnum } from "./toolStateService";

/**
 * Service to control interaction with then VSCode context
 * This will allow us to control access to the `context`, and easily mock context
 * calls in tests
 */
export abstract class VscodeContextService {
    static readonly id: ServiceId<VscodeContextService> = { id: VscodeContextService.name };

    /**
     * Get the path of an icon resource
     * @param iconName The file name of the icon
     * @param iconSubDir The subdirectory within the icons dir of the icon. If omitted, the icon is assumed to be at the root level
     */
    abstract getIconPath(iconName: string, ...iconSubDir: string[]): string;

    /**
     * Get the path of an icon resource as a URI
     * @param iconName The file name of the icon
     * @param iconSubDir The subdirectory within the icons dir of the icon. If omitted, the icon is assumed to be at the root level
     */
    abstract getIconPathUri(iconName: string, ...iconSubDir: string[]): Uri;

    /**
     * Get the version number of the last persistent storage migration
     */
    abstract getPreservedPersistentStorageMigration(): number | undefined;

    /**
     * Set the version number of the last persistent storage migration
     * @param version number
     */
    abstract preservePersistentStorageMigration(v: number): void;

    /**
     * @param serverType Team View server type
     * Get the preserved Team view filter state by server type
     */
    abstract getPreservedTeamViewFilterState(serverType: ServerType): TeamViewFilterState | undefined;

    /**
     * @param filterState Filter state to preserve
     * @param serverType Team View server type
     */
    abstract preserveTeamViewFilterState(filterState: TeamViewFilterState, serverType: ServerType): Promise<void>;

    /**
     * @param filterState Filter state to preserve
     * @param scanType Local View scan type (if Project mode)
     */
    abstract preserveLocalViewFilterState(filterState: LocalViewFilterState, scanType?: ScanConfig.ScanType.Type): Promise<void>;

    /**
     * @param scanType Local View scan type (if Project mode)
     * Get the preserved Local View filter state
     */
    abstract getPreservedLocalViewFilterState(scanType?: ScanConfig.ScanType.Type): LocalViewFilterState | undefined;

    /**
     * @returns the location of the extension installation.
     */
    abstract getExtensionPath(): string;

    /**
     * Preserves the installed Code Sight version.
     * @param version the version to preserve
     */
    abstract preserveCodeSightVersion(version: string): void;

    /**
     * @returns The preserved Code Sight version or an empty string if it does not exist.
     */
    abstract getPreservedCodeSightVersion(): string;

    /**
     * @returns The preserved show empty workspace message state.
     */
    abstract getPreservedEmptyWorkspaceMessageEnabled(): boolean;

    /**
     * Preserves the show empty workspace message state.
     * @param showMessageState if the message should be shown.
     */
    abstract preserveEmptyWorkspaceMessageEnabled(showMessageState: boolean): void;

    /**
     * @returns The preserved file outside workspace message state.
     */
    abstract getPreservedFileOutsideWorkspaceMessageEnabled(): boolean;

    /**
     * Preserves the show file outside workspace message state.
     * @param showMessageState if the message should be shown.
     */
    abstract preserveFileOutsideWorkspaceMessageEnabled(showMessageState: boolean): void;

    /**
     * @returns this preserved state indicating if the given @param tool was skipped previously
     */
    abstract getPreservedToolInstallSkipped(tool: ToolTypeEnum) : boolean;
    
    /**
     * Preserves that the state of whether the given tool has been skipped during onboarding
     * @param tool 
     * @param state 
     */
    abstract preserveToolInstallSkipped(tool: ToolTypeEnum, state: boolean) : void;

    /**
     * @returns preserved state of scan mode (manual vs auto) for Local View
     */
    abstract getPreservedScanMode() : ScanMode | undefined;
    
     /**
      * Preserves the state of scan mode
      */
    abstract preserveScanMode(mode: ScanMode) : Promise<void>;

    /**
     * @returns preserved state of marker view (Local vs Team) for editor markers
     */
    abstract getPreservedMarkerView(): MarkerView | undefined;

    /**
     * Preserves the state of marker view
     */
    abstract preserveMarkerView(view: MarkerView): void;

    /**
     * @returns preserved state of AI mode (enabled vs disabled) for Signal view
     */
    abstract getPreservedAIMode(): boolean | undefined;

    /**
     * Preserves the state of AI mode
     */
    abstract preserveAIMode(enabled: boolean): Promise<void>;

    /**
     * @returns the preserved last export directory path, or undefined if not set
     */
    abstract getPreservedExportDirectory(): string | undefined;

    /**
     * Preserves the last export directory path
     * @param path the directory path where files were last exported
     */
    abstract preserveExportDirectory(path: string): Promise<void>;

    /**
     * @returns the preserved "warn before cancelling project scan to switch to incremental mode" message state.
     */
    abstract getPreservedWarnBeforeAutoModeCancelsManualScanMessageEnabled() : boolean;

    /**
     * Preserves the "warn before cancelling project scan to switch to incremental mode" message state.
     * @param state if the message should be shown
     */
    abstract preserveWarnBeforeAutoModeCancelsManualScanMessageEnabled(state: boolean) : void;

    /**
     * Preserve the license analysis enablement state
     */
    abstract preserveLicenseAnalysisEnabled(enabled: boolean, enabledOnOpen?: boolean, enabledOnSave?: boolean): void;

    /**
     * Get the preserved license analysis enablement state
     */
    abstract getPreservedLicenseAnalysisEnabled(): LicenseAnalysisEnabledState;

    /**
     * Get the preserved file scope for Signal scans
     */
    abstract getPreservedScanFileScope(): RefreshResultsRequest.Tier | undefined;

    /**
     * Preserve Signal's current file scope for scans
     */
    abstract preserveScanFileScope(fileScope: RefreshResultsRequest.Tier): Promise<void>;

    /*
     * Preserve Signal last scan time
     */
    abstract preserveSignalLastScanTime(lastScanTime: Date): Promise<void>;

    /**
     * Get the preserved Signal last scan time
     */
    abstract getPreservedSignalLastScanTime(): Date | undefined;

    /**
     * Preserve the reference branch configuration for Signal scans.
     * The branch name is always preserved regardless of the toggle state.
     */
    abstract preserveReferenceBranchConfig(isEnabled: boolean): Promise<void>;

    /**
     * Get the preserved reference branch configuration for Signal scans
     */
    abstract getPreservedReferenceBranchConfig(): boolean;

    /**
     * @returns whether AI mode has ever been enabled by the user for this project
     */
    abstract getPreservedAIEverEnabled(): boolean;

    /**
     * Marks that AI mode has been enabled at least once for this project
     */
    abstract preserveAIEverEnabled(): Promise<void>;

}

class Preserved<T> {
    private readonly key: string;
    private memento: Memento;
    private value: T;

    constructor(init: T, key: string, memento: Memento) {
        this.memento = memento;
        this.key = key;
        this.value = init;
        let preserved = this.memento.get<T>(this.key);

        if (preserved !== undefined) {
            this.value = preserved;
        }
    }

    get(): T {
        return this.value;
    }

    preserve(v: T) {
        this.value = v;
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        this.memento.update(this.key, v);
    }
}

export class VscodeContextServiceImpl extends VscodeContextService {
    private static readonly PERSISTENT_STORAGE_MIGRATION_VERSION = "codesight-persistent-storage-migration-version";
    private static readonly LOCAL_VIEW_AUTO_MODE_FILTER_STATE_STORAGE_KEY = "codesight-my-view-filter-state-auto-mode";
    private static readonly LOCAL_VIEW_MANUAL_MODE_FILTER_STATE_STORAGE_KEY = "codesight-my-view-filter-state-manual-mode";
    private static readonly TEAM_VIEW_FILTER_STATE_STORAGE_KEY = "codesight-remote-filter-state";
    private static readonly EXTENSION_VERSION_STORAGE_KEY = "codesight-installed-version";
    private static readonly SCAN_MODE_STORAGE_KEY = "codesight-scan-mode";
    private static readonly MARKER_VIEW_STORAGE_KEY = "codesight-marker-view";
    private static readonly AI_MODE_STORAGE_KEY = "codesight-ai-mode";
    private static readonly EXPORT_DIRECTORY_STORAGE_KEY = "codesight-last-export-directory";
    private static readonly LICENSE_ANALYSIS_ENABLED = "codesight-license-analysis-enabled";
    private static readonly SCAN_FILE_SCOPE_STORAGE_KEY = "codesight-signal-scan-file-scope";
    private static readonly SIGNAL_ENABLED_STORAGE_KEY = "codesight-signal-enabled";
    private static readonly SIGNAL_LAST_SCAN_TIME_STORAGE_KEY = "codesight-signal-last-scan-time";
    private static readonly REFERENCE_BRANCH_CONFIG_STORAGE_KEY = "codesight-signal-reference-branch-config";
    private static readonly AI_EVER_ENABLED_STORAGE_KEY = "codesight-signal-ai-ever-enabled";

    
    private storedCodeSightVersion: string | undefined;
    private emptyWorkspaceMessageEnabled: Preserved<boolean>;
    private fileOutsideWorkspaceMessageEnabled: Preserved<boolean>;
    private warnBeforeAutoModeCancelsManualScanMessageEnabled: Preserved<boolean>;

    private coverityInstallSkipped: Preserved<boolean>;
    private sigmaInstallSkipped: Preserved<boolean>;
    private bdInstallSkipped: Preserved<boolean>;

    context: ExtensionContext;
    constructor(context: ExtensionContext) {
        super();
        this.context = context;

        this.emptyWorkspaceMessageEnabled = new Preserved(true, "codesight-show-empty-workspace-message", context.globalState);
        this.fileOutsideWorkspaceMessageEnabled = new Preserved(true, "codesight-show-file-outside-workspace-message", context.workspaceState);
        this.warnBeforeAutoModeCancelsManualScanMessageEnabled = new Preserved(true, "codesight-show-warn-auto-mode-cancels-manual-scan-message", context.globalState);

        this.coverityInstallSkipped = new Preserved(false, "codesight-coverity-install-skipped", context.globalState);
        this.sigmaInstallSkipped = new Preserved(false, "codesight-sigma-install-skipped", context.globalState);
        this.bdInstallSkipped = new Preserved(false, "codesight-bd-install-skipped", context.globalState);
    }

    getIconPath(iconName: string, ...iconSubDir: string[]): string {
        return this.context.asAbsolutePath(join("resources", "icons", ...iconSubDir, iconName));
    }

    getIconPathUri(iconName: string, ...iconSubDir: string[]): Uri {
        return Uri.file(this.getIconPath(iconName, ...iconSubDir));
    }

    getPreservedPersistentStorageMigration(): number | undefined {
        return this.context.globalState.get<number>(VscodeContextServiceImpl.PERSISTENT_STORAGE_MIGRATION_VERSION);
    }

    preservePersistentStorageMigration(v: number) {
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        this.context.globalState.update(VscodeContextServiceImpl.PERSISTENT_STORAGE_MIGRATION_VERSION, v);
    }

    getLocalViewStateKey(scanMode: ScanMode, scanType?: ScanConfig.ScanType.Type): string | undefined {
        let key: string | undefined;
        if (scanMode === ScanMode.Auto) {
            key = VscodeContextServiceImpl.LOCAL_VIEW_AUTO_MODE_FILTER_STATE_STORAGE_KEY;
        } else if (scanMode === ScanMode.Manual) {
            key = `${VscodeContextServiceImpl.LOCAL_VIEW_MANUAL_MODE_FILTER_STATE_STORAGE_KEY}-${scanType}`;
        } else {
            getLogger().warn(`Local View results filter key was empty`); // should not happen
        }

        return key;
    }

    async preserveLocalViewFilterState(filterState: LocalViewFilterState, scanType?: ScanConfig.ScanType.Type) {
        const scanStatusCoordinator = getService(ScanStatusCoordinator.id);
        const scanMode = scanStatusCoordinator.getCurrentScanMode();
        let key = this.getLocalViewStateKey(scanMode, scanType);
        if (!key) {
            return;
        }
        return this.context.workspaceState.update(key, filterState);
    }

    getPreservedLocalViewFilterState(scanType?: ScanConfig.ScanType.Type): LocalViewFilterState | undefined {
        const scanStatusCoordinator = getService(ScanStatusCoordinator.id);
        const scanMode = scanStatusCoordinator.getCurrentScanMode();
        let key = this.getLocalViewStateKey(scanMode, scanType);
        if (!key) {
            return;
        }
        let storedValue = this.context.workspaceState.get<LocalViewFilterState>(key);
        if (!storedValue) {
            return undefined;
        }
        let sort;
        if (storedValue.sort) {
            let columnInfo = new ColumnInfo();
            columnInfo.setId(storedValue.sort.id);
            columnInfo.setName(storedValue.sort.sortName);
            sort =  new NewIssueSortState(columnInfo, storedValue.sort.isAscending);
        }

        let diffSourceFilter;
        if (storedValue.issueDiffSourceFilter) {
            diffSourceFilter = <IssueDiffValue> storedValue.issueDiffSourceFilter;
        }

        return {
            sort: sort,
            issueDiffSourceFilter: diffSourceFilter ?? IssueDiffValue.ALL,
            activeFileFilter: storedValue.activeFileFilter ?? false,
        };
    }

    async preserveTeamViewFilterState(filterState: TeamViewFilterState, serverType: ServerType) {
        let key = `${VscodeContextServiceImpl.TEAM_VIEW_FILTER_STATE_STORAGE_KEY}-${serverType}`;
        return await this.context.workspaceState.update(key, filterState);
    }
    
    getPreservedTeamViewFilterState(serverType: ServerType): TeamViewFilterState | undefined {
        let key = `${VscodeContextServiceImpl.TEAM_VIEW_FILTER_STATE_STORAGE_KEY}-${serverType}`;
        let storedValue = this.context.workspaceState.get<TeamViewFilterState>(key);
        if (!storedValue) {
            return undefined;
        }

        let sort;
        if (storedValue.sort) {
            let columnInfo = new ColumnInfo();
            columnInfo.setId(storedValue.sort.id);
            columnInfo.setName(storedValue.sort.sortName);
            sort =  new NewIssueSortState(columnInfo, storedValue.sort.isAscending);
        }

        return {
            sort: sort,
            activeFileFilter: storedValue.activeFileFilter ?? false,
        };
    }

    getPreservedScanMode(): ScanMode | undefined {
        let scanMode = this.context.workspaceState.get<ScanMode>(VscodeContextServiceImpl.SCAN_MODE_STORAGE_KEY);
        /*  with the removal of ScanMode.Remote we must confirm
            the currently preserved scan mode is valid */
        if (ScanMode.Auto === scanMode || ScanMode.Manual === scanMode) {
            return scanMode;
        } 
        return undefined;
    }

    async preserveScanMode(mode: ScanMode): Promise<void> {
        await this.context.workspaceState.update(VscodeContextServiceImpl.SCAN_MODE_STORAGE_KEY, mode);
    }

    getPreservedMarkerView(): MarkerView | undefined {
        let markerView = this.context.workspaceState.get<MarkerView>(VscodeContextServiceImpl.MARKER_VIEW_STORAGE_KEY);
        return markerView;
    }

    preserveMarkerView(view: MarkerView): void {
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        this.context.workspaceState.update(VscodeContextServiceImpl.MARKER_VIEW_STORAGE_KEY, view);
    }

    getPreservedAIMode(): boolean | undefined {
        return this.context.workspaceState.get<boolean>(VscodeContextServiceImpl.AI_MODE_STORAGE_KEY);
    }

    async preserveAIMode(enabled: boolean): Promise<void> {
        await this.context.workspaceState.update(VscodeContextServiceImpl.AI_MODE_STORAGE_KEY, enabled);
    }

    getPreservedExportDirectory(): string | undefined {
        return this.context.globalState.get<string>(VscodeContextServiceImpl.EXPORT_DIRECTORY_STORAGE_KEY);
    }

    async preserveExportDirectory(path: string): Promise<void> {
        await this.context.globalState.update(VscodeContextServiceImpl.EXPORT_DIRECTORY_STORAGE_KEY, path);
    }

    getExtensionPath(): string {
        return this.context.extensionPath;
    }

    preserveCodeSightVersion(version: string) {
        this.storedCodeSightVersion = version;
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        this.context.globalState.update(VscodeContextServiceImpl.EXTENSION_VERSION_STORAGE_KEY, version);
    }

    getPreservedCodeSightVersion(): string {
        if (this.storedCodeSightVersion !== undefined) {
            return this.storedCodeSightVersion;
        }

        let storedValue = this.context.globalState.get<string>(VscodeContextServiceImpl.EXTENSION_VERSION_STORAGE_KEY);

        if (!storedValue) {
            return "";
        }

        return storedValue;
    }

    getPreservedEmptyWorkspaceMessageEnabled(): boolean {
        return this.emptyWorkspaceMessageEnabled.get();
    }

    preserveEmptyWorkspaceMessageEnabled(showMessageState: boolean) {
        this.emptyWorkspaceMessageEnabled.preserve(showMessageState);
    }

    getPreservedFileOutsideWorkspaceMessageEnabled(): boolean {
        return this.fileOutsideWorkspaceMessageEnabled.get();
    }

    preserveFileOutsideWorkspaceMessageEnabled(showMessageState: boolean) {
        this.fileOutsideWorkspaceMessageEnabled.preserve(showMessageState);
    }

    getPreservedToolInstallSkipped(tool: ToolTypeEnum) : boolean {
        switch(tool){
            case ToolTypeEnum.Coverity:
                return this.coverityInstallSkipped.get();
            case ToolTypeEnum.Sigma:
                return this.sigmaInstallSkipped.get();
            case ToolTypeEnum.Blackduck:
                return this.bdInstallSkipped.get();
        }
    }

    preserveToolInstallSkipped(tool: ToolTypeEnum, state: boolean) {
        switch(tool){
            case ToolTypeEnum.Coverity:
                this.coverityInstallSkipped.preserve(state);
                break;
            case ToolTypeEnum.Sigma:
                this.sigmaInstallSkipped.preserve(state);
                break;
            case ToolTypeEnum.Blackduck:
                this.bdInstallSkipped.preserve(state);
                break;
        }
    }

    getPreservedWarnBeforeAutoModeCancelsManualScanMessageEnabled(): boolean {
        return this.warnBeforeAutoModeCancelsManualScanMessageEnabled.get();
    }

    preserveWarnBeforeAutoModeCancelsManualScanMessageEnabled(state: boolean): void {
        this.warnBeforeAutoModeCancelsManualScanMessageEnabled.preserve(state);
    }

    getPreservedLicenseAnalysisEnabled(): LicenseAnalysisEnabledState {
        return this.context.workspaceState.get<LicenseAnalysisEnabledState>(VscodeContextServiceImpl.LICENSE_ANALYSIS_ENABLED) ?? { isEnabled: false, isEnabledOnOpen: false, isEnabledOnSave: undefined }; // 'isEnabledOnSave: undefined' to be able to set it to true when license Analysis turned ON for the first time
    }

    preserveLicenseAnalysisEnabled(enabled: boolean, enabledOnOpen?: boolean, enabledOnSave?: boolean): void {
        if (!enabledOnOpen || !enabledOnSave) {
            let preservedState = this.getPreservedLicenseAnalysisEnabled();
            enabledOnOpen = (enabledOnOpen !== undefined) ? enabledOnOpen : preservedState.isEnabledOnOpen;
            enabledOnSave = (enabledOnSave !== undefined) ? enabledOnSave : preservedState.isEnabledOnSave;
        }
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        this.context.workspaceState.update(VscodeContextServiceImpl.LICENSE_ANALYSIS_ENABLED, {
            isEnabled: enabled,
            isEnabledOnOpen: enabledOnOpen,
            isEnabledOnSave: (enabledOnSave !== undefined) ? enabledOnSave : enabled
        });
    }

    getPreservedScanFileScope(): RefreshResultsRequest.Tier | undefined {
        let scanFileScope = this.context.workspaceState.get<RefreshResultsRequest.Tier>(VscodeContextServiceImpl.SCAN_FILE_SCOPE_STORAGE_KEY);
        return scanFileScope;
    }

    async preserveScanFileScope(fileScope: RefreshResultsRequest.Tier): Promise<void> {
        await this.context.workspaceState.update(VscodeContextServiceImpl.SCAN_FILE_SCOPE_STORAGE_KEY, fileScope);
    }
    async preserveSignalLastScanTime(lastScanTime: Date): Promise<void> {
        await this.context.workspaceState.update(VscodeContextServiceImpl.SIGNAL_LAST_SCAN_TIME_STORAGE_KEY, lastScanTime.toISOString());
    }

    getPreservedSignalLastScanTime(): Date | undefined {
        const stored = this.context.workspaceState.get<string>(VscodeContextServiceImpl.SIGNAL_LAST_SCAN_TIME_STORAGE_KEY);
        return stored ? new Date(stored) : undefined;
    }

    async preserveReferenceBranchConfig(isEnabled: boolean): Promise<void> {
        await this.context.workspaceState.update(VscodeContextServiceImpl.REFERENCE_BRANCH_CONFIG_STORAGE_KEY, isEnabled);
    }

    getPreservedReferenceBranchConfig(): boolean {
        return this.context.workspaceState.get(VscodeContextServiceImpl.REFERENCE_BRANCH_CONFIG_STORAGE_KEY)
            ?? false;
    }

    getPreservedAIEverEnabled(): boolean {
        return this.context.workspaceState.get<boolean>(VscodeContextServiceImpl.AI_EVER_ENABLED_STORAGE_KEY) ?? false;
    }

    async preserveAIEverEnabled(): Promise<void> {
        await this.context.workspaceState.update(VscodeContextServiceImpl.AI_EVER_ENABLED_STORAGE_KEY, true);
    }

}
