import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { Disposable, WebviewPanel } from "vscode";
import { CsseLicenseInfo } from "../../models/csseLicenseInfo";
import { EntitlementService, EntitlementServiceListener } from "../../services/entitlementService";
import { WarningMessageService } from "../../services/extensionMessageService";
import { ExtensionService } from "../../services/extensionService";
import { getService } from "../../services/serviceContainer";
import { SetupService } from "../../services/setupService";
import { ToolStateService, ToolTypeEnum } from "../../services/toolStateService";
import { getLogger } from "../../utils/logger";
import { WebviewCoordinator } from "../webviewCoordinator";
import { WebviewPresenter } from "../webviewPresenter";
import { InstalledToolsMessageViewProvider, InstalledToolsViewCommandIds } from "./installedToolsMessageViewProvider";

export class InstalledToolsMessageViewPresenter implements WebviewPresenter, EntitlementServiceListener {
    private readonly panel: WebviewPanel;
    private view: InstalledToolsMessageViewProvider;
    private onMessageFromWebviewDisposable: Disposable | undefined;
    private viewState: InstalledToolsMessageState | undefined;

    constructor(panel: WebviewPanel) {
        this.panel = panel;
        this.view = getService(InstalledToolsMessageViewProvider.id);
        this.view.initView(this.panel);
        getService(EntitlementService.id).addListener(this);

        this.onMessageFromWebviewDisposable = this.view.onMessageFromWebview(async message => {
            switch (message.command) {
                case InstalledToolsViewCommandIds.INSTALL_SIGMA:
                    await getService(SetupService.id).installOrUpdateTool(ToolTypeEnum.Sigma);
                    break;
                case InstalledToolsViewCommandIds.UPDATE_SIGMA:
                    await getService(WebviewCoordinator.id).showUpdateAvailableMessage(ToolTypeEnum.Sigma);
                    break;
                case InstalledToolsViewCommandIds.INSTALL_COVERITY:
                    await getService(SetupService.id).installOrUpdateTool(ToolTypeEnum.Coverity);
                    break;
                case InstalledToolsViewCommandIds.UPDATE_COVERITY:
                    await getService(WebviewCoordinator.id).showUpdateAvailableMessage(ToolTypeEnum.Coverity);
                    break;
                case InstalledToolsViewCommandIds.INSTALL_BLACKDUCK:
                    await getService(SetupService.id).installOrUpdateTool(ToolTypeEnum.Blackduck);
                    break;
                case InstalledToolsViewCommandIds.UPDATE_BLACKDUCK:
                    await getService(WebviewCoordinator.id).showUpdateAvailableMessage(ToolTypeEnum.Blackduck);
                    break;
                case InstalledToolsViewCommandIds.ENABLE_CSSE_PRODUCT:
                    await getService(WebviewCoordinator.id).showRegistrationForm(true);
                    break;
                case InstalledToolsViewCommandIds.ENABLE_COVERITY_PRODUCT:
                    await getService(SetupService.id).beginCoverityUserFlow();
                    break;
                case InstalledToolsViewCommandIds.ENABLE_POLARIS_PRODUCT:
                    await getService(SetupService.id).beginPolarisUserFlow();
                    break;
                case InstalledToolsViewCommandIds.ENABLE_SRM_PRODUCT:
                    await getService(SetupService.id).beginSRMUserFlow();
                    break;
                case InstalledToolsViewCommandIds.ENABLE_BLACKDUCK_PRODUCT:
                    await getService(SetupService.id).beginBlackDuckUserFlow();
                    break;
                case InstalledToolsViewCommandIds.ENABLE_SIGNAL_PRODUCT:
                case InstalledToolsViewCommandIds.UPDATE_SIGNAL_KEY:
                    await getService(WebviewCoordinator.id).showSignalAuthView();
                    break;
                case InstalledToolsViewCommandIds.ADD_LICENSE_BUTTON:
                    await getService(WebviewCoordinator.id).showLicenseView(true, false);
                    break;
                case InstalledToolsViewCommandIds.ADD_PAID_LICENSE_LINK:
                    await getService(WebviewCoordinator.id).showLicenseView(true, true);
                    break;
                case InstalledToolsViewCommandIds.VERIFY_EMAIL:
                    await getService(WebviewCoordinator.id).showEmailVerificationMessage(true);
                    break;
                case InstalledToolsViewCommandIds.REFRESH_LICENSE_STATUS:
                    await this.refreshLicenseStatus();
                    break;
                case InstalledToolsViewCommandIds.LICENSE_ERROR_MESSAGE:
                    await getService(WarningMessageService.id).getLicenseErrorMessage(this.viewState?.csseLicenseInfo.getState());
                    break;
                case 'specify-location':
                    await getService(WebviewCoordinator.id).showSigmaInstallLocationView(false);
                    break;
                default:
                    getLogger().warn(`Received unexpected message ${message.command}`);
                    break;
            }

            return Promise.resolve();
        });
    }

    public async parseNotification(message: NotificationMessage) {
    }

    public async initView() {
        this.view.addloadingScreen();
        const toolStateService = getService(ToolStateService.id);
        await toolStateService.refreshToolsFromController(false);

        let entitlementService = getService(EntitlementService.id);
        await entitlementService.checkEntitlements();
        let entitlements = entitlementService.getCachedProductEntitlement();

        let hasCoverityEntitlement = entitlements.isCoverityEntitled();
        let hasBlackduckEntitlement = entitlements.isBlackDuckEntitled();
        let hasPolarisEntitlement = entitlements.isPolarisEntitled();
        let hasSignalEntitlement = entitlements.isSignalEntitled();
        let hasSRMEntitlement = entitlements.isSRMEntitled();

        const state: InstalledToolsMessageState = {
            codeSightVersion: getService(ExtensionService.id).getCodeSightVersion(),
            sigmaInstalled: toolStateService.isSigmaInstalled(),
            sigmaVersion: toolStateService.getVersionForTool(ToolTypeEnum.Sigma),
            sigmaUpdateAvailable: toolStateService.isUpdateAvailable(ToolTypeEnum.Sigma),
            coverityInstalled: toolStateService.isCoverityInstalled(),
            coverityVersion: toolStateService.getVersionForTool(ToolTypeEnum.Coverity),
            coverityUpdateAvailable: toolStateService.isUpdateAvailable(ToolTypeEnum.Coverity),
            blackduckInstalled: toolStateService.isBlackduckInstalled(),
            blackduckVersion: toolStateService.getVersionForTool(ToolTypeEnum.Blackduck),
            blackduckUpdateAvailable: toolStateService.isUpdateAvailable(ToolTypeEnum.Blackduck),
            hasCsseLicense: entitlements.hasCsseLicense(),
            csseLicenseInfo: entitlements.getCsseLicense(),
            isCsseLicenseInactive: hasCoverityEntitlement && hasBlackduckEntitlement,
            hasCoverityEntitlement: hasCoverityEntitlement,
            hasPolarisEntitlement: hasPolarisEntitlement,
            hasSRMEntitlement: hasSRMEntitlement,
            hasBlackduckEntitlement: hasBlackduckEntitlement,
            hasSignalEntitlement: hasSignalEntitlement
        };

        this.viewState = state;
        await this.showView(true);
    }

    private async showView(shouldRefreshUpdateStatus?: boolean) {
        if (!this.viewState) {
            // should not ever happen
            getLogger().warn(`showView called with no state set..`);
            return;
        }

        this.view.initHtml(this.viewState);

        const toolStateService = getService(ToolStateService.id);

        if (shouldRefreshUpdateStatus) {
            await toolStateService.refreshToolsFromController(true);
        }

        this.view.postMessageToWebview({
            command: InstalledToolsViewCommandIds.REFRESH_UPDATE_STATE_COVERITY,
            value: String(toolStateService.isUpdateAvailable(ToolTypeEnum.Coverity)),
        });
        this.view.postMessageToWebview({
            command: InstalledToolsViewCommandIds.REFRESH_UPDATE_STATE_SIGMA,
            value: String(toolStateService.isUpdateAvailable(ToolTypeEnum.Sigma)),
        });
        this.view.postMessageToWebview({
            command: InstalledToolsViewCommandIds.REFRESH_UPDATE_STATE_BLACKDUCK,
            value: String(toolStateService.isUpdateAvailable(ToolTypeEnum.Blackduck)),
        });
    }

    private async refreshLicenseStatus() {
        if (!this.viewState) {
            // should not ever happen
            getLogger().warn(`refreshLicenseStatus called with no state set..`);
            return;
        }

        // set loading text and disable the button
        this.view.postMessageToWebview({
            command: InstalledToolsViewCommandIds.UPDATE_LICENSE_STATUS,
            loading: "true"
        });

        let entitlementService = getService(EntitlementService.id);
        await entitlementService.checkEntitlements();
        let entitlements = entitlementService.getCachedProductEntitlement();

        this.viewState.hasCsseLicense = entitlements.hasCsseLicense();
        this.viewState.csseLicenseInfo = entitlements.getCsseLicense();

        await this.showView();

        this.view.postMessageToWebview({
            command: InstalledToolsViewCommandIds.UPDATE_LICENSE_STATUS,
            loading: "false"
        });
    }

    async onEntitlementsChanged(): Promise<void> {
        if (!this.viewState) {
            return;
        }

        const entitlements = getService(EntitlementService.id).getCachedProductEntitlement();
        this.viewState.hasCsseLicense = entitlements.hasCsseLicense();
        this.viewState.csseLicenseInfo = entitlements.getCsseLicense();

        await this.showView();
    }

    public dispose() {
        this.onMessageFromWebviewDisposable?.dispose();
        getService(EntitlementService.id).removeListener(this);
    }
}

export interface InstalledToolsMessageState {
    codeSightVersion: string;
    sigmaInstalled: boolean;
    sigmaVersion: string;
    sigmaUpdateAvailable: boolean;
    coverityInstalled: boolean;
    coverityVersion: string;
    coverityUpdateAvailable: boolean;
    blackduckInstalled: boolean;
    blackduckVersion: string;
    blackduckUpdateAvailable: boolean;
    hasCsseLicense: boolean;
    csseLicenseInfo: CsseLicenseInfo;
    isCsseLicenseInactive: boolean;
    hasCoverityEntitlement: boolean;
    hasPolarisEntitlement: boolean;
    hasSRMEntitlement: boolean;
    hasBlackduckEntitlement: boolean;
    hasSignalEntitlement: boolean;
}
