import { EchoRequest, EchoResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/control_service_pb";
import { connectivityState } from "@grpc/grpc-js";
import * as fs from "fs";
import { isWindows } from "../utils/environmentUtils";
import { getLogger } from "../utils/logger";
import { AnalysisServiceClientImpl } from "./analysisServiceClient";
import { ConfigurationServiceClientImpl } from "./configurationServiceClient";
import { ControlServiceClientImpl } from "./controlServiceClient";
import { DiagnosticsServiceClientImpl } from "./diagnosticsServiceClient";
import { ExportScanResultsServiceClientImpl } from "./exportScanResultsServiceClient";
import { IssuesServiceClientImpl } from "./issuesServiceClient";
import { LicenseServiceClientImpl } from "./licenseServiceClient";
import { SigmaServiceClientImpl } from "./sigmaServiceClient";
import { TelemetryServiceClientImpl } from "./telemetryServiceClient";
import { ToolServiceClientImpl } from "./toolServiceClient";
import { UserServiceClientImpl } from "./userServiceClient";

interface ConfigFile {
    autoExitTimeout: string;
    lastConnectionAutoEx: string;
    connectionConfigurations: ConnectionConfiguration[];
}

interface ConnectionConfiguration {
    address: string;
    transportProtocol: string;
    applicationProtocol: string;
}

export class ControllerGrpcClient {
    private analysisServiceClientImpl: AnalysisServiceClientImpl;
    private controlServiceClientImpl: ControlServiceClientImpl;
    private toolServiceClientImpl: ToolServiceClientImpl;
    private telemetryServiceClientImpl: TelemetryServiceClientImpl;
    private configurationServiceClientImpl: ConfigurationServiceClientImpl;
    private issuesServiceClientImpl: IssuesServiceClientImpl;
    private diagnosticsServiceClientImpl: DiagnosticsServiceClientImpl;
    private sigmaServiceClientImpl: SigmaServiceClientImpl;
    private licenseServiceClientImpl: LicenseServiceClientImpl;
    private userServiceClientImpl: UserServiceClientImpl;
    private exportScanResultsServiceClientImpl: ExportScanResultsServiceClientImpl;

    constructor(outputConfig: string|undefined) {
        let connectionAddress = this.getConnectionAddress(outputConfig);

        this.analysisServiceClientImpl = new AnalysisServiceClientImpl(connectionAddress);
        this.controlServiceClientImpl = new ControlServiceClientImpl(connectionAddress);
        this.toolServiceClientImpl = new ToolServiceClientImpl(connectionAddress);
        this.telemetryServiceClientImpl = new TelemetryServiceClientImpl(connectionAddress);
        this.configurationServiceClientImpl = new ConfigurationServiceClientImpl(connectionAddress);
        this.issuesServiceClientImpl = new IssuesServiceClientImpl(connectionAddress);
        this.diagnosticsServiceClientImpl = new DiagnosticsServiceClientImpl(connectionAddress);
        this.sigmaServiceClientImpl = new SigmaServiceClientImpl(connectionAddress);
        this.licenseServiceClientImpl = new LicenseServiceClientImpl(connectionAddress);
        this.userServiceClientImpl = new UserServiceClientImpl(connectionAddress);
        this.exportScanResultsServiceClientImpl = new ExportScanResultsServiceClientImpl(connectionAddress);

        getLogger().info(`Controller client initialized with connection address ${connectionAddress}`);
    }

    getAnalysisServiceClientImpl(): AnalysisServiceClientImpl {
        return this.analysisServiceClientImpl;
    }

    getToolServiceClientImpl(): ToolServiceClientImpl {
        return this.toolServiceClientImpl;
    }

    getTelemetryServiceClientImpl(): TelemetryServiceClientImpl {
        return this.telemetryServiceClientImpl;
    }

    getConfigurationServiceClientImpl(): ConfigurationServiceClientImpl {
        return this.configurationServiceClientImpl;
    }

    getIssuesServiceClientImpl(): IssuesServiceClientImpl {
        return this.issuesServiceClientImpl;
    }

    getDiagnosticsServiceClientImpl(): DiagnosticsServiceClientImpl {
        return this.diagnosticsServiceClientImpl;
    }

    getSigmaServiceClientImpl(): SigmaServiceClientImpl {
        return this.sigmaServiceClientImpl;
    }

    getLicenseServiceClientImpl(): LicenseServiceClientImpl {
        return this.licenseServiceClientImpl;
    }

    getControlServiceClientImpl(): ControlServiceClientImpl {
        return this.controlServiceClientImpl;
    }

    getUserServiceClientImpl(): UserServiceClientImpl {
        return this.userServiceClientImpl;
    }

    getExportScanResultsServiceClientImpl(): ExportScanResultsServiceClientImpl {
        return this.exportScanResultsServiceClientImpl;
    }

    private getConnectionAddress(outputConfig: string|undefined) {
        if (outputConfig) {
            getLogger().info(`Controller config file found at ${outputConfig}`);
            // eslint-disable-next-line no-useless-catch
            try {
                let jsonString = fs.readFileSync(outputConfig, 'utf-8');
                const configFile: ConfigFile = JSON.parse(jsonString);
                const connectionConfigurations: ConnectionConfiguration[] = configFile.connectionConfigurations;

                for (let i = 0; i < connectionConfigurations.length; i++) {
                    if (connectionConfigurations[i].applicationProtocol === 'grpc') {
                        return connectionConfigurations[i].address;
                    }
                }
            } catch (err) {
                throw (err);
            }

            throw new Error("No grpc address exists for controller");
        }

        throw new Error("Controller configuration file does not exist");
    }

    async isValid(): Promise<void> {
        const logger = getLogger();

        switch (this.controlServiceClientImpl.getConnectivityState()) {
            case connectivityState.SHUTDOWN:
            case connectivityState.TRANSIENT_FAILURE:
                logger.debug(`Controller is not valid`);
                return Promise.reject();
            default:
                break;
        }

        let request = new EchoRequest();
        let date = new Date();
        request.setMessage(date.getTime().toString());

        // eslint-disable-next-line no-async-promise-executor
        let echoResponse = await new Promise<EchoResponse>(async (resolve, reject) => {
            const WINDOWS_TIMEOUT = 5000;
            const LONG_TIMEOUT = 50000;

            // There is a GRPC-JS issue on Windows where sending a request to an unresponsive/non-existent server never resolves
            // or rejects (i.e. it hangs forever). See UD-4112.
            // To work around this while we wait for a fix on the GRPC side, set a timeout on the Echo request, so that if we are
            // trying to connect with a non-existent controller, we don't hang the extension.
            // We use a longer / dummy timeout for non-windows machines as they will properly error out on their own and this timeout
            // can cause issues if there is a lot of processing happening on the controller side (that we would like to isolate to as
            // few platforms as possible).
            const initializationTimeout = isWindows() ? WINDOWS_TIMEOUT : LONG_TIMEOUT;
            const timeout = setTimeout(() => {
                logger.info(`Timed out pinging the controller with echo request. Controller is down.`);
                clearTimeout(timeout);
                reject(`The server did not respond to the echo request within ${initializationTimeout} milliseconds. Assume that it is down`);
            }, initializationTimeout);

            try {
                const response = await this.controlServiceClientImpl.echo(request);
                clearTimeout(timeout);
                resolve(response);
            }
            catch (error) {
                logger.info(`Sending echo request to controller failed with error ${error}`);
                clearTimeout(timeout);
                reject(error);
            }
        });

        return (echoResponse && request.getMessage() === echoResponse.getMessage())
            ? Promise.resolve()
            : Promise.reject("Echo response from controller did not match echo request sent by extension");
    }
}