import { Webview } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { ServiceId } from "../../services/serviceContainer";
import { BUTTON_STYLING, getWebviewHead } from "../../utils/webviewUtils";
import { WebviewProvider } from "../webviewProvider";
import * as exportLogsComponent from "./exportLogsViewComponent";



const localize: LocalizeFunc = loadMessageBundle();

export abstract class ExportLogsViewProvider extends WebviewProvider {
    static readonly id: ServiceId<ExportLogsViewProvider> = { id: ExportLogsViewProvider.name };

    abstract initHtml(): void;
}

export class ExportLogsViewProviderImpl extends ExportLogsViewProvider {
    constructor() {
        super();
    }

    public initHtml(): void {
        let html = `<html>
                    <head>
                        ${this.head}
                    </head>
                    <style>
                        ${this.style}
                    </style>
                    <body>
                        <div class='box'>
                            <img class='blackduck-icon float-left' width="35" height="35"/>
                            <h2 class='float-left margin-left'>Export Logs</h2>
                        </div>
                        <div>
                            <p>${localize('export.logs.view.description.line1', "If Customer Support is required, please click 'Export Logs' and then attach the zip file to any Support requests to help troubleshoot issues.")}</p>
                        </div>
                        ${exportLogsComponent.EXPORT_LOGS_BODY}
                        <script>
                            const vscode = acquireVsCodeApi();
                            window.onload = function() {
                                let buttons = document.querySelectorAll(".button");
            
                                buttons.forEach(function(button) {
                                    button.onclick = function() {
                                        
                                        vscode.postMessage({
                                            command: button.id
                                        });
            
                                        return false;
                                    }
                                });
                            }
                            ${exportLogsComponent.EXPORT_LOGS_SCRIPTS}
                        </script>
                    </body>
                    </html>
        `;

        this.webviewPanel!.webview.html = html;
    }

    protected getHead(webview: Webview): string {
        return getWebviewHead("Export Logs", webview);
    }

    protected getStyle(): string {
        return `
        #outer {
            width: 600px;
        }

        #inner {
            display: inline-block;
            margin: 0 auto;
            text-align: center;
        }

        ${exportLogsComponent.EXPORT_LOGS_STYLING}

        ${BUTTON_STYLING}
        `;
    }
}
