import { MarkdownString, QuickPickItem, QuickPickItemKind, ThemeColor, ThemeIcon, TreeItem, TreeItemCollapsibleState, TreeItemLabel, Uri } from "vscode";
import { LINK_RESOURCE_URI, LINK_THEME_COLOR, ThemeIconId } from "./constants";

export class ModeSelectQuickPickItem implements QuickPickItem {
    label: string;
    onSelectedCallback: () => Promise<void>;
    constructor(label: string, onSelected: () => Promise<void>) {
        this.label = label;
        this.onSelectedCallback = onSelected;
    }
}
export class FileScopeSelectQuickPickItem implements QuickPickItem {
    label: string;
    onSelectedCallback: () => Promise<void>;
    constructor(label: string, onSelected: () => Promise<void>) {
        this.label = label;
        this.onSelectedCallback = onSelected;
    }
}
export class SortQuickPickItem implements QuickPickItem {
    label: string;
    description: string;
    onSelectedCallback: () => Promise<void>;
    constructor(label: string, description: string, onSelected: () => Promise<void>) {
        this.label = label;
        this.description = description;
        this.onSelectedCallback = onSelected;
    }
}
export class LinkTreeItem extends TreeItem {
    constructor(label?: string | TreeItemLabel, collapsibleState?: TreeItemCollapsibleState) {
        super(label ?? "", collapsibleState);
        this.tooltip = new MarkdownString("");
        this.resourceUri = Uri.parse(`${LINK_RESOURCE_URI}:`);
        const editIconLinkColor = new ThemeColor(LINK_THEME_COLOR);
        const editIcon = new ThemeIcon(ThemeIconId.edit, editIconLinkColor);
        this.iconPath = editIcon;
    }
}

export class StandardQuickPickItem implements QuickPickItem {
    label: string;
    onSelectedCallback: () => Promise<void>;

    constructor(label: string, onSelected: () => Promise<void>) {
        this.label = label;
        this.onSelectedCallback = onSelected;
    }
}

export class SeparatorQuickPickItem implements QuickPickItem {
    label: string;
    kind: QuickPickItemKind;
    onSelectedCallback = () => Promise.resolve();

    constructor(label: string) {
        this.label = label;
        this.kind = QuickPickItemKind.Separator;
    }
}