import * as sigmaServiceGrpc from "@codesight/codesight-controller-proto/controller_proto/v1/sigma_reporting_service_grpc_pb";
import { GetLogRequest, GetLogResponse } from "@codesight/codesight-controller-proto/controller_proto/v1/sigma_reporting_service_pb";
import { credentials } from "@grpc/grpc-js";
import { getGrpcLimit } from '../utils/environmentUtils';
/**
 * Defines the interface points with the controller's `SigmaReportingService`
 */
export interface SigmaServiceClient {
    getLogFile(request: GetLogRequest): Promise<GetLogResponse>;
}

export class SigmaServiceClientImpl {
    private client: sigmaServiceGrpc.SigmaReportingServiceClient;

    constructor(connectionAddress: string) {
        this.client = new sigmaServiceGrpc.SigmaReportingServiceClient(connectionAddress, credentials.createInsecure(), {'grpc.max_receive_message_length': getGrpcLimit(), 'grpc.enable_http_proxy': 0});
    }

    async getLogFile(request: GetLogRequest): Promise<GetLogResponse> {
        return new Promise<GetLogResponse>((resolve, reject) => {
            this.client.getLogFile(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }
}