import { BuildToolConfig, ConfigId, ConfiguredSource, GitConfig, IssueSource, IssueSourceConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/config_pb";
import { StringValue, ValueSource } from "@codesight/codesight-controller-proto/controller_proto/v0/config_types_pb";
import { DeleteScanConfigRequest, DeleteScanConfigResponse, GetConfigurationRequest, GetConfigurationResponse, GetScanConfigListRequest, GetScanConfigListResponse, GetScanConfigRequest, GetScanConfigResponse, GetScanFormResponse, GetScanTypesRequest, GetScanTypesResponse, NewScanConfigRequest, ScanForm, SetSelectedScanConfigRequest, SetSelectedScanConfigResponse, StoreScanFormRequest, StoreScanFormResponse, TrustCertificateRequest, TrustCertificateResponse, UpdateConfigurationRequest, UpdateConfigurationResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/configuration_service_pb";
import { ScanConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/scan_config_pb";
import { ControllerClientService } from "../services/controllerClientService";
import { ServiceId, getService } from "../services/serviceContainer";
import { getLogger } from "../utils/logger";
import { AnalysisContextService } from "./analysisContextService";

export enum BuildToolConfigType {
    JAVA_HOME,
    MAVEN,
    NPM
}

export abstract class ConfigurationService {
    static readonly id: ServiceId<ConfigurationService> = { id: ConfigurationService.name };

    abstract getConfiguration(): Promise<GetConfigurationResponse>;

    abstract updateBuildToolConfiguration(configType: BuildToolConfigType, newConfigPath: string): Promise<UpdateConfigurationResponse | undefined>;

    abstract configureNewIssueSource(newSource: IssueSource): Promise<UpdateConfigurationResponse | undefined>;

    abstract updateActiveIssueSource(activeSourceID: string): Promise<UpdateConfigurationResponse | undefined>;

    abstract trustCertificate(cert: string, url: string, accept: boolean): Promise<TrustCertificateResponse | undefined>;

    abstract getScanTypes(): Promise<GetScanTypesResponse>;

    abstract newScanForm(scanType: ScanConfig.ScanType.Type): Promise<GetScanFormResponse>;

    abstract getScanForm(name: string): Promise<GetScanFormResponse>

    abstract storeScanForm(configId: ConfigId, scanType: ScanConfig.ScanType | undefined, groups: ScanForm.ConfigGroup[]): Promise<StoreScanFormResponse>;
    
    abstract getScanConfiguration(name: string): Promise<GetScanConfigResponse>;
    
    abstract getScanConfigurationList(): Promise<GetScanConfigListResponse>;

    abstract deleteScanConfiguration(configId: ConfigId): Promise<DeleteScanConfigResponse>;

    abstract setSelectedScanConfig(configId: ConfigId | undefined): Promise<SetSelectedScanConfigResponse>;

    abstract updateGitRepositoryPath(path: string): Promise<UpdateConfigurationResponse | undefined>;

    abstract updateReferenceBranchName(branchName: string): Promise<UpdateConfigurationResponse | undefined>;

    /**
     * Initializes the git repository path if not already set.
     * Sets it to the first workspace folder if the controller has no configured path.
     */
    abstract initGitRepositoryPath(workspaceFolderPaths: string[]): Promise<void>;

    /**
     * Returns the currently configured git repository path from the controller.
     * Returns undefined if no path has been set.
     */
    abstract getConfiguredGitRepositoryPath(): Promise<string | undefined>;
}

export class ConfigurationServiceImpl implements ConfigurationService {

    async getConfiguredGitRepositoryPath(): Promise<string | undefined> {
        const configResponse = await this.getConfiguration();
        return configResponse.getWorkspaceconfig()?.getGitconfig()?.getPathtogitrepository()?.getValue() || undefined;
    }

    async getConfiguration(): Promise<GetConfigurationResponse> {
        const configServiceClient = await getService(ControllerClientService.id).getConfigurationServiceClient();

        let request = new GetConfigurationRequest();
        let analysisContextService = getService(AnalysisContextService.id);
        request.setContextid(analysisContextService.getAnalysisContextId());

        return configServiceClient.getConfiguration(request);
    }

    async updateBuildToolConfiguration(configType: BuildToolConfigType, path: string): Promise<UpdateConfigurationResponse | undefined> {
        const logger = getLogger();
        const configService = await getService(ControllerClientService.id).getConfigurationServiceClient();
        let getConfigResponse = await this.getConfiguration();
        if (getConfigResponse.getError()) {
            logger.warn(`updateBuildToolConfiguration(): getConfigResponse returned an error=${getConfigResponse.getError()?.getMessage()}`);
            return;
        }

        let userConfig = getConfigResponse.getUserconfig();
        if (!userConfig) {
            logger.warn(`updateBuildToolConfiguration(): no user config received`);
            return;
        }

        let buildToolConfig = userConfig.getBuildtoolconfig();
        if (!buildToolConfig) {
            logger.warn(`updateBuildToolConfiguration(): no build tool config returned`);
            return;
        }

        // update build tool config
        let toolConfig = new BuildToolConfig.ToolConfig();
        let valueSource = new ValueSource();
        valueSource.setType(ValueSource.Type.CODE_SIGHT_USER);
        let stringValue = new StringValue();
        stringValue.setValue(path);
        stringValue.setSource(valueSource);
        toolConfig.setBinarylocation(stringValue);

        if (configType === BuildToolConfigType.JAVA_HOME) {
            buildToolConfig.setJava(toolConfig);
        } else if (configType === BuildToolConfigType.MAVEN) {
            buildToolConfig.setMaven(toolConfig);
        } else if (configType === BuildToolConfigType.NPM) {
            buildToolConfig.setNpm(toolConfig);
        }

        userConfig.setBuildtoolconfig(buildToolConfig);
        let request = new UpdateConfigurationRequest();
        request.setUserconfig(userConfig);

        return configService.updateConfiguration(request);
    }

    async configureNewIssueSource(newSource: IssueSource): Promise<UpdateConfigurationResponse | undefined> {
        const logger = getLogger();
        const configService = await getService(ControllerClientService.id).getConfigurationServiceClient();
        let getConfigResponse = await this.getConfiguration();
        if (getConfigResponse.getError()) {
            logger.warn(`updateIssueSourceConfiguration(): getConfigResponse returned an error=${getConfigResponse.getError()?.getMessage()}`);
            return;
        }

        let workspaceConfig = getConfigResponse.getWorkspaceconfig();
        if (!workspaceConfig) {
            logger.warn(`updateIssueSourceConfiguration(): no workspace config received`);
            return;
        }

        let issueSourceConfig = workspaceConfig.getIssuesourceconfig();
        if (!issueSourceConfig) {
            issueSourceConfig = new IssueSourceConfig();
        }

        let configuredSource = new ConfiguredSource();
        configuredSource.setSource(newSource);

        // replace configured source for the given server      
        let issueSourceList = issueSourceConfig.getConfiguredsourcesList();  
        let hasMatchingServer: boolean = false;
        for (let i=0; i < issueSourceList.length; i++) {
            if (issueSourceList[i].getSource()?.getServertype() === configuredSource.getSource()?.getServertype()) {
                issueSourceList[i] = configuredSource;
                hasMatchingServer = true;
            }
        }
        if (!hasMatchingServer) {
            issueSourceList.push(configuredSource);
        }

        issueSourceConfig.setConfiguredsourcesList(issueSourceList);
        workspaceConfig.setIssuesourceconfig(issueSourceConfig);
        
        let request = new UpdateConfigurationRequest();
        request.setWorkspaceconfig(workspaceConfig);
        return configService.updateConfiguration(request);
    }

    async updateActiveIssueSource(activeSourceID: string): Promise<UpdateConfigurationResponse | undefined> {
        const logger = getLogger();
        const configService = await getService(ControllerClientService.id).getConfigurationServiceClient();
        let getConfigResponse = await this.getConfiguration();
        if (getConfigResponse.getError()) {
            logger.warn(`updateIssueSourceConfiguration(): getConfigResponse returned an error=${getConfigResponse.getError()?.getMessage()}`);
            return;
        }

        let workspaceConfig = getConfigResponse.getWorkspaceconfig();
        if (!workspaceConfig) {
            logger.warn(`updateIssueSourceConfiguration(): no workspace config received`);
            return;
        }

        let issueSourceConfig = workspaceConfig.getIssuesourceconfig();
        if (!issueSourceConfig) {
            issueSourceConfig = new IssueSourceConfig();
        }

        let issueSourceList = issueSourceConfig.getConfiguredsourcesList();
        if (issueSourceList.length === 0) {
            return Promise.reject("No issue sources configured");
        }

        issueSourceConfig.setActivesourceid(activeSourceID);
        issueSourceConfig.setConfiguredsourcesList(issueSourceList);
        workspaceConfig.setIssuesourceconfig(issueSourceConfig);
        
        let request = new UpdateConfigurationRequest();
        request.setWorkspaceconfig(workspaceConfig);
        return configService.updateConfiguration(request);
    }

    async trustCertificate(cert: string, url: string, accept: boolean): Promise<TrustCertificateResponse | undefined> {
        const configService = await getService(ControllerClientService.id).getConfigurationServiceClient();
        
        let request = new TrustCertificateRequest();
        request.setTrust(accept);
        request.setCertificate(cert);
        request.setUrl(url);
        return configService.trustCertificate(request);
    }

    async newScanForm(scanType: ScanConfig.ScanType.Type): Promise<GetScanFormResponse> {
        const configClient = await getService(ControllerClientService.id).getConfigurationServiceClient();
        
        let request = new NewScanConfigRequest();
        request.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        if (scanType) {
            request.setScantype(scanType);
        }
        return configClient.newScanForm(request);
    }

    async getScanForm(name: string): Promise<GetScanFormResponse> {
        const configClient = await getService(ControllerClientService.id).getConfigurationServiceClient();
        
        let request = new GetScanConfigRequest();
        request.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        let filter = new GetScanConfigRequest.Filter();
        filter.setName(name);
        request.setSearchconfig(filter);

        return configClient.getScanForm(request);
    }

    async getScanTypes(): Promise<GetScanTypesResponse> {
        const configClient = await getService(ControllerClientService.id).getConfigurationServiceClient();
        
        let request = new GetScanTypesRequest();
        request.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        
        return configClient.getScanTypes(request);
    }

    async getScanConfigurationList(): Promise<GetScanConfigListResponse> {
        const configClient = await getService(ControllerClientService.id).getConfigurationServiceClient();
        
        let request = new GetScanConfigListRequest();
        request.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        return configClient.getScanConfigurationList(request);
    }

    async getScanConfiguration(name: string): Promise<GetScanConfigResponse> {
        const configClient = await getService(ControllerClientService.id).getConfigurationServiceClient();
        
        let request = new GetScanConfigRequest();
        request.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());

        const filter = new GetScanConfigRequest.Filter();
        filter.setName(name);
        request.setSearchconfig(filter);

        return configClient.getScanConfiguration(request);
    }

    async storeScanForm(configId: ConfigId, scanType: ScanConfig.ScanType | undefined, groups: ScanForm.ConfigGroup[]): Promise<StoreScanFormResponse> {
        const configClient = await getService(ControllerClientService.id).getConfigurationServiceClient();
        
        let request = new StoreScanFormRequest();
        request.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        request.setConfigid(configId);
        request.setScantype(scanType);
        request.setGroupsList(groups);

        return configClient.storeScanForm(request);
    }

    async deleteScanConfiguration(configId: ConfigId): Promise<DeleteScanConfigResponse> {
        const configClient = await getService(ControllerClientService.id).getConfigurationServiceClient();

        let request = new DeleteScanConfigRequest();
        request.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        request.setConfigid(configId);

        return configClient.deleteScanConfiguration(request);
    }

    async setSelectedScanConfig(configId: ConfigId): Promise<SetSelectedScanConfigResponse> {
        const configClient = await getService(ControllerClientService.id).getConfigurationServiceClient();
        let request = new SetSelectedScanConfigRequest();
        request.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        request.setConfigid(configId);
        return configClient.setSelectedScanConfig(request);
    }

    async updateGitRepositoryPath(path: string): Promise<UpdateConfigurationResponse | undefined> {
        const logger = getLogger();
        const configService = await getService(ControllerClientService.id).getConfigurationServiceClient();
        let getConfigResponse = await this.getConfiguration();
        if (getConfigResponse.getError()) {
            logger.warn(`updateGitRepositoryPath(): getConfigResponse returned an error=${getConfigResponse.getError()?.getMessage()}`);
            return;
        }

        let workspaceConfig = getConfigResponse.getWorkspaceconfig();
        if (!workspaceConfig) {
            logger.warn(`updateGitRepositoryPath(): no workspace config received`);
            return;
        }

        let gitConfig = workspaceConfig.getGitconfig();
        if (!gitConfig) {
            gitConfig = new GitConfig();
        }

        let valueSource = new ValueSource();
        valueSource.setType(ValueSource.Type.CODE_SIGHT_WORKSPACE);
        let stringValue = new StringValue();
        stringValue.setValue(path);
        stringValue.setSource(valueSource);
        gitConfig.setPathtogitrepository(stringValue);

        workspaceConfig.setGitconfig(gitConfig);

        let request = new UpdateConfigurationRequest();
        request.setWorkspaceconfig(workspaceConfig);
        return configService.updateConfiguration(request);
    }

    async updateReferenceBranchName(branchName: string): Promise<UpdateConfigurationResponse | undefined> {
        const logger = getLogger();
        const configService = await getService(ControllerClientService.id).getConfigurationServiceClient();
        let getConfigResponse = await this.getConfiguration();
        if (getConfigResponse.getError()) {
            logger.warn(`updateReferenceBranchName(): getConfigResponse returned an error=${getConfigResponse.getError()?.getMessage()}`);
            return;
        }

        let workspaceConfig = getConfigResponse.getWorkspaceconfig();
        if (!workspaceConfig) {
            logger.warn(`updateReferenceBranchName(): no workspace config received`);
            return;
        }

        let gitConfig = workspaceConfig.getGitconfig();
        if (!gitConfig) {
            gitConfig = new GitConfig();
        }

        let valueSource = new ValueSource();
        valueSource.setType(ValueSource.Type.CODE_SIGHT_WORKSPACE);
        let stringValue = new StringValue();
        stringValue.setValue(branchName);
        stringValue.setSource(valueSource);
        gitConfig.setDiffscanreferencebranch(stringValue);

        workspaceConfig.setGitconfig(gitConfig);

        let request = new UpdateConfigurationRequest();
        request.setWorkspaceconfig(workspaceConfig);
        return configService.updateConfiguration(request);
    }

    async initGitRepositoryPath(workspaceFolderPaths: string[]): Promise<void> {
        if (workspaceFolderPaths.length === 0) {
            return;
        }
        const configuredPath = await this.getConfiguredGitRepositoryPath();
        if (configuredPath && workspaceFolderPaths.includes(configuredPath)) {
            return;
        }
        await this.updateGitRepositoryPath(workspaceFolderPaths[0]);
    }

}
