import * as vscode from "vscode";
import { CODESIGHT_CONFIGURATION_KEY, CODESIGHT_SCAN_TOOL_CONFIGURATION_KEY } from "../utils/constants";
import { getLogger } from "../utils/logger";
import { ServiceId } from "./serviceContainer";
import { ToolTypeEnum } from "./toolStateService";

export abstract class ScanToolConfigService {
    static readonly id: ServiceId<ScanToolConfigService> = { id: ScanToolConfigService.name };

    /**
     * Fetch and return a copy of the stored scan configuration 
     */
    abstract getCodeSightScanConfig() : Promise<CodeSightScanConfig>;
    
    /**
     * Turns on/off Sigma scanning on every file change
     */
    abstract enableSigmaScanOnChange(enable:boolean): Promise<void>;

    abstract addListener(listener: ScanToolConfigListener): void;
    abstract removeListener(listener: ScanToolConfigListener): void;
}

const SIGMA_ONCHANGE_DEFAULT = false;
export interface SigmaScanConfig {
    sigmaAnalyzeOnChange: boolean;
}

export interface CodeSightScanConfig {
    sigma: SigmaScanConfig;
}

function createDefaultSigmaConfig() : SigmaScanConfig {
    return {
        sigmaAnalyzeOnChange: SIGMA_ONCHANGE_DEFAULT,
    };
}

export abstract class ScanToolConfigListener {
    abstract onToolConfigChanged(toolType: ToolTypeEnum): Promise<void>;
}

export class ScanToolConfigServiceImpl implements ScanToolConfigService {

    private scanToolConfigListeners: ScanToolConfigListener[];

    constructor() {
        this.scanToolConfigListeners = [];
    }
    
    async getCodeSightScanConfig(): Promise<CodeSightScanConfig> {
        let codeSightConfig = vscode.workspace.getConfiguration(CODESIGHT_CONFIGURATION_KEY);
        let defaultConfig : CodeSightScanConfig = {sigma:createDefaultSigmaConfig()};
        try{
            let toolConfig = codeSightConfig.get(CODESIGHT_SCAN_TOOL_CONFIGURATION_KEY);
            if(toolConfig){
                let storedConfig = <CodeSightScanConfig>toolConfig;
                // loaded config can have undefined settings if the settings file has been altered.
                // Type safety check for that
                if(storedConfig.sigma === undefined){
                    storedConfig.sigma = createDefaultSigmaConfig();
                } else {
                    const s = storedConfig.sigma;
                    if(!(isBoolean(s.sigmaAnalyzeOnChange))){
                        storedConfig.sigma =  createDefaultSigmaConfig();
                    }
                }
                return storedConfig;
            }
        } catch(e){
            getLogger().info("No existing scan tool config found. Using default scan tool config");
        }
        return defaultConfig;
    }
    
    async enableSigmaScanOnChange(enable: boolean): Promise<void> {
        let currentConfig = await this.getCodeSightScanConfig();
        if(currentConfig.sigma.sigmaAnalyzeOnChange !== enable){
            getLogger().info(`${enable? "Enabling" : "Disabling"} Rapid Scan Static scan onChange`);
            currentConfig.sigma.sigmaAnalyzeOnChange = enable;
            await vscode.workspace.getConfiguration(CODESIGHT_CONFIGURATION_KEY).update(CODESIGHT_SCAN_TOOL_CONFIGURATION_KEY, currentConfig);
            return this.notifyListenersConfigChanged(ToolTypeEnum.Sigma);
        }
    }

    private async notifyListenersConfigChanged(tool:ToolTypeEnum) : Promise<void>{
        const promises: Promise<void>[] = [];
        this.scanToolConfigListeners.forEach(listener =>{
            promises.push(listener.onToolConfigChanged(tool));
        });
        await Promise.all(promises);
    }

    addListener(listener: ScanToolConfigListener): void {
        this.scanToolConfigListeners.push(listener);
    }

    removeListener(listener: ScanToolConfigListener): void {
        let index = this.scanToolConfigListeners.indexOf(listener);
        if (index >= 0) {
            this.scanToolConfigListeners.splice(index, 1);
        }
    }
}

function isBoolean(value:unknown): boolean{
    return value !== undefined && (typeof value === "boolean");
}