import { ConfigId } from "@codesight/codesight-controller-proto/controller_proto/v0/config_pb";
import { DisplayKind } from "@codesight/codesight-controller-proto/controller_proto/v0/configuration_service_pb";
import { ScanConfig as ControllerScanConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/scan_config_pb";

export type ScanConfigViewProps = {
  scanConfigs: ScanConfig[];
  scanTypes: ControllerScanConfig.ScanType.AsObject[];
  selectedScanConfig: ConfigId.AsObject | undefined;
  selectedScanType: ControllerScanConfig.ScanType.AsObject | undefined;
  groupsToLoad: ConfigGroup[];
  isScanRunning: boolean;
}

export type ConfigGroup = {
  name: string;
  configItems: ConfigItem[];
  configGroups: ConfigGroup[];
  expanded: boolean;
}

export type ConfigItem = {
  id: string;
  values: string[];
  label: string;
  required?: boolean;
  type: DisplayKind;
  hintText: string;
  options?: string[];
  optionWarnings?: { [key: string]: string };
}

export type ScanConfig = {
  id: string;
  name: string;
  unsaved?: boolean;
}

export enum ScanConfigCommands {
  ADD_SCAN_CONFIG = "addScanConfig",
  ADD_SCAN_CONFIG_RESULT = "addScanConfigResult",
  DELETE_SCAN_CONFIG = "deleteScanConfig",
  DELETE_SCAN_CONFIG_RESULT = "deleteScanConfigResult",
  COPY_SCAN_CONFIG = "copyScanConfig",
  COPY_SCAN_CONFIG_RESULT = "copyScanConfigResult",
  SELECT_SCAN_CONFIG = "selectScanConfig",
  SELECT_SCAN_CONFIG_RESULT = "selectScanConfigResult",
  UPDATE_SCAN_CONFIG = "updateScanConfig",
  UPDATE_SCAN_CONFIG_RESULT = "updateScanConfigResult",
  CONFIGURE_SOURCE = "configureSource",
  CONFIGURE_SOURCE_RESULT = "configureSourceResult",
  RELOAD_COMPONENT = "reloadComponent",
  UPDATE_STATUS = "updateStatus",
  UPDATE_DETAILS_MESSAGE = "updateDetailsMessage",
  REFRESH_SCAN_TYPES = "refreshScanTypes",
  APPLY_AND_SCAN_CONFIG = "applyAndScanConfig",
  UPDATE_SCAN_RUNNING_STATUS = "updateScanRunningStatus",
}