import { BoolValue, StringValue, Uint32Value } from "@codesight/codesight-controller-proto/controller_proto/v0/config_types_pb";

/**
 * Replaces any line break characters (\r,\n or \r\n) with spaces
 */
export function removeLineBreaks(text: string): string {
    return text.replace(/\r?\n|\r/g, " ").trim();
}

export function stringToBoolValue(value: string | undefined | null): BoolValue {
    let boolValue = new BoolValue();
    boolValue.setValue(value?.toLocaleLowerCase() === 'true' ? true : false);
    return boolValue;
}

export function stringToStringValue(value: string | undefined | null): StringValue {
    let stringValue = new StringValue();
    stringValue.setValue(value ?? '');
    return stringValue;
}

export function stringToUInt32Value(value: string | undefined | null): Uint32Value {
    let intValue = new Uint32Value();
    try {
        if (value && value.length > 0) {
            intValue.setValue(parseInt(value));
        }
    } catch {
        //ignore, not a number
    }
    return intValue;

}

export function stringToBool(value: string | undefined | null): boolean {
    return value?.toLowerCase() === 'true';
}

export function stringToInt(value: string | undefined | null): number | undefined {
    try {
        return value ? parseInt(value) : undefined;
    } catch {
        return undefined;
    }

}