export const COMMAND_OPEN_CWE_ID = "codesight.decorations.open.cwe";

export abstract class EditorDecorationService {
    static readonly id: ServiceId<EditorDecorationService> = { id: EditorDecorationService.name };

    /**
     * Handles the task of redecorating visible editors
     */
    abstract handleVisibleEditorsChanged(): Promise<void>;

    abstract addIssueDecorationToEditor(activeFileIssueList: NewIssue[]): Promise<void>;

    abstract clearEditorMarkerDecorations(): Promise<void>;

    /**
     * This service needs to be initialized before it will become operational
     * This is because this service functions as a listener, so other services will not
     * instruct it directly to update the editor decorations (so the service provider will never need to create it)
     */
    abstract init(): void;

    /**
     * Navigates to issues in editor: Team View and Local View
     */
    abstract navigate(identifier: IssuesListIdentifier, issueId: string, displayType: DisplayType, occurrenceIndex?: number, eventNumber?: number, location?: Location): Promise<void>;
}

