    unselectedNewIssueDecorationRange!: TextEditorDecorationType;
    unselectedIssueDecoration!: TextEditorDecorationType;
    unselectedNewIssueDecoration!: TextEditorDecorationType;
    multiEventSelectedDecoration!: TextEditorDecorationType;
    multiNewEventSelectedDecoration!: TextEditorDecorationType;
    multiEventUnselectedDecoration!: TextEditorDecorationType;
    multiNewEventUnselectedDecoration!: TextEditorDecorationType;
    directDependencyDecoration!: TextEditorDecorationType;
    transitiveDependencyDecoration!: TextEditorDecorationType;
