    configurationChangedListener: Disposable | undefined;

    private initialized = false;
    commandDisposables: Disposable[];
    isSelectedEvent: (event: NewEvent, selectedIssue: NewIssue) => boolean;

    defaultViewInFocus: IssuesListIdentifier;
    // keeps track of the issues list currently active
    viewTypeInFocus: IssuesListIdentifier;

    constructor() {
        this.commandDisposables = [];
        this.initializeDecorations();

        this.isSelectedEvent = (event: NewEvent, selectedIssue: NewIssue) => {
            if (event instanceof NewEvent && selectedIssue instanceof NewIssue) {
                const parentIssue = event.getParentIssue();
                return parentIssue && parentIssue.equals(selectedIssue);
            }

            return false;
        };

        this.defaultViewInFocus = IssuesListIdentifier.LocalViewIssuesList;
        this.viewTypeInFocus = this.defaultViewInFocus;
    }

    init() {
        if (this.initialized) { return; }
        this.initialized = true;

        getService(IssueSelectionService.id).addListener(this);
        getService(LocalViewIssuesListService.id).addListener(this);
        getService(TeamViewIssuesListService.id).addListener(this);
        getService(ScanConfigurationService.id).addListener(this);
        this.listenForEditorChanges();

        this.configurationChangedListener = workspace.onDidChangeConfiguration((changeEvent: ConfigurationChangeEvent) => {
            if (changeEvent.affectsConfiguration(CODESIGHT_HIGHLIGHTING_CONFIGURATION_KEY)) {
                getLogger().info("Code Sight highlighting configuration changed. Updating settings");
                this.initializeDecorations();
                return this.redrawGutterDecorations();
            }
            return Promise.resolve();
        });

        this.commandDisposables.push(commands.registerCommand(COMMAND_OPEN_CWE_ID, async (urlToOpen: string) => {
            await getService(CsBrowserService.id).openLink(urlToOpen);
        }));
    }

