import { commands, Uri, ViewColumn } from "vscode";
import { ServiceId } from "./serviceContainer";

/**
 * Defines a service meant for handling browsing to external sites.
 *
 * Note: the prefixed "Cs" on this class name is intentional and should NOT be
 * removed. For some reason when this and it's implementation are called simply
 * "BrowserService" and "BrowserServiceImpl" the tests will sometimes fail to resolve
 * them.
 */
export abstract class CsBrowserService {
    static readonly id: ServiceId<CsBrowserService> = { id: CsBrowserService.name };

    /**
     * Opens an external browser to the given URL or navigates to the file path provided.
     *
     * @param link the url or file path to navigate to
     */
    abstract openLink(link: string): Promise<void>;
}

export class CsBrowserServiceImpl implements CsBrowserService {

    async openLink(link: string): Promise<void> {
        let linkPath = Uri.parse(link);
        if (linkPath.scheme === "http" || linkPath.scheme === "https") {
            // eslint-disable-next-line @typescript-eslint/no-floating-promises
            commands.executeCommand('vscode.open', linkPath);
        } else {
            linkPath = Uri.file(link);
            // eslint-disable-next-line @typescript-eslint/no-floating-promises
            commands.executeCommand('vscode.open', linkPath, {viewColumn: ViewColumn.One});
        }
    }
}