import * as mkdirp from "mkdirp";
import * as path from 'path';
import { version } from "vscode";
import * as winston from "winston";
import { ExtensionConfigService } from "../services/extensionConfigService";
import { getService } from "../services/serviceContainer";
import { getLogFilenameTimestamp } from "./dateUtils";
import { getEnvVar } from "./environmentUtils";
import { makeTmpDir } from "./fileUtils";

let timestamp = getLogFilenameTimestamp();
let logFileName: string = `codesight_extension-vscode-${ timestamp }.log`;
let logLevel = getEnvVar("CODESIGHT_DESKTOP_DEBUG_LOG") ? "debug" : "info";
let basePath: string = "";

const STACK_FRAME_RE = new RegExp(/at ((\S+)\s)?(\(?|\(?[a-zA-Z]:?)([^:]+):(\d+):(\d+)/);
const FUNC_IDX = 2;
const MODULE_IDX = 4;
const LINE_IDX = 5;
const COL_IDX = 6;

let logger: winston.Logger;
let logFileDir: string;
let oldLogFileDir: string;

/**
 * Logs header information and sets the base path to use when looking through stack traces for file / function / line info.
 *
 * @param extensionPath the extension path used for determining what part of the stack trace is relevant
 */
export async function initLogger(): Promise<void> {
	oldLogFileDir = logFileDir;
	logFileDir = await getService(ExtensionConfigService.id).getExtensionLogPath();
	updateLogDir(logFileDir);
	logger.info(`Running VS Code version: ${ version }`, { header: 'true' });
	logger.info(`Start up extension log is available at: ${oldLogFileDir}`, { header: 'true' });
}

/**
 * Logs header information and sets the base path to use when looking through stack traces for file / function / line info.
 *
 * @param extensionPath the extension path used for determining what part of the stack trace is relevant
 */
 export async function initTempLogger(extensionPath: string): Promise<void> {
	basePath = extensionPath;
	let tmpLogDir = await makeTmpDir("codesight_extension-vscode-");	
	updateLogDir(tmpLogDir); // initialize logger to a tmp location
}

export function updateLogDir(newLogPath: string) {
	logFileDir = newLogPath;
	mkdirp.sync(logFileDir);
	logger = createLogger();
}

export function getLogger(): winston.Logger {
	return logger;
}

function createLogger(): winston.Logger {
	return winston.createLogger({
		level: 'debug',
		format: winston.format.combine(
			winston.format.simple(),
			winston.format.timestamp({
				format: 'YYYY-MM-DD HH:mm:ss.SSS'
			}),
			winston.format.printf(info => {
				// Skip the call info if this is header info as it is not useful
				if (info["header"]) {
					return `${ info.timestamp } ${ info.level }: ${ info.message }`;
				}

				let callerInfo = getCaller();

				return `${ info.timestamp } ${ info.level }: ${ callerInfo?.module }${ callerInfo?.function ? `#${ callerInfo.function }()` : `` }:${ callerInfo?.line } ${ info.message }`;
			})
		),
		transports: [
			new winston.transports.File({
				level: logLevel,
				dirname: logFileDir,
				filename: logFileName,
				handleExceptions: true
			}),
			new winston.transports.Console()
		],
		exitOnError: false
	});
}

function getCaller() {
	let err = new Error();
	Error.captureStackTrace(err);
	let srcDir = path.join(basePath, "src") + path.sep;

	// Throw away the first line of the trace
	let frames = err.stack!.split('\n').slice(1);

	// Find the first line in the stack that doesn't name this module.
	// eslint-disable-next-line @typescript-eslint/no-explicit-any
	let callerInfo : any = null;
	for (let i = 0; i < frames.length; i++) {
		if (frames[i].indexOf(srcDir) !== -1 && frames[i].indexOf("logger.ts") === -1) {
			callerInfo = STACK_FRAME_RE.exec(frames[i]);
			break;
		}
	}

	if (callerInfo) {
		let moduleName = callerInfo[MODULE_IDX];
		if (moduleName) {
			let pos = moduleName.indexOf(srcDir);
			if (pos !== -1) {
				moduleName = moduleName.substr(moduleName.indexOf(srcDir) + srcDir.length);
			}
		}
		return {
			function: callerInfo[FUNC_IDX] || undefined,
			module: moduleName || undefined,
			line: callerInfo[LINE_IDX] || undefined,
			column: callerInfo[COL_IDX] || undefined
		};
	}
	return null;
}