import { FileScanInfo, RefreshStatus } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_service_pb";
import { LicensedToolsConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/licensed_tools_config_pb";
import { ScanConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/scan_config_pb";

/**
 * Pure functions for determining scan result handling logic.
 * These are extracted from LocalViewPresenter to improve testability.
 */
export class ScanResultHandlers {
    /**
     * Determines if this notification should be processed in Signal AI mode.
     *
     * @param signalViewEnabled Whether Signal view is enabled
     * @param aiModePreserved Whether AI mode is preserved
     * @param toolType The tool type from the notification
     * @returns true if all Signal AI mode conditions are met
     */
    static isSignalInAIMode(
        signalViewEnabled: boolean,
        aiModePreserved: boolean | undefined,
        toolType: LicensedToolsConfig.Type | undefined
    ): boolean {
        return signalViewEnabled &&
               (aiModePreserved ?? false) &&
               toolType === LicensedToolsConfig.Type.SIGNAL;
    }

    /**
     * Determines if this is an incremental scan failure that needs special handling.
     * Incremental scan failures require a refresh to clear the loading state.
     *
     * @param isScanModeMatch Whether the scan mode matches the current mode
     * @param scanSource The source of the scan
     * @param status The scan status
     * @returns true if this is an incremental scan failure requiring refresh
     */
    static isAutoScanFailureRequiringRefresh(
        isScanModeMatch: boolean,
        scanSource: FileScanInfo.Source | undefined,
        status: RefreshStatus.Status | undefined
    ): boolean {
        return isScanModeMatch &&
               scanSource === FileScanInfo.Source.AUTO &&
               status === RefreshStatus.Status.FAILED;
    }

    /**
     * Determines if scan type has changed in project scan mode.
     * When scan type changes, we show a message instead of auto-refreshing.
     *
     * @param isManualScan Whether this is a project scan
     * @param scanType The scan type from the notification
     * @param selectedResultsType The currently selected results type
     * @returns true if scan type has changed in project mode
     */
    static hasScanTypeChanged(
        isManualScan: boolean,
        scanType: ScanConfig.ScanType | undefined,
        selectedResultsType: ScanConfig.ScanType | undefined
    ): boolean {
        return isManualScan &&
               !!selectedResultsType &&
               !!scanType &&
               scanType.getType() !== selectedResultsType.getType();
    }
}
