import * as controlServiceGrpc from "@codesight/codesight-controller-proto/controller_proto/v0/control_service_grpc_pb";
import { EchoRequest, EchoResponse, GetConfigRequest, GetConfigResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/control_service_pb";
import { connectivityState, credentials } from "@grpc/grpc-js";
import { getGrpcLimit } from '../utils/environmentUtils';

/**
 * Defines the interface points with the controller's `ControlService`
 */
export interface ControlServiceClient {
    getConnectivityState(): connectivityState;

    getConfig(request: GetConfigRequest): Promise<GetConfigResponse>;

    echo(request: EchoRequest): Promise<EchoResponse>;
}

export class ControlServiceClientImpl implements ControlServiceClient {
    private client: controlServiceGrpc.ControlServiceClient;

    constructor(connectionAddress: string) {
        this.client = new controlServiceGrpc.ControlServiceClient(connectionAddress, credentials.createInsecure(), {'grpc.max_receive_message_length': getGrpcLimit(), 'grpc.enable_http_proxy': 0});
    }

    getConnectivityState(): connectivityState {
        return this.client.getChannel().getConnectivityState(true);
    }

    getConfig(request: GetConfigRequest): Promise<GetConfigResponse> {
        return new Promise<GetConfigResponse>((resolve, reject) => {
            this.client.getConfig(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }

    echo(request: EchoRequest): Promise<EchoResponse> {
        return new Promise<EchoResponse>((resolve, reject) => {
            this.client.echo(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }
}