import * as vscode from "vscode";
import { TreeNodeProvider } from "../utils/issuePresenterUtils";
import { ExtensionStatusPresenter } from "../views/extension-status/extensionStatusPresenter";
import { ExtensionStatusTreeProvider, ExtensionStatusTreeProviderImpl } from "../views/extension-status/extensionStatusTreeProvider";
import { IssuesFoundTreeProvider, IssuesFoundTreeProviderImpl } from "../views/issues/issuesFoundTreeProvider";
import { LocalViewPresenter } from "../views/local-view/localViewPresenter";
import { LocalViewTreeProvider, LocalViewTreeProviderImpl } from "../views/local-view/localViewTreeProvider";
import { CodeSightSetupTreeProvider, CodeSightSetupTreeProviderImpl } from "../views/setup/codeSightSetupTreeProvider";
import { CodeSightSetupPresenter } from "../views/setup/codesightSetupPresenter";
import { TeamViewPresenter } from "../views/team-view/teamViewPresenter";
import { TeamViewTreeProvider, TeamViewTreeProviderImpl } from "../views/team-view/teamViewTreeProvider";
import { LocalViewIssuesListService, TeamViewIssuesListService } from "./issuesService";
import { ServiceId, getService } from "./serviceContainer";

export abstract class ViewProviderService {
    static readonly id: ServiceId<ViewProviderService> = { id: ViewProviderService.name };

    /**
     * Get or create the extension status presenter. Creates and initializes the Extension Status View
     * the first time this is called.
     */
    abstract getOrCreateExtensionStatusPresenter(): ExtensionStatusPresenter;

    /**
     * Get or create the Code Sight setup presenter. Creates and initializes the Code Sight Setup View
     * the first time this is called.
     */
    abstract getOrCreateSetupPresenter(): CodeSightSetupPresenter;

    /**
     * Get or create the team view presenter. Create and initialize the Team View the first
     * time this is called.
     */
    abstract getOrCreateTeamViewPresenter(): TeamViewPresenter;

    /**
     * Get or create the Local View presenter. Create and initialize the Local View the first time this is called.
     */
    abstract getOrCreateLocalViewPresenter(): LocalViewPresenter;
}

export class ViewProviderServiceImpl extends ViewProviderService {

    private extensionStatusPresenter: ExtensionStatusPresenter | undefined;
    private setupPresenter: CodeSightSetupPresenter | undefined;
    private localViewPresenter: LocalViewPresenter | undefined;
    private teamViewPresenter: TeamViewPresenter | undefined;


    getOrCreateTeamViewPresenter(): TeamViewPresenter {
        if (this.teamViewPresenter === undefined) {
            let teamViewTreeProvider = this.createTeamViewTreeProvider();
            let treeView = vscode.window.createTreeView("codesight-team-view", {
                treeDataProvider: teamViewTreeProvider,
                showCollapseAll: true,
                canSelectMany: false
            });
            this.teamViewPresenter = this.createTeamViewPresenter(teamViewTreeProvider, treeView);
        }
        return this.teamViewPresenter;
    }

    getOrCreateLocalViewPresenter(): LocalViewPresenter {
        if (this.localViewPresenter === undefined) {
            let localViewTreeProvider = this.createLocalViewTreeProvider();
            let treeView = vscode.window.createTreeView("codesight-local-view", {
                treeDataProvider: localViewTreeProvider,
                showCollapseAll: false,
                canSelectMany: false
            });
            this.localViewPresenter = this.createLocalViewTreePresenter(localViewTreeProvider, treeView);
        }
        return this.localViewPresenter;
    }

    createLocalViewTreeProvider(): LocalViewTreeProvider {
        return new LocalViewTreeProviderImpl();
    }

    createLocalViewTreePresenter(localViewTreeProvider: LocalViewTreeProvider, treeView: vscode.TreeView<TreeNodeProvider>): LocalViewPresenter {
        return new LocalViewPresenter(localViewTreeProvider, treeView, getService(LocalViewIssuesListService.id).pageControls());
    }

    createTeamViewTreeProvider(): TeamViewTreeProvider {
        return new TeamViewTreeProviderImpl(getService(TeamViewIssuesListService.id).pageControls());
    }

    createTeamViewPresenter(teamViewTreeProvider: TeamViewTreeProvider, treeView: vscode.TreeView<TreeNodeProvider>): TeamViewPresenter {
        return new TeamViewPresenter(teamViewTreeProvider, treeView);
    }

    createIssuesFoundTreeProvider(): IssuesFoundTreeProvider {
        return new IssuesFoundTreeProviderImpl();
    }

    getOrCreateExtensionStatusPresenter(): ExtensionStatusPresenter {
        if (this.extensionStatusPresenter === undefined) {
            let extensionStatusTreeProvider = this.createExtensionStatusTreeProvider();
            let treeView = vscode.window.createTreeView("codesight-status-view", {
                treeDataProvider: extensionStatusTreeProvider,
                showCollapseAll: true,
                canSelectMany: true
            });
            this.extensionStatusPresenter = new ExtensionStatusPresenter(extensionStatusTreeProvider, treeView);
        }

        return this.extensionStatusPresenter;
    }

    createExtensionStatusTreeProvider(): ExtensionStatusTreeProvider {
        return new ExtensionStatusTreeProviderImpl();
    }

    getOrCreateSetupPresenter(): CodeSightSetupPresenter {
        if (this.setupPresenter === undefined) {
            let treeProvider = this.createSetupTreeProvider();
            let treeView = vscode.window.createTreeView("codesight-setup-status", {
                treeDataProvider: treeProvider,
                showCollapseAll: false,
                canSelectMany: true
            });
            this.setupPresenter = new CodeSightSetupPresenter(treeProvider, treeView);
        }

        return this.setupPresenter;
    }

    createSetupTreeProvider(): CodeSightSetupTreeProvider {
        return new CodeSightSetupTreeProviderImpl();
    }
}