import { commands } from "vscode";

/**
 * Abstraction for executing VS Code commands.
 * This interface allows for testability by enabling command execution to be mocked.
 */
export interface CommandExecutor {
    /**
     * Executes a VS Code command with the given arguments.
     *
     * @param command The command identifier
     * @param args Arguments to pass to the command
     * @returns A promise that resolves when the command completes
     */
    executeCommand(command: string, ...args: any[]): Promise<void>;
}

/**
 * Production implementation of CommandExecutor that delegates to VS Code's command API.
 */
export class VsCodeCommandExecutor implements CommandExecutor {
    async executeCommand(command: string, ...args: any[]): Promise<void> {
        await commands.executeCommand(command, ...args);
    }
}

/**
 * Test/Mock implementation of CommandExecutor for use in tests.
 * Tracks all commands executed instead of actually running them.
 */
export class MockCommandExecutor implements CommandExecutor {
    public executedCommands: Array<{ command: string; args: any[] }> = [];

    async executeCommand(command: string, ...args: any[]): Promise<void> {
        this.executedCommands.push({ command, args });
    }

    /**
     * Check if a specific command was executed.
     *
     * @param command The command identifier to check
     * @returns true if the command was executed at least once
     */
    wasCommandExecuted(command: string): boolean {
        return this.executedCommands.some(c => c.command === command);
    }

    /**
     * Get the number of times a command was executed.
     *
     * @param command The command identifier
     * @returns The execution count
     */
    getCommandExecutionCount(command: string): number {
        return this.executedCommands.filter(c => c.command === command).length;
    }

    /**
     * Get the arguments passed to a command on a specific execution.
     *
     * @param command The command identifier
     * @param executionIndex The execution index (0 for first, 1 for second, etc.)
     * @returns The arguments or undefined if not found
     */
    getCommandArgs(command: string, executionIndex: number = 0): any[] | undefined {
        const executions = this.executedCommands.filter(c => c.command === command);
        return executions[executionIndex]?.args;
    }

    /**
     * Reset the tracked command history.
     */
    reset(): void {
        this.executedCommands = [];
    }
}
