import { Event, EventEmitter, ProviderResult, TreeDataProvider, TreeItem } from "vscode";
import { Copyable } from "../../utils/interfaces";

export interface ExtensionStatusTreeProvider extends TreeDataProvider<ExtensionStatusTreeItem> {

    /**
     * Set the data for the Extension Status Tree
     * Triggers a refresh of the tree
     *
     * @param treeItems The root items of the tree
     * @param itemChildren A map of tree items to their children. Any item which does not appear as a key in
     *                     this map is presumed to be a leaf node of the tree
     */
    setItems(rootTreeItems: ExtensionStatusTreeItem[], itemChildren: Map<ExtensionStatusTreeItem, ExtensionStatusTreeItem[]>): void;

}

export class ExtensionStatusTreeItem extends TreeItem implements Copyable {

    jobId?: string; // add an optional field to track which scan job a tree item is linked to

    getCopyText(): string {
        return this.label + (this.description ? " " + this.description : "");
    }
}

export class ExtensionStatusTreeProviderImpl implements ExtensionStatusTreeProvider {

    private _onDidChangeTreeData: EventEmitter<ExtensionStatusTreeItem | null> = new EventEmitter<ExtensionStatusTreeItem | null>();
    readonly onDidChangeTreeData: Event<ExtensionStatusTreeItem | null> = this._onDidChangeTreeData.event;

    protected rootItems: ExtensionStatusTreeItem[];
    protected itemToChildrenMap: Map<ExtensionStatusTreeItem, ExtensionStatusTreeItem[]>;

    constructor() {
        this.rootItems = [];
        this.itemToChildrenMap = new Map();
    }

    setItems(rootTreeItems: ExtensionStatusTreeItem[], itemChildren: Map<ExtensionStatusTreeItem, ExtensionStatusTreeItem[]>): void {
        this.rootItems = rootTreeItems;
        this.itemToChildrenMap = itemChildren;
        this._onDidChangeTreeData.fire(null); // TODO: investigate only firing for changed elements UD-4144
    }

    getTreeItem(element: ExtensionStatusTreeItem): TreeItem | Thenable<TreeItem> {
        return element;
    }

    getChildren(element?: ExtensionStatusTreeItem): ProviderResult<ExtensionStatusTreeItem[]> {
        if (!element) {
            return this.rootItems;
        }
        if (!this.itemToChildrenMap.has(element)) {
            return [];
        }
        return this.itemToChildrenMap.get(element);
    }
}