import * as fsExtra from 'fs-extra';
import * as path from 'path';
import { CONTROLLER_VERSION_FILE_NAME, ENV_CODESIGHT_DESKTOP_CUSTOM_CONTROLLER_PATH, FOLDER_NAME_ARCH_AMD64, FOLDER_NAME_ARCH_ARM64, FOLDER_NAME_CONTROLLER, FOLDER_NAME_LICENSE } from '../utils/constants';
import * as envUtils from '../utils/environmentUtils';
import * as fileUtils from '../utils/fileUtils';
import { getLogger } from '../utils/logger';
import * as controllerUtils from './controllerUtils';

export const CODESIGHT_SCOPE = "@codesight";
const NODE_MODULES = "node_modules";
export const CODESIGHT_CONTROLLER = "codesight-controller";

/**
 * @param extensionPath extension path
 * @returns binary path if extraction succeeded
 */
export async function extractController(extensionPath: string, testControllerBinaryRootPath?: string): Promise<string> {

    let customBinLocation =  envUtils.getEnvVar(ENV_CODESIGHT_DESKTOP_CUSTOM_CONTROLLER_PATH);

    // if a custom binary was specified, use that instead of extracting the controller
    if(customBinLocation){
        return customBinLocation;
    }

    let controllerPath = buildControllerPath(extensionPath);
    let version = await getControllerVersion(extensionPath);
    let controllerBin =  testControllerBinaryRootPath ? testControllerBinaryRootPath : controllerUtils.getControllerBinaryRootPath();
    const logger = getLogger();
    logger.info(`Extracting controller version ${ version } from path ${ controllerPath }`);

    if (!controllerBin) {
        return "";
    }

    try {
        let controllerVersionPath = path.join(controllerBin, version);
        if (!(fsExtra.existsSync(controllerVersionPath))) {
            await fileUtils.createDir(controllerVersionPath);
        }

        let platform = getControllerPlatform();
        let arch = getControllerArch();
        logger.info(`Extension detected platform: ${platform} arch: ${arch}`);

        let binaryName = FOLDER_NAME_CONTROLLER;
        if (envUtils.isWindows()) {
            binaryName = `${ binaryName }.exe`;
        }

        let licenseDir = path.join(controllerVersionPath, FOLDER_NAME_LICENSE);

        if (!(fsExtra.existsSync(licenseDir))) {
            await fsExtra.copy(path.join(controllerPath, FOLDER_NAME_LICENSE), licenseDir);
        }
        let amdPath = path.join(controllerVersionPath, platform, arch);
        let binaryPath = path.join(amdPath, binaryName);

        if (!(fsExtra.existsSync(binaryPath))) {
            await fsExtra.copy(path.join(controllerPath, platform), path.join(controllerVersionPath, platform));
            await fsExtra.copyFile(path.join(controllerPath, CONTROLLER_VERSION_FILE_NAME),
                path.join(controllerVersionPath, platform, arch, `${ binaryName }.${ CONTROLLER_VERSION_FILE_NAME }`));
        }
        const filePermissions = 0o760;
        fsExtra.chmodSync(binaryPath, filePermissions);
        return binaryPath;
    } catch (error) {
        logger.warn(`Error occurred while extracting the controller, err=${error}`);
        return Promise.reject(error);
    }
}

function buildControllerPath(extensionPath: string) {
    return path.join(extensionPath, NODE_MODULES, CODESIGHT_SCOPE, CODESIGHT_CONTROLLER);
}

export async function getControllerVersion(extensionPath: string): Promise<string> {
    let controllerPath = buildControllerPath(extensionPath);
    let versionString: string = await fileUtils.readFileToString(path.join(controllerPath, CONTROLLER_VERSION_FILE_NAME));
    let version = JSON.parse(versionString);
    return version.version;
}

export function getControllerPlatform() {
    if (envUtils.isWindows()) {
        return "windows";
    } else if (envUtils.isOSX()) {
        return "darwin";
    } else {
        return "linux";
    }
}
export function getControllerArch() {
    if (envUtils.isArm64OSX()) {
        return FOLDER_NAME_ARCH_ARM64;
    } else {
        return FOLDER_NAME_ARCH_AMD64;
    }
}

