// Special case message IDs
export const TOOL_SETUP_ID = "tool.setup";
export const LICENSE_VALIDATION_ID = "license.validation";

export const MESSAGE_ID_BEGINNING_INSTALLATION = "beginningInstallation.message";
export const WELCOME_ID = "welcome.message";
export const MESSAGE_ID_INSTALLED_TOOLS = "installed.tools.message";
export const REMOTE_ERROR_DETAILS = "remote.error.message";
export const CERTIFICATE_VALIDATION_ERROR = "certificate.validation";

// Setup Notification Meta Val map keys
export const NOTIFICATION_STATE_KEY = "state";
export const LOCAL_TOOLS_VERSION_KEY = "localToolVersion";
export const SUGGESTED_TOOL_VERSION_KEY = "updateToolVersion";
export const URL_KEY = "url";
export const ERROR_KEY = "error";
export const TRUST_STORE_LOCATION_KEY = "trustStoreLocation";
export const CERT_PEM_FORMAT = "certificatePEMFormat";
export const HOST = "host";

// setup tool states
export const SETUP_STATE_IDLE = "IDLE";
export const SETUP_STATE_VALIDATING_SETTINGS = "VALIDATING_SETTINGS";
export const SETUP_STATE_FINDING_AVAILABLE_LICENSES = "FINDING_AVAILABLE_LICENSES";
export const SETUP_STATE_DOWNLOADING_LICENSE = "DOWNLOADING_LICENSE";
export const SETUP_STATE_FINDING_AVAILABLE_INSTALLERS = "FINDING_AVAILABLE_INSTALLERS";
export const SETUP_STATE_DOWNLOADING_INSTALLER = "DOWNLOADING_INSTALLER";
export const SETUP_STATE_DOWNLOADED = "DOWNLOADED";
export const SETUP_STATE_INSTALLING = "INSTALLING";
export const SETUP_STATE_INSTALLED = "INSTALLED";
export const SETUP_STATE_UPDATE_AVAILABLE = "UPDATE_AVAILABLE";
export const SETUP_STATE_SUCCESS = "SUCCESS";
export const SETUP_STATE_ERROR = "ERROR";
export const SETUP_STATE_NO_TOOL_MATCH = "NO_TOOL_MATCH";
export const SETUP_STATE_NO_TOOL_MATCH_UPDATE = "NO_TOOL_MATCH_UPDATE";

export const ERROR_TYPE_AUTH = "Authentication";

// Special case Additional content IDs
export const PROBLEM_DETAILS_ID = "problem.details";
export const GENERAL_INFO_ID = "general.info";

// titles of known remediation actions
export const DO_UPDATE_REMEDIATION_ID = "remediation.do.update";
export const OPEN_PROJECT_COVERITY_CONF_REMEDIATION_ID = "remediation.open.project.conf";
export const OPEN_USER_COVERITY_CONF_REMEDIATION_ID = "remediation.open.user.conf";
export const CONTACT_SUPPORT_REMEDIATION_ID = "remediation.contact.support";
export const RETRY_DOWNLOAD_REMEDIATION_ID = "remediation.retry.download";
export const SKIP_DOWNLOAD_REMEDIATION_ID = "remediation.skip.download";
export const OLDER_DETECT_ERROR_REMEDIATION_ID = "remediation.older.error.id";
export const OPEN_DETECT_CONFIG_REMEDIATION_ID = "remediation.open.detect.config";
export const DO_INSTALL_REMEDIATION_ID = "remediation.do.install";
export const COMMUNITY_PORTAL_REMEDIATION_ID = "remediation.community.portal";
export const EXPORT_LOGS_REMEDIATION_ID = "remediation.collect.diagnostics";
export const USE_LOCAL_BINARY_REMEDIATION_ID = "remediation.use.local.binary";
export const OPEN_DOWNLOAD_LOCATION_REMEDIATION_ID = "remediation.open.download.location";
export const REAUTHENTICATE_BLACK_DUCK_REMEDIATION_ID   = "remediation.reauthenticate.black.duck";

export const REMEDIATION_ID = "remediation";

// tool meta map values
export const TOOL_NAME_META_KEY = "tool";
export const TOOL_NAME_BLACKDUCK = "blackduck";
export const TOOL_NAME_SIGMA = "sigma";
export const TOOL_NAME_COVERITY = "coverity-analysis";

const DOWNLOAD_STATES = [MESSAGE_ID_BEGINNING_INSTALLATION,
    SETUP_STATE_DOWNLOADING_INSTALLER,
    SETUP_STATE_DOWNLOADED,
    SETUP_STATE_INSTALLING,
    SETUP_STATE_INSTALLED,
    SETUP_STATE_DOWNLOADING_LICENSE
];

const PLUGIN_ASSOCIATED_FILE = "plugin.associated.file.path";

const localize: LocalizeFunc = loadMessageBundle();

export function isBlackduckMessage(message: NotificationMessage): boolean {
    return getMetaVal(message, TOOL_NAME_META_KEY) === TOOL_NAME_BLACKDUCK;
}

export function isWelcomeMessage(message: NotificationMessage): boolean {
    return message.getId() === WELCOME_ID;
}

export function isInstalledToolsMessage(message: NotificationMessage): boolean {
    return message.getId() === MESSAGE_ID_INSTALLED_TOOLS;
}

export function isSetupMessage(message: NotificationMessage): boolean {
    return message.getId() === TOOL_SETUP_ID;
}

export function isAutoInstallToolSetupMessage(message: NotificationMessage): boolean {
    return isSetupMessage(message) && (message.getTooltype() === LicensedToolsConfig.Type.BRIDGE || message.getTooltype() === LicensedToolsConfig.Type.SIGNAL);
}

export function isCsseLicenseStateMessage(message: NotificationMessage): boolean {
    return message.getId() === LICENSE_VALIDATION_ID;
}

export function isDownloadRelatedSetupMessage(message: NotificationMessage): boolean {
    let state = getState(message);
    return state !== "" && DOWNLOAD_STATES.indexOf(state) !== -1;
}

export function hasState(message: NotificationMessage): boolean {
    return getState(message) !== "";
}

export function getLocalToolVersion(message: NotificationMessage): string {
    return getMetaVal(message, LOCAL_TOOLS_VERSION_KEY);
}

export function getSuggestedToolVersion(message: NotificationMessage): string {
    return getMetaVal(message, SUGGESTED_TOOL_VERSION_KEY);
}

export function isSigmaMessage(message: NotificationMessage): boolean {
    return getTool(message) === TOOL_NAME_SIGMA;
}

export function isCoverityMessage(message: NotificationMessage): boolean {
    return getTool(message) === TOOL_NAME_COVERITY;
}

export function isCoverityAuthMessage(message: NotificationMessage): boolean {
    return isSetupMessage(message) && isSetupErrorState(message) && isAuthenticationError(message) && isCoverityMessage(message);
}

export function isBlackduckAuthMessage(message: NotificationMessage): boolean {
    return isSetupMessage(message) && isSetupErrorState(message) && isAuthenticationError(message) && isBlackduckMessage(message);
}

export function localToolsAvailable(message: NotificationMessage): boolean {
    return getLocalToolVersion(message) !== "";
}

export function isSetupErrorState(message: NotificationMessage): boolean {
    return getState(message) === SETUP_STATE_ERROR;
}

export function isSetupSuccessState(message: NotificationMessage): boolean {
    return getState(message) === SETUP_STATE_SUCCESS;
}

export function isNoToolMatchState(message: NotificationMessage): boolean {
    return getState(message) === SETUP_STATE_NO_TOOL_MATCH;
}

export function getToolType(message: NotificationMessage): ToolTypeEnum | undefined {
    if (isSigmaMessage(message)) {
        return ToolTypeEnum.Sigma;
    } else if (isBlackduckMessage(message)) {
        return ToolTypeEnum.Blackduck;
    } else if (isCoverityMessage(message)) {
        return ToolTypeEnum.Coverity;
    }

    return undefined;
}

export function getTruststoreLocation(message: NotificationMessage): string {
    return getMetaVal(message, TRUST_STORE_LOCATION_KEY);
}

export function getError(message: NotificationMessage): string {
    return getMetaVal(message, ERROR_KEY);
}

/**
 * Returns true if the message is a setup message which indicates a "Complete" state which may be one of SUCCESS, UPDATE or ERROR
 * @param message 
 * @returns 
 */
export function isSetupCompleteState(message: NotificationMessage): boolean {
    return isSetupSuccessState(message) || isUpdateMessage(message) || isSetupErrorState(message);
}

export function isAuthenticationError(message: NotificationMessage): boolean {
    return getErrorType(message) === ERROR_TYPE_AUTH;
}

export function isScanningToolAvailableMessage(message: NotificationMessage): boolean {
    let generalInfo: boolean = getGeneralInfoContent(message) ? true : false;
    return getErrorType(message) === ERROR_TYPE_AUTH && generalInfo && message.getSeverity() !== Message.Severity.ERROR;
}

export function getMessageSummaryForState(message: NotificationMessage): string {
    if (!hasState(message)) {
        return message.getDescription();
    }

    if (isScanningToolAvailableMessage(message)) {
        let generalInfo = getGeneralInfoContent(message);
        if (generalInfo) {
            return generalInfo.getTitle();
        }
    }

    let summary = getTitleFromProblemDetails(message);
    if (summary === "") {
        summary = getFirstContentTitle(message);
    }
    if (summary === "") {
        summary = message.getDescription();
    }
    return summary;
}

export function isUpdateMessage(message: NotificationMessage): boolean {
    let state = getState(message);
    return state !== "" && (state === SETUP_STATE_UPDATE_AVAILABLE || state === SETUP_STATE_NO_TOOL_MATCH_UPDATE);
}

export function getTitleFromProblemDetails(message: NotificationMessage): string {    
    let additionalContentList = message.getAdditionalcontentList();

    if (additionalContentList.length >= 1) {
        let problemDetails = getProblemDetails(message);
        if (problemDetails !== undefined) {
            return problemDetails.getTitle();
        }
    }

    return "";
}

export function getFirstContentTitle(message: NotificationMessage): string {
    let additionalContentList = message.getAdditionalcontentList();

    if (additionalContentList.length === 0) {
        return "";
    }

    return additionalContentList[0].getTitle();
}

export function isSingleActionRemediation(remediationId: string): boolean {
    return remediationId === DO_UPDATE_REMEDIATION_ID || remediationId === RETRY_DOWNLOAD_REMEDIATION_ID || remediationId === SKIP_DOWNLOAD_REMEDIATION_ID;
}

export function getUserFriendlyError(message: NotificationMessage): string {
    return getMetaVal(message, "userFriendlyError");
}

export function getUserCoverityConfLocation(message: NotificationMessage): string {
    return getMetaVal(message, "coverityConfLoc");
}

export function getProjectCoverityConfLocation(message: NotificationMessage): string {
    let confLocation = getMetaVal(message, "projectRoot");

    if (confLocation !== "") {
        confLocation += path.sep + "coverity.conf"; //$NON-NLS-1$
    }

    return confLocation;
}

export function getUniqueID(message: NotificationMessage): string {
    let toolName = getTool(message);
    if (toolName) {
        return `${ message.getId() }.${ toolName }`;
    }
    return message.getId();
}

export function getTool(message: NotificationMessage): string {
    return getMetaVal(message, TOOL_NAME_META_KEY);
}

export function isUntrustedCertificateMessage(message: NotificationMessage): boolean {
    return message.getId() === CERTIFICATE_VALIDATION_ERROR;
}

function getState(message: NotificationMessage): string {
    return getMetaVal(message, NOTIFICATION_STATE_KEY);
}

function getErrorType(message: NotificationMessage): string {
    return getMetaVal(message, "errorType");
}

function getMetaVal(message: NotificationMessage, key: string): string {
    let val = message.getMetaMap().get(key);

    return val ? val : "";
}

function getMetaValAc(additionalContent: NotificationMessage.AdditionalContent, key: string): string {
    let val = additionalContent.getMetaMap().get(key);

    return val ? val : "";
}

function getProblemDetails(message: NotificationMessage): NotificationMessage.AdditionalContent | undefined {
    for (let val of message.getAdditionalcontentList()) {
        if (val.getSourceid() === PROBLEM_DETAILS_ID) {
            return val;
        }
    }

    return undefined;
}

function getGeneralInfoContent(message: NotificationMessage): NotificationMessage.AdditionalContent | undefined {
    for (let val of message.getAdditionalcontentList()) {
        if (val.getSourceid() === GENERAL_INFO_ID) {
            return val;
        }
    }

    return undefined;
}

// Allow an associated file path to be added to a notification message
// This is helpful for when a message corresponds with something like a scan
// failure, which is tracked on the plugin side.
export function setAssociatedFilePath(message: NotificationMessage, filepath: string): void {
    message.getMetaMap().set(PLUGIN_ASSOCIATED_FILE, filepath);
}

export function getAssociatedFilePath(message: NotificationMessage): string {
    return getMetaVal(message, PLUGIN_ASSOCIATED_FILE);
}

export function getCertPEMFormat(message: NotificationMessage): string {
    return getMetaVal(message, CERT_PEM_FORMAT);
}

export function getHost(message: NotificationMessage): string {
    return getMetaVal(message, HOST);
}

export function createWelcomeMessage(): NotificationMessage {
    let message = new NotificationMessage();

    message.setId(WELCOME_ID);
    message.setDescription(localize('webview.welcome.title', 'Welcome to the Black Duck Code Sight Extension'));

    return message;
}

export function getInstalledToolsMessageTitle(): string {
    return localize('webview.installed.tools.title', 'Products and Licenses');
}

export function createNotificationBasedOnControllerError(error: Error) {
    let notification = new NotificationMessage();
    notification.setId(REMOTE_ERROR_DETAILS);
    notification.setSeverity(Message.Severity.ERROR);
    notification.setDescription(localize('remote.issue.list.load.error.title', 'Failed to Load Data'));

    let errorDetails = new NotificationMessage.AdditionalContent();
    errorDetails.setSourceid(PROBLEM_DETAILS_ID);
    errorDetails.setFormattedcontent(getFormattedErrorContentHtml(error));

    let contactSupport = new NotificationMessage.AdditionalContent.RemediationAction();
    contactSupport.setId(CONTACT_SUPPORT_REMEDIATION_ID);
    contactSupport.setContent(localize('remote.issue.list.load.error.contact.support', 'Contact Support'));

    let exportLogs = new NotificationMessage.AdditionalContent.RemediationAction();
    exportLogs.setId(EXPORT_LOGS_REMEDIATION_ID);

    errorDetails.addRemediationactions(exportLogs);
    errorDetails.addRemediationactions(contactSupport);
    notification.addAdditionalcontent(errorDetails);
    return notification;
}

export function getFormattedErrorContentHtml(error: Error, includeButtons?: boolean): string {
    let html = /*html*/`
    <div class="errorPadding">${localize('new.issue.list.load.error.desc', 'Code Sight was unable to load the data from the server.  Please check the server connection and try again.  If the problem persists, collect the export logs and contact support.')}</div>
    <div class="errorPadding" style="font-weight: bold; font-size: large;">${localize('new.issue.list.load.error.code.label', 'Error Details: ')}</div>
    <div style="border-style: solid; border-width: 1px; border-color: var(--vscode-textBlockQuote-border); padding: 0 0.7rem 0.7rem 0.7rem; background-color: var(--vscode-textBlockQuote-background);">
        <code class="errorCodeBlock">${localize('new.issue.list.load.error.code.details', 'Code {0} - {1} ', error.getCode(), error.getMessage())}</code>
    </div>`;
    
    if (includeButtons) {
        html += /*html*/`
        ${EXPORT_LOGS_BODY}
        <button class="button" type="button" id='${CONTACT_SUPPORT_REMEDIATION_ID}'>
            <div class='box'>
                <div class='button-content'>
                    <img class='margin-right contact-support-icon' width='16' height='16'/>    
                    <span>${localize('new.issue.list.load.error.contact.support', 'Contact Support')}</span>
                </div>
            </div>
        </button>
        `;
    }
    return html;
}

