import { Webview } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { AuthModel } from "../../models/authModel";
import { DOC_APP_ADDRESS } from "../../utils/constants";
import { getServerName, getServerShortName } from "../../utils/typeUtils";
import * as webviewUtils from "../../utils/webviewUtils";
import { getProxyScript } from "../../views/proxy/proxyConfigComponent";
import { WebviewProvider } from "../webviewProvider";

const localize: LocalizeFunc = loadMessageBundle();

export abstract class SingleStepAuthViewProviderBase extends WebviewProvider {
    abstract reloadHtml(model: AuthModel): void;
}
const testConnectionText = localize('auth.button.test', 'Test Connection');
const saveSettingsText = localize('auth.button.save', 'Save Settings');

export namespace SingleStepAuthViewCommandIds{
    export const TEST_CONNECTION = "test-connection";
    export const SAVE_SETTINGS = "save-settings";
    export const BROWSE = "browse";
    export const CONFIGURE = "configure";
    
    export const SET_STATUS = "set-status";
    export const CLEAR_STATUS = "clear-status";
    export const ENABLE_BUTTON = "enable-button";
    export const SAVE_SUCCESSFUL = "save-successful";
}

export abstract class SingleStepAuthViewProviderBaseImpl extends SingleStepAuthViewProviderBase {
    abstract defaultUrl: string;
    
    protected abstract urlRowForServer(model: AuthModel) : string;
    protected abstract tokenDescForServer() : string;

    public reloadHtml(model: AuthModel) {
        let body = "";
        let script = "";

        body = this.getBody(model);
        script = this.getScript();

        let html = /*html*/`<!DOCTYPE html>
            <html lang="en">
            <head>
            ${this.head}
            </head>
            <style>
            ${this.style}
            </style>
            <body>
                ${body}
                <script>
                    const vscode = acquireVsCodeApi();
                    let settingsSaved = document.querySelector('input[name="url"]').value ? true : false;

                    function handleFormContent(button) {
                        switch (button) {
                            case '${SingleStepAuthViewCommandIds.TEST_CONNECTION}':
                                vscode.postMessage({
                                    command: '${SingleStepAuthViewCommandIds.TEST_CONNECTION}',
                                    url: document.querySelector('input[name="url"]').value,
                                    password: document.querySelector('input[name="pass"]').value
                                });
                                break;
                                case '${SingleStepAuthViewCommandIds.SAVE_SETTINGS}':
                                    settingsSaved = true;
                                    vscode.postMessage({
                                        command: '${SingleStepAuthViewCommandIds.SAVE_SETTINGS}',
                                        url: document.querySelector('input[name="url"]').value,
                                        password: document.querySelector('input[name="pass"]').value
                                    });
                                    break;
                            default:
                                break;
                        }
                    }
                    
                    function updateButtonState(fields) {
                        let shouldEnable = true;
                        fields.forEach(field => {
                            if(!isFilled(field)) {
                                shouldEnable = false;
                            }
                        });
                        enableButton('testConnection', shouldEnable, false);
                        enableButton('saveSettings', shouldEnable, true);
                    }

                    function isFilled(field) {
                        var input = document.getElementById(field).value;
                        if (input !== "") return true;
                        return false;
                    }

                    function enableButton(buttonId, shouldEnable, primary) {
                        let secondaryText = primary ? "" : "-secondary";
                        if (shouldEnable) {
                            document.getElementById(buttonId).classList.remove("button-disabled" + secondaryText);
                            document.getElementById(buttonId).removeAttribute("disabled");
                        } else {
                            document.getElementById(buttonId).classList.add("button-disabled" + secondaryText);
                            document.getElementById(buttonId).setAttribute("disabled", "");
                        }
                    }

                    function handleCheckboxChange(checkbox) {
                        let urlTextInput = document.getElementById('url');
                        if (checkbox.checked) {
                            urlTextInput.value = "${this.defaultUrl}";
                            urlTextInput.setAttribute("disabled", "");
                            updateButtonState(['url']);
                        } else {
                            urlTextInput.removeAttribute("disabled");
                        }
                        clearPasswordInput();
                        clearStatusMessage();
                    }

                    function showStatusMessage(header, message, type) {
                        let actionStatusId = '#status';
                        let actionStatusTextId = '#statusText';
                        let actionStatusHeaderId = '#statusHeader';
                        let statusImgId = '#statusImg';
                        let icon;
                        switch (type) {
                            case "success":
                                icon = "success-icon";
                                document.getElementById("troubleshootingLink").classList.add('hidden');
                                break;
                            case "error":
                                icon = "severity-high";
                                document.getElementById("troubleshootingLink").classList.remove('hidden');
                                break;
                            case "spin":
                                icon = "spinner-icon";
                                document.getElementById("troubleshootingLink").classList.add('hidden');
                                break;
                        }

                        document.querySelector(actionStatusId).classList.remove('hidden');
                        if (header) {
                            document.querySelector(actionStatusHeaderId).innerHTML = header;
                            document.querySelector(actionStatusHeaderId).classList.remove('hidden');
                        }
                        document.querySelector(actionStatusTextId).innerHTML = message;
                        let statusImg = document.querySelector(statusImgId);
                        statusImg.className = "";
                        statusImg.classList.add(icon);
                    }

                    function clearStatusMessage() {
                        document.querySelector('#status').classList.add('hidden');
                        document.querySelector('#statusText').innerHTML = "";
                        document.querySelector('#statusHeader').innerHTML = "";
                        document.getElementById("statusHeader").classList.add('hidden');
                        document.querySelector('#statusImg').className = "";
                        document.getElementById("troubleshootingLink").classList.add('hidden');
                    }

                    function clearPasswordInput() {
                        let passInput = document.getElementById("pass");
                        if (passInput && settingsSaved) {
                            passInput.value = ""
                        }
                        if (passInput?.getAttribute("placeholder") !== "") {
                            passInput.setAttribute("placeholder", "");
                        }
                    }

                    window.addEventListener('message', event => {
                        const message = event.data;
                        switch (message.command) {
                            case '${SingleStepAuthViewCommandIds.SET_STATUS}':
                                clearStatusMessage();
                                showStatusMessage(message.header, message.message, message.type);
                                break;
                            case '${SingleStepAuthViewCommandIds.CLEAR_STATUS}':
                                clearStatusMessage();
                                break;
                            case '${SingleStepAuthViewCommandIds.ENABLE_BUTTON}':
                                let enabled = message.enable === "true";
                                let primary = message.primary === "true";
                                enableButton(message.buttonId, enabled, primary);
                                break;
                            case '${SingleStepAuthViewCommandIds.SAVE_SUCCESSFUL}':
                                document.getElementById('pass').setAttribute("placeholder", "*************************************************");
                                break;
                        }
                    });

                    ${getProxyScript()}

                    ${script}
                </script>
            </body>
            </html>`;

        // If the html is unchanged, then the webview will not update. Nice feature, right?
        //
        // It's a problem when the html is indeed unchanged, but the input boxes have deviated
        // from their initial values, and we want to reset them to their initial values. As a
        // workaround, clearing the webview.html before setting it ensures that the html is updated.
        this.webviewPanel!.webview.html = "";
        this.webviewPanel!.webview.html = html;
    }

    protected getHead(webview: Webview): string {
        return webviewUtils.getWebviewHead("Code Sight Initial Configuration: Authentication", webview);
    }

    protected getStyle(): string {
        return /*css*/`
        /* Full-width inputs */
        input[type=text], input[type=url], input[type=password] {
            padding: 12px 20px;
            margin: 8px 0;
            box-sizing: border-box;
        }

        ${webviewUtils.BUTTON_STYLING}

        .inactive-status {
            width: 50%;
            text-align: center;
            border-width: 1px;
            border-style: solid;
            padding: 14px 20px;
        }

        .active-status {
            width: 50%;
            text-align: center;
            border-width: 1px;
            border-style: solid;
            box-shadow:inset 0px 0px 0px 3px;
            padding: 14px 20px;
            font-weight: bold;
        }

        .step-title { 
            display: flex;
            gap: 1rem;
            align-items: center;
        }

        .step-title hr { 
            flex-grow: 1;
            opacity: 0.2;
            border: 1px solid var(--vscode-settings-textInputForeground);
        }

        .vertical {
            align-self: stretch;
            opacity: 0.2;
            border: 1px solid var(--vscode-settings-textInputForeground);
        }

        .login-grid {
            display: grid;
            grid-gap: 0.7rem;
            align-items: center;
            grid-template-columns: [col] 75px [col] 225px [col] 1px [col] 25px [col] auto;
            grid-template-rows: repeat(4, [row] auto);
            padding-bottom: 2.5rem;
          }

          .button-grid {
            display: grid;
            grid-gap: 0.7rem;
            align-items: center;
            grid-template-columns: [col] 190px [col] auto;
            grid-template-rows: repeat(2, [row] auto);
            padding-bottom: 2.5rem;
          }

          .inner-box, .button-box {
            display: flex;
            gap: 0.7rem;
            align-items: center;
          }

          .button-box {
            padding-bottom: 1rem;
          }

          .link-padding {
            padding-top: 0.3rem;
          }

          .auth-button {
            min-width: 175px;
          }
          
          .inner-box :first-child {
            flex-shrink: 0;
            min-width: 1.5rem;
          }


         #defaultServerUrl {
            width: 20px;
            height: 20px;
         }

         .link-configure {
            padding-top: 0.7rem;
            font-size: medium;
         }

         #singleAuth-wrapper {
            min-width: 500px;
            max-width: 900px;
        }
        `;
    }

    private getBody(model: AuthModel) {
        let url = model.getUrl();
        let serverName = getServerName(model.getServerType());
        let serverShortName = getServerShortName(model.getServerType());
        return /*html*/`
            <div class="box">
            <img class="blackduck-icon float-left" width="28" height="28">
            <h2 class="float-left margin-left">${localize('auth.single.step.title', '{0}: Authentication', serverName)}</h2>
        </div>
        <div id="singleAuth-wrapper">
            <form id="combined-form">
                <div>
                    <h3 class="step-title">
                        ${localize('auth.step1.authenticate', '1. Authenticate')}
                        <hr/>
                    </h3>
                </div>
                <div>
                    <div class="login-grid">
                        <label style="grid-column: col / span 5; grid-row: row 1;" for="pass">
                            <b>${localize('auth.serverurl.input.title', '{0} URL', serverShortName)}:</b>
                        </label>
                        ${this.urlRowForServer(model)}
                        <label style="grid-column: col / span 5; grid-row: row 3;" for="pass">
                            <b>${localize('auth.token.input.title', 'Personal Access Token')}:</b>
                        </label>
                        <input style="grid-column: col / span 2; grid-row: row 4;" placeholder="${url ? '*************************************************' : ''}" id="pass" type="password" name="pass"/>
                        <div style="grid-column: col 3; grid-row: row 4;" class="vertical"></div>
                        <div style="grid-column: col 4 / span 2; grid-row: row 4;">
                            <div>
                                ${this.tokenDescForServer()}
                            </div>
                            <div class="link-padding">
                                <a class="browse" href="#">${localize('auth.single.step.server.link.label', 'Open {0}', serverShortName)}</a>
                            </div>
                        </div>
                        <div style="grid-column: col; grid-row: row 5;">
                            <div style="display: flex; align-items: flex-end;">
                                <label><b>${localize('auth.proxy.title', 'Proxy')}:</b></label>
                                <img class="margin-left hint-icon" title="${localize('auth.proxy.hint', 'Proxy settings are optional. If your organization uses a proxy, click \'here\' to add or edit Code Sight\'s proxy settings.')}" width="15" height="15"/>
                            </div>
                        </div> 
                        <span style="grid-column: col 2; grid-row: row 5;" id='proxyStatusLabel'></span>
                        <div style="grid-column: col 3; grid-row: row 5;" class="vertical"></div>   
                        <div style="grid-column: col 4 / span 2; grid-row: row 5;">
                            <a href="#" onclick="onConfigureProxyClick();">${localize('auth.configureProxy.title', 'Configure Proxy')}</a>
                        </div>
                    </div>

                <div class="button-grid">
                <button id="testConnection" style="grid-column: col 1; grid-row: row 1;" class="button-secondary button-small button-disabled-secondary auth-button" type="button" data-text="${testConnectionText}" onclick="handleFormContent('${SingleStepAuthViewCommandIds.TEST_CONNECTION}');" disabled>
                    ${testConnectionText}
                </button>
                <button id="saveSettings" style="grid-column: col 1; grid-row: row 2;" class="button-small button-disabled auth-button" type="button" data-text="${saveSettingsText}" onclick="handleFormContent('${SingleStepAuthViewCommandIds.SAVE_SETTINGS}');" disabled>
                    ${saveSettingsText}
                </button>

                <div id="status" style="grid-column: col 2; grid-row: row 1 / span 2;" class="hidden inner-box">
                        <img id="statusImg" width=25 height=25>
                        <div class="margin-left">
                            <h3 id="statusHeader"></h3>
                            <b id="statusText"></b>
                            <a id="troubleshootingLink" href="${DOC_APP_ADDRESS}">
                                ${localize('auth.status.troubleshootingLink', 'Troubleshooting help')}
                            </a>
                        </div>
                    </div>
                </div>
                <div>
                    <h3 class="step-title">
                        ${localize('auth.step2.configure', '2. Configure Team View Result Source')}
                        <hr/>
                    </h3>
                    <div>
                        ${localize('auth.step2.desc', 'After successfully authenticating Code Sight with {0}, configure a source to view {0} results in Team View.', serverShortName)}
                    </div>
                    <div class="link-configure">
                        <a class="configure" href="#">${localize('auth.step2.link', 'Configure Source')}</a>
                    </div>
                </div>
            </form>
        </div>`;
    }

    private getScript(): string {
        let browseSelector = `".browse"`;
        let configureSelector = `".configure"`;

        return /*javascript*/`
        let browseLinks = document.querySelectorAll(${browseSelector});
        let configureLinks = document.querySelectorAll(${configureSelector});
        window.onload = function() {
            browseLinks.forEach(function(link) {
                link.onclick = function() {
                    vscode.postMessage({
                        command: '${SingleStepAuthViewCommandIds.BROWSE}',
                        url: document.querySelector('input[name="url"]').value,
                    });
                    return false;
                }
            });

            configureLinks.forEach(function(link) {
                link.onclick = function() {
                    vscode.postMessage({
                        command: '${SingleStepAuthViewCommandIds.CONFIGURE}',      
                    });
                    return false;
                }
            });

            let stepFields = ['url'];
            updateButtonState(stepFields); // update button state for auto-filled fields
            document.getElementById("combined-form").addEventListener("keyup", function() {
                updateButtonState(stepFields);
                clearStatusMessage();
            });
            document.getElementById("url").addEventListener("keyup", clearPasswordInput);
        }`;
    }
}
