import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { Disposable, WebviewPanel } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { BuildToolConfigType, ConfigurationService } from "../../services/configurationService";
import { getService } from "../../services/serviceContainer";
import { VsCodeInputService } from "../../services/vscodeInputService";
import { getLogger } from "../../utils/logger";
import { WebviewPresenter } from "../webviewPresenter";
import { DetectConfigurationViewProvider, EnvSettingsViewCommandIds } from "./detectConfigurationViewProvider";

const localize: LocalizeFunc = loadMessageBundle();

export class DetectConfigurationViewPresenter extends WebviewPresenter {

    private readonly panel: WebviewPanel;
    private view: DetectConfigurationViewProvider;
    private onMessageFromWebviewDisposable: Disposable | undefined;

    constructor(panel: WebviewPanel) {
        super();
        this.panel = panel;
        this.view = getService(DetectConfigurationViewProvider.id);
        this.view.initView(this.panel);
        this.onMessageFromWebviewDisposable = this.view.onMessageFromWebview(async message => {
            switch (message.command) {
                case EnvSettingsViewCommandIds.EDIT_BUTTON:
                    await this.handleEditButtonClick(message.configType);
                    break;
                case EnvSettingsViewCommandIds.RESET_BUTTON:
                    await this.handleResetButtonClick(message.configType);
                    break;
                default:
                    getLogger().warn(`Received unexpected message ${ message.command }`);
                    return;
            }
        });
    }

    async initView(): Promise<void> {
        let configurationData = await this.getConfigurationData();
        this.view.initHtml(configurationData);
    }

    private async getConfigurationData(): Promise<TableRow[]> {
        let configResponse = await getService(ConfigurationService.id).getConfiguration();
        let buildToolConfig = configResponse.getUserconfig()?.getBuildtoolconfig();
        let configs: TableRow[] = [];
        if (!buildToolConfig) {
            return configs;
        }

        let javaPath = buildToolConfig.getJava()?.getBinarylocation();
        configs = configs.concat({
            id: BuildToolConfigType.JAVA_HOME,
            configName: "JAVA_HOME",
            configPath: javaPath?.getValue() ?? ""
        });

        let mavenPath = buildToolConfig.getMaven()?.getBinarylocation();
        configs = configs.concat({
            id: BuildToolConfigType.MAVEN,
            configName: "MAVEN",
            configPath: mavenPath?.getValue() ?? ""
        });

        let npmPath = buildToolConfig.getNpm()?.getBinarylocation();
        configs = configs.concat({
            id: BuildToolConfigType.NPM,
            configName: "NPM",
            configPath: npmPath?.getValue() ?? ""
        });
        
        return configs;
    }

    async handleEditButtonClick(configType: string): Promise<void> {
        // show file picker
        let isJavaHomeConfig = this.isJavaHomeConfig(configType);
        let chosenDir = await getService(VsCodeInputService.id).showOpenDialog({ canSelectFiles: !isJavaHomeConfig, canSelectFolders: isJavaHomeConfig, canSelectMany: false });
        if (!chosenDir || chosenDir.length < 1) {
            getLogger().debug("No path provided");
            return;
        }

        let newConfigPath = chosenDir[0].fsPath;

        this.view.postMessageToWebview({
            command: EnvSettingsViewCommandIds.SET_CONF_STATUS,
            state: "loading",
            message: localize('detectConfigView.updateConf.statusText', 'Updating configuration..')
        });

        let configResponse = await getService(ConfigurationService.id).updateBuildToolConfiguration(+configType, newConfigPath);
        if (configResponse && configResponse.getErrorList().length !== 0) {
            this.view.postMessageToWebview({
                command: EnvSettingsViewCommandIds.SET_CONF_STATUS,
                state: "error",
                message: configResponse.getErrorList()[0].getMessage()
            });

            return;
        }

        this.view.postMessageToWebview({
            command: EnvSettingsViewCommandIds.SET_CONF_STATUS,
            state: "success"
        });
        
        // reload data
        await this.initView();
    }

    async handleResetButtonClick(configType: string): Promise<void> {
        this.view.postMessageToWebview({
            command: EnvSettingsViewCommandIds.SET_CONF_STATUS,
            state: "loading",
            message: localize('detectConfigView.resetConf.statusText', 'Resetting configuration..')
        });
        
        let configResponse = await getService(ConfigurationService.id).updateBuildToolConfiguration(+configType, "");
        if (configResponse && configResponse.getErrorList().length !== 0) {
            this.view.postMessageToWebview({
                command: EnvSettingsViewCommandIds.SET_CONF_STATUS,
                state: "error",
                message: configResponse.getErrorList()[0].getMessage()
            });

            return;
        }

        this.view.postMessageToWebview({
            command: EnvSettingsViewCommandIds.SET_CONF_STATUS,
            state: "success"
        });
        
        // reload data
        await this.initView();
    }

    private isJavaHomeConfig(configType: string): boolean {
        return +configType === BuildToolConfigType.JAVA_HOME;
    }

    async parseNotification(message: NotificationMessage): Promise<void> {
        // no-op for the scan tool configuration
    }

    dispose(): void {
        this.onMessageFromWebviewDisposable?.dispose();
    }
}

export interface TableRow {
    id: number;
    configName: string;
    configPath: string;
}