import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { commands, Disposable, WebviewPanel } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { ExtensionConfigService } from "../../services/extensionConfigService";
import { ProgressNotificationService } from "../../services/progressNotificationService";
import { getService } from "../../services/serviceContainer";
import { VsCodeInputService } from "../../services/vscodeInputService";
import { getLogger } from "../../utils/logger";
import { WebviewPresenter } from "../../views/webviewPresenter";
import { CustomWorkingDirCommandId, CustomWorkingDirMessageViewProvider } from "./customWorkingDirMessageViewProvider";

const localize: LocalizeFunc = loadMessageBundle();

export class CustomWorkingDirMessageViewPresenter implements WebviewPresenter {
    private readonly panel: WebviewPanel;
    private view: CustomWorkingDirMessageViewProvider;
    private onMessageFromWebviewDisposable: Disposable | undefined;
    private currentlyConfiguredValue: string | undefined;

    constructor(panel: WebviewPanel) {
        this.panel = panel;
        this.view = getService(CustomWorkingDirMessageViewProvider.id);
        this.view.initView(this.panel);

        this.onMessageFromWebviewDisposable = this.view.onMessageFromWebview(async message => {
            const logger = getLogger();
            switch (message.command) {
                case CustomWorkingDirCommandId.VIEW_BROWSE:
                    let chosenDir = await getService(VsCodeInputService.id).showOpenDialog({ canSelectFolders: true, canSelectMany: false });
                    if (!chosenDir || chosenDir.length < 1) {
                        logger.debug("No file selected from Custom location browser");
                        break;
                    }
                    this.view.postMessageToWebview({
                        command: CustomWorkingDirCommandId.SET_DIR,
                        value: chosenDir[0].fsPath,
                    });

                    return this.validateProvidedPath(chosenDir[0].fsPath);
                case CustomWorkingDirCommandId.VIEW_APPLY:
                    return this.handleContinuePressed();
                default:
                    logger.warn(`Received unexpected message ${ message.command }`);
                    break;
            }

            return Promise.resolve();
        });
    }

    public async initView(): Promise<void> {
        let configuredDir = getService(ExtensionConfigService.id).getBlackDuckHomePath();
        this.view.initHtml(configuredDir);

        // set and validate configured path
        this.view.postMessageToWebview({
            command: CustomWorkingDirCommandId.SET_INITIAL_DIR_PATH,
            value: configuredDir
        });
        await this.validateProvidedPath(configuredDir);
    }

    public async parseNotification(message: NotificationMessage): Promise<void> {
        // no-op
    }

    public dispose(): void {
        this.onMessageFromWebviewDisposable?.dispose();
    }

    private setLoadingState() {
        this.view.postMessageToWebview({
            command: CustomWorkingDirCommandId.SET_STATUS,
            type: CustomWorkingDirCommandId.STATUS_LOADING,
            message: localize('custom.dir.view.loading', 'Validating location')
        });
        this.view.postMessageToWebview({
            command: CustomWorkingDirCommandId.SET_CONTINUE_ENABLED,
            enabled: "false",
        });
        this.view.postMessageToWebview({
            command: CustomWorkingDirCommandId.SET_BROWSE_ENABLED,
            enabled: "false"
        });
    }

    private setSuccessState() {
        this.view.postMessageToWebview({
            command: CustomWorkingDirCommandId.SET_STATUS,
            type: CustomWorkingDirCommandId.STATUS_VALID,
            message: localize("custom.dir.valid", "Location meets working directory requirements")
        });
        this.view.postMessageToWebview({
            command: CustomWorkingDirCommandId.SET_CONTINUE_ENABLED,
            enabled: "true"
        });
        this.view.postMessageToWebview({
            command: CustomWorkingDirCommandId.SET_BROWSE_ENABLED,
            enabled: "true"
        });
    }

    private setErrorState(error: string) {
        this.view.postMessageToWebview({
            command: CustomWorkingDirCommandId.SET_BROWSE_ENABLED,
            enabled: "true"
        });
        this.view.postMessageToWebview({
            command: CustomWorkingDirCommandId.SET_STATUS,
            type: CustomWorkingDirCommandId.STATUS_INVALID,
            message: `${ localize("custom.dir.invalid", "Validation failed") }: ${ error }`
        });
    }

    private async validateProvidedPath(value: string) {
        this.setLoadingState();

        if (!value) {
            // if value is empty, clear status message
            this.view.postMessageToWebview({
                command: CustomWorkingDirCommandId.SET_STATUS,
                type: CustomWorkingDirCommandId.STATUS_CLEAR,
                message: ""
            });
            return;
        }

        let error = await getService(ExtensionConfigService.id).validateProvidedPath(value);
        if (error) {
            this.setErrorState(error);
        } else {
            this.currentlyConfiguredValue = value;
            this.setSuccessState();
        }
    }

    private async handleContinuePressed() {
        // spinner has been added to the view in provider

        // disable continue button
        this.view.postMessageToWebview({
            command: CustomWorkingDirCommandId.SET_CONTINUE_ENABLED,
            enabled: "false",
        });

        try {
            if (this.currentlyConfiguredValue) {
                // close the view and remove alert
                await this.view.dispose();
                await getService(ProgressNotificationService.id).showCustomWorkingDirAlert(false);

                // configure directory and re-activate the extension
                await getService(ExtensionConfigService.id).configureWorkspaceDir(this.currentlyConfiguredValue);
                // eslint-disable-next-line @typescript-eslint/no-floating-promises
                commands.executeCommand('workbench.action.reloadWindow');
            }

            this.view.postMessageToWebview({
                command: CustomWorkingDirCommandId.REMOVE_BUTTON_SPINNER
            });
        } catch (error) {
            this.view.postMessageToWebview({
                command: CustomWorkingDirCommandId.REMOVE_BUTTON_SPINNER
            });
            this.view.postMessageToWebview({
                command: CustomWorkingDirCommandId.SET_STATUS,
                type: CustomWorkingDirCommandId.STATUS_INVALID,
                message: `${ localize("custom.dir.configuration.failed", "Validation failed") }: ${ error }`
            });
        }
    }
}