import { ClassicAutoScanContext, ClassicManualScanContext, LocalScanModeContext, SignalManualScanContext } from "../models/localViewScanModeContext";
import { EntitlementService } from "./entitlementService";
import { LicenseAnalysisService } from "./licenseAnalysisService";
import { ScanMode, ScanStatusCoordinator } from "./scanStatusCoordinator";
import { ServiceId, getService } from "./serviceContainer";
import { VscodeContextService } from "./vscodeContextService";

/**
 * Service responsible for determining the current local scan mode context.
 *
 * The context determines:
 * - Which scan types should be loaded (Signal, Sigma, License)
 * - Whether issues should be filtered by active file
 * - Whether UI controls like active file filter should be shown
 *
 * There are three context types:
 * - Classic Auto: When in incremental mode - loads Sigma/License incremental scan results (file-scoped)
 * - Signal Manual: When in project mode with AI enabled - loads Signal scan results (project-wide, uses Auto-style loading)
 * - Classic Manual: When in project mode with AI disabled - loads user-selected scan results
 */
export abstract class LocalScanModeContextService {
    static readonly id: ServiceId<LocalScanModeContextService> = { id: LocalScanModeContextService.name };

    /**
     * Get the current local scan mode context based on:
     * - Current scan mode (Auto/Manual)
     * - Signal view enablement
     * - Entitlements and configuration
     */
    abstract getCurrentContext(): LocalScanModeContext;
}

export class LocalScanModeContextServiceImpl implements LocalScanModeContextService {
    getCurrentContext(): LocalScanModeContext {
        // Check Signal first - it takes precedence over scan mode
        // (Signal forces Project mode, but this handles edge cases)
        const isSignalView = getService(EntitlementService.id).getCachedProductEntitlement().isSignalEntitled();
        const aiEnabled = getService(VscodeContextService.id).getPreservedAIMode() ?? false;

        if (isSignalView && aiEnabled) {
            const tier = getService(ScanStatusCoordinator.id).getCurrentScanFileScope();
            return new SignalManualScanContext(tier);
        }

        const currentMode = getService(ScanStatusCoordinator.id).getCurrentScanMode();

        if (currentMode === ScanMode.Auto) {
            return this.createClassicAutoContext();
        } else {
            return new ClassicManualScanContext();
        }
    }

    private createClassicAutoContext(): ClassicAutoScanContext {
        const entitlements = getService(EntitlementService.id).getCachedProductEntitlement();
        const isSigmaEntitled = entitlements.isSigmaReadyToScan();

        const licenseAnalysisService = getService(LicenseAnalysisService.id);
        const isLicenseEntitled = entitlements.isSnippetScanEntitled();
        const isLicenseEnabled = licenseAnalysisService.isLicenseScanEnabled();
        const isLicenseEntitledAndEnabled = (isLicenseEntitled && isLicenseEnabled.isEnabled &&
            (isLicenseEnabled.isEnabledOnOpen || isLicenseEnabled.isEnabledOnSave)) ?? false;

        const tier = getService(ScanStatusCoordinator.id).getCurrentScanFileScope();
        return new ClassicAutoScanContext(isSigmaEntitled, isLicenseEntitledAndEnabled, tier);
    }
}
