import * as moment from "moment";

/**
 * Returns a displayable string representing the time since a particular instant
 * E.g.
 *  - now
 *  - 4 hours ago
 *  - 3 years ago
 * @param date The starting date
 */
export function getElapsedTimeSinceDate(date: Date): string {
    return moment(date).fromNow();
}

/**
 * Returns a pretty printed time string
 * E.g.
 *  - Jan 20, 2021
 */
export function getPrettyLocalDateString(date: Date): string {
    let options: Intl.DateTimeFormatOptions = {
        day: "numeric",
        month: "short",
        year: "numeric",
    };
    return date.toLocaleString(undefined, options);
}

/**
 * Returns a pretty printed time string
 * E.g.
 *  - Dec 6, 2021, 11:50 PM
 */
export function getPrettyLocalDateTimeString(date: Date): string {
    let options: Intl.DateTimeFormatOptions = {
        minute: "numeric",
        hour: "numeric",
        day: "numeric",
        month: "short",
        year: "numeric",
    };
    return date.toLocaleString(undefined, options);
}

/**
 * Returns the date format used for our extension log filenames. This will return the
 * year / month / date and hour / minute / second separated by a 'T'
 * E.g.
 * 20200102T085511 for January 2nd, 2020 at 8:55:11
 */
export function getLogFilenameTimestamp(): string {
    return moment().format("YYYYMMDDTHHmmss");
}

/**
 * Formats given date to desired structure 
 * 
 * @param date - date to format
 * @param format - moment specific formatting
 */
export function formatDate(date: Date, format: string): string {
    return moment(date).format(format);
}

/**
 * Returns a displayable string representing the time until/since a particular instant,
 * with better precision for short periods (minutes/hours instead of days).
 * E.g.
 *  - now
 *  - in 5 minutes
 *  - in 2 hours
 *  - in 25 hours (instead of "in a day")
 *  - 30 minutes ago
 * @param date The target date
 */
export function getElapsedTimeSinceDateWithPrecision(date: Date): string {
    const now = moment();
    const target = moment(date);
    const diffMinutes = target.diff(now, 'minutes');
    const absDiffMinutes = Math.abs(diffMinutes);

    if (absDiffMinutes < 1) {
        return "now";
    } else if (absDiffMinutes < 60) {
        const minutes = Math.round(absDiffMinutes);
        return diffMinutes > 0 ? `${minutes}m` : `${minutes}m ago`;
    } else if (absDiffMinutes < 72 * 60) {
        const hours = Math.round(absDiffMinutes / 60);
        return diffMinutes > 0 ? `${hours}h` : `${hours}h ago`;
    }

    return target.fromNow();
}