import { ADD, COPY, DELETE, LOAD_SELECTED, SCAN_CONFIG_VIEW_CONFIG_ACTION_FAILED, SCAN_CONFIG_VIEW_ERROR_DETAILS, SCAN_CONFIG_VIEW_ERROR_LOAD_CONFIGS, SCAN_CONFIG_VIEW_NO_ACTIVE_FILE, SCAN_CONFIG_VIEW_NO_WORKSPACE, SCAN_CONFIG_VIEW_SCAN_FAILED, SCAN_CONFIG_VIEW_SCAN_TRIGGER_FAILED } from "../../utils/localizedConstants";
import { getLogger } from "../../utils/logger";
import { SourcePicker } from "../../utils/sourcePicker";
import { getRemoteReferenceDisplayString } from "../../utils/typeUtils";
import { OPEN_INSTALLED_TOOLS_MSG_COMMAND_ID } from "../extension-status/extensionStatusPresenter";
import { WebviewPresenter } from "../webviewPresenter";
import { ScanConfigViewProvider } from "./scanConfigViewProvider";

const COMPONENT_NAME = "ScanConfig";

export class ScanConfigViewPresenter implements WebviewPresenter, EntitlementServiceListener, ScanStatusCoordinatorListener {
    
    private readonly panel: WebviewPanel;
    private view: ScanConfigViewProvider;
    private onMessageFromWebviewDisposable: Disposable | undefined;
    private selectedForm: ScanForm | undefined;
    private issueSources: Map<string, IssueSource | undefined> = new Map<string, IssueSource | undefined>();
    private lastActiveFilePath: string | undefined;
    private onDidChangeViewStateDisposable: Disposable | undefined;

    constructor(panel: WebviewPanel) {
        this.panel = panel;
        this.view = getService(ScanConfigViewProvider.id);
        this.view.initView(this.panel);
        getService(EntitlementService.id).addListener(this);
        getService(ScanStatusCoordinator.id).addListener(this);
        this.updateLastActiveFilePath();
        
        this.onDidChangeViewStateDisposable = this.panel.onDidChangeViewState(() => {
            if (this.panel.visible) {
                this.updateLastActiveFilePath();
            }
        });
    }

    private updateLastActiveFilePath() {
        const activeEditor = window.activeTextEditor;
        if (activeEditor && activeEditor.document.uri.scheme === 'file') {
            this.lastActiveFilePath = normalizeDriveLetter(activeEditor.document?.uri.fsPath);
        }
    }

    public dispose() {
        this.onMessageFromWebviewDisposable?.dispose();
        this.onDidChangeViewStateDisposable?.dispose();
        getService(EntitlementService.id).removeListener(this);
        getService(ScanStatusCoordinator.id).removeListener(this);
    }

    public async parseNotification(message: NotificationMessage) {
    }

    public async initView() {
        this.view.initLoading();

        this.onMessageFromWebviewDisposable = this.view.onObjectMessageFromWebview(async message => {
            switch (message.command) {
                case 'init': {
                    const scanTypesResp = getService(ScanConfigurationService.id).getScanTypes();
                    const configList = await getService(ConfigurationService.id).getScanConfigurationList();

                    if (this.handleDetailsError([scanTypesResp?.getError(), configList.getError()], SCAN_CONFIG_VIEW_ERROR_LOAD_CONFIGS)) {
                        this.view.postObjectMessageToWebview({
                            command: 'loadComponent',
                            component: "Error",
                            props: {
                                title: "Code Sight Scan Configuration",
                                errorDetails: "Code Sight failed to initialize Scan Configuration. If the problem persists, collect the export logs and contact support.",
                                errorMessage: scanTypesResp?.getError()?.getMessage() ?? configList.getError()?.getMessage() ?? "An unknown error occurred",
                            }
                        });
                        break;
                    }

                    let groupsToLoad: ConfigGroup[] = [];
                    let selectedScanConfig: ConfigId.AsObject | undefined;
                    let selectedScanType: ScanConfig.ScanType.AsObject | undefined;
                    const scanConfig = getService(ScanConfigurationService.id).getSelectedScanConfig();
                    if (scanConfig) {
                        const scanFormResponse = await getService(ConfigurationService.id).getScanForm(scanConfig?.name);
                        if (scanFormResponse.getScanform() !== undefined) {
                            const scanForm = scanFormResponse.getScanform()!;
                            selectedScanConfig = scanForm.getConfigid()?.toObject();
                            selectedScanType = scanForm.getScantype()?.toObject();
                            groupsToLoad = this.toConfigGroups(scanForm.getGroupsList());
                            if (!scanFormResponse.hasError()) {
                                this.selectedForm = scanForm;
                            }
                        }
                    }

                    this.view.postObjectMessageToWebview({
                        command: 'loadComponent',
                        component: COMPONENT_NAME,
                        props: {
                            scanConfigs: configList.getNamesList().map(name => { return { id: name, name: name } }),
                            scanTypes: scanTypesResp ? scanTypesResp.getScantypesList().map(scanType => scanType.toObject()) : [],
                            selectedScanType,
                            groupsToLoad,
                            selectedScanConfig,
                            isScanRunning: getService(ScanService.id).isLocalViewScanRunning(),
                        } as ScanConfigViewProps
                    });
                    break;
                } case ScanConfigCommands.SELECT_SCAN_CONFIG: {
                    let [configListResp, scanFormResponse] = await Promise.all([
                        getService(ConfigurationService.id).getScanConfigurationList(),
                        getService(ConfigurationService.id).getScanForm(message.id)
                    ]);

                    if (this.handleDetailsError([scanFormResponse.getError(), configListResp.getError()], SCAN_CONFIG_VIEW_CONFIG_ACTION_FAILED(LOAD_SELECTED))) {
                        this.selectedForm = undefined;
                        break;
                    }
                    this.selectedForm = scanFormResponse.getScanform()!;

                    const configId = this.selectedForm.getConfigid()!;
                    const rootGroups = this.toConfigGroups(this.selectedForm.getGroupsList());
                   
                    this.view.postObjectMessageToWebview({
                        command: ScanConfigCommands.SELECT_SCAN_CONFIG_RESULT,
                        id: configId.toObject(),
                        scanConfigs: configListResp.getNamesList().map(name => { return { id: name, name: name } }),
                        selectedScanType: this.selectedForm.getScantype()?.toObject(),
                        groupsToLoad: rootGroups,
                    });
                    break;
                } case ScanConfigCommands.ADD_SCAN_CONFIG: {
                    const scanType: ScanConfig.ScanType.Type = message.scanType.type;

                    let scanFormResponse = await getService(ConfigurationService.id).newScanForm(scanType);
                    if (this.handleDetailsError([scanFormResponse.getError()], SCAN_CONFIG_VIEW_CONFIG_ACTION_FAILED(ADD))) {
                        this.selectedForm = undefined;
                        break;
                    }
                    this.selectedForm = scanFormResponse.getScanform()!;

                    const configId = this.selectedForm.getConfigid()!;

                    const rootGroups = this.toConfigGroups(this.selectedForm.getGroupsList());
                    this.view.postObjectMessageToWebview({
                        command: ScanConfigCommands.ADD_SCAN_CONFIG_RESULT,
                        id: configId.toObject(),
                        name: configId.getName(),
                        selectedScanType: this.selectedForm.getScantype()?.toObject(),
                        groupsToLoad: rootGroups,
                    });

                    break;
                }
                case ScanConfigCommands.DELETE_SCAN_CONFIG: {
                    let configId = new ConfigId();
                    configId.setId(message.scanConfig.id);
                    configId.setName(message.scanConfig.name);
                    configId.setLocation(message.scanConfig.location);
                    const deleteResponse = await getService(ScanConfigurationService.id).deleteScanConfiguration(configId);
                    const configList = await getService(ConfigurationService.id).getScanConfigurationList();
                    if (this.handleDetailsError([deleteResponse.getError(), configList.getError()], SCAN_CONFIG_VIEW_CONFIG_ACTION_FAILED(DELETE))) {
                        break;
                    }
                    this.selectedForm = undefined;

                    this.view.postObjectMessageToWebview({
                        command: ScanConfigCommands.DELETE_SCAN_CONFIG_RESULT,
                        scanConfigs: configList.getNamesList().map(name => { return { id: name, name: name } }),
                        id: message.scanConfig,
                    });
                    break;
                } case ScanConfigCommands.COPY_SCAN_CONFIG: {
                    const scanType: ScanConfig.ScanType.Type = message.scanType.type;
                    // create new scan config
                    let scanFormResponse = await getService(ConfigurationService.id).newScanForm(scanType);

                    if (this.handleDetailsError([scanFormResponse.getError()], SCAN_CONFIG_VIEW_CONFIG_ACTION_FAILED(COPY))) {
                        this.selectedForm = undefined;
                        break;
                    }
                    this.selectedForm = scanFormResponse.getScanform()!;

                    const configId = this.selectedForm.getConfigid()!;
                    // get config list to figure out name for the copy
                    let configListResp = await getService(ConfigurationService.id).getScanConfigurationList();
                    if (this.handleStatusError([configListResp.getError()])) {
                        break;
                    }
                    let configCopies = [];
                    configListResp.getNamesList().forEach(name => {
                        if (name.startsWith(`${message.scanConfig.name}-copy`)) {
                            configCopies.push(name)
                        }
                    });
                    configId.setName(`${message.scanConfig.name}-copy${configCopies.length > 0 ? `-${configCopies.length}` : ""}`);

                    // update additional fields values and store config
                    let configGroups : ScanForm.ConfigGroup[] = [];
                    configGroups = this.updateScanFormFields(this.selectedForm.getGroupsList(), message.configGroups);

                    const storeConfigResp = await getService(ConfigurationService.id).storeScanForm(configId, this.selectedForm.getScantype(), configGroups);
                    configListResp = await getService(ConfigurationService.id).getScanConfigurationList();

                    if (this.handleStatusError([configListResp.getError(), storeConfigResp.getError()])) {
                        break;
                    }

                    this.selectedForm = storeConfigResp.getScanform()!;
                    const updateConfigId = this.selectedForm.getConfigid()!;
                    const rootGroups = this.toConfigGroups(this.selectedForm.getGroupsList());

                    this.view.postObjectMessageToWebview({
                        command: ScanConfigCommands.COPY_SCAN_CONFIG_RESULT,
                        scanConfigs: configListResp.getNamesList().map(name => { return { id: name, name: name } }),
                        selectedScanType: this.selectedForm.getScantype()?.toObject(),
                        id: updateConfigId.toObject(),
                        name: updateConfigId.getName(),
                        groupsToLoad: rootGroups,
                    });

                    break;
                } case ScanConfigCommands.UPDATE_SCAN_CONFIG: {
                    // Save config changes
                    const success = await this.saveScanConfigAndNotify(message);
                    if (!success) {
                        break;
                    }
                    break;
                } case ScanConfigCommands.APPLY_AND_SCAN_CONFIG: {
                    const success = await this.saveScanConfigAndNotify(message);
                    if (!success) {
                        break;
                    }

                    const updateConfigId = this.selectedForm!.getConfigid()!;
                    await getService(ScanConfigurationService.id).setSelectedScanConfig(updateConfigId.getName());
                    
                    const scanConfig = getService(ScanConfigurationService.id).getSelectedScanConfig();
                    if (scanConfig) {
                        // Build file paths based on scan scope
                        let filePaths: string[] = [];
                        if (scanConfig.scope === ScanConfig.ScanMode.Mode.ACTIVEFILE) {
                            this.updateLastActiveFilePath();
                            if (!this.lastActiveFilePath) {
                                this.view.postObjectMessageToWebview({
                                    command: ScanConfigCommands.UPDATE_STATUS,
                                    detail: SCAN_CONFIG_VIEW_NO_ACTIVE_FILE,
                                });
                                break;
                            }
                            filePaths.push(this.lastActiveFilePath);
                        } else {
                            // FULLSCOPE
                            const folders = workspace.workspaceFolders;
                            if (folders) {
                                folders.forEach(folder => {
                                    filePaths.push(normalizeDriveLetter(folder.uri.fsPath));
                                });
                            } else {
                                this.view.postObjectMessageToWebview({
                                    command: ScanConfigCommands.UPDATE_STATUS,
                                    detail: SCAN_CONFIG_VIEW_NO_WORKSPACE,
                                });
                                break;
                            }
                        }

                        await getService(LocalViewIssuesListService.id).setCachedSelectedResultType(scanConfig.scanType);
                        await getService(LocalViewIssuesListService.id).clearIssues();
                        await getService(IssueSelectionService.id).clearSelection(IssuesListIdentifier.LocalViewIssuesList);
                        await getService(LocalViewIssueListFilterService.id).resetSearchFilter();
                        
                        try {
                            const scopeDesc = scanConfig.scope === ScanConfig.ScanMode.Mode.ACTIVEFILE ? 'active file' : 'workspace';
                            getLogger().info(`Triggering ${scopeDesc} scan with config: ${scanConfig.name}`);
                            const scanResponse = await getService(ScanService.id).requestScanForConfig(scanConfig, filePaths);
                            
                            if (scanResponse) {
                                const status = scanResponse.getStatus();
                                if (status && status.getStatus() === RefreshStatus.Status.FAILED) {
                                    getLogger().warn(`Scan failed with reason: ${status.getReason()}`);
                                    
                                    this.view.postObjectMessageToWebview({ 
                                        command: ScanConfigCommands.UPDATE_STATUS,
                                        detail: SCAN_CONFIG_VIEW_SCAN_FAILED(status.getReason()?.toString() || 'Unknown error'),
                                    });
                                }
                            }
                        } catch (error) {
                            getLogger().error(`Failed to trigger scan: ${error}`);
                            const errorMessage = error && typeof error === 'object' && 'message' in error 
                                ? (error as any).message 
                                : String(error);
                            
                            this.view.postObjectMessageToWebview({
                                command: ScanConfigCommands.UPDATE_STATUS,
                                detail: SCAN_CONFIG_VIEW_SCAN_TRIGGER_FAILED(errorMessage),
                            });
                        }
                    }
                    break;
                } case ScanConfigCommands.CONFIGURE_SOURCE: {
                    if (this.selectedForm === undefined) {
                        break;
                    }
                    const sourcePicker = new SourcePicker(message.configItemLabel, async (_: SourceType, remoteRef: RemoteReference) => {
                        let issueSource = new IssueSource();
                        issueSource.setReference(remoteRef);
                        this.issueSources.set(message.configItemId, issueSource);
                        this.view.postObjectMessageToWebview({
                            command: ScanConfigCommands.CONFIGURE_SOURCE_RESULT,
                            id: message.configItemId,
                            value: getRemoteReferenceDisplayString(remoteRef),
                        });
                    });
                    if (this.selectedForm.getScantype()) {
                        await sourcePicker.showConfigurationMenu(new SourceType(undefined,  this.selectedForm.getScantype()!, GetIssueSourceStructureRequest.Context.SCAN));
                    }
                    break;
                } case FilePickerCommands.ON_CLICK_BROWSE: 
                    const filePath: string = await onBrowse(message.type);
                    if (filePath) {
                        this.view.postObjectMessageToWebview({
                            command: FilePickerCommands.BROWSE_RESULT,
                            id: message.id,
                            value: filePath,
                        });
                    }
                    break;
                case 'openScanToolConfig':
                    await commands.executeCommand(OPEN_INSTALLED_TOOLS_MSG_COMMAND_ID);
                    break;
            }
        });

        this.view.initHtml();
    }

    private async saveScanConfigAndNotify(message: any): Promise<boolean> {
        if (this.selectedForm === undefined) {
            return false;
        }
        
        const configId = this.selectedForm.getConfigid()!;
        let updatedGroups: ScanForm.ConfigGroup[] = [];
        updatedGroups = this.updateScanFormFields(this.selectedForm.getGroupsList(), message.configGroups);
        configId.setName(message.name);
        const storeConfigResp = await getService(ConfigurationService.id).storeScanForm(configId, this.selectedForm.getScantype(), updatedGroups);
        const configListResp = await getService(ConfigurationService.id).getScanConfigurationList();
        
        if (this.handleStatusError([configListResp.getError(), storeConfigResp.getError()])) {
            return false;
        }
        
        this.selectedForm = storeConfigResp.getScanform()!;
        const updateConfigId = this.selectedForm.getConfigid()!;

        this.view.postObjectMessageToWebview({
            command: ScanConfigCommands.UPDATE_SCAN_CONFIG_RESULT,
            scanConfigs: configListResp.getNamesList().map(name => { return { id: name, name: name } }),
            id: updateConfigId.toObject(),
            name: updateConfigId.getName(),
            groupsToLoad: this.toConfigGroups(this.selectedForm.getGroupsList()),
        });
        
        return true;
    }
    

    private handleDetailsError(errors: (Error | undefined)[], title: string): boolean {
        for (const error of errors) {
            if (error) {
                getLogger().error(`An error occurred ${error.getCode()}: ${error.getMessage()}`);
                this.view.postObjectMessageToWebview({
                    command: ScanConfigCommands.UPDATE_DETAILS_MESSAGE,
                    title: title,
                    detail: SCAN_CONFIG_VIEW_ERROR_DETAILS,
                    errorDetail: error.getMessage(),
                });
                return true;
            }
        }
        return false;
    }

    private handleStatusError(errors: (Error | undefined)[]): boolean {
        for (const error of errors) {
            if (error) {
                getLogger().error(`An error occurred ${error.getCode()}: ${error.getMessage()}`);
                this.view.postObjectMessageToWebview({
                    command: ScanConfigCommands.UPDATE_STATUS,
                    detail: error.getMessage(),
                });
                return true;
            }
        }
       
        return false;
    }

    async onEntitlementsChanged(): Promise<void> {
        const scanTypesResp = await getService(ConfigurationService.id).getScanTypes();
        this.view.postObjectMessageToWebview({
            command: ScanConfigCommands.REFRESH_SCAN_TYPES,
            scanTypes: scanTypesResp.getScantypesList().map(scanType => scanType.toObject()),
        });
    }

    async onScanResultReceived(notificationStatus: RefreshStatus): Promise<void> {
        this.view.postObjectMessageToWebview({
            command: ScanConfigCommands.UPDATE_SCAN_RUNNING_STATUS,
            props: {
                isScanRunning: getService(ScanService.id).isLocalViewScanRunning()
            }
        });
    }

    private updateScanFormFields(scanFormGroupList: ScanForm.ConfigGroup[], reactGroups: ConfigGroup[]): ScanForm.ConfigGroup[] {
        const flattedGroups = this.flattenReactGroups(reactGroups);
        const updateFields = (groups: ScanForm.ConfigGroup[]) => {
            groups.forEach(group => {
                group.getFieldsList().forEach(field => {
                    field.getValue()?.setSource(undefined);
                    switch (field.getDisplaykind()) {
                        case DisplayKind.FILE:
                        case DisplayKind.DIRECTORY:
                        case DisplayKind.TEXT:
                        case DisplayKind.SCOPE: {
                            if (flattedGroups[field.getId()] != undefined) {
                                field.getValue()?.setValue(flattedGroups[field.getId()][0]);
                            }
                            break;
                        }
                        case DisplayKind.SOURCE: {
                            field.getValue()?.setIssuesource(this.issueSources.get(field.getId()));
                            break;
                        }
                        case DisplayKind.MULTISELECT:
                        case DisplayKind.SINGLESELECT: {
                            field.getValue()?.getChildrenList().forEach(child => {
                                if (flattedGroups[field.getId()].includes(child.getDisplayvalue())) {
                                    child.setSelectionstate(ScanForm.ConfigValue.SelectionState.SELECTED);
                                } else {
                                    child.setSelectionstate(ScanForm.ConfigValue.SelectionState.UNSELECTED);
                                }
                            });
                            break;
                        }
                    }
                });
                updateFields(group.getChildrenList());
            });
        };
    
        updateFields(scanFormGroupList);

        return scanFormGroupList;
    }

    private flattenReactGroups(reactGroups: ConfigGroup[]): { [key: string]: string[] } {
        let itemsMap: { [key: string]: string[] } = {};
      
        const addItems = (groups: ConfigGroup[]) => {
            groups.forEach(group => {
              group.configItems.forEach(item => {
                itemsMap[item.id] = item.values;
              });
        
            addItems(group.configGroups);
            });
          };

        addItems(reactGroups);

        return itemsMap;
    }

    private toConfigGroups(groupsList: ScanForm.ConfigGroup[]): ConfigGroup[] {
        let configGroups: ConfigGroup[] = [];
        groupsList.forEach(group => {
            configGroups.push({
                expanded: group.getExpanded(),
                name: group.getName(),
                configItems: this.toConfigItems(group.getFieldsList()),
                configGroups: this.toConfigGroups(group.getChildrenList())
            } as ConfigGroup);
        })

        return configGroups;
    }

    private getHintText(hint: string, docUrl?: string): string {
        if (docUrl) {
            return `${hint}\n\n[Learn more](${docUrl})`;
        }
        return hint;
    }

    private toConfigItems(fields: ScanForm.ConfigField[]): ConfigItem[] {
        let configItems: ConfigItem[] = [];
        fields.forEach(field => {
            let result = this.convertValueForKind(field.getValue(), field.getDisplaykind());
            this.issueSources.set(field.getId(), field.getValue()?.getIssuesource());
            configItems.push({
                id: field.getId(),
                label: field.getDisplayname(),
                required: field.getRequired(),
                type: field.getDisplaykind(),
                hintText: this.getHintText(field.getHinttext(), field.getDocurl()),
                values: result.values,
                options: result.options,
                optionWarnings: result.optionWarnings
            } as ConfigItem);
        });

        return configItems;
    }

    private convertValueForKind(configValue: ScanForm.ConfigValue | undefined, displayKind: DisplayKind): { values: string[], options: string[], optionWarnings: { [key: string]: string } } {
        if (!configValue) {
            return { values: [""], options: [], optionWarnings: {} };
        } else {
            let values: string[] = [];
            let options: string[] = [];
            let optionWarnings: { [key: string]: string } = {};
            switch (displayKind) {
                case DisplayKind.FILE:
                case DisplayKind.DIRECTORY:
                case DisplayKind.TEXT:
                case DisplayKind.SCOPE: {
                    values.push(configValue.getValue());
                    break;
                }
                case DisplayKind.SOURCE:{
                    values.push(getRemoteReferenceDisplayString(configValue.getIssuesource()?.getReference()) || "");
                    break;
                }
                case DisplayKind.SINGLESELECT:
                case DisplayKind.MULTISELECT: {
                    configValue.getChildrenList().forEach(child => {
                        options.push(child.getDisplayvalue());
                        if (child.getSelectionstate() === ScanForm.ConfigValue.SelectionState.SELECTED) {
                            values.push(child.getDisplayvalue());
                        }
                        const warningMessage = child.getValue();
                        if (warningMessage && warningMessage.trim() !== '') {
                            optionWarnings[child.getDisplayvalue()] = warningMessage;
                        }
                    });
                    break;
                }
            }
            return { values, options, optionWarnings };
        }
    }
}