import { AnalysisContext } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_context_pb";
import { MonitorEventNotificationRequest, MonitorResultsNotification, MonitorResultsRequest, SyncAnalysisContextRequest, SyncAnalysisContextResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_service_pb";
import { LicensedToolsConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/licensed_tools_config_pb";
import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { GetGitInfoRequest, SetupToolRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/tool_service_pb";
import { ClientReadableStream } from "@grpc/grpc-js";
import { getLogger } from "../utils/logger";
import { isSetupCompleteState, isSetupMessage, isUntrustedCertificateMessage } from "../utils/notificationMessageUtils";
import { AnalysisContextService } from "./analysisContextService";
import { ControllerClientService } from "./controllerClientService";
import { WarningMessageService } from "./extensionMessageService";
import { GitInfoService } from "./gitInfoService";
import { ProgressNotificationService } from "./progressNotificationService";
import { ScanService } from "./scanService";
import { ServiceId, getService } from "./serviceContainer";
import { SetupService } from "./setupService";
import { ToolStateService } from "./toolStateService";
import { ViewProviderService } from "./viewProviderService";
import { WorkspaceService } from "./workspaceService";

/**
 * This service manages observers for use with the controller AnalysisService
 */
export abstract class AnalysisContextObservationService {
    static readonly id: ServiceId<AnalysisContextObservationService> = { id: AnalysisContextObservationService.name };

    /**
     * Creates an observer for the current context if one does not already exist.
     */
    abstract observeCurrentContext(): Promise<void>;

    /**
     * This will sync the current context with the controller
     */
    abstract syncContext(): Promise<void>;

    /**
     * Fetches and caches git repository status for a specific folder path.
     */
    abstract fetchGitInfoForFolder(folderPath: string): Promise<void>;
}

export class AnalysisContextObservationServiceImpl extends AnalysisContextObservationService {
    private observers: Map<string, ClientReadableStream<MonitorResultsNotification>>;
    private messageObservers: Map<string, ClientReadableStream<NotificationMessage>>;
    private delayTimeoutId: NodeJS.Timeout | undefined;
    readonly DELAY_TIMEOUT = 200;

    constructor() {
        super();
        this.observers = new Map<string, ClientReadableStream<MonitorResultsNotification>>();
        this.messageObservers = new Map<string, ClientReadableStream<NotificationMessage>>();
    }

    async observeCurrentContext() {
        const logger = getLogger();
        let contextId = getService(AnalysisContextService.id).getAnalysisContextId();
        let resultsObserved = this.observers.has(contextId.getValue());
        let messagesObserved = this.messageObservers.has(contextId.getValue());

        if (resultsObserved && messagesObserved) {
            // Everything observed, nothing to do
            return;
        }

        let context = await this.doSyncContext();

        let analysisServiceClient = await getService(ControllerClientService.id).getAnalysisServiceClient();

        if (!resultsObserved) {
            let monitorResultsRequest = new MonitorResultsRequest();
            monitorResultsRequest.setContextid(contextId);

            let stream = await analysisServiceClient.monitorResults(monitorResultsRequest);
            this.addMonitorResultsListeners(stream, contextId, this);
            this.observers.set(contextId.getValue(), stream);

            logger.debug(`Observing monitor results for ${contextId.getValue()}`);
        }

        if (!messagesObserved) {
            let monitorEventNotificationRequest = new MonitorEventNotificationRequest();
            monitorEventNotificationRequest.setContextid(contextId);

            let stream = await analysisServiceClient.monitorNotifications(monitorEventNotificationRequest);
            this.addNotificationMessageListeners(stream, contextId, this);
            this.messageObservers.set(contextId.getValue(), stream);

            logger.debug(`Observing notification messages for ${contextId.getValue()}`);
        }

        await this.setupTools(context);
        await this.fetchGitInfo(context);
        await this.fetchGitInfoForWorkspaceFolders();
    }

    async syncContext() {
        let context = await this.doSyncContext();
        await this.setupTools(context);
        await this.fetchGitInfo(context);
        await this.fetchGitInfoForWorkspaceFolders();
    }

    stopObserving() {
        this.observers.forEach((value: ClientReadableStream<MonitorResultsNotification>, key: string) => {
            value.cancel();
        });

        this.messageObservers.forEach((value: ClientReadableStream<NotificationMessage>, key: string) => {
            value.cancel();
        });
    }

    private async doSyncContext() {
        let analysisServiceClient = await getService(ControllerClientService.id).getAnalysisServiceClient();
        let context = getService(AnalysisContextService.id).buildAnalysisContext();

        let syncAnalysisContextRequest = new SyncAnalysisContextRequest();
        syncAnalysisContextRequest.setContext(context);

        let syncAnalysisContextResponse = await analysisServiceClient.syncAnalysisContext(syncAnalysisContextRequest);

        if (syncAnalysisContextResponse.getStatus() === SyncAnalysisContextResponse.Status.FAILED) {
            getLogger().warn(`Failed to sync context ${context.getRef()!.getId()!.getValue()}`);
        }

        return context;
    }


    private addNotificationMessageListeners(stream: ClientReadableStream<NotificationMessage>, contextId: AnalysisContext.Id, parent: AnalysisContextObservationServiceImpl) {
        const logger = getLogger();
        stream.on('data', async (notificationMessage: NotificationMessage) => {
            if (isUntrustedCertificateMessage(notificationMessage)) {
                await getService(WarningMessageService.id).warnUntrustedCertificate(notificationMessage);
            } else {
                // update tool/download state if it has changed
                if (isSetupMessage(notificationMessage)) {
                    if (isSetupCompleteState(notificationMessage)) {
                        await getService(ToolStateService.id).updateToolState(notificationMessage);
                    }
                }

                await getService(SetupService.id).parseNotificationMessage(notificationMessage);

                await getService(ViewProviderService.id).getOrCreateExtensionStatusPresenter().parseNotificationMessage(notificationMessage);
                }
        });

        stream.on('error', (err: Error) => {
            logger.warn(`Error occurred while processing notification messages: ${err}`);
        });

        stream.on('end', () => {
            parent.observers.delete(contextId.getValue());
        });

        stream.on('close', () => {
            parent.observers.delete(contextId.getValue());
        });
    }

    private addMonitorResultsListeners(stream: ClientReadableStream<MonitorResultsNotification>, contextId: AnalysisContext.Id, parent: AnalysisContextObservationServiceImpl) {

        stream.on('data', async (notification: MonitorResultsNotification) => {
            const notificationStatus = notification.getStatus();
            if (!notificationStatus) {
                return;
            }

            await getService(ProgressNotificationService.id).updateScanProgress(notification);
            await getService(ViewProviderService.id).getOrCreateExtensionStatusPresenter().parseResultsMessage(notification);
            await getService(ScanService.id).parseResultsMessage(notification);
        });

        stream.on('error', (err: Error) => {
            getLogger().warn(`Error occurred while processing notification results: ${err}`);
        });

        stream.on('end', () => {
            getLogger().info(`Results notifications for ${contextId.getValue()} have ended`);
            parent.messageObservers.delete(contextId.getValue());
        });

        stream.on('close', () => {
            getLogger().info(`Results notifications channel for ${contextId.getValue()} has closed`);
            parent.messageObservers.delete(contextId.getValue());
        });
    }

    async fetchGitInfoForFolder(folderPath: string): Promise<void> {
        const request = new GetGitInfoRequest();
        request.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        request.setProjectrootpath(folderPath);

        const toolClient = await getService(ControllerClientService.id).getToolServiceClient();
        const response = await toolClient.getGitInfo(request);

        const gitInfo = response.getGitinfo();
        if (gitInfo) {
            getService(GitInfoService.id).setGitRepositoryStatus(
                folderPath,
                gitInfo.getIsgitrepository()
            );
        }
    }

    private async fetchGitInfoForWorkspaceFolders(): Promise<void> {
        const workspaceFolders = getService(WorkspaceService.id).getWorkspaceFolders();
        await Promise.all(workspaceFolders.map(folder => this.fetchGitInfoForFolder(folder.uri.fsPath)));
    }

    private async fetchGitInfo(context: AnalysisContext) {
        const request = new GetGitInfoRequest();
        request.setContextid(context.getRef()!.getId());
        request.setProjectrootpath(context.getContextroot());

        const toolClient = await getService(ControllerClientService.id).getToolServiceClient();
        const response = await toolClient.getGitInfo(request);

        const gitInfo = response.getGitinfo();
        if (gitInfo) {
            getService(GitInfoService.id).setGitRepositoryStatus(
                context.getContextroot(),
                gitInfo.getIsgitrepository()
            );
        }

        return response;
    }

    private async setupTools(context: AnalysisContext) {
        let setupToolsRequest = new SetupToolRequest();
        setupToolsRequest.setProjectrootpath(context.getContextroot());
        setupToolsRequest.setContextid(context!.getRef()!.getId());
        setupToolsRequest.setIsdryrun(true); // tool download should go through onboarding

        // setup classic tools
        setupToolsRequest.setToolList([LicensedToolsConfig.Type.BLACKDUCK, LicensedToolsConfig.Type.COVERITY, LicensedToolsConfig.Type.SIGMA]);

        let toolClient = await getService(ControllerClientService.id).getToolServiceClient();
        return toolClient.setupTools(setupToolsRequest);
    }
}