import { TestServerConnectionResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/configuration_service_pb";
import { CheckLicenseResponse, GetEntitlementsRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/license_service_pb";
import { ServerType } from "@codesight/codesight-controller-proto/controller_proto/v0/server_info_pb";
import { CsseLicenseInfo } from "../models/csseLicenseInfo";
import { Authentication, Entitlement } from '../models/entitlement';
import { getService, ServiceId } from "../services/serviceContainer";
import { getLogger } from "../utils/logger";
import { nullableComparison } from "../utils/utils";
import { AnalysisContextService } from "./analysisContextService";
import { AuthenticationService, AuthenticationServiceListener } from "./authenticationService";
import { ControllerClientService } from "./controllerClientService";
import { SetupServiceListener } from "./setupService";
import { ToolStateEnum, ToolStateService, ToolStateServiceListener, ToolTypeEnum } from "./toolStateService";

export abstract class EntitlementService {
	static readonly id: ServiceId<EntitlementService> = { id: EntitlementService.name };

	abstract init(): Promise<void>;

	abstract checkEntitlements(): Promise<void>;

	abstract getCachedProductEntitlement(): Entitlement;

	abstract addListener(listener: EntitlementServiceListener): void;

	abstract removeListener(listener: EntitlementServiceListener): void;
}

export interface EntitlementServiceListener {
	onEntitlementsChanged(entitlementsChanged: EntitlementsChanged): Promise<void>;
}

export interface EntitlementsChanged {
	didCsseEntitlementChange: boolean;
	didCoverityEntitlementChange: boolean;
	didBlackDuckEntitlementChange: boolean;
	didPolarisEntitlementChange: boolean;
	didSRMEntitlementChange: boolean;
	didScaEntitlementChange: boolean;
	didSastEntitlementChange: boolean;
	didSignalEntitlementChange: boolean;

	didCsseLicenseInfoChange: boolean;

	didSigmaReadyToScanChange: boolean;
	didBlackDuckReadyToScanChange: boolean;
	didCoverityReadyToScanChange: boolean;

	didCoverityAuthenticationChange: boolean;
	didBlackDuckAuthenticationChange: boolean;
}

function didSomeEntitlementChanged(e: EntitlementsChanged): boolean {
	return (e.didCsseEntitlementChange === true ||
		e.didCoverityEntitlementChange === true ||
		e.didBlackDuckEntitlementChange === true ||
		e.didPolarisEntitlementChange === true ||
		e.didSRMEntitlementChange === true ||
		e.didScaEntitlementChange === true ||
		e.didSastEntitlementChange === true ||
		e.didSignalEntitlementChange === true ||
		e.didCsseLicenseInfoChange === true ||
		e.didSigmaReadyToScanChange === true ||
		e.didBlackDuckReadyToScanChange === true ||
		e.didCoverityReadyToScanChange === true ||
		e.didCoverityAuthenticationChange === true ||
		e.didBlackDuckAuthenticationChange === true);
}

export class EntitlementServiceImpl implements EntitlementService, ToolStateServiceListener, AuthenticationServiceListener, SetupServiceListener {

	protected entitlementListeners: EntitlementServiceListener[];
	entitlement: Entitlement;

	constructor() {
		this.entitlementListeners = [];
		this.entitlement = Entitlement.createDefault();

		getService(ToolStateService.id).addListener(this);
		getService(AuthenticationService.id).addListener(this);
	}

	public async init() {
		getLogger().info("Initializing EntitlementService...");
		await this.checkEntitlements();
	}

	async checkEntitlements(): Promise<void> {
		let licenseServiceClient = await getService(ControllerClientService.id).getLicenseServiceClient();
		let analysisContextService = getService(AnalysisContextService.id);

		let entitlementRequest = new GetEntitlementsRequest();
		entitlementRequest.setId(analysisContextService.getAnalysisContextId());
		let resp = await licenseServiceClient.getEntitlementRequest(entitlementRequest);

		let products = resp.getProducts();
		let features = resp.getFeatures();
		let tools = resp.getTools();

		let covAuth;
		{
			let coverityInfo = tools?.getCoverityinfo();
			let serverInfo = coverityInfo?.getServer();
			let serverConnectionState = coverityInfo?.getServerconnectionstate();
			if (tools &&
				tools.hasCoverityinfo() &&
				coverityInfo &&
				coverityInfo.hasServer() &&
				serverInfo &&
				coverityInfo.hasServerconnectionstate() &&
				serverConnectionState
			) {
				let type = serverInfo.getType();
				let url = serverInfo.getUrl();
				let isConnectionStatusSuccess = serverConnectionState.getServerconnectionstatus() === TestServerConnectionResponse.Status.SUCCESS;
				covAuth = new Authentication(type, url, isConnectionStatusSuccess);
			}
		}

		let bdAuth;
		{
			let blackDuckInfo = tools?.getBlackduckinfo();
			let serverInfo = blackDuckInfo?.getServer();
			let serverConnectionState = blackDuckInfo?.getServerconnectionstate();
			if (tools &&
				tools.hasCoverityinfo() &&
				blackDuckInfo &&
				blackDuckInfo.hasServer() &&
				serverInfo &&
				blackDuckInfo.hasServerconnectionstate() &&
				serverConnectionState
			) {
				let type = serverInfo.getType();
				let url = serverInfo.getUrl();
				let isConnectionStatusSuccess = serverConnectionState.getServerconnectionstatus() === TestServerConnectionResponse.Status.SUCCESS;
				bdAuth = new Authentication(type, url, isConnectionStatusSuccess);
			}
		}

		let csseLicenseInfo;
		let csseEntitlementInfo = products?.getCodesightstandardeditionentitlement()?.getEntitlementinfo();
		let hasCsseEntitlement = csseEntitlementInfo?.getEntitled();
		{
			let csseLicense = csseEntitlementInfo?.getLicense();
			let expiry = csseLicense?.getExpiry();

			if (csseEntitlementInfo !== undefined &&
				hasCsseEntitlement !== undefined &&
				csseLicense !== undefined) {
				csseLicenseInfo = new CsseLicenseInfo(csseLicense.getIstrial(), hasCsseEntitlement, expiry, csseLicense.getState());
			} else {
				csseLicenseInfo = new CsseLicenseInfo(false, false, undefined, CheckLicenseResponse.LicenseState.NOLICENSE);
			}

		}

		let hasCoverityEntitlement = products?.getCoverityentitlement()?.getEntitlementinfo()?.getEntitled() ?? false;
		let hasBlackduckEntitlement = products?.getBlackduckentitlement()?.getEntitlementinfo()?.getEntitled() ?? false;
		let hasPolarisEntitlement = products?.getPolarisentitlement()?.getEntitlementinfo()?.getEntitled() ?? false;
		let hasSRMEntitlement = products?.getSoftwareriskmanagerentitlement()?.getEntitlementinfo()?.getEntitled() ?? false;
		let hasRapidScanScaEntitlement = features?.getRapidscanscaentitlement()?.getInfo()?.getEntitled() ?? false;
		let hasRapidScanStaticEntitlement = features?.getRapidscanstaticentitlement()?.getInfo()?.getEntitled() ?? false;
		let hasSignalEntitlement = products?.getSignalentitlement()?.getEntitlementinfo()?.getEntitled() ?? false;
		let hasSnippetScanEntitlement = features?.getSnippetscanentitlement()?.getInfo()?.getEntitled() ?? false;
		let hasCoverity = tools?.getCoverityinfo()?.hasTool() ?? false;
		let hasSigma = tools?.getSigmainfo()?.hasTool() ?? false;
		let hasBlackDuck = tools?.getBlackduckinfo()?.hasTool() ?? false;

		let newEntitlement = new Entitlement(hasCsseEntitlement ?? false, csseLicenseInfo, hasCoverityEntitlement,
			hasBlackduckEntitlement, hasPolarisEntitlement, hasSRMEntitlement, hasRapidScanScaEntitlement, hasRapidScanStaticEntitlement, hasSignalEntitlement, hasSnippetScanEntitlement, hasCoverity,
			hasSigma, hasBlackDuck, covAuth, bdAuth);

		let entitlementsChanged = {
			didCsseEntitlementChange: this.entitlement?.isCsseEntitled() !== newEntitlement.isCsseEntitled(),
			didCoverityEntitlementChange: this.entitlement?.isCoverityEntitled() !== newEntitlement.isCoverityEntitled(),
			didBlackDuckEntitlementChange: this.entitlement?.isBlackDuckEntitled() !== newEntitlement.isBlackDuckEntitled(),
			didPolarisEntitlementChange: this.entitlement?.isPolarisEntitled() !== newEntitlement.isPolarisEntitled(),
			didSRMEntitlementChange: this.entitlement?.isSRMEntitled() !== newEntitlement.isSRMEntitled(),
			didScaEntitlementChange: this.entitlement?.isSCAEntitled() !== newEntitlement.isSCAEntitled(),
			didSastEntitlementChange: this.entitlement?.isSASTEntitled() !== newEntitlement.isSASTEntitled(),
			didSignalEntitlementChange: this.entitlement?.isSignalEntitled() !== newEntitlement.isSignalEntitled(),

			didCsseLicenseInfoChange: !nullableComparison(this.entitlement?.getCsseLicense(), newEntitlement.getCsseLicense()),

			didSigmaReadyToScanChange: this.entitlement?.isSigmaReadyToScan() !== newEntitlement.isSigmaReadyToScan(),
			didBlackDuckReadyToScanChange: this.entitlement?.isBlackDuckReadyToScan() !== newEntitlement.isBlackDuckReadyToScan(),
			didCoverityReadyToScanChange: this.entitlement?.isCoverityReadyToScan() !== newEntitlement.isCoverityReadyToScan(),

			didCoverityAuthenticationChange: !nullableComparison(this.entitlement?.getCoverityAuthentication(), newEntitlement.getCoverityAuthentication()),
			didBlackDuckAuthenticationChange: !nullableComparison(this.entitlement?.getBlackDuckAuthentication(), newEntitlement.getBlackDuckAuthentication()),
		};

		this.entitlement = newEntitlement;

		if (didSomeEntitlementChanged(entitlementsChanged)) {
			await this.notifyEntitlementsChanged(entitlementsChanged);
		}
	}

	getCachedProductEntitlement(): Entitlement {
		return this.entitlement;
	}

	addListener(listener: EntitlementServiceListener): void {
		this.entitlementListeners.push(listener);
	}

	removeListener(listener: EntitlementServiceListener): void {
		let index = this.entitlementListeners.indexOf(listener);
		if (index >= 0) {
			this.entitlementListeners.splice(index, 1);
		}
	}

	async notifyEntitlementsChanged(entitlementsChanged: EntitlementsChanged): Promise<void> {
		let promises: Promise<void>[] = [];
		this.entitlementListeners.forEach((listener) => {
			promises.push(listener.onEntitlementsChanged(entitlementsChanged));
		});
		await Promise.all(promises);
	}

	async onToolStateChanged(toolType: ToolTypeEnum, toolState: ToolStateEnum, toolVersion: string): Promise<void> {
		await this.checkEntitlements();
	}

	async onAuthenticated(serverType: ServerType): Promise<void> {
		await this.checkEntitlements();
	}

	async onOnboardingComplete(): Promise<void> {
		await this.checkEntitlements();
	}

	async onSuggestedToolVersionChanged(tooltype: ToolTypeEnum, suggestedVersion: string): Promise<void> {
	}
}