import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { Command, commands, Disposable, TreeView } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { getService } from "../../services/serviceContainer";
import { SetupService } from "../../services/setupService";
import { VscodeContextService } from "../../services/vscodeContextService";
import { COMMAND_OPEN_CUSTOM_WORKING_DIR } from "../../utils/constants";
import { getOpenFolderCommand } from "../../utils/environmentUtils";
import { CodeSightSetupTreeItem, CodeSightSetupTreeProvider } from "./codeSightSetupTreeProvider";

const localize: LocalizeFunc = loadMessageBundle();

export const SECTION_SEPARATOR = "\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014";
export const OPEN_SETUP_WEBVIEW_COMMAND_ID = "codesight.setup.view.open.webview";

export enum SetupStepStatus {
    NotApplicable,
    Unstarted,
    Installing,
    Success,
    Failed,
    Skipped
}

export interface SetupViewSteps {
    createTrialAccount : SetupStepStatus;
    downloadSigma : SetupStepStatus;
    downloadCoverity: SetupStepStatus;
    connectToBlackduckServer: SetupStepStatus;
    downloadBlackduck: SetupStepStatus;
    connectToCoverityServer: SetupStepStatus;
} 

export class CodeSightSetupPresenter{

    treeProvider: CodeSightSetupTreeProvider;
    treeView: TreeView<CodeSightSetupTreeItem>;
    commandDisposables: Disposable[];

    constructor(treeProvider: CodeSightSetupTreeProvider, treeView: TreeView<CodeSightSetupTreeItem>) {
        this.treeProvider = treeProvider;
        this.treeView = treeView;
        this.commandDisposables = [];
        this.initCommands();
    }

    showCustomWorkingDirNeededState() {
        let treeItems: CodeSightSetupTreeItem[] = [];
        let treeItemChildrenMap = new Map<CodeSightSetupTreeItem, CodeSightSetupTreeItem[]>();
        const header = new CodeSightSetupTreeItem(localize("setup.view.no.working.dir1", "Choose a Working Directory"));
        header.iconPath = getService(VscodeContextService.id).getIconPath("severity-high.svg", "severity");
        treeItems.push(header);
        [
            localize("setup.view.no.working.dir2", "Code Sight is unable to access"),
            localize("setup.view.no.working.dir3", "its working directory."),
            localize("setup.view.no.working.dir4", "Configure a new working directory"),
            localize("setup.view.no.working.dir5", "to start scanning files."),
        ].forEach(message =>{
            let item = new CodeSightSetupTreeItem("");
            item.description = message;
            treeItems.push(item);
        });
        const configureWorkingDir = new CodeSightSetupTreeItem(localize("setup.view.working.dir.button", "[Configure]"));
        configureWorkingDir.command = {
            command: COMMAND_OPEN_CUSTOM_WORKING_DIR,
            title: "configure working dir", // Not user facing
        };
        treeItems.push(configureWorkingDir);
        this.treeProvider.setItems(treeItems, treeItemChildrenMap);
    }

    showEmptyWorkspaceState() {
        let treeItems: CodeSightSetupTreeItem[] = [];
        let treeItemChildrenMap = new Map<CodeSightSetupTreeItem, CodeSightSetupTreeItem[]>();
        const header = new CodeSightSetupTreeItem(localize("setup.view.no.workspace1", "No Folder Has Been Opened"));
        header.iconPath = getService(VscodeContextService.id).getIconPath("severity-low.svg", "severity");
        treeItems.push(header);
        [
            localize("setup.view.no.workspace2", "To scan files with Code Sight"),
            localize("setup.view.no.workspace3", "you need to open a source-code"),
            localize("setup.view.no.workspace4", "folder or workspace."),
        ].forEach(message =>{
            let item = new CodeSightSetupTreeItem("");
            item.description = message;
            treeItems.push(item);
        });
        const openFolderButton = new CodeSightSetupTreeItem(localize("setup.view.open.folder.button", "[Open Folder]"));
        openFolderButton.command = {
            command: getOpenFolderCommand(),
            title: "Open folder", // Not user facing
        };
        treeItems.push(openFolderButton);
        this.treeProvider.setItems(treeItems, treeItemChildrenMap);
    }

    showInitialLoadingState() {
        let treeItems: CodeSightSetupTreeItem[] = [];
        let treeItemChildrenMap = new Map<CodeSightSetupTreeItem, CodeSightSetupTreeItem[]>();
        const header = new CodeSightSetupTreeItem(
            localize("setup.view.loading", "Code Sight Loading"));
        header.iconPath = getService(VscodeContextService.id).getIconPath("severity-low.svg", "severity");
        treeItems.push(header);
        const message = [
            localize("setup.view.loading.msg1", "Searching for installed scanning"),
            localize("setup.view.loading.msg2", "engines and licenses")];
        message.forEach(m =>{
            const treeItem = new CodeSightSetupTreeItem("");
            treeItem.description = m;
            treeItems.push(treeItem);
        });
        this.treeProvider.setItems(treeItems, treeItemChildrenMap);
    }

    showErrorMessage() {
        let treeItems: CodeSightSetupTreeItem[] = [];
        let treeItemChildrenMap = new Map<CodeSightSetupTreeItem, CodeSightSetupTreeItem[]>();
        const header = new CodeSightSetupTreeItem(
            localize("setup.view.error", "Startup Failed"));
        header.iconPath = getService(VscodeContextService.id).getIconPath("severity-medium.svg", "severity");
        treeItems.push(header);
        const message = [localize("setup.view.error.msg1", "Please restart VS Code")];
        message.forEach(m =>{
            const treeItem = new CodeSightSetupTreeItem("");
            treeItem.description = m;
            treeItems.push(treeItem);
        });
        this.treeProvider.setItems(treeItems, treeItemChildrenMap);
    }

    showSetupNeededMessage() {
        let treeItems: CodeSightSetupTreeItem[] = [];
        let treeItemChildrenMap = new Map<CodeSightSetupTreeItem, CodeSightSetupTreeItem[]>();
        const header = new CodeSightSetupTreeItem(
            localize("setup.view.register.header", "Register to Start Scanning"));
        header.iconPath = getService(VscodeContextService.id).getIconPath("severity-low.svg", "severity");
        treeItems.push(header);
        
        let message = [
            localize("setup.view.register.msg1","To start scanning register for a"),
            localize("setup.view.register.msg2","Standard Edition free trial."),
            localize("setup.view.register.existing.remote1","Existing Polaris, Software Risk Manager (SRM),"),
            localize("setup.view.register.existing.remote2","Coverity and Black Duck SCA users"),
            localize("setup.view.register.msg3","can enable integration to get started.")];
            
        message.forEach(m =>{
            const treeItem = new CodeSightSetupTreeItem("");
            treeItem.description = m;
            treeItems.push(treeItem);
        });
        const getStartedItem = new CodeSightSetupTreeItem(
            localize("setup.view.register.button","[Start Trial]"));
        getStartedItem.command = {command: OPEN_SETUP_WEBVIEW_COMMAND_ID, title: "Open Setup"}; //not user facing string
        treeItems.push(getStartedItem);
        this.treeProvider.setItems(treeItems, treeItemChildrenMap);

        // shift focus to the view
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        commands.executeCommand("codesight-setup-status.focus");
    }

    showSetupStatusFlow(setupStatus:SetupViewSteps) {
        let treeItems: CodeSightSetupTreeItem[] = [];
        let treeItemChildrenMap = new Map<CodeSightSetupTreeItem, CodeSightSetupTreeItem[]>();
        const header = new CodeSightSetupTreeItem(
            localize("setup.view.progress.header","Setup In Progress"));
        header.iconPath = getService(VscodeContextService.id).getIconPath("severity-low.svg", "severity");
        const openSetupCommand: Command = {command:OPEN_SETUP_WEBVIEW_COMMAND_ID, title:"Open Setup"};
        header.command = openSetupCommand;
        treeItems.push(header);

        let sectionBreak = new CodeSightSetupTreeItem("");
        sectionBreak.description = SECTION_SEPARATOR;
        treeItems.push(sectionBreak);

        const successIcon = {
            dark: getService(VscodeContextService.id).getIconPath("circle-check-dark.svg", "general"),
            light: getService(VscodeContextService.id).getIconPath("circle-check-light.svg", "general"),
        };
        const skipIcon = {
            dark: getService(VscodeContextService.id).getIconPath("skipped-dark.svg", "general"),
            light: getService(VscodeContextService.id).getIconPath("skipped-light.svg", "general"),
        };
        const errorIcon = getService(VscodeContextService.id).getIconPath("severity-high.svg", "severity");
        const loadingIcon = {
            dark: getService(VscodeContextService.id).getIconPath("spinner-dark.svg", "general"),
            light: getService(VscodeContextService.id).getIconPath("spinner-light.svg", "general"),
        };

        if(setupStatus.createTrialAccount !== SetupStepStatus.NotApplicable){
            const registration = new CodeSightSetupTreeItem("");
            registration.description = localize("setup.view.registration","Create Trial Account");
            registration.command = openSetupCommand;
            registration.iconPath = successIcon;
            treeItems.push(registration); 
        }

        // show coverity setup information first, if applicable
        switch (setupStatus.connectToCoverityServer) {
            case SetupStepStatus.Installing:
                const coverityServerInProgress = new CodeSightSetupTreeItem(
                    localize("setup.view.progress.coverity.server.installing",
                    "Connecting to Coverity server"));
                coverityServerInProgress.command = openSetupCommand;
                coverityServerInProgress.iconPath = loadingIcon;
                treeItems.push(coverityServerInProgress);
                break;
            case SetupStepStatus.Success:
                const coverityServerSuccess = new CodeSightSetupTreeItem("");
                coverityServerSuccess.description = localize("setup.view.progress.coverity.server.success",
                    "Connected to Coverity Server");
                coverityServerSuccess.iconPath = successIcon;
                treeItems.push(coverityServerSuccess);
                break;
            case SetupStepStatus.Unstarted:
                const coverityServerUnstarted = new CodeSightSetupTreeItem(
                    localize("setup.view.progress.coverity.unstarted",
                    "Connect to Coverity Server"));
                coverityServerUnstarted.command = openSetupCommand;
                treeItems.push(coverityServerUnstarted);
                break;
            case SetupStepStatus.Skipped:
            case SetupStepStatus.Failed:
            case SetupStepStatus.NotApplicable:
                //no-op
                break;
        }

        switch(setupStatus.downloadCoverity) {
            case SetupStepStatus.Unstarted:
                const coverityUnstarted = new CodeSightSetupTreeItem("");
                coverityUnstarted.description = localize("setup.view.progress.coverity.unstarted",
                    "Install Coverity Scan");
                treeItems.push(coverityUnstarted);
                break;
            case SetupStepStatus.Installing:
                const coverityInstalling = new CodeSightSetupTreeItem(
                    localize("setup.view.progress.coverity.installing",
                    "Installing Coverity Scan"));
                coverityInstalling.command = openSetupCommand;
                coverityInstalling.iconPath = loadingIcon;
                treeItems.push(coverityInstalling);
                break;
            case SetupStepStatus.Success:
                const coveritySuccess = new CodeSightSetupTreeItem("");
                coveritySuccess.description = localize("setup.view.progress.coverity.success",
                    "Coverity Scan Installed");
                coveritySuccess.iconPath = successIcon;
                treeItems.push(coveritySuccess);
                break;
            case SetupStepStatus.Skipped:
                const coveritySkipped = new CodeSightSetupTreeItem("");
                coveritySkipped.description = localize("setup.view.progress.coverity.skipped",
                    "Coverity Scan Install Skipped");
                    coveritySkipped.iconPath = skipIcon;
                treeItems.push(coveritySkipped);
                break;
            case SetupStepStatus.Failed:
                const coverityError = new CodeSightSetupTreeItem(
                    localize("setup.view.progress.coverity.failed",
                    "Error Installing Coverity Scan"));
                coverityError.iconPath = errorIcon;
                coverityError.command = openSetupCommand;
                treeItems.push(coverityError);
                break;
            case SetupStepStatus.NotApplicable:
                // no-op
                break;
        }

        switch(setupStatus.downloadSigma) {
            case SetupStepStatus.Unstarted:
                const sigmaUnstarted = new CodeSightSetupTreeItem("");
                sigmaUnstarted.description = localize("setup.view.progress.sigma.unstarted",
                    "Install Rapid Scan Static");
                treeItems.push(sigmaUnstarted);
                break;
            case SetupStepStatus.Installing:
                const sigmaInstalling = new CodeSightSetupTreeItem(
                    localize("setup.view.progress.sigma.installing",
                    "Installing Rapid Scan Static"));
                sigmaInstalling.command = openSetupCommand;
                sigmaInstalling.iconPath = loadingIcon;
                treeItems.push(sigmaInstalling);
                break;
            case SetupStepStatus.Success:
                const sigmaSuccess = new CodeSightSetupTreeItem("");
                sigmaSuccess.description = localize("setup.view.progress.sigma.success",
                    "Rapid Scan Static Installed");
                sigmaSuccess.iconPath = successIcon;
                treeItems.push(sigmaSuccess);
                break;
            case SetupStepStatus.Skipped:
                const sigmaSkipped = new CodeSightSetupTreeItem("");
                sigmaSkipped.description = localize("setup.view.progress.sigma.skipped",
                    "Rapid Scan Static Skipped");
                sigmaSkipped.iconPath = skipIcon;
                treeItems.push(sigmaSkipped);
                break;
            case SetupStepStatus.Failed:
                const sigmaError = new CodeSightSetupTreeItem(
                    localize("setup.view.progress.sigma.failed",
                    "Error Installing Rapid Scan Static"));
                sigmaError.iconPath = errorIcon;
                sigmaError.command = openSetupCommand;
                treeItems.push(sigmaError);
                break;
            case SetupStepStatus.NotApplicable:
                // no-op
                break;
        }

        // show black duck setup information first, if applicable
        switch (setupStatus.connectToBlackduckServer) {
            case SetupStepStatus.Installing:
                const blackDuckServerInProgress = new CodeSightSetupTreeItem(
                    localize("setup.view.progress.bd.server.installing",
                    "Connecting to Black Duck SCA server"));
                blackDuckServerInProgress.command = openSetupCommand;
                blackDuckServerInProgress.iconPath = loadingIcon;
                treeItems.push(blackDuckServerInProgress);
                break;
            case SetupStepStatus.Success:
                const coverityServerSuccess = new CodeSightSetupTreeItem("");
                coverityServerSuccess.description = localize("setup.view.progress.bd.server.success",
                    "Connected to Black Duck SCA Server");
                coverityServerSuccess.iconPath = successIcon;
                treeItems.push(coverityServerSuccess);
                break;
            case SetupStepStatus.Unstarted:
                const coverityServerUnstarted = new CodeSightSetupTreeItem(
                    localize("setup.view.progress.bd.unstarted",
                    "Connect to Black Duck SCA Server"));
                coverityServerUnstarted.command = openSetupCommand;
                treeItems.push(coverityServerUnstarted);
                break;
            case SetupStepStatus.Skipped:
            case SetupStepStatus.Failed:
            case SetupStepStatus.NotApplicable:
                //no-op
                break;
        }


        switch(setupStatus.downloadBlackduck) {
            case SetupStepStatus.Unstarted:
                const bdUnstarted = new CodeSightSetupTreeItem("");
                bdUnstarted.description = localize("setup.view.progress.bd.unstarted",
                    "Install Rapid Scan SCA");
                treeItems.push(bdUnstarted);
                break;
            case SetupStepStatus.Installing:
                const bdInstalling = new CodeSightSetupTreeItem(
                    localize("setup.view.progress.bd.installing",
                    "Installing Rapid Scan SCA"));
                bdInstalling.command = openSetupCommand;
                bdInstalling.iconPath = loadingIcon;
                treeItems.push(bdInstalling);
                break;
            case SetupStepStatus.Success:
                const bdSuccess = new CodeSightSetupTreeItem("");
                bdSuccess.description = localize("setup.view.progress.bd.success",
                    "Rapid Scan SCA Installed");
                bdSuccess.iconPath = successIcon;
                treeItems.push(bdSuccess);
                break;
            case SetupStepStatus.Skipped:
                const bdSkipped = new CodeSightSetupTreeItem("");
                bdSkipped.description = localize("setup.view.progress.bd.skipped",
                    "Rapid Scan SCA Skipped");
                bdSkipped.iconPath = skipIcon;
                treeItems.push(bdSkipped);
                break;
            case SetupStepStatus.Failed:
                const bdError = new CodeSightSetupTreeItem(
                    localize("setup.view.progress.bd.failed",
                    "Error Installing Rapid Scan SCA"));
                bdError.iconPath = errorIcon;
                bdError.command = openSetupCommand;
                treeItems.push(bdError);
                break;
            case SetupStepStatus.NotApplicable:
                // no-op
                break;
        }
        treeItems.push(sectionBreak);

        const message = [
            localize("setup.view.footer.msg1", "Code Sight will be able to scan"),
            localize("setup.view.footer.msg2", "your code once the above steps"),
            localize("setup.view.footer.msg3", "are complete")];
        message.forEach(m =>{
            const treeItem = new CodeSightSetupTreeItem("");
            treeItem.description = m;
            treeItems.push(treeItem);
        });
    
        this.treeProvider.setItems(treeItems, treeItemChildrenMap);
    }
    
    dispose() {
        this.commandDisposables.forEach(disposable => disposable.dispose());
    }

    public async parseNotificationMessage(message: NotificationMessage) {
       // no-op
    }

    private initCommands() {
        this.commandDisposables.push(commands.registerCommand(OPEN_SETUP_WEBVIEW_COMMAND_ID, async (): Promise<void> => {
            return getService(SetupService.id).showCurrentSetupStep();
        }));
    }
}
