import { Message } from "@codesight/codesight-controller-proto/controller_proto/v0/message_pb";
import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { Uri, Webview } from "vscode";
import { LocalizeFunc, loadMessageBundle } from "vscode-nls";
import { ServiceId, getService } from "../../services/serviceContainer";
import { SetupService } from "../../services/setupService";
import { isWindows } from "../../utils/environmentUtils";
import { COMMUNITY_PORTAL_REMEDIATION_ID, CONTACT_SUPPORT_REMEDIATION_ID, DO_UPDATE_REMEDIATION_ID, EXPORT_LOGS_REMEDIATION_ID, OLDER_DETECT_ERROR_REMEDIATION_ID, OPEN_DETECT_CONFIG_REMEDIATION_ID, PROBLEM_DETAILS_ID, REAUTHENTICATE_BLACK_DUCK_REMEDIATION_ID, RETRY_DOWNLOAD_REMEDIATION_ID, SKIP_DOWNLOAD_REMEDIATION_ID, USE_LOCAL_BINARY_REMEDIATION_ID } from "../../utils/notificationMessageUtils";
import { getWebviewHead } from "../../utils/webviewUtils";
import { EXPORT_LOGS_BODY, EXPORT_LOGS_SCRIPTS, EXPORT_LOGS_STYLING } from "../../views/exportLogs/exportLogsViewComponent";
import { WebviewProvider } from "../webviewProvider";

const localize: LocalizeFunc = loadMessageBundle();

export namespace NotificationViewCommandIds {
    export const COPY_TO_CLIPBOARD = "copy-to-clipboard";
    export const OPEN_SCAN_LOG_FOLDER = "open-scan-log-folder";
    export const OPEN_SCAN_LOG_FILE = "open-scan-log-file";
}

export abstract class NotificationViewProviderBase extends WebviewProvider {
    static readonly id: ServiceId<NotificationViewProviderBase> = { id: NotificationViewProviderBase.name };

    abstract reloadHtml(message?: NotificationMessage): Promise<void>;
}

export abstract class NotificationViewProviderBaseImpl extends NotificationViewProviderBase {
    protected notificationMessage: NotificationMessage | undefined;
    protected scanLogPath: string = "";
    
    abstract isScanDetailsView: boolean;
    abstract loadState(): Promise<void>;
    abstract getViewTitle(): string;
    abstract getViewIcon(): string;
    abstract getViewContent(): string;

    private collapsibleCount: number = 0;

    constructor() {
        super();
    }

    public async reloadHtml(message?: NotificationMessage) {
        this.notificationMessage = message;
        
        await this.loadState();

        let html = `<html>
            <head>
                ${this.head}
            </head>
            <style>
                ${this.style}
            </style>
            <body>
                <div class='box'>
                    <img class='${this.getViewIcon()}' width="28" height="28" class='float-left'/>
                    <h2 class='float-left margin-left'>${this.getViewTitle()}</h2>
                </div>
                ${this.getViewContent()}
            </body>
            <script>
                const vscode = acquireVsCodeApi();
                window.onload = function() {
                    let buttons = document.querySelectorAll(".button");

                    buttons.forEach(function(button) {
                        button.onclick = function() {
                            if(button.classList.contains("spinner-button")) {
                                let spinnerIcon = button.querySelector(".spinner-icon");
                                if(spinnerIcon){
                                    spinnerIcon.classList.remove("hidden");
                                }
                            }

                            if(button.id === '${NotificationViewCommandIds.COPY_TO_CLIPBOARD}' || button.id === '${NotificationViewCommandIds.OPEN_SCAN_LOG_FOLDER}' || button.id === '${NotificationViewCommandIds.OPEN_SCAN_LOG_FILE}') {
                                let path = button.attributes.path;
                                vscode.postMessage({
                                    command: button.id,
                                    logPath: '${isWindows() ? Uri.file(this.scanLogPath).path.substring(1) : this.scanLogPath}'
                                });
                            } else {
                                vscode.postMessage({
                                    command: button.id
                                });
                            }
                            
                            return false;
                        }
                    });
                }

                ${EXPORT_LOGS_SCRIPTS}
            </script>
        </html>`;
        this.webviewPanel!.webview.html = html;
    }

    protected getScanDetailsContent(description:  NotificationMessage.AdditionalContent | undefined, shouldShowScanLogsContent: boolean, shouldShowExportLogs: boolean): string {
        let title = localize('scan.details.more.details.header', 'More Details');

        let html = "";
        if (description) {
            html += description.getFormattedcontent();
        }

        let detailsDesc = localize('scan.log.description', 'The file at the path below is the log for the scan.');
        let scanLogsContent = `<p>${detailsDesc}</p>
                            <div id="scan-log-div">
                                <p id="scan-log-path">${this.scanLogPath}</p>
                                <button class="button copy-to-clipboard-icon" id='${NotificationViewCommandIds.COPY_TO_CLIPBOARD}' title="${localize("scan.details.copy.to.clipboard.text", "Copy to Clipboard")}"></button>
                                <button class="button open-folder-icon" id='${NotificationViewCommandIds.OPEN_SCAN_LOG_FOLDER}' title="${localize("scan.details.open.scan.log.folder.text", "Open Scan Log Folder")}"></button>
                                <button class="button open-file-icon" id='${NotificationViewCommandIds.OPEN_SCAN_LOG_FILE}' title="${localize("scan.details.open.scan.log.file.text", "Open Scan Log File")}"></button>
                            </div>`
        let content = `<div>
                            ${shouldShowScanLogsContent ? scanLogsContent : ""}
                            ${shouldShowExportLogs ? EXPORT_LOGS_BODY : ""}
                        </div>`;
        html += this.getCollapsibleSection(title, content, true);

        return `<div style="margin-top: 13px;">
                  ${html}
                </div>`;
    }

    protected getNotificationMessageContent(additionalContentList: NotificationMessage.AdditionalContent[], startIndex: number): string {
        let html = "";
        let remediationItemCount = 0;

        // determine if there will be more than one remediation item, so we know if we need dropdown sections or not
        additionalContentList.forEach(additionalContent => {
            if (additionalContent.getRemediationactionsList().length > 0) {
                remediationItemCount += 1;
            }
        });

        let hasMultipleActions = remediationItemCount > 1;

        const isOnboarding = getService(SetupService.id).currentlyOnboarding();

        for (let i = startIndex; i < additionalContentList.length; i++) {
            let shouldAutoExpand: boolean = false;
            let additionalContent = additionalContentList[i];

            let remediationActions = additionalContent.getRemediationactionsList();
            let remediationActionsHtml = "";
            let shouldSkipRemediation = false;
            remediationActions.forEach(remediationAction => {

                if(remediationAction.getId() === SKIP_DOWNLOAD_REMEDIATION_ID && !isOnboarding){
                    shouldSkipRemediation = true;
                    return; // Do not show the skip download remediation if the user is not in onboarding
                }

                if (remediationAction.getId() === OLDER_DETECT_ERROR_REMEDIATION_ID) {
                    shouldSkipRemediation = true;
                    return;
                }

                shouldAutoExpand = remediationAction.getId() === RETRY_DOWNLOAD_REMEDIATION_ID ||
                    remediationAction.getId() === USE_LOCAL_BINARY_REMEDIATION_ID ||
                    remediationAction.getId() === SKIP_DOWNLOAD_REMEDIATION_ID ||
                    remediationAction.getId() === OPEN_DETECT_CONFIG_REMEDIATION_ID;
                remediationActionsHtml += this.getRemediationContentSection(remediationAction.getId(), remediationAction.getContent());
            });
            if(shouldSkipRemediation){
                continue;
            }

            let description = additionalContent.getFormattedcontent();
            description = description.replace(/\n/g, "<br>");
            let content = description + remediationActionsHtml;

            if (hasMultipleActions) {
                if (additionalContent.getSourceid() === PROBLEM_DETAILS_ID) {
                    html += `${content}<br>`;
                } else if (shouldAutoExpand) {
                    html += this.getCollapsibleSection(additionalContent.getTitle(), content, true);
                } else {
                    html += this.getCollapsibleSection(additionalContent.getTitle(), content, false);
                }
            } else {
                html += content;
            }
        }

        return html;
    }

    private getRemediationContentSection(remediationContentId: string, title: string): string {
        let content = "";

        switch (remediationContentId) {
            case DO_UPDATE_REMEDIATION_ID:
            // Intentional Fallthrough
            case SKIP_DOWNLOAD_REMEDIATION_ID:
            case RETRY_DOWNLOAD_REMEDIATION_ID:

                content = `
                    <button class="button spinner-button" type="button" id='${remediationContentId}'>
                        <div class='box'>
                            <div class='button-content'>
                                <span>${title}</span>
                                <img class='margin-left spinner-icon hidden' width='16' height='16'/>
                            </div>
                        </div>
                    </button>
                `;
                break;
            case EXPORT_LOGS_REMEDIATION_ID:
                content = EXPORT_LOGS_BODY;
                break;
            case CONTACT_SUPPORT_REMEDIATION_ID:
                content = this.getIconRemediationButtonContent(remediationContentId, title, "contact-support-icon");
                break;
            case COMMUNITY_PORTAL_REMEDIATION_ID:
                content = this.getIconRemediationButtonContent(remediationContentId, title, "help-icon");
                break;
            case REAUTHENTICATE_BLACK_DUCK_REMEDIATION_ID:
                let authenticate = localize("reauthenticate.button.text", "Authenticate");
                content = `
                <div class="box">
                    <button class="button-left button" type="button" id='${remediationContentId}'>
                        <div class='box'>
                            <div class='button-content'>
                                <span>${authenticate}</span>
                            </div>
                        </div>
                    </button>
                </div>
                `;
                break;
            default:
                content = `<button class='button' id='${remediationContentId}'>${title}</button>`;
                break;
        }

        return content;
    }

    private getIconRemediationButtonContent(remediationId: string, buttonText: string, iconType: string) {
        return `
            <button class="button" type="button" id='${remediationId}'>
                <div class='box'>
                    <div class='button-content'>
                        <img class='margin-right ${iconType}' width='16' height='16'/>    
                        <span>${buttonText}</span>
                    </div>
                </div>
            </button>
        `;
    }

    private getCollapsibleSection(title: string, content: string, shouldBeOpened: boolean): string {
        let collapsibleToggle = shouldBeOpened ? `<input id="collapsible${this.collapsibleCount}" class="toggle" type="checkbox" checked>` :
            `<input id="collapsible${this.collapsibleCount}" class="toggle" type="checkbox">`;

        let html = `
        <div class="wrap-collapsible">
            ${collapsibleToggle}
            <label for="collapsible${this.collapsibleCount}" class="label-toggle">${title}</label>
            <div class="collapsible-content">
                <div class="content-inner">
                ${content}
                </div>
            </div>
        </div>`;
        this.collapsibleCount++;

        return html;
    }

    protected getMessageSeverityClass(message: NotificationMessage | undefined): string {
        switch (message?.getSeverity()) {
            case Message.Severity.ERROR:
                return "severity-high";
            case Message.Severity.WARNING:
            case Message.Severity.DEBUG:
            case Message.Severity.TRACE:
            case Message.Severity.INFO:
            default:
                return "severity-low";
        }
    }

    protected getHead(webview: Webview): string {
        return getWebviewHead("Tool Setup", webview);
    }

    protected getStyle(): string {
        return `
        #outer {
            width: 600px;
        }

        #inner {
            display: inline-block;
            margin: 0 auto;
            text-align: center;
        }

        #scan-log-div {
            display: flex;
            align-items: center;
        }

        #scan-log-path {
            margin-right: 5px;
        }

        .copy-to-clipboard-icon {
            border: none;
            background-color: transparent;
            padding: 7px !important;
            min-width: unset !important;
            max-height: 5px !important;
        }

        .open-file-icon {
            border: none;
            background-color: transparent;
            padding: 7px !important;
            min-width: unset !important;
            max-height: 5px !important;
        }

        .button {
            background-color: var(--vscode-button-background);
            border: none;
            color: var(--vscode-button-foreground);
            padding: 10px 40px;
            text-align: center;
            text-decoration: none;
            display: inline-block;
            margin: 4px 2px;
            cursor: pointer;
            font-family: Sans-Serif;
            font-size: 1em;
            min-width: 200px
        }

        .button-content{
            text-align: center;
            display: flex;
            align-items:center;
            margin-left: auto;
            margin-right: auto;
        }

        /* Add a hover effect for buttons */
        button:hover {
            background-color: var(--vscode-button-hoverBackground);
        }

        ${EXPORT_LOGS_STYLING}
        `;
    }

    protected supportsCollapsibleSections(): boolean {
        return true;
    }
}
