import * as exportServiceGrpc from "@codesight/codesight-controller-proto/controller_proto/v1/export_scan_results_service_grpc_pb";
import { CheckScanResultsExistRequest, CheckScanResultsExistResponse, ExportScanResultsRequest, ExportScanResultsResponse, GetScanResultsInfoRequest, GetScanResultsInfoResponse } from "@codesight/codesight-controller-proto/controller_proto/v1/export_scan_results_service_pb";
import { credentials } from '@grpc/grpc-js';
import { getGrpcLimit } from '../utils/environmentUtils';

/**
 * Defines the interface points with the controller's `ExportScanResultsService`
 */
export interface ExportScanResultsServiceClient {
    getScanResultsInfo(request: GetScanResultsInfoRequest): Promise<GetScanResultsInfoResponse>;
    checkScanResultsExist(request: CheckScanResultsExistRequest): Promise<CheckScanResultsExistResponse>;
    exportScanResults(request: ExportScanResultsRequest): Promise<ExportScanResultsResponse>;
}

export class ExportScanResultsServiceClientImpl implements ExportScanResultsServiceClient {
    private client: exportServiceGrpc.ExportScanResultsServiceClient;

    constructor(connectionAddress: string) {
        this.client = new exportServiceGrpc.ExportScanResultsServiceClient(connectionAddress, credentials.createInsecure(), { 'grpc.max_receive_message_length': getGrpcLimit() });
    }

    getScanResultsInfo(request: GetScanResultsInfoRequest): Promise<GetScanResultsInfoResponse> {
        return new Promise((resolve, reject) => {
            this.client.getScanResultsInfo(request, (error, response) => {
              error ? reject(error) : resolve(response);
            });
        });
    }

    checkScanResultsExist(request: CheckScanResultsExistRequest): Promise<CheckScanResultsExistResponse> {
        return new Promise((resolve, reject) => {
            this.client.checkScanResultsExist(request, (error, response) => {
                 error ? reject(error) : resolve(response);
            });
        });
    }

    exportScanResults(request: ExportScanResultsRequest): Promise<ExportScanResultsResponse> {
        return new Promise((resolve, reject) => {
            this.client.exportScanResults(request, (error, response) => {
                 error ? reject(error) : resolve(response);
            });
        });
    }
}
