import { Error as ControllerError } from "@codesight/codesight-controller-proto/controller_proto/v0/tool_service_pb";
import * as issue_pb_v1 from "@codesight/codesight-controller-proto/controller_proto/v1/issues_service_pb";

export class BlackDuckAssistAIInsights {
    // TODO: implement model for AI insights
    private model: issue_pb_v1.BlackDuckAssistInfoResponse;
    private error: ControllerError | undefined;

    constructor(model: issue_pb_v1.BlackDuckAssistInfoResponse) {
        this.model = model;
        this.error = model.getError();
    }

    getResponseId(): string {
        return this.model.getResponseid();
    }

    getFeatureDescription(): string {
        return this.model.getFeaturedescription();
    }

    getSummary(): string {
        return this.model.getSummary();
    }

    getCodeAnalysis(): string {
        return this.model.getCodeanalysis();
    }

    getAnalysis(): string {
        return this.model.getAnalysis();
    }

    getSuggestedFix(): string {
        return this.model.getSuggestedfix();
    }

    getError(): ControllerError | undefined {
        return this.error;
    }

    hasError(): boolean {
        return this.error !== undefined;
    }
}

export interface BlackDuckAssistFeedbackType {
    occurrenceId: string;
    assistId: string;
    disposition: boolean;
    comment: string | undefined;
}