import { FileScanInfo, RefreshResultsRequest, RefreshStatus, ScanState } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_service_pb";
import { parse } from "path";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { getUserFriendlyError } from "./notificationMessageUtils";

const localize: LocalizeFunc = loadMessageBundle();

export function getLastResultString(scanInfo: FileScanInfo): string {
    switch (scanInfo.getLastresult()) {
        case FileScanInfo.Result.CANCELLED:
            return localize('scan.result.cancelled', 'Cancelled');
        case FileScanInfo.Result.FAILED:
            return localize('scan.result.failed', 'Failed');
        case FileScanInfo.Result.SUCCEEDED:
            return localize('scan.result.succeeded', 'Succeeded');
        case FileScanInfo.Result.UNSPECIFIED:
        default:
            return "";
    }
}

export function getCurrentStateString(scanInfo: FileScanInfo): string {
    switch (scanInfo.getCurrentstate()?.getState()) {
        case ScanState.State.QUEUED:
            return localize('scan.state.queued', 'Queued');
        case ScanState.State.RUNNING:
            return localize('scan.state.running', 'Running');
        case ScanState.State.COMPLETE:
            return localize('scan.state.complete', 'Complete');
        case ScanState.State.PREPARING:
            return localize('scan.state.preparing', 'Preparing');
        case ScanState.State.UNKNOWN:
        default:
            return "";
    }
}

export function getFileName(scanInfo: FileScanInfo): string {
    let fileName = scanInfo.getFilepath();

    return parse(fileName).base;
}

export function getMostConciseError(scanInfo: FileScanInfo): string {
    let message = scanInfo.getNotificationmessage();
    let userFriendlyError = message ? getUserFriendlyError(message) : "";

    if (userFriendlyError === "") {
        return scanInfo.getError();
    }

    return userFriendlyError;
}

export function getScanStatus(scanInfo: FileScanInfo | undefined): RefreshStatus.Status | undefined {
    if (!scanInfo) {
        return;
    }

    let scanStatus;
    let state = scanInfo.getCurrentstate()?.getState();
    if (state === ScanState.State.COMPLETE) {
        let result = scanInfo.getLastresult();
        if (result === FileScanInfo.Result.SUCCEEDED){
            scanStatus = RefreshStatus.Status.SUCCESS;
        } else if (result === FileScanInfo.Result.FAILED) {
            scanStatus = RefreshStatus.Status.FAILED;
        } else if (result === FileScanInfo.Result.CANCELLED) {
            scanStatus = RefreshStatus.Status.CANCELLED;
        }
    } else if (state === ScanState.State.RUNNING) {
        scanStatus = RefreshStatus.Status.RUNNING;
    }

    return scanStatus;
}

export function isRunningState(status: RefreshStatus.Status) {
    return status === RefreshStatus.Status.QUEUED || status === RefreshStatus.Status.PREPARING || status === RefreshStatus.Status.FINALIZING
            || status === RefreshStatus.Status.RUNNING;
}

export function isChangedFileScanTier(tier: RefreshResultsRequest.Tier | undefined): boolean {
    return tier === RefreshResultsRequest.Tier.ALLUNCOMMITTED
        || tier === RefreshResultsRequest.Tier.REFERENCEBRANCH;
}