import { Webview } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { ServiceId } from "../../services/serviceContainer";
import { BUTTON_STYLING, getWebviewHead } from "../../utils/webviewUtils";
import { WebviewProvider } from "../webviewProvider";

const localize: LocalizeFunc = loadMessageBundle();

export namespace LicenseViewCommandIds{
    export const VIEW_CONTINUE = "continue-button";
    export const VIEW_PREVIOUS = "previous-button";
    export const VIEW_CHOOSE = "license-file-choose";
    
    export const SET_LICENSE_PATH = "set-license-file-path";
    export const SET_STATUS = "set-status";
    export const SET_CONTINUE_ENABLED = "continue-enabled";
    export const SET_PREVIOUS_ENABLED = "previous-enabled";

    export const STATUS_LOADING="spin";
    export const STATUS_VALID="valid";
    export const STATUS_INVALID="invalid";
    export const STATUS_CLEAR="clear";

    export const ADD_SPINNER_CONTINUE = "add-spinner-continue-button";
    export const REMOVE_SPINNER = "remove-spinner-all-buttons";
}

export abstract class LicenseViewProvider extends WebviewProvider {
    static readonly id: ServiceId<LicenseViewProvider> = { id: LicenseViewProvider.name };

    abstract initHtml(): void;
}

export class LicenseViewProviderImpl extends LicenseViewProvider {
    constructor() {
        super();
    }

    public initHtml(): void {
        const viewTitle: string = localize("license.view.title", "Add a Code Sight Standard Edition License");
        const contactSupportLinkText: string = localize("license.view.contact.support.link.text", "Contact Support");
        const contactSalesLinkText: string = localize("license.view.contact.sales.link.text", "Contact Us");
        const descriptionString1 = localize("license.view.description.one", "Please");
        const descriptionString2 = localize("license.view.description.three", "to purchase a license.");
        const descriptionString3 = localize("license.view.description.two", "If you already have a license and need assistance, please");
        
        let html = `<html>
                    <head>
                        ${ this.head }
                    </head>
                    <style>
                        ${ this.style }
                    </style>
                    <body class='fixedView'>
                        <div class='box'>
                            <img class='blackduck-icon float-left' width="28" height="28"/>
                            <h2 class='float-left margin-left'>${viewTitle}</h2>
                        </div>
                        <p class="text-bold" style="margin-bottom: 0px; margin-top: 25px;">${localize('license.view.add.license.file.header','Standard Edition license file path:')}</p>
                        <div id="licenseInputDiv" class="box">
                            <input id="licenseFileInput" type="text" value="" name="licenseFileInput" readonly>
                            <button id="${LicenseViewCommandIds.VIEW_CHOOSE}" class="button-style" onclick="handleButtonClick(this);" type="button">${localize('license.view.button.choose', 'Choose')}</button>
                        </div>
                        <div id="status" class="hidden box">
                            <img id="statusImg" width="15" height="15"/>
                            <div class="margin-left"><b id="statusText"></b></div>
                        </div>
                        <div class="box" id="prev-continue-buttons">
                            <button id="${LicenseViewCommandIds.VIEW_PREVIOUS}" class="button button-half" onclick="handleButtonClick(this); addSpinner(this);" type="button">< ${localize('license.view.button.previous', 'Previous')}</button>
                            <button id="${LicenseViewCommandIds.VIEW_CONTINUE}" class="button button-half" type="button" disabled>${localize('license.view.button.continue', 'Continue')} ></button>
                        </div>
                        <p>${descriptionString1} <a href="https://www.blackduck.com/code-sight/contact-sales.html?utm_medium=referral&utm_source=Trial-MKTPLC_VSCode">${contactSalesLinkText}</a> ${descriptionString2} ${descriptionString3} <a href="https://community.blackduck.com/s/code-sight-hub/code-sight-standard-edition">${contactSupportLinkText}</a>.</p>
                        <script>
                            const vscode = acquireVsCodeApi();

                            window.addEventListener('message', event => {
                                const message = event.data;
                                switch (message.command) {
                                    case '${LicenseViewCommandIds.SET_LICENSE_PATH}':
                                        const fileInputText = document.getElementById('licenseFileInput');
                                        fileInputText.value = message.value;
                                        fileInputText.title = message.value; // tooltip
                                        break;
                                    case '${LicenseViewCommandIds.SET_STATUS}':
                                        showStatusMessage(message.message, message.type);
                                        break;
                                    case '${LicenseViewCommandIds.SET_CONTINUE_ENABLED}':
                                        enableContinueButton(message.enabled);
                                        break;
                                    case '${LicenseViewCommandIds.SET_PREVIOUS_ENABLED}':
                                        enablePreviousButton(message.enabled);
                                        break;
                                    case '${LicenseViewCommandIds.ADD_SPINNER_CONTINUE}':
                                        const continueButton = document.getElementById('${LicenseViewCommandIds.VIEW_CONTINUE}');
                                        addSpinner(continueButton);
                                        break;
                                    case '${LicenseViewCommandIds.REMOVE_SPINNER}':
                                        removeSpinner();
                                        break;
                                }
                            });

                            function showStatusMessage(message, type) {
                                let icon;
                                switch (type) {
                                    case "${LicenseViewCommandIds.STATUS_CLEAR}":
                                        clearStatusMessage();
                                        return;
                                    case "${LicenseViewCommandIds.STATUS_LOADING}":
                                        icon = "spinner-icon";
                                        break;
                                    case "${LicenseViewCommandIds.STATUS_INVALID}":
                                        icon = "severity-high";
                                        break;
                                    case "${LicenseViewCommandIds.STATUS_VALID}":
                                        icon = "success-icon";
                                        break;
                                }
        
                                document.querySelector("#status").classList.remove('hidden');
                                document.querySelector("#statusText").innerHTML = message;
                                let statusImg = document.querySelector("#statusImg");
        
                                statusImg.className = "";
                                statusImg.classList.add(icon);
                            }
        
                            function clearStatusMessage() {
                                document.querySelector("#status").classList.add('hidden');
                                document.querySelector("#statusText").innerHTML = "";
                                document.querySelector("#statusImg").className = "";
                            }

                            function enableContinueButton(enable) {
                                const continueButton = document.getElementById('${LicenseViewCommandIds.VIEW_CONTINUE}');
                                if(enable === "true"){
                                    continueButton.classList.remove("button-disabled");
                                    continueButton.removeAttribute("disabled");
                                } else {
                                    continueButton.classList.add("button-disabled");
                                    continueButton.setAttribute("disabled", "");
                                }
                            }

                            function enablePreviousButton(enable) {
                                const continueButton = document.getElementById('${LicenseViewCommandIds.VIEW_PREVIOUS}');
                                if(enable === "true"){
                                    continueButton.classList.remove("button-disabled");
                                    continueButton.removeAttribute("disabled");
                                } else {
                                    continueButton.classList.add("button-disabled");
                                    continueButton.setAttribute("disabled", "");
                                }
                            }

                            function handleButtonClick(button) {
                                vscode.postMessage({
                                    command: button.id,
                                });
                            }

                            function addSpinner(button) {
                                if (!button.innerHTML.includes("img")) {
                                    let spinner = "<img class='spinner-icon margin-left' width='20' height='20'>";
                                    button.innerHTML += spinner;
                                    button.setAttribute("disabled", "");
                                }
                            }

                            function removeSpinner() {
                                const continueButton = document.getElementById('${LicenseViewCommandIds.VIEW_CONTINUE}');
                                if (continueButton.innerHTML.includes("img")) {
                                    var buttonHTML = continueButton.innerHTML.split("<img");
                                    continueButton.innerHTML = buttonHTML[0]; // set button text again
                                }

                                const previousButton = document.getElementById('${LicenseViewCommandIds.VIEW_PREVIOUS}');
                                if (previousButton.innerHTML.includes("img")) {
                                    var buttonHTML = previousButton.innerHTML.split("<img");
                                    previousButton.innerHTML = buttonHTML[0]; // set button text again
                                }
                            }
                        </script>
                    </body>
                    </html>
        `;

        this.webviewPanel!.webview.html = html;
    }

    protected getHead(webview: Webview): string {
        return getWebviewHead("Add a Code Sight Standard Edition License", webview);
    }

    protected getStyle(): string {
        return `
        ${BUTTON_STYLING}

        .fixedView {
            max-width: 900px;
            min-width: 550px;
        }

        .label-style {
            margin-bottom: 0px;
        }

        #licenseInputDiv {
            max-width: 670px;
        }

        .button-style {
            background-color: #008CBA;
            border: none;
            color: white;
            text-align: center;
            text-decoration: none;
            display: inline-block;
            font-size: 14px;
            cursor: pointer;
        }

        .spinner-div .button-style {
            padding: 10px 25px;
        }

        #licenseFileInput {
            width: 60%;
            margin-top: 15px;
        }

        .button-style {
            background-color: var(--vscode-button-background);
            color: var(--vscode-button-foreground);
            cursor: pointer;
            border-width: 1px;
            border-style: solid;
            border-color: var(--vscode-editor-background);
            font-weight: bold;
        }

        .button-style:hover {
            background-color: var(--vscode-button-hoverBackground);
        }

        #${LicenseViewCommandIds.VIEW_CHOOSE} {
            padding: 3px 10px;
            margin: 15px 10px 0px 10px;
        }

        #prev-continue-buttons {
            margin-top: 20px;
            width: 50%;
        }

        #status {
            margin-top: 10px;
        }

        #licenseFileInput{
            cursor: default;
        }
        `;
    }
}
