 import * as diagnosticsServiceGrpc from "@codesight/codesight-controller-proto/controller_proto/v0/collect_logs_grpc_pb";
import { CollectLogsRequest, CollectLogsResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/collect_logs_pb";
import { credentials } from "@grpc/grpc-js";
import { getGrpcLimit } from '../utils/environmentUtils';

/**
 * Defines the interface points with the controller's `DiagnosticsService`
 */
export interface DiagnosticsServiceClient {
    collectLogs(request: CollectLogsRequest): Promise<CollectLogsResponse>;
}

export class DiagnosticsServiceClientImpl implements DiagnosticsServiceClient {
    private client: diagnosticsServiceGrpc.DiagnosticServiceClient;

    constructor(connectionAddress: string) {
        this.client = new diagnosticsServiceGrpc.DiagnosticServiceClient(connectionAddress, credentials.createInsecure(), {'grpc.max_receive_message_length': getGrpcLimit(), 'grpc.enable_http_proxy': 0});
    }

    async collectLogs(request: CollectLogsRequest): Promise<CollectLogsResponse> {
        return new Promise<CollectLogsResponse>((resolve, reject) => {
            this.client.collectLogs(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }
}