import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { Location } from "@codesight/codesight-controller-proto/controller_proto/v1/location_pb";
import { Disposable, env, WebviewPanel } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { BlackDuckAssistFeedbackType } from "../../models/blackduckAssist";
import { NewIssue } from "../../models/newIssue";
import { CsBrowserService } from "../../services/browserService";
import { EditorDecorationService } from "../../services/editorDecorationService";
import { InfoMessageService, WarningMessageService } from "../../services/extensionMessageService";
import { IssueSelectionService, IssueSelectionServiceListener, ListSelection } from "../../services/issueSelectionService";
import { IssuesListIdentifier, IssuesListServiceListener, LazyLoadableIssueListService, LocalViewIssuesListService, TeamViewIssuesListService } from "../../services/issuesService";
import { RevealTreeService } from "../../services/revealTreeService";
import { ScanConfigurationService, ScanConfigurationServiceListener } from "../../services/scanConfigurationService";
import { ScanMode } from "../../services/scanStatusCoordinator";
import { getService } from "../../services/serviceContainer";
import { VsCodeInputService } from "../../services/vscodeInputService";
import { SUPPORT_ADDRESS } from "../../utils/constants";
import { getLogger } from "../../utils/logger";
import { CONTACT_SUPPORT_REMEDIATION_ID } from "../../utils/notificationMessageUtils";
import { EXPORT_LOGS_BUTTON_ID, handleExportLogsButtonClicked, handleOpenLogsFolderClicked, OPEN_LOGS_FOLDER_BUTTON_ID } from "../../views/exportLogs/exportLogsViewComponent";
import { WebviewPresenter } from "../webviewPresenter";
import { NewIssueDetailsCommandIds, NewIssueDetailsProvider } from "./newIssueDetailsProvider";

const localize: LocalizeFunc = loadMessageBundle();

interface NoIssueSelectedState {
    tag: "NoIssueSelectedState";
}

interface LoadingIssueSelectedState {
    tag: "LoadingIssueSelectedState";
}

interface IssueDetailsState {
    tag: "IssueDetailsState";
}

export class NewIssueDetailsPresenter extends WebviewPresenter implements IssuesListServiceListener, IssueSelectionServiceListener, ScanConfigurationServiceListener {
    private view: NewIssueDetailsProvider;
    private onMessageFromWebviewDisposable: Disposable | undefined;
    private state: IssueDetailsState | NoIssueSelectedState | LoadingIssueSelectedState;
    private issuesListService: LazyLoadableIssueListService<NewIssue>;
    private prevIssueId: string;

    constructor(panel: WebviewPanel, issueListIdentifier: IssuesListIdentifier) {
        super();
        this.view = getService(NewIssueDetailsProvider.id);
        this.view.initView(panel);
        switch (issueListIdentifier) {
            case IssuesListIdentifier.LocalViewIssuesList:
                this.issuesListService = getService(LocalViewIssuesListService.id);
                break;
            case IssuesListIdentifier.TeamViewIssuesList:
                this.issuesListService = getService(TeamViewIssuesListService.id);
                getService(ScanConfigurationService.id).addListener(this);
                break;
        }
        this.issuesListService.addListener(this);
        this.prevIssueId = "";
        this.state = {
            tag: "NoIssueSelectedState",
        };

        getService(IssueSelectionService.id).addListener(this);

        this.onMessageFromWebviewDisposable = this.view.onMessageFromWebview(async message => {
            switch (message.command) {
                case NewIssueDetailsCommandIds.NEW_ISSUE_COPY_TO_CLIPBOARD: {
                    env.clipboard.writeText(message.issueId).then((_value) => {
                        let successMessage = localize('new.issues.info.message.text.copy.to.clipboard.success', "Issue ID successfully copied to clipboard");
                        // eslint-disable-next-line @typescript-eslint/no-floating-promises
                        getService(InfoMessageService.id).copyToClipboardSuccess(successMessage);
                    },
                        (_reason) => {
                            // eslint-disable-next-line @typescript-eslint/no-floating-promises
                            getService(WarningMessageService.id).copyToClipboardFailed();
                        });
                    }
                    break;
                case NewIssueDetailsCommandIds.SELECT_OCCURRENCE: {
                    let issueId = message.issueId;
                    let occurrenceNumber = message.occurrenceNumber;
                    const issue = this.getCurrentIssue();
                    if (!issueId || occurrenceNumber === undefined || occurrenceNumber === null || !issue) {
                        getLogger().warn(` Invalid Issue id or Occurrence number when selecting an occurrence issueId: ${issueId} , occurrenceNumber: ${occurrenceNumber}`);
                        break;
                    }

                    const occurrenceIndex = Number(message.occurrenceNumber);
                    await getService(IssueSelectionService.id).selectNewOccurrence(issueId, occurrenceIndex, this.issuesListService.getIdentifier(), issue.getDisplayType());
                }
                    break;
                case NewIssueDetailsCommandIds.REVEAL_TREE: {
                    if (this.state.tag === "IssueDetailsState") {
                        let issue = getService(IssueSelectionService.id).getSelection()?.selection.issue;
                        let eventInfo = issue?.getEventInfo();
                        let contributingDetail = issue ? getService(IssueSelectionService.id).getSelectedOccurrence(issue) : undefined;
                        
                        if (eventInfo && contributingDetail) {
                            let contributingDetails = eventInfo.getContributingDetails();
                            let selectedIndex = contributingDetail.getContributingDetailIndex();
                            
                            if (selectedIndex >= 0 && selectedIndex < contributingDetails.length && 
                                contributingDetails[selectedIndex] === contributingDetail) {
                                
                                let mainEvent = contributingDetail.getMainEvent();
                                let event = mainEvent ? mainEvent : contributingDetail.getEventList()[0]; // we need to send some event to revealTree method, and SCA issues have no main event, so sending 0th by default
                                if (event) {
                                    if (this.issuesListService.getIdentifier() === IssuesListIdentifier.LocalViewIssuesList) {
                                        await getService(RevealTreeService.id).revealLocalViewTree(event);
                                    } else if (this.issuesListService.getIdentifier() === IssuesListIdentifier.TeamViewIssuesList) {
                                        await getService(RevealTreeService.id).revealTeamViewTree(event);
                                    }
                                }
                            }
                        }
                    } else {
                        getLogger().warn(` No issue is selected to reveal tree`);
                    }
                }
                    break;
                case NewIssueDetailsCommandIds.NAVIGATE_TO_OCCURRENCE: {
                    const ctx = this.validateNavigationBasics(message);
                    if (!ctx) { 
                        break; 
                    }

                    await getService(EditorDecorationService.id)
                        .navigate(this.issuesListService.getIdentifier(),
                            message.issueId,
                            ctx.issue.getDisplayType(),
                            ctx.occurrenceIndex);
                    break;
                }
                case NewIssueDetailsCommandIds.NAVIGATE_TO_DEPENDENCY: {
                    const ctx = this.validateNavigationBasics(message);
                    if (!ctx) { 
                        break; 
                    }

                    const eventLine = parseInt(message.eventLine, 10);
                    const eventNumber = parseInt(message.eventNumber, 10);
                    const eventFile = message.eventFile;

                    if (isNaN(eventLine) || isNaN(eventNumber) || !eventFile) {
                        getLogger().warn(`Invalid dependency navigation data: line='${message.eventLine}', number='${message.eventNumber}', file='${eventFile}'`);
                        break;
                    }

                    const location = new Location();
                    location.setPath(eventFile);
                    location.setLinenumber(eventLine);

                    await getService(EditorDecorationService.id)
                        .navigate(this.issuesListService.getIdentifier(),
                            message.issueId,
                            ctx.issue.getDisplayType(),
                            ctx.occurrenceIndex,
                            eventNumber,
                            location);
                    break;
                }
                case NewIssueDetailsCommandIds.GENERATE_BLACKDUCK_ASSIST_INSIGHTS:
                    const aiData = await this.issuesListService.loadBlackDuckAssistInfo(message.occurrenceId);
                    if (!this.prevIssueId) {
                        const currentIssue = this.getCurrentIssue();
                        this.prevIssueId = this.state.tag === "IssueDetailsState" && currentIssue ? currentIssue.getIssueId() : "";
                    }
                    this.view.postMessageToWebview({
                        command: NewIssueDetailsCommandIds.BLACKDUCK_ASSIST_INSIGHTS_GENERATED,
                        html: this.view.renderAITabContent(aiData),
                        prevIssueId: this.prevIssueId,
                        assistId: aiData?.getResponseId() ?? "",
                    });
                    break;
                case NewIssueDetailsCommandIds.COPY_BLACKDUCK_ASSIST_INSIGHTS:
                    env.clipboard.writeText(message.text).then((_value) => {
                        let successMessage = localize('new.issues.info.message.text.copy.to.clipboard.success', `${message.type} successfully copied to clipboard`);
                        // eslint-disable-next-line @typescript-eslint/no-floating-promises
                        getService(InfoMessageService.id).copyToClipboardSuccess(successMessage);
                    }, (_reason) => {
                        // eslint-disable-next-line @typescript-eslint/no-floating-promises
                        getService(WarningMessageService.id).copyToClipboardFailed();
                    });
                    break;
                case NewIssueDetailsCommandIds.SUBMIT_BLACKDUCK_ASSIST_FEEDBACK: {
                    let comment = await getService(VsCodeInputService.id).showInputBox({
                        placeHolder: localize('blackduck.assist.provide.feedback.prompt', 'Optional: Please provide additional feedback'),
                        value: message.comment ?? "",
                        ignoreFocusOut: true,
                    });

                    // if the user cancelled the input box, exit early
                    if (comment === undefined) {
                        break;
                    }

                    const assistFeedback: BlackDuckAssistFeedbackType = {
                        occurrenceId: message.occurrenceId,
                        assistId: message.assistId,
                        disposition: message.disposition == "true",
                        comment: comment,
                    };
                    
                    const feedbackSubmitted = await this.issuesListService.submitBlackDuckAssistInfoFeedback(assistFeedback);
                    if (feedbackSubmitted !== undefined) {
                        await getService(InfoMessageService.id).showBlackDuckAssistFeedbackMessage(feedbackSubmitted);
                    }
                    break;
                }
                case EXPORT_LOGS_BUTTON_ID:
                    await handleExportLogsButtonClicked(this.view);
                    break;
                case OPEN_LOGS_FOLDER_BUTTON_ID:
                    await handleOpenLogsFolderClicked(this.view);
                    break;
                case CONTACT_SUPPORT_REMEDIATION_ID:
                    await getService(CsBrowserService.id).openLink(SUPPORT_ADDRESS);
                    break;
                default: {
                    getLogger().warn(`Received unexpected message ${message.command}`);
                    break;
                }
            }
        });
    }

    private validateNavigationBasics(message: { issueId?: string; occurrenceIndex?: string; }): { issue: NewIssue; occurrenceIndex: number } | undefined {
        const issue = this.getCurrentIssue();
        if (!message.issueId || !issue || issue.getIssueId() !== message.issueId) {
            getLogger().warn(`Navigation aborted: issue mismatch or missing (msgId='${message.issueId}', current='${issue?.getIssueId()}')`);
            return undefined;
        }

        const rawIndex = message.occurrenceIndex;
        const occurrenceIndex = parseInt(rawIndex ?? "", 10);
        if (isNaN(occurrenceIndex) || occurrenceIndex < 0) {
            getLogger().warn(`Invalid occurrenceIndex: '${rawIndex}'`);
            return undefined;
        }

        return { issue, occurrenceIndex };
    }

    async onSelectedReferenceBranchChanged(): Promise<void> {
        //no-op
    }

    async onSelectionChanged(listSelection: ListSelection | undefined): Promise<void> {
        if (!listSelection) {
            this.state = {
                tag: "NoIssueSelectedState",
            };
            await this.initView();
            return;
        }

        let selectedIssue;

        selectedIssue = getService(IssueSelectionService.id).getSelection()?.selection.issue;


        if (selectedIssue) {
            this.state = this.buildIssueDetailsState();
        }

        await this.initView();
    }

    async onIssuesReloaded(): Promise<void> {
        let selection = getService(IssueSelectionService.id).getIssuesListSelection(this.issuesListService.getIdentifier());
        let selectedIssue;
        //TODO Fix local view sigma coverity issue selection when ID is the same // if View Result From selection has changed, clear selection (no issue selected state) to address same issue ID scenario with Coverity and Sigma
        if (selection) {
             selectedIssue = selection?.issue;

            if (selectedIssue) {
                this.state = this.buildIssueDetailsState();
            }
        } else {
            this.state = {
                tag: "NoIssueSelectedState",
            };
        }

        await this.initView();
    }


    async onScanModeChanged(scanMode: ScanMode): Promise<void> {
        return this.onIssuesReloaded();
    }

    async onScanFileScopeChanged(): Promise<void> {
        // no-op
    }

    async onSelectedScanConfigChanged(): Promise<void> {
        // no-op
    }

    async parseNotification(_message: NotificationMessage): Promise<void> {

    }

    public async initView(requestToken?: number) {
        switch (this.state.tag) {
            case "NoIssueSelectedState":
                    this.view.initNoIssueSelectedHtml();
                break;
            case "LoadingIssueSelectedState":
                    this.view.initLoadingIssueHtml();
                break;
            case "IssueDetailsState": {
                let issue = this.getCurrentIssue();
                if (issue) {
                    this.view.setIssue(issue);
                    let service = this.issuesListService;
                    await service.loadDetailsAndEventsForIssue(issue);
                        let showAIInsights = issue.getDetails()?.getIsBlackDuckAssistAvailable() ?? false;
                        this.view.initIssueDetails(showAIInsights);
                }
                break;
            }
        }
    }

    dispose(): void {
        this.onMessageFromWebviewDisposable?.dispose();
        this.issuesListService.removeListener(this);
        getService(ScanConfigurationService.id).removeListener(this);
        getService(IssueSelectionService.id).removeListener(this);
    }

    buildIssueDetailsState(): IssueDetailsState {
        return this.state = {
            tag: "IssueDetailsState",
        };
    }

    getCurrentIssue(): NewIssue | undefined {
        return getService(IssueSelectionService.id).getIssuesListSelection(this.issuesListService.getIdentifier())?.issue;
    }

    async init() {
        let issue: NewIssue | undefined;
        let selection = getService(IssueSelectionService.id).getIssuesListSelection(this.issuesListService.getIdentifier());

        if (selection) {
            issue = selection?.issue;
        }

        if (issue) {
            this.state = this.buildIssueDetailsState();
        } else {
            this.state = {
                tag: "LoadingIssueSelectedState",
            };
        }
    }
}