export const NOTIFICATION_SELECTED_COMMAND_ID = "codesight.extensionStatus.notificationSelected";
export const CANCEL_SCAN_COMMAND_ID = "codesight.cancelJob";
export const OPEN_SETTINGS_COMMAND_ID = "codesight.configure";
export const OPEN_INSTALLED_TOOLS_MSG_COMMAND_ID = "codesight.installed.tools";
export const OPEN_EMAIL_VERIFICATION_MSG_COMMAND_ID = "codesight.email.verification.view";
export const EDIT_COVERITY_SERVER_INFO_COMMAND_ID = "codesight.edit.coverity.server.info";
export const EXPORT_LOGS_COMMAND_ID = "codesight.export.logs";
export const EDIT_BLACK_DUCK_SERVER_INFO_COMMAND_ID = "codesight.edit.black.duck.server.info";
export const EDIT_POLARIS_SERVER_INFO_COMMAND_ID = "codesight.edit.polaris.server.info";
export const EDIT_SRM_SERVER_INFO_COMMAND_ID = "codesight.edit.srm.server.info";
const SIGMA_JOB_ID = "sigma";
export const EDIT_COVERITY_SERVER_SETTINGS = "Edit Coverity Server Settings";
export const EDIT_BLACK_DUCK_SERVER_SETTINGS = "Edit Black Duck SCA Server Settings";
export const EDIT_POLARIS_SERVER_SETTINGS = "Edit Polaris Server Settings";
export const EDIT_SRM_SERVER_SETTINGS = "Edit SRM Server Settings";
/**
 * This IssuesFoundPresenter is responsible for determining the structure and functionality of
 * the Issues Found View, and updating the view when new data is available
 */
export class ExtensionStatusPresenter implements ToolStateServiceListener, ScanToolConfigListener, AuthenticationServiceListener {

    treeProvider: ExtensionStatusTreeProvider;
    treeView: TreeView<ExtensionStatusTreeItem>;
    commandDisposables: Disposable[];
    notifications: Map<string, NotificationMessage>;
    scanJobs: Map<string, RefreshStatus>;
    sigmaScanJobs: Set<string>;

    extensionVersion: string;

    serverInfo: ServerInfo | undefined;
 
    openCoverityServerSettingsCommand = {
        command: EDIT_COVERITY_SERVER_INFO_COMMAND_ID,
        title: EDIT_COVERITY_SERVER_SETTINGS // Not user facing
    };

    openBlackDuckServerSettingsCommand = {
        command: EDIT_BLACK_DUCK_SERVER_INFO_COMMAND_ID,
        title: EDIT_BLACK_DUCK_SERVER_SETTINGS // Not user facing
    };

    openPolarisServerSettingsCommand = {
        command: EDIT_POLARIS_SERVER_INFO_COMMAND_ID,
        title: EDIT_POLARIS_SERVER_SETTINGS // Not user facing
    };

    openSRMServerSettingsCommand = {
        command: EDIT_SRM_SERVER_INFO_COMMAND_ID,
        title: EDIT_SRM_SERVER_SETTINGS // Not user facing
    };

    constructor(treeProvider: ExtensionStatusTreeProvider, treeView:TreeView<ExtensionStatusTreeItem>) {
        
        let extensionVersion = getService(ExtensionService.id).getCodeSightVersion();

        if (extensionVersion === "") {
            getLogger().error("Could not determine extension version of " + EXTENSION_ID);
            this.extensionVersion = localize("extension.status.unknown.version", "Unknown");
        } else {
            this.extensionVersion = extensionVersion;
        }

        this.treeProvider = treeProvider;
        this.treeView = treeView;
        this.commandDisposables = [];
        this.notifications = new Map<string, NotificationMessage>();
        this.scanJobs = new Map<string, RefreshStatus>();
        this.sigmaScanJobs = new Set<string>();

        getService(ToolStateService.id).addListener(this);
        getService(ScanToolConfigService.id).addListener(this);
        getService(AuthenticationService.id).addListener(this);

        this.initCommands();
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        this.reloadViewData();
    }

    onAuthenticated(serverType: ServerType): Promise<void> {
        return this.reloadViewData();
    }

    /**
    * Async method to force refresh of view data
    */
    async refresh(): Promise<void> {
        return this.reloadViewData();
    }

    dispose() {
        getService(ToolStateService.id).removeListener(this);
        getService(ScanToolConfigService.id).removeListener(this);
        getService(AuthenticationService.id).removeListener(this);
        this.commandDisposables.forEach(disposable => disposable.dispose());
    }

    async onToolStateChanged(toolType: ToolTypeEnum, toolState: ToolStateEnum, toolVersion: string): Promise<void> {
        return this.reloadViewData();
    }

    async onSuggestedToolVersionChanged(tooltype: ToolTypeEnum, suggestedVersion: string): Promise<void> {
        return this.reloadViewData();
    }

    async onToolConfigChanged(_: ToolTypeEnum): Promise<void> {
        // no-op
    }

    public async refreshNotification(message: NotificationMessage) {
        let id = getUniqueID(message);
        if (this.notifications.has(id)) {
            await this.parseNotificationMessage(message);
        }
    }

    /**
     * Removes error notification with the matching tool
     * If the message is not constructed, make sure the ID is unique
     */
    public async removeSetupErrorNotification(tool: ToolTypeEnum) {
        this.notifications.forEach(async (message: NotificationMessage, id: string) => {
            if (isSetupErrorState(message) && tool === getToolType(message)) {
                this.notifications.delete(id);
                await this.reloadViewData();
            }
        });
    }
    
    public async removeAuthRequiredNotification(tool: ToolTypeEnum) {
        this.notifications.forEach(async (message: NotificationMessage, id: string) => {
            if ((isCoverityAuthMessage(message) || isBlackduckAuthMessage(message)) && tool === getToolType(message)) {
                this.notifications.delete(id);
                await this.reloadViewData();
            }
        });
    }

    public getUpdateMessage(tool: ToolTypeEnum): NotificationMessage | undefined {
        let foundMessage: NotificationMessage | undefined;
        this.notifications.forEach((message: NotificationMessage, key: string) => {
            if (isUpdateMessage(message)) {
                if (tool === ToolTypeEnum.Sigma && isSigmaMessage(message)) {
                    foundMessage = message;
                } else if (tool === ToolTypeEnum.Blackduck && isBlackduckMessage(message)) {
                    foundMessage = message;
                } else if (tool === ToolTypeEnum.Coverity && isCoverityMessage(message)) {
                    foundMessage = message;
                }
            }
        });

        return foundMessage;
    }

    public async parseNotificationMessage(message: NotificationMessage) {
        let skipMessage = await this.shouldIgnoreNotificationMessage(message);
        if (skipMessage) {
            // stateless setup messages should not update the notifications we display
            return;
        }

        let id = getUniqueID(message); // unique identifier

        // Cases to remove the message:
        // - setup success message
        if (isSetupMessage(message) && isSetupSuccessState(message)) {
            this.notifications.delete(id);
        } else {
            this.notifications.set(id, message);
        }

        return this.reloadViewData();
    }

    public async parseResultsMessage(resultsNotification: MonitorResultsNotification) {
        let resultStatus: RefreshStatus | undefined = resultsNotification.getStatus();
        if (!resultStatus) {
            getLogger().warn("Unexpected state: MonitorResultsNotification from controller has no status");
            return;
        }
        let scanStatus = resultStatus.getStatus();

        switch (scanStatus) {
            case RefreshStatus.Status.PREPARING:
            case RefreshStatus.Status.RUNNING:
                if (this.isSigmaScan(resultStatus)) {
                    this.sigmaScanJobs.add(resultStatus.getJobid());
                    if (this.sigmaScanJobs.size === 1) {
                        this.scanJobs.set(SIGMA_JOB_ID, resultStatus);
                    } else {
                        return;
                    }
                } else {
                    this.scanJobs.set(resultStatus.getJobid(), resultStatus);
                }
                break;
            case RefreshStatus.Status.FAILED:
            case RefreshStatus.Status.CANCELLED:
            case RefreshStatus.Status.SUCCESS:
                if (this.isSigmaScan(resultStatus)) {
                    this.sigmaScanJobs.delete(resultStatus.getJobid());
                    if (this.sigmaScanJobs.size === 0) {
                        this.scanJobs.delete(SIGMA_JOB_ID);
                    } else {
                        return;
                    }
                } else {
                    this.scanJobs.delete(resultStatus.getJobid());
                }
        }

        return this.reloadViewData();
    }

    private async shouldIgnoreNotificationMessage(message: NotificationMessage): Promise<boolean> {
        // some setup notification messages provide only noise, or override previous messages with the same ID, such as an "idle" setup message
        if (isScanningToolAvailableMessage(message) || isCsseLicenseStateMessage(message) || isAutoInstallToolSetupMessage(message)) {
            return true;
        }

        // ignore all setup messages which are not a completion state, an update prompt, or an in-progress download/install message
        if (isSetupMessage(message)) {
            return !(isSetupSuccessState(message) || isSetupErrorState(message) || isUpdateMessage(message) || isDownloadRelatedSetupMessage(message) || isNoToolMatchState(message));
        }

        // ignore welcome messages if one already exists
        if (isWelcomeMessage(message)) {
            let welcomeMessageExists = this.notifications.get(WELCOME_ID) !== undefined;

            // refresh the server status when we receive the welcome message for the first time
            if (!welcomeMessageExists) {
                return false;
            } else {
                return true;
            }
        }

        return false;
    }

    private async onNotificationSelected(message: NotificationMessage): Promise<WebviewPresenter> {
        return getService(WebviewCoordinator.id).showNotification(message);
    }

    private initCommands() {
        this.commandDisposables.push(commands.registerCommand(NOTIFICATION_SELECTED_COMMAND_ID, (message: NotificationMessage): Promise<WebviewPresenter> => {
            return this.onNotificationSelected(message);
        }));

        this.commandDisposables.push(commands.registerCommand(CANCEL_SCAN_COMMAND_ID, async (treeItem: ExtensionStatusTreeItem) => {
            const logger = getLogger();
            if (!treeItem?.jobId) {
                logger.warn("Unexpected state: Cancel job invoked on an undefined tree item or a status tree item without a job id");
                return;
            }

            let analysisServiceClient = await getService(ControllerClientService.id).getAnalysisServiceClient();
            let cancelRequest = new CancelRequest();
            cancelRequest.addJobs(treeItem.jobId);
            logger.debug("Requesting that the controller cancel job " + treeItem.jobId);
            return analysisServiceClient.cancelJobs(cancelRequest);
        }));

        this.commandDisposables.push(commands.registerCommand(OPEN_SETTINGS_COMMAND_ID, () => {
            return commands.executeCommand('workbench.action.openSettings', "@ext:" + EXTENSION_ID);
        }));

        this.commandDisposables.push(commands.registerCommand(OPEN_INSTALLED_TOOLS_MSG_COMMAND_ID, () => {
            return getService(WebviewCoordinator.id).showInstalledToolsMessage();
        }));

        this.commandDisposables.push(commands.registerCommand(OPEN_EMAIL_VERIFICATION_MSG_COMMAND_ID, () => {
            return getService(WebviewCoordinator.id).showEmailVerificationMessage();
        }));

        this.commandDisposables.push(commands.registerCommand(EDIT_COVERITY_SERVER_INFO_COMMAND_ID , async () => {
            return getService(WebviewCoordinator.id).showEditCoverityServerConfiguration(true);
        }));

        this.commandDisposables.push(commands.registerCommand(EXPORT_LOGS_COMMAND_ID, async () => {
            return getService(WebviewCoordinator.id).showExportLogs();
        }));

        this.commandDisposables.push(commands.registerCommand(EDIT_BLACK_DUCK_SERVER_INFO_COMMAND_ID, async () => {
            return getService(WebviewCoordinator.id).showEditBlackDuckServerConfiguration(true);
        }));

        this.commandDisposables.push(commands.registerCommand(EDIT_POLARIS_SERVER_INFO_COMMAND_ID, async () => {
            return getService(WebviewCoordinator.id).showEditPolarisServerConfiguration(true);
        }));

        this.commandDisposables.push(commands.registerCommand(EDIT_SRM_SERVER_INFO_COMMAND_ID, async () => {
            return getService(WebviewCoordinator.id).showEditSRMServerConfiguration(true);
        }));
    }

    private getSeverityIconPath(message: NotificationMessage): string {
        let contextService = getService(VscodeContextService.id);

        switch (message.getSeverity()) {
            case Message.Severity.ERROR:
                return contextService.getIconPath('severity-high.svg', 'severity');
            case Message.Severity.WARNING:
            case Message.Severity.DEBUG:
            case Message.Severity.TRACE:
            case Message.Severity.INFO:
            default:
                return contextService.getIconPath('severity-low.svg', 'severity');
        }
    }

    private async reloadViewData() {
        let treeItems: ExtensionStatusTreeItem[] = [];
        let treeItemChildrenMap = new Map<ExtensionStatusTreeItem, ExtensionStatusTreeItem[]>();

        let notificationsTreeItem = new ExtensionStatusTreeItem(localize("extension.status.view.notifications.title", "Notifications:"), TreeItemCollapsibleState.None);
        treeItems.push(notificationsTreeItem);

        const codeSightScanConfig = await getService(ScanToolConfigService.id).getCodeSightScanConfig();
        const authenticationService = getService(AuthenticationService.id);

        const settingsIcon = {
            dark: getService(VscodeContextService.id).getIconPath("settings-dark.svg", "general"),
            light: getService(VscodeContextService.id).getIconPath("settings-light.svg", "general"),
        };
        const wrenchIcon = {
            dark: getService(VscodeContextService.id).getIconPath("wrench-dark.svg", "general"),
            light: getService(VscodeContextService.id).getIconPath("wrench-light.svg", "general"),
        };

        let notificationAdded = false;
        this.notifications.forEach((message: NotificationMessage, key: string) => {
            notificationAdded = true;
            let newTreeItem = new ExtensionStatusTreeItem("", TreeItemCollapsibleState.None);
            newTreeItem.description = getMessageSummaryForState(message);

            newTreeItem.iconPath = this.getSeverityIconPath(message);
            newTreeItem.command = {
                command: NOTIFICATION_SELECTED_COMMAND_ID,
                arguments: [message],
                title: "Notification selected in tree" // Not user facing
            };
            newTreeItem.contextValue = getTreeItemContext(ContextValue.copyable);

            treeItems.push(newTreeItem);
        });

        if (!notificationAdded) {
            treeItems = treeItems.concat(this.getNoNotificationsMessage());
        }

        const openInstalledToolsCommand = {
            command: OPEN_INSTALLED_TOOLS_MSG_COMMAND_ID,
            title: "Open installed tools" // Not user facing
        };
        const openCSSettingsCommand = {
            command: COMMAND_OPEN_CS_SETTINGS,
            title: "Open CS settings" // Not user facing
        };

        const loadingIcon = {
            dark: getService(VscodeContextService.id).getIconPath("spinner-dark.svg", "general"),
            light: getService(VscodeContextService.id).getIconPath("spinner-light.svg", "general"),
        };

        let productDetailsHeader = new ExtensionStatusTreeItem(localize("extension.status.view.product.details.title", "Product Details:"), TreeItemCollapsibleState.None);
        treeItems.push(productDetailsHeader);

        let installedProductsHeader = new ExtensionStatusTreeItem("", TreeItemCollapsibleState.None);
        installedProductsHeader.description = localize("extension.status.view.installed.products", "Products and Licenses");
        installedProductsHeader.contextValue = getTreeItemContext(ContextValue.copyable);
        installedProductsHeader.command = openInstalledToolsCommand;
        installedProductsHeader.iconPath = wrenchIcon;
        treeItems.push(installedProductsHeader);

        // Code Sight Settings
        let settingsItem = new ExtensionStatusTreeItem("", TreeItemCollapsibleState.None);
        settingsItem.description = localize("extension.status.view.product.settings", "Code Sight Settings");
        settingsItem.iconPath = settingsIcon;
        settingsItem.command = openCSSettingsCommand;
        treeItems.push(settingsItem);

        let isEmptyWorkspace = getService(WorkspaceService.id).getWorkspaceFolders().length === 0;

        // determine if we have found tools, or are loading
        // if a tool state is unknown, assume we are still loading that tool availability
        // plugin state is loading if either tool is still loading

        const toolStateService = getService(ToolStateService.id);
        const coverityState = toolStateService.getStateForTool(ToolTypeEnum.Coverity);
        const coverityLoading = !isEmptyWorkspace && coverityState === ToolStateEnum.Unknown;

        const sigmaState = toolStateService.getStateForTool(ToolTypeEnum.Sigma);
        const sigmaLoading = !isEmptyWorkspace && sigmaState === ToolStateEnum.Unknown;

        const blackduckState = toolStateService.getStateForTool(ToolTypeEnum.Blackduck);
        const blackduckLoading = !isEmptyWorkspace && blackduckState === ToolStateEnum.Unknown;

        const pluginLoading = coverityLoading || sigmaLoading || blackduckLoading;

        if (!isEmptyWorkspace && !pluginLoading) {
            let serverConnectionItems = [];

            // Polaris server item
            let polarisServerItem;
            let polarisServerInfo = authenticationService.getServerInfo(ServerType.POLARIS);
            if (polarisServerInfo) {
                polarisServerItem = this.getServerConnectionItem(polarisServerInfo);
            } else {
                polarisServerItem = this.getNoConnectionServerItem(ServerType.POLARIS);
            }
            serverConnectionItems.push(polarisServerItem);

            // Coverity server item
            let coverityServerItem;
            let coverityOnPolarisServerInfo = authenticationService.getServerInfo(ServerType.COVERITYONPOLARIS);
            if(coverityOnPolarisServerInfo) {
                coverityServerItem = this.getServerConnectionItem(coverityOnPolarisServerInfo);
            } else {
                let coverityServerInfo = authenticationService.getServerInfo(ServerType.COVERITYCONNECT);
                if(coverityServerInfo) {
                    coverityServerItem = this.getServerConnectionItem(coverityServerInfo);
                } else {
                    coverityServerItem = this.getNoConnectionServerItem(ServerType.COVERITYCONNECT);
                }
            }
            serverConnectionItems.push(coverityServerItem);

            // Black Duck server item
            let blackDuckServerItem;
            let blackDuckServerInfo = authenticationService.getServerInfo(ServerType.BLACKDUCKHUB);
            if(blackDuckServerInfo) {
                blackDuckServerItem = this.getServerConnectionItem(blackDuckServerInfo);
            } else {
                blackDuckServerItem = this.getNoConnectionServerItem(ServerType.BLACKDUCKHUB);
            }
            serverConnectionItems.push(blackDuckServerItem);

            // SRM server item
            let srmServerItem;
            let srmServerInfo = authenticationService.getServerInfo(ServerType.SOFTWARERISKMANAGER);
            if (srmServerInfo) {
                srmServerItem = this.getServerConnectionItem(srmServerInfo);
            } else {
                srmServerItem = this.getNoConnectionServerItem(ServerType.SOFTWARERISKMANAGER);
            }
            serverConnectionItems.push(srmServerItem);
            
            if(serverConnectionItems.length > 0) {
                const serverHeader = new ExtensionStatusTreeItem(localize("extension.status.view.server.connections", "Server Connections:"), TreeItemCollapsibleState.None);
                treeItems.push(serverHeader);
                treeItems.push(...serverConnectionItems);
            }
        }
        this.treeProvider.setItems(treeItems, treeItemChildrenMap);
    }

    private getServerConnectionItem(serverInfo: ServerInfo): ExtensionStatusTreeItem {
        let serverConnectionItem = new ExtensionStatusTreeItem("", TreeItemCollapsibleState.None);
        serverConnectionItem.description = `${getServerShortName(serverInfo.getType())}: ${serverInfo.getUrl()}`;
    
        let openServerSettingsCommand;

        switch (serverInfo.getType()) {
            case ServerType.COVERITYCONNECT:
                openServerSettingsCommand = this.openCoverityServerSettingsCommand;
                serverConnectionItem.contextValue = getTreeItemContext(ContextValue.editCoverityServerInfo);
                break;
            case ServerType.COVERITYONPOLARIS:
                openServerSettingsCommand = this.openCoverityServerSettingsCommand;
                serverConnectionItem.contextValue = getTreeItemContext(ContextValue.editCoverityServerInfo);
                break;
            case ServerType.BLACKDUCKHUB:
                openServerSettingsCommand = this.openBlackDuckServerSettingsCommand;
                serverConnectionItem.contextValue = getTreeItemContext(ContextValue.editBlackDuckServerInfo);
                break;
            case ServerType.POLARIS:
                openServerSettingsCommand = this.openPolarisServerSettingsCommand;
                serverConnectionItem.contextValue = getTreeItemContext(ContextValue.editPolarisServerInfo);
                break;
            case ServerType.SOFTWARERISKMANAGER:
                openServerSettingsCommand = this.openSRMServerSettingsCommand;
                serverConnectionItem.contextValue = getTreeItemContext(ContextValue.editSRMServerInfo);
                break;
        }

        serverConnectionItem.command = openServerSettingsCommand;
        serverConnectionItem.tooltip = serverInfo.getHumanreadableservername();
        return serverConnectionItem;
    }

    private getNoConnectionServerItem(serverType: ServerType): ExtensionStatusTreeItem {
        const noCoverityServerFoundDescription = localize("extension.status.view.codesight.coverity.no.tools", "No Coverity server connected");
        const noCoverityServerFoundTooltip = localize("extension.status.view.tools.coverity.no.server", "No Coverity Connect or Coverity on Polaris Server has been found. Code Sight offers best results and performance when connected to a Coverity Connect or Coverity on Polaris Server. Try authenticating to a Coverity Platform or Coverity on Polaris server by clicking the notifications above");
        const noBlackDuckServerFoundDescription = localize("extension.status.view.codesight.bd.no.tools", "No Black Duck SCA server connected"); 
        const noBlackDuckServerFoundTooltip = localize("extension.status.view.tools.bd.no.server", "No Black Duck SCA server has been found. Code Sight offers best results and performance when connected to a Black Duck SCA Server. Try authenticating to a Black Duck SCA server by clicking the notifications above");
        const noPolarisServerFoundDescription = localize("extension.status.view.codesight.polaris.no.tools", "No Polaris server connected"); 
        const noPolarisServerFoundTooltip = localize("extension.status.view.tools.polaris.no.server", "No Polaris server has been found. Code Sight offers best results and performance when connected to a Polaris Server. Try authenticating to a Polaris Server by clicking the notifications above");
        const noSRMServerFoundDescription = localize("extension.status.view.codesight.srm.no.tools", "No SRM server connected"); 
        const noSRMServerFoundTooltip = localize("extension.status.view.tools.srm.no.server", "No Software Risk Manager (SRM) server has been found. Code Sight offers best results and performance when connected to a SRM Server. Try authenticating to a SRM Server by clicking the notifications above");

        let serverItem = new ExtensionStatusTreeItem("", TreeItemCollapsibleState.None);
        switch (serverType) {
            case ServerType.COVERITYCONNECT:
            case ServerType.COVERITYONPOLARIS:
                serverItem.description = noCoverityServerFoundDescription;
                serverItem.tooltip = noCoverityServerFoundTooltip;
                serverItem.command = this.openCoverityServerSettingsCommand;
                serverItem.contextValue = getTreeItemContext(ContextValue.editCoverityServerInfo);
                return serverItem;
            case ServerType.BLACKDUCKHUB:
                serverItem.description = noBlackDuckServerFoundDescription;
                serverItem.tooltip = noBlackDuckServerFoundTooltip;
                serverItem.command = this.openBlackDuckServerSettingsCommand;
                serverItem.contextValue = getTreeItemContext(ContextValue.editBlackDuckServerInfo);
                return serverItem;
            case ServerType.POLARIS:
                serverItem.description = noPolarisServerFoundDescription;
                serverItem.tooltip = noPolarisServerFoundTooltip;
                serverItem.command = this.openPolarisServerSettingsCommand;
                serverItem.contextValue = getTreeItemContext(ContextValue.editPolarisServerInfo);
                return serverItem;
                case ServerType.SOFTWARERISKMANAGER:
                    serverItem.description = noSRMServerFoundDescription;
                    serverItem.tooltip = noSRMServerFoundTooltip;
                    serverItem.command = this.openSRMServerSettingsCommand;
                    serverItem.contextValue = getTreeItemContext(ContextValue.editSRMServerInfo);
                    return serverItem;
            default: 
                return serverItem;
        }
    }

    private getNoNotificationsMessage(): ExtensionStatusTreeItem[] {
        let emptyNotificationsItem = new ExtensionStatusTreeItem("", TreeItemCollapsibleState.None);
        emptyNotificationsItem.description = localize("extension.status.view.notifications.empty", "No notifications to display");
        return [emptyNotificationsItem];
    }

    private isSigmaScan(resultStatus: RefreshStatus): boolean {
        return resultStatus.getTooltype() === LicensedToolsConfig.Type.SIGMA;
    }
}
