import { ScanConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/scan_config_pb";
import { ServerType } from "@codesight/codesight-controller-proto/controller_proto/v0/server_info_pb";
import { Modifier, NamedFilter, SelectionState } from "@codesight/codesight-controller-proto/controller_proto/v1/issues_service_pb";

export enum FilterViewType {
  TEAM_VIEW,
  LOCAL_VIEW
}

export type FilterViewProps = {
  _serverType?: ServerType;
  _scanType?: ScanConfig.ScanType.Type;
  _isAutoScanMode?: boolean;
  _namedFilter: NamedFilter.AsObject;
  currentUser: Option[];
  _viewType: FilterViewType;
}

export type Option = {
  id: string;
  value: string;
  label: string;
  error?: string;
  state: SelectionState;
}

export type SearchModifier = {
  id: string;
  value: string;
  type: Modifier.ModifierType;
  state: SelectionState;
}