import { NewEvent } from "../models/newIssue";
import { getService, ServiceId } from "../services/serviceContainer";
import { ViewProviderService } from "./viewProviderService";

export abstract class RevealTreeService {
    static readonly id: ServiceId<RevealTreeService> = { id: RevealTreeService.name };

    abstract revealTeamViewTree(teamViewEvent: NewEvent): Promise<void>;
    abstract revealLocalViewTree(localViewEvent: NewEvent): Promise<void>;
}

export class RevealTreeServiceImpl extends RevealTreeService {

    async revealTeamViewTree(teamViewEvent: NewEvent) {
        const teamViewIssuesPresenter = getService(ViewProviderService.id).getOrCreateTeamViewPresenter();
        await teamViewIssuesPresenter.revealTreeForEvent(teamViewEvent);
    }

    async revealLocalViewTree(localViewEvent: NewEvent) {
        const localViewIssuesPresenter = getService(ViewProviderService.id).getOrCreateLocalViewPresenter();
        await localViewIssuesPresenter.revealTreeForEvent(localViewEvent);
    }
        
}
