import * as path from 'path';
import { tmpNameSync } from 'tmp';
import { ExtensionConfigService } from '../services/extensionConfigService';
import { getService } from '../services/serviceContainer';
import { ENV_CODESIGHT_DESKTOP_CONTROLLER_HOME, ENV_CODESIGHT_DESKTOP_CONTROLLER_OUTPUT_FILE, ENV_CODESIGHT_DESKTOP_CONTROLLER_USE_TEMP_OUTPUT_FILE, FOLDER_NAME_BINARY, FOLDER_NAME_CONFIG, FOLDER_NAME_CONTROLLER, FOLDER_NAME_DESKTOP } from '../utils/constants';
import * as envUtils from '../utils/environmentUtils';

export function getControllerHome() {
    if (envUtils.getEnvVar(ENV_CODESIGHT_DESKTOP_CONTROLLER_HOME)) {
        return envUtils.getEnvVar(ENV_CODESIGHT_DESKTOP_CONTROLLER_HOME);
    }
    let bdHome = getService(ExtensionConfigService.id).getBlackDuckHomePath();
    if (bdHome) {
        return path.join(bdHome, FOLDER_NAME_DESKTOP, FOLDER_NAME_CONTROLLER);
    }
    return undefined;
}

export function getControllerBinaryRootPath() {
    let controllerHome = getControllerHome();
    if (controllerHome) {
        return path.join(controllerHome, FOLDER_NAME_BINARY);
    }
    return undefined;
}

export function getStartupOutputConfigFilePath(fullVersion: string) {
    let version = getControllerVersionMajorMinorRevision(fullVersion);
    if (envUtils.getEnvVar(ENV_CODESIGHT_DESKTOP_CONTROLLER_OUTPUT_FILE)) {
        return envUtils.getEnvVar(ENV_CODESIGHT_DESKTOP_CONTROLLER_OUTPUT_FILE);
    }

    // eslint-disable-next-line no-constant-condition -- this seems like it would always be true
    if(envUtils.getEnvVar(ENV_CODESIGHT_DESKTOP_CONTROLLER_USE_TEMP_OUTPUT_FILE), true) {
        return tmpNameSync();
    }

    let controllerHome = getControllerHome();
    if (controllerHome) {
        return path.join(controllerHome, FOLDER_NAME_CONFIG, `startup-${ version }.json`);
    }
    return undefined;
}

function getControllerVersionMajorMinorRevision(fullVersion: string) {
    let versFields = fullVersion.split(".");
    const expectedMinVersionFieldCount = 3;
    if (versFields.length < expectedMinVersionFieldCount) {
        return "";
    } else {
        return `${ versFields[0] }.${ versFields[1] }.${ versFields[2] }`;
    }
}
