import { Event, EventEmitter, ProviderResult, TreeDataProvider, TreeItem } from "vscode";
import { Copyable } from "../../utils/interfaces";

export interface CodeSightSetupTreeProvider extends TreeDataProvider<CodeSightSetupTreeItem> {

    /**
     * Set the data for the Code Sight Setup Tree
     * Triggers a refresh of the tree
     *
     * @param treeItems The root items of the tree
     * @param itemChildren A map of tree items to their children. Any item which does not appear as a key in
     *                     this map is presumed to be a leaf node of the tree
     */
    setItems(rootTreeItems: CodeSightSetupTreeItem[], itemChildren: Map<CodeSightSetupTreeItem, CodeSightSetupTreeItem[]>): void;

}

export class CodeSightSetupTreeItem extends TreeItem implements Copyable {


    getCopyText(): string {
        return this.label + (this.description ? " " + this.description : "");
    }
}

export class CodeSightSetupTreeProviderImpl implements CodeSightSetupTreeProvider {

    private _onDidChangeTreeData: EventEmitter<CodeSightSetupTreeItem | null> = new EventEmitter<CodeSightSetupTreeItem | null>();
    readonly onDidChangeTreeData: Event<CodeSightSetupTreeItem | null> = this._onDidChangeTreeData.event;

    protected rootItems: CodeSightSetupTreeItem[];
    protected itemToChildrenMap: Map<CodeSightSetupTreeItem, CodeSightSetupTreeItem[]>;

    constructor() {
        this.rootItems = [];
        this.itemToChildrenMap = new Map();
    }

    setItems(rootTreeItems: CodeSightSetupTreeItem[], itemChildren: Map<CodeSightSetupTreeItem, CodeSightSetupTreeItem[]>): void {
        this.rootItems = rootTreeItems;
        this.itemToChildrenMap = itemChildren;
        this._onDidChangeTreeData.fire(null); // TODO: investigate only firing for changed elements UD-4144
    }

    getTreeItem(element: CodeSightSetupTreeItem): TreeItem | Thenable<TreeItem> {
        return element;
    }

    getChildren(element?: CodeSightSetupTreeItem): ProviderResult<CodeSightSetupTreeItem[]> {
        if (!element) {
            return this.rootItems;
        }
        if (!this.itemToChildrenMap.has(element)) {
            return [];
        }
        return this.itemToChildrenMap.get(element);
    }
}