import { TestServerConnectionResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/configuration_service_pb";
import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { AuthenticationMethod, ServerInfo, ServerType } from "@codesight/codesight-controller-proto/controller_proto/v0/server_info_pb";
import { Disposable, WebviewPanel } from "vscode";
import { LocalizeFunc, loadMessageBundle } from "vscode-nls";
import { AuthModel } from "../../models/authModel";
import { ProxyEventListener, ProxyEventService } from "../../services/ProxyEventService";
import { AuthenticationService } from "../../services/authenticationService";
import { CsBrowserService } from "../../services/browserService";
import { getService } from "../../services/serviceContainer";
import { getLogger } from "../../utils/logger";
import { ProxyComponentCommandIds, handleProxyUpdate, openProxySettings } from "../../views/proxy/proxyConfigComponent";
import { WebviewCoordinator } from "../webviewCoordinator";
import { WebviewPresenter } from "../webviewPresenter";
import { PolarisSingleStepAuthViewProvider } from "./polarisSingleStepAuthViewProvider";
import { SingleStepAuthViewCommandIds, SingleStepAuthViewProviderBase } from "./singleStepAuthViewProviderBase";
import { SRMSingleStepAuthViewProvider } from "./srmSingleStepAuthViewProvider";

export enum AuthStep {
    Initial,
    Password,
    Token,
    CombinedToken,
}
const localize: LocalizeFunc = loadMessageBundle();

export const credentialsAreMissing = localize('auth.credentials.are.missing', "Credentials are missing");
export const awaitingServerStatus = localize('auth.awaiting.server.status', "Checking credentials and server status");
export const testAction = 'conn';
export const saveAction = 'save';

export class SingleStepAuthViewPresenter implements WebviewPresenter, ProxyEventListener {
    private serverType: ServerType;
    private view: SingleStepAuthViewProviderBase;
    private model: AuthModel;
    private onMessageFromWebviewDisposable: Disposable | undefined;
    private existingServerInfo?: ServerInfo;


    constructor(panel: WebviewPanel, serverType: ServerType, existingServerInfo?: ServerInfo) {
        this.serverType = serverType;
        this.existingServerInfo = existingServerInfo;
        this.view = serverType === ServerType.POLARIS ? getService(PolarisSingleStepAuthViewProvider.id) : getService(SRMSingleStepAuthViewProvider.id);
        this.model = new AuthModel();
        this.view.initView(panel);

        getService(ProxyEventService.id).addListener(this);

        this.onMessageFromWebviewDisposable = this.view.onMessageFromWebview(async message => {
            switch (message.command) {
                case SingleStepAuthViewCommandIds.TEST_CONNECTION:
                    this.model.setUrl(message.url);
                    this.model.setPassword(message.password);
                    await this.testConnection();
                    break;
                case SingleStepAuthViewCommandIds.SAVE_SETTINGS: 
                    this.setLoadingState(localize('auth.saving.settings.inprogress', 'Saving settings'));
                    this.model.setUrl(message.url);
                    this.model.setPassword(message.password);
                    let response = await getService(AuthenticationService.id).authenticate(this.model);
                    let success = response === "";

                    if (success) {
                        this.setSuccessState(localize('auth.success.save.text', 'Settings saved'));
                        this.enablePasswordPlaceholder();
                    } else {
                        this.setErrorState(localize('auth.error.save.text', 'Failed to save settings'), response);
                    }
                    break;
                case SingleStepAuthViewCommandIds.BROWSE:
                    let url = message.url;
                    if (!url.startsWith("http://") && !url.startsWith('https://')) {
                        url = "https://" + url;
                    }
                    await getService(CsBrowserService.id).openLink(url);
                    break;
                case SingleStepAuthViewCommandIds.CONFIGURE:
                    await getService(WebviewCoordinator.id).showTeamViewIssueSourceView();
                    break;
                case ProxyComponentCommandIds.OPEN_PROXY_SETTINGS:
                    openProxySettings();
                    break;
                default:
                    getLogger().warn(`Received unexpected message ${message.command}`);
                    break;
            }

            return Promise.resolve();
        });
    }

    private async testConnection() {
        this.setLoadingState(localize('auth.test.connection.inprogress', 'Testing connection'));
        let authInfo = new ServerInfo.AuthInfo();
        authInfo.setMethod(this.model.getAuthMethod());
        authInfo.setKey(this.model.getPassword());
        let serverInfo = new ServerInfo();
        serverInfo.setType(this.serverType);
        serverInfo.setUrl(this.model.getUrl());
        serverInfo.setAuthinfo(authInfo);
        let response = await getService(AuthenticationService.id).testServerConnection(serverInfo);

        let success = response.getStatus() === TestServerConnectionResponse.Status.SUCCESS;

        if (success) {
            this.setSuccessState(localize('auth.success.testconnection.text', 'Ok - Credentials and server URL are valid'));
        } else {
            this.setErrorState("", response.getStatusmessage());
        }
    }

    onProxyInformationUpdated(): void {
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        handleProxyUpdate(this.view);
    }

    public async parseNotification(message: NotificationMessage) {
    }

    public async initView() {

        // makes sure server type is set when serverInfo is undefined
        this.model.setServerType(this.serverType);
        this.model.setAuthMethod(AuthenticationMethod.TOKEN);
        
        if (this.existingServerInfo) {
            this.model.setUrl(this.existingServerInfo.getUrl());
        }

        this.reloadHtml();
        await handleProxyUpdate(this.view);
        if (this.model.getUrl()) {
            await this.testConnection();
        }
    }

    private setLoadingState(localizedMessage: string) {
        this.view.postMessageToWebview({
            command: SingleStepAuthViewCommandIds.SET_STATUS,
            type: 'spin',
            message: localizedMessage,
        });

        this.enableButtons(false);
    }

    private setErrorState(errorHeader: string, errorMessage: string) {
        this.view.postMessageToWebview({
            command: SingleStepAuthViewCommandIds.SET_STATUS,
            type: 'error',
            header: errorHeader,
            message: errorMessage,
        });
        this.enableButtons(true);
    }

    private setSuccessState(saveMessage: string) {
        this.view.postMessageToWebview({
            command: SingleStepAuthViewCommandIds.SET_STATUS,
            type: 'success',
            message: saveMessage,
        });
        this.enableButtons(true);
    }

    private enablePasswordPlaceholder() {
        this.view.postMessageToWebview({
            command: SingleStepAuthViewCommandIds.SAVE_SUCCESSFUL,
        });
    }

    private enableButtons(enable: boolean) {
        this.view.postMessageToWebview({
            command: SingleStepAuthViewCommandIds.ENABLE_BUTTON,
            enable: String(enable),
            primary: "true",
            buttonId: 'saveSettings',
        });
        this.view.postMessageToWebview({
            command: SingleStepAuthViewCommandIds.ENABLE_BUTTON,
            enable: String(enable),
            buttonId: 'testConnection',
        });
    }

    private reloadHtml() {
        this.view.reloadHtml(this.model);
    }

    public dispose() {
        this.onMessageFromWebviewDisposable?.dispose();
        getService(ProxyEventService.id).removeListener(this);
    }
}