import { TestServerConnectionResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/configuration_service_pb";
import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { AuthenticationMethod, ServerInfo, ServerType } from "@codesight/codesight-controller-proto/controller_proto/v0/server_info_pb";
import * as url from "url";
import { Disposable, WebviewPanel } from "vscode";
import { LocalizeFunc, loadMessageBundle } from "vscode-nls";
import { AuthModel } from "../../models/authModel";
import { ProxyEventListener, ProxyEventService } from "../../services/ProxyEventService";
import { AuthenticationService } from "../../services/authenticationService";
import { CsBrowserService } from "../../services/browserService";
import { getService } from "../../services/serviceContainer";
import { SetupService } from "../../services/setupService";
import { ToolTypeEnum } from "../../services/toolStateService";
import { ViewProviderService } from "../../services/viewProviderService";
import { VsCodeInputService } from "../../services/vscodeInputService";
import { CC_AUTH_KEY_CREATE_URL_SEGMENTS, COP_ACCESS_TOKEN_CREATE_URL_SEGMENTS } from "../../utils/constants";
import { getLogger } from "../../utils/logger";
import { ProxyComponentCommandIds, handleProxyUpdate, openProxySettings } from "../proxy/proxyConfigComponent";
import { WebviewCoordinator } from "../webviewCoordinator";
import { WebviewPresenter } from "../webviewPresenter";
import { AuthenticationViewCommandIds, AuthenticationViewProviderBase } from "./authenticationViewProviderBase";
import { BlackDuckAuthenticationViewProvider } from "./blackDuckAuthenticationViewProvider";
import { CoverityAuthenticationViewProvider } from "./coverityAuthenticationViewProvider";

export enum AuthStep {
    Initial,
    Password,
    Token,
    AuthkeyOrPassword
}
const localize: LocalizeFunc = loadMessageBundle();

export const credentialsAreMissing = localize('auth.credentials.are.missing', "Credentials are missing");
export const awaitingServerStatus = localize('auth.awaiting.server.status', "Checking credentials and server status");

export class AuthenticationViewPresenter implements WebviewPresenter, ProxyEventListener {
    private model: AuthModel;
    private view: AuthenticationViewProviderBase;
    private authStep: AuthStep;
    private isEditServerConfig: boolean;
    private onMessageFromWebviewDisposable: Disposable | undefined;
    private toolType: ToolTypeEnum;

    constructor(panel: WebviewPanel, toolType: ToolTypeEnum, onDoneClicked: () => void, isEditServerConfig?: boolean) {
        this.toolType = toolType;

        switch (this.toolType) {
            case ToolTypeEnum.Blackduck:
                this.view = getService(BlackDuckAuthenticationViewProvider.id);
                break;
            case ToolTypeEnum.Coverity:
            default: // fallthrough
                this.view = getService(CoverityAuthenticationViewProvider.id);
                break;
        }
        this.model = new AuthModel();
        this.view.initView(panel);
        this.authStep = AuthStep.Initial;
        this.isEditServerConfig = isEditServerConfig ? isEditServerConfig : false;

        getService(ProxyEventService.id).addListener(this);

        this.onMessageFromWebviewDisposable = this.view.onMessageFromWebview(async message => {
            switch (message.command) {
                case 'continue-url':
                    {
                        this.setLoadingState();
                        this.model.setUserName(message.username).setUrl(message.url);
                        let response = await getService(AuthenticationService.id).determineAuthType(this.model);

                        let authMethod;
                        if (response.authMethod === AuthenticationMethod.SAML_SSO) {
                            // change authentication method to token since SAML_SSO is not supported
                            authMethod = AuthenticationMethod.TOKEN;
                        } else {
                            authMethod = response.authMethod;
                        }

                        this.model.setAuthMethod(authMethod);
                        switch (this.toolType) {
                            case ToolTypeEnum.Blackduck:
                                this.model.setServerType(ServerType.BLACKDUCKHUB);
                                break;
                            default:
                                this.model.setServerType(response.serverType);
                        }

                        if (response.errorMessage !== "") {
                            this.setErrorState(response.errorMessage);
                        } else {
                            if (response.serverType === ServerType.COVERITYCONNECT) {
                                this.authStep = AuthStep.AuthkeyOrPassword;
                            } else {
                                switch (response.authMethod) {
                                    case AuthenticationMethod.PASSWORD:
                                        this.authStep = AuthStep.Password;
                                        break;
                                    case AuthenticationMethod.SAML_SSO:
                                    case AuthenticationMethod.TOKEN:
                                        this.authStep = AuthStep.Token;
                                        break;
                                }
                            }
                            this.reloadHtml();
                        }
                    }
                    break;
                case 'continue-password':
                    {
                        this.model.setPassword(message.password);
                        this.setLoadingState();
                        let response = await getService(AuthenticationService.id).authenticate(this.model);
                        let success = response === "";

                        if (success) {
                            this.setSuccessState();

                            this.view.postMessageToWebview({
                                command: 'enable-continue-button',
                                enable: "true"
                            });

                            // remove auth required message after successful authentication
                            await getService(ViewProviderService.id).getOrCreateExtensionStatusPresenter().removeAuthRequiredNotification(this.toolType);
                        } else {
                            this.setErrorState(response);
                        }
                    }
                    break;
                case 'continue-authkey-or-password':
                    {
                        if (message.method !== "") {
                            switch (message.method) {
                                case AuthenticationMethod.PASSWORD.toString():
                                    this.model.setAuthMethod(AuthenticationMethod.PASSWORD);
                                    this.model.setPassword(message.password);
                                    break;
                                case AuthenticationMethod.SAML_SSO.toString():
                                case AuthenticationMethod.TOKEN.toString():
                                    this.model.setAuthMethod(AuthenticationMethod.TOKEN);
                                    this.model.setAuthkey(message.authkey);
                                    break;
                            }
                        }
                        this.setLoadingState();
                        let response = await getService(AuthenticationService.id).authenticate(this.model);
                        let success = response === "";

                        if (success) {
                            this.setSuccessState();

                            this.view.postMessageToWebview({
                                command: 'enable-continue-button',
                                enable: "true"
                            });

                            // remove auth required message after successful authentication
                            await getService(ViewProviderService.id).getOrCreateExtensionStatusPresenter().removeAuthRequiredNotification(this.toolType);
                        } else {
                            this.setErrorState(response);
                        }
                    }
                    break;
                case 'browseBdHub':
                    await getService(CsBrowserService.id).openLink(this.model.getUrl());
                    break;
                case 'browseCop':
                    let fullUrl = url.resolve(this.model.getUrl(), COP_ACCESS_TOKEN_CREATE_URL_SEGMENTS);
                    await getService(CsBrowserService.id).openLink(fullUrl);
                    break;
                case 'browseCC':
                    let ccfullUrl = url.resolve(this.model.getUrl(), CC_AUTH_KEY_CREATE_URL_SEGMENTS);
                    await getService(CsBrowserService.id).openLink(ccfullUrl);
                    break;
                case 'previous':
                    this.authStep = AuthStep.Initial;
                    if (this.toolType === ToolTypeEnum.Coverity) {
                        this.model.setServerType(ServerType.UNKNOWNSERVERTYPE);
                    }
                    this.reloadHtml();
                    await handleProxyUpdate(this.view);
                    break;
                case 'done':
                    onDoneClicked();
                    switch (this.model.getServerType()) {
                        case ServerType.COVERITYCONNECT:
                        case ServerType.COVERITYONPOLARIS:
                            await getService(WebviewCoordinator.id).showEditCoverityServerConfiguration(true);
                            break;
                        case ServerType.BLACKDUCKHUB:
                            await getService(WebviewCoordinator.id).showEditBlackDuckServerConfiguration(true);
                            break;
                    }
                    break;
                case 'configure':
                    await getService(WebviewCoordinator.id).showTeamViewIssueSourceView();
                    break;
                case 'view-previous':
                    await getService(SetupService.id).authPreviousClicked();
                    break;
                case AuthenticationViewCommandIds.CHOOSE_AUTHKEY_FILE:
                    let authkeyFile = await getService(VsCodeInputService.id).showOpenDialog({ canSelectFolders: false, canSelectMany: false });
                    if (!authkeyFile || authkeyFile.length < 1) {
                        getLogger().debug("No file selected from authkey view browser");
                        break;
                    }
                    this.view.postMessageToWebview({
                        command: AuthenticationViewCommandIds.SET_AUTHKEY_PATH,
                        value: authkeyFile[0].fsPath,
                    });
                    break;
                case ProxyComponentCommandIds.OPEN_PROXY_SETTINGS:
                    openProxySettings();
                    break;
                default:
                    getLogger().warn(`Received unexpected message ${message.command}`);
                    break;
            }

            return Promise.resolve();
        });
    }
    onProxyInformationUpdated(): void {
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        handleProxyUpdate(this.view);
    }

    public async parseNotification(message: NotificationMessage) {
        // TODO: change text if this is an update case
    }

    async refreshServerConnectionMessage(serverInfo?: ServerInfo) {
        let isServerInfoComplete = serverInfo !== undefined
            && serverInfo.getUrl() !== "";
        if (!isServerInfoComplete || serverInfo === undefined) {
            this.view.postMessageToWebview({
                command: 'set-status',
                type: 'error',
                message: credentialsAreMissing,
            });
            return;
        }

        // Spin while we are awaiting responses
        this.view.postMessageToWebview({
            command: 'set-status',
            type: 'spin',
            message: awaitingServerStatus,
        });

        // Test server connection
        let serverConnectionStatus = await getService(AuthenticationService.id).testServerConnection(serverInfo);
        this.view.postMessageToWebview({
            command: 'set-status',
            type: (serverConnectionStatus && serverConnectionStatus.getStatus() === TestServerConnectionResponse.Status.SUCCESS) ? "success" : "error",
            message: serverConnectionStatus ? serverConnectionStatus.getStatusmessage() : "",
        });
    }

    public async initView() {
        let serverInfo;

        switch (this.toolType) {
            case ToolTypeEnum.Blackduck:
                this.model.setServerType(ServerType.BLACKDUCKHUB); // makes sure server type is set when serverInfo is undefined
                serverInfo = await getService(AuthenticationService.id).fetchServerInfo(ServerType.BLACKDUCKHUB);
                break;
            case ToolTypeEnum.Coverity:
                this.model.setServerType(ServerType.UNKNOWNSERVERTYPE); // let controller resolve server type
                serverInfo = await getService(AuthenticationService.id).fetchServerInfo(ServerType.COVERITYONPOLARIS);
                if (!serverInfo) {
                    serverInfo = await getService(AuthenticationService.id).fetchServerInfo(ServerType.COVERITYCONNECT);
                }
                break;
        }

        if (serverInfo) {
            this.model.setUrl(serverInfo.getUrl());

            let authInfo = serverInfo.getAuthinfo();
            if (authInfo) {
                this.model.setUserName(authInfo.getUsername());
            }
        }

        this.reloadHtml();
        if (this.isEditServerConfig) {
            await this.refreshServerConnectionMessage(serverInfo);
        }

        await handleProxyUpdate(this.view);
    }

    private setLoadingState() {
        // spinner added in the provider

        // disable continue button     
        this.view.postMessageToWebview({
            command: 'enable-continue-button',
            enable: "false"
        });
    }

    private setErrorState(errorMessage: string) {
        this.view.postMessageToWebview({
            command: 'set-status',
            type: 'error',
            message: errorMessage,
        });
        this.view.postMessageToWebview({ command: 'remove-spinner' });
        this.view.postMessageToWebview({
            command: 'enable-continue-button',
            enable: "true"
        });
    }

    private setSuccessState() {
        this.view.postMessageToWebview({
            command: 'set-status',
            type: 'success',
            message: localize('auth.success.text', 'Ok - Credentials and server URL are valid'),
        });
        this.view.postMessageToWebview({
            command: 'finish-authentication',
            isEditServerConfig: String(this.isEditServerConfig)
        });
    }

    private reloadHtml() {
        this.view.reloadHtml(this.authStep, this.model, this.isEditServerConfig);

        if (this.authStep === AuthStep.AuthkeyOrPassword) {
            this.view.postMessageToWebview({
                command: AuthenticationViewCommandIds.SET_AUTHKEY_OPTION_SELECTION,
                value: 'true',
            });
        }
    }

    public dispose() {
        this.onMessageFromWebviewDisposable?.dispose();
        getService(ProxyEventService.id).removeListener(this);
    }
}