import { access, constants, lstatSync, mkdtemp, readdir, readFile, rmdir, stat, unlink, writeFile } from 'fs';
import * as mkdirp from 'mkdirp';
import * as os from 'os';
import { basename, isAbsolute, join, relative, resolve, sep } from 'path';
import { Uri, workspace } from "vscode";
import { isWindows } from "./environmentUtils";

export enum ScannableStatus {
    Scannable,
    BadFileType,
    OutOfWorkspace,
    FileDoesNotExist,
    Ignore
}

export function fileExists(filePath: string): Promise<boolean> {
    return new Promise<boolean>((resolve) => {
        stat(filePath, (err, exists) => {
            if (err || exists === null) { resolve(false); }
            else { resolve(true); }
        });
    });
}

export function isFile(filePath: string): boolean {
    return lstatSync(filePath).isFile();
}

export function isFileExecutable(filepath: string): Promise<boolean> {
    return new Promise<boolean>((resolve) => {
        access(filepath, constants.X_OK, (err) => {
            if (err) {
                resolve(false);
            }
            resolve(true);
        });
    });
}

export async function createDir(dirPath: string): Promise<void> {
    return new Promise<void>((resolve, reject) => {
        mkdirp(dirPath, (err) => {
            if (err) { reject(err); }
            else { resolve(); }
        });
    });
}

export async function readFileToString(filePath: string): Promise<string> {
    return new Promise<string>((resolve, reject) => {
        readFile(filePath, 'utf-8', (err, data) => {
            if (err) { reject(err); }
            else { resolve(data); }
        });
    });
}

export async function writeToFile(filePath: string, contents: string): Promise<void> {
    return new Promise<void>((resolve, reject) => {
        writeFile(filePath, contents, 'utf-8', error => {
            if (error) { reject(error); }
            else { resolve(); }
        });
    });
}

export function getBaseFileName(filepath: string) {
    return basename(filepath);
}

export function middleTruncateFilepath(filepath: string): string {
    if (isValidFileFormat(filepath)) {
        const fileName = getBaseFileName(filepath);
        const firstSegment = filepath.substring(0,filepath.indexOf(sep));
        const length = firstSegment.length + fileName.length;
        const MAX_LENGTH = 50;
        const maxLength = Math.max(MAX_LENGTH, length);

        if(filepath.length > maxLength){
            return `${firstSegment}${sep}...${sep}${fileName}`;
        }
    }
    return filepath;
}

/**
 * Validates if the current string is of a valid file format.
 * This looks for the following:
 *   - a separator character (/ or \)
 *   - followed by at least one word/digit/period/dash character
 *   - followed by a period
 *   - ending with at least two word/digit characters
 * 
 * @param filepath 
 * @returns 
 */
function isValidFileFormat(filepath: string): boolean {
    let regex = new RegExp("[\\\\/][A-Za-z0-9.\\-_]{1,}.(?:[A-Za-z0-9]{2,})$");
    return filepath.match(regex) !== null;
}

export async function makeTmpDir(prefix: string, tmpDir: string = os.tmpdir()): Promise<string> {
    return new Promise<string>((resolve, reject) => {
        mkdtemp(join(tmpDir, prefix), (err, folder) => {
            if (err) {
                reject(err);
            } else {
                resolve(folder);
            }
        });
    });
}

export async function listDir(dirPath: string): Promise<string[]> {
    return new Promise<string[]>((resolve, reject) => {
        readdir(dirPath, (err, items) => {
            if (err) { reject(err); }
            else { resolve(items); }
        });
    });
}

export async function rmFile(path: string): Promise<void> {
    return new Promise<void>((resolve, reject) => {
        unlink(path, err => {
            if (err) {
                reject(err);
            } else {
                resolve();
            }
        });
    });
}

export async function rmDir(path: string): Promise<void> {
    return new Promise<void>((resolve, reject) => {
        rmdir(path, { recursive: true }, err => {
            if (err) {
                reject(err);
            } else {
                resolve();
            }
        });
    });
}

/**
 * VSCode often returns Windows paths with a lower case drive letter, whereas Coverity will return an upper-case drive letter
 *
 * Accepts a path, and, if the OS is Windows and the path is absolute, ensure the drive letter is capitalized
 */
export function normalizeDriveLetter(path: string): string {
    if (path && isWindows() && isAbsolute(path)) {
        path = path[0].toUpperCase() + path.slice(1);
    }
    return path;
}

/**
 * Checks if a file path is within a given folder by resolving both paths
 * and verifying the folder is a proper directory prefix.
 * Resolving handles '..' sequences and ensures consistent comparison.
 */
export function isPathWithinFolder(filePath: string, folderPath: string): boolean {
    const resolvedFile = resolve(filePath);
    const resolvedFolder = resolve(folderPath);
    const rel = relative(resolvedFolder, resolvedFile);
    return rel.length > 0 && !rel.startsWith('..') && !isAbsolute(rel);
}

/**
 * Normalizes a Windows file path by converting all backslashes to forward slashes. Consecutive backslashses are converted to a
 * single slash e.g '\\' -> '/'
 */
export function normalizePathSeparators(path: string) {
    if (path) {
        path = path.replace(/\\+/g, '/');
    }
    return path;
}

/**
 * Queries to see if the file at the given uri is scannable. Returns ScannableStatus.Scannable if the file can be scanned.
 * Returns ScannableStatus.BadFileType if the file type is not scannable, and ScannableStatus.OutOfWorkspace if the file
 * type is scannable but exists outside of the workspace.
 *
 * @param uri the uri for the file in question
 */
export async function isFileScannable(uri: Uri): Promise<ScannableStatus> {
    // Exclude scanning text documents that are not actually files
    if (uri.scheme !== "file") {
        return ScannableStatus.BadFileType;
    }

    // Exclude scanning text documents that don't exist (e.g. this can happen with virtual files for git / mercurial)
    if (!(await fileExists(uri.fsPath))) {
        return ScannableStatus.FileDoesNotExist;
    }

    let workspaceFolder = workspace.getWorkspaceFolder(uri);
    if (!workspaceFolder) {
        return ScannableStatus.OutOfWorkspace;
    }

    if(uri.fsPath.match(/.*settings.json$/)?.length === 1
        || workspace.workspaceFile?.toString() === uri.toString()){
        return ScannableStatus.Ignore;
    }

    return ScannableStatus.Scannable;
}