import { ContributingDetail, DisplayType, NewIssue } from "../models/newIssue";
import { getLogger } from "../utils/logger";
import { IssueSourceConfigService, IssueSourceConfigServiceListener } from "./issueSourceConfigService";
import { IssuesListIdentifier, IssuesListService, LocalViewIssuesListService, TeamViewIssuesListService } from "./issuesService";
import { ServiceId, getService } from "./serviceContainer";

export abstract class IssueSelectionService {
    static readonly id: ServiceId<IssueSelectionService> = { id: IssueSelectionService.name };

    abstract selectNewIssue(issueId: string, issueListIdentifier: IssuesListIdentifier, displayType: DisplayType): Promise<ListSelection | undefined>;
    abstract selectNewOccurrence(issueId: string, occurrenceIndex: number, issueListIdentifier: IssuesListIdentifier, displayType: DisplayType): Promise<ListSelection | undefined>;
    abstract selectNewEvent(issueId: string, occurrenceIndex: number, eventNumber: number, issueListIdentifier: IssuesListIdentifier, displayType: DisplayType):  Promise<ListSelection | undefined>;
    abstract getIssuesListSelection(identifier: IssuesListIdentifier): Selection | undefined;
    abstract getSelection(): ListSelection | undefined;
    abstract getLastSelection(): ListSelection | undefined;
    abstract getSelectedOccurrence(issue: NewIssue): ContributingDetail | undefined;
    abstract clearSelection(identifier: IssuesListIdentifier): Promise<void>;
    abstract addListener(listener: IssueSelectionServiceListener): void;
    abstract removeListener(listener: IssueSelectionServiceListener): void;
}
export interface Selection {
    tag: SelectionTag;
    issueId: string;
    displayType: DisplayType;
    occurrenceIndex: number;
    eventNumber?: number;
    issue: NewIssue;
}

export type SelectionTag = 'TeamViewIssueSelection' | 'TeamViewOccurrenceSelection' | 'TeamViewEventSelection' | 'LocalViewIssueSelection' | 'LocalViewOccurrenceSelection' | 'LocalViewEventSelection';

export interface ListSelection {
    selection: Selection;
    list: IssuesListIdentifier;
}

export interface IssueSelectionServiceListener {
    onSelectionChanged(listSelection: ListSelection | undefined): Promise<void>;
}

export function selection_equals(a: Selection, b: Selection): boolean {
    return a.tag === b.tag &&
        a.eventNumber === b.eventNumber &&
        a.occurrenceIndex === b.occurrenceIndex &&
        a.issueId === b.issueId &&
        a.displayType === b.displayType;
}

export class IssueSelectionServiceImpl extends IssueSelectionService implements IssueSourceConfigServiceListener {
    issueLists: Map<IssuesListIdentifier, IssuesListService<NewIssue>> = new Map();
    protected listeners: IssueSelectionServiceListener[];
    issueListSelections: Map<IssuesListIdentifier, Selection> = new Map();
    selection: ListSelection | undefined;
    lastSelection: ListSelection | undefined;
    
    constructor() {
        super();
        this.listeners = [];
        this.issueLists.set(IssuesListIdentifier.TeamViewIssuesList, getService(TeamViewIssuesListService.id));
        this.issueLists.set(IssuesListIdentifier.LocalViewIssuesList, getService(LocalViewIssuesListService.id));

        getService(IssueSourceConfigService.id).addListener(this);
        getService(LocalViewIssuesListService.id).addListener(this);
    }

    private async createSelection(issueId: string, issueListIdentifier: IssuesListIdentifier,  displayType: DisplayType, occurrenceIndex: number, eventNumber?: number): Promise<ListSelection | undefined> {
        let issuesListService = this.issueLists.get(issueListIdentifier);
        if (!issuesListService) {
            return;
        }

        let issue = await issuesListService.getIssue(issueId, displayType);
        if (!issue) {
            return;
        }

        const tagMapping = this.getTagMapping();

        const tag = occurrenceIndex !== undefined
            ? (eventNumber !== undefined ? tagMapping[issueListIdentifier].event : tagMapping[issueListIdentifier].occurrence)
            : tagMapping[issueListIdentifier].issue;

        const selection = {
            tag,
            issueId,
            occurrenceIndex,
            eventNumber,
            displayType,
            issue,
        } as Selection;

        let newListSelection: ListSelection = {
            selection: selection,
            list: issueListIdentifier
        };

        let occurrences = issue.getEventInfo()?.getContributingDetails() ?? [];
        if (occurrenceIndex !== undefined && (occurrenceIndex < 0 || occurrenceIndex >= occurrences.length)) {
            getLogger().warn(`Invalid occurrence index ${occurrenceIndex} for issue ${issueId}. Valid range: 0-${occurrences.length - 1}`);
        }
        
        await this.selectAndNotifyIfChanged(newListSelection);

        return this.selection;
    }

    async selectNewIssue(issueId: string, issueListIdentifier: IssuesListIdentifier, displayType: DisplayType): Promise<ListSelection | undefined> {
        return this.createSelection(issueId, issueListIdentifier, displayType, 0);
    }

    async selectNewOccurrence(issueId: string, occurrenceIndex: number, issueListIdentifier: IssuesListIdentifier, displayType: DisplayType): Promise<ListSelection | undefined> {
        return this.createSelection(issueId, issueListIdentifier, displayType, occurrenceIndex);
    }

    async selectNewEvent(issueId: string, occurrenceIndex: number, eventNumber: number, issueListIdentifier: IssuesListIdentifier, displayType: DisplayType): Promise<ListSelection | undefined> {
        return this.createSelection(issueId, issueListIdentifier, displayType, occurrenceIndex, eventNumber);
    }

    private async selectAndNotifyIfChanged(listSelection: ListSelection) {
        let currentSelection = this.getSelection();
        if (currentSelection &&
            listSelection.list === currentSelection.list &&
            selection_equals(listSelection.selection, currentSelection.selection)) {
            // Selection is unchanged
            return;
        }

        this.selection = listSelection;

        if (this.selection) {
            this.lastSelection = this.selection;
        }
        
        this.issueListSelections.set(listSelection.list, listSelection.selection);
        await this.onSelectionChanged();
    }

    private getTagMapping(): Record<IssuesListIdentifier, Record<string, SelectionTag>> {
        return {
            [IssuesListIdentifier.TeamViewIssuesList]: {
                issue: 'TeamViewIssueSelection',
                occurrence: 'TeamViewOccurrenceSelection',
                event: 'TeamViewEventSelection',
            },
            [IssuesListIdentifier.LocalViewIssuesList]: {
                issue: 'LocalViewIssueSelection',
                occurrence: 'LocalViewOccurrenceSelection',
                event: 'LocalViewEventSelection',
            },
        };
    }
    
    getIssuesListSelection(identifier: IssuesListIdentifier): Selection| undefined {
        return this.issueListSelections.get(identifier);
    }

    getSelection(): ListSelection | undefined {
        return this.selection;
    }

    getLastSelection(): ListSelection | undefined {
        return this.lastSelection;
    }

    getSelectedOccurrence(issue: NewIssue): ContributingDetail | undefined {
        const currentSelection = this.getSelection();
        if (!currentSelection) {
            return undefined;
        }

        if (currentSelection.selection.issueId !== issue.getIssueId()) {
            return undefined;
        }

        const occurrenceIndex = currentSelection.selection.occurrenceIndex ?? 0;
        const contributingDetails = issue.getEventInfo()?.getContributingDetails();
        
        if (!contributingDetails || occurrenceIndex < 0 || occurrenceIndex >= contributingDetails.length) {
            return undefined;
        }

        return contributingDetails[occurrenceIndex];
    }

    async clearSelection(identifier: IssuesListIdentifier): Promise<void> {
        if (!this.selection) {
            // no need to clear anything
            return;
        }

        this.issueListSelections.delete(identifier);
        if (this.selection?.list === identifier) {
            this.selection = undefined;
            await this.onSelectionChanged();
        }
    }

    async onSelectionChanged(): Promise<void> {
        let promises: Promise<void>[] = [];
        this.listeners.forEach((listener) => {
            promises.push(listener.onSelectionChanged(this.selection));
        });
        await Promise.all(promises);
    }

    addListener(listener: IssueSelectionServiceListener): void {
        this.listeners.push(listener);
    }

    removeListener(listener: IssueSelectionServiceListener): void {
        let index = this.listeners.indexOf(listener);
        if (index >= 0) {
            this.listeners.splice(index, 1);
        }
    }

    async onIssueSourceListUpdated(): Promise<void> {
        // no-op
    }

    async onSelectedSourceChanged(): Promise<void> {
        await this.clearSelection(IssuesListIdentifier.TeamViewIssuesList);
    }

    async onIssuesReloaded(issuesListIdentifier: IssuesListIdentifier): Promise<void> {
        const issueList = this.issueLists.get(issuesListIdentifier);
        if (!issueList) return;

        const selection = this.issueListSelections.get(issuesListIdentifier);
        if (!selection) return;

        const issue = await issueList.getIssue(selection.issueId, selection.displayType);
        const clearSelection = await this.shouldClearSelection(issuesListIdentifier, issue);

        if (clearSelection) {
            await this.clearSelection(issuesListIdentifier);
        } else if (issuesListIdentifier === IssuesListIdentifier.LocalViewIssuesList) {
            if (issue) {
                await this.repopulateLocalViewIssue(issue);
            }
        }
    }

    private async shouldClearSelection(issuesListIdentifier: IssuesListIdentifier, issue: NewIssue | undefined): Promise<boolean> {
        if (issuesListIdentifier === IssuesListIdentifier.LocalViewIssuesList) {
            if (issue && issue.getDisplayType() !== DisplayType.MARKER) {
                const localViewIssuesListService = getService(LocalViewIssuesListService.id);
                const selectedResultScanType = await localViewIssuesListService.getSelectedResultScanType();
                const previousScanType = localViewIssuesListService.getPreviousSelectedScanType();
                if (selectedResultScanType?.getType() !== previousScanType?.getType()) {
                    return true;
                }
            }
        }
        return !issue;
    }

    private async repopulateLocalViewIssue(issue: NewIssue): Promise<void> {
        const localViewIssuesListService = getService(LocalViewIssuesListService.id);
        await localViewIssuesListService.loadDetailsAndEventsForIssue(issue);
        await this.onSelectionChanged();
    }
}
