import { DismissIssuesRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/issues_service_pb";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { getLogger } from "../utils/logger";
import { AnalysisContextService } from "./analysisContextService";
import { ControllerClientService } from "./controllerClientService";
import { getService, ServiceId } from "./serviceContainer";
import { VsCodeInputService } from "./vscodeInputService";

const localize: LocalizeFunc = loadMessageBundle();

export abstract class IssueDismissalService {

    static readonly id: ServiceId<IssueDismissalService> = { id: IssueDismissalService.name };

    /**
     * Dismisses or undismissed the issues with the given issue IDs
     *
     * @param issueIds the IDs of the issues to update
     * @param dismiss if true, dismiss the issues, else undismiss them
     */
    abstract updateIssueDismissal(issueIds: string[], dismiss: boolean): Promise<void>;
}


export class IssueDismissalServiceImpl extends IssueDismissalService {
    async updateIssueDismissal(issueIds: string[], dismiss: boolean): Promise<void> {

        let comment = await getService(VsCodeInputService.id).showInputBox({
            prompt: dismiss ? localize('dismissal.comment.prompt', 'Please enter a dismissal comment') : localize('undismissal.comment.prompt', 'Please enter an un-dismissal comment'),
            ignoreFocusOut: true,
            validateInput: (value: string) => {
                if (value.length === 0) {
                    return dismiss ?
                        localize('dismissal.comment.empty', 'The issue dismissal comment cannot be empty') :
                        localize('undismissal.comment.empty', 'The issue un-dismissal comment cannot be empty');
                }
                return undefined;
            }
        });

        if (!comment) {
            getLogger().info(`No comment entered for the dismissal of ${issueIds}. Aborting dismissal`);
            return;
        }

        let dismissRequest = new DismissIssuesRequest();
        dismissRequest.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        issueIds.forEach(issueId => {
            dismissRequest.addIssueids(issueId);
        });
        dismissRequest.setComment(comment);
        dismissRequest.setDismiss(dismiss);

        let issueServiceClient = await getService(ControllerClientService.id).getIssuesServiceClient();
        await issueServiceClient.dismissIssues(dismissRequest);
    }

}