import { CollectLogsRequest, CollectLogsResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/collect_logs_pb";
import { commands, Uri } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { AnalysisContextService } from "../../services/analysisContextService";
import { ControllerClientService } from "../../services/controllerClientService";
import { ExtensionConfigService } from "../../services/extensionConfigService";
import { getService } from "../../services/serviceContainer";
import { WebviewProvider } from "../../views/webviewProvider";

export const EXPORT_LOGS_BUTTON_ID = "export-logs-button";
export const OPEN_LOGS_FOLDER_BUTTON_ID = "open-folder-button";
export const EXPORT_LOGS_RESPONSE_LOADING_ID = "export-in-progress";
export const EXPORT_LOGS_RESPONSE_SUCCESS_ID = "export-success";
export const EXPORT_LOGS_RESPONSE_FAILURE_ID = "export-failure";

const localize: LocalizeFunc = loadMessageBundle();

/**
 * HTML to include in the <body> section of a webview to add the UI for an export logs component
 */
export const EXPORT_LOGS_BODY = `
    <div class="box">
        <button class="button-left button" type="button" id='${EXPORT_LOGS_BUTTON_ID}'>
            <div class='box'>
                <div class='button-content'>
                    <span>${localize("export.logs.button.text", "Export Logs")}</span>
                    <img class='margin-left hidden spinner-icon' id='export-logs-button-inner-icon' width='20' height='20'/>
                </div>
            </div>
        </button>
        <img class="margin-left hint-icon" title="${localize('export.logs.component.help.text', "Log files can contain confidential information.\nThese logs will be exported:\n - Extension log file(s)\n - Controller log file(s)\n - Single-file scan logs\n - Full scan logs")}" width="24" height="24"/>
    </div>
    <div id="export-logs-status" class="hidden box">
        <img id="export-logs-status-img" width="24" height="24"/>
        <p id="export-logs-status-text" class="margin-left"></p>
        <div id="open-logs-folder" class="hidden box">
            <button class="button open-folder-icon" id='${OPEN_LOGS_FOLDER_BUTTON_ID}' title="${localize("export.logs.open.folder.text", "Open Folder")}"></button>
        </div>
    </div>
`;


/**
 * HTML to include in the <scripts> section of a webview to enable the functionality of an export logs component
 */
export const EXPORT_LOGS_SCRIPTS = `
    window.addEventListener('message', event => {
        const message = event.data;
        switch (message.command) {
            case '${EXPORT_LOGS_RESPONSE_LOADING_ID}':
                showExportLogsLoadingState();
                break;
            case '${EXPORT_LOGS_RESPONSE_FAILURE_ID}':
                showExportLogsFailureMessage(message);
                break;
            case '${EXPORT_LOGS_RESPONSE_SUCCESS_ID}':
                showExportLogsSuccessMessage(message);
                break;
        }
    });

    function showExportLogsLoadingState() {
        revealExportLogsSpinner()
        hideStatusMessage()
    }

    function showExportLogsSuccessMessage(message) {
        hideExportLogsSpinner()
        revealOpenLogsButton()
        updateStatusMessage(message.text, "success-icon", "var(--vscode-terminal-ansiGreen)")
    }

    function showExportLogsFailureMessage(message) {
        hideExportLogsSpinner()
        hideOpenLogsButton();
        updateStatusMessage(message.text, "severity-high", "var(--vscode-errorForeground)")
    }

    function hideExportLogsSpinner() {
        let icons = document.querySelectorAll("#export-logs-button-inner-icon");

        icons.forEach(function(icon) {
            icon.classList.add('hidden');
        });
    }

    function revealExportLogsSpinner() {
        let icons = document.querySelectorAll("#export-logs-button-inner-icon");

        icons.forEach(function(icon) {
            icon.classList.remove('hidden');
        });
    }

    function hideOpenLogsButton() {
        let buttons = document.querySelectorAll("#open-logs-folder");

        buttons.forEach(function(button) {
            button.classList.add('hidden');
        });
    }

    function revealOpenLogsButton() {
        let buttons = document.querySelectorAll("#open-logs-folder");

        buttons.forEach(function(button) {
            button.classList.remove('hidden');
        });
    }

    function hideStatusMessage() {
        let statusSections = document.querySelectorAll("#export-logs-status");
        statusSections.forEach(function(statusSection) {
            statusSection.classList.add('hidden');
        });
    }

    function revealStatusMessage() {
        let statusSections = document.querySelectorAll("#export-logs-status");
        statusSections.forEach(function(statusSection) {
            statusSection.classList.remove('hidden');
        });
    }

    function updateStatusMessage(message, icon, color){
        revealStatusMessage()
        
        let statusTexts = document.querySelectorAll("#export-logs-status-text");
        statusTexts.forEach(function(statusText) {
            statusText.innerHTML = message;
            statusText.style.color = color;
        });
        
        let statusIcons = document.querySelectorAll("#export-logs-status-img");
        statusIcons.forEach(function(statusIcon) {
            statusIcon.className = "";
            statusIcon.classList.add(icon);
        });   
    }
`;

/**
 * CSS to include in the styling section of a webview to properly format an export logs component
 */
export const EXPORT_LOGS_STYLING = `
    #open-logs-folder {
        padding-left: 10px;
    }
`;

let latestArchivePath = "";
async function exportLogs(scannedFile?: string) {
    let diagnosticsService = await getService(ControllerClientService.id).getDiagnosticsServiceClient();
    let request = new CollectLogsRequest();
    request.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
    if (scannedFile) {
        request.addScannedfiles(scannedFile);
    }
    let extensionLogDir = await getService(ExtensionConfigService.id).getExtensionLogPath();
    request.addAdditionallocations(extensionLogDir);
    return diagnosticsService.collectLogs(request);
}

export async function handleExportLogsButtonClicked(view: WebviewProvider, scannedFile?: string) {
    view.postMessageToWebview({
        command: EXPORT_LOGS_RESPONSE_LOADING_ID,
        text: localize('export.logs.loading.text', "Exporting..."),
    });
    let response = await exportLogs(scannedFile);
    let collectLogsStatus: CollectLogsResponse.Status = response.getStatus();
    if (collectLogsStatus === CollectLogsResponse.Status.SUCCESS) {
        let archivePath = response.getArchivelocation();
        latestArchivePath = archivePath;
        view.postMessageToWebview({
            command: EXPORT_LOGS_RESPONSE_SUCCESS_ID,
            text: localize('export.logs.success.text', "Saved: {0}", archivePath),
        });
    } else {
        let errorMessage = response.getMessage();
        view.postMessageToWebview({
            command: EXPORT_LOGS_RESPONSE_FAILURE_ID,
            text: localize('export.logs.failure.text', "Failed: {0}", errorMessage),
        });
    }

}

export async function handleOpenLogsFolderClicked(view: WebviewProvider) {
    if (latestArchivePath) {
        await commands.executeCommand("revealFileInOS", Uri.file(latestArchivePath));
    }
}