    private renderAutoScanning(state: AutoModeScanningState): TreeNodeProvider[] {
        this.renderHeader(state.scanMode, state.scanFileScope, state.selectedFolder);

        if (state.searchFilter) {
            this.root_nodes.push(new SearchFilterNode(state.searchFilter));
        }

        const separator = new SeparatorNode();
        separator.setIssueListIdFor(IssuesListIdentifier.LocalViewIssuesList);
        this.root_nodes.push(separator);

        // When scanning, always show both Secrets and Vulnerabilities categories (in that order)
        if (state.rapidScan) {
            const secretsScanState: AutoScanState = {
                scanRunning: state.rapidScan.scanning,
                issuesList: [],
                totalIssueCount: undefined
            };
            this.root_nodes.push(new ResultTypeNode(RESULT_TYPE_NAMES.SECRETS, secretsScanState));

            const vulnerabilitiesScanState: AutoScanState = {
                scanRunning: state.rapidScan.scanning,
                issuesList: [],
                totalIssueCount: undefined
            };
            this.root_nodes.push(new ResultTypeNode(RESULT_TYPE_NAMES.VULNERABILITIES, vulnerabilitiesScanState));
        }

        if (state.licenseScan) {
            const licenseScanState: AutoScanState = {
                scanRunning: state.licenseScan.scanning,
                issuesList: [],
                totalIssueCount: undefined
            };
            this.root_nodes.push(new ResultTypeNode(RESULT_TYPE_NAMES.LICENSES, licenseScanState));
        }

        return this.root_nodes;
    }

    private renderAutoResults(state: AutoModeResultsState): TreeNodeProvider[] {
        this.renderHeader(state.scanMode, state.scanFileScope, state.selectedFolder);

        if (state.searchFilter) {
            this.root_nodes.push(new SearchFilterNode(state.searchFilter));
        }

        const separator = new SeparatorNode();
        separator.setIssueListIdFor(IssuesListIdentifier.LocalViewIssuesList);
        this.root_nodes.push(separator);

        // Show rapid scan results (or scanning state if still running)
        if (state.rapidScan) {
            if (state.rapidScan.scanning) {
                // Still scanning - show scanning state (Secrets first, then Vulnerabilities)
                const secretsScanState: AutoScanState = {
                    scanRunning: true,
                    issuesList: [],
                    totalIssueCount: undefined
                };
                this.root_nodes.push(new ResultTypeNode(RESULT_TYPE_NAMES.SECRETS, secretsScanState));

                const vulnerabilitiesScanState: AutoScanState = {
                    scanRunning: true,
                    issuesList: [],
                    totalIssueCount: undefined
                };
                this.root_nodes.push(new ResultTypeNode(RESULT_TYPE_NAMES.VULNERABILITIES, vulnerabilitiesScanState));
            } else {
                if (state.rapidScan.categoryIssues && state.rapidScan.categoryIssues.length > 0) {
                    const categoryOrder: Record<string, number> = {
                        [RESULT_TYPE_NAMES.SECRETS]: 0,
                        [RESULT_TYPE_NAMES.VULNERABILITIES]: 1,
                        [RESULT_TYPE_NAMES.LICENSES]: 2
                    };
                    const sortedCategories = [...state.rapidScan.categoryIssues].sort((a, b) =>
                        (categoryOrder[a.categoryName] ?? 99) - (categoryOrder[b.categoryName] ?? 99)
                    );

                    sortedCategories.forEach(category => {
                        const categoryScanState: AutoScanState = {
                            scanRunning: false,
                            categoryIssuesList: [category],
                            issuesList: [],
                            totalIssueCount: category.totalIssueCount
                        };
                        this.root_nodes.push(new ResultTypeNode(category.categoryName, categoryScanState));
                    });
                } else {
                    // No categories - show flat list under "Vulnerabilities"
                    const rapidScanState: AutoScanState = {
                        scanRunning: false,
                        issuesList: state.rapidScan.flatIssues ?? [],
                        totalIssueCount: state.rapidScan.totalIssueCount
                    };
                    this.root_nodes.push(new ResultTypeNode(RESULT_TYPE_NAMES.VULNERABILITIES, rapidScanState));
                }
                this.issuesShown = true;
            }
        }

        if (state.licenseScan) {
            if (state.licenseScan.scanning) {
                const licenseScanState: AutoScanState = {
                    scanRunning: true,
                    issuesList: [],
                    totalIssueCount: undefined
                };
                this.root_nodes.push(new ResultTypeNode(RESULT_TYPE_NAMES.LICENSES, licenseScanState));
            } else {
                const licenseScanState: AutoScanState = {
                    scanRunning: false,
                    issuesList: state.licenseScan.issues,
                    totalIssueCount: state.licenseScan.totalIssueCount,
                    errors: (state.licenseScan.lastScanStatus === RefreshStatus.Status.FAILED) ? {
                        status: state.licenseScan.lastScanStatus,
                        date: state.licenseScan.lastScanDate
                    } : undefined
                };
                this.root_nodes.push(new ResultTypeNode(RESULT_TYPE_NAMES.LICENSES, licenseScanState));

                // Only mark as shown if not in error state
                if (state.licenseScan.lastScanStatus !== RefreshStatus.Status.FAILED) {
                    this.licenseIssuesShown = true;
                }
            }
        }

        return this.root_nodes;
    }

    private renderAutoNoResults(state: AutoModeNoResultsState): TreeNodeProvider[] {
        this.renderHeader(state.scanMode, state.scanFileScope, state.selectedFolder);

        if (state.searchFilter) {
            this.root_nodes.push(new SearchFilterNode(state.searchFilter));
        }

        const separator = new SeparatorNode();
        separator.setIssueListIdFor(IssuesListIdentifier.LocalViewIssuesList);
        this.root_nodes.push(separator);

        if (state.rapidScan) {
            const secretsState: AutoScanState = {
                scanRunning: false,
                issuesList: [],
                totalIssueCount: 0
            };
            this.root_nodes.push(new ResultTypeNode(RESULT_TYPE_NAMES.SECRETS, secretsState));

            const vulnerabilitiesState: AutoScanState = {
                scanRunning: false,
                issuesList: [],
                totalIssueCount: 0
            };
            this.root_nodes.push(new ResultTypeNode(RESULT_TYPE_NAMES.VULNERABILITIES, vulnerabilitiesState));
        }

        // Show license scan category with 0 results if entitled
        if (state.licenseScan) {
            const licenseScanState: AutoScanState = {
                scanRunning: false,
                issuesList: [],
                totalIssueCount: 0
            };
            this.root_nodes.push(new ResultTypeNode(RESULT_TYPE_NAMES.LICENSES, licenseScanState));
        }

        return this.root_nodes;
    }

