    private renderSignalLoading(state: SignalModeLoadingState): TreeNodeProvider[] {
        this.renderHeader(ScanMode.Auto, state.scanFileScope, state.selectedFolder);
        this.addTimerNodeIfEnabled(state);
        if (state.searchFilter) {
            this.root_nodes.push(new SearchFilterNode(state.searchFilter));
        }
        // Add separator
        this.root_nodes.push(new SeparatorNode());

        this.root_nodes.push(new ScanStatusNode(
            RefreshStatus.Status.RUNNING,
            undefined,
            { type: 'customText', value: localize('signal.mode.loading.results', 'Loading results...') }
        ));

        return this.root_nodes;
    }

