    private renderSignalResults(state: SignalModeResultsState): TreeNodeProvider[] {
        this.renderHeader(ScanMode.Auto, state.scanFileScope, state.selectedFolder);
        this.addTimerNodeIfEnabled(state);
        if (state.searchFilter) {
            this.root_nodes.push(new SearchFilterNode(state.searchFilter));
        }
        // Add separator
        this.root_nodes.push(new SeparatorNode());

        state.categoryIssues.forEach(category => {
            const categoryScanState: AutoScanState = {
                scanRunning: false,
                categoryIssuesList: [category],
                issuesList: [],
                totalIssueCount: category.totalIssueCount
            };
            this.root_nodes.push(new ResultTypeNode(category.categoryName, categoryScanState, true));
        });

        return this.root_nodes;
    }

    private renderSignalNoResults(state: SignalModeNoResultsState): TreeNodeProvider[] {
        this.renderHeader(ScanMode.Auto, state.scanFileScope, state.selectedFolder);
        this.addTimerNodeIfEnabled(state);
        if (state.searchFilter) {
            this.root_nodes.push(new SearchFilterNode(state.searchFilter));
        }
        // Add separator
        this.root_nodes.push(new SeparatorNode());

        if (state.activeFileNotScanned) {
            this.root_nodes.push(...this.buildActiveFileNotScannedMessage());
        } else if (state.hasScanInfo) {
            this.root_nodes.push(...this.buildNoIssuesFoundMessage());
        } else {
            this.root_nodes.push(...this.buildNoScanInfoAvailableMessage());
        }

        return this.root_nodes;
    }

    private renderSimpleView(state: SimpleViewState): TreeNodeProvider[] {
        const baseState = state.baseState;

        if (baseState.type.startsWith('signal')) {
            return this.renderSimpleViewSignal(state);
        } else if (baseState.scanMode === ScanMode.Auto) {
            return this.renderSimpleViewAuto(state);
        } else {
            return this.renderSimpleViewManual(state);
        }
    }

    /**
     * Render SimpleView for Project mode
     */
    private renderSimpleViewManual(state: SimpleViewState): TreeNodeProvider[] {
        const baseState = state.baseState;

        this.renderHeader(ScanMode.Manual);

        if ('selectedScanInfo' in baseState && baseState.selectedScanInfo) {
            this.root_nodes.push(new ScanResultsNode(baseState.selectedScanInfo));
        }

        if ('selectedScanType' in baseState &&
            'appliedDiffFilter' in baseState &&
            'selectedReferenceBranch' in baseState &&
            baseState.selectedScanType?.getSupportsdiffing()) {
            this.root_nodes.push(
                new ReferenceBranchSelectionNode(
                    baseState.appliedDiffFilter,
                    baseState.selectedReferenceBranch
                )
            );
        }

        if ('searchFilter' in baseState && baseState.searchFilter) {
            this.root_nodes.push(new SearchFilterNode(baseState.searchFilter));
        }

        const separator = new SeparatorNode();
        separator.setIssueListIdFor(IssuesListIdentifier.LocalViewIssuesList);
        this.root_nodes.push(separator);

        const diffFilter = ('appliedDiffFilter' in baseState) ? baseState.appliedDiffFilter : undefined;
        this.root_nodes.push(
            new IssueNode(
                IssuesListIdentifier.LocalViewIssuesList,
                state.focusedIssue,
                undefined,
                diffFilter,
                false // Project mode is not signal mode
            )
        );

        this.root_nodes.push(
            new ButtonNode(
                localize('local.view.issues.children.load.view.more.label', 'Back to Issues'),
                COMMAND_LOCAL_VIEW_RESTORE_FULL_LIST,
                { themeIconId: ThemeIconId.arrowCircleLeft }
            )
        );

        return this.root_nodes;
    }

    /**
     * Render SimpleView for Incremental mode
     */
    private renderSimpleViewAuto(state: SimpleViewState): TreeNodeProvider[] {
        const baseState = state.baseState;

        const scanFileScope = ('scanFileScope' in baseState) ? baseState.scanFileScope : undefined;
        const selectedFolder = ('selectedFolder' in baseState) ? baseState.selectedFolder : undefined;
        this.renderHeader(ScanMode.Auto, scanFileScope, selectedFolder);

        if ('searchFilter' in baseState && baseState.searchFilter) {
            this.root_nodes.push(new SearchFilterNode(baseState.searchFilter));
        }

        const separator = new SeparatorNode();
        separator.setIssueListIdFor(IssuesListIdentifier.LocalViewIssuesList);
        this.root_nodes.push(separator);

        if (state.categoryName) {
            const autoScanState: AutoScanState = {
                scanRunning: false,
                categoryIssuesList: [{
                    categoryName: state.categoryName,
                    issuesList: [state.focusedIssue],
                    totalIssueCount: 1
                }],
                issuesList: [],
                totalIssueCount: 1
            };
            this.root_nodes.push(new ResultTypeNode(state.categoryName, autoScanState));
        } else {
            this.root_nodes.push(
                new IssueNode(
                    IssuesListIdentifier.LocalViewIssuesList,
                    state.focusedIssue,
                    undefined,
                    undefined,
                    false // Incremental mode is not signal mode
                )
            );
        }

        this.root_nodes.push(
            new ButtonNode(
                localize('local.view.issues.children.load.view.more.label', 'Back to Issues'),
                COMMAND_LOCAL_VIEW_RESTORE_FULL_LIST,
                { themeIconId: ThemeIconId.arrowCircleLeft }
            )
        );

        return this.root_nodes;
    }

    /**
     * Render SimpleView for Signal mode
     * Matches the pattern from renderSignalResults - no header, no separator
     */
    private renderSimpleViewSignal(state: SimpleViewState): TreeNodeProvider[] {
        const baseState = state.baseState;
        const scanFileScope = ('scanFileScope' in baseState) ? baseState.scanFileScope : undefined;
        const selectedFolder = ('selectedFolder' in baseState) ? baseState.selectedFolder : undefined;
        this.renderHeader(ScanMode.Auto, scanFileScope, selectedFolder);

        // Add search filter if active (Signal mode shows this)
        if ('searchFilter' in baseState && baseState.searchFilter) {
            this.root_nodes.push(new SearchFilterNode(baseState.searchFilter));
        }

        // Signal mode always uses categories, show in ResultTypeNode
        if (state.categoryName) {
            const scanState: AutoScanState = {
                scanRunning: false,
                categoryIssuesList: [{
                    categoryName: state.categoryName,
                    issuesList: [state.focusedIssue],
                    totalIssueCount: 1
                }],
                issuesList: [],
                totalIssueCount: 1
            };
            this.root_nodes.push(new ResultTypeNode(state.categoryName, scanState, true));
        } else {
            // Fallback: show issue directly (shouldn't happen in Signal mode)
            this.root_nodes.push(
                new IssueNode(
                    IssuesListIdentifier.LocalViewIssuesList,
                    state.focusedIssue,
                    undefined,
                    undefined,
                    true // Signal mode
                )
            );
        }

        this.root_nodes.push(
            new ButtonNode(
                localize('local.view.issues.children.load.view.more.label', 'Back to Issues'),
                COMMAND_LOCAL_VIEW_RESTORE_FULL_LIST,
                { themeIconId: ThemeIconId.arrowCircleLeft }
            )
        );

        return this.root_nodes;
    }

