    private buildCSSELicenseError(licenseState: CsseLicenseState): TreeNodeProvider[] {
        const headerNode = new StatusNode(
            Status.Error,
            localize('localview.issues.view.entitlement.error.header', 'Local View scanning disabled')
        );

        let descriptionText: string;
        let linkText: string;
        let commandId: string;

        if (licenseState === CsseLicenseState.EmailVerificationRequired) {
            descriptionText = localize('localview.issues.view.license.verify.content', 'Please verify your email to start scanning');
            linkText = localize('localview.issues.view.installed.tools.verify.link.text', 'Verify Email');
            commandId = OPEN_EMAIL_VERIFICATION_MSG_COMMAND_ID;
        } else {
            descriptionText = localize('localview.issues.view.license.error.content', 'Unable to verify your Standard Edition license');
            linkText = localize('localview.issues.view.installed.tools.link.text', 'View Details');
            commandId = OPEN_INSTALLED_TOOLS_MSG_COMMAND_ID;
        }

        return [
            headerNode,
            new DescriptionNode(descriptionText),
            new ButtonNode(linkText, commandId, { themeIconId: ThemeIconId.goToFile })
        ];
    }

