    private addTimerNodeIfEnabled(state: { timerInfo?: { isActive: boolean; nextScanTime?: Date; lastScanTime?: Date } }): void {
        if (state.timerInfo) {
            this.currentTimerNode = new TimerNode(
                state.timerInfo.isActive,
                state.timerInfo.nextScanTime,
                state.timerInfo.lastScanTime
            );
            this.root_nodes.push(this.currentTimerNode);
        } else {
            this.currentTimerNode = undefined;
        }
    }

    async refreshTimerNode(): Promise<void> {
        if (this.currentTimerNode) {
            await this.reloadNode(this.currentTimerNode);
        }
    }
