import { InputBox, InputBoxOptions, OpenDialogOptions, QuickPick, QuickPickItem, QuickPickOptions, Uri, window } from "vscode";
import { ServiceId } from "./serviceContainer";

/**
 * Service for abstracting user input methods, such as the Input Box and Quick Pick
 * Allows these user input methods to be mocked during tests
 */
export abstract class VsCodeInputService {
    static readonly id: ServiceId<VsCodeInputService> = { id: VsCodeInputService.name };
    abstract createInputBox(): InputBox;
    abstract showInputBox(inputBoxOptions: InputBoxOptions): Thenable<string | undefined>;
    abstract showQuickPick<T extends QuickPickItem>(items: T[], options?: QuickPickOptions): Thenable<T | undefined>;
    abstract showOpenDialog(options?: OpenDialogOptions | undefined): Thenable<Uri[] | undefined>;
    abstract createQuickPick(): QuickPick<QuickPickItem>;
}


export class VsCodeInputServiceImpl implements VsCodeInputService {
    showOpenDialog(options?: OpenDialogOptions): Thenable<Uri[] | undefined> {
        return window.showOpenDialog(options);
    }
    showInputBox(inputBoxOptions: InputBoxOptions): Thenable<string | undefined> {
        return window.showInputBox(inputBoxOptions);
    }

    createInputBox(): InputBox {
        return window.createInputBox();
    }

    showQuickPick<T extends QuickPickItem>(items: T[], options?: QuickPickOptions): Thenable<T | undefined> {
        return window.showQuickPick(items, options);
    }

    createQuickPick(): QuickPick<QuickPickItem> {
        return window.createQuickPick();
    }

}