import { HttpProxyConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/config_pb";
import { GetConfigurationRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/configuration_service_pb";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { AnalysisContextService } from "../../services/analysisContextService";
import { ControllerClientService } from "../../services/controllerClientService";
import { getService } from "../../services/serviceContainer";
import { getLogger } from "../../utils/logger";
import { WebviewCoordinator } from "../webviewCoordinator";
import { WebviewProvider } from "../webviewProvider";

const localize: LocalizeFunc = loadMessageBundle();
const proxyNotConfigured = localize('auth.proxy.notConfigured', "Not configured");
const proxySystemConfigured = localize('auth.proxy.systemConfigured', "Using proxy configuration from OS settings");

export namespace ProxyComponentCommandIds {
    export const OPEN_PROXY_SETTINGS = 'open-proxy-settings';
    export const SET_PROXY_STATUS: string = "set-proxy-status";
}
export async function handleProxyUpdate(view: WebviewProvider) {
    let configService = await getService(ControllerClientService.id).getConfigurationServiceClient();

    let request = new GetConfigurationRequest();
    let analysisContextService = getService(AnalysisContextService.id);
    request.setContextid(analysisContextService.getAnalysisContextId());

    let response = await configService.getConfiguration(request);
    if (response.hasError()) {
        getLogger().warn("Couldn't get configuration: ", response.getError());
        return;
    }

    let proxyConfig = response.getUserconfig()?.getProxyconfig();
    if (!proxyConfig || proxyConfig.getNoproxy()?.getValue()) {
        updateViewWithProxyStatus(view, proxyNotConfigured);
        return;
    }
    else if (proxyConfig.getUsesystemproxy()?.getValue()) {
        updateViewWithProxyStatus(view, proxySystemConfigured);
        return;
    }

    let httpUrl = getUrl(proxyConfig.getHttpproxyconfig());
    let httpsUrl = getUrl(proxyConfig.getHttpsproxyconfig());
    let isHttpConfEnabled = proxyConfig.getHttpproxyconfig()?.getEnabled()?.getValue();
    let isHttpsConfEnabled = proxyConfig.getHttpsproxyconfig()?.getEnabled()?.getValue();

    let httpStatus = isHttpConfEnabled && httpUrl !== "" ? httpUrl : proxyNotConfigured;
    let httpsStatus = isHttpsConfEnabled && httpsUrl !== "" ? httpsUrl : proxyNotConfigured;

    if (httpStatus === httpsStatus) {
        if (httpStatus === proxyNotConfigured) {
            updateViewWithProxyStatus(view, proxyNotConfigured);
            return;
        }
        updateViewWithProxyStatus(view, `HTTP/HTTPS:&nbsp;&nbsp;${httpStatus}`);
        return;
    }

    let proxyStatus = `
        <div style='display: flex; flex-direction: column;'>
            <!-- row 1 -->
            <div style='display: flex;'>
                <label style='min-width: 60px;'>HTTP:</label>
                <label data-http-value>${httpStatus}</label>
            </div>
            
            <!-- row 2 -->
            <div style='display: flex;'>
                <label style='min-width: 60px;'>HTTPS:</label>
                <label data-https-value>${httpsStatus}</label>
            </div>
        </div>
    `;
    updateViewWithProxyStatus(view, proxyStatus);
}

function getUrl(config: HttpProxyConfig | undefined): string {
    let hostname = config?.getHostname()?.getValue();
    if (!hostname || hostname === "") {
        return "";
    }

    let port = config?.getPort()?.getValue();
    if (!port || port <= 0) {
        return hostname;
    }

    return `${hostname}:${port}`;
}

function updateViewWithProxyStatus(view: WebviewProvider, message: string) {
    view.postMessageToWebview({
        command: ProxyComponentCommandIds.SET_PROXY_STATUS,
        value: message
    });
}

export function openProxySettings() {
    // eslint-disable-next-line @typescript-eslint/no-floating-promises
    getService(WebviewCoordinator.id).showProxyView();
}

export function getProxyStatusBody(): string {
    return /*html*/`
    <table>
    
        <tr>
            <td style="width: 70%;">
                <div style="display: flex; align-items: flex-end;">
                    <label><b>${localize('auth.proxy.title', 'Proxy')}:</b></label>
                    <img class="margin-left hint-icon" title="${localize('auth.proxy.hint', 'Proxy settings are optional. If your organization uses a proxy, click \'here\' to add or edit Code Sight\'s proxy settings.')}" width="15" height="15"/>
                </div>
            </td>
            <td rowspan="2">
                <!-- configure proxy button -->
                <button type="button"class='button-full' style="padding: 10px; 7px;" onclick="onConfigureProxyClick();">${localize('auth.configureProxy.title', 'Configure Proxy')}</button>
            </td>
        </tr>
        
        <tr>
            <td>
                <!-- Proxy info section -->
                <span id='proxyStatusLabel'></span>
            </td>
        </tr>
    
    </table>
    `;
}

export function getProxyScript(): string {
    return /*javascript*/`
function setProxyStatus(message){
    let el = document.getElementById('proxyStatusLabel');
    if (el){
        el.innerHTML = message;
    }
}

function onConfigureProxyClick(){
    vscode.postMessage({
        command: 'open-proxy-settings'
    });
}

window.addEventListener('message', event => {
    const message = event.data;
    switch (message.command) {
        case '${ProxyComponentCommandIds.SET_PROXY_STATUS}':
            setProxyStatus(message.value);
            break;
    }
});
`;
}