import { FilePickerTypes } from "@webview-model/models/components/FilePickerModel";
import { getService } from "../../services/serviceContainer";
import { VsCodeInputService } from "../../services/vscodeInputService";
import { getLogger } from "../logger";

export async function onBrowse(type: FilePickerTypes): Promise<string> {
        let browseResult = await getService(VsCodeInputService.id).showOpenDialog({
            canSelectFolders: type === FilePickerTypes.DIRECTORY,
            canSelectFiles: type === FilePickerTypes.FILE,
            canSelectMany: false
        });
        if (!browseResult || browseResult.length < 1) {
            getLogger().debug("No file/directory selected from browseResult open dialog");
            return "";
        }
        
        return browseResult[0].fsPath;
}