import { RegistrationInfo, TrialRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/license_service_pb";
import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { Disposable, env, WebviewPanel } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { ControllerClientService } from "../../services/controllerClientService";
import { getService } from "../../services/serviceContainer";
import { SetupService } from "../../services/setupService";
import { SUPPORT_ADDRESS } from "../../utils/constants";
import { countriesToIsoCodes } from "../../utils/countries";
import { getLogger } from "../../utils/logger";
import { WebviewCoordinator } from "../../views/webviewCoordinator";
import { WebviewPresenter } from "../webviewPresenter";
import { RegistrationFormViewProvider, RegistrationViewCommandIds } from "./registrationFormViewProvider";
const localize: LocalizeFunc = loadMessageBundle();
export class RegistrationFormViewPresenter implements WebviewPresenter {
    private readonly panel: WebviewPanel;
    private view: RegistrationFormViewProvider;
    private isInstalledTools: boolean;
    private onMessageFromWebviewDisposable: Disposable | undefined;

    constructor(panel: WebviewPanel, isInstalledTools: boolean) {
        this.panel = panel;
        this.view = getService(RegistrationFormViewProvider.id);
        this.view.initView(this.panel);
        this.isInstalledTools = isInstalledTools;

        this.onMessageFromWebviewDisposable = this.view.onMessageFromWebview(async message => {
            switch (message.command) {
                case RegistrationViewCommandIds.VIEW_SUBMIT:
                    await this.submitRegistration(message.firstName, message.lastName, message.email, message.country, message.companyName);
                    break;
                case RegistrationViewCommandIds.VIEW_ENABLE_COVERITY:
                    await getService(SetupService.id).beginCoverityUserFlow();
                    break;
                case RegistrationViewCommandIds.VIEW_ENABLE_SRM:
                    await getService(SetupService.id).beginSRMUserFlow();
                    break;
                case RegistrationViewCommandIds.VIEW_ENABLE_POLARIS:
                    await getService(SetupService.id).beginPolarisUserFlow();
                    break;
                case RegistrationViewCommandIds.VIEW_ENABLE_BD:
                    await getService(SetupService.id).beginBlackDuckUserFlow();
                    break;
                case RegistrationViewCommandIds.VIEW_ENABLE_SIGNAL:
                    await getService(SetupService.id).beginSignalUserFlow();
                    break;
                case RegistrationViewCommandIds.VIEW_ADD_LICENSE:
                    await getService(WebviewCoordinator.id).showLicenseView(false, true);
                    break;
                case RegistrationViewCommandIds.VIEW_PROXY_SETTINGS:
                    await getService(WebviewCoordinator.id).showProxyView();
                    break;
                case RegistrationViewCommandIds.VIEW_PREVIOUS:
                    // navigates to installed tools page because the previous button only appears outside of onboarding
                    await getService(WebviewCoordinator.id).showInstalledToolsMessage();
                    break;
                default:
                    getLogger().warn(`Received unexpected message ${ message.command }`);
                    break;
            }

            return Promise.resolve();
        });
    }

    public async parseNotification(message: NotificationMessage) {
    }

    public async initView() {
        // construct country options for dropdown
        const countryNames = Object.keys(countriesToIsoCodes).sort();

        let countryOptions: string = "";
        for (let i = 0; i < countryNames.length; i++) {
            countryOptions += `<option value="${countriesToIsoCodes[countryNames[i]]}">${countryNames[i]}</option>`;
        }

        this.view.initHtml(countryOptions, this.isInstalledTools);
    }

    public dispose() {
        this.onMessageFromWebviewDisposable?.dispose();
    }

    private async submitRegistration(firstName: string, lastName: string, emailAddress : string, country: string, company?:string){
        const logger = getLogger();
        logger.info(`Registering ${firstName} ${lastName} ${emailAddress} ${country}${company ? ` ${company}` : ""}`);

        // disable start trial button and show loading state
        this.view.postMessageToWebview({
            command: RegistrationViewCommandIds.SET_CONTINUE_ENABLED,
            enabled: "false",
        });
        this.view.postMessageToWebview({ 
            command: RegistrationViewCommandIds.SET_STATUS,
            type: RegistrationViewCommandIds.STATUS_LOADING,
            message: localize('registration.start.trial.loading', 'Submitting registration information...')
        });

        const licenseService = await getService(ControllerClientService.id).getLicenseServiceClient();
        const trialRequest = new TrialRequest();
        const registrationInfo = new RegistrationInfo(); 
        registrationInfo.setFirstname(firstName);
        registrationInfo.setLastname(lastName);
        registrationInfo.setEmailaddress(emailAddress);
        registrationInfo.setCountry(country);
        registrationInfo.setIdename(env.appName);
        if(company){
            registrationInfo.setCompany(company);
        }

        trialRequest.setInfo(registrationInfo);

        const noConnectionErrorMessage = localize('registration.start.trial.error.no.response', 'Unable to connect to the server. Please check your internet connection, Code Sight');
        const proxyMessage = localize('registration.proxy.settings', "proxy settings");
        const noConnectionErrorMessage2 = localize('registration.start.trial.error.no.response.one', 'and try again.');
        const contactSupportMessage = localize('registration.contact.support', 'Contact support');
        const noConnectionErrorMessage3 = localize('registration.start.trial.error.no.response.two', 'if the problem persists.');
        const defaultErrorMessage = localize('registration.start.trial.error.default', 'Unexpected error occurred during the registration process. Please contact support if the problem persists.');
        try {
            let response = await licenseService.registerTrial(trialRequest);
            let registrationError = response.getError();
            logger.info(`Registration response ${response.getMessage()}`);
            if (response.getSuccess()) {
                // registration was successful
                this.view.postMessageToWebview({ 
                    command: RegistrationViewCommandIds.SET_STATUS,
                    type: RegistrationViewCommandIds.STATUS_VALID,
                    message: localize('registration.start.trial.valid', 'Registration successful')
                });

                await getService(SetupService.id).notifyRegistrationListeners();

                // begin standard edition flow
                if (this.isInstalledTools) {
                    await getService(SetupService.id).beginEnableStandardEditionFlow();
                } else {
                    await getService(SetupService.id).beginStandardEditionFlow();
                }
            } else {
                logger.error(`Registration error occurred - status code: ${registrationError?.getStatuscode()} message: ${registrationError?.getMessage()}`); 
                this.view.postMessageToWebview({ 
                    command: RegistrationViewCommandIds.SET_STATUS,
                    type: RegistrationViewCommandIds.STATUS_INVALID,
                    message: registrationError?.getMessage() ?? defaultErrorMessage
                });
                // enable start trial button
                this.view.postMessageToWebview({
                    command: RegistrationViewCommandIds.SET_CONTINUE_ENABLED,
                    enabled: "true",
                });
            }
        } catch (error) {
            this.view.postMessageToWebview({ 
                command: RegistrationViewCommandIds.SET_STATUS,
                type: RegistrationViewCommandIds.STATUS_INVALID,
                // TODO: Replace this and related code (UD-9294) with error message from controller UD-9032
                message: `
                <p>${noConnectionErrorMessage} 
                    <a id="${RegistrationViewCommandIds.VIEW_PROXY_SETTINGS}" href="#" title="${proxyMessage}">${proxyMessage}</a> 
                    ${noConnectionErrorMessage2} 
                    <a id="contactsupportlink" href=${SUPPORT_ADDRESS}>${contactSupportMessage}</a> 
                    ${noConnectionErrorMessage3}
                </p>
                `
            });
            // enable start trial button
            this.view.postMessageToWebview({
                command: RegistrationViewCommandIds.SET_CONTINUE_ENABLED,
                enabled: "true",
            });
            logger.error(`An unexpected error occurred while submitting registration information - err: ${error}`); 
        }
    }
}
