import { CaptureConfiguration } from "@codesight/codesight-controller-proto/controller_proto/v0/capture_configuration_pb";
import { normalizeDriveLetter } from '../utils/fileUtils';
import { getService, ServiceId } from "./serviceContainer";
import { WorkspaceService } from "./workspaceService";

/**
 * Service for managing creating the capture configuration object for known workspaces.
 */
export abstract class CaptureProviderService {
    static readonly id: ServiceId<CaptureProviderService> = { id: CaptureProviderService.name };

    abstract buildCaptureConfiguration(): CaptureConfiguration;

    abstract markAsStale(): void;
}

export class CaptureProviderServiceImpl extends CaptureProviderService {
    private isCaptureConfigurationStale: boolean;
    private fileSystemCaptureConfigurations: CaptureConfiguration.FileSystemCaptureConfiguration[];

    constructor() {
        super();
        this.isCaptureConfigurationStale = true;
        this.fileSystemCaptureConfigurations = [];
    }

    markAsStale(): void {
        this.isCaptureConfigurationStale = true;
    }

    buildCaptureConfiguration(): CaptureConfiguration {
        let captureConfig = new CaptureConfiguration();

        // Build up different configuration types as needed
        captureConfig.setFilesystemcaptureconfigurationsList(this.getFileSystemCaptureConfigurations());

        return captureConfig;
    }

    private getFileSystemCaptureConfigurations(): CaptureConfiguration.FileSystemCaptureConfiguration[] {
        if (this.isCaptureConfigurationStale) {
            this.isCaptureConfigurationStale = false;
            this.fileSystemCaptureConfigurations = [];

            getService(WorkspaceService.id).getWorkspaceFolders().forEach(folder => {
                let fileSystemCaptureConfig = new CaptureConfiguration.FileSystemCaptureConfiguration();
                let path = normalizeDriveLetter(folder.uri.fsPath);
                fileSystemCaptureConfig.setProjectlocation(path);
                fileSystemCaptureConfig.addSearchdirectories(path);

                this.fileSystemCaptureConfigurations.push(fileSystemCaptureConfig);
            });

        }
        return this.fileSystemCaptureConfigurations;
    }
}
