import { platform } from 'os';
import * as path from 'path';
import { ENV_APP_DATA, ENV_CODESIGHT_DESKTOP_GRPC_MSG_LIMIT, ENV_HOME, FILE_NAME_CODE_SIGHT_CONF, FOLDER_NAME_BLACKDUCK_UNIX, FOLDER_NAME_BLACKDUCK_WINDOWS, FOLDER_NAME_DESKTOP } from './constants';
export function getDefaultBlackDuckHomePath(): string {
    let homePath: string = "";

    if (isWindows()) {
        let home = getFirstResolvedEnv(ENV_APP_DATA, ENV_HOME);
        if (home) {
            homePath = path.join(home, FOLDER_NAME_BLACKDUCK_WINDOWS);
        }
    } else {
        let home = getEnvVar(ENV_HOME);
        if (home) {
            homePath = path.join(home, FOLDER_NAME_BLACKDUCK_UNIX);
        }
    }

    return homePath;
}

export function getExtensionLogPath(rootDirPath: string): string {
    return path.join(rootDirPath, FOLDER_NAME_DESKTOP, "extension", "logs");
}

export function getExtensionConfigFilePath(): string {
    let blackduckHome = getDefaultBlackDuckHomePath();
    return path.join(blackduckHome, FILE_NAME_CODE_SIGHT_CONF);
}

export function isWindows(): boolean {
    return platform().startsWith("win");
}

export function isOSX(): boolean {
    return platform().startsWith("darwin");
}

export function isArm64OSX(): boolean {
    return isOSX() && process.arch === "arm64";
}

export function getEnvVar(envVar: string, defaultValue?: string): string | undefined {
    let val = process.env[envVar];
    if (defaultValue && !val) {
        return defaultValue;
    }
    return val;
}

export function isFeatureFlagEnabled(envVar: string): boolean {
    const featureFlag = getEnvVar(envVar);
    if (featureFlag === undefined || featureFlag === "0" || featureFlag.toLowerCase() === "false") {
        return false;
    }
    return true;
}



export function getGrpcLimit(): number {
    const flagValue = getEnvVar(ENV_CODESIGHT_DESKTOP_GRPC_MSG_LIMIT, "250");
    let grpcLimit;
    
    const DEFAULT = 250;
    const MIN = 4;
    const MAX = 1000;
    const MULTIPLIER = 1024;

    if(flagValue !== undefined){
        grpcLimit = parseInt(flagValue);
    }
    
    if(grpcLimit === undefined || isNaN(grpcLimit)){
        grpcLimit = DEFAULT;
    }

    if(grpcLimit < MIN){
        grpcLimit = MIN;
    }
    
    if(grpcLimit > MAX){
        grpcLimit = MAX;
    }

    return grpcLimit * MULTIPLIER * MULTIPLIER;
}

export function getFirstResolvedEnv(...names: string[]): string | undefined {
    for (let name of names) {
        if (name) {
            let value = getEnvVar(name);
            if (value) {
                return value;
            }
        }
    }

    return undefined;
}

/**
 * Gets the command to open a folder based on the OS as they are different
 * (see https://github.com/Microsoft/vscode/issues/5437)
 */
export function getOpenFolderCommand(): string {
    if (isOSX()) {
        return "workbench.action.files.openFileFolder";
    } else {
        return "workbench.action.files.openFolder";
    }
}