export type SimpleCommandTooltip = {
    command: string;
    tooltip: string;
};

export type LocalAndTeamViewResultsState = {
    hasLocalViewResults: boolean,
    hasTeamViewResults: boolean
};

export const COMMAND_LOAD_MARKER_DETAILS_ID = "codesight.load.marker.details";

export enum MarkerView {
    Local = "Local",
    Team = "Team"
}

export abstract class MarkerService {
    
    static readonly id: ServiceId<MarkerService> = { id: MarkerService.name };

    /**
     * Set the current marker view (Local or Team) and update context
     */
    abstract setMarkerView(view: MarkerView, isUserSelected: boolean): Promise<void>;

    /**
     * Get the current marker view state
     */
    abstract getCurrentMarkerView(): MarkerView;

    /**
     * Load markers for the currently active file based on the current view
     */
    abstract loadMarkersForActiveFile(editor?: TextEditor): Promise<void>;

    /**
     * Get markers from the currently active view
     */
    abstract getActiveMarkers(): Promise<NewIssue[]>;

    /**
     * Update the status bar display for marker information
     */
    abstract updateMarkerStatusDisplay(loading: boolean, count?: number, isNonFileEditor?: boolean): Promise<void>;

    /**
     * Initialize marker service - setup event listeners and register commands
     * @returns Array of Disposables for the extension context to manage
     */
    abstract init(): Promise<Disposable[]>;

    /**
     * Load marker details for a specific issue based on the current view
     */
    abstract loadMarkerDetails(issueId: string): Promise<void>;

    abstract getMarkerToggleCommand(totalMarkersCount?: number, isNonFileEditor?: boolean, isMarkersSupported?: boolean): SimpleCommandTooltip;

    abstract getIsEditorMarkersEnabled(): boolean;
}

export class MarkerServiceImpl implements MarkerService, ScanConfigurationServiceListener, ScanStatusCoordinatorListener, LocalViewIssueListFilterServiceListener, TeamViewIssueListFilterServiceListener, TeamViewIssueListFilterServiceListener, AuthenticationServiceListener, EntitlementServiceListener, ScanResultTypeSelectionListener, IssueSourceConfigServiceListener {
    private currentMarkerView: MarkerView = MarkerView.Local;
    private activeFilePath: string | undefined;
    private lastActiveFilePath: string | undefined;
    private currentLoadOperation?: CancellationTokenSource;
    isEditorMarkersEnabled: boolean = DEFAULT_EDITOR_MARKERS_ENABLEMENT_STATE;
    configurationChangedListener: Disposable | undefined;

    constructor() {
        if (isFeatureFlagEnabled(ENV_CODESIGHT_EDITOR_MARKERS)) {
            const storedView = getService(VscodeContextService.id).getPreservedMarkerView();
            const isUserSelected = storedView !== undefined;
            this.currentMarkerView = storedView || MarkerView.Local;
            // eslint-disable-next-line @typescript-eslint/no-floating-promises
            this.setMarkerView(this.currentMarkerView, isUserSelected);
        }

    }

    async init(): Promise<Disposable[]> {
        if (!isFeatureFlagEnabled(ENV_CODESIGHT_EDITOR_MARKERS) ) {
            return [];
        }

        const disposables: Disposable[] = [];

        getService(ScanConfigurationService.id).addListener(this);
        getService(ScanStatusCoordinator.id).addListener(this);
        getService(LocalViewIssueListFilterService.id).addListener(this);
        getService(TeamViewIssueListFilterService.id).addListener(this);
        getService(AuthenticationService.id).addListener(this);
        getService(EntitlementService.id).addListener(this);
        getService(LocalViewIssuesListService.id).addScanResultTypeListener(this);
        getService(IssueSourceConfigService.id).addListener(this);

        this.configurationChangedListener = workspace.onDidChangeConfiguration((changeEvent: ConfigurationChangeEvent) => {
            if (changeEvent.affectsConfiguration(CODESIGHT_EDITOR_MARKERS_CONFIGURATION_KEY)) {
                getLogger().info("Code Sight marker enablement configuration changed. Updating...");
                return this.loadMarkersForActiveFile();
            }
            return Promise.resolve();
        });
        
        disposables.push({
            dispose: () => {
                getService(ScanConfigurationService.id).removeListener(this);
                getService(ScanStatusCoordinator.id).removeListener(this);
                getService(LocalViewIssueListFilterService.id).removeListener(this);
                getService(TeamViewIssueListFilterService.id).removeListener(this);
                getService(AuthenticationService.id).removeListener(this);
                getService(EntitlementService.id).removeListener(this);
                getService(LocalViewIssuesListService.id).removeScanResultTypeListener(this);
                getService(IssueSourceConfigService.id).removeListener(this);
                if (this.configurationChangedListener) { this.configurationChangedListener.dispose(); }
            }
        });

        disposables.push(window.onDidChangeActiveTextEditor(this.debouncedHandleActiveEditorChange));
        disposables.push(window.onDidChangeVisibleTextEditors(this.handleVisibleEditorChange));

        disposables.push(workspace.onDidChangeTextDocument(debounce(async (event) => {
            const activeEditor = window.activeTextEditor;
            if (activeEditor && activeEditor.document === event.document && !activeEditor.document.isDirty) {
                try {
                    const context = getService(LocalScanModeContextService.id).getCurrentContext();
                    if (context.isAutoContext()) {
                        await this.loadMarkersForActiveFile();
                    }
                } catch (error) {
                    getLogger().error('Failed to reload markers after external file change', error);
                }
            }
        }, 500)));

        const showLocalViewMarkers = async () => {
            await getService(IssueSelectionService.id).clearSelection(IssuesListIdentifier.TeamViewIssuesList);
            await this.setMarkerView(MarkerView.Local, true);
        };

        const showTeamViewMarkers = async () => {
            await getService(IssueSelectionService.id).clearSelection(IssuesListIdentifier.LocalViewIssuesList);
            if (getService(LocalScanModeContextService.id).getCurrentContext().isAutoContext()) {
                await getService(ViewProviderService.id).getOrCreateLocalViewPresenter().restorePreviousFullState();
            }

            await this.setMarkerView(MarkerView.Team, true);
        };

        disposables.push(commands.registerCommand(COMMAND_SHOW_LOCAL_VIEW_MARKERS, showLocalViewMarkers));
        disposables.push(commands.registerCommand(COMMAND_SHOW_TEAM_VIEW_MARKERS, showTeamViewMarkers));
        disposables.push(commands.registerCommand(CODESIGHT_NOOP, function() {}));

        disposables.push(commands.registerCommand(COMMAND_LOAD_MARKER_DETAILS_ID, async (args: any[]) => {
            const issueId = Array.isArray(args) ? args[0] : args;
            if (!issueId || typeof issueId !== 'string') {
                getLogger().warn('Invalid issueId argument provided to COMMAND_LOAD_MARKER_DETAILS_ID', args);
                return;
            }
            await this.loadMarkerDetails(issueId);
        }));

        setTimeout(async () => {
            try {
                // Determine the marker view based on actual results state
                await this.determineAndSetCorrectMarkerView(true);
                const activeEditor = window.activeTextEditor;
                if (activeEditor && !isNonFileEditor(activeEditor)) {
                    if (this.currentMarkerView === MarkerView.Team) {
                        await getService(IssueSourceConfigService.id).refreshConfiguredSourceList();
                    }
                    void this.loadMarkersForActiveFile();
                }
            } catch (error) {
                getLogger().debug('Failed to load initial markers on startup', error);
            }
        }, 100);

        return disposables;
    }

    getIsEditorMarkersEnabled(): boolean {
        return this.isEditorMarkersEnabled;
    }

    getLocalAndTeamViewResultsState(): LocalAndTeamViewResultsState {
        let hasLocalViewResults = false;
        let hasTeamViewResults = getService(IssueSourceConfigService.id).getSelectedSource() !== undefined;

        // Use ScanContext to determine if we have results to show
        const scanContext = getService(LocalScanModeContextService.id).getCurrentContext();

        if (scanContext.isAutoContext()) {
            // Incremental mode (Signal or Classic): Check if scan context has any scan types configured
            const configSources = scanContext.createConfigSources();
            hasLocalViewResults = this.isEditorMarkersEnabled && configSources.length > 0;
        } else {
            // Project mode: Check if a scan config is selected
            hasLocalViewResults = this.isEditorMarkersEnabled && getService(ScanConfigurationService.id).getSelectedScanConfig() !== undefined;
        }
        return { hasLocalViewResults, hasTeamViewResults };
    }

    async setMarkerView(view: MarkerView, isUserSelected: boolean): Promise<void> {
        this.currentMarkerView = view;
        
        if (isUserSelected) {
            getService(VscodeContextService.id).preserveMarkerView(view);
        }
        
        // Update all context variables
        await this.setContextVariablesForMarkerView();
        await this.loadMarkersForActiveFile();
    }

    getCurrentMarkerView(): MarkerView {
        return this.currentMarkerView;
    }

    /**
     * Determines and sets the correct marker view based on current results state.
     * This is called after services are properly initialized to get accurate state.
     */
    async determineAndSetCorrectMarkerView(startup?: boolean): Promise<void> {
        const storedView = getService(VscodeContextService.id).getPreservedMarkerView();
        const isUserSelected = storedView !== undefined;

        // If user has manually selected a view, keep using that
        if (isUserSelected) {
            await this.setContextVariablesForMarkerView();
            return;
        }

        // Ensure Team View sources are refreshed to get accurate selected source state
        await getService(IssueSourceConfigService.id).refreshConfiguredSourceList();

        const { hasLocalViewResults, hasTeamViewResults } = this.getLocalAndTeamViewResultsState();

        // Determine correct marker view based on requirements:
        // 1. Local View has priority when available
        // 2. Show Team View only if Local View has no results
        let targetView: MarkerView;
        if (hasLocalViewResults) {
            targetView = MarkerView.Local;
        } else if (hasTeamViewResults) {
            targetView = MarkerView.Team;
        } else {
            targetView = MarkerView.Local;
        }

        if (startup || targetView !== this.currentMarkerView) {
            await this.setMarkerView(targetView, false);
        }
    }

    private async setContextVariablesForMarkerView(): Promise<void> {
        const { hasLocalViewResults, hasTeamViewResults } = this.getLocalAndTeamViewResultsState();
        await commands.executeCommand("setContext", "codesight.localViewMarkers", this.currentMarkerView === MarkerView.Local);
        await commands.executeCommand("setContext", "codesight.hasLocalViewResults", hasLocalViewResults);
        await commands.executeCommand("setContext", "codesight.hasTeamViewResults", hasTeamViewResults);
    }

    private debouncedHandleActiveEditorChange = debounce(async (editor: TextEditor | undefined) => {
        try {
            if (!this.isEditorMarkersEnabled) {
                return;
            }
            if (!editor) {
                this.lastActiveFilePath = undefined;
                await this.clearMarkersForActiveFile(editor);
                return;
            }
            
            if (!this.shouldReloadMarkers(editor)) {
                return;
            }
            await this.loadMarkersForActiveFile();
        } catch (error) {
            getLogger().error('Failed to load markers for active editor', error);
        }
    }, 300);

    private handleVisibleEditorChange = async (editors: readonly TextEditor[]) => {
        const matchingEditors = editors.filter(editor => normalizeDriveLetter(editor.document.uri.fsPath) === this.lastActiveFilePath);
        if (matchingEditors.length === 0) {
            this.lastActiveFilePath = undefined;
            
            const fileEditors = editors.filter(editor => !isNonFileEditor(editor));
            if (fileEditors.length === 0) {
               await this.updateMarkerStatusDisplay(false, undefined, true);
            }
            return;
        }
    };

    /**
     * Determines if markers should be reloaded based on editor changes
     * Prevents redundant reloads when switching between same file or non-file editors
     */
    private shouldReloadMarkers(editor: TextEditor | undefined): boolean {
        const result = shouldReloadForEditorChange(editor, this.lastActiveFilePath);
        this.lastActiveFilePath = result.newFilePath;
        return result.shouldReload;
    }


    /**
     * Common method to reload markers if conditions are met
     * @param errorContext Context string for error logging
     * @param applicableViews Array of marker views that should trigger reload (defaults to all views)
     */
    private async reloadMarkersIfNeeded(errorContext: string, applicableViews?: MarkerView[]): Promise<void> {
        const activeEditor = window.activeTextEditor;

        // Update marker view based on current results state if not user-selected
        await this.determineAndSetCorrectMarkerView();
        
        // If no active editor, check if any visible editor matches the lastActiveFilePath
        if (!activeEditor) {
            if (this.lastActiveFilePath) {
                const visibleEditors = window.visibleTextEditors;
                const matchingEditor = visibleEditors.find(editor => 
                    !isNonFileEditor(editor) && 
                    normalizeDriveLetter(editor.document.uri.fsPath) === this.lastActiveFilePath
                );
                
                if (matchingEditor) {
                    const shouldReload = !applicableViews || applicableViews.length === 0 || applicableViews.includes(this.currentMarkerView);
                    if (shouldReload) {
                        try {
                            await this.loadMarkersForActiveFile(matchingEditor);
                        } catch (error) {
                            getLogger().warn(`Failed to reload markers after ${errorContext}`, error);
                        }
                    }
                }
            }
            return;
        }

        if (isNonFileEditor(activeEditor)) {
            return;
        }

        const shouldReload = !applicableViews || applicableViews.length === 0 || applicableViews.includes(this.currentMarkerView);
        if (!shouldReload) {
            return;
        }

        try {
            await this.loadMarkersForActiveFile(activeEditor);
        } catch (error) {
            getLogger().warn(`Failed to reload markers after ${errorContext}`, error);
        }
    }

    async onFiltersChanged(): Promise<void> {
        // When filters change, visible issues change, so markers should refresh
        void this.reloadMarkersIfNeeded('filter change');
    }

    async onAuthenticated(serverType: ServerType): Promise<void> {
        // When authentication completes, new issue data may be available
        void this.reloadMarkersIfNeeded('authentication');
    }

    async onScanModeChanged(scanMode: ScanMode): Promise<void> {
        // When scan mode changes (AUTO <-> MANUAL), different issue data will be shown
        void this.reloadMarkersIfNeeded('scan mode change', [MarkerView.Local]);
    }

    async onScanFileScopeChanged(): Promise<void> {
        void this.reloadMarkersIfNeeded('file scope change', [MarkerView.Local]);
    }

    async onSelectedReferenceBranchChanged(): Promise<void> {
        void this.reloadMarkersIfNeeded('selected reference branch changed', [MarkerView.Local]);
    }

    async onEntitlementsChanged(entitlementsChanged: EntitlementsChanged): Promise<void> {
        // When entitlements change, new scan types may become available
        void this.reloadMarkersIfNeeded('entitlement change');
    }

    async onSelectedSourceChanged(): Promise<void> {
        // When issue source changes (Team View), different server data is shown
        await getService(TeamViewIssueListFilterService.id).refreshCachedFilters();
        void this.reloadMarkersIfNeeded('source change', [MarkerView.Team]);
    }

    async onResultTypeChanged(): Promise<void> {
        // When scan result type changes, different issue data will be shown
        void this.reloadMarkersIfNeeded('scan result type change', [MarkerView.Local]);
    }

    async onScanResultReceived(notificationStatus: RefreshStatus): Promise<void> {
        void this.reloadMarkersIfNeeded('scan result received', [MarkerView.Local]);
    }

    async onIssueSourceListUpdated(): Promise<void> {
        // no-op
    }

    async onSelectedScanConfigChanged(): Promise<void> {
        // no-op
    }

    getMarkerToggleCommand(totalMarkersCount?: number, isNonFileEditor?: boolean, isMarkersSupported?: boolean): SimpleCommandTooltip {
        const { hasLocalViewResults, hasTeamViewResults } = this.getLocalAndTeamViewResultsState();
        let fileName = this.activeFilePath;
        totalMarkersCount = totalMarkersCount || 0;
        isNonFileEditor = isNonFileEditor || false;
        let markerTooltip = "";
        const separator = "\n\n---\n";
        if (fileName && isMarkersSupported) {
            markerTooltip = localize("statusbar.codesight.markers.in.file.tooltip", "{0} issues found in `{1}`", totalMarkersCount, fileName);
        }
        // add checks here for manual/auto local view and team view scan type/source
        if (!isNonFileEditor) {
            if (this.currentMarkerView === MarkerView.Local && hasTeamViewResults) {
                const toggleTeamViewText = localize("statusbar.codesight.show.team.view.markers.tooltip", "Click to see Team View issues")
                markerTooltip += markerTooltip.length > 0 ? `${separator}${toggleTeamViewText}` : `${toggleTeamViewText}`;
                return { command: COMMAND_SHOW_TEAM_VIEW_MARKERS, tooltip: markerTooltip };
            } else if (this.currentMarkerView === MarkerView.Team && hasLocalViewResults) {
                const toggleLocalViewText = localize("statusbar.codesight.show.local.view.markers.tooltip", "Click to see Local View issues")
                markerTooltip += markerTooltip.length > 0 ? `${separator}${toggleLocalViewText}` : `${toggleLocalViewText}`;
                return { command: COMMAND_SHOW_LOCAL_VIEW_MARKERS, tooltip: markerTooltip };
            } else {
                return { command: CODESIGHT_NOOP, tooltip: markerTooltip };
            }
        } else {
            return { command: CODESIGHT_NOOP, tooltip: "" };
        }
    }

    async clearMarkersForActiveFile(editor?: TextEditor): Promise<void> {
        const isNonFileEditor = !(editor || window.activeTextEditor);
            await this.clearActiveMarkers();
            await Promise.all([
                getService(EditorDecorationService.id).clearEditorMarkerDecorations(),
                getService(MarkerService.id).updateMarkerStatusDisplay(false, undefined, isNonFileEditor),
            ]);
    }

    async loadMarkersForActiveFile(editor?: TextEditor): Promise<void> {
        const { enablement } = workspace.getConfiguration(CODESIGHT_EDITOR_MARKERS_CONFIGURATION_KEY);
        this.isEditorMarkersEnabled = enablement;
        await vscode.commands.executeCommand("setContext", "codesight.isEditorMarkersEnabledFromSettings", this.isEditorMarkersEnabled);
        if (!this.isEditorMarkersEnabled) {
            await this.clearMarkersForActiveFile(editor);
            getService(ProgressNotificationService.id).hideMarkerStatus();
            return;
        }

        const activeEditor = editor || window.activeTextEditor;
        this.activeFilePath = activeEditor?.document.fileName ? path.basename(activeEditor.document.fileName) : "";

        this.currentLoadOperation?.cancel();
        this.currentLoadOperation = new CancellationTokenSource();
        const token = this.currentLoadOperation.token;

        try {
            if (token.isCancellationRequested) {
                return;
            }

            if (this.currentMarkerView === MarkerView.Local) {
                await this.clearMarkersForActiveFile(editor);
                const context = getService(LocalScanModeContextService.id).getCurrentContext();
                if (context.isAutoContext()) {
                    if (getService(ScanStatusCoordinator.id).isCurrentScanFilesScopeChangedFiles()) {
                        const isRunning = context.contextType === LocalScanModeContextType.SIGNAL_MANUAL
                            ? await getService(ScanService.id).isLocalViewSignalScanRunning()
                            : await getService(ScanService.id).isLocalViewAutoChangedFileScanRunning();
                        if (!isRunning) {
                            const { selectedScanInfo } = await getService(LocalViewIssuesListService.id).getAvailableScanInfos();
                            const scanInfoStatus = getScanStatus(selectedScanInfo);
                            if (scanInfoStatus === RefreshStatus.Status.SUCCESS) {
                                await getService(LocalViewIssuesListService.id).refreshMarkers(editor);
                            }
                        }
                    } else {
                        const isRunning = context.contextType === LocalScanModeContextType.SIGNAL_MANUAL
                            ? await getService(ScanService.id).isLocalViewSignalScanRunning()
                            : getService(ScanService.id).isLocalViewAutoLicenseScanRunning() || getService(ScanService.id).isLocalViewAutoRapidScanRunning();
                        if (!isRunning) {
                            await getService(LocalViewIssuesListService.id).refreshMarkers(editor);
                        }
                    }
                } else {
                    const { selectedScanInfo } = await getService(LocalViewIssuesListService.id).getAvailableScanInfos();
                    const scanInfoStatus = getScanStatus(selectedScanInfo);
                    if (scanInfoStatus === RefreshStatus.Status.SUCCESS) {
                        await getService(LocalViewIssuesListService.id).refreshMarkers(editor);
                    }
                }
            } else {
                await getService(TeamViewIssuesListService.id).refreshMarkers(editor);
            }

            if (!token.isCancellationRequested) {
                getLogger().debug(`Markers loaded successfully for ${this.currentMarkerView} view`);
            }
        } catch (error) {
            if (!token.isCancellationRequested) {
                getLogger().error(`Failed to load markers for ${this.currentMarkerView} view`, error);
                return;
            }
        } finally {
            if (this.currentLoadOperation?.token === token) {
                this.currentLoadOperation = undefined;
            }
        }
    }

    async getActiveMarkers(): Promise<NewIssue[]> {
        if (!this.isEditorMarkersEnabled) {
            return [];
        }
        if (this.currentMarkerView === MarkerView.Local) {
            return getService(LocalViewIssuesListService.id).getMarkers();
        } else {
            return getService(TeamViewIssuesListService.id).getMarkers();
        }
    }

    async updateMarkerStatusDisplay(loading: boolean, count?: number, isNonFileEditor?: boolean): Promise<void> {
        await getService(ProgressNotificationService.id).updateMarkerStatus(loading, count, isNonFileEditor, this.isEditorMarkersEnabled);
    }

    async clearActiveMarkers(): Promise<void> {
        if (this.currentMarkerView === MarkerView.Local) {
            await getService(LocalViewIssuesListService.id).clearMarkersList();
        } else {
            await getService(TeamViewIssuesListService.id).clearMarkersList();
        }
    }

    async loadMarkerDetails(issueId: string): Promise<void> {
        if (!issueId || typeof issueId !== 'string' || issueId.trim().length === 0) {
            getLogger().warn('Invalid issueId provided to loadMarkerDetails');
            return;
        }

        const viewProviderService = getService(ViewProviderService.id);
        
        const currentDetailsSelection = Date.now();

        if (this.currentMarkerView === MarkerView.Local) {
            const issueService = getService(LocalViewIssuesListService.id);
            const displayType = await getService(LocalViewIssuesListService.id).getDisplayTypeForIssueDetails(DisplayType.MARKER)
            let issue = await issueService.getIssue(issueId, displayType);

            if (!issue) {
                // if displayType is set to LICENSE and no issue is returned, try fetching as MARKER (for Auto-Sigma scans)
                issue = await issueService.getIssue(issueId, DisplayType.MARKER);
           }

            if (issue) {
                const presenter = viewProviderService.getOrCreateLocalViewPresenter();
                await this.loadMarkerDetailsForPresenter(
                    presenter,
                    issueService,
                    issue,
                    IssuesListIdentifier.LocalViewIssuesList,
                    currentDetailsSelection,
                    true,
                    true
                );
            }
        } else {
            const issueService = getService(TeamViewIssuesListService.id);
            const issue = await issueService.getIssue(issueId, DisplayType.MARKER);

            if (issue) {
                const presenter = viewProviderService.getOrCreateTeamViewPresenter();
                await this.loadMarkerDetailsForPresenter(
                    presenter,
                    issueService,
                    issue,
                    IssuesListIdentifier.TeamViewIssuesList,
                    currentDetailsSelection,
                    true
                );
            }
        }
    }

    private async findAndRevealOccurrence(
        presenter: MarkerEventDetailsCapable,
        issue: NewIssue,
        issuesListIdentifier: IssuesListIdentifier
    ): Promise<void> {
        let detailToReveal = getService(IssueSelectionService.id).getSelectedOccurrence(issue);
        let detailIndex = detailToReveal?.getContributingDetailIndex() ?? 0;
        
        issue.getEventInfo()?.getContributingDetails()?.forEach((detail) => {
            if (this.lastActiveFilePath === detail.getFilePath() && detail.getLineNumber() === issue.getOriginalLineNumber()) {
                detailToReveal = detail;
                detailIndex = detail.getContributingDetailIndex();
            }
        });
        
        await getService(IssueSelectionService.id).selectNewOccurrence(
            issue.getIssueId(),
            detailIndex,
            issuesListIdentifier,
            issue.getDisplayType()
        );
        
        let multipleOccurrences = (issue.getEventInfo()?.getContributingDetails()?.length ?? 0) > 1;
        if (detailToReveal && multipleOccurrences) {
            await presenter.revealTreeForOccurrence(issue, detailToReveal);
        }
    }

    private async loadMarkerDetailsForPresenter(
        presenter: MarkerEventDetailsCapable,
        issueService: LocalViewIssuesListService | TeamViewIssuesListService,
        issue: NewIssue,
        issuesListIdentifier: IssuesListIdentifier,
        currentDetailsSelection: number,
        shouldShowIssueCount: boolean,
        shouldShowLicenseIssueCount?: boolean
    ): Promise<void> {
        presenter.setLatestDetailsSelection(currentDetailsSelection);

        await presenter.showIssueDetailsLoading();
        if (this.currentMarkerView === MarkerView.Team && getService(LocalScanModeContextService.id).getCurrentContext().isAutoContext()) {
            await getService(ViewProviderService.id).getOrCreateLocalViewPresenter().restorePreviousFullState();
        }
        await presenter.reloadTreeProviderSimple(issue);
        presenter.updateViewTitle(shouldShowIssueCount, shouldShowLicenseIssueCount);
        await presenter.revealTreeForIssue(issue);
        
        getLogger().debug(`Loading EventInfo for marker issue ${issue.getIssueId()}`);
        await issueService.loadDetailsAndEventsForIssue(issue);
        
        if (presenter.getLatestDetailsSelection() === currentDetailsSelection) {
            await this.findAndRevealOccurrence(
                presenter,
                issue,
                issuesListIdentifier
            );
        } else {
            getLogger().debug(`Skipping tree state correction for issue ${issue.getIssueId()} - request superseded`);
        }
    }

}