import * as vscode from 'vscode';
import { getLogger } from '../utils/logger';
import {
    BASE_PROMPT,
    BLACK_DUCK_SCA_CONFIGURATION_PROMPT,
    CODESIGHT_GETTING_STARTED_PROMPT,
    COVERITY_REMOTE_ISSUES_PROMPT,
    COVERITY_SCAN_CONFIGURATION_PROMPT,
    POLARIS_REMOTE_ISSUES_PROMPT,
    POLARIS_SCAN_CONFIGURATION_PROMPT,
    SIGMA_SCAN_CONFIGURATION_PROMPT
} from './chatPrompts';

/**
 * Get the appropriate prompt based on the command
 */
export function getPromptForCommand(command: string | undefined): string {
    switch (command) {
        case "code-sight-getting-started":
            return CODESIGHT_GETTING_STARTED_PROMPT;
        case "code-sight-configure-coverity-scan":
            return COVERITY_SCAN_CONFIGURATION_PROMPT;
        case "code-sight-configure-polaris-scan":
            return POLARIS_SCAN_CONFIGURATION_PROMPT;
        case "code-sight-configure-rapid-scan-static-scan":
            return SIGMA_SCAN_CONFIGURATION_PROMPT;
        case "code-sight-configure-black-duck-sca-scan":
            return BLACK_DUCK_SCA_CONFIGURATION_PROMPT;
        case "code-sight-view-polaris-server-issues":
            return POLARIS_REMOTE_ISSUES_PROMPT;
        case "code-sight-view-coverity-server-issues":
            return COVERITY_REMOTE_ISSUES_PROMPT;
        default:
            return BASE_PROMPT;
    }
}

/**
 * Build the query string from the request
 */
export function buildQuery(request: vscode.ChatRequest): string {
    return request.prompt ? request.prompt : (request.command ? request.command : "");
}

/**
 * Build chat messages including system prompt, history, and current query
 */
export function buildChatMessages(prompt: string, chatContext: vscode.ChatContext, query: string): vscode.LanguageModelChatMessage[] {
    const messages: vscode.LanguageModelChatMessage[] = [];
    
    // Add system prompt as the first message
    messages.push(vscode.LanguageModelChatMessage.User(prompt));
    
    // Add conversation history (limit to last 10 exchanges to manage token usage)
    const recentHistory = chatContext.history.slice(-20); // Last 20 turns (10 exchanges)
    for (const historyItem of recentHistory) {
        try {
            if (historyItem instanceof vscode.ChatRequestTurn) {
                // Add user messages from history
                const userQuery = historyItem.prompt;
                if (userQuery.trim()) {
                    messages.push(vscode.LanguageModelChatMessage.User(userQuery));
                }
            } else if (historyItem instanceof vscode.ChatResponseTurn) {
                // Add assistant responses from history
                let assistantResponse = "";
                historyItem.response.forEach((responsePart: any) => {
                    if (responsePart instanceof vscode.ChatResponseMarkdownPart) {
                        assistantResponse += responsePart.value.value;
                    }
                });
                if (assistantResponse.trim()) {
                    messages.push(vscode.LanguageModelChatMessage.Assistant(assistantResponse));
                }
            }
        } catch (historyError) {
            // Skip problematic history items rather than failing the entire request
            getLogger().warn(`Error processing chat history item: ${historyError}`);
        }
    }
    
    // Add current user query
    if (query.trim()) {
        messages.push(vscode.LanguageModelChatMessage.User(query));
    }

    return messages;
}

/**
 * Create and return the chat request handler
 */
export function createChatRequestHandler(): vscode.ChatRequestHandler {
    return async (request: vscode.ChatRequest, chatContext: vscode.ChatContext, stream: vscode.ChatResponseStream, token: vscode.CancellationToken) => {
        // Set up the prompt based on the command
        const prompt = getPromptForCommand(request.command);
        const query = buildQuery(request);
        
        // Select language model to use for the chat and send it the prompt
        const chatModels = await vscode.lm.selectChatModels({ vendor: 'copilot'});
        if (chatModels.length === 0) {
            stream.markdown('No compatible language models are available. Please enable a language model extension to use this feature.');
            return;
        }

        try {
            // Build messages in correct order: system prompt, then conversation history, then current query
            const messages = buildChatMessages(prompt, chatContext, query);

            // Send request and stream response
            const chatResponse = await chatModels[0].sendRequest(messages, {}, token);
            for await (const responseToken of chatResponse.text) {
                stream.markdown(responseToken);
            }
        } catch (error) {
            getLogger().error(`Chat participant error: ${error}`);
            stream.markdown(`Sorry, Black Duck Assist encountered an error while processing your request: ${error instanceof Error ? error.message : 'Unknown error'}`);
        }
    };
}

/**
 * Initialize and register the chat participant
 */
export function initializeChatParticipant(context: vscode.ExtensionContext): vscode.ChatParticipant {
    const handler = createChatRequestHandler();
    
    // Register the chat participant and its request handler
    const chatParticipant = vscode.chat.createChatParticipant('codesight-scan-helper.codesight', handler);
    
    // Set icon path for @codesight
    chatParticipant.iconPath = vscode.Uri.joinPath(context.extensionUri, 'resources/icons/extension-logo.png');
    
    return chatParticipant;
}

