import { MonitorResultsNotification, RefreshResultsRequest, RefreshStatus } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_service_pb";
import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { Command, MarkdownString, StatusBarAlignment, StatusBarItem, ThemeColor, window } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { COMMAND_OPEN_CUSTOM_WORKING_DIR, COMMAND_OPEN_ONBOARDING, ENV_CODESIGHT_EDITOR_MARKERS, TEAM_VIEW_SERVER_TYPE_SUPPORTS_MARKERS_AND_ACTIVE_FILE_FILTER } from "../utils/constants";
import { isFeatureFlagEnabled } from "../utils/environmentUtils";
import { getLogger } from "../utils/logger";
import { isDownloadRelatedSetupMessage } from "../utils/notificationMessageUtils";
import { IssueSourceConfigService } from "./issueSourceConfigService";
