const localize: LocalizeFunc = loadMessageBundle();
const SPIN_ICON = "$(sync~spin) ";
const INFO_ICON = "$(info)";
const ALERT_ICON = "$(alert)";
const WARNING_ICON = "$(warning)";

enum StatusPriority {
    HIGH = 1,    // Errors, configuration required
    MEDIUM = 2,  // Active scans, loading states
    LOW = 3      // Idle states, completed operations
}

interface StatusState {
    id: string;
    priority: StatusPriority;
    text: string;
    tooltip?: string | MarkdownString;
    backgroundColor?: ThemeColor;
    command?: string | Command;
}

export class UnifiedStatusManager {
    private statusItem: StatusBarItem;
    private currentStates: Map<string, StatusState> = new Map();

    constructor() {
        this.statusItem = window.createStatusBarItem(StatusBarAlignment.Left);
    }

    updateStatus(state: StatusState): void {
        this.currentStates.set(state.id, state);
        this.refreshDisplay();
    }

    removeStatus(id: string): void {
        this.currentStates.delete(id);
        this.refreshDisplay();
    }

    private refreshDisplay(): void {
        if (this.currentStates.size === 0) {
            this.statusItem.hide();
            return;
        }

        // Find highest priority state
        let highestPriorityState: StatusState | undefined;
        for (const state of this.currentStates.values()) {
            if (!highestPriorityState || state.priority < highestPriorityState.priority) {
                highestPriorityState = state;
            }
        }

        if (highestPriorityState) {
            this.statusItem.text = highestPriorityState.text;
            this.statusItem.tooltip = highestPriorityState.tooltip;
            this.statusItem.backgroundColor = highestPriorityState.backgroundColor;
            this.statusItem.command = highestPriorityState.command;
            this.statusItem.show();
        }
    }

    hide(): void {
        this.statusItem.hide();
        this.currentStates.clear();
    }

    dispose(): void {
        this.hide();
        this.statusItem.dispose();
    }

    // Testing support methods
    hasStatus(statusId: string): boolean {
        return this.currentStates.has(statusId);
    }

    getCurrentStatusText(): string {
        return this.statusItem.text;
    }

    getCurrentStatusTooltip(): string | undefined {
        const tooltip = this.statusItem.tooltip;
        if (typeof tooltip === 'string') {
            return tooltip;
        } else if (tooltip && typeof tooltip === 'object' && 'value' in tooltip) {
            return tooltip.value;
        }
        return undefined;
    }

    isVisible(): boolean {
        return this.currentStates.size > 0;
    }
}

export abstract class ProgressNotificationService {

    static readonly id: ServiceId<ProgressNotificationService> = { id: ProgressNotificationService.name };

    /**
     * Display the setup progress status bar item
     * @param reveal if the status bar item is currently hidden, reveal it
     * @param setupNotificationMessage optional. Details from this notification will be displayed in the notification
     */
    abstract updateSetupProgress(reveal: boolean, setupNotificationMessage?: NotificationMessage): void;
    abstract hideSetupProgress(): void;

    abstract updateScanProgress(scanProgressNotification: MonitorResultsNotification): Promise<void>;
    abstract updateMarkerStatus(loading: boolean, totalMarkersCount?: number, isNonFileEditor?: boolean, isEditorMarkersEnabled?: boolean): Promise<void>;
    abstract hideMarkerStatus(): void;
    abstract showCustomWorkingDirAlert(shouldShow: boolean): Promise<void>;
    abstract dispose(): void;
}
export class ProgressNotificationServiceImpl implements ProgressNotificationService {

    protected codeSightSetupStatus: CodeSightStatusBarItem;
    protected scanningStatus: CodeSightStatusBarItem;
    protected customWorkingDirAlert: CodeSightStatusBarItem;

    private runningSingleFileScansData: Map<string, RefreshStatus>;
    private runningFullScan: RefreshStatus | undefined;

    constructor() {
        this.codeSightSetupStatus = new CodeSightStatusBarItem();
        this.codeSightSetupStatus.setCommand(COMMAND_OPEN_ONBOARDING);

        this.scanningStatus = new CodeSightStatusBarItem();

        this.customWorkingDirAlert = new CodeSightStatusBarItem();
        this.customWorkingDirAlert.setCommand(COMMAND_OPEN_CUSTOM_WORKING_DIR);

        this.runningSingleFileScansData = new Map<string, RefreshStatus>();
    }

    async showCustomWorkingDirAlert(shouldShow: boolean) {
        if (shouldShow) {
            this.customWorkingDirAlert.setText(`${ALERT_ICON} ${localize('custom.working.dir.alert', 'Code Sight: Configuration Required')}`);
            this.customWorkingDirAlert.show();
        } else {
            this.customWorkingDirAlert.hide();
        }
    }

    updateSetupProgress(reveal: boolean, setupNotificationMessage?: NotificationMessage): void {
        if (setupNotificationMessage && isDownloadRelatedSetupMessage(setupNotificationMessage)) {
            // show message reflecting setup status
            if (setupNotificationMessage.getAdditionalcontentList().length === 1) {
                let additionalContent = setupNotificationMessage.getAdditionalcontentList()[0];
                this.codeSightSetupStatus.setText(SPIN_ICON + `Code Sight: ${additionalContent.getTitle()} - ${additionalContent.getContent()}`);
            } else {
                this.codeSightSetupStatus.setText(SPIN_ICON + `Code Sight: ${setupNotificationMessage.getDescription()}`);
            }
        } else {
            // setup is required, but we do not have an active download/install happening
            // just show a generic "Code Sight setting up" message
            this.codeSightSetupStatus.setText(`${ALERT_ICON} ${localize('progress.setup.status', 'Code Sight Setup Required')}`);
        } 
        if(reveal){
            this.codeSightSetupStatus.show();
        }        
    }

    hideSetupProgress(){
        this.codeSightSetupStatus.hide();
    }

    hideMarkerStatus() {
        // Legacy implementation does nothing for marker status
        return;
    }

    async updateMarkerStatus(loading: boolean, totalMarkersCount?: number, isNonFileEditor?: boolean, isEditorMarkersEnabled?: boolean) {
        // Legacy implementation does nothing for marker status
        return;
    }

    async updateScanProgress(scanProgressNotification: MonitorResultsNotification): Promise<void> {
        let resultStatus: RefreshStatus | undefined = scanProgressNotification.getStatus();
        if (!resultStatus) {
            getLogger().warn("Unexpected state: MonitorResultsNotification from controller has no status");
            return;
        }
        let scanStatus = resultStatus.getStatus();

        switch (scanStatus) {
            case RefreshStatus.Status.PREPARING:
            case RefreshStatus.Status.RUNNING:
                this.scanStartedOrUpdated(resultStatus);
                break;
            case RefreshStatus.Status.FAILED:
            case RefreshStatus.Status.CANCELLED:
            case RefreshStatus.Status.SUCCESS:
                this.scanStopped(resultStatus);
                break;
        }
    }

    private scanStartedOrUpdated(scanNotification: RefreshStatus) {
        if (this.isSingleFileScan(scanNotification)) {
            this.runningSingleFileScansData.set(scanNotification.getJobid(), scanNotification);
            this.refreshScanningStatus();
        } else if (this.isFullScan(scanNotification)) {
            if (!this.runningFullScan
                || this.runningFullScan.getJobid() !== scanNotification.getJobid()
                || this.runningFullScan.getDescription() !== scanNotification.getDescription()) {
                this.runningFullScan = scanNotification;
                this.refreshScanningStatus();
            }
        }
    }

    private scanStopped(scanNotification: RefreshStatus) {
        if (this.isFullScan(scanNotification) && this.runningFullScan && this.runningFullScan.getJobid() === scanNotification.getJobid()) {
            this.runningFullScan = undefined;
            this.refreshScanningStatus();
        } else if (this.isSingleFileScan(scanNotification)) {
            this.runningSingleFileScansData.delete(scanNotification.getJobid());
            this.refreshScanningStatus();
        }
    }

    private refreshScanningStatus() {
        if (!this.runningFullScan && this.runningSingleFileScansData.size === 0) {
            this.scanningStatus.hide();
        } else if (this.runningFullScan && this.runningSingleFileScansData.size > 0) {
            this.scanningStatus.setText(SPIN_ICON + localize("progress.single.and.full", "Code Sight: Running single file and full scans"));
            this.scanningStatus.show();
        } else if (this.runningFullScan) {
            this.scanningStatus.setText(SPIN_ICON + this.runningFullScan.getDescription());
            this.scanningStatus.show();
        } else if (this.runningSingleFileScansData.size > 0) {
            if (this.runningSingleFileScansData.size === 1) {
                let refreshStatus: RefreshStatus | undefined = this.runningSingleFileScansData.values().next().value;
                if (refreshStatus) {
                    this.scanningStatus.setText(SPIN_ICON + refreshStatus.getDescription());
                }
            } else {
                this.scanningStatus.setText(SPIN_ICON + localize("progress.many.single", "Code Sight: Scanning file(s) for issues"));
            }
            this.scanningStatus.show();
        }
    }

    private isFullScan(scanNotification: RefreshStatus): boolean {
        return scanNotification.getReason() === RefreshStatus.Reason.GENERATESUMMARIES;
    }

    private isSingleFileScan(scanNotification: RefreshStatus) {
        return scanNotification.getReason() === RefreshStatus.Reason.REFRESHRESULTS && scanNotification.getFilenamesList().length === 1;
    }

    dispose(): void {
        this.codeSightSetupStatus.statusBarItem.dispose();
        this.scanningStatus.statusBarItem.dispose();
        this.customWorkingDirAlert.statusBarItem.dispose();
    }
}

export class ProgressNotificationServiceMarkerImpl implements ProgressNotificationService {

    protected unifiedStatusManager: UnifiedStatusManager;
    protected customWorkingDirAlert: CodeSightStatusBarItem;

    private runningSingleFileScansData: Map<string, RefreshStatus>;
    private runningFullScan: RefreshStatus | undefined;
    private runningChangedFileScan: RefreshStatus | undefined;

    constructor() {
        this.unifiedStatusManager = new UnifiedStatusManager();
        this.customWorkingDirAlert = new CodeSightStatusBarItem();
        this.customWorkingDirAlert.setCommand(COMMAND_OPEN_CUSTOM_WORKING_DIR);
        this.runningSingleFileScansData = new Map<string, RefreshStatus>();
    }

    async showCustomWorkingDirAlert(shouldShow: boolean) {
        if (shouldShow) {
            this.unifiedStatusManager.updateStatus({
                id: 'custom-working-dir',
                priority: StatusPriority.HIGH,
                text: `${WARNING_ICON} Code Sight: Config Required`,
                tooltip: new MarkdownString(localize('custom.working.dir.alert.tooltip', 'Code Sight configuration is required for custom working directory')),
                backgroundColor: new ThemeColor("statusBarItem.informationBackground"),
                command: COMMAND_OPEN_CUSTOM_WORKING_DIR
            });
        } else {
            this.unifiedStatusManager.removeStatus('custom-working-dir');
        }
    }

    updateSetupProgress(reveal: boolean, setupNotificationMessage?: NotificationMessage): void {
        if (!reveal) {
            return;
        }

        if (setupNotificationMessage && isDownloadRelatedSetupMessage(setupNotificationMessage)) {
            let text: string;
            let tooltip: string;

            if (setupNotificationMessage.getAdditionalcontentList().length === 1) {
                let additionalContent = setupNotificationMessage.getAdditionalcontentList()[0];
                text = `${SPIN_ICON}Code Sight: ${additionalContent.getTitle()}`;
                tooltip = `${additionalContent.getTitle()} - ${additionalContent.getContent()}`;
            } else {
                text = `${SPIN_ICON}Code Sight: ${setupNotificationMessage.getDescription()}`;
                tooltip = setupNotificationMessage.getDescription();
            }

            this.unifiedStatusManager.updateStatus({
                id: 'setup-progress',
                priority: StatusPriority.MEDIUM,
                text: text,
                tooltip: new MarkdownString(tooltip),
                backgroundColor: new ThemeColor("statusBarItem.informationBackground"),
                command: COMMAND_OPEN_ONBOARDING
            });
        } else {
            this.unifiedStatusManager.updateStatus({
                id: 'setup-required',
                priority: StatusPriority.HIGH,
                text: `${INFO_ICON} Code Sight: Setup Required`,
                tooltip: new MarkdownString(localize('progress.setup.status.tooltip', 'Code Sight setup is required. Click to open onboarding.')),
                backgroundColor: new ThemeColor("statusBarItem.informationBackground"),
                command: COMMAND_OPEN_ONBOARDING
            });
        }
    }

    hideSetupProgress() {
        this.unifiedStatusManager.removeStatus('setup-progress');
        this.unifiedStatusManager.removeStatus('setup-required');
    }

    hideMarkerStatus() {
        this.unifiedStatusManager.removeStatus('marker-status');
    }

    async updateMarkerStatus(loading: boolean, totalMarkersCount?: number, isNonFileEditor?: boolean, isEditorMarkersEnabled?: boolean) {
        if (!isFeatureFlagEnabled(ENV_CODESIGHT_EDITOR_MARKERS) || !isEditorMarkersEnabled) {
            return;
        }
        const markerView = getService(MarkerService.id).getCurrentMarkerView();
        let isMarkersSupported = true;
        if (markerView === MarkerView.Team) {
            const issueSource = getService(IssueSourceConfigService.id).getSelectedSource();
            isMarkersSupported = issueSource?.serverType !== undefined && TEAM_VIEW_SERVER_TYPE_SUPPORTS_MARKERS_AND_ACTIVE_FILE_FILTER.includes(issueSource.serverType);
        }
        const markerToggleCommand = getService(MarkerService.id).getMarkerToggleCommand(totalMarkersCount, isNonFileEditor, isMarkersSupported);
        let markersCountText = isMarkersSupported ? (totalMarkersCount) : localize('markers.not.supported', 'n/a');

        if (loading) {
            this.unifiedStatusManager.updateStatus({
                id: 'marker-status',
                priority: StatusPriority.MEDIUM,
                text: `${SPIN_ICON}Code Sight: ${markerView} View Issues`,
                tooltip: new MarkdownString(markerToggleCommand.tooltip),
                command: markerToggleCommand.command,

            });
        } else {
            this.unifiedStatusManager.updateStatus({
                id: 'marker-status',
                priority: StatusPriority.LOW,
                text: `Code Sight: ${markerView} View Issues${(totalMarkersCount !== undefined || (!isNonFileEditor && !isMarkersSupported)) ? ` (${markersCountText})` : ''}`,
                tooltip: new MarkdownString(markerToggleCommand.tooltip),
                backgroundColor: totalMarkersCount ? new ThemeColor("statusBarItem.warningBackground") : undefined,
                command: markerToggleCommand.command,
            });
        }
    }

    async updateScanProgress(scanProgressNotification: MonitorResultsNotification): Promise<void> {
        let resultStatus: RefreshStatus | undefined = scanProgressNotification.getStatus();
        if (!resultStatus) {
            getLogger().warn("Unexpected state: MonitorResultsNotification from controller has no status");
            return;
        }
        let scanStatus = resultStatus.getStatus();

        switch (scanStatus) {
            case RefreshStatus.Status.PREPARING:
            case RefreshStatus.Status.RUNNING:
                this.scanStartedOrUpdated(resultStatus);
                break;
            case RefreshStatus.Status.FAILED:
            case RefreshStatus.Status.CANCELLED:
            case RefreshStatus.Status.SUCCESS:
                this.scanStopped(resultStatus);
                break;
        }
    }

    private scanStartedOrUpdated(scanNotification: RefreshStatus) {
        if (this.isSingleFileScan(scanNotification)) {
            this.runningSingleFileScansData.set(scanNotification.getJobid(), scanNotification);
            this.refreshScanningStatus();
        } else if (this.isFullScan(scanNotification)) {
            if (!this.runningFullScan
                || this.runningFullScan.getJobid() !== scanNotification.getJobid()
                || this.runningFullScan.getDescription() !== scanNotification.getDescription()) {
                this.runningFullScan = scanNotification;
                this.refreshScanningStatus();
            }
        } else if (this.isChangedFileScan(scanNotification)) {
            if (!this.runningChangedFileScan
                || this.runningChangedFileScan.getJobid() !== scanNotification.getJobid()
                || this.runningChangedFileScan.getDescription() !== scanNotification.getDescription()) {
                this.runningChangedFileScan = scanNotification;
                this.refreshScanningStatus();
            }
        }
    }

    private scanStopped(scanNotification: RefreshStatus) {
        if (this.isFullScan(scanNotification) && this.runningFullScan && this.runningFullScan.getJobid() === scanNotification.getJobid()) {
            this.runningFullScan = undefined;
            this.refreshScanningStatus();
        } else if (this.isChangedFileScan(scanNotification) && this.runningChangedFileScan
            && this.runningChangedFileScan.getJobid() === scanNotification.getJobid()) {
            this.runningChangedFileScan = undefined;
            this.refreshScanningStatus();
        } else if (this.isSingleFileScan(scanNotification)) {
            this.runningSingleFileScansData.delete(scanNotification.getJobid());
            this.refreshScanningStatus();
        }
    }

    private refreshScanningStatus() {
        if (!this.runningFullScan && !this.runningChangedFileScan && this.runningSingleFileScansData.size === 0) {
            this.unifiedStatusManager.removeStatus('scanning-status');
        } else if (this.runningFullScan) {
            this.unifiedStatusManager.updateStatus({
                id: 'scanning-status',
                priority: StatusPriority.MEDIUM,
                text: `${SPIN_ICON}${this.addCodeSightPrefix(this.runningFullScan.getDescription())}`,
                tooltip: new MarkdownString(this.runningFullScan.getDescription())
            });
        } else if (this.runningChangedFileScan) {
            this.unifiedStatusManager.updateStatus({
                id: 'scanning-status',
                priority: StatusPriority.MEDIUM,
                text: `${SPIN_ICON}${this.addCodeSightPrefix(localize("progress.changed.files", "Scanning code changes"))}`,
                tooltip: new MarkdownString(this.runningChangedFileScan.getDescription())
            });
        } else if (this.runningSingleFileScansData.size > 0) {
            if (this.runningSingleFileScansData.size === 1) {
                let refreshStatus: RefreshStatus | undefined = this.runningSingleFileScansData.values().next().value;
                if (refreshStatus) {
                    const fileName = this.getFileNameFromScanStatus(refreshStatus);
                    this.unifiedStatusManager.updateStatus({
                        id: 'scanning-status',
                        priority: StatusPriority.MEDIUM,
                        text: `${SPIN_ICON}${this.addCodeSightPrefix(localize("progress.single.file", "Scanning {0}", fileName))}`,
                        tooltip: new MarkdownString(refreshStatus.getDescription())
                    });
                }
            } else {
                this.unifiedStatusManager.updateStatus({
                    id: 'scanning-status',
                    priority: StatusPriority.MEDIUM,
                    text: `${SPIN_ICON}${this.addCodeSightPrefix(localize("progress.many.single.files", "Scanning {0} Files", this.runningSingleFileScansData.size))}`,
                    tooltip: new MarkdownString(localize("progress.many.single.tooltip", "Scanning {0} files for issues", this.runningSingleFileScansData.size))
                });
            }
        }
    }

    private addCodeSightPrefix(text: string): string {
        if (text.startsWith("Code Sight")) {
            return text;
        }
        return `Code Sight: ${text}`;
    }

    private isFullScan(scanNotification: RefreshStatus): boolean {
        return scanNotification.getReason() === RefreshStatus.Reason.GENERATESUMMARIES;
    }

    private isSingleFileScan(scanNotification: RefreshStatus) {
        return scanNotification.getReason() === RefreshStatus.Reason.REFRESHRESULTS && scanNotification.getFilenamesList().length === 1;
    }

    private isChangedFileScan(scanNotification: RefreshStatus): boolean {
        return scanNotification.getReason() === RefreshStatus.Reason.REFRESHRESULTS
            && scanNotification.getFilenamesList().length === 0
            && (scanNotification.getTier() === RefreshResultsRequest.Tier.ALLUNCOMMITTED
                || scanNotification.getTier() === RefreshResultsRequest.Tier.REFERENCEBRANCH);
    }

    private getFileNameFromPath(filePath: string): string {
        const parts = filePath.split('/');
        return parts[parts.length - 1] || filePath;
    }

    private getFileNameFromScanStatus(scanStatus: RefreshStatus): string {
        const fileNames = scanStatus.getFilenamesList();
        if (fileNames.length > 0) {
            return this.getFileNameFromPath(fileNames[0]);
        }
        return 'file';
    }


    dispose(): void {
        this.unifiedStatusManager.dispose();
        this.customWorkingDirAlert.statusBarItem.dispose();
    }
}

/**
 * Code Sight wrapper for StatusBarItem that allows for testing visibility
 */
export class CodeSightStatusBarItem {
    statusBarItem: StatusBarItem;
    isVisible: boolean;

    constructor() {
        this.statusBarItem = window.createStatusBarItem(StatusBarAlignment.Left);
        this.isVisible = false;
    }

    setCommand(command: string | Command) {
        this.statusBarItem.command = command;
    }

    setText(text: string) {
        this.statusBarItem.text = text;
    }

    show(): void {
        this.isVisible = true;
        this.statusBarItem.show();
    }

    hide(): void {
        this.isVisible = false;
        this.statusBarItem.hide();
    }

    isStatusBarVisible(): boolean {
        return this.isVisible;
    }

    getCommand(): string | Command | undefined {
        return this.statusBarItem.command;
    }

    getText(): string {
        return this.statusBarItem.text;
    }
}