import { FileScanInfo, RefreshResultsRequest, RefreshStatus } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_service_pb";
import { ScanConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/scan_config_pb";
import { Error } from "@codesight/codesight-controller-proto/controller_proto/v0/tool_service_pb";
import { IssueDiffValue } from "@codesight/codesight-controller-proto/controller_proto/v1/issues_service_pb";
import { CsseLicenseState } from "../../models/csseLicenseInfo";
import { NewIssue } from "../../models/newIssue";
import { CategoryItems, PageControls } from "../../services/issuesService";
import { ReferenceBranch, ScanConfiguration } from "../../services/scanConfigurationService";
import { ScanMode } from "../../services/scanStatusCoordinator";

/**
 * Centralized definition of all LocalView state types.
 * Using const object pattern provides autocomplete, type safety, and no runtime overhead.
 */
export const LocalViewStateType = {
    // Error states
    ViewLevelError: 'viewLevelError',
    ModeSpecificError: 'modeSpecificError',

    // Project mode states
    ManualLoading: 'manualLoading',
    ManualNoScan: 'manualNoScan',
    ManualNoScanTypes: 'manualNoScanTypes',
    ManualResults: 'manualResults',
    ManualNoResults: 'manualNoResults',
    ManualScanFailed: 'manualScanFailed',
    ManualScanCancelled: 'manualScanCancelled',
    ManualPagingError: 'manualPagingError',

    // Incremental mode states
    AutoNoEditors: 'autoNoEditors',
    AutoScanning: 'autoScanning',
    AutoResults: 'autoResults',
    AutoNoResults: 'autoNoResults',
    AutoScanFailed: 'autoScanFailed',

    // Signal mode states
    SignalLoading: 'signalLoading',
    SignalScanning: 'signalScanning',
    SignalScanCancelling: 'signalScanCancelling',
    SignalScanFailed: 'signalScanFailed',
    SignalScanCancelled: 'signalScanCancelled',
    SignalResults: 'signalResults',
    SignalNoResults: 'signalNoResults',

    // Auto changed-files mode states
    AutoChangedFilesLoading: 'autoChangedFilesLoading',
    AutoChangedFilesScanning: 'autoChangedFilesScanning',
    AutoChangedFilesScanCancelling: 'autoChangedFilesScanCancelling',
    AutoChangedFilesScanFailed: 'autoChangedFilesScanFailed',
    AutoChangedFilesScanCancelled: 'autoChangedFilesScanCancelled',
    AutoChangedFilesResults: 'autoChangedFilesResults',
    AutoChangedFilesNoResults: 'autoChangedFilesNoResults',

    // Special view states
    SimpleView: 'simpleView',
} as const;

/**
 * Common properties shared across all Local View states
 */
interface BaseLocalViewState {
    scanMode: ScanMode;
    pageControls: PageControls;
}

/**
 * Top-level discriminated union for all possible Local View states
 * This replaces the previous LocalViewTreeState interface with a type-safe
 * discriminated union that prevents invalid state combinations.
 */
export type LocalViewState =
    | ViewLevelErrorState
    | ModeSpecificErrorState
    | NormalOperationState;

/**
 * View-level errors that hide the entire view content
 * These errors take precedence over all other states and hide the mode selector
 */
export interface ViewLevelErrorState extends BaseLocalViewState {
    type: typeof LocalViewStateType.ViewLevelError;
    error: {
        kind: 'noProductEntitlement';
    } | {
        kind: 'invalidCSSELicense';
        licenseState: CsseLicenseState;
    };
}

/**
 * Mode-specific errors shown below the mode selector
 * These errors hide the normal view content but show the mode selector
 */
export interface ModeSpecificErrorState extends BaseLocalViewState {
    type: typeof LocalViewStateType.ModeSpecificError;
    scanFileScope?: RefreshResultsRequest.Tier;
    selectedFolder?: WorkspaceFolderSelection;
    error: {
        kind: 'noInstalledTools';
    } | {
        kind: 'notAGitRepository';
    };
}

/**
 * Normal operation states - further discriminated by scan mode and sub-states
 */
export type NormalOperationState =
    | ManualModeState
    | AutoModeState
    | AutoChangedFilesModeState
    | SignalModeState
    | SimpleViewState;


/**
 * Base properties for all Project mode states
 */
interface BaseManualModeState extends BaseLocalViewState {
    scanMode: ScanMode.Manual;
    selectedScanType?: ScanConfig.ScanType;
    selectedScanInfo?: FileScanInfo;
    appliedDiffFilter: IssueDiffValue;
    hasFiltersApplied: boolean;
    searchFilter?: string;
    selectedReferenceBranch?: ReferenceBranch;
}

/**
 * Project mode: Scan is currently running and loading results
 */
export interface ManualModeLoadingState extends BaseManualModeState {
    type: typeof LocalViewStateType.ManualLoading;
    lastScanStatus: RefreshStatus.Status;
    selectedScanConfig: ScanConfiguration;
    lastScanConfigName: string;
    loadingReason: 'scanning' | 'refreshing';
}

/**
 * Project mode: No scan has been performed yet
 */
export interface ManualModeNoScanState extends BaseManualModeState {
    type: typeof LocalViewStateType.ManualNoScan;
    lastScanStatus: undefined;
}

/**
 * Project mode: No scan types are available (only Signal/Incremental mode is available)
 */
export interface ManualModeNoScanTypesState extends BaseManualModeState {
    type: typeof LocalViewStateType.ManualNoScanTypes;
    lastScanStatus: undefined;
}

/**
 * Project mode: Scan completed successfully with results
 */
export interface ManualModeResultsState extends BaseManualModeState {
    type: typeof LocalViewStateType.ManualResults;
    lastScanStatus: RefreshStatus.Status.SUCCESS;
    issuesList: NewIssue[];
    totalIssueCount: number;
}

/**
 * Project mode: Scan completed successfully but found no issues
 */
export interface ManualModeNoResultsState extends BaseManualModeState {
    type: typeof LocalViewStateType.ManualNoResults;
    lastScanStatus: RefreshStatus.Status.SUCCESS;
}

/**
 * Project mode: Scan failed with an error
 */
export interface ManualModeScanFailedState extends BaseManualModeState {
    type: typeof LocalViewStateType.ManualScanFailed;
    lastScanStatus: RefreshStatus.Status.FAILED;
    lastScanDate: Date;
    lastScanConfigName: string;
}

/**
 * Project mode: Scan was cancelled by the user
 */
export interface ManualModeScanCancelledState extends BaseManualModeState {
    type: typeof LocalViewStateType.ManualScanCancelled;
    lastScanStatus: RefreshStatus.Status.CANCELLED;
}

/**
 * Project mode: Error occurred while paginating results
 */
export interface ManualModePagingErrorState extends BaseManualModeState {
    type: typeof LocalViewStateType.ManualPagingError;
    lastScanStatus: RefreshStatus.Status.SUCCESS;
    pagingError: Error;
}

/**
 * Represents the workspace folder selection state for multi-folder workspaces.
 * When undefined on a state interface, the folder selection node is not shown.
 */
export type WorkspaceFolderSelection = { status: 'configured'; name: string; path: string };


/**
 * Union of all Project mode states
 */
export type ManualModeState =
    | ManualModeLoadingState
    | ManualModeNoScanState
    | ManualModeNoScanTypesState
    | ManualModeResultsState
    | ManualModeNoResultsState
    | ManualModeScanFailedState
    | ManualModeScanCancelledState
    | ManualModePagingErrorState;

/**
 * Base properties for all Incremental mode states
 */
interface BaseAutoModeState extends BaseLocalViewState {
    scanMode: ScanMode.Auto;
    scanFileScope?: RefreshResultsRequest.Tier;
    searchFilter?: string;
    /** Workspace folder selection for multi-folder workspaces in changed-files scope. */
    selectedFolder?: WorkspaceFolderSelection;
}

/**
 * Incremental mode: No text editors are currently open
 */
export interface AutoModeNoEditorsState extends BaseAutoModeState {
    type: typeof LocalViewStateType.AutoNoEditors;
}

/**
 * Incremental mode: Actively scanning open files
 */
export interface AutoModeScanningState extends BaseAutoModeState {
    type: typeof LocalViewStateType.AutoScanning;
    rapidScan?: {
        scanning: boolean;
    };
    licenseScan?: {
        scanning: boolean;
    };
}

/**
 * Incremental mode: Scan completed with results available
 */
export interface AutoModeResultsState extends BaseAutoModeState {
    type: typeof LocalViewStateType.AutoResults;
    rapidScan?: {
        scanning: boolean;
        categoryIssues?: CategoryItems[];
        flatIssues?: NewIssue[];
        totalIssueCount: number;
    };
    licenseScan?: {
        scanning: boolean;
        issues: NewIssue[];
        totalIssueCount: number;
        lastScanStatus?: RefreshStatus.Status;
        lastScanDate?: Date;
    };
}

/**
 * Incremental mode: No issues found in open files
 */
export interface AutoModeNoResultsState extends BaseAutoModeState {
    type: typeof LocalViewStateType.AutoNoResults;
    hasScanInfo: boolean;
    rapidScan?: {
        scanning: boolean;
    };
    licenseScan?: {
        scanning: boolean;
    };
}

/**
 * Incremental mode: Code Changes scan failed with an error
 */
export interface AutoModeScanFailedState extends BaseAutoModeState {
    type: typeof LocalViewStateType.AutoScanFailed;
    lastScanStatus: RefreshStatus.Status.FAILED;
    lastScanDate: Date;
}

/**
 * Union of all Incremental mode states
 */
export type AutoModeState =
    | AutoModeNoEditorsState
    | AutoModeScanningState
    | AutoModeResultsState
    | AutoModeNoResultsState
    | AutoModeScanFailedState;

/**
 * Base properties for all Auto changed-files mode states.
 * Changed-files scans don't depend on open editors and always show categorized results.
 */
interface BaseAutoChangedFilesModeState extends BaseLocalViewState {
    scanMode: ScanMode.Auto;
    scanFileScope: RefreshResultsRequest.Tier;
    searchFilter?: string;
    selectedFolder?: WorkspaceFolderSelection;
}

/**
 * Auto changed-files mode: Loading/refreshing results (not scanning)
 */
export interface AutoChangedFilesLoadingState extends BaseAutoChangedFilesModeState {
    type: typeof LocalViewStateType.AutoChangedFilesLoading;
    loadingReason: 'refreshing';
}

/**
 * Auto changed-files mode: Scan is currently running
 */
export interface AutoChangedFilesScanningState extends BaseAutoChangedFilesModeState {
    type: typeof LocalViewStateType.AutoChangedFilesScanning;
}

/**
 * Auto changed-files mode: Scan failed with an error
 */
export interface AutoChangedFilesScanFailedState extends BaseAutoChangedFilesModeState {
    type: typeof LocalViewStateType.AutoChangedFilesScanFailed;
    lastScanStatus: RefreshStatus.Status.FAILED;
    lastScanDate: Date;
}

/**
 * Auto changed-files mode: Cancel request is in-flight, waiting for controller acknowledgement
 */
export interface AutoChangedFilesScanCancellingState extends BaseAutoChangedFilesModeState {
    type: typeof LocalViewStateType.AutoChangedFilesScanCancelling;
}

/**
 * Auto changed-files mode: Scan was cancelled by the user
 */
export interface AutoChangedFilesScanCancelledState extends BaseAutoChangedFilesModeState {
    type: typeof LocalViewStateType.AutoChangedFilesScanCancelled;
}

/**
 * Auto changed-files mode: Scan completed with categorized results
 */
export interface AutoChangedFilesResultsState extends BaseAutoChangedFilesModeState {
    type: typeof LocalViewStateType.AutoChangedFilesResults;
    categoryIssues: CategoryItems[];
    totalIssueCount: number;
}

/**
 * Auto changed-files mode: No results found or no scan performed
 */
export interface AutoChangedFilesNoResultsState extends BaseAutoChangedFilesModeState {
    type: typeof LocalViewStateType.AutoChangedFilesNoResults;
    hasScanInfo: boolean;
}

/**
 * Union of all Auto changed-files mode states
 */
export type AutoChangedFilesModeState =
    | AutoChangedFilesLoadingState
    | AutoChangedFilesScanningState
    | AutoChangedFilesScanCancellingState
    | AutoChangedFilesScanFailedState
    | AutoChangedFilesScanCancelledState
    | AutoChangedFilesResultsState
    | AutoChangedFilesNoResultsState;

/**
 * Base properties for all Signal mode states
 */
interface BaseSignalModeState extends BaseLocalViewState {
    scanMode: ScanMode.Manual; // Signal mode uses Manual scanMode internally
    scanFileScope: RefreshResultsRequest.Tier;
    searchFilter?: string;
    selectedScanType?: ScanConfig.ScanType;
    timerInfo?: {
        isActive: boolean;
        nextScanTime?: Date;
        lastScanTime?: Date;
    };
    /** Workspace folder selection for multi-folder workspaces in changed-files scope. */
    selectedFolder?: WorkspaceFolderSelection;
}

/**
 * Signal mode: Loading results (refreshing UI, not scanning)
 */
export interface SignalModeLoadingState extends BaseSignalModeState {
    type: typeof LocalViewStateType.SignalLoading;
    loadingReason: 'refreshing';
}

/**
 * Signal mode: AI scan is currently running
 */
export interface SignalModeScanningState extends BaseSignalModeState {
    type: typeof LocalViewStateType.SignalScanning;
    lastScanDate?: Date;
}

/**
 * Signal mode: Cancel request is in-flight, waiting for controller acknowledgement
 */
export interface SignalModeScanCancellingState extends BaseSignalModeState {
    type: typeof LocalViewStateType.SignalScanCancelling;
}

/**
 * Signal mode: AI scan failed with an error
 */
export interface SignalModeScanFailedState extends BaseSignalModeState {
    type: typeof LocalViewStateType.SignalScanFailed;
    lastScanStatus: RefreshStatus.Status.FAILED;
    lastScanDate: Date;
}

/**
 * Signal mode: AI scan was cancelled by user
 */
export interface SignalModeScanCancelledState extends BaseSignalModeState {
    type: typeof LocalViewStateType.SignalScanCancelled;
}

/**
 * Signal mode: AI scan completed with categorized results
 */
export interface SignalModeResultsState extends BaseSignalModeState {
    type: typeof LocalViewStateType.SignalResults;
    categoryIssues: CategoryItems[];
    totalIssueCount: number;
}

/**
 * Signal mode: AI scan completed but found no issues
 */
export interface SignalModeNoResultsState extends BaseSignalModeState {
    type: typeof LocalViewStateType.SignalNoResults;
    hasScanInfo: boolean;
    /** True when file scope is FAST and the current active file was not part of the last scan */
    activeFileNotScanned?: boolean;
}

/**
 * Union of all Signal mode states
 */
export type SignalModeState =
    | SignalModeLoadingState
    | SignalModeScanningState
    | SignalModeScanCancellingState
    | SignalModeScanFailedState
    | SignalModeScanCancelledState
    | SignalModeResultsState
    | SignalModeNoResultsState;

/**
 * Simple view mode: Focusing on a single issue with option to return to full list
 * This state wraps another normal state and adds single-issue focus
 */
export interface SimpleViewState extends BaseLocalViewState {
    type: typeof LocalViewStateType.SimpleView;
    focusedIssue: NewIssue;
    categoryName?: string;
    // The underlying normal state that this view is based on
    // Used to restore the full view when exiting simple view
    baseState: Exclude<NormalOperationState, SimpleViewState>;
}
