import { ResendTrialEmailRequest, ResendTrialEmailResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/license_service_pb";
import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { Disposable, WebviewPanel } from "vscode";
import { LocalizeFunc, loadMessageBundle } from "vscode-nls";
import { CsseLicenseState } from "../../models/csseLicenseInfo";
import { ControllerClientService } from "../../services/controllerClientService";
import { EntitlementService } from "../../services/entitlementService";
import { InfoMessageService, WarningMessageService } from "../../services/extensionMessageService";
import { LicenseService } from "../../services/licenseService";
import { getService } from "../../services/serviceContainer";
import { getLogger } from "../../utils/logger";
import { WebviewCoordinator } from "../../views/webviewCoordinator";
import { WebviewPresenter } from "../webviewPresenter";
import { EmailVerificationMessageViewProvider, EmailVerificationViewCommandIds } from "./emailVerificationViewProvider";
const localize: LocalizeFunc = loadMessageBundle();

export class EmailVerificationMessageViewPresenter implements WebviewPresenter {
    private readonly panel: WebviewPanel;
    private view: EmailVerificationMessageViewProvider;
    private onMessageFromWebviewDisposable: Disposable | undefined;
    private hasTransition?: boolean;

    constructor(panel: WebviewPanel, hasTransition?: boolean) {
        this.panel = panel;
        this.view = getService(EmailVerificationMessageViewProvider.id);
        this.view.initView(this.panel);
        this.hasTransition = hasTransition;

        this.onMessageFromWebviewDisposable = this.view.onMessageFromWebview(async message => {
            switch (message.command) {
                case EmailVerificationViewCommandIds.VIEW_RESEND_VERIFICATION_EMAIL:
                    await this.resendVerificationEmail();
                    break;
                case EmailVerificationViewCommandIds.VIEW_REFRESH_LICENSE_STATUS:
                    await this.refreshLicenseStatus();
                    break;
                case EmailVerificationViewCommandIds.VIEW_PREVIOUS_BUTTON:
                    await getService(WebviewCoordinator.id).showInstalledToolsMessage();
                    break;
                case EmailVerificationViewCommandIds.VIEW_CLOSE_BUTTON:
                    return this.view.dispose();
                default:
                    getLogger().warn(`Received unexpected message ${message.command}`);
                    break;
            }

            return Promise.resolve();
        });
    }

    public async parseNotification(message: NotificationMessage) {
    }

    public async initView() {
        this.view.initHtml(this.hasTransition);

        // set email field
        let email = await getService(LicenseService.id).getRegistrationEmail();
        this.view.postMessageToWebview({
            command: EmailVerificationViewCommandIds.SET_EMAIL_ADDRESS,
            value: email
        });

        // disable refresh button while state is loading
        this.view.postMessageToWebview({
            command: EmailVerificationViewCommandIds.ENABLE_BUTTON,
            id: EmailVerificationViewCommandIds.VIEW_REFRESH_LICENSE_STATUS,
            enable: "false"
        });

        // set verification status
        let entitlementService = getService(EntitlementService.id);
        await entitlementService.checkEntitlements();
        let license = entitlementService.getCachedProductEntitlement().getCsseLicense();
        await this.handleLicenseStatusResponse(license.getState());
    }

    private async resendVerificationEmail() {
        // set spinner and disable the button
        this.view.postMessageToWebview({
            command: EmailVerificationViewCommandIds.UPDATE_RESEND_BUTTON_STATE,
            loading: "true",
        });
        this.view.postMessageToWebview({
            command: EmailVerificationViewCommandIds.ENABLE_BUTTON,
            id: EmailVerificationViewCommandIds.VIEW_RESEND_VERIFICATION_EMAIL,
            enable: "false"
        });
        
        let licenseServiceClient = await getService(ControllerClientService.id).getLicenseServiceClient();
        let resendEmailResponse = await licenseServiceClient.resendTrialEmail(new ResendTrialEmailRequest());
        if (!resendEmailResponse.getSuccess()) {
            let responseCode = resendEmailResponse.getState();
            if (responseCode === ResendTrialEmailResponse.TrialState.TOOMANYREQUESTS) {
                // eslint-disable-next-line @typescript-eslint/no-floating-promises
                getService(InfoMessageService.id).show(localize("resend.email.already.sent.message", "Your verification email is already on its way."), []);
            } else {
                getLogger().warn(`Error occurred while calling resendTrialEmail; error=${responseCode} message=${resendEmailResponse.getMessage()};`);
                // eslint-disable-next-line @typescript-eslint/no-floating-promises
                getService(WarningMessageService.id).getResendEmailErrorMessage(responseCode);
            }
        }

        // remove spinner and enable the button
        this.view.postMessageToWebview({
            command: EmailVerificationViewCommandIds.UPDATE_RESEND_BUTTON_STATE,
            loading: "false",
        });
        this.view.postMessageToWebview({
            command: EmailVerificationViewCommandIds.ENABLE_BUTTON,
            id: EmailVerificationViewCommandIds.VIEW_RESEND_VERIFICATION_EMAIL,
            enable: "true"
        });
    }

    private async refreshLicenseStatus() {
        // set loading text and disable the button
        this.view.postMessageToWebview({
            command: EmailVerificationViewCommandIds.UPDATE_LICENSE_STATUS,
            status: "loading"
        });
        this.view.postMessageToWebview({
            command: EmailVerificationViewCommandIds.ENABLE_BUTTON,
            id: EmailVerificationViewCommandIds.VIEW_REFRESH_LICENSE_STATUS,
            enable: "false"
        });

        let entitlementService = getService(EntitlementService.id);
        await entitlementService.checkEntitlements();
        let license = entitlementService.getCachedProductEntitlement().getCsseLicense();
        await this.handleLicenseStatusResponse(license.getState());
    }

    private async handleLicenseStatusResponse(licenseState: CsseLicenseState) {
        if (licenseState === CsseLicenseState.Valid) {
            this.view.postMessageToWebview({
                command: EmailVerificationViewCommandIds.UPDATE_LICENSE_STATUS,
                status: "success"
            });
        } else {
            this.view.postMessageToWebview({
                command: EmailVerificationViewCommandIds.UPDATE_LICENSE_STATUS,
                status: "failure"
            });

            await getService(WarningMessageService.id).getLicenseErrorMessage(licenseState);
        }

        // enable the button
        this.view.postMessageToWebview({
            command: EmailVerificationViewCommandIds.ENABLE_BUTTON,
            id: EmailVerificationViewCommandIds.VIEW_REFRESH_LICENSE_STATUS,
            enable: "true"
        });
    }

    public dispose() {
        this.onMessageFromWebviewDisposable?.dispose();
    }
}