import { extensions } from "vscode";
import { EXTENSION_ID } from "../utils/constants";
import { ServiceId } from "./serviceContainer";

export abstract class ExtensionService {
    static readonly id: ServiceId<ExtensionService> = { id: ExtensionService.name };

    /**
     * Returns the currently running version of Code Sight or an empty string if this fails.
     */
    abstract getCodeSightVersion(): string;
}

export class ExtensionServiceImpl implements ExtensionService {

    getCodeSightVersion(): string {
        let extension = extensions.getExtension(EXTENSION_ID);
        if (!extension) {
            return "";
        } else {
            return extension.packageJSON.version;
        }
    }
}