import { Webview } from "vscode";
import { ServiceId } from "../../services/serviceContainer";
import { getWebviewHead } from "../../utils/webviewUtils";
import { WebviewProvider } from "../webviewProvider";

export abstract class DownloadViewProvider extends WebviewProvider {
    static readonly id: ServiceId<DownloadViewProvider> = { id: DownloadViewProvider.name };

    abstract reloadHtml(): void;
}

export class DownloadViewProviderImpl extends DownloadViewProvider {
    constructor() {
        super();
    }

    public reloadHtml() {
        let html = `<!DOCTYPE html>
        <html lang="en">
        <head>
            ${this.head}
        </head>
        <style>
            ${this.style}
        </style>
        <body>
            <div id="outer">
                <div id="inner">
                    <div class='box'>
                        <img class='blackduck-icon float-left' width="28" height="28">
                        <h2 class='float-left margin-left'>Code Sight Initial Configuration: Scan Engine Setup</h2>
                    </div>
                    <h1 id="tool-setup-title"></h1>
                    <img class='spinner-icon' height="64" width="64"></img>
                    <h1 id="tool-setup-content"></h1>
                </div>
            </div>
        </body>
        <script>
            window.addEventListener('message', event => {
                const message = event.data;
                switch (message.command) {
                    case 'update-progress':
                        updateProgress(message);
                        break;
                }
            });

            function updateProgress(message) {
                document.querySelector("#tool-setup-title").innerHTML = message.title;
                document.querySelector("#tool-setup-content").innerHTML =  message.content;
            }
        </script>
        </html>
        `;

        this.webviewPanel!.webview.html = html;
    }

    protected getHead(webview: Webview): string {
        return getWebviewHead("Tool Setup", webview);
    }

    protected getStyle(): string {
        return `
        #outer {
            width: 700px;
        }

        #inner {
            display: inline-block;
            margin: 0 auto;
            text-align: center;
        }
        `;
    }
}
