import { GetRegistrationInfoRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/license_service_pb";
import { CancellationToken, Disposable, Uri, WebviewView, WebviewViewProvider, WebviewViewResolveContext } from "vscode";
import { LocalizeFunc, loadMessageBundle } from "vscode-nls";
import { ControllerClientService } from "../../services/controllerClientService";
import { ServiceId, getService } from "../../services/serviceContainer";
import { RegistrationListener, SetupService } from "../../services/setupService";
import { DOC_APP_ADDRESS, SUPPORT_ADDRESS } from "../../utils/constants";
import { getLogger } from "../../utils/logger";
import { getIconPath } from "../../utils/webviewUtils";
import { WebviewCoordinator } from "../../views/webviewCoordinator";

const localize: LocalizeFunc = loadMessageBundle();

export class CodeSightHelpViewProvider implements WebviewViewProvider, RegistrationListener {
    public static readonly viewType = 'codesight-help-view';
    static readonly id: ServiceId<CodeSightHelpViewProvider> = { id: CodeSightHelpViewProvider.name };
    private onMessageFromWebviewDisposable: Disposable | undefined;

    private view?: WebviewView;

    constructor(private readonly extensionUri: Uri) {
        getService(SetupService.id).addRegistrationListener(this);
    }

    public async resolveWebviewView(webviewView: WebviewView, context?: WebviewViewResolveContext, token?: CancellationToken) {
        this.view = webviewView;

        webviewView.webview.options = {
            enableScripts: true,

            localResourceRoots: [
                this.extensionUri
            ]
        };

        webviewView.webview.onDidReceiveMessage( async message => {
            switch (message.command) {
                case HelpViewCommandIds.VIEW_EXPORT_LOGS:
                    await getService(WebviewCoordinator.id).showExportLogs();
                    break;
                
                default:
                    getLogger().warn(`Received unexpected message ${ message.command }`);
                    break;
            }
          },
        );
        let contactSalesLink = await this.getContactSalesLink();
        webviewView.webview.html = this.getHtmlForWebview(contactSalesLink);
    }

    onRegistrationComplete(): Promise<void> {
        if (this.view) {
            // eslint-disable-next-line @typescript-eslint/no-floating-promises
            this.resolveWebviewView(this.view);
        }

        return Promise.resolve();
    }

    async getContactSalesLink(): Promise<string> {
        const licenseService = await getService(ControllerClientService.id).getLicenseServiceClient();
        let emailField = "";
        try {
            let registrationInfo = await licenseService.getRegistrationInfo(new GetRegistrationInfoRequest());
            let emailAddress = registrationInfo.getEmailaddress();
            
            if (emailAddress !== "") {
                emailField = `&utm_term=${emailAddress}`;
            }
        } catch (error) {
            getLogger().warn(`getRegistrationInfo call resulted in an error, err=${error}`);
        }
        
        return `https://www.blackduck.com/code-sight/contact-sales.html?utm_medium=referral&utm_source=Trial-MKTPLC_VSCode`;
    }

    async getExportLogs(): Promise<void>{
        await getService(WebviewCoordinator.id).showExportLogs();
    }

    public getHtmlForWebview(contactSalesLink: string): string {
        return `<html>
                    <style>
                        ${ this.getStyle() }
                    </style>
                    <body class='fixedView'>
                        <div>
                            <a href="${DOC_APP_ADDRESS}">${localize('code.sight.help.view.documentation.link', 'Code Sight Documentation')}</a>
                            <img class='link-icon float-left' width="18" height="18"/>
                        </div>
                        <div>
                            <a href="${SUPPORT_ADDRESS}">${localize('code.sight.help.view.community.Portal.link', 'Community Support')}</a>
                            <img class='link-icon float-left' width="18" height="18"/>
                        </div>
                        <div>
                            <a href="${contactSalesLink}">${localize('code.sight.help.contact.sales.link', 'Contact Us')}</a>
                            <img class='link-icon float-left' width="18" height="18"/>
                        </div>
                         <div>
                            <a id="${HelpViewCommandIds.VIEW_EXPORT_LOGS}" href="#">${localize("codesight.export.logs", "Export Logs")}</a>
                            <img class='save-icon float-left' width="18" height="18"/>
                        </div>

                    <script>
                    const vscode = acquireVsCodeApi();

                    window.onload = () => {
                        const viewExportLogsLink = document.querySelector("#${HelpViewCommandIds.VIEW_EXPORT_LOGS}")
                        viewExportLogsLink.onclick = () => {
                            vscode.postMessage({
                                command: '${HelpViewCommandIds.VIEW_EXPORT_LOGS}',
                            });
                            return false;
                        };

                    };
                    
                    </script>
                    </body>
                    </html>
        `;
    }

    protected getStyle(): string {
        let linkDark = getIconPath(this.view!.webview, this.extensionUri.fsPath, 'general', 'external-link-dark.svg');
        let linkLight = getIconPath(this.view!.webview, this.extensionUri.fsPath, 'general', 'external-link-light.svg');

        let saveDark = getIconPath(this.view!.webview, this.extensionUri.fsPath, 'general', 'save-dark.svg');
        let saveLight = getIconPath(this.view!.webview, this.extensionUri.fsPath, 'general', 'save-light.svg');
        return `
            div {
                display: flex;
                margin: 5px;
            }

            a {
                margin-right: 5px;
            }

            .vscode-dark .link-icon {
                content:url("${ linkDark.toString() }");
            }

            .vscode-high-contrast .link-icon {
                content:url("${ linkDark.toString() }");
            }

            .vscode-light .link-icon {
                content:url("${ linkLight.toString() }");
            }

            .vscode-dark .save-icon {
                content:url("${ saveDark.toString() }");
            }

            .vscode-high-contrast .save-icon {
                content:url("${ saveDark.toString() }");
            }

            .vscode-light .save-icon {
                content:url("${ saveLight.toString() }");
            }
        `;
    }

    dispose() {
        getService(SetupService.id).removeRegistrationListener(this);
    }
}

export namespace HelpViewCommandIds{
    export const VIEW_EXPORT_LOGS:string  = "view-export-logs";
}