import { Webview } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { ServiceId } from "../../services/serviceContainer";
import { isOSX } from "../../utils/environmentUtils";
import { BUTTON_STYLING, getWebviewHead } from "../../utils/webviewUtils";
import { WebviewProvider } from "../webviewProvider";
import { TableRow } from "./detectConfigurationViewPresenter";

const localize: LocalizeFunc = loadMessageBundle();

export namespace EnvSettingsViewCommandIds {
    export const EDIT_BUTTON = "edit-button";
    export const RESET_BUTTON = "reset-button";
    export const VIEW_STATUS_DIV = "view-status-div";
    export const VIEW_STATUS_ICON = "view-status-icon";
    export const VIEW_STATUS_TEXT = "view-status-text";

    // loading/error/success
    export const SET_CONF_STATUS = "set-conf-status";
}

export abstract class DetectConfigurationViewProvider extends WebviewProvider {
    static readonly id: ServiceId<DetectConfigurationViewProvider> = { id: DetectConfigurationViewProvider.name };

    abstract initHtml(configurationData: TableRow[]): void;

    abstract dispose(): Promise<void>;
}

export class DetectConfigurationViewProviderImpl extends DetectConfigurationViewProvider {
    /**
     * Tabulator uses Ctrl + c as copy key for OSX
     * in other OSX applications the copy key is command + c
     * that is why we are changing the copy binding for OSX
     */
    private getCopyKeyBindings(): string {
        if (isOSX()) {
            return "meta + 67";
        }
        return "ctrl + 67";
    }

    public initHtml(configurationData: TableRow[]): void {
        let tabulatorCss = this.getNodeModulePath('tabulator-tables', 'dist', 'css', 'tabulator.min.css');
        let tabulatorJs = this.getNodeModulePath('tabulator-tables', 'dist', 'js', 'tabulator.min.js');
        let copyKey = this.getCopyKeyBindings();
        
        let html = `<html>
                    <link href="${tabulatorCss}" rel="stylesheet">
                    <script type="text/javascript" src="${tabulatorJs}"></script>
                    <head>
                        ${ this.head }
                    </head>
                    <style>
                        ${ this.style }
                    </style>
                    <body id="view-wrapper">
                        <div class='box' style="margin-bottom: 13px;">
                            <img class='blackduck-icon float-left' width="28" height="28"/>
                            <h2 class='float-left margin-left'>${ localize('detectConfigView.view.title', 'Rapid Scan SCA Configuration') }</h2>
                        </div>

                        <div>
                            <h3 style="margin-top: 0px;">${localize('detectConfigView.configurePaths.title', 'Configure Paths')}</h3>
                            <p>${localize('detectConfigView.configurePaths.desc.one', 'Code Sight will use the following settings to run the Rapid Scan SCA engine. For more details')}, ${localize('detectConfigView.configurePaths.desc.two', 'please read')} <a href="#">${localize('detectConfigView.configurePaths.desc.three', 'our documentation')}</a>. </p>
                        </div>
                        <div style="width: 70%;" id="configuration-table"></div>

                        <div id="${EnvSettingsViewCommandIds.VIEW_STATUS_DIV}" class="hidden">
                            <img id="${EnvSettingsViewCommandIds.VIEW_STATUS_ICON}" width="16" height="16" />
                            <p id="${EnvSettingsViewCommandIds.VIEW_STATUS_TEXT}"></p>
                        </div>

                        <script>
                            const vscode = acquireVsCodeApi();
                            window.addEventListener('message', event => {
                                const message = event.data;
                                switch (message.command) {
                                    case '${EnvSettingsViewCommandIds.SET_CONF_STATUS}':
                                        this.handleConfStatusState(message.state, message.message);
                                        break;
                                }
                            });

                            function handleConfStatusState(state, messageText) {
                                const statusDiv = document.getElementById("${EnvSettingsViewCommandIds.VIEW_STATUS_DIV}");
                                const statusIcon = document.getElementById("${EnvSettingsViewCommandIds.VIEW_STATUS_ICON}");
                                const statusText = document.getElementById("${EnvSettingsViewCommandIds.VIEW_STATUS_TEXT}");

                                switch (state) {
                                    case "loading":
                                        statusDiv.classList.remove("hidden");
                                        statusIcon.classList.add("spinner-icon");
                                        statusText.innerHTML = messageText;
                                        break;
                                    case "error":
                                        statusDiv.classList.remove("hidden");
                                        statusIcon.classList.remove("spinner-icon");
                                        statusIcon.classList.add("severity-high");
                                        statusText.innerHTML = messageText;
                                        break;
                                    case "success":
                                        statusDiv.classList.add("hidden");
                                        statusIcon.classList.remove("spinner-icon");
                                        statusText.innerHTML = "";
                                        break;
                                }
                            }

                            function pathTooltip(e, cell, onRendered) {
                                return "<div class='tooltip-style'>" + cell.getValue() + "</div>";
                            }

                            function editButtonTooltip(e, cell, onRendered) {
                                return "<div class='tooltip-style'>${localize('detectConfigView.editConf.tooltip', 'Edit Configuration')}</div>";
                            }
            
                            function editButtonFormatter(cell, formatterParams, onRendered) {
                                return "<img style='cursor: pointer;' class='edit-icon' width='16' height='16'>";
                            }

                            function handleEditButtonClick(e, cell) {
                                let data = cell.getData();
                                vscode.postMessage({
                                    command: '${EnvSettingsViewCommandIds.EDIT_BUTTON}',
                                    configType: data.id,
                                });
                            }                
                            
                            function resetButtonFormatter(cell, formatterParams, onRendered) {
                                return "<img style='cursor: pointer;' class='reload-icon' width='16' height='16'>";
                            }

                            function resetButtonTooltip(e, cell, onRendered) {
                                return "<div class='tooltip-style'>${localize('detectConfigView.resetConf.tooltip', 'Reset to Default')}</div>";
                            }

                            function handleResetButtonClick(e, cell) {
                                let data = cell.getData();
                                vscode.postMessage({
                                    command: '${EnvSettingsViewCommandIds.RESET_BUTTON}',
                                    configType: data.id,
                                });
                            }

                            function configFormatter(cell, formatterParams, onRendered) {
                                let path = cell.getValue();
                                if (!path) {
                                    return "<div class='placeholder-style'>${localize('detectConfigView.noConfiguration.placeholderText', '(No path configured)')}</div>";
                                }
                                return "<div>" + path + "</div>";
                            }

                            var table = new Tabulator("#configuration-table", {
                                layout: "fitColumns",
                                movableColumns: false,
                                resizableRows: false,
                                data: ${JSON.stringify(configurationData)},
                                keybindings: {
                                    "copyToClipboard" : "${copyKey}"
                                },
                                clipboard: true,
                                clipboardCopyConfig:{
                                    columnHeaders:false,
                                    columnGroups:false,
                                    rowGroups:false,
                                    columnCalcs:false,
                                    dataTree:true,
                                    formatCells:false
                                },
                                columns: [ //Define Table Columns
                                    {
                                        title: "",
                                        field: "configName",
                                        formatter:"plaintext",
                                        resizable: false,
                                        width: 150,
                                    },
                                    {
                                        title: "${localize('detectConfigView.location.column', 'Location')}",
                                        field: "configPath",
                                        tooltip: pathTooltip,
                                        formatter: configFormatter,
                                        cssClass: "rtl",
                                        resizable: true                                    
                                    },
                                    {
                                        title: "${localize('detectConfigView.edit.column', 'Edit')}",
                                        field: "editButton",
                                        formatter: editButtonFormatter,
                                        cellClick: handleEditButtonClick,
                                        tooltip: editButtonTooltip,
                                        width: 60,
                                        hozAlign:"center"
                                    },
                                    {
                                        title: "${localize('detectConfigView.reset.column', 'Reset')}",
                                        field: "resetButton",
                                        formatter: resetButtonFormatter,
                                        cellClick: handleResetButtonClick,
                                        tooltip: resetButtonTooltip,
                                        width: 80,
                                        hozAlign:"center"
                                    }
                                ],
                            });
                            
                            function handleButtonClick(button) {
                                vscode.postMessage({
                                    command: button.id,
                                });
                            }          

                            window.onresize = function() {
                                table.redraw();
                            };
                        </script>
                    </body>
                    </html>
        `;

        this.webviewPanel!.webview.html = html;
    }

    protected getHead(webview: Webview): string {
        return getWebviewHead("Rapid Scan SCA Configuration view", webview);
    }

    protected getStyle(): string {
        return `
        ${BUTTON_STYLING}

        body {
            display: flex;
            flex-direction: column;
            height: 100vh;
        }
        
        .body-text {
            margin-top: 0px;
            margin-bottom: 7px;
        }

        .tooltip-style {
            color: var(--vscode-editor-background);
        }

        .vscode-dark .placeholder-style {
            color: var(--vscode-editor-inactiveSelectionBackground);
        }

        .vscode-high-contrast .placeholder-style {
            color: var(--vscode-editor-inactiveSelectionBackground);
        }

        .vscode-light .placeholder-style {
            color: var(--vscode-editor-foreground);
        }

        #${EnvSettingsViewCommandIds.VIEW_STATUS_DIV} {
            margin-top: 20px;
            display: flex;
        }

        #${EnvSettingsViewCommandIds.VIEW_STATUS_ICON} {
            margin-right: 5px;
        }

        #${EnvSettingsViewCommandIds.VIEW_STATUS_TEXT} {
            margin-top: 0px;
        }

        .tabulator-row-odd {
            background: var(--vscode-editor-background);
            color: var(--vscode-editor-foreground);
        }

        .tabulator-row.tabulator-row-odd:hover {
            background: var(--vscode-editor-background);
            cursor: default;
        }

        .tabulator-row.tabulator-row-even {
            background: var(--vscode-editor-background);
            color: var(--vscode-editor-foreground);
            filter: brightness(95%);
        }

        .vscode-dark .tabulator-row.tabulator-row-even {
            background: var(--vscode-editor-background);
            color: var(--vscode-editor-foreground);
            filter: brightness(125%);
        }

        .tabulator-row.tabulator-row-even:hover {
            background: var(--vscode-editor-background);
            cursor: default;
        }

        a:link {
            color: var(--vscode-textLink-foreground);
        }

        a:visited {
            color: var(--vscode-textLink-activeForeground);
        }

        a:hover {
            color: var(--vscode-textLink-activeForeground);
        }

        .tabulator .tabulator-header .tabulator-col {
            background: var(--vscode-editor-background);
            color: var(--vscode-editor-foreground);
            filter: brightness(85%);
            border-color: var(--vscode-editorGroup-border);
        }

        .vscode-dark .tabulator .tabulator-header .tabulator-col {
            background: var(--vscode-editor-background);
            color: var(--vscode-editor-foreground);
            filter: brightness(125%);
            border-color: var(--vscode-editorGroup-border);
        }

        .vscode-dark .tabulator .tabulator-header:hover .tabulator-col:hover {
            background: var(--vscode-editor-background);
        }

        .tabulator .tabulator-header:hover .tabulator-col:hover {
            background: var(--vscode-editor-background);
        }

        .tabulator .tabulator-header .tabulator-footer {
            background: var(--vscode-editor-background);
            filter: brightness(85%);
        }

        .tabulator .tabulator-header {
            border-color: var(--vscode-editorGroup-border);
            font-weight: normal;
        }

        .vscode-dark .tabulator .tabulator-footer {
            background: var(--vscode-editor-background);
            filter: brightness(125%);
        }

        .tabulator .tabulator-footer .tabulator-page {
            color: var(--vscode-editor-foreground);
        }

        .tabulator {
            background-color: var(--vscode-editor-background);
            border-color: var(--vscode-editorGroup-border);
        }

        .tabulator-row .tabulator-cell {
            border-color: var(--vscode-editorGroup-border);
        }

        .tabulator-row:last-of-type {
            border-bottom: 1px solid;
            border-color: var(--vscode-editorGroup-border);
        }

        `;
    }

    dispose(): Promise<void> {
        return this.webviewPanel?.dispose();
    }
}