import { ConfiguredSource, RemoteReference } from '@codesight/codesight-controller-proto/controller_proto/v0/config_pb';
import { ScanConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/scan_config_pb";
import { ServerType } from '@codesight/codesight-controller-proto/controller_proto/v0/server_info_pb';
import { IssueDiffValue } from '@codesight/codesight-controller-proto/controller_proto/v1/issues_service_pb';

export function getServerName(type: ServerType): string {
    switch (type) {
        case ServerType.POLARIS:
            return "Polaris";
        case ServerType.SOFTWARERISKMANAGER:
            return "Software Risk Manager (SRM)";
        case ServerType.BLACKDUCKHUB:
            return "Black Duck SCA";
        case ServerType.COVERITYCONNECT:
            return "Coverity Connect";
        case ServerType.COVERITYONPOLARIS:
            return "Coverity on Polaris";
        default:
            return "Unsupported Server Type";
    }
}

export function getScanTypeName(type: ScanConfig.ScanType.Type): string {
    switch (type) {
        case ScanConfig.ScanType.Type.POLARIS:
            return "Polaris";
        case ScanConfig.ScanType.Type.BLACKDUCK:
            return "Black Duck SCA";
        case ScanConfig.ScanType.Type.SIGMA:
            return "Rapid Scan Static";
        case ScanConfig.ScanType.Type.COVERITY:
        case ScanConfig.ScanType.Type.COVERITYCLI:
            return "Coverity Connect";
        case ScanConfig.ScanType.Type.SIGNAL:
            return "Signal";
        default:
            return "Unsupported Scan Type";
    }
}

export function getServerShortName(type: ServerType): string {
    if (ServerType.SOFTWARERISKMANAGER === type) {
        return "SRM";
    }
    return getServerName(type);
}

export function isLocalViewFilteringSupported(type: ScanConfig.ScanType.Type, isAutoMode?: boolean): boolean{
    if (isAutoMode) {
        return false;
    }
    switch(type){
        case ScanConfig.ScanType.Type.POLARIS:
            return true;
        default:
            return false;
    }
}

export function isLocalViewOwnerFilteringSupported(type: ScanConfig.ScanType.Type): boolean{
    switch(type){
        case ScanConfig.ScanType.Type.POLARIS:
            return true;
        default:
            return false;
    }
}

export function isTeamViewFilteringSupported(type: ServerType): boolean{
    switch(type){
        case ServerType.POLARIS:
        case ServerType.SOFTWARERISKMANAGER:
        case ServerType.COVERITYCONNECT:
            return true;
        default:
            return false;
    }
}

export function isOwnerFilteringSupported(type: ServerType): boolean{
    switch(type){
        case ServerType.POLARIS:
        case ServerType.COVERITYCONNECT:
            return true;
        default:
            return false;
    }
}

export function getSourceDisplayString(configuredSource: ConfiguredSource): string {
    return getRemoteReferenceDisplayString(configuredSource.getSource()?.getReference());
}

export function getRemoteReferenceDisplayString(reference: RemoteReference | undefined): string {
    if (!reference) {
        return "";
    }

    let result = [];
    result.push(reference.getInfo()?.getDisplayname());
    while (reference!.getParent() !== undefined) {
        let parent: RemoteReference = reference.getParent()!;
        result.push(parent.getInfo()?.getDisplayname());
        reference = parent;
    }

    result = result.reverse();
    return result.join(" > ");
}

export function getDiffSourceDisplayString(diffSource: IssueDiffValue | undefined): string {
    switch (diffSource) {
        case IssueDiffValue.NEW:
            return "New";
        case IssueDiffValue.FIXED:
            return "Absent";
        case IssueDiffValue.ALL:
        default:
            return "All";
    }

}
