import { TelemetryConfig, UserConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/config_pb";
import { GetConfigurationRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/configuration_service_pb";
import { TrackRequest, UpdateTelemetryConfigRequest, UpdateTelemetryConfigResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/telemetry_service_pb";
import * as vscode from "vscode";
import { ConfigurationTarget } from "vscode";
import { CODESIGHT_TELEMETRY_CONFIGURATION_KEY, ENV_CODESIGHT_DESKTOP_TELEMETRY_DISABLED } from "../utils/constants";
import { isFeatureFlagEnabled } from "../utils/environmentUtils";
import { getLogger } from "../utils/logger";
import { stringToBoolValue } from "../utils/stringUtils";
import { AnalysisContextService } from "./analysisContextService";
import { ControllerClientService } from "./controllerClientService";
import { InfoMessageService } from "./extensionMessageService";
import { ServiceId, getService } from "./serviceContainer";

export abstract class TelemetryService {
    static readonly id: ServiceId<TelemetryService> = { id: TelemetryService.name };

    abstract init(): Promise<void>;

    abstract sendStartupEvent(): void;

    abstract sendUpdateTelemetryEnablementRequest(value: string): Promise<UpdateTelemetryConfigResponse | undefined>;
}

export class TelemetryServiceImpl implements TelemetryService {
    async init(): Promise<void> {
        getLogger().info("Initializing telemetry service");

        if (!isFeatureFlagEnabled(ENV_CODESIGHT_DESKTOP_TELEMETRY_DISABLED)) {
            const userConfig = await this.getUserConfiguration();
            let telemetryEnabled = userConfig?.getTelemetryconfig()?.getTelemetryenabled();	
            if (telemetryEnabled === undefined) {
                // make sure settings config is correct
                await vscode.workspace.getConfiguration(CODESIGHT_TELEMETRY_CONFIGURATION_KEY).
                    update("enablement", false, ConfigurationTarget.Global);
                await this.showTelemetryEnablementUnsetMessage();                
            } else {
                // sync settings config with value from code_sight.json
                await vscode.workspace.getConfiguration(CODESIGHT_TELEMETRY_CONFIGURATION_KEY).
                    update("enablement", telemetryEnabled.getValue(), ConfigurationTarget.Global);
            }		
        }

        vscode.workspace.onDidChangeConfiguration((changeEvent: vscode.ConfigurationChangeEvent) => {
            if (changeEvent.affectsConfiguration(CODESIGHT_TELEMETRY_CONFIGURATION_KEY)) {
                const { enablement } = vscode.workspace.getConfiguration(CODESIGHT_TELEMETRY_CONFIGURATION_KEY);
                getLogger().info(`Code Sight telemetry has been ${enablement ? "enabled" : "disabled"} by the user.`);
                return this.sendUpdateTelemetryEnablementRequest(enablement.toString());
            }
            return Promise.resolve();
        });
    }

    async showTelemetryEnablementUnsetMessage() {
        // don't wait for user selection, since that causes a hang on start up
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        getService(InfoMessageService.id).telemetryEnablementUnsetInfo();
        return Promise.resolve(undefined);
    }

    sendStartupEvent(): void {
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        getService(ControllerClientService.id).getTelemetryServiceClient().then(telemetryService => {
            return telemetryService.track(TrackRequest.Event.STARTUP);
        });
    }

    async sendUpdateTelemetryEnablementRequest(value: string): Promise<UpdateTelemetryConfigResponse> {
        let enabled = stringToBoolValue(value);
        let telemetryConfig: TelemetryConfig;

        const userConfig = await this.getUserConfiguration();            
        if (userConfig != null && userConfig?.hasTelemetryconfig()) {
            telemetryConfig = userConfig!.getTelemetryconfig()!;
        } else {
            telemetryConfig = new TelemetryConfig();
        }        
        telemetryConfig.setTelemetryenabled(enabled);

        let configRequest = new UpdateTelemetryConfigRequest();
        configRequest.setTelemetryconfig(telemetryConfig);
        
        let client = await getService(ControllerClientService.id).getTelemetryServiceClient();
        return await client.updateTelemetryConfig(configRequest);
    }

    async getUserConfiguration() : Promise<UserConfig|undefined> {
        let getConfigRequest = new GetConfigurationRequest();
        let contextId = getService(AnalysisContextService.id).getAnalysisContextId();
        getConfigRequest.setContextid(contextId);
    
        let configServiceClient = await getService(ControllerClientService.id).getConfigurationServiceClient();
        let config = await configServiceClient.getConfiguration(getConfigRequest);
        return config.getUserconfig();
    }
}