import { RemoteReference } from "@codesight/codesight-controller-proto/controller_proto/v0/config_pb";
import { Error } from "@codesight/codesight-controller-proto/controller_proto/v0/tool_service_pb";
import { GetIssueSourceStructureResponse } from "@codesight/codesight-controller-proto/controller_proto/v1/issues_service_pb";
import { QuickPickItem } from "vscode";
import { LocalizeFunc, loadMessageBundle } from "vscode-nls";
import { IssueSourceConfigService, SourceType } from "../services/issueSourceConfigService";
import { getService } from "../services/serviceContainer";
import { VsCodeInputService } from "../services/vscodeInputService";
import { getLogger } from "../utils/logger";

const localize: LocalizeFunc = loadMessageBundle();

const loadingText = localize('team.view.issue.source.view.loading.text', 'Loading...');

export type OnSourceSelected = (sourceType: SourceType, issueSource: RemoteReference) => Promise<void>;

export class SourcePicker {
    private onSourceSelected: OnSourceSelected;
    private name: string;

    constructor(name: string, onSourceSelected: OnSourceSelected) {
        this.name = name;
        this.onSourceSelected = onSourceSelected;
    }

    async showConfigurationMenu(sourceType: SourceType) {
        let quickPickItem = getService(VsCodeInputService.id).createQuickPick();
        quickPickItem.title = localize('team.view.issue.source.view.config.menu.title', 'Configure {0}', this.name),
        quickPickItem.busy = true;
        quickPickItem.placeholder = loadingText;
        quickPickItem.selectedItems = [];
		quickPickItem.show();

        try {
            let structure = await getService(IssueSourceConfigService.id).getSourceStructureForServer(sourceType);
            let containerStructure = structure.getContainerstructure();
            let structureDepth = 0;
            while (containerStructure) {            
                structureDepth++;
                containerStructure = containerStructure!.getChild();
            }

            let data: ConfigurationMenuStepData = {
                currentStep: 1,
                totalSteps: structureDepth,
                sourceType: sourceType,
                stepContainer: structure.getContainerstructure(),
                sourceReference: undefined
            };
            await this.showStep(data);
        } catch (error) {
            await this.showErrorMessage(localize('team.view.issue.source.view.error.loading.sources.text', 'Error loading {0}. Please contact support if the problem persists.', this.name), error);
        }
    }

    async showSingleConfigurationStep({title, placeholderText, sourceType}: SingleConfigurationStepData) {
        let quickPickItem = getService(VsCodeInputService.id).createQuickPick();
        quickPickItem.title = title;
        quickPickItem.busy = true;
        quickPickItem.placeholder = loadingText;
        quickPickItem.selectedItems = [];
        quickPickItem.show();

        try {
            let sourceList = await getService(IssueSourceConfigService.id).fetchIssueSourceList(sourceType, undefined);
            let items = this.convertToSourceQuickPick(sourceType, sourceList);
            quickPickItem.items = items;
            quickPickItem.busy = false;
            quickPickItem.placeholder = placeholderText;
            quickPickItem.selectedItems = [];

            quickPickItem.onDidChangeSelection(async selection => {
                if (selection.length === 0) {
                    return;
                }

                let sourceItem: SourceQuickPick =  <SourceQuickPick> selection[0];
                await this.handleConfigurationStep(sourceItem);
            });
        } catch (error) {
            await this.showErrorMessage(localize('team.view.issue.source.view.error.loading.sources.text', 'Error loading {0} branches. Please contact support if the problem persists.', this.name), error);
        }
    }

    async showStep(data: ConfigurationMenuStepData) {
        let quickPickItem = getService(VsCodeInputService.id).createQuickPick();
        quickPickItem.title = localize('team.view.issue.source.view.config.menu.title', 'Configure {0}', this.name);
        quickPickItem.step = data.currentStep;
        quickPickItem.totalSteps = data.totalSteps;
        quickPickItem.busy = true;
        quickPickItem.placeholder = loadingText;
        quickPickItem.selectedItems = [];
		quickPickItem.show();

        try {
            // load the sources
            let sourceList = await getService(IssueSourceConfigService.id).fetchIssueSourceList(data.sourceType, data.sourceReference);
            let items = this.convertToSourceQuickPick(data.sourceType, sourceList);
            quickPickItem.items = items;
            quickPickItem.busy = false;
            quickPickItem.placeholder = data.stepContainer?.getDisplayname();
            quickPickItem.selectedItems = [];

            quickPickItem.onDidChangeSelection(async selection => {
                if (selection.length === 0) {
                    return;
                }

                // configure the source as the last step
                if (data.currentStep === data.totalSteps) {
                    let sourceItem: SourceQuickPick =  <SourceQuickPick> selection[0];
                    await this.handleConfigurationStep(sourceItem, data.currentStep, data.totalSteps);
                } else {
                    // show the next step
                    let sourceItem: SourceQuickPick =  <SourceQuickPick> selection[0];
                    let nextStepData: ConfigurationMenuStepData = {
                        currentStep: data.currentStep + 1,
                        totalSteps: data.totalSteps,
                        sourceType: data.sourceType,
                        stepContainer: data.stepContainer?.getChild(),
                        sourceReference: sourceItem.issueSource
                    };
                    await this.showStep(nextStepData);
                }
            });
        } catch (error) {
            await this.showErrorMessage(localize('team.view.issue.source.view.error.loading.sources.text', 'Error loading {0}. Please contact support if the problem persists.', this.name), error);
        }
    }

    async handleConfigurationStep(sourceItem: SourceQuickPick, currentStep?: number, totalSteps?: number) {
        // show loading screen
        const configLoadingText = localize('team.view.issue.source.view.config.step.loading.text', 'Configuring the selection...');
        let quickPickItem = getService(VsCodeInputService.id).createQuickPick();
        quickPickItem.title = localize('team.view.issue.source.view.config.menu.title', 'Configure {0}', this.name);
        if (currentStep && totalSteps) {
            quickPickItem.step = currentStep;
            quickPickItem.totalSteps = totalSteps;
        }
        quickPickItem.busy = true;
        quickPickItem.placeholder = configLoadingText;
        quickPickItem.selectedItems = [];
        quickPickItem.show();

        try {
            await this.onSourceSelected(sourceItem.sourceType, sourceItem.issueSource);
            quickPickItem.hide();
        } catch (error) {
            await this.showErrorMessage(localize('team.view.issue.source.view.error.configuring.sources.text', 'Error configuring {0}. Please contact support if the problem persists.', this.name), error);
        }
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    async showErrorMessage(errorText: string, error: any) {
        getLogger().warn(`Error loading sources from the server, err=${error}`);

        let errorQuickPick = getService(VsCodeInputService.id).createQuickPick();
        errorQuickPick.title = localize('team.view.issue.source.view.config.menu.title', 'Configure {0}', this.name);
        errorQuickPick.busy = false;
        errorQuickPick.placeholder = localize('team.view.issue.source.view.config.error.menu.placeholder', 'Error');
        errorQuickPick.selectedItems = [];

        errorQuickPick.items = [new ErrorMessage(errorText, error)];
		errorQuickPick.show();
    }

    private convertToSourceQuickPick(sourceType: SourceType, list: RemoteReference[]): SourceQuickPick[] {
        let quickPickItems: SourceQuickPick[] = [];

        list.forEach(item => {
            quickPickItems.push(new SourceQuickPick(sourceType, item));
        });
        
        return quickPickItems;
    }
}

export interface SingleConfigurationStepData {
    title: string;
    placeholderText: string;
    sourceType: SourceType;
}

export interface ConfigurationMenuStepData {
    currentStep: number;
    totalSteps: number;
    sourceType: SourceType;
    stepContainer: GetIssueSourceStructureResponse.SourceContainer | undefined;
    sourceReference: RemoteReference | undefined;
}

export class SourceQuickPick implements QuickPickItem {
    label: string;
    sourceType: SourceType;
    issueSource: RemoteReference;

    constructor(sourceType: SourceType, issueSource: RemoteReference) {
        this.sourceType = sourceType;
        this.label = issueSource.getInfo()?.getDisplayname() ?? "unnamed source"; // should not be displayed
        this.issueSource = issueSource;
    }
}

export class ErrorMessage implements QuickPickItem {
    label: string;
    detail?: string;

    constructor(errorTitle: string, error: any) {
        this.label = `$(alert) ${errorTitle}`;

        if (error instanceof Error) {
            this.detail = `${error.getCode()} ${error.getMessage()}`;
        }
    }
}