import { ScanConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/scan_config_pb";
import { ServerType } from "@codesight/codesight-controller-proto/controller_proto/v0/server_info_pb";
import { Filter, FilterValue, GetIssueFiltersRequest, GetIssueFiltersResponse, GetSearchFilterRequest, IssueDiffValue, NamedFilter, SelectionState, StoreIssueFiltersRequest, StoreIssueFiltersResponse, StoreSearchFilterRequest } from "@codesight/codesight-controller-proto/controller_proto/v1/issues_service_pb";
import { commands } from "vscode";
import { NewIssueSortState, getDefaultNewSortState } from "../models/issueSorting";
import { TEAM_VIEW_SERVER_TYPE_SUPPORTS_MARKERS_AND_ACTIVE_FILE_FILTER } from "../utils/constants";
import { getLogger } from "../utils/logger";
import { convertToConfigSource } from "../utils/protoUtils";
import { AnalysisContextService } from "./analysisContextService";
import { ControllerClientService } from "./controllerClientService";
import { IssueSourceConfigService } from "./issueSourceConfigService";
import { LocalViewIssuesListService, TeamViewIssuesListService } from "./issuesService";
import { LocalScanModeContextService } from "./localScanModeContextService";
import { ScanMode, ScanStatusCoordinator } from "./scanStatusCoordinator";
import { ServiceId, getService } from "./serviceContainer";
import { VscodeContextService } from "./vscodeContextService";

export interface NewIssueListFilterService {
    getSortState(type: ScanConfig.ScanType.Type | ServerType | undefined): NewIssueSortState;
    getCachedFilterState(): NamedFilter | undefined;
    getSearchFilterValue(): string | undefined;
    storeIssueFilters(namedFilters: NamedFilter[], source: ScanConfig.ScanType | ServerType | undefined): Promise<StoreIssueFiltersResponse>
}

//  LOCAL VIEW FILTERS -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
export interface LocalViewFilterState {
    sort: NewIssueSortState | undefined;
    issueDiffSourceFilter: IssueDiffValue | undefined;
    activeFileFilter: boolean;
}

export abstract class LocalViewIssueListFilterServiceListener {
    abstract onFiltersChanged(): Promise<void>;
}

function emptyLocalViewFilterState(): LocalViewFilterState {
    return { sort: undefined, issueDiffSourceFilter: IssueDiffValue.ALL, activeFileFilter: false};
}

const codesightHasLocalViewActiveFileFilter = "codesight.hasLocalViewActiveFileFilter";
export class LocalViewIssueListFilterService implements NewIssueListFilterService {
    static readonly id: ServiceId<LocalViewIssueListFilterService> = { id: LocalViewIssueListFilterService.name };
    protected vscodeContextService = getService(VscodeContextService.id);
    protected searchFilter: { searchValue: string, hint?: string } | undefined;
    private appliedFilters: NamedFilter | undefined;
    protected localViewIssueListFilterServiceListeners: LocalViewIssueListFilterServiceListener[];
    hasFiltersApplied: boolean = false;

    constructor() {
        this.localViewIssueListFilterServiceListeners = [];
    }

    async getSortOptions(): Promise<NewIssueSortState[]> {
        let issueService = getService(LocalViewIssuesListService.id);
        let sortOptions: NewIssueSortState[] = [];
        let options = await issueService.getIssueListStructure();
        options.forEach(option => {
            if (option.getSupportssorting()) {
                sortOptions.push(new NewIssueSortState(option, false));
            }            
        });
        return sortOptions;
    }

    getSortState(scanType?: ScanConfig.ScanType.Type): NewIssueSortState {
        return this.vscodeContextService.getPreservedLocalViewFilterState(scanType)?.sort ?? getDefaultNewSortState();
    }

    async persistSort(sort: NewIssueSortState, scanType?: ScanConfig.ScanType.Type) {
        let sortState = this.vscodeContextService.getPreservedLocalViewFilterState(scanType) ?? emptyLocalViewFilterState();
        sortState.sort = sort;
        return this.persistState(sortState, scanType);
    }

    private async persistState(state: LocalViewFilterState, scanType?: ScanConfig.ScanType.Type) {
        return this.vscodeContextService.preserveLocalViewFilterState(state, scanType);
    }

    getCachedFilterState() {
        return this.appliedFilters;
    }

    getAppliedDiffSourceFilter(scanType?: ScanConfig.ScanType.Type) {
        return this.vscodeContextService.getPreservedLocalViewFilterState(scanType)?.issueDiffSourceFilter ?? IssueDiffValue.ALL;
    }

    async persistDiffSourceFilter(diffSourceFilter: IssueDiffValue, scanType?: ScanConfig.ScanType.Type) {
        let state = this.vscodeContextService.getPreservedLocalViewFilterState(scanType) ?? emptyLocalViewFilterState();
        const previousValue = state.issueDiffSourceFilter;
        state.issueDiffSourceFilter = diffSourceFilter;
        await this.persistState(state, scanType);

          if (previousValue !== state.issueDiffSourceFilter) {
            await this.notifyListenersOnFiltersChanged();
        }
    }

     async resetSearchFilter() {
        const previousValue = this.searchFilter?.searchValue;
        this.searchFilter = undefined;
        await this.storeSearchFilterValue("");

        if (previousValue !== "") {
            await this.notifyListenersOnFiltersChanged();
        }
    }

    async persistSearchFilter(searchValue: string) {
        const previousValue = this.searchFilter?.searchValue;

        this.searchFilter = {
            ...this.searchFilter,
            searchValue: searchValue,
        };
        await this.storeSearchFilterValue(searchValue);

        if (previousValue !== searchValue) {
            await this.notifyListenersOnFiltersChanged();
        }
    }

    private async storeSearchFilterValue(search: string) {
        // store the search filter in controller
        const mode = getService(ScanStatusCoordinator.id).getCurrentScanMode();
        const selectedResultType = await getService(LocalViewIssuesListService.id).getSelectedResultScanType();
        const contextId = getService(AnalysisContextService.id).getAnalysisContextId();
        const issuesServiceClient = await getService(ControllerClientService.id).getIssuesServiceClient();

        let request = new StoreSearchFilterRequest();
        request.setContextid(contextId);
        request.setConfigsource(convertToConfigSource(mode, selectedResultType));
        request.setSearchsetting(search);
        let response = await issuesServiceClient.storeSearchFilter(request);
        if (response.getError() !== undefined) {
            getLogger().warn(`storeSearchFilter() failed with error code ${response.getError()?.getCode()}: ${response.getError()?.getMessage()}`);
        }
        return response;
    }

    getSearchHintText(): string {
        return this.searchFilter?.hint ?? "";
    }

    getSearchFilterValue(): string | undefined {
        return this.searchFilter?.searchValue;
    }

    getHasFiltersApplied(): boolean {
        return this.hasFiltersApplied;
    }

    async loadSearchFilter() {
        const mode = getService(ScanStatusCoordinator.id).getCurrentScanMode();
        const selectedResultType = await getService(LocalViewIssuesListService.id).getSelectedResultScanType();
        const contextId = getService(AnalysisContextService.id).getAnalysisContextId();
        const issuesServiceClient = await getService(ControllerClientService.id).getIssuesServiceClient();
        
        let request = new GetSearchFilterRequest();
        request.setContextid(contextId);
        request.setConfigsource(convertToConfigSource(mode, selectedResultType));
        let response = await issuesServiceClient.getSearchFilter(request);
        if (response.getError() !== undefined) {
            getLogger().warn(`storeSearchFilter() failed with error code ${response.getError()?.getCode()}: ${response.getError()?.getMessage()}`);
            return;
        }

        this.searchFilter = { searchValue: response.getSearchsetting(), hint: response.getHinttext() };
    }

    addListener(listener: LocalViewIssueListFilterServiceListener) {
        this.localViewIssueListFilterServiceListeners.push(listener);
    }

    removeListener(listener: LocalViewIssueListFilterServiceListener) {
        let index = this.localViewIssueListFilterServiceListeners.indexOf(listener);
        if (index >= 0) {
            this.localViewIssueListFilterServiceListeners.splice(index, 1);
        }
    }

    async setContextForLocalViewFilters(filters: NamedFilter | undefined) {
        let selectedLocalViewManualScanSource = await getService(LocalViewIssuesListService.id).getSelectedResultScanType(ScanMode.Manual);
        // always show filters icon when a project scan result source is selected, irrespective of whether filters are available for the scan type
        let showFilterIcon: boolean = selectedLocalViewManualScanSource ? true : false;
        await commands.executeCommand("setContext", "codesight.showLocalViewFilter", showFilterIcon);

        let hasFiltersApplied = false;
        if (selectedLocalViewManualScanSource !== undefined && filters) {
            outerloop: for (let f of filters.getFiltersList()) {
                let fk = f.getFilterkind();
                switch (fk) {
                    case Filter.FilterKind.SINGLESELECT:
                    case Filter.FilterKind.MULTISELECT: {
                        hasFiltersApplied = this.getSelectedState(f.getFiltervalueList());
                        if (hasFiltersApplied){
                            break outerloop;
                        }
                        break;
                    }
                    case Filter.FilterKind.TEXT: {
                        for (let textFilterValue of f.getFiltervalueList()) {
                            if (textFilterValue.getValue().trim().length > 0) {
                                hasFiltersApplied = true;
                                break outerloop;
                            }
                        }
                        break;
                    }
                    case Filter.FilterKind.USER: {
                        for (let ufv of f.getFiltervalueList()) {
                            if (ufv.getValue().trim().length > 0) {
                                hasFiltersApplied = true;
                                break outerloop;
                            }
                        }
                        break;
                    }
                    case Filter.FilterKind.MULTISELECTWITHSEARCH: {
                        hasFiltersApplied = this.getSelectedState(f.getFiltervalueList());
                        if (hasFiltersApplied) {
                            break outerloop;
                        }
                        break;
                    }
                }                    
            }   
        }
        this.hasFiltersApplied = hasFiltersApplied;
        await commands.executeCommand("setContext", "codesight.hasLocalViewFiltersApplied", hasFiltersApplied);

        const scanContext = getService(LocalScanModeContextService.id).getCurrentContext();
        const hasActiveFileFilter = scanContext.shouldShowActiveFileFilterUI && this.getActiveFileFilter(selectedLocalViewManualScanSource?.getType());
        await commands.executeCommand("setContext", codesightHasLocalViewActiveFileFilter, hasActiveFileFilter);
    }

    getSelectedState(filter: FilterValue[]): boolean {
        return filter.some(filterValue => {
           if (filterValue.getState() === SelectionState.SELECTED) {
             return true;
           }
           if (filterValue.getChildrenList().length > 0) {
             return this.getSelectedState(filterValue.getChildrenList());
           }
           return false;
         });
    }

    async storeIssueFilters(namedFilters: NamedFilter[], source?: ScanConfig.ScanType): Promise<StoreIssueFiltersResponse> {
        let issuesServiceClient = await getService(ControllerClientService.id).getIssuesServiceClient();
        let request = new StoreIssueFiltersRequest();
        let configSource = convertToConfigSource(ScanMode.Manual, source);
        request.setConfigsource(configSource);
        request.setFiltersList(namedFilters);
        const response = await issuesServiceClient.storeIssueFilters(request);
        if (response.getError() === undefined) {
            this.setAppliedFilters(namedFilters[0]);
            await this.notifyListenersOnFiltersChanged();
        }
        return issuesServiceClient.storeIssueFilters(request);
    }

    setAppliedFilters(namedFilter: NamedFilter | undefined) {
        this.appliedFilters = namedFilter;
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        this.setContextForLocalViewFilters(this.appliedFilters);
    }

    async getIssueFiltersAsync(): Promise<GetIssueFiltersResponse> {
        let issuesServiceClient = await getService(ControllerClientService.id).getIssuesServiceClient();
        let selectedScanType = await getService(LocalViewIssuesListService.id).getSelectedResultScanType(ScanMode.Manual);
        let configSource = convertToConfigSource(ScanMode.Manual, selectedScanType);
        if (!selectedScanType) {
            getLogger().warn("getIssueFilters() called without a selected scan config source");
            return Promise.reject("getIssueFilters() called without a selected scan config source");
        }

        let request = new GetIssueFiltersRequest();
        request.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        request.setConfigsource(configSource);

        return issuesServiceClient.getIssueFilters(request);
    }

    async refreshCachedFilters() {
        await this.loadSearchFilter();
        const selectedScanType = await getService(LocalViewIssuesListService.id).getSelectedResultScanType(ScanMode.Manual);
        if (!selectedScanType) {
            this.setAppliedFilters(undefined);
            return;
        }

        const filtersResponse = await this.getIssueFiltersAsync();
        if (filtersResponse.getError()?.getCode() === 501) {
            // refreshing filters for an unsupported server type
            this.setAppliedFilters(undefined);
        } else if (filtersResponse.getError() !== undefined) {
            getLogger().warn(`refreshFilters() failed with error code ${filtersResponse.getError()?.getCode()}: ${filtersResponse.getError()?.getMessage()}`);
            // preserve the current filters
            // eslint-disable-next-line @typescript-eslint/no-floating-promises
            this.setContextForLocalViewFilters(undefined);
            return;
        }

        const filters = filtersResponse.getFiltersList();
        if (filters.length > 0) {
            this.setAppliedFilters(filters[0]);
        }
    }

    async notifyListenersOnFiltersChanged() {
        let promises: Promise<void>[] = [];
        this.localViewIssueListFilterServiceListeners.forEach(listener => {
            promises.push(listener.onFiltersChanged());
        });
    }

    getActiveFileFilter(scanType?: ScanConfig.ScanType.Type): boolean {
        return this.vscodeContextService.getPreservedLocalViewFilterState(scanType)?.activeFileFilter ?? false;
    }

    async setActiveFileFilter(enabled: boolean, scanType?: ScanConfig.ScanType.Type): Promise<void> {
        let filterState = this.vscodeContextService.getPreservedLocalViewFilterState(scanType) ?? emptyLocalViewFilterState();
        filterState.activeFileFilter = enabled;
        await this.vscodeContextService.preserveLocalViewFilterState(filterState, scanType);

        const currentManualScanType = await getService(LocalViewIssuesListService.id).getSelectedResultScanType(ScanMode.Manual);
        const scanContext = getService(LocalScanModeContextService.id).getCurrentContext();
        const activeFileFilterActive = scanContext.shouldShowActiveFileFilterUI && this.getActiveFileFilter(currentManualScanType?.getType());
        await commands.executeCommand("setContext", codesightHasLocalViewActiveFileFilter, activeFileFilterActive);
    }
}

//  TEAM VIEW FILTERS -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
export interface TeamViewFilterState {
    sort: NewIssueSortState | undefined;
    activeFileFilter: boolean;
}
function emptyTeamViewFilterState(): TeamViewFilterState {
    return {  sort: undefined, activeFileFilter: false };
}
export abstract class TeamViewIssueListFilterServiceListener {
    abstract onFiltersChanged(): Promise<void>;
}
export class TeamViewIssueListFilterService implements NewIssueListFilterService {
    static readonly id: ServiceId<TeamViewIssueListFilterService> = { id: TeamViewIssueListFilterService.name };
    protected vscodeContextService = getService(VscodeContextService.id);
    protected teamViewIssueListFilterServiceListeners: TeamViewIssueListFilterServiceListener[];
    private appliedFilters: NamedFilter | undefined;

    constructor() {
        this.teamViewIssueListFilterServiceListeners = [];
    }

    async getSortOptions(): Promise<NewIssueSortState[]> {
        let issueService = getService(TeamViewIssuesListService.id);
        let sortOptions: NewIssueSortState[] = [];
        let options = await issueService.getIssueListStructure();
        options.forEach(option => {
            if (option.getSupportssorting() && (option.getId() === 'type' || option.getId() === 'severity')) {
                sortOptions.push(new NewIssueSortState(option, false));
            }
        });
        return sortOptions;
    }

    getSortState(serverType?: ServerType): NewIssueSortState {
        return this.vscodeContextService.getPreservedTeamViewFilterState(serverType!)?.sort ?? getDefaultNewSortState();
    }

    getSearchFilterValue(): string | undefined {
        return; // TODO: add support for search filters in Team view
    }

    async persistSort(sort: NewIssueSortState, serverType: ServerType) {
        let sortState = this.vscodeContextService.getPreservedTeamViewFilterState(serverType) ?? emptyTeamViewFilterState();
        sortState.sort = sort;
        return this.persistState(sortState, serverType);
    }

    addListener(listener: TeamViewIssueListFilterServiceListener) {
        this.teamViewIssueListFilterServiceListeners.push(listener);
    }

    removeListener(listener: TeamViewIssueListFilterServiceListener) {
        let index = this.teamViewIssueListFilterServiceListeners.indexOf(listener);
        if (index >= 0) {
            this.teamViewIssueListFilterServiceListeners.splice(index, 1);
        }
    }

    private async persistState(state: TeamViewFilterState, serverType: ServerType) {
        return this.vscodeContextService.preserveTeamViewFilterState(state, serverType);
    }

    getCachedFilterState() {
        return this.appliedFilters;
    }

    setContextForTeamViewFilters(filters: NamedFilter | undefined) {
        const issueSource = getService(IssueSourceConfigService.id).getSelectedSource();
        let showFilterIcon: boolean = !(filters == undefined || filters.getFiltersList().length == 0);
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        commands.executeCommand("setContext", "codesight.showTeamViewFilter", showFilterIcon);

        // Set active file filter context
        if (issueSource?.serverType) {
            const hasActiveFileFilter = this.getActiveFileFilter(issueSource.serverType);
            // eslint-disable-next-line @typescript-eslint/no-floating-promises
            commands.executeCommand("setContext", "codesight.hasActiveFileFilter", hasActiveFileFilter);
        }

        let hasFiltersApplied = false;
        if (issueSource !== undefined && filters) {
            outerloop: for (let f of filters.getFiltersList()) {
                let fk = f.getFilterkind();
                switch (fk) {
                    case Filter.FilterKind.SINGLESELECT:
                    case Filter.FilterKind.MULTISELECT: {
                        hasFiltersApplied = this.getSelectedState(f.getFiltervalueList());
                        if (hasFiltersApplied){
                            break outerloop;
                        }
                        break;
                    }
                    case Filter.FilterKind.TEXT: {
                        for (let textFilterValue of f.getFiltervalueList()) {
                            if (textFilterValue.getValue().trim().length > 0) {
                                hasFiltersApplied = true;
                                break outerloop;
                            }
                        }
                        break;
                    }
                    case Filter.FilterKind.USER: {
                        for (let ufv of f.getFiltervalueList()) {
                            if (ufv.getValue().trim().length > 0) {
                                hasFiltersApplied = true;
                                break outerloop;
                            }
                        }
                        break;
                    }
                    case Filter.FilterKind.MULTISELECTWITHSEARCH: {
                        hasFiltersApplied = this.getSelectedState(f.getFiltervalueList());
                        if (hasFiltersApplied) {
                            break outerloop;
                        }
                        break;
                    }
                }                    
            }   
        }  
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        commands.executeCommand("setContext", "codesight.hasFiltersApplied", hasFiltersApplied);
    }

    getSelectedState(filter: FilterValue[]): boolean {
        return filter.some(filterValue => {
           if (filterValue.getState() === SelectionState.SELECTED) {
             return true;
           }
           if (filterValue.getChildrenList().length > 0) {
             return this.getSelectedState(filterValue.getChildrenList());
           }
           return false;
         });
     }

    async refreshCachedFilters() {
        const selectedSource = getService(IssueSourceConfigService.id).getSelectedSource();
        if (!selectedSource) {
            this.setAppliedFilters(undefined);
            return;
        }

        const filtersResponse = await this.getIssueFiltersAsync();
        if (filtersResponse.getError()?.getCode() === 501) {
            // refreshing filters for an unsupported server type
            this.setAppliedFilters(undefined);
        } else if (filtersResponse.getError() !== undefined) {
            getLogger().warn(`refreshFilters() failed with error code ${filtersResponse.getError()?.getCode()}: ${filtersResponse.getError()?.getMessage()}`);
            // preserve the current filters
            // eslint-disable-next-line @typescript-eslint/no-floating-promises
            this.setContextForTeamViewFilters(undefined);
            return;
        }

        const filters = filtersResponse.getFiltersList();
        if (filters.length > 0) {
            this.setAppliedFilters(filters[0]);
        }
    }

    async getIssueFiltersAsync(): Promise<GetIssueFiltersResponse> {
        let issuesServiceClient = await getService(ControllerClientService.id).getIssuesServiceClient();
        let selectedSource = getService(IssueSourceConfigService.id).getSelectedSource();
        if (!selectedSource) {
            getLogger().warn("getIssueFilters() called without a selected source");
            return Promise.reject("getIssueFilters() called without a selected source");
        }

        let request = new GetIssueFiltersRequest();
        request.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        request.setServertype(selectedSource.serverType);
        request.setSource(selectedSource.sourceRef.getSource()?.getReference());

        return issuesServiceClient.getIssueFilters(request);
    }

    async storeIssueFilters(namedFilters: NamedFilter[], source?: ServerType): Promise<StoreIssueFiltersResponse> {
        let issuesServiceClient = await getService(ControllerClientService.id).getIssuesServiceClient();
        let request = new StoreIssueFiltersRequest();
        request.setServertype(source!);
        request.setFiltersList(namedFilters);
        const response = await issuesServiceClient.storeIssueFilters(request);
        if (response.getError() === undefined) {
            this.setAppliedFilters(namedFilters[0]);
            await this.notifyListenersOnFiltersChanged();
        }
        return issuesServiceClient.storeIssueFilters(request);
    }

    setAppliedFilters(namedFilter: NamedFilter | undefined) {
        this.appliedFilters = namedFilter;
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        this.setContextForTeamViewFilters(this.appliedFilters);
    }

    async notifyListenersOnFiltersChanged() {
        let promises: Promise<void>[] = [];
        this.teamViewIssueListFilterServiceListeners.forEach(listener => {
            promises.push(listener.onFiltersChanged());
        });
    }

    getActiveFileFilter(serverType: ServerType): boolean {
        if (TEAM_VIEW_SERVER_TYPE_SUPPORTS_MARKERS_AND_ACTIVE_FILE_FILTER.includes(serverType)) {
            return this.vscodeContextService.getPreservedTeamViewFilterState(serverType)?.activeFileFilter ?? false;
        }
        return false;
    }

    async setActiveFileFilter(enabled: boolean, serverType: ServerType): Promise<void> {
        let filterState = this.vscodeContextService.getPreservedTeamViewFilterState(serverType) ?? emptyTeamViewFilterState();
        filterState.activeFileFilter = enabled;
        await this.persistState(filterState, serverType);

        return commands.executeCommand("setContext", "codesight.hasActiveFileFilter", enabled);
    }
}
