import { HttpProxyConfig, ProxyConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/config_pb";
import { GetConfigurationRequest, GetConfigurationResponse, UpdateConfigurationRequest, UserSecrets } from "@codesight/codesight-controller-proto/controller_proto/v0/configuration_service_pb";
import { Disposable, WebviewPanel } from "vscode";
import { LocalizeFunc, loadMessageBundle } from "vscode-nls";
import { ProxyEventService } from "../../services/ProxyEventService";
import { AnalysisContextService } from "../../services/analysisContextService";
import { ControllerClientService } from "../../services/controllerClientService";
import { getService } from "../../services/serviceContainer";
import { WebviewPresenter } from "../webviewPresenter";
import { getLogger } from './../../utils/logger';
import { stringToBoolValue, stringToStringValue, stringToUInt32Value } from "./../../utils/stringUtils";
import { ProxyStatusMessageEnum, ProxyViewCommandIds, ProxyViewProvider } from "./proxyViewProvider";

const MIN_PORT_VALUE = 0;
const MAX_PORT_VALUE = 65535;
const LEN_OF_BR = 4;

const localize: LocalizeFunc = loadMessageBundle();

export type ProxyInfo = {
    noProxy: string,
    systemProxy: string

    httpEnabled: string,
    httpHostname: string,
    httpPort: string,
    httpAuth: string,
    httpUsername: string,
    httpPassword: string,

    httpsEnabled: string,
    httpsHostname: string,
    httpsPort: string,
    httpsAuth: string,
    httpsUsername: string,
    httpsPassword: string,

    bypassList: string
};

let settingsAppliedSuccessfullyText = localize('proxy.settingsAppliedSuccessfully', 'Settings applied successfully');
let somethingWentWrongText = localize('proxy.somethingWentWrong', 'Something went wrong while updating proxy settings');
let savingSettingsText = localize('proxy.savingSettings', 'Saving proxy settings');
let loadingSettingsText = localize('proxy.loadingSettings', 'Loading proxy settings');

export class ProxyViewPresenter extends WebviewPresenter {
    private readonly panel: WebviewPanel;
    private view: ProxyViewProvider;
    private onMessageFromWebviewDisposable: Disposable | undefined;

    constructor(panel: WebviewPanel) {
        super();
        this.panel = panel;
        this.view = getService(ProxyViewProvider.id);
        this.view.initView(this.panel);

        this.registerMessagesFromWebView();
    }

    public async initView() {
        this.view.initHtml();
        await this.getProxyConfigurationInfo();
    }

    public async parseNotification() {
    }

    public dispose() {
        this.onMessageFromWebviewDisposable?.dispose();
    }

    private async getProxyConfigurationInfo() {
        this.setStatusMessage(ProxyStatusMessageEnum.Loading, loadingSettingsText);
        let response = await this.getConfiguration();
        let proxyConfig = response.getUserconfig()?.getProxyconfig();
        if (proxyConfig) {
            let httpConfig = proxyConfig.getHttpproxyconfig();
            let httpsConfig = proxyConfig.getHttpsproxyconfig();

            // set radio buttons
            if (proxyConfig.getNoproxy()?.getValue()){
                this.view.postMessageToWebview({
                    command: ProxyViewCommandIds.SET_NO_PROXY_CHECKBOX,
                    value: 'true',
                });
            } else if (proxyConfig.getUsesystemproxy()?.getValue()){
                this.view.postMessageToWebview({
                    command: ProxyViewCommandIds.SET_SYSTEM_PROXY_CHECKBOX,
                    value: 'true',
                });
            }
            else{
                this.view.postMessageToWebview({
                    command: ProxyViewCommandIds.SET_MANUAL_PROXY_CHECKBOX,
                    value: 'true',
                });
            }

            // set http section
            this.view.postMessageToWebview({
                command: ProxyViewCommandIds.SET_HTTP_VALUES,
                enabled: this.boolToString(httpConfig?.getEnabled()?.getValue()),
                hostname: httpConfig?.getHostname()?.getValue() ?? '',
                port: httpConfig?.getPort()?.getValue().toString() ?? '',
                auth: this.boolToString(httpConfig?.getAuthenticated()?.getValue()),
                username: httpConfig?.getUsername()?.getValue() ?? ''
            });

            // set https section
            this.view.postMessageToWebview({
                command: ProxyViewCommandIds.SET_HTTPS_VALUES,
                enabled: this.boolToString(httpsConfig?.getEnabled()?.getValue()),
                hostname: httpsConfig?.getHostname()?.getValue() ?? '',
                port: httpsConfig?.getPort()?.getValue().toString() ?? '',
                auth: this.boolToString(httpsConfig?.getAuthenticated()?.getValue()),
                username: httpsConfig?.getUsername()?.getValue() ?? ''
            });

            // set https section
            this.view.postMessageToWebview({
                command: ProxyViewCommandIds.SET_BYPASS_LIST,
                value: proxyConfig.getBypasshosts()?.getValue() ?? ''
            });
        } else {
            // set by default
            this.view.postMessageToWebview({
                command: ProxyViewCommandIds.SET_SYSTEM_PROXY_CHECKBOX,
                value: 'true',
            });
        }

        this.clearStatusMessage();
    }

    private registerMessagesFromWebView() {
        this.onMessageFromWebviewDisposable = this.view.onMessageFromWebview(async message => {
            switch (message.command) {
                case ProxyViewCommandIds.SAVE_SETTINGS:
                    let proxyInfo: ProxyInfo = {
                        noProxy: message.noProxy,
                        systemProxy: message.systemProxy,

                        httpEnabled: message.httpEnabled.toString(),
                        httpHostname: message.httpHostname,
                        httpPort: message.httpPort,
                        httpAuth: message.httpAuth.toString(),
                        httpUsername: message.httpUsername,
                        httpPassword: message.httpPassword,

                        httpsEnabled: message.httpsEnabled.toString(),
                        httpsHostname: message.httpsHostname,
                        httpsPort: message.httpsPort,
                        httpsAuth: message.httpsAuth.toString(),
                        httpsUsername: message.httpsUsername,
                        httpsPassword: message.httpsPassword,

                        bypassList: message.bypassList

                    };

                    await this.saveSettings(proxyInfo);
                    break;
                default:
                    return;
            }
        });
    }

    private async saveSettings(message: ProxyInfo) {
        this.setStatusMessage(ProxyStatusMessageEnum.Loading, savingSettingsText);

        let httpConfig: HttpProxyConfig | undefined = new HttpProxyConfig();
        httpConfig.setEnabled(stringToBoolValue(message.httpEnabled));
        httpConfig.setHostname(stringToStringValue(message.httpHostname));
        if (message.httpPort !== '') {
            let portValue = stringToUInt32Value(message.httpPort);
            // Fix bug with big numbers causing extension to crash
            if (portValue.getValue() < MIN_PORT_VALUE || portValue.getValue() > MAX_PORT_VALUE) {
                portValue.setValue(0);
            }
            httpConfig.setPort(portValue);
        }
        httpConfig.setAuthenticated(stringToBoolValue(message.httpAuth));
        httpConfig.setUsername(stringToStringValue(message.httpUsername));

        if (httpConfig.getHostname()?.getValue() === "" &&
            httpConfig.getUsername()?.getValue() === "" &&
            httpConfig.getPort() === undefined &&
            !httpConfig.getEnabled()?.getValue() &&
            !httpConfig.getAuthenticated()?.getValue()) {
            httpConfig = undefined;
        }

        let httpsConfig: HttpProxyConfig | undefined = new HttpProxyConfig();
        httpsConfig.setEnabled(stringToBoolValue(message.httpsEnabled));
        httpsConfig.setHostname(stringToStringValue(message.httpsHostname));
        if (message.httpsPort !== '') {
            let portValue = stringToUInt32Value(message.httpsPort);
            // Fix bug with big numbers causing extension to crash
            if (portValue.getValue() < MIN_PORT_VALUE || portValue.getValue() > MAX_PORT_VALUE) {
                portValue.setValue(0);
            }
            httpsConfig.setPort(portValue);
        }
        httpsConfig.setAuthenticated(stringToBoolValue(message.httpsAuth));
        httpsConfig.setUsername(stringToStringValue(message.httpsUsername));

        if (httpsConfig.getHostname()?.getValue() === "" &&
            httpsConfig.getUsername()?.getValue() === "" &&
            httpsConfig.getPort() === undefined &&
            !httpsConfig.getEnabled()?.getValue() &&
            !httpsConfig.getAuthenticated()?.getValue()) {
            httpsConfig = undefined;
        }

        let proxyConfig = new ProxyConfig();
        proxyConfig.setNoproxy(stringToBoolValue(message.noProxy));
        proxyConfig.setUsesystemproxy(stringToBoolValue(message.systemProxy));
        proxyConfig.setBypasshosts(stringToStringValue(message.bypassList));
        proxyConfig.setHttpproxyconfig(httpConfig);
        proxyConfig.setHttpsproxyconfig(httpsConfig);

        let userSecrets = new UserSecrets();
        userSecrets.setHttpproxypassword(message.httpPassword);
        userSecrets.setHttpsproxypassword(message.httpsPassword);

        let errorMessage = await this.setConfiguration(proxyConfig, userSecrets);
        if (errorMessage === "") {
            this.setStatusMessage(ProxyStatusMessageEnum.Success, settingsAppliedSuccessfullyText);
        } else {
            this.setStatusMessage(ProxyStatusMessageEnum.Error, errorMessage);
        }

        getService(ProxyEventService.id).emitChanges();
    }

    private async getConfiguration(): Promise<GetConfigurationResponse> {
        let configService = await getService(ControllerClientService.id).getConfigurationServiceClient();

        let request = new GetConfigurationRequest();
        let analysisContextService = getService(AnalysisContextService.id);
        request.setContextid(analysisContextService.getAnalysisContextId());

        return configService.getConfiguration(request);
    }

    /**
     * 
     * @param userConfig 
     * @param userSecrets 
     * @returns string with error messages, empty if no messages exist
     */
    private async setConfiguration(proxyConfig: ProxyConfig, userSecrets: UserSecrets): Promise<string> {
        let configService = await getService(ControllerClientService.id).getConfigurationServiceClient();

        let getResponse = await this.getConfiguration();
        if (getResponse.getError()) {
            return somethingWentWrongText;
        }

        let userConfig = getResponse.getUserconfig();
        userConfig?.setProxyconfig(proxyConfig);

        let request = new UpdateConfigurationRequest();
        request.setUserconfig(userConfig);
        request.setUsersecrets(userSecrets);

        let updateResponse;
        try {
            updateResponse = await configService.updateConfiguration(request);
        } catch (e) {
            getLogger().error(e);
            return somethingWentWrongText;
        }

        let errorMessage = "";
        for (let error of updateResponse.getErrorList()) {
            errorMessage += `${error.getMessage()}<br>`;
        }

        return errorMessage.length > 0 ? errorMessage.substring(0, errorMessage.length - LEN_OF_BR) : "";
    }

    private setStatusMessage(status: ProxyStatusMessageEnum, message: string) {
        this.view.postMessageToWebview({
            command: ProxyViewCommandIds.SET_STATUS_MESSAGE,
            status: status,
            message: message
        });
    }

    private clearStatusMessage() {
        this.view.postMessageToWebview({
            command: ProxyViewCommandIds.CLEAR_STATUS_MESSAGE
        });
    }

    private boolToString(value: boolean | undefined): string {
        return value ? 'true' : 'false';
    }
}