import { FileScanInfo, RefreshResultsRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_service_pb";
import { LicensedToolsConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/licensed_tools_config_pb";
import { ScanConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/scan_config_pb";
import { ConfigSource } from "@codesight/codesight-controller-proto/controller_proto/v1/issues_service_pb";
import { ScanMode } from "../services/scanStatusCoordinator";

export function convertToScanSource(mode: ScanMode) {
    if (mode === ScanMode.Auto) {
        return FileScanInfo.Source.AUTO;
    }

    return FileScanInfo.Source.MANUAL;
}

export function convertToConfigSource(mode: ScanMode, scanType: ScanConfig.ScanType | undefined): ConfigSource {
    const configSource = new ConfigSource();
    configSource.setSource(convertToScanSource(mode));
    if (mode === ScanMode.Manual || scanType !== undefined) {
        configSource.setScantype(scanType);
    }
    //TODO consider adding config source scantype if scan type is undefined (for coverity / prescan settings)

    return configSource;
}

export function convertToLicensedToolType(scanType: ScanConfig.ScanType.Type): LicensedToolsConfig.Type {
    switch (scanType) {
        case ScanConfig.ScanType.Type.BLACKDUCK:
            return LicensedToolsConfig.Type.BLACKDUCK;
        case ScanConfig.ScanType.Type.COVERITY:
            return LicensedToolsConfig.Type.COVERITY;
        case ScanConfig.ScanType.Type.POLARIS:
            return LicensedToolsConfig.Type.BRIDGE;
        case ScanConfig.ScanType.Type.SIGMA:
            return LicensedToolsConfig.Type.SIGMA;
        case ScanConfig.ScanType.Type.UNSPECIFIED:
            return LicensedToolsConfig.Type.UNKNOWN;
        case ScanConfig.ScanType.Type.COVERITYCLI:
            return LicensedToolsConfig.Type.COVERITY;
        case ScanConfig.ScanType.Type.SIGNAL:
            return LicensedToolsConfig.Type.SIGNAL;
    }
}

export function convertToRefreshResultsTier(scanMode: ScanConfig.ScanMode.Mode): RefreshResultsRequest.Tier {
    switch (scanMode) {
        case ScanConfig.ScanMode.Mode.ACTIVEFILE:
            return RefreshResultsRequest.Tier.FAST;
        case ScanConfig.ScanMode.Mode.FULLSCOPE:
            return RefreshResultsRequest.Tier.FULL;
        default:
            return RefreshResultsRequest.Tier.FULL;
    }
}