import * as toolServiceClientGrpc from "@codesight/codesight-controller-proto/controller_proto/v0/tool_service_grpc_pb";
import { GetGitInfoRequest, GetGitInfoResponse, GetInstalledToolsRequest, GetInstalledToolsResponse, GitRepoHasChangedFilesRequest, GitRepoHasChangedFilesResponse, ModifyToolInstallationsRequest, ModifyToolInstallationsResponse, SetupToolRequest, SetupToolResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/tool_service_pb";
import { credentials } from '@grpc/grpc-js';
import { getGrpcLimit } from '../utils/environmentUtils';

export interface ToolServiceClient {
    setupTools(request: SetupToolRequest): Promise<SetupToolResponse>;

    updateTools(request: SetupToolRequest): Promise<SetupToolResponse>;

    getInstalledTools(request: GetInstalledToolsRequest): Promise<GetInstalledToolsResponse>;

    modifyToolInstallations(request: ModifyToolInstallationsRequest) : Promise<ModifyToolInstallationsResponse>;

    getGitInfo(request: GetGitInfoRequest): Promise<GetGitInfoResponse>;

    gitRepoHasChangedFiles(request: GitRepoHasChangedFilesRequest): Promise<GitRepoHasChangedFilesResponse>;
}

export class ToolServiceClientImpl implements ToolServiceClient {
    private client: toolServiceClientGrpc.ToolServiceClient;

    constructor(connectionAddress: string) {
        this.client = new toolServiceClientGrpc.ToolServiceClient(connectionAddress, credentials.createInsecure(), {'grpc.max_receive_message_length': getGrpcLimit(), 'grpc.enable_http_proxy': 0});
    }

    async setupTools(request: SetupToolRequest): Promise<SetupToolResponse> {
        return new Promise<SetupToolResponse>((resolve, reject) => {
            this.client.setupTool(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }

    async updateTools(request: SetupToolRequest): Promise<SetupToolResponse> {
        return new Promise<SetupToolResponse>((resolve, reject) => {
            this.client.updateTool(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }

    async getInstalledTools(request: GetInstalledToolsRequest): Promise<GetInstalledToolsResponse> {
        return new Promise<GetInstalledToolsResponse>((resolve, reject) => {
            this.client.getInstalledTools(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }

    async modifyToolInstallations(request: ModifyToolInstallationsRequest) : Promise<ModifyToolInstallationsResponse>{
        return new Promise<ModifyToolInstallationsResponse>((resolve, reject) => {
            this.client.modifyToolInstallations(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }

    async getGitInfo(request: GetGitInfoRequest): Promise<GetGitInfoResponse> {
        return new Promise<GetGitInfoResponse>((resolve, reject) => {
            this.client.getGitInfo(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }

    async gitRepoHasChangedFiles(request: GitRepoHasChangedFilesRequest): Promise<GitRepoHasChangedFilesResponse> {
        return new Promise<GitRepoHasChangedFilesResponse>((resolve, reject) => {
            this.client.gitRepoHasChangedFiles(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }
}