import * as issue_pb from "@codesight/codesight-controller-proto/controller_proto/v0/issue_pb";
import { basename } from "path";
import { MarkdownString } from "vscode";
import { LocalizeFunc, loadMessageBundle } from "vscode-nls";
import { NewEvent, NewIssue } from "../models/newIssue";
import { MARKDOWN_DBL_NEWLINE, MARKDOWN_NEWLINE, MARKDOWN_SPACE, getIconMarkdown } from "../utils/markdownUtils";
import { severityLocalizedText } from "../utils/webviewUtils";
import { IssueSelectionService } from "./issueSelectionService";
import { IssuesListIdentifier, LocalViewIssuesListService, TeamViewIssuesListService } from "./issuesService";
import { COMMAND_LOAD_MARKER_DETAILS_ID } from "./markerService";
import { ServiceId, getService } from "./serviceContainer";
import { VscodeContextService } from "./vscodeContextService";

const localize: LocalizeFunc = loadMessageBundle();

const viewIssueDetailsTitle = localize("editor.marker.view.details.link", "View Issue Details");

enum EventDisplayType {
    MAIN_EVENT = "MAIN_EVENT",
    FIRST_NON_MAIN_EVENT = "FIRST_NON_MAIN_EVENT", 
    SUBSEQUENT_NON_MAIN_EVENT = "SUBSEQUENT_NON_MAIN_EVENT"
}

export abstract class TooltipGenerationService {
    static readonly id: ServiceId<TooltipGenerationService> = { id: TooltipGenerationService.name };

    abstract createIssueHoverMarkdown(issue: NewIssue, isSelected: boolean): MarkdownString;

    abstract getHoverMessageForNewEvents(events: NewEvent[], selectedEvent?: NewEvent): Promise<MarkdownString[]>;

    abstract getHoverMessageForNewEventsMarker(events: NewEvent[], selectedEvent: NewEvent | undefined, selectedIssue: NewIssue): Promise<MarkdownString[]>;

    abstract getHoverMessageForNewEvent(event: NewEvent): Promise<MarkdownString>;

    abstract getHoverMessageForNewEventMarker(event: NewEvent, selectedIssue: NewIssue): Promise<MarkdownString>;
}

export class TooltipGenerationServiceImpl implements TooltipGenerationService {

    createIssueHoverMarkdown(issue: NewIssue, isSelected: boolean): MarkdownString {
        const description = issue.getDescription();
        const markdown = new MarkdownString();

        const severityIcon = issue.getSeverity() ? getIconMarkdown(issue.getIconPathForSeverity(), severityLocalizedText(issue.getSeverity())) : ""; // need to check for issue.getSeverity() as it is not set for license issues
        const issueTitle = `**${issue.getDisplayString().trim()}**`;
        const coverityCID = issue.getCoverityCID();
        let coverityCIDText = coverityCID ? `${localize("editor.markers.coverity.cid", "CID")}: ${coverityCID}&nbsp;` : "";
        if (severityIcon) {
            markdown.appendMarkdown(`${severityIcon}&nbsp;${coverityCIDText}${issueTitle}`);
        } else {
            markdown.appendMarkdown(`${coverityCIDText}${issueTitle}`);
        }
        if (issue.isNewIssue()) {
            markdown.appendMarkdown(` **${localize("editor.marker.new.issue", "(New)")}**`);
            markdown.appendMarkdown(MARKDOWN_NEWLINE);
            markdown.appendMarkdown(localize("editor.marker.new.issue.desc", "Issue found in local codebase only"));
            markdown.appendMarkdown(MARKDOWN_NEWLINE);
        }

        if (issue.isPolicyViolationDetected()) {
           const fixByMarkdown = this.formatFixByDateMarkdown(issue);
           if (issue.isNewIssue()) {
                markdown.appendMarkdown(MARKDOWN_NEWLINE);
           } else {
                markdown.appendMarkdown(MARKDOWN_DBL_NEWLINE);
           }
           markdown.appendMarkdown(fixByMarkdown.value);
           markdown.appendMarkdown(MARKDOWN_NEWLINE);
        }

        markdown.appendMarkdown(MARKDOWN_NEWLINE);
        markdown.appendMarkdown(description);

        if (description !== "") {
            markdown.appendMarkdown(MARKDOWN_NEWLINE);
        }
        
        markdown.appendMarkdown(MARKDOWN_DBL_NEWLINE);
        markdown.appendMarkdown("---");
        markdown.appendMarkdown(MARKDOWN_NEWLINE);
        
        markdown.isTrusted = true;
        if (!isSelected) {
            const commandArg = encodeURIComponent(JSON.stringify([issue.getIssueId()]));
            const commandLink = `[${viewIssueDetailsTitle}](command:${COMMAND_LOAD_MARKER_DETAILS_ID}?${commandArg} "${viewIssueDetailsTitle}")`;
            markdown.appendMarkdown(commandLink);
        }
        return markdown;
    }

    async getHoverMessageForNewEvents(events: NewEvent[], selectedEvent?: NewEvent): Promise<MarkdownString[]> {
        let result: MarkdownString[] = [];
        let hasMultiEventHeader = events.length > 1;

        let promises: Promise<void>[] = [];
        events.forEach(async event => {
            promises.push((async () => {
                if (event.getIdentifier() === selectedEvent?.getIdentifier()) {
                    if (hasMultiEventHeader) {
                        result.splice(0, 0, await this.getHoverMessageForNewEvent(event));
                    } else {
                        result.unshift(await this.getHoverMessageForNewEvent(event));
                    }
                } else {
                    result.push(await this.getHoverMessageForNewEvent(event));
                }
            })());
        });
        await Promise.all(promises);

        return result;
    }

    async getHoverMessageForNewEventsMarker(events: NewEvent[], selectedEvent: NewEvent | undefined, selectedIssue: NewIssue): Promise<MarkdownString[]> {
        if (events.length === 0) {
            return [];
        }

        const result: MarkdownString[] = [];
        const selectedOccurrence = getService(IssueSelectionService.id).getSelectedOccurrence(selectedIssue);
        const mainEventFromSelectedIssue = selectedOccurrence?.getMainEvent();
        
        const mainEventOnThisLine = mainEventFromSelectedIssue && 
            events.some(event => this.isMainEvent(event) && event.getIdentifier() === mainEventFromSelectedIssue.getIdentifier());
        
        if (mainEventFromSelectedIssue) {
            const eventMarkdown = mainEventOnThisLine 
                ? await this.getHoverMessageForNewEventMarker(mainEventFromSelectedIssue, selectedIssue, EventDisplayType.MAIN_EVENT)
                : await this.createMainEventHeaderOnly(mainEventFromSelectedIssue, selectedIssue);
            result.push(eventMarkdown);
        }
        
        const { mainEvents, supportingEvents } = this.separateEventsByType(events, mainEventFromSelectedIssue);
        
        for (const event of mainEvents) {
            const eventMarkdown = await this.getHoverMessageForNewEventMarker(event, selectedIssue, EventDisplayType.MAIN_EVENT);
            result.push(eventMarkdown);
        }
        
        for (let i = 0; i < supportingEvents.length; i++) {
            const displayType = i === 0 ? EventDisplayType.FIRST_NON_MAIN_EVENT : EventDisplayType.SUBSEQUENT_NON_MAIN_EVENT;
            const eventMarkdown = await this.getHoverMessageForNewEventMarker(supportingEvents[i], selectedIssue, displayType);
            result.push(eventMarkdown);
        }
        
        return result;
    }

    private separateEventsByType(events: NewEvent[], excludeMainEvent?: NewEvent): { mainEvents: NewEvent[], supportingEvents: NewEvent[] } {
        const mainEvents: NewEvent[] = [];
        const supportingEvents: NewEvent[] = [];
        
        for (const event of events) {
            if (this.isMainEvent(event)) {
                if (!excludeMainEvent || event.getIdentifier() !== excludeMainEvent.getIdentifier()) {
                    mainEvents.push(event);
                }
            } else {
                supportingEvents.push(event);
            }
        }
        
        return { mainEvents, supportingEvents };
    }

    private isMainEvent(event: NewEvent): boolean {
        return event.getEventType() === issue_pb.Event.Type.MAINEVENT;
    }

    protected createMultiEventHeader(eventCount: number): MarkdownString {
        const markdownString = new MarkdownString('');
        markdownString
            .appendMarkdown(localize("multiple.hover.issues.or.events", "Multiple Issues or Events ({0} total)", eventCount))
            .appendMarkdown(MARKDOWN_NEWLINE);
        return markdownString;
    }

    protected async createMainEventHeaderOnly(mainEvent: NewEvent, selectedIssue: NewIssue): Promise<MarkdownString> {
        let markdown = new MarkdownString(``);
        markdown.isTrusted = true;

        let parentIssue: NewIssue | undefined = mainEvent.getParentIssue();
        let issueType = parentIssue?.getType() ?? "";
        let occurrenceCount = parentIssue?.getEventInfo()?.getContributingDetails()?.length;

        if (parentIssue?.isLicenseAnalysisIssue()) {
            issueType = parentIssue.getLicenseName();
        } else if (parentIssue) {
            markdown.appendMarkdown(getIconMarkdown(parentIssue.getIconPathForSeverity()))
                .appendMarkdown(MARKDOWN_SPACE);
        }

        markdown = this.addCoverityCIDToHeader(markdown, parentIssue);
        
        let issueTitle = localize("editor.hover.issue.header", "{0}", issueType);

        if (occurrenceCount && occurrenceCount > 1) {
            let occurrenceText = ` (${occurrenceCount} ${localize('editor.hover.issue.occurrences.text', 'Occurrences')})`;
            issueTitle += occurrenceText;
        }
        
        markdown.appendMarkdown(MARKDOWN_SPACE)
            .appendMarkdown(`__${issueTitle}__`)
            .appendMarkdown(MARKDOWN_DBL_NEWLINE);
        
        return markdown;
    }

    protected isEventSelected(event: NewEvent, selectedEvent?: NewEvent): boolean {
        return event.getIdentifier() === selectedEvent?.getIdentifier();
    }

    async getHoverMessageForNewEvent(event: NewEvent): Promise<MarkdownString> {
        let listSelection = getService(IssueSelectionService.id).getSelection();
        let contextService = getService(VscodeContextService.id);
        let markdown = new MarkdownString(``);
        markdown.isTrusted = true;

        let isDismissed = false;

        let selectedIssue: NewIssue | undefined;
        let selection = getService(IssueSelectionService.id).getIssuesListSelection(listSelection?.list!);
        if (selection && listSelection?.list === IssuesListIdentifier.TeamViewIssuesList) {
            selectedIssue = await getService(TeamViewIssuesListService.id).getIssue(selection.issueId, selection.displayType);
        } else if (selection && listSelection?.list === IssuesListIdentifier.LocalViewIssuesList) {
            selectedIssue = await getService(LocalViewIssuesListService.id).getIssue(selection.issueId, selection.displayType);
        }
        
        let parentIssue: NewIssue | undefined = event.getParentIssue();

        let isSelectedIssue = selectedIssue !== undefined && selectedIssue.equals(parentIssue);
        let isMainEvent = event.getEventType() === issue_pb.Event.Type.MAINEVENT;

        this.addHoverHeader(markdown, parentIssue, contextService, isSelectedIssue, isDismissed, isMainEvent, event.getEventNumber(), parentIssue.getEventInfo()?.getContributingDetails()?.length);

        const selectedOccurrence = getService(IssueSelectionService.id).getSelectedOccurrence(parentIssue);
        let mainEventDesc = selectedOccurrence?.getMainEvent()?.getEventDescription();
        markdown.appendMarkdown(isMainEvent && mainEventDesc ? mainEventDesc : event.getEventDescription());
        markdown.appendMarkdown(MARKDOWN_DBL_NEWLINE);
        
        return markdown;
    }

    async getHoverMessageForNewEventMarker(event: NewEvent, selectedIssue: NewIssue, eventDisplayType?: EventDisplayType): Promise<MarkdownString> {
        const markdown = new MarkdownString(``);
        markdown.isTrusted = true;

        const parentIssue = event.getParentIssue();
        const isMainEvent = this.isMainEvent(event);
        const displayType = eventDisplayType ?? (isMainEvent ? EventDisplayType.MAIN_EVENT : EventDisplayType.FIRST_NON_MAIN_EVENT);

        this.addMarkerHeader(markdown, parentIssue, displayType, parentIssue?.getEventInfo()?.getContributingDetails()?.length);
        this.addEventDescription(markdown, event, parentIssue, isMainEvent);
        
        return markdown;
    }

    private addHoverHeader(markdown: MarkdownString, parentIssue: NewIssue, contextService: VscodeContextService, isSelectedIssue: boolean, isDismissed: boolean, isMainEvent: boolean, eventNumber?: number, occurrenceCount?: number) {
        let filepath = "";
        let lineNumber = 0;
        let issueType = "";
        const selectedOccurrence = getService(IssueSelectionService.id).getSelectedOccurrence(parentIssue);
        filepath = selectedOccurrence?.getMainEvent()?.getFilePath() ?? "";
        lineNumber = selectedOccurrence?.getMainEvent()?.getEventNumber() ?? 0;
        issueType = parentIssue.getType();

        if (parentIssue.isLicenseAnalysisIssue()) {
            issueType = parentIssue.getLicenseName();
        } else {
            markdown.appendMarkdown(getIconMarkdown(parentIssue.getIconPathForSeverity()))
            .appendMarkdown(MARKDOWN_SPACE);
        }

        markdown = this.addCoverityCIDToHeader(markdown, parentIssue);

        if (isMainEvent) {
            let headerIcon = isDismissed ?
                (isSelectedIssue ? "dismissed-issue-selected.svg" : "dismissed-issue-unselected.svg") :
                (isSelectedIssue ? "issue-selected.svg" : "issue-unselected.svg");

            let issueTitle = localize("editor.hover.issue.header", "ISSUE: {0}", issueType);
            
            if (occurrenceCount && occurrenceCount > 1) {
                let occurrenceText = ` (${occurrenceCount} ${localize('editor.hover.issue.occurrences.text', 'Occurrences')})`;
                issueTitle += occurrenceText;
            }
            markdown.appendMarkdown(getIconMarkdown(contextService.getIconPath(headerIcon, "hover")))
                .appendMarkdown(MARKDOWN_SPACE)
                .appendMarkdown(`__${issueTitle}__`);
        } else {
            markdown.appendMarkdown(getIconMarkdown(contextService.getIconPath(isDismissed ? "dismissed-event.svg" : "event.svg", "hover")))
                .appendMarkdown(MARKDOWN_SPACE)
                .appendMarkdown(localize("editor.hover.event.header", "__EVENT[{0}]: Supporting Event__", eventNumber))
                .appendMarkdown(MARKDOWN_NEWLINE)
                .appendMarkdown(localize("editor.hover.event.assoc.issue", "(for ISSUE - {0}: {1}: {2})",
                    basename(filepath),
                    lineNumber,
                    issueType));
        }
        markdown.appendMarkdown(MARKDOWN_NEWLINE);
    }

    private addMarkerHeader(markdown: MarkdownString, parentIssue: NewIssue | undefined, eventDisplayType: EventDisplayType, occurrenceCount?: number): void {
        if (!parentIssue) return;
        
        if (eventDisplayType === EventDisplayType.MAIN_EVENT) {
            this.addMainEventHeader(markdown, parentIssue, occurrenceCount);
        } else if (eventDisplayType === EventDisplayType.FIRST_NON_MAIN_EVENT) {
            this.addSupportingEventHeader(markdown, parentIssue);
        }
        markdown.appendMarkdown(MARKDOWN_NEWLINE);
    }

    private addMainEventHeader(markdown: MarkdownString, parentIssue: NewIssue, occurrenceCount?: number): void {
        let issueType = parentIssue.getType() ?? "";
        
        if (parentIssue.isLicenseAnalysisIssue()) {
            issueType = parentIssue.getLicenseName();
        } else {
            markdown.appendMarkdown(getIconMarkdown(parentIssue.getIconPathForSeverity()))
                .appendMarkdown(MARKDOWN_SPACE);
        }

        markdown = this.addCoverityCIDToHeader(markdown, parentIssue);
        
        let issueTitle = localize("editor.hover.issue.header", "{0}", issueType);
        if (occurrenceCount && occurrenceCount > 1) {
            issueTitle += ` (${occurrenceCount} ${localize('editor.hover.issue.occurrences.text', 'Occurrences')})`;
        }

        
        markdown.appendMarkdown(MARKDOWN_SPACE).appendMarkdown(`__${issueTitle}__`);
        if (parentIssue.isNewIssue()) {
            markdown.appendMarkdown(` **${localize("editor.marker.new.issue", "(New)")}**`);
            markdown.appendMarkdown(MARKDOWN_NEWLINE);
            markdown.appendMarkdown(localize("editor.marker.new.issue.desc", "Issue found in local codebase only"));
            markdown.appendMarkdown(MARKDOWN_NEWLINE);
        }

        if (parentIssue.isPolicyViolationDetected()) {
            const fixByMarkdown = this.formatFixByDateMarkdown(parentIssue);
            markdown.appendMarkdown(MARKDOWN_NEWLINE);
            markdown.appendMarkdown(fixByMarkdown.value);
        }
    }

    private addSupportingEventHeader(markdown: MarkdownString, parentIssue: NewIssue): void {
        const selectedOccurrence = getService(IssueSelectionService.id).getSelectedOccurrence(parentIssue);
        const filepath = selectedOccurrence?.getFilePath() ?? "";
        const lineNumber = selectedOccurrence?.getLineNumber() ?? 0;
        
        markdown.appendMarkdown(MARKDOWN_NEWLINE)
            .appendMarkdown(localize("editor.hover.event.assoc.issue", "in {0}:{1}", basename(filepath), lineNumber))
            .appendMarkdown(MARKDOWN_DBL_NEWLINE)
            .appendMarkdown(`**${localize("editor.hover.supporting.event", "Supporting event(s):")}**`)
            .appendMarkdown(MARKDOWN_DBL_NEWLINE);
    }

    private addEventDescription(markdown: MarkdownString, event: NewEvent, parentIssue: NewIssue | undefined, isMainEvent: boolean): void {
        const selectedOccurrence = parentIssue
            ? getService(IssueSelectionService.id).getSelectedOccurrence(parentIssue)
            : undefined;
        const mainEventDesc = selectedOccurrence?.getMainEvent()?.getEventDescription();

        if (isMainEvent && mainEventDesc) {
            markdown.appendMarkdown(mainEventDesc).appendMarkdown(MARKDOWN_DBL_NEWLINE);
            return;
        }

        const includeEventLabel = event.getEventType() !== issue_pb.Event.Type.UNDEFINEDEVENTTYPE;
        const eventPrefix = includeEventLabel ? `E[${event.getEventNumber()}]` : `[${event.getEventNumber()}]`;
        const description = `**${eventPrefix}**: ${event.getEventDescription()}`;

        markdown.appendMarkdown(description).appendMarkdown(MARKDOWN_DBL_NEWLINE);
    }

    private formatFixByDateMarkdown(issue: NewIssue): MarkdownString {
        const iconPath = issue.getIconPathForPolicyViolations();
        const iconAlt = localize("policy.violation.detected", "Policy Violation Detected");
        const date = issue.getFixBy();

        let fixByTitle: string;
        if (date) {
            // Format date localized to user's locale
            const formattedDate = date.toLocaleDateString(undefined, {
                month: 'short',
                day: 'numeric',
                year: 'numeric',
                hour: 'numeric',
                minute: '2-digit',
                hour12: true
            });
            fixByTitle = localize("editor.marker.fix.by", "**Fix by:** {0}", formattedDate);
        } else {
            fixByTitle = localize("editor.marker.policy.violation", "**Policy Violation Detected**");
        }

        const iconMarkdown = getIconMarkdown(iconPath, iconAlt, 17);
        return new MarkdownString(`${iconMarkdown}&nbsp;${fixByTitle}`);
    }

    private addCoverityCIDToHeader(markdown: MarkdownString, issue: NewIssue): MarkdownString {
        let coverityCID = issue.getCoverityCID();
        let coverityCIDText = coverityCID ? `${localize("editor.markers.coverity.cid", "CID")}: ${coverityCID}` : "";

        if (coverityCID) {
            markdown.appendMarkdown(coverityCIDText)
                .appendMarkdown(MARKDOWN_SPACE);
        }
        return markdown;
    }
}