import { FileScanInfo, RefreshStatus } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_service_pb";
import { LicensedToolsConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/licensed_tools_config_pb";
import { LocalizeFunc, loadMessageBundle } from "vscode-nls";
import { LocalViewIssuesListService } from "../../services/issuesService";
import { ServiceId, getService } from "../../services/serviceContainer";
import { getScanStatus, isChangedFileScanTier, isRunningState } from "../../utils/fileScanInfoUtils";
import { getFirstContentTitle } from "../../utils/notificationMessageUtils";
import { NotificationViewProviderBase, NotificationViewProviderBaseImpl } from "./notificationViewProviderBase";

const localize: LocalizeFunc = loadMessageBundle();

export abstract class LocalViewScanDetailsProvider extends NotificationViewProviderBase {

    static readonly id: ServiceId<LocalViewScanDetailsProvider> = { id: LocalViewScanDetailsProvider .name };
}

export class LocalViewScanDetailsProviderImpl extends NotificationViewProviderBaseImpl implements LocalViewScanDetailsProvider {
    isScanDetailsView: boolean = true;

    private scanDetailsStatus: RefreshStatus.Status | undefined;
    private scanDetailsInfo: FileScanInfo | undefined;

    async loadState() {
        this.scanDetailsInfo = (await getService(LocalViewIssuesListService.id).getAvailableScanInfos()).selectedScanInfo;
        this.scanDetailsStatus = getScanStatus(this.scanDetailsInfo);
        let logPath = this.scanDetailsInfo?.getScanloginfo()?.getScanlogpath();
        if (logPath) {
            this.scanLogPath = logPath;
        }

        // only use notification message for failure state
        if (this.scanDetailsStatus === RefreshStatus.Status.FAILED) {
            this.notificationMessage = this.scanDetailsInfo?.getNotificationmessage();
        } else {
            this.notificationMessage = undefined;
        }
    }

    getViewTitle(): string {
        let title = "";
        let notificationMessageTitle = "";

        if (this.notificationMessage !== undefined) {
            notificationMessageTitle = getFirstContentTitle(this.notificationMessage);
            if (notificationMessageTitle === "") {
                notificationMessageTitle = this.notificationMessage.getDescription();
            }
        }

        // grab the title from scan info if in Scan Details view
        // otherwise, grab it from the notification message
        switch (this.scanDetailsStatus) {
            case RefreshStatus.Status.QUEUED:
            case RefreshStatus.Status.PREPARING:
            case RefreshStatus.Status.FINALIZING:
            case RefreshStatus.Status.RUNNING:
                title = localize('scan.details.scan.running.title', 'Scan Running');
                break;
            case RefreshStatus.Status.SUCCESS:
                title = localize('scan.details.scan.success.title', 'Scan Successful');
                break;
            case RefreshStatus.Status.CANCELLED:
                title = localize('scan.details.scan.cancelled.title', 'Scan Manually Cancelled');
                break;
            case RefreshStatus.Status.FAILED:
                let scanFailedText = localize('scan.details.scan.failed.title', 'Scan Failed');
                if (!notificationMessageTitle.includes(scanFailedText)) {
                    title = `${scanFailedText}: ${notificationMessageTitle}`;
                } else {
                    title = notificationMessageTitle;
                }
                break;
        }

        return title;
    }

    getViewIcon(): string {
        switch (this.scanDetailsStatus) {
            case RefreshStatus.Status.QUEUED:
            case RefreshStatus.Status.PREPARING:
            case RefreshStatus.Status.FINALIZING:
            case RefreshStatus.Status.RUNNING:
                return "spinner-icon";
            case RefreshStatus.Status.SUCCESS:
                return "success-icon";
            case RefreshStatus.Status.FAILED:
                return "severity-high";
            case RefreshStatus.Status.CANCELLED:
                return "cancel-icon";
            default:
                return "severity-info";
        }
    }

    getViewContent(): string {
        let shouldShowExportLogs = true;
        const isManual = this.scanDetailsInfo?.getScansource() === FileScanInfo.Source.MANUAL;
        const isSignalScan = this.scanDetailsInfo?.getTool()?.getType() === LicensedToolsConfig.Type.SIGNAL;
        let shouldShowScanLogsContent = isManual || isSignalScan || isChangedFileScanTier(this.scanDetailsInfo?.getTier());

        if (this.scanDetailsStatus && isRunningState(this.scanDetailsStatus)) {
            shouldShowExportLogs = false;
        }

        let html = this.getScanDetailsContent(this.notificationMessage?.getAdditionalcontentList()[0], shouldShowScanLogsContent, shouldShowExportLogs);
        
        if (this.notificationMessage !== undefined) {
            // add possible solutions header when in Scan Details view
            html += `<div>
                            <h3>${localize('scan.details.possible.solutions.header', 'Possible Solutions')}:</h3>
                        </div>`;
            html += this.getNotificationMessageContent(this.notificationMessage.getAdditionalcontentList(), 1);
        }

        return html;
    }
}