import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { AuthModel } from "../../models/authModel";
import { ServiceId } from "../../services/serviceContainer";
import { SingleStepAuthViewProviderBase, SingleStepAuthViewProviderBaseImpl } from "./singleStepAuthViewProviderBase";

const localize: LocalizeFunc = loadMessageBundle();

export abstract class SRMSingleStepAuthViewProvider extends SingleStepAuthViewProviderBase {
    static readonly id: ServiceId<SRMSingleStepAuthViewProvider> = { id: SRMSingleStepAuthViewProvider.name };
}

export class SRMSingleStepAuthViewProviderImpl extends SingleStepAuthViewProviderBaseImpl implements SRMSingleStepAuthViewProvider {
    defaultUrl = "";

    protected urlRowForServer(model: AuthModel): string {
        return /*html*/`
            <input style="grid-column: col / span 2; grid-row: row 2;" id="url" type="url" value="${model.getUrl()}" name="url"/>
            <div style="grid-column: col 3; grid-row: row 2;" class="vertical">
            </div>
            <div style="grid-column: col 4 / span 2; grid-row: row 2;">
                ${localize('auth.token.srm.url.desc', 'This should be the base URL as configured by your server administrator. It can be just the URL or it can include additional segments: e.g., https://localhost/srm')}
            </div>`;
    }

    protected tokenDescForServer(): string {
        return `${localize('auth.token.srm.generate.desc', 'To generate a token, open SRM in a Web browser: User Profile > My Settings > Personal Access Tokens > Generate New Token. Name your token, copy and paste it into the token credential field.')}`;
    }
 }