import { RefreshResultsRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_service_pb";
import { GitRepoHasChangedFilesRequest, GitRepoHasChangedFilesResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/tool_service_pb";
import * as path from "path";
import { isChangedFileScanTier } from "../utils/fileScanInfoUtils";
import { getLogger } from "../utils/logger";
import { AnalysisContextService } from "./analysisContextService";
import { ConfigurationService } from "./configurationService";
import { ControllerClientService } from "./controllerClientService";
import { InfoMessageService } from "./extensionMessageService";
import { ScanStatusCoordinator } from "./scanStatusCoordinator";
import { ServiceId, getService } from "./serviceContainer";

/**
 * Service for tracking git repository information per workspace folder.
 * Populated by the GetGitInfo gRPC call during context sync.
 */
export abstract class GitInfoService {
    static readonly id: ServiceId<GitInfoService> = { id: GitInfoService.name };

    /**
     * Returns whether the given folder path is a git repository.
     * Returns undefined if git info has not been fetched yet for this path.
     */
    abstract isGitRepository(folderPath: string): boolean | undefined;

    /**
     * Updates the git repository status for a given folder path.
     */
    abstract setGitRepositoryStatus(folderPath: string, isGitRepo: boolean): void;

    /**
     * Removes the cached git repository status for a given folder path.
     */
    abstract removeGitRepositoryStatus(folderPath: string): void;

    /**
     * Queries the controller for changed files in the current folder's git repository.
     * Returns the response, or undefined if the check fails or the tier is not a changed files scope.
     */
    abstract checkGitRepoForChangedFiles(): Promise<GitRepoHasChangedFilesResponse | undefined>;

    /**
     * Handles a GitRepoHasChangedFilesResponse by showing the appropriate info/warning message.
     * Returns true if the scan should proceed, false if it should be skipped.
     */
    abstract handleGitRepoHasChangedFilesResponse(response: GitRepoHasChangedFilesResponse): Promise<boolean>;
}

export class GitInfoServiceImpl extends GitInfoService {
    private gitRepoStatus: Map<string, boolean> = new Map();

    isGitRepository(folderPath: string): boolean | undefined {
        return this.gitRepoStatus.get(folderPath);
    }

    setGitRepositoryStatus(folderPath: string, isGitRepo: boolean): void {
        this.gitRepoStatus.set(folderPath, isGitRepo);
    }

    removeGitRepositoryStatus(folderPath: string): void {
        this.gitRepoStatus.delete(folderPath);
    }

    async checkGitRepoForChangedFiles(): Promise<GitRepoHasChangedFilesResponse | undefined> {
        try {
            const tier = getService(ScanStatusCoordinator.id).getCurrentScanFileScope();
            if (!isChangedFileScanTier(tier)) {
                return undefined;
            }

            const analysisContext = getService(AnalysisContextService.id).buildAnalysisContext();
            const request = new GitRepoHasChangedFilesRequest();
            request.setContextref(analysisContext.getRef());
            request.setTier(tier);
            request.setProjectrootpath(getService(AnalysisContextService.id).getContextRoot());

            const toolServiceClient = await getService(ControllerClientService.id).getToolServiceClient();
            return toolServiceClient.gitRepoHasChangedFiles(request);
        } catch (error) {
            getLogger().warn(`GitRepoHasChangedFiles check failed: ${error}`);
            return undefined;
        }
    }

    async handleGitRepoHasChangedFilesResponse(response: GitRepoHasChangedFilesResponse): Promise<boolean> {
        const errorCode = response.getErrorcode();
        if (errorCode !== GitRepoHasChangedFilesResponse.ErrorCode.NOERROR) {
            const infoMessageService = getService(InfoMessageService.id);
            const folderName = path.basename(await getService(ConfigurationService.id).getConfiguredGitRepositoryPath() ?? getService(AnalysisContextService.id).getContextRoot());
            switch (errorCode) {
                case GitRepoHasChangedFilesResponse.ErrorCode.REFERENCEBRANCHNOTFOUND:
                    void infoMessageService.referenceBranchNotFound(response.getReferencebranch());
                    return false;
                case GitRepoHasChangedFilesResponse.ErrorCode.NOGITREPOSITORY:
                    void infoMessageService.noGitRepository(folderName);
                    return false;
                case GitRepoHasChangedFilesResponse.ErrorCode.NOCOMMITS:
                    void infoMessageService.noCommits(folderName);
                    return false;
                case GitRepoHasChangedFilesResponse.ErrorCode.REFERENCEBRANCHNOTCONFIGURED:
                    void infoMessageService.referenceBranchNotConfigured();
                    return false;
                case GitRepoHasChangedFilesResponse.ErrorCode.GITERROR:
                default:
                    getLogger().warn(`GitRepoHasChangedFiles check returned error code: ${errorCode}, detail: ${response.getErrordetail()}`);
                    void infoMessageService.gitChangedFilesError(response.getErrordetail());
                    return false;
            }
        }

        if (!response.getHaschangedfiles()) {
            const tier = getService(ScanStatusCoordinator.id).getCurrentScanFileScope();
            if (tier === RefreshResultsRequest.Tier.ALLUNCOMMITTED) {
                void getService(InfoMessageService.id).noChangedFilesUncommitted();
            } else {
                void getService(InfoMessageService.id).noChangedFilesReferenceBranch(response.getReferencebranch());
            }
            return false;
        }

        return true;
    }
}
