import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { Webview } from "vscode";
import { LocalizeFunc, loadMessageBundle } from "vscode-nls";
import { ServiceId } from "../../services/serviceContainer";
import { getError, getTitleFromProblemDetails, getTruststoreLocation } from "../../utils/notificationMessageUtils";
import { BUTTON_STYLING, getWebviewHead } from "../../utils/webviewUtils";
import { WebviewProvider } from "../webviewProvider";

const localize: LocalizeFunc = loadMessageBundle();

export namespace UntrustedCertCommandId {
    export const ACCEPT_BUTTON = "accept-button";
    export const REJECT_BUTTON = "reject-button";

    export const CLEAR_STATUS = "clear-status";
    export const STATUS_IN_PROGRESS = "status-in-progress";
    export const STATUS_FAILED = "status-failed";
}

export abstract class UntrustedCertMessageViewProvider extends WebviewProvider {
    static readonly id: ServiceId<UntrustedCertMessageViewProvider> = { id: UntrustedCertMessageViewProvider.name };

    abstract initHtml(notificationMessage: NotificationMessage): void;

    abstract dispose(): Promise<void>;
}

export class UntrustedCertMessageViewProviderImpl extends UntrustedCertMessageViewProvider {
    public initHtml(notificationMessage: NotificationMessage): void {
        let title = getTitleFromProblemDetails(notificationMessage);
        let html = `<html>
                        <head>
                            ${this.head}
                        </head>
                        <style>
                            ${this.style}
                        </style>
                        <body>
                            ${this.getBodyHtml(notificationMessage, title)}
                            ${this.getScript()}
                        </body>
                    </html>`;


        this.webviewPanel!.title = title;
        this.webviewPanel!.webview.html = html;
    }

    private getBodyHtml(notificationMessage: NotificationMessage, title: string): string {
        let description = notificationMessage.getDescription();
        let certificateError = getError(notificationMessage);
        let contentList = notificationMessage.getAdditionalcontentList();
        let location = getTruststoreLocation(notificationMessage);
        
        let html = `
            <div class='box'>
                <img class='blackduck-icon float-left' width='28' height='28'/>
                <h2 class='float-left margin-left'>${title}</h2>
            </div>
            `;

        html += this.addDescriptionHtml(description, certificateError);
        html += this.addDetailsHtml(contentList);
        html += this.getLocationHtml(location);
        html += this.getStatusHtml();
        html += this.getButtonBarHtml();

        return html;
    }

    private addDetailsHtml(contentList: NotificationMessage.AdditionalContent[]): string {
        let html = `
            <div class="margin-top margin-bottom">
                <span class="text-bold">${localize("untrusted.cert.message.view.details", "Certificate Details:")}</span>
            </div>
            <div>`;

        for (let i = 1; i < contentList.length; i++) {
            let content = contentList[i];
            let contentMap = content.getMetaMap();
            let subcontent = "";
            contentMap.forEach((text: string, key: string) => {
                subcontent += this.addHeaderWithText(key, text, true, true);
            });
            html += this.addHeaderWithText(content.getTitle(), subcontent, false);
        }

        html += `</div>`;

        return html;
    }

    private addDescriptionHtml(description: string, certificateError: string): string {
        let errorText = localize("untrusted.cert.message.description.error", "Error:");
        return `
            <div">
                <p>
                    ${description}
                    <br/>
                    ${this.addHeaderWithText(errorText, certificateError, true)}
                </p>
            </div>`;
    }

    private getLocationHtml(location: string): string {
        let locationText = localize("untrusted.cert.message.view.location", "If accepted, the certificate will be saved in:");
        return `
            <div class="margin-top margin-bottom">
                ${this.addHeaderWithText(locationText, location, true)}
            </div>`;
    }

    private getStatusHtml(): string {
        return `
            <div id="status" class="hidden box margin-top">
                <img id="statusImg" width="15" height="15"/>
                <div class="margin-left"><b id="statusText"></b></div>
            </div>
            `;
    }

    private getButtonBarHtml(): string {
        return `
            <div class="box" id="button-box">
                <button id="${UntrustedCertCommandId.REJECT_BUTTON}" class="button button-small" onclick="handleButtonClick(this); addSpinner(this);" type="button">${localize('untrusted.cert.message.view.reject.button', 'Reject')}</button>
                <button id="${UntrustedCertCommandId.ACCEPT_BUTTON}" class="button button-small" onclick="handleButtonClick(this); addSpinner(this);" type="button">${localize('untrusted.cert.message.view.accept.button', 'Accept')}</button>
            </div>
        `;
    }

    addHeaderWithText(header: string, text: string | undefined, sameLine: boolean, boldedHeader: boolean = true) {
        if (text === "" || text === undefined) {
            return "";
        }
        if (sameLine) {
            return `<div class="margin-left vertical-less-margin center-flex body-text">
                             <div>${boldedHeader ? `<span class="text-bold">${header}</span>` : header}</div>
                            <span style="margin-left:5px;">${text}</span>
                        </div>`;
        }
        return `<div class="margin-left vertical-margin body-text">
                    <div>${boldedHeader ? `<span class="text-bold">${header}</span>` : header}</div>
                    <div class="margin-spaced-text">${text}</div>
                </div>`;

    }

    protected getHead(webview: Webview): string {
        return getWebviewHead("Untrusted Certificate", webview);
    }

    private getScript(): string {
        return `
            <script>
                const vscode = acquireVsCodeApi();

                window.addEventListener('message', event => {
                    const message = event.data;
                    switch (message.command) {
                        case '${UntrustedCertCommandId.STATUS_IN_PROGRESS}':
                            clearStatusMessage();
                            enableButton(false, '${UntrustedCertCommandId.ACCEPT_BUTTON}');
                            enableButton(false, '${UntrustedCertCommandId.REJECT_BUTTON}');
                            break;
                        case '${UntrustedCertCommandId.STATUS_FAILED}':
                            removeSpinner('${UntrustedCertCommandId.ACCEPT_BUTTON}');
                            removeSpinner('${UntrustedCertCommandId.REJECT_BUTTON}');
                            showStatusMessage(message.message, message.command);
                            break;
                    }
                });

                function handleButtonClick(button) {
                    console.log(button.id);
                    vscode.postMessage({
                        command: button.id,
                    });
                }

                function addSpinner(button) {
                    let spinner = "<img class='spinner-icon margin-left' width='20' height='20'>";
                    button.innerHTML += spinner;
                }

                function removeSpinner(id) {
                    const button = document.getElementById(id);
                    if (button.innerHTML.includes("img")) {
                        var buttonHTML = button.innerHTML.split("<img");
                        button.innerHTML = buttonHTML[0]; // set button text again
                    }
                }

                function showStatusMessage(message, type) {
                    let icon;
                    switch (type) {
                        case "${UntrustedCertCommandId.STATUS_FAILED}":
                            icon = "severity-high";
                            break;
                    }
                    document.querySelector("#status").classList.remove('hidden');
                    document.querySelector("#statusText").innerHTML = message;
                    let statusImg = document.querySelector("#statusImg");
                    
                    statusImg.className = "";
                    statusImg.classList.add(icon);
                }

                function clearStatusMessage() {
                    document.querySelector("#status").classList.add('hidden');
                    document.querySelector("#statusText").innerHTML = "";
                    document.querySelector("#statusImg").className = "";
                }

                function enableButton(enable, id) {
                    const button = document.getElementById(id);
                    if (enable === true) {
                        button.classList.remove("button-disabled");
                        button.removeAttribute("disabled");
                    } else {
                        button.classList.add("button-disabled");
                        button.setAttribute("disabled", "");
                    }
                }

            </script>
        `;
    }

    protected getStyle(): string {
        return `
        ${BUTTON_STYLING}

        .center-flex {
            display: flex;
            align-items: center;
            flex-direction: row;
        }
        
        .body-text {
            margin-top: 0px;
            margin-bottom: 7px;
        }

        .box {
            margin-top: 10px;
        }

        .margin-top {
            margin-top: 30px;
        }

        .margin-bottom {
            margin-bottom: 10px;
        }
        
        .margin-left{
            margin-left: 3px;
        }

        .vertical-less-margin {
            margin-top: 5px;
            margin-bottom: 5px;
        }

        .margin-spaced-text{
            margin-top: 5px;
            margin-bottom: 5px;
            margin-left: 10px;
            overflow-wrap: anywhere;
        }

        #status {
            margin-top: 10px;
        }
        `;
    }

    dispose(): Promise<void> {
        return this.webviewPanel?.dispose();
    }
}