import { Webview } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { ServiceId } from "../../services/serviceContainer";
import { BUTTON_STYLING, getWebviewHead } from "../../utils/webviewUtils";
import { WebviewProvider } from "../webviewProvider";

const localize: LocalizeFunc = loadMessageBundle();

export namespace CustomWorkingDirCommandId {
    export const VIEW_APPLY = "apply-button";
    export const VIEW_DIR_CHANGED = "custom-working-dir";
    export const VIEW_BROWSE = "custom-directory-browse";
    
    export const SET_DIR = "set-dir";
    export const SET_STATUS = "set-status";
    export const SET_INITIAL_DIR_PATH = "set-placeholder-dir";
    export const SET_CONTINUE_ENABLED = "continue-enabled";
    export const SET_BROWSE_ENABLED = "browse-enabled";
    export const REMOVE_BUTTON_SPINNER = "remove-continue-button-spinner";

    export const STATUS_LOADING="spin";
    export const STATUS_VALID="valid";
    export const STATUS_INVALID="invalid";
    export const STATUS_CLEAR="clear";
}

export abstract class CustomWorkingDirMessageViewProvider extends WebviewProvider {
    static readonly id: ServiceId<CustomWorkingDirMessageViewProvider> = { id: CustomWorkingDirMessageViewProvider.name };

    abstract initHtml(path: string): void;

    abstract dispose(): Promise<void>;
}

export class CustomWorkingDirMessageViewProviderImpl extends CustomWorkingDirMessageViewProvider {
    public initHtml(path: string): void {
        let html = `<html>
                    <head>
                        ${ this.head }
                    </head>
                    <style>
                        ${ this.style }
                    </style>
                    <body id="view-wrapper">
                        <div class='box' style="margin-bottom: 13px;">
                            <img class='blackduck-icon float-left' width="28" height="28"/>
                            <h2 class='float-left margin-left'>${ localize('custom.working.dir.message.content.title', 'Choose a Working Directory') }</h2>
                        </div>

                        <p class='body-text'>${ localize('custom.working.dir.message.content.body.first', 'Code Sight cannot continue extension startup because it is unable to write to or execute from the working directory.') }</p>
                        <p class='body-text'>${ localize('custom.working.dir.message.content.body.second', 'The working directory is used by Code Sight to store working files as well as logs. Scanning engines are installed to and run from the working directory.') }</p>
                        <p class='body-text'>${ localize('custom.working.dir.message.content.body.third', 'Code Sight needs read, write and execute permissions for the selected working directory.') }</p>
                        <br>
                        <p class='body-text text-bold'>${localize('custom.working.dir.message.content.path.first', 'The currently configured working directory is')}:</p>
                        <p class='body-text'>${path}</p>
                        <br>
                        <p class='body-text'>${ localize('custom.working.dir.message.content.path.second', 'Please select another location to be the working directory:')}</p>

                        <div class="box">
                            <input id="customWorkingDirInput" type="text" value="" name="customWorkingDirInput" placeholder="${path}" readonly>
                            <button id="${CustomWorkingDirCommandId.VIEW_BROWSE}" class="button" onclick="handleButtonClick(this);" type="button">${localize('button.browse', 'Browse')}</label>
                        </div>

                        <div id="status" class="hidden box">
                            <img id="statusImg" width="15" height="15"/>
                            <div class="margin-left"><b id="statusText"></b></div>
                        </div>
                        
                        <div class="box" id="apply-box">
                            <button id="${CustomWorkingDirCommandId.VIEW_APPLY}" class="button button-small button-disabled" onclick="handleButtonClick(this); addSpinner(this);" type="button" disabled>${localize('custom.working.dir.view.apply.button', 'Apply')}</button>
                            <i style="margin-left: 10px;">${localize("custom.working.dir.view.reload.text", "Clicking 'Apply' will update the location and reload your VS Code window")}</i>
                        </div>

                        <script>
                            const vscode = acquireVsCodeApi();
                            window.onload = function() {
                                const fileInputText = document.getElementById('customWorkingDirInput');
                                fileInputText.addEventListener('input', (event)=>{
                                    vscode.postMessage({
                                        command: "${CustomWorkingDirCommandId.VIEW_DIR_CHANGED}",
                                        value: event.target.value,
                                    });
                                });
                            };

                            window.addEventListener('message', event => {
                                const message = event.data;
                                switch (message.command) {
                                    case '${CustomWorkingDirCommandId.SET_DIR}':
                                        const fileInputText = document.getElementById('customWorkingDirInput');
                                        fileInputText.value = message.value;
                                        fileInputText.title = message.value; // tooltip
                                        break;
                                    case '${CustomWorkingDirCommandId.SET_INITIAL_DIR_PATH}':
                                        const customWorkingDirInput = document.getElementById('customWorkingDirInput');
                                        customWorkingDirInput.value = "";
                                        customWorkingDirInput.title = "";
                                        customWorkingDirInput.placeholder = message.value;
                                        break;
                                    case '${CustomWorkingDirCommandId.SET_STATUS}':
                                        showStatusMessage(message.message, message.type);
                                        break;
                                    case '${CustomWorkingDirCommandId.SET_CONTINUE_ENABLED}':
                                        enableButton(message.enabled, '${CustomWorkingDirCommandId.VIEW_APPLY}');
                                        break;
                                    case '${CustomWorkingDirCommandId.SET_BROWSE_ENABLED}':
                                        enableButton(message.enabled, '${CustomWorkingDirCommandId.VIEW_BROWSE}');
                                        break;
                                    case '${CustomWorkingDirCommandId.REMOVE_BUTTON_SPINNER}':
                                        removeSpinner('${CustomWorkingDirCommandId.VIEW_APPLY}');
                                        break;
                                }
                            });

                            function showStatusMessage(message, type) {
                                let icon;
                                switch (type) {
                                    case "${CustomWorkingDirCommandId.STATUS_CLEAR}":
                                        clearStatusMessage();
                                        return;
                                    case "${CustomWorkingDirCommandId.STATUS_LOADING}":
                                        icon = "spinner-icon";
                                        break;
                                    case "${CustomWorkingDirCommandId.STATUS_INVALID}":
                                        icon = "severity-high";
                                        break;
                                    case "${CustomWorkingDirCommandId.STATUS_VALID}":
                                        icon = "success-icon";
                                        break;
                                }
                                document.querySelector("#status").classList.remove('hidden');
                                document.querySelector("#statusText").innerHTML = message;
                                let statusImg = document.querySelector("#statusImg");
                                
                                statusImg.className = "";
                                statusImg.classList.add(icon);
                            }
        
                            function clearStatusMessage() {
                                document.querySelector("#status").classList.add('hidden');
                                document.querySelector("#statusText").innerHTML = "";
                                document.querySelector("#statusImg").className = "";
                            }

                            function enableButton(enable, id) {
                                const button = document.getElementById(id);
                                if (enable === "true") {
                                    button.classList.remove("button-disabled");
                                    button.removeAttribute("disabled");
                                } else {
                                    button.classList.add("button-disabled");
                                    button.setAttribute("disabled", "");
                                }
                            }

                            function handleButtonClick(button) {
                                vscode.postMessage({
                                    command: button.id,
                                });
                            }

                            function addSpinner(button) {
                                let spinner = "<img class='spinner-icon margin-left' width='20' height='20'>";
                                button.innerHTML += spinner;
                            }

                            function removeSpinner(id) {
                                const button = document.getElementById(id);
                                if (button.innerHTML.includes("img")) {
                                    var buttonHTML = button.innerHTML.split("<img");
                                    button.innerHTML = buttonHTML[0]; // set button text again
                                }
                            }

                        </script>
                    </body>
                    </html>
        `;

        this.webviewPanel!.webview.html = html;
    }

    protected getHead(webview: Webview): string {
        return getWebviewHead("Custom Working Directory", webview);
    }

    protected getStyle(): string {
        return `
        ${BUTTON_STYLING}
        
        .body-text {
            margin-top: 0px;
            margin-bottom: 7px;
        }

        #${CustomWorkingDirCommandId.VIEW_BROWSE}{
            background-color: var(--vscode-button-background);
            color: var(--vscode-button-foreground);
            padding: 3px 10px;
            cursor: pointer;
            border-width: 1px;
            border-style: solid;
            border-color: var(--vscode-editor-background);
            margin: 2px 5px;
        }

        #customWorkingDirInput {
            width: 60%;
        }

        #${CustomWorkingDirCommandId.VIEW_BROWSE}:hover {
            background-color: var(--vscode-button-hoverBackground);
        }

        #view-wrapper {
            min-width: 500px;
            max-width: 900px;
        }

        #status {
            margin-top: 10px;
        }

        #apply-box {
            margin-top: 10px;
        }
        `;
    }

    dispose(): Promise<void> {
        return this.webviewPanel?.dispose();
    }
}