import { RefreshResultsRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_service_pb";
import { BoolValue, ValueSource } from "@codesight/codesight-controller-proto/controller_proto/v0/config_types_pb";
import { GetConfigurationRequest, GetConfigurationResponse, UpdateConfigurationRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/configuration_service_pb";
import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { AutoModeSpecificError, AutoScanConfigCommands, AutoScanConfigProps, LicenseAnalysisEnabledState, SignalScanConfigState } from "@webview-model/models/views/autoScanConfigModel";
import { commands, Disposable, WebviewPanel } from "vscode";
import { AnalysisContextService } from "../../services/analysisContextService";
import { CsBrowserService } from "../../services/browserService";
import { ConfigurationService } from "../../services/configurationService";
import { ControllerClientService } from "../../services/controllerClientService";
import { EntitlementService, EntitlementServiceListener } from "../../services/entitlementService";
import { LicenseAnalysisService } from "../../services/licenseAnalysisService";
import { ScanStatusCoordinator } from "../../services/scanStatusCoordinator";
import { ScanToolConfigService } from "../../services/scanToolConfigService";
import { getService } from "../../services/serviceContainer";
import { SignalTimerService } from "../../services/signalTimerService";
import { VscodeContextService } from "../../services/vscodeContextService";
import { DOC_SIGMA_ADDRESS, SIGNAL_DOCUMENTATION_ADDRESS, SNIPPET_ANALYSIS_DOCUMENTATION_ADDRESS } from "../../utils/constants";
import { getLogger } from "../../utils/logger";
import { EDIT_BLACK_DUCK_SERVER_INFO_COMMAND_ID, OPEN_EMAIL_VERIFICATION_MSG_COMMAND_ID, OPEN_INSTALLED_TOOLS_MSG_COMMAND_ID } from "../extension-status/extensionStatusPresenter";
import { WebviewPresenter } from "../webviewPresenter";
import { AutoScanConfigViewProvider } from "./autoScanConfigViewProvider";

const COMPONENT_NAME = "AutoScanConfig";

export class AutoScanConfigViewPresenter implements WebviewPresenter, EntitlementServiceListener {
    private readonly panel: WebviewPanel;
    private view: AutoScanConfigViewProvider;
    private onMessageFromWebviewDisposable: Disposable | undefined;

    constructor(panel: WebviewPanel) {
        this.panel = panel;
        this.view = getService(AutoScanConfigViewProvider.id);
        this.view.initView(this.panel);
        getService(EntitlementService.id).addListener(this);
    }

    public dispose() {
        this.onMessageFromWebviewDisposable?.dispose();
        getService(EntitlementService.id).removeListener(this);
    }

    public async parseNotification(message: NotificationMessage) {
        // no-op
    }

    public async initView() {
        this.view.initLoading();
        let vscodeContextService = getService(VscodeContextService.id);
        let licenseAnalysisEnabledState: LicenseAnalysisEnabledState, sigmaScanOnType: boolean;
        let signalScanConfig = await this.fetchSignalScanConfigState();
        this.onMessageFromWebviewDisposable = this.view.onObjectMessageFromWebview(async message => {
            switch (message.command) {
                // this is called as soon as the react app is initialized
                case 'init':
                    const entitlementErrors = this.getEntitlementErrors();
                    let codeSightScanConfig = await getService(ScanToolConfigService.id).getCodeSightScanConfig();
                    licenseAnalysisEnabledState = vscodeContextService.getPreservedLicenseAnalysisEnabled();
                    sigmaScanOnType = codeSightScanConfig.sigma.sigmaAnalyzeOnChange;
                    this.view.postObjectMessageToWebview({
                        command: 'loadComponent',
                        component: COMPONENT_NAME,
                        props: {
                            licenseAnalysisEnabledState,
                            sigmaScanOnType,
                            signalScanConfig,
                            entitlementErrors
                        } as AutoScanConfigProps
                    });
                    break;
                case 'applyAllChanges': {
                    const previousSigmaScanOnType = sigmaScanOnType;
                    const previousLicenseAnalysisEnabledState = licenseAnalysisEnabledState;
                    const previousSignalScanConfig = signalScanConfig;
                    try {
                        sigmaScanOnType = message.sigmaScanOnType;
                        await getService(ScanToolConfigService.id).enableSigmaScanOnChange(message.sigmaScanOnType);
                        this.view.postObjectMessageToWebview({
                            command: AutoScanConfigCommands.REFRESH_SIGMA_SCAN_ON_TYPE_STATE,
                            sigmaScanOnType
                        });

                        const msgLicense = message.licenseAnalysisEnabledState;
                        const isEnabledOnOpen = msgLicense.isEnabledOnOpen ?? licenseAnalysisEnabledState.isEnabledOnOpen;
                        const isEnabledOnSave = msgLicense.isEnabledOnSave ?? licenseAnalysisEnabledState.isEnabledOnSave;
                        const isEnabled = (isEnabledOnOpen || isEnabledOnSave) ? msgLicense.isEnabled : false;
                        vscodeContextService.preserveLicenseAnalysisEnabled(isEnabled, isEnabledOnOpen, isEnabledOnSave);
                        licenseAnalysisEnabledState = vscodeContextService.getPreservedLicenseAnalysisEnabled();
                        if (!licenseAnalysisEnabledState.isEnabled) {
                            getService(LicenseAnalysisService.id).setLicenseScanLastFilePath('');
                        }
                        this.view.postObjectMessageToWebview({
                            command: AutoScanConfigCommands.REFRESH_LICENSE_ANALYSIS_STATE,
                            licenseAnalysisEnabledState
                        });

                        if (message.signalScanConfig) {
                            signalScanConfig = message.signalScanConfig;
                            await this.updateSignalScanConfigState(signalScanConfig);
                            await getService(VscodeContextService.id).preserveReferenceBranchConfig(signalScanConfig.isCompareAgainstReferenceBranch);
                            if (signalScanConfig.isCompareAgainstReferenceBranch) {
                                if (getService(ScanStatusCoordinator.id).getCurrentScanFileScope() === RefreshResultsRequest.Tier.ALLUNCOMMITTED) {
                                    await getService(ScanStatusCoordinator.id).changeScanFileScope(RefreshResultsRequest.Tier.REFERENCEBRANCH);
                                }
                                await this.updateReferenceBranchName(signalScanConfig.referenceBranchName);
                            } else {
                                if (getService(ScanStatusCoordinator.id).getCurrentScanFileScope() === RefreshResultsRequest.Tier.REFERENCEBRANCH) {
                                    await getService(ScanStatusCoordinator.id).changeScanFileScope(RefreshResultsRequest.Tier.ALLUNCOMMITTED);
                                }
                                await this.updateReferenceBranchName('');
                            }
                            this.view.postObjectMessageToWebview({
                                command: AutoScanConfigCommands.REFRESH_SIGNAL_SCAN_CONFIG_STATE,
                                signalScanConfig
                            });
                        }

                        this.view.postObjectMessageToWebview({
                            command: AutoScanConfigCommands.APPLY_CHANGES_RESULT
                        });
                    } catch (error) {
                        getLogger().error(`Failed to apply configuration changes: ${error}`);

                        // Revert sigma state
                        sigmaScanOnType = previousSigmaScanOnType;
                        await getService(ScanToolConfigService.id).enableSigmaScanOnChange(sigmaScanOnType);
                        this.view.postObjectMessageToWebview({
                            command: AutoScanConfigCommands.REFRESH_SIGMA_SCAN_ON_TYPE_STATE,
                            sigmaScanOnType
                        });

                        // Revert license analysis state
                        licenseAnalysisEnabledState = previousLicenseAnalysisEnabledState;
                        vscodeContextService.preserveLicenseAnalysisEnabled(
                            licenseAnalysisEnabledState.isEnabled,
                            licenseAnalysisEnabledState.isEnabledOnOpen,
                            licenseAnalysisEnabledState.isEnabledOnSave
                        );
                        this.view.postObjectMessageToWebview({
                            command: AutoScanConfigCommands.REFRESH_LICENSE_ANALYSIS_STATE,
                            licenseAnalysisEnabledState
                        });

                        // Revert signal state
                        signalScanConfig = previousSignalScanConfig;
                        this.view.postObjectMessageToWebview({
                            command: AutoScanConfigCommands.REFRESH_SIGNAL_SCAN_CONFIG_STATE,
                            signalScanConfig
                        });

                        this.view.postObjectMessageToWebview({
                            command: AutoScanConfigCommands.APPLY_CHANGES_FAILED
                        });
                    }
                    break;
                }
                case 'openProductsAndLicensesPage':
                    await commands.executeCommand(OPEN_INSTALLED_TOOLS_MSG_COMMAND_ID);
                    break;
                case 'openCsseEmailVerificationPage':
                    await commands.executeCommand(OPEN_EMAIL_VERIFICATION_MSG_COMMAND_ID);
                    break;
                case 'openBdAuthPage':
                    await commands.executeCommand(EDIT_BLACK_DUCK_SERVER_INFO_COMMAND_ID);
                    break;
                case 'openSigmaDocumentation':
                    await getService(CsBrowserService.id).openLink(DOC_SIGMA_ADDRESS);
                    break;
                case 'openSnippetDocumentation':
                    await getService(CsBrowserService.id).openLink(SNIPPET_ANALYSIS_DOCUMENTATION_ADDRESS);
                    break;
                case 'openSignalDocumentation':
                    await getService(CsBrowserService.id).openLink(SIGNAL_DOCUMENTATION_ADDRESS);
                    break;
            }
        });

        // should be called last
        this.view.initHtml();
    }

    private async getConfigResponse() : Promise<GetConfigurationResponse|undefined> {
        const configServiceClient = await getService(ControllerClientService.id).getConfigurationServiceClient();
        const getConfigRequest = new GetConfigurationRequest();
        getConfigRequest.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        let config = await configServiceClient.getConfiguration(getConfigRequest);
        return config;
    }

    async fetchSignalScanConfigState(): Promise<SignalScanConfigState> {
        const configResponse = await this.getConfigResponse();
        const userConfig = configResponse?.getUserconfig();
        const workspaceConfig = configResponse?.getWorkspaceconfig();
        let configuredSignalState = userConfig?.getSignalconfig();
        const isReferenceBranchEnabled = getService(VscodeContextService.id).getPreservedReferenceBranchConfig();
        const referenceBranchName = workspaceConfig?.getGitconfig()?.getDiffscanreferencebranch()?.getValue() || '';
        return {
            isTimerBasedScansEnabled: configuredSignalState?.getTimerbasedscan()?.getValue() || false,
            isDataFlowScansEnabled: configuredSignalState?.getDataflow()?.getValue() || false,
            isOversightScansEnabled: configuredSignalState?.getOversight()?.getValue() || false,
            isCompareAgainstReferenceBranch: isReferenceBranchEnabled,
            referenceBranchName: referenceBranchName,
            isScanEntireContentChangedFilesEnabled: configuredSignalState?.getScanentirecontentchangedfiles()?.getValue() || false,
        }
    }

    async updateSignalScanConfigState(state: SignalScanConfigState): Promise<void> {
        const configResponse = await this.getConfigResponse();
        const userConfig = configResponse?.getUserconfig();
        const configuredSignalState = userConfig?.getSignalconfig();

        const makeBoolValue = (value: boolean): BoolValue => {
            const boolValue = new BoolValue();
            boolValue.setValue(value);
            const source = new ValueSource();
            source.setType(ValueSource.Type.CODE_SIGHT_USER);
            boolValue.setSource(source);
            return boolValue;
        };

        configuredSignalState?.setTimerbasedscan(makeBoolValue(state.isTimerBasedScansEnabled));
        configuredSignalState?.setDataflow(makeBoolValue(state.isDataFlowScansEnabled));
        configuredSignalState?.setOversight(makeBoolValue(state.isOversightScansEnabled));
        configuredSignalState?.setScanentirecontentchangedfiles(makeBoolValue(state.isScanEntireContentChangedFilesEnabled));

        // Notify SignalTimerService about any timer configuration change
        await getService(SignalTimerService.id).onTimerConfigChanged(state.isTimerBasedScansEnabled);

        const configService = await getService(ControllerClientService.id).getConfigurationServiceClient();
        const request = new UpdateConfigurationRequest();
        request.setUserconfig(userConfig);
        await configService.updateConfiguration(request);
    }

    private async updateReferenceBranchName(branchName: string): Promise<void> {
        await getService(ConfigurationService.id).updateReferenceBranchName(branchName);
    }

    getEntitlementErrors(): AutoModeSpecificError {
        const entitlements = getService(EntitlementService.id).getCachedProductEntitlement();
        let entitlementErrors: AutoModeSpecificError = {};

        if (!entitlements.isSnippetScanEntitled()) {
            entitlementErrors.noSnippetScanEntitlement = true;
        }

        if (!entitlements.isSASTEntitled()) {
            if (entitlements.hasCsseLicense() && !entitlements.isCsseLicenseValid()) {
                entitlementErrors.invalidCSSELicense = entitlements.getCsseLicense().getState();
            } else {
                entitlementErrors.noSASTEntitlement = true;
            }
        } else if (!entitlements.isSigmaReadyToScan()) {
            entitlementErrors.noSigmaInstalled = true;
        }

        if (!entitlements.isSignalEntitled()) {
            entitlementErrors.noSignalEntitlement = true;
        }
        return Object.keys(entitlementErrors).length > 0 ? entitlementErrors : undefined;
    }


    async onSelectedScanConfigChanged(): Promise<void> {}
    async onSelectedReferenceBranchChanged(): Promise<void> {}
    async onScanModeChanged(): Promise<void> {}

    async onEntitlementsChanged(): Promise<void> {
        // reload the view
        this.view.postObjectMessageToWebview({
            command: AutoScanConfigCommands.REFRESH_ENTITLEMENTS,
            entitlementErrors: this.getEntitlementErrors(),
        });

    }
}
