export class TelemetryEnablementUnsetInfoMessage extends InfoMessage {
    async telemetryEnablementUnsetInfo(): Promise<void> {
        let enableText = TELEMETRY_ENABLEMENT_UNSET_ENABLE_TEXT;
        let disableText = TELEMETRY_ENABLEMENT_UNSET_DISABLE_TEXT;

        let optionClicked = await this.show(TELEMETRY_ENABLEMENT_UNSET_TEXT, enableText, disableText);
        let enable;
        if (optionClicked === enableText) {
            enable = true;            
        } else if (optionClicked === disableText) {
            enable = false;        
        }
        
        if (enable !== undefined) {
            let response = await getService(TelemetryService.id).sendUpdateTelemetryEnablementRequest(enable.toString());

            if (response !== undefined) {
                if (response.hasError()) {
                    getLogger().warn(`Error updating telemetry configuration: ${response.getError()?.getMessage()}`);
                } else {
                    // make sure settings config gets updated too
                    await vscode.workspace.getConfiguration(CODESIGHT_TELEMETRY_CONFIGURATION_KEY).
                    update("enablement", enable, vscode.ConfigurationTarget.Global);
                }
            }
        }
    }
}

