/**
 * Warning messages
 */
export abstract class WarningMessage {
    public async show(text: string, ...buttons: string[]): Promise<string | undefined> {
        return getService(WarningMessageService.id).show(this, text, buttons);
    }

    public async isCoverityInstalled(): Promise<boolean> {
        return getService(ToolStateService.id).isCoverityInstalled();
    }
}

export abstract class DismissableWarningMessage extends WarningMessage {

    abstract isEnabled(): boolean;

    abstract setEnabled(enabled: boolean): void;

    abstract onDontShowAgainClicked(): Promise<void>;

    public async showIfEnabled(text: string, buttons: string[]): Promise<string | undefined> {
        let disableMessagesForTests = isFeatureFlagEnabled(ENV_CODESIGHT_DESKTOP_DISABLE_WARNING_MESSAGES);
        if (!this.isEnabled() || disableMessagesForTests) {
            return Promise.resolve(undefined);
        }
        let disableMessageText = localize("empty.workspace.warning.Dismiss", "Do Not Show Again");
        let optionClicked = await this.show(text, ...buttons, disableMessageText);
        if (optionClicked === disableMessageText) {
            this.setEnabled(false);
            // eslint-disable-next-line @typescript-eslint/no-floating-promises
            vscode.workspace.getConfiguration(CODESIGHT_WARNINGS_CONFIGURATION_KEY)
                .update("showAll", false, vscode.ConfigurationTarget.Global);

            // eslint-disable-next-line @typescript-eslint/no-floating-promises
            this.onDontShowAgainClicked();
        }
        return optionClicked;
    }
}

