    abstract getLicenseErrorMessage(csseLicenseState?: CsseLicenseState): Promise<void>;

    abstract getResendEmailErrorMessage(code: number): Promise<void>;

    abstract warnBeforeAutoModeCancelsManualScan(): Promise<void>;

    abstract copyToClipboardFailed(): Promise<void>;

    abstract migrationScriptFailed(): Promise<void>;

