export class WarningMessageServiceImpl extends WarningMessageService {
    fileOutsideWorkspaceWarningMessage = new FileOutsideWorkspaceWarningMessage();
    emptyWorkspaceWarningMessage = new EmptyWorkspaceWarningMessage();
    sigmaLocationWarningMessage = new SigmaLocationWarningMessage();
    noFileOpenSingleFileScanWarningMessage = new NoFileOpenSingleFileScanWarningMessage();
    noToolsInstalledWarningMessage = new NoToolsInstalledWarningMessage();
    invalidDetectZipMessage = new InvalidDetectZipWarningMessage();
    licenseErrorWarningMessage = new LicenseErrorWarningMessage();
    warnBeforeAutoModeCancelsManualScanMessage = new WarnBeforeAutoModeCancelsManualScanMessage();
    copyToClipboardWarningMessage = new CopyToClipboardWarningMessage();
    warnUntrustedCertificateMessage = new WarnUntrustedCertificateMessage();
    migrationScriptFailedMessage = new MigrationScriptErrorWarningMessage();

    allDismissableWarningMessages: DismissableWarningMessage[] = [this.fileOutsideWorkspaceWarningMessage, 
        this.emptyWorkspaceWarningMessage, this.warnBeforeAutoModeCancelsManualScanMessage];

    syncShowMessageState(): void {
        let { showAll } = vscode.workspace.getConfiguration(CODESIGHT_WARNINGS_CONFIGURATION_KEY);
        if (showAll) {
            this.allDismissableWarningMessages.forEach(m => {
                m.setEnabled(true);
            });
        }
    }

    getUntrustedCertPopupsSet(): Set<string> {
        return untrustedCertPopupsSet;
    }

    async scannedFileOutsideWorkspace(fileName: string): Promise<void> {
        await this.fileOutsideWorkspaceWarningMessage.scannedFileOutsideWorkspace(fileName);
    }

    async workspaceFoldersChanged(): Promise<void> {
        this.syncShowMessageState();
        await this.emptyWorkspaceWarningMessage.workspaceFoldersChanged();
    }

    async noSigmaBinaryWarning(): Promise<void> {
        return this.sigmaLocationWarningMessage.noSigmaBinaryWarning();
    }

    async sigmaPathDoesNotExist(sigmaPath: string) {
        return this.sigmaLocationWarningMessage.sigmaPathDoesNotExist(sigmaPath);
    }

    async failedToLaunchSigmaWarning(sigmaPath: string): Promise<void> {
        return this.sigmaLocationWarningMessage.failedToLaunchSigmaWarning(sigmaPath);
    }

    async noFileOpenSingleFileScanWarning(): Promise<void> {
        return this.noFileOpenSingleFileScanWarningMessage.noFileOpenSingleFileScanWarning();
    }

    async noToolIsInstalledWarning(): Promise<void> {
        return this.noToolsInstalledWarningMessage.noToolIsInstalledWarning();
    }

    async invalidDetectZipSelected(errorMessage?: string): Promise<void> {
        return this.invalidDetectZipMessage.invalidDetectZipWarning(errorMessage);
    }

    async getLicenseErrorMessage(licenseState?: CsseLicenseState) : Promise<void> {
        return this.licenseErrorWarningMessage.getLicenseErrorMessage(licenseState);
    }

    async getResendEmailErrorMessage(code: number) : Promise<void> {
        return this.licenseErrorWarningMessage.getResendEmailErrorMessage(code);
    }

    async warnBeforeAutoModeCancelsManualScan(): Promise <void> {
        return this.warnBeforeAutoModeCancelsManualScanMessage.warnBeforeAutoModeCancelsManualScan();
    }

    async copyToClipboardFailed(): Promise<void> {
        return this.copyToClipboardWarningMessage.copyToClipboardFailed();
    }

    async migrationScriptFailed(): Promise<void> {
        return this.migrationScriptFailedMessage.migrationScriptError();
    }

    async warnUntrustedCertificate(notificationMessage: NotificationMessage): Promise<void> {
        let cert = getCertPEMFormat(notificationMessage);
        if (untrustedCertPopupsSet.has(cert)) {
            return;
        }
        untrustedCertPopupsSet.add(cert);
        return this.warnUntrustedCertificateMessage.getUntrustedCertificateErrorMessage(notificationMessage);
    }

    public async init() {
        getLogger().info("Initializing WarningMessageService...");
        vscode.workspace.onDidChangeConfiguration((e: vscode.ConfigurationChangeEvent) => {
            if (e.affectsConfiguration(CODESIGHT_WARNINGS_CONFIGURATION_KEY)) {
                this.syncShowMessageState();
            }
        });
    }

    public async show(warningMessage: WarningMessage, text: string, buttons: string[]): Promise<string | undefined> {
        return await vscode.window.showWarningMessage(text, ...buttons);
    }
}

