import { Disposable, Event, EventEmitter, FileDecoration, FileDecorationProvider, ThemeColor, Uri, window } from 'vscode';
import { ABSENT_DIFF_FILTER_RESOURCE_URI, ABSENT_DIFF_FILTER_THEME_COLOR, LINK_RESOURCE_URI, LINK_THEME_COLOR, NEW_DIFF_FILTER_RESOURCE_URI, NEW_DIFF_FILTER_THEME_COLOR, SIGNAL_RESOURCE_URI, SIGNAL_THEME_COLOR } from '../utils/constants';


export class TreeItemDecorationProvider implements FileDecorationProvider {

    private disposables: Disposable[] = [];

    private readonly _onDidChangeFileDecorations: EventEmitter<Uri | Uri[]> = new EventEmitter< Uri | Uri[]>();
    readonly onDidChangeFileDecorations: Event<Uri | Uri[]> = this._onDidChangeFileDecorations.event;

    constructor() {
        this.disposables = [];
        this.disposables.push(window.registerFileDecorationProvider(this));
    } 
    
    async provideFileDecoration(uri?: Uri): Promise<FileDecoration | undefined> {
        if (uri?.scheme === LINK_RESOURCE_URI) {
            return {
                color: new ThemeColor(LINK_THEME_COLOR), 
            };
        } else if (uri?.scheme === NEW_DIFF_FILTER_RESOURCE_URI) {
            return {
                color: new ThemeColor(NEW_DIFF_FILTER_THEME_COLOR), 
            };
        } else if (uri?.scheme === ABSENT_DIFF_FILTER_RESOURCE_URI) {
            return {
                color: new ThemeColor(ABSENT_DIFF_FILTER_THEME_COLOR), 
            };
        } else if (uri?.scheme === SIGNAL_RESOURCE_URI) {
            return {
                color: new ThemeColor(SIGNAL_THEME_COLOR),
            };
        } else {
            return {};
        }
    }
    
    dispose() {
        this.disposables.forEach((d) => d.dispose());
    }
}