export const LOCAL_VIEW_SCAN_RUNNING_CONTEXT = "codesight.localViewScanRunning";
export const LOCAL_VIEW_MANUAL_SCAN_RUNNING_CONTEXT = "codesight.localViewManualScanRunning";
export const LOCAL_VIEW_SIGNAL_SCAN_RUNNING_CONTEXT = "codesight.localViewSignalScanRunning";
export const LOCAL_VIEW_SIGMA_CHANGED_FILE_SCAN_RUNNING_CONTEXT = "codesight.localViewSigmaChangedFileScanRunning";

/**
 * Handles making requests for scans to the controller.
 */
export abstract class ScanService {
    static readonly id: ServiceId<ScanService> = { id: ScanService.name };

    /**
     * Scan status of the last Local View scan
     */
    protected localViewScanStatus: RefreshStatus | undefined;

    /**
     * Scan status of the last Local View Rapid incremental scan
     */
    protected localViewAutoRapidScanStatus: RefreshStatus | undefined;

    /**
     * Scan status of the last Local View auto changed-file scan (ALLUNCOMMITTED/REFERENCEBRANCH tier)
     */
    protected localViewAutoChangedFileScanStatus: RefreshStatus | undefined;

    /**
     * Scan status of the last Local View License incremental scan
     */
    protected localViewAutoLicenseScanStatus: RefreshStatus | undefined;

    /**
     * Scan status of the last Local View Manual scan
     */
    protected localViewManualScanRunningStatus: RefreshStatus | undefined;

    /**
     * Scan status of the last Local View Signal scan
     */
    protected localViewSignalScanStatus: RefreshStatus | undefined;

    /**
     * File path being scanned in the last Local View Signal scan for FAST tier only.
     * Undefined for ALLUNCOMMITTED and REFERENCEBRANCH scans which scan multiple files.
     */
    protected localViewSignalScanFilePath: string | undefined;

    /**
     * Requests a scan for the given file.
     *
     * @param fileName the file to scan
     * @param tier the tier (fast or full)
     * @param trigger the trigger (e.g., on save)
     */
    abstract requestScan(fileName: string, tier: RefreshResultsRequest.Tier, trigger: RefreshResultsRequest.Trigger): Promise<void>;

    /**
     * Requests Sigma scans for multiple files.
     */
    abstract requestSigmaScan(): Promise<void>;

        /**
     * Requests License Analysis scans for a file.
     *
     * @param filePath the file to scan
     */
    abstract requestLicenseAnalysisScan(filePath: string): Promise<void>;

    /**
     * Requests scans for multiple files.
     * 
     * @param fileNames the set of files to scan
     * @param tier the tier (fast or full)
     * @param trigger the trigger (e.g., on save)
     */
    abstract requestScans(fileNames: Set<string>, tier: RefreshResultsRequest.Tier, trigger: RefreshResultsRequest.Trigger): Promise<void>;

    /**
     * Cancel running or queued job
     */
    abstract cancelJob(jobId: string): Promise<void>;

    abstract getLocalViewLastScanId(): string | undefined;

    abstract getLocalViewLastScanStatus(): RefreshStatus.Status | undefined

    /**
     * Returns true if a Local View scan is currently running
     */
    abstract isLocalViewScanRunning(): boolean;

    /**
     * Returns true if a Local View auto rapid scan is currently running
     */
    abstract isLocalViewAutoRapidScanRunning(): boolean;

    /**
     * Returns true if a Local View auto changed-file scan (ALLUNCOMMITTED/REFERENCEBRANCH) is currently running
     */
    abstract isLocalViewAutoChangedFileScanRunning(): Promise<boolean>;

    /**
     * Marks a changed-file scan as pending so the UI shows scanning state immediately,
     * before the controller sends back the first status notification.
     */
    async markChangedFileScanPending(): Promise<void> {
        const pendingStatus = new RefreshStatus();
        pendingStatus.setStatus(RefreshStatus.Status.QUEUED);
        const currentGitRepoPath = await getService(ConfigurationService.id).getConfiguredGitRepositoryPath();
        if (currentGitRepoPath) {
            pendingStatus.setGitrepositorypath(currentGitRepoPath);
        }
        this.localViewAutoChangedFileScanStatus = pendingStatus;
    }

    /**
     * Marks a Signal scan as pending so the UI shows scanning state immediately,
     * before the controller sends back the first status notification.
     */
    async markSignalScanPending(): Promise<void> {
        const pendingStatus = new RefreshStatus();
        pendingStatus.setStatus(RefreshStatus.Status.QUEUED);
        const currentGitRepoPath = await getService(ConfigurationService.id).getConfiguredGitRepositoryPath();
        if (currentGitRepoPath) {
            pendingStatus.setGitrepositorypath(currentGitRepoPath);
        }
        this.localViewSignalScanStatus = pendingStatus;
    }

    /**
     * Returns true if a Local View auto license scan is currently running
     */
    abstract isLocalViewAutoLicenseScanRunning(): boolean;

    /**
     * Returns true if a Local View project scan is currently running
     */
    abstract isLocalViewManualScanRunning(): boolean;

    /**
     * Returns true if a Local View Signal scan is currently running
     */
    abstract isLocalViewSignalScanRunning(): Promise<boolean>;

    /**
     * Returns true while a Signal scan cancel request is in-flight
     */
    abstract isSignalScanCancelling(): boolean;

    /**
     * Returns true while a Sigma changed-file scan cancel request is in-flight
     */
    abstract isChangedFileScanCancelling(): boolean;

    /**
     * Returns true if a Local View Signal scan is currently running for the specified file path.
     * Only returns true for FAST tier scans - returns false for ALLUNCOMMITTED/REFERENCEBRANCH scans
     * even if they are running.
     *
     * @param filePath The file path to check
     */
    abstract isLocalViewSignalScanRunningForFile(filePath: string): boolean;

    /**
     * Returns the file path of the last FAST tier Signal scan, or undefined if no FAST scan has been run.
     */
    abstract getLastSignalScanFilePath(): string | undefined;

    /**
     * Cancels the currently running Signal scan
     */
    abstract cancelSignalScan(): Promise<void>;

    /**
     * Cancels the currently running Sigma changed-file scan
     */
    abstract cancelSigmaChangedFileScan(): Promise<void>;

    /**
     * Returns whether entitlement present for scan
     *
     * @param scanType the type of scan
     */
    abstract isScanEntitled(scanType: ScanConfig.ScanType.Type): boolean;

    /**
     * Returns true if a current ScanMode matches the FileScanInfo.Source
     */
    abstract doesScanModeMatch(source: FileScanInfo.Source): boolean;

    abstract parseResultsMessage(resultsNotification: MonitorResultsNotification): Promise<void>;

    abstract requestScanForConfig(scanConfig: ScanConfiguration, filePaths: string[]): Promise<RefreshResultsResponse | undefined>;

    abstract requestSignalScan(filePaths: string[], scope: RefreshResultsRequest.Tier): Promise<RefreshResultsResponse | undefined>;
}

export class ScanServiceImpl extends ScanService {

    private isSignalCancellingFlag: boolean = false;
    private isChangedFileCancellingFlag: boolean = false;

    isSignalScanCancelling(): boolean {
        return this.isSignalCancellingFlag;
    }

    isChangedFileScanCancelling(): boolean {
        return this.isChangedFileCancellingFlag;
    }

    async requestScanForConfig(scanConfig: ScanConfiguration, filePaths: string[]): Promise<RefreshResultsResponse | undefined> {
        const logger = getLogger();
        const configId = scanConfig.name;
        if (filePaths.length === 0) {
            logger.debug(`Skipping custom ${configId} config scan. filePath length: ${filePaths.length}`);
            return;
        }

        let analysisService = await getService(ControllerClientService.id).getAnalysisServiceClient();
        await getService(AnalysisContextObservationService.id).observeCurrentContext();
        let observedContext = getService(AnalysisContextService.id).buildAnalysisContext();
        let refreshResultsRequest = new RefreshResultsRequest();
        let filePathList: PathOrContent[] = [];
        filePaths.forEach(element => {
            let filePath = new PathOrContent();
            filePath.setPath(element);
            filePathList.push(filePath);
        });
 
        refreshResultsRequest.setContextref(observedContext.getRef());
        refreshResultsRequest.setScanconfigid(configId);
        refreshResultsRequest.setFilesList(filePathList);
        refreshResultsRequest.setTier(convertToRefreshResultsTier(scanConfig.scope));
        refreshResultsRequest.setTriggeraction(RefreshResultsRequest.Trigger.USERREQUESTED);
        refreshResultsRequest.setToolsList([convertToLicensedToolType(scanConfig.scanType.getType())]);

        if (scanConfig.scanType.getType() === ScanConfig.ScanType.Type.SIGNAL) {
            const scanMode = getService(ScanStatusCoordinator.id).getCurrentScanMode();
            const source = scanMode === ScanMode.Auto ? FileScanInfo.Source.AUTO : FileScanInfo.Source.MANUAL;
            refreshResultsRequest.setSource(source);
        }

        let refreshResultsResponse = await analysisService.refreshResults(refreshResultsRequest);
        this.logRequestResponse(refreshResultsResponse);

        let status = refreshResultsResponse.getStatus();
        if (status && status.getStatus() === RefreshStatus.Status.FAILED && status.getReason() === RefreshStatus.Reason.SYNCREQUIRED) {
            logger.info(`Repeating async analysis for config ${configId}`);
            let reattemptResponse = await analysisService.refreshResults(refreshResultsRequest);
            this.logRequestResponse(reattemptResponse);
            return reattemptResponse;
        }
        
        return refreshResultsResponse;
    }

    async requestSignalScan(filePaths: string[], scope: RefreshResultsRequest.Tier): Promise<RefreshResultsResponse | undefined> {
        const logger = getLogger();

        // For Code Changes scopes, filePaths can be empty
        if (scope === RefreshResultsRequest.Tier.FAST && filePaths.length === 0) {
            logger.debug(`Skipping Signal scan. filePath length: ${filePaths.length} for FAST scope`);
            return;
        }

        // Track file path only for FAST tier scans (single active file)
        if (scope === RefreshResultsRequest.Tier.FAST && filePaths.length > 0) {
            this.localViewSignalScanFilePath = filePaths[0];
        } else {
            // Clear file path for multi-file scans (ALLUNCOMMITTED, REFERENCEBRANCH)
            this.localViewSignalScanFilePath = undefined;
        }

        let analysisService = await getService(ControllerClientService.id).getAnalysisServiceClient();
        await getService(AnalysisContextObservationService.id).observeCurrentContext();
        let observedContext = getService(AnalysisContextService.id).buildAnalysisContext();
        let refreshResultsRequest = new RefreshResultsRequest();
        let filePathList: PathOrContent[] = [];
        filePaths.forEach(element => {
            let filePath = new PathOrContent();
            filePath.setPath(element);
            filePathList.push(filePath);
        });

        refreshResultsRequest.setContextref(observedContext.getRef());
        refreshResultsRequest.setFilesList(filePathList);
        refreshResultsRequest.setTier(scope);
        refreshResultsRequest.setTriggeraction(RefreshResultsRequest.Trigger.USERREQUESTED);
        refreshResultsRequest.setToolsList([LicensedToolsConfig.Type.SIGNAL]);
        refreshResultsRequest.setSource(FileScanInfo.Source.AUTO);

        let refreshResultsResponse = await analysisService.refreshResults(refreshResultsRequest);
        this.logRequestResponse(refreshResultsResponse);

        let status = refreshResultsResponse.getStatus();
        if (status && status.getStatus() === RefreshStatus.Status.FAILED && status.getReason() === RefreshStatus.Reason.SYNCREQUIRED) {
            logger.info(`Repeating async Signal analysis`);
            let reattemptResponse = await analysisService.refreshResults(refreshResultsRequest);
            this.logRequestResponse(reattemptResponse);
            return reattemptResponse;
        }

        return refreshResultsResponse;
    }

    async requestScan(fileName: string, tier: RefreshResultsRequest.Tier, trigger: RefreshResultsRequest.Trigger): Promise<void> {
        const logger = getLogger();

        if (tier !== RefreshResultsRequest.Tier.FULL) {
            let scannableStatus = await isFileScannable(vscode.Uri.file(fileName));

            switch (scannableStatus) {
                case ScannableStatus.OutOfWorkspace:
                    await getService(WarningMessageService.id).scannedFileOutsideWorkspace(fileName);
                    logger.info(`File ${fileName} was opened, but is not in the workspace. Skipping scan`);
                    break;
            }

            if (scannableStatus !== ScannableStatus.Scannable) {
                return;
            }
        }

        // in case we forgot to normalize it elsewhere
        fileName = normalizeDriveLetter(fileName);

        let analysisService = await getService(ControllerClientService.id).getAnalysisServiceClient();
        await getService(AnalysisContextObservationService.id).observeCurrentContext();
        let observedContext = getService(AnalysisContextService.id).buildAnalysisContext();
        let refreshResultsRequest = new RefreshResultsRequest();
        let filePath = new PathOrContent();
        filePath.setPath(fileName);
        let fileNameArray: PathOrContent[] = [filePath];
        refreshResultsRequest.setContextref(observedContext.getRef());
        refreshResultsRequest.setFilesList(fileNameArray);
        refreshResultsRequest.setTier(tier);
        refreshResultsRequest.setTriggeraction(trigger);
        refreshResultsRequest.setToolsList([LicensedToolsConfig.Type.COVERITY]);

        let refreshResultsResponse = await analysisService.refreshResults(refreshResultsRequest);
        this.logRequestResponse(refreshResultsResponse);

        let status = refreshResultsResponse.getStatus();
        if (status && status.getStatus() === RefreshStatus.Status.FAILED && status.getReason() === RefreshStatus.Reason.SYNCREQUIRED) {
            logger.info(`Repeating async analysis for ${fileName}`);
            let reattemptResponse = await analysisService.refreshResults(refreshResultsRequest);
            this.logRequestResponse(reattemptResponse);
        }
    }

    async requestScans(fileNames: Set<string>, tier: RefreshResultsRequest.Tier, trigger: RefreshResultsRequest.Trigger): Promise<void> {
        let promises: Promise<void>[] = [];

        fileNames.forEach(element => {
            promises.push(this.requestScan(element, tier, trigger));
        });
        await Promise.all(promises);
    }

    async requestSigmaScan(): Promise<void> {
        let analysisService = await getService(ControllerClientService.id).getAnalysisServiceClient();
        await getService(AnalysisContextObservationService.id).observeCurrentContext();
        let observedContext = getService(AnalysisContextService.id).buildAnalysisContext();
        let refreshResultsRequest = new RefreshResultsRequest();
 
        refreshResultsRequest.setContextref(observedContext.getRef());
        const scanFileScope = getService(ScanStatusCoordinator.id).getCurrentScanFileScope();
        refreshResultsRequest.setTier(scanFileScope);
        refreshResultsRequest.setSource(FileScanInfo.Source.AUTO);
        refreshResultsRequest.setTriggeraction(RefreshResultsRequest.Trigger.USERREQUESTED);
        refreshResultsRequest.setToolsList([LicensedToolsConfig.Type.SIGMA]);

        let refreshResultsResponse = await analysisService.refreshResults(refreshResultsRequest);
        this.logRequestResponse(refreshResultsResponse);
    }

    async requestLicenseAnalysisScan(filePath: string): Promise<void> {
        if (getService(ScanStatusCoordinator.id).getCurrentScanMode() !== ScanMode.Auto) {
            return;
        }

        if (getService(ScanStatusCoordinator.id).isCurrentScanFilesScopeChangedFiles()) {
            return;
        }

        const logger = getLogger();
        if (filePath === undefined || filePath.length === 0) {
            logger.debug(`Skipping License Analysis scan. filePath: ${filePath}`);
            return;
        }

        let scannableStatus = await isFileScannable(vscode.Uri.file(filePath));

        switch (scannableStatus) {
            case ScannableStatus.OutOfWorkspace:
                await getService(WarningMessageService.id).scannedFileOutsideWorkspace(filePath);
                logger.info(`File ${filePath} was opened, but is not in the workspace. Skipping scan`);
                break;
        }

        if (scannableStatus !== ScannableStatus.Scannable) {
            return;
        }
    

        let analysisService = await getService(ControllerClientService.id).getAnalysisServiceClient();
        await getService(AnalysisContextObservationService.id).observeCurrentContext();
        let observedContext = getService(AnalysisContextService.id).buildAnalysisContext();
        let refreshResultsRequest = new RefreshResultsRequest();

        let filePathOrContent = new PathOrContent();
        filePathOrContent.setPath(filePath);
 
        refreshResultsRequest.setContextref(observedContext.getRef());
        refreshResultsRequest.setFilesList([filePathOrContent]);
        refreshResultsRequest.setTriggeraction(RefreshResultsRequest.Trigger.USERREQUESTED);
        refreshResultsRequest.setSource(FileScanInfo.Source.AUTO);
        refreshResultsRequest.setToolsList([LicensedToolsConfig.Type.SNIPPETMATCH]);

        let refreshResultsResponse = await analysisService.refreshResults(refreshResultsRequest);
        this.logRequestResponse(refreshResultsResponse);
    }
    
    async cancelJob(jobId: string): Promise<void> {
        const logger = getLogger();
        logger.info("Cancel job: ", jobId);

        let analysisService = await getService(ControllerClientService.id).getAnalysisServiceClient();
        let cancelRequest = new CancelRequest();
        cancelRequest.setJobsList([jobId]);
        
        await analysisService.cancelJobs(cancelRequest);
    }

    getLocalViewLastScanStatus(): RefreshStatus.Status | undefined {
        return this.localViewScanStatus?.getStatus();
    }

    getLocalViewLastScanId(): string | undefined {
        return this.localViewScanStatus?.getJobid();
    }

    isLocalViewScanRunning(): boolean {        
        return this.isRunningStatus(this.localViewScanStatus?.getStatus());
    }

    isLocalViewAutoRapidScanRunning(): boolean {
        return this.isRunningStatus(this.localViewAutoRapidScanStatus?.getStatus());
    }

    async isLocalViewAutoChangedFileScanRunning(): Promise<boolean> {
        if (!this.isRunningStatus(this.localViewAutoChangedFileScanStatus?.getStatus())) {
            return false;
        }
        // Only report running if it's for the currently selected folder
        const currentGitRepoPath = await getService(ConfigurationService.id).getConfiguredGitRepositoryPath();
        if (currentGitRepoPath === undefined) {
            return true;
        }
        return this.localViewAutoChangedFileScanStatus?.getGitrepositorypath() === currentGitRepoPath;
    }

    isLocalViewAutoLicenseScanRunning(): boolean {
        return this.isRunningStatus(this.localViewAutoLicenseScanStatus?.getStatus());
    }

    isLocalViewManualScanRunning(): boolean {
        return this.isRunningStatus(this.localViewManualScanRunningStatus?.getStatus())
    }

    async isLocalViewSignalScanRunning(): Promise<boolean> {
        if (!this.isRunningStatus(this.localViewSignalScanStatus?.getStatus())) {
            return false;
        }
        // For changed-file tiers, only report running if it's for the currently selected folder
        const scanGitRepoPath = this.localViewSignalScanStatus?.getGitrepositorypath();
        if (scanGitRepoPath) {
            const currentGitRepoPath = await getService(ConfigurationService.id).getConfiguredGitRepositoryPath();
            if (currentGitRepoPath === undefined) {
                return true;
            }
            return scanGitRepoPath === currentGitRepoPath;
        }
        return true;
    }

    getLastSignalScanFilePath(): string | undefined {
        return this.localViewSignalScanFilePath;
    }

    isLocalViewSignalScanRunningForFile(filePath: string): boolean {
        // Only return true if:
        // 1. A Signal scan is running AND
        // 2. We have a tracked file path (FAST tier scan) AND
        // 3. The tracked file path matches the requested file path
        return this.isRunningStatus(this.localViewSignalScanStatus?.getStatus()) &&
               this.localViewSignalScanFilePath !== undefined &&
               this.localViewSignalScanFilePath === filePath;
    }

    async cancelSignalScan(): Promise<void> {
        const jobId = this.localViewSignalScanStatus?.getJobid();
        // Immediately set CANCELLED so the UI doesn't get stuck if cancel fires before
        // the controller sends a RUNNING notification (no job ID yet)
        const cancelledStatus = new RefreshStatus();
        cancelledStatus.setStatus(RefreshStatus.Status.CANCELLED);
        this.localViewSignalScanStatus = cancelledStatus;
        if (!jobId) {
            getLogger().warn("Cannot cancel Signal scan: no job ID available, clearing pending state");
            return;
        }

        this.isSignalCancellingFlag = true;
        try {
            getLogger().info("Cancelling Signal scan with job ID: ", jobId);
            await this.cancelJob(jobId);
        } finally {
            this.isSignalCancellingFlag = false;
        }
    }

    async cancelSigmaChangedFileScan(): Promise<void> {
        const jobId = this.localViewAutoChangedFileScanStatus?.getJobid();
        // Immediately set CANCELLED so the UI doesn't get stuck if cancel fires before
        // the controller sends a RUNNING notification (no job ID yet)
        const cancelledStatus = new RefreshStatus();
        cancelledStatus.setStatus(RefreshStatus.Status.CANCELLED);
        this.localViewAutoChangedFileScanStatus = cancelledStatus;
        if (!jobId) {
            getLogger().warn("Cannot cancel Sigma changed-file scan: no job ID available, clearing pending state");
            return;
        }

        this.isChangedFileCancellingFlag = true;
        try {
            getLogger().info("Cancelling Sigma changed-file scan with job ID: ", jobId);
            await this.cancelJob(jobId);
        } finally {
            this.isChangedFileCancellingFlag = false;
        }
    }

    isRunningStatus(status: RefreshStatus.Status | undefined): boolean {
        if(!status) {
            return false;
        }
        
        return status === RefreshStatus.Status.QUEUED || status === RefreshStatus.Status.PREPARING 
            || status === RefreshStatus.Status.FINALIZING || status === RefreshStatus.Status.RUNNING;
    }

    isScanEntitled(scanType: ScanConfig.ScanType.Type): boolean {
        const entitlements = getService(EntitlementService.id).getCachedProductEntitlement();
        switch (scanType) {
            case ScanConfig.ScanType.Type.SIGMA:
                if ((!entitlements.isSASTEntitled() || !entitlements.isSigmaReadyToScan())) {
                    return false;
                }
                return true;
            case ScanConfig.ScanType.Type.BLACKDUCK:
                if (!entitlements.isBlackDuckEntitled()) {
                    return false;
                }
                return true;
            default:
                return false;
        }
    }
    
    async parseResultsMessage(notification: MonitorResultsNotification): Promise<void> {
        let notificationStatus = notification.getStatus();
        if (!notificationStatus) {
            return;
        }
        let mode = notificationStatus.getScansource();
        let tier = notificationStatus.getTier();
        const scanMode = getService(ScanStatusCoordinator.id).getCurrentScanMode();
        const isSignalScan = notificationStatus.getScantype()?.getType() === ScanConfig.ScanType.Type.SIGNAL;

        // Signal scans are tracked regardless of scan mode
        if (!isSignalScan && !this.doesScanModeMatch(mode)) {
            return;
        }

        if (isSignalScan && tier !== getService(ScanStatusCoordinator.id).getCurrentScanFileScope()) {
            return;
        }

        this.localViewScanStatus = notificationStatus;
        if (scanMode === ScanMode.Auto) {
            if (notificationStatus.getScantype()?.getType() === ScanConfig.ScanType.Type.SIGMA){
                if (isChangedFileScanTier(tier)) {
                    this.localViewAutoChangedFileScanStatus = notificationStatus;
                } else {
                    this.localViewAutoRapidScanStatus = notificationStatus;
                }
            } else if (notificationStatus.getScantype()?.getType() === ScanConfig.ScanType.Type.BLACKDUCK) {
                this.localViewAutoLicenseScanStatus = notificationStatus;
            }
        }

        // Track Signal scan status regardless of scan mode (Signal runs in Project mode)
        if (notificationStatus.getTooltype() === LicensedToolsConfig.Type.SIGNAL) {
            this.localViewSignalScanStatus = notificationStatus;

        }

        // For changed-file tiers, check if notification is for the currently selected folder
        const isForCurrentFolder = !isChangedFileScanTier(tier) || await this.isNotificationForCurrentFolder(notificationStatus);

        const status = notificationStatus.getStatus();
        switch (status) {
            case RefreshStatus.Status.FAILED:
            case RefreshStatus.Status.SUCCESS:
            case RefreshStatus.Status.CANCELLED:
            case RefreshStatus.Status.UNKNOWNSTATUS:
                // Always clear running contexts on completion — safe even for other folders
                // eslint-disable-next-line @typescript-eslint/no-floating-promises
                vscode.commands.executeCommand("setContext", LOCAL_VIEW_SCAN_RUNNING_CONTEXT, false);
                if (scanMode === ScanMode.Manual && notificationStatus.getScansource() === FileScanInfo.Source.MANUAL) {
                    // eslint-disable-next-line @typescript-eslint/no-floating-promises
                    vscode.commands.executeCommand("setContext", LOCAL_VIEW_MANUAL_SCAN_RUNNING_CONTEXT, false);
                    this.localViewManualScanRunningStatus = notificationStatus;
                }
                if (notificationStatus.getScantype()?.getType() === ScanConfig.ScanType.Type.SIGNAL) {
                    // eslint-disable-next-line @typescript-eslint/no-floating-promises
                    vscode.commands.executeCommand("setContext", LOCAL_VIEW_SIGNAL_SCAN_RUNNING_CONTEXT, false);
                }
                if (notificationStatus.getScantype()?.getType() === ScanConfig.ScanType.Type.SIGMA && isChangedFileScanTier(tier)) {
                    // eslint-disable-next-line @typescript-eslint/no-floating-promises
                    vscode.commands.executeCommand("setContext", LOCAL_VIEW_SIGMA_CHANGED_FILE_SCAN_RUNNING_CONTEXT, false);
                }
                break;
            default:
                // Only set running contexts if notification is for the current folder
                if (isForCurrentFolder) {
                    // eslint-disable-next-line @typescript-eslint/no-floating-promises
                    vscode.commands.executeCommand("setContext", LOCAL_VIEW_SCAN_RUNNING_CONTEXT, true);
                }
                if (scanMode === ScanMode.Manual && notificationStatus.getScansource() === FileScanInfo.Source.MANUAL) {
                    // eslint-disable-next-line @typescript-eslint/no-floating-promises
                    vscode.commands.executeCommand("setContext", LOCAL_VIEW_MANUAL_SCAN_RUNNING_CONTEXT, true);
                    this.localViewManualScanRunningStatus = notificationStatus;
                }
                if (isForCurrentFolder && notificationStatus.getScantype()?.getType() === ScanConfig.ScanType.Type.SIGNAL) {
                    // eslint-disable-next-line @typescript-eslint/no-floating-promises
                    vscode.commands.executeCommand("setContext", LOCAL_VIEW_SIGNAL_SCAN_RUNNING_CONTEXT, true);
                }
                if (isForCurrentFolder && notificationStatus.getScantype()?.getType() === ScanConfig.ScanType.Type.SIGMA && isChangedFileScanTier(tier)) {
                    // eslint-disable-next-line @typescript-eslint/no-floating-promises
                    vscode.commands.executeCommand("setContext", LOCAL_VIEW_SIGMA_CHANGED_FILE_SCAN_RUNNING_CONTEXT, true);
                }
                break;

        }
        await getService(ScanStatusCoordinator.id).notifyListenersOfScanResultsReceived(notificationStatus);
        return;
    }

    private async isNotificationForCurrentFolder(notificationStatus: RefreshStatus): Promise<boolean> {
        const currentGitRepoPath = await getService(ConfigurationService.id).getConfiguredGitRepositoryPath();
        // If no folder has been explicitly selected yet, consider all notifications as current
        if (currentGitRepoPath === undefined) {
            return true;
        }
        return notificationStatus.getGitrepositorypath() === currentGitRepoPath;
    }

    public doesScanModeMatch(source: FileScanInfo.Source): boolean {
        let scanMode = getService(ScanStatusCoordinator.id).getCurrentScanMode();
        return (scanMode === ScanMode.Manual && source === FileScanInfo.Source.MANUAL) ||
            (scanMode === ScanMode.Auto && source === FileScanInfo.Source.AUTO);
    }

    public matchesCurrentScanSource(source: FileScanInfo.Source): boolean {
        return source === this.localViewScanStatus?.getScansource();
    }

    private logRequestResponse(response: RefreshResultsResponse) {
        getLogger().debug(`Refresh results response: Status: ${refreshStatusToReadable(response.getStatus()!.getStatus())} Reason: ${refreshReasonToReadable(response.getStatus()!.getReason())} Description: ${response.getStatus()!.getDescription()}`);
    }
}