import { Webview } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { ServiceId } from "../../services/serviceContainer";
import { isWindows } from "../../utils/environmentUtils";
import { BUTTON_STYLING, getWebviewHead } from "../../utils/webviewUtils";
import { WebviewProvider } from "../../views/webviewProvider";

const localize: LocalizeFunc = loadMessageBundle();

export namespace SigmaInstallViewCommandIds{
    export const VIEW_APPLY = "apply-button";
    export const VIEW_PREV = "previous-button";
    export const VIEW_FILE_CHANGED = "sigmaFile";
    export const VIEW_BROWSE = "sigma-file-browse";
    
    export const SET_FILE = "set-file";
    export const SET_INITIAL_VALUE = "set-initial-value";
    export const SET_STATUS = "set-status";
    export const SET_CONTINUE_ENABLED = "continue-enabled";
    export const REMOVE_SPINNER = "remove-spinner";

    export const STATUS_LOADING="spin";
    export const STATUS_VALID="valid";
    export const STATUS_INVALID="invalid";
    export const STATUS_CLEAR="clear";
}




export abstract class SigmaInstallPathViewProvider extends WebviewProvider {
    static readonly id: ServiceId<SigmaInstallPathViewProvider> = { id: SigmaInstallPathViewProvider.name };

    abstract reloadHtml(isInstalledToolsMessage: boolean): void;

    abstract dispose(): Promise<void>;
}

export class SigmaInstallPathViewProviderImpl extends SigmaInstallPathViewProvider {
    
    public reloadHtml(isInstalledToolsMessage: boolean): void {
        const messageTitle: string = isInstalledToolsMessage ? localize("code.sight.setup.sigma.location.message.title", "Code Sight Setup: Rapid Scan Static Existing Install") : localize("sigma.install.location.message.title", "Rapid Scan Static Installation Location");
        
        const descriptionPrompt: string = localize("sigma.location.view.prompt", "Please enter the location of your Rapid Scan Static installation");
        const descriptionUnix: string = localize("sigma.location.view.description.unix", "This should be the location of your executable Rapid Scan Static binary");
        const descriptionWindows: string = localize("sigma.location.view.description.windows", "This should be the location of your executable Rapid Scan Static .exe binary");

        const prevButtonText =  isInstalledToolsMessage ? `&lt ${localize('button.previous', 'Previous')}` : localize("close.button", "Close");
        const nextButtonText =  isInstalledToolsMessage ? `${localize('button.continue', 'Continue')} &gt` : localize("apply.button", "Apply");

        let html = `<html>
                    <head>
                        ${this.head}
                    </head>
                    <style>
                        ${this.style}
                    </style>
                    <body>
                    <div id="sigma-location-wrapper">
                        <div class='box'>
                            <img class='blackduck-icon float-left' width="28" height="28"/>
                            <h2 class='float-left margin-left'>${messageTitle}</h2>
                        </div>
                        <p style="font-weight: bold;">${descriptionPrompt}</p>
                        <p>${isWindows() ? descriptionWindows : descriptionUnix}</p>

                        <p id="currentValueDesc" class="hidden" style="font-weight: lighter; font-style: italic"></p>
                        <div class="box">
                            <input id="sigmaLocationInput" type="text" value="" name="sigmaLocationInput" readonly>
                            <button id="${SigmaInstallViewCommandIds.VIEW_BROWSE}" class="button" onclick="handleButtonClick(this);" type="button">${localize('button.browse', 'Change')}</label>
                        </div>
                        <div id="status" class="hidden box">
                            <img id="statusImg" width="15" height="15"/>
                            <div class="margin-left"><b id="statusText"></b></div>
                        </div>
                        
                        <div class="box" id="prev-continue-buttons">
                            <button id="${SigmaInstallViewCommandIds.VIEW_PREV}" class="button button-half" onclick="handleButtonClick(this); addSpinner(this);" type="button">${prevButtonText}</button>
                            <button id="${SigmaInstallViewCommandIds.VIEW_APPLY}" class="button button-half button-disabled" onclick="handleButtonClick(this); addSpinner(this);" type="button" disabled>${nextButtonText}</button>
                        </div>
                        
                        <script>
                            const vscode = acquireVsCodeApi();
                            window.onload = function() {
                                const fileInputText = document.getElementById('sigmaLocationInput');
                                fileInputText.addEventListener('input', (event)=>{
                                    vscode.postMessage({
                                        command: "${SigmaInstallViewCommandIds.VIEW_FILE_CHANGED}",
                                        value: event.target.value,
                                    });
                                });

                            };

                            window.addEventListener('message', event => {
                                const message = event.data;
                                switch (message.command) {
                                    case '${SigmaInstallViewCommandIds.SET_FILE}':
                                        const fileInputText = document.getElementById('sigmaLocationInput');
                                        fileInputText.value = message.value;
                                        fileInputText.title = message.value; // tooltip
                                        break;
                                    case '${SigmaInstallViewCommandIds.SET_INITIAL_VALUE}':
                                        showCurrentConfiguredValue(message.value); 
                                        break;
                                    case '${SigmaInstallViewCommandIds.SET_STATUS}':
                                        showStatusMessage(message.message, message.type);
                                        break;
                                    case '${SigmaInstallViewCommandIds.SET_CONTINUE_ENABLED}':
                                        enableContinueButton(message.enabled);
                                        break;
                                    case '${SigmaInstallViewCommandIds.REMOVE_SPINNER}':
                                        removeSpinner();
                                        break;
                                }
                            });

                            function showCurrentConfiguredValue(value) {
                                const currentValue = document.getElementById('currentValueDesc');
                                if(value){
                                    currentValue.classList.remove("hidden");
                                    currentValue.innerText = "Currently Configured: " + value
                                } else {
                                    currentValue.classList.add("hidden");
                                    currentValue.innerText = ""
                                }
                            }

                            function showStatusMessage(message, type) {
                                let icon;
                                switch (type) {
                                    case "${SigmaInstallViewCommandIds.STATUS_CLEAR}":
                                        clearStatusMessage();
                                        return;
                                    case "${SigmaInstallViewCommandIds.STATUS_LOADING}":
                                        icon = "spinner-icon";
                                        break;
                                    case "${SigmaInstallViewCommandIds.STATUS_INVALID}":
                                        icon = "severity-high";
                                        break;
                                    case "${SigmaInstallViewCommandIds.STATUS_VALID}":
                                        icon = "success-icon";
                                        break;
                                }
        
                                document.querySelector("#status").classList.remove('hidden');
                                document.querySelector("#statusText").innerHTML = message;
                                let statusImg = document.querySelector("#statusImg");
        
                                statusImg.className = "";
                                statusImg.classList.add(icon);
                            }
        
                            function clearStatusMessage() {
                                document.querySelector("#status").classList.add('hidden');
                                document.querySelector("#statusText").innerHTML = "";
                                document.querySelector("#statusImg").className = "";
                            }

                            function enableContinueButton(enable) {
                                const continueButton = document.getElementById('${SigmaInstallViewCommandIds.VIEW_APPLY}');
                                if(enable === "true"){
                                    continueButton.classList.remove("button-disabled");
                                    continueButton.removeAttribute("disabled");
                                } else {
                                    continueButton.classList.add("button-disabled");
                                    continueButton.setAttribute("disabled", "");
                                }
                            }

                            function handleButtonClick(button) {
                                vscode.postMessage({
                                    command: button.id,
                                });
                            }

                            function addSpinner(button) {
                                let spinner = "<img class='spinner-icon margin-left' width='20' height='20'>";
                                button.innerHTML += spinner;
                            }

                            function removeSpinner() {
                                const button = document.getElementById('${SigmaInstallViewCommandIds.VIEW_APPLY}');
                                if (button.innerHTML.includes("img")) {
                                    var buttonHTML = button.innerHTML.split("<img");
                                    button.innerHTML = buttonHTML[0]; // set button text again
                                }
                            }

                        </script>
                    </div>
                    </body>
                    </html>
        `;

        this.webviewPanel!.webview.html = html;
    }
    
    protected getHead(webview: Webview): string {
        return getWebviewHead("Rapid Scan Static Install Location", webview);
    }
    
    protected getStyle(): string {
        return `
            ${BUTTON_STYLING}


            #${SigmaInstallViewCommandIds.VIEW_BROWSE}{
                background-color: var(--vscode-button-background);
                color: var(--vscode-button-foreground);
                padding: 3px 10px;
                cursor: pointer;
                border-width: 1px;
                border-style: solid;
                border-color: var(--vscode-editor-background);
                margin: 2px 5px;
            }

            #sigmaLocationInput {
                width: 60%;
            }

            #${SigmaInstallViewCommandIds.VIEW_BROWSE}:hover {
                background-color: var(--vscode-button-hoverBackground);
            }

            #sigma-location-wrapper {
                min-width: 500px;
                max-width: 600px;
            }

            #status {
                padding-left : 5px;
            }
        `;
    }
    
    dispose(): Promise<void> {
        return this.webviewPanel?.dispose();
    }
}

