import { FileScanInfo, RefreshResultsRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_service_pb";
import { ScanConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/scan_config_pb";
import { ConfigSource } from "@codesight/codesight-controller-proto/controller_proto/v1/issues_service_pb";

export const LocalScanModeContextType = {
    SIGNAL_MANUAL: 'signal-manual',
    CLASSIC_AUTO: 'classic-auto',
    CLASSIC_MANUAL: 'classic-manual'
} as const;

export type LocalScanModeContextType = typeof LocalScanModeContextType[keyof typeof LocalScanModeContextType];

/**
 * Represents the context for a local view scan operation, including what should be scanned
 * and how results should be filtered.
 *
 * This abstraction encapsulates the differences between:
 * - Signal project scans (project-wide AI-based analysis, Project mode subtype with Auto-style loading)
 * - Classic incremental scans (Sigma/License file-scoped analysis)
 * - Classic project scans (user-initiated scans with configurable scope)
 */
export interface LocalScanModeContext {
    /** The type of scan context */
    readonly contextType: LocalScanModeContextType;

    /** Scan types that should be loaded in this context */
    readonly scanTypes: ScanConfig.ScanType.Type[];

    /** Whether the active file filter toggle should be shown in the UI */
    readonly shouldShowActiveFileFilterUI: boolean;

    /**
     * Create ConfigSource objects for each scan type in this context.
     * Each ConfigSource specifies the source (AUTO/MANUAL) and scan type.
     * Returns an empty array for contexts that don't use ConfigSource directly (e.g., Project mode).
     */
    createConfigSources(): ConfigSource[];

    /**
     * Get the appropriate ConfigSource for fetching issue details.
     * This is used when retrieving detailed information about a specific issue.
     *
     * @param isLicenseIssue - Whether the issue is a license/Black Duck issue (vs Sigma/Signal)
     * @returns ConfigSource for the issue details request, or undefined if not applicable
     */
    getConfigSourceForIssueDetails(isLicenseIssue: boolean): ConfigSource | undefined;

    /**
     * Check if this is an auto-scan context (Classic Auto, or Signal which uses Auto-style loading).
     * Auto contexts load results automatically based on file activity.
     */
    isAutoContext(): boolean;

    /**
     * Check if this is a project scan context.
     * Manual contexts only load results from user-initiated scans.
     */
    isManualContext(): boolean;
}

/**
 * Signal view context - loads only Signal project scan results (uses Auto-style loading).
 * Signal scans return project-wide results (not filtered to active file),
 * but still require the active file path for context.
 */
export class SignalManualScanContext implements LocalScanModeContext {
    readonly contextType = LocalScanModeContextType.SIGNAL_MANUAL;
    readonly scanTypes = [ScanConfig.ScanType.Type.SIGNAL];
    readonly shouldShowActiveFileFilterUI = false;

    private readonly tier: RefreshResultsRequest.Tier;

    constructor(tier: RefreshResultsRequest.Tier) {
        this.tier = tier;
    }

    createConfigSources(): ConfigSource[] {
        const configSource = new ConfigSource();
        configSource.setSource(FileScanInfo.Source.AUTO);
        configSource.setTier(this.tier);

        const scanType = new ScanConfig.ScanType();
        scanType.setType(ScanConfig.ScanType.Type.SIGNAL);
        configSource.setScantype(scanType);

        return [configSource];
    }

    getConfigSourceForIssueDetails(_isLicenseIssue: boolean): ConfigSource {
        return this.createConfigSources()[0];
    }

    isAutoContext(): boolean {
        return true;
    }

    isManualContext(): boolean {
        return false;
    }
}

/**
 * Classic incremental mode context - loads Sigma and/or License incremental scan results.
 * Both are file-scoped scans that filter to the active file.
 */
export class ClassicAutoScanContext implements LocalScanModeContext {
    readonly contextType = LocalScanModeContextType.CLASSIC_AUTO;
    readonly shouldShowActiveFileFilterUI = true;

    private readonly isSigmaEntitled: boolean;
    private readonly isLicenseEntitledAndEnabled: boolean;
    private readonly fileScope: RefreshResultsRequest.Tier;

    constructor(isSigmaEntitled: boolean, isLicenseEntitledAndEnabled: boolean, fileScope: RefreshResultsRequest.Tier) {
        this.isSigmaEntitled = isSigmaEntitled;
        this.isLicenseEntitledAndEnabled = isLicenseEntitledAndEnabled;
        this.fileScope = fileScope;
    }

    get scanTypes(): ScanConfig.ScanType.Type[] {
        const types: ScanConfig.ScanType.Type[] = [];
        // Note: Sigma uses undefined scanType in ConfigSource, so we don't add it here
        // Only License uses an explicit BLACKDUCK scanType
        if (this.isLicenseEntitledAndEnabled) {
            types.push(ScanConfig.ScanType.Type.BLACKDUCK);
        }
        return types;
    }

    createConfigSources(): ConfigSource[] {
        const sources: ConfigSource[] = [];

        if (this.isSigmaEntitled) {
            const sigmaSource = new ConfigSource();
            sigmaSource.setSource(FileScanInfo.Source.AUTO);
            this.setSigmaTier(sigmaSource);
            sources.push(sigmaSource);
        }

        if (this.isLicenseEntitledAndEnabled) {
            const licenseSource = new ConfigSource();
            licenseSource.setSource(FileScanInfo.Source.AUTO);

            const scanType = new ScanConfig.ScanType();
            scanType.setType(ScanConfig.ScanType.Type.BLACKDUCK);
            licenseSource.setScantype(scanType);

            sources.push(licenseSource);
        }

        return sources;
    }

    getConfigSourceForIssueDetails(isLicenseIssue: boolean): ConfigSource {
        if (isLicenseIssue) {
            const licenseSource = new ConfigSource();
            licenseSource.setSource(FileScanInfo.Source.AUTO);
            const scanType = new ScanConfig.ScanType();
            scanType.setType(ScanConfig.ScanType.Type.BLACKDUCK);
            licenseSource.setScantype(scanType);
            return licenseSource;
        } else {
            const sigmaSource = new ConfigSource();
            this.setSigmaTier(sigmaSource);
            sigmaSource.setSource(FileScanInfo.Source.AUTO);
            return sigmaSource;
        }
    }

    private setSigmaTier(sigmaSource: ConfigSource) {
        switch (this.fileScope) {
            case RefreshResultsRequest.Tier.ALLUNCOMMITTED:
            case RefreshResultsRequest.Tier.REFERENCEBRANCH:
                sigmaSource.setTier(this.fileScope);
                break;
            case RefreshResultsRequest.Tier.UNKNOWNTIER:
            case RefreshResultsRequest.Tier.ULTRAQUICK:
            case RefreshResultsRequest.Tier.FAST:
            case RefreshResultsRequest.Tier.FULL:
            default:
                sigmaSource.setTier(RefreshResultsRequest.Tier.UNKNOWNTIER);
        }
    }

    isAutoContext(): boolean {
        return true;
    }

    isManualContext(): boolean {
        return false;
    }
}

/**
 * Classic project scan context - loads results from user-initiated scans.
 * File filtering depends on user preferences (active file filter toggle).
 */
export class ClassicManualScanContext implements LocalScanModeContext {
    readonly contextType = LocalScanModeContextType.CLASSIC_MANUAL;
    readonly scanTypes: ScanConfig.ScanType.Type[] = [];
    readonly shouldShowActiveFileFilterUI = true;

    createConfigSources(): ConfigSource[] {
        // Project mode doesn't use this - it gets ConfigSource from selected scan config
        return [];
    }

    getConfigSourceForIssueDetails(_isLicenseIssue: boolean): undefined {
        // Project mode doesn't use this method - ConfigSource comes from selected scan config
        return undefined;
    }

    isAutoContext(): boolean {
        return false;
    }

    isManualContext(): boolean {
        return true;
    }
}
