export const TEAM_VIEW_TREE_OCCURRENCE_SELECTED_COMMAND_ID = "codesight.team.view.tree.item.occurrence.selected";
export const TEAM_VIEW_TREE_EVENT_SELECTED_COMMAND_ID = "codesight.team.view.tree.tree.item.event.selected";
export const COMMAND_SHOW_REMOTE_ISSUE_LIST_ERROR = "codesight.open.remote.issue.list.error";
export const SORT_VISIBLE_CONTEXT = "codesight.team.view.issue.sort.visible";

const localize: LocalizeFunc = loadMessageBundle();

export class TeamViewPresenter implements IssueSourceConfigServiceListener, AuthenticationServiceListener, IssuesListServiceListener, TeamViewIssueListFilterServiceListener, MarkerEventDetailsCapable {
    private treeProvider: TeamViewTreeProvider;
    private treeView: TreeView<TreeNodeProvider>;
    private latestDetailsSelection: number = Date.now();
    private lastActiveFilePath: string | undefined;
    protected viewLock = new Semaphore(0, 1);
    private isInSimpleViewMode: boolean = false;
    private previousFullState: TeamViewIssueFoundTreeState | undefined = undefined;
    private currentSimpleViewParams: {
        issue: NewIssue;
        totalIssueCount: number;
        pageControls: PageControls;
    } | undefined = undefined;

    commandDisposables: Disposable[];

    constructor(treeProvider: TeamViewTreeProvider, treeView: TreeView<TreeNodeProvider>) {
        this.treeProvider = treeProvider;
        this.treeView = treeView;
        this.treeView.onDidExpandElement(event => this.onDidExpandElement(event));
        this.commandDisposables = [];

        getService(TeamViewIssuesListService.id).addListener(this);
        getService(IssueSourceConfigService.id).addListener(this);
        getService(AuthenticationService.id).addListener(this);
        getService(TeamViewIssueListFilterService.id).addListener(this);

        this.initCommands();
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        commands.executeCommand(REFRESH_REMOTE_ISSUES);
    }

    dispose() {
        this.commandDisposables.forEach(disposable => disposable.dispose());
        getService(TeamViewIssuesListService.id).removeListener(this);
        getService(IssueSourceConfigService.id).removeListener(this);
        getService(AuthenticationService.id).removeListener(this);
        getService(TeamViewIssueListFilterService.id).removeListener(this);
    }

    updateViewTitle(shouldShowIssueCount?: boolean) {
        const issueService = getService(TeamViewIssuesListService.id);
        let title = TEAM_VIEW_TITLE;

        let totalIssueCount = issueService.getTotalIssueCount();
        if (shouldShowIssueCount && totalIssueCount) {
            let currentIssueCount = issueService.getCurrentIssueCount();
            title += ` (${currentIssueCount} of ${totalIssueCount})`;
        }

        this.treeView.title = title;
    }

    async onIssuesReloaded(issuesListIdentifier: IssuesListIdentifier): Promise<void> {
        if (issuesListIdentifier !== IssuesListIdentifier.TeamViewIssuesList) {
            return;
        }

        await this.reloadTreeProvider();
    }

    async onDidExpandElement(event: TreeViewExpansionEvent<TreeNodeProvider>) {
        if (event.element instanceof IssueNode) {
            if (event.element.issue.getEventInfo()?.hasError()) {
                event.element.issue.setEventInfo(undefined);
                await this.treeProvider.reloadNode(event.element);
            }
            await getService(TeamViewIssuesListService.id).loadIssueEventInformation(event.element.issue.getIssueId(), event.element.issue.getDisplayType());
            await this.treeProvider.reloadNode(event.element);
        }
    }

    async onAuthenticated(serverType: ServerType): Promise<void> {
        if (TEAM_VIEW_SERVERS.includes(serverType)) {
            let selectedSource = getService(IssueSourceConfigService.id).getSelectedSource();
            if (selectedSource && selectedSource.serverType === serverType) {
                await this.showTreeViewSpinner();
                await getService(IssueSelectionService.id).clearSelection(IssuesListIdentifier.TeamViewIssuesList);
                await getService(TeamViewIssueListFilterService.id).refreshCachedFilters();
                await getService(TeamViewIssuesListService.id).refreshIssues();
            }
            await this.reloadTreeProvider();
        }
    }

    public async revealTreeForEvent(teamViewEvent: NewEvent) {
        let issue = teamViewEvent.getParentIssue();
        let revealIssue = new IssueNode(IssuesListIdentifier.TeamViewIssuesList, issue, undefined, undefined, false);
        let revealOccurrence = new OccurrenceNode(IssuesListIdentifier.TeamViewIssuesList, teamViewEvent.getParentContributingDetail(), revealIssue);

        let revealEvent;
        if (issue.getEventInfo()?.getContributingDetails() && issue.getEventInfo()?.getContributingDetails().length === 1) {
            revealEvent = new EventNode(IssuesListIdentifier.TeamViewIssuesList, teamViewEvent, revealIssue);
        } else {
            revealEvent = new EventNode(IssuesListIdentifier.TeamViewIssuesList, teamViewEvent, revealOccurrence);
        }

        await this.treeView.reveal(revealEvent, {
            select: true,
            focus: true,
        });
    }

    public async revealTreeForIssue(issue: NewIssue) {
        let revealIssue = new IssueNode(IssuesListIdentifier.TeamViewIssuesList, issue, undefined, undefined, false);
        const visible = this.treeView.visible;
        await this.treeView.reveal(revealIssue, {
            select: true,
            focus: true,
            expand: true,
        });
        if (!visible) {
            await this.treeView.reveal(revealIssue, {
                select: true,
                focus: true,
                expand: true,
            });
        }
    }

    public async revealTreeForOccurrence(issue: NewIssue, detail: ContributingDetail) {
        let revealIssue = new IssueNode(IssuesListIdentifier.TeamViewIssuesList, issue, undefined, undefined, false);
        let revealOccurrence = new OccurrenceNode(IssuesListIdentifier.TeamViewIssuesList, detail, revealIssue);
        await this.treeView.reveal(revealOccurrence, {
            select: true,
            focus: true,
            expand: true,
        });
    }

    async onSelectedSourceChanged(): Promise<void> {
        await this.showTreeViewSpinner();
        await getService(IssueSelectionService.id).clearSelection(IssuesListIdentifier.TeamViewIssuesList);
        await getService(TeamViewIssueListFilterService.id).refreshCachedFilters();
        await getService(TeamViewIssuesListService.id).refreshIssues();
    }

    async onIssueSourceListUpdated(): Promise<void> {
        await this.reloadTreeProvider();
    }

    async showTreeViewSpinner() {
        this.latestDetailsSelection = Date.now();
        await this.reloadTreeProvider(true);
    }

    async reloadTreeProviderSimple(issue: NewIssue) {
        // Capture current full state before entering simple view
        let baseState: TeamViewIssueFoundTreeState;
        if (!this.isInSimpleViewMode && this.previousFullState === undefined) {
            // Build current state that would be used for full view
            baseState = await this.buildCurrentFullState();
            this.previousFullState = baseState;
        } else {
            baseState = this.previousFullState || await this.buildCurrentFullState();
        }

        this.isInSimpleViewMode = true;

        // Set context to indicate we're entering simple view
        await commands.executeCommand('setContext', 'codesight.teamViewSimpleView', true);

        // Store the simple view parameters for future updates
        this.currentSimpleViewParams = {
            issue: issue,
            totalIssueCount: 1,
            pageControls: new IssueListActions(async () => {}, () => false, () => undefined)
        };

        await this.treeProvider.reloadViewSimple([issue], 1, new IssueListActions(async () => { }, () => false, () => undefined), baseState);
    }

    async reloadTreeProvider(loading: boolean = false) {
        // When in simple view mode, update both states and reload with simple view parameters
        if (this.isInSimpleViewMode) {
            // Update the state we'll restore to when exiting simple view
            this.previousFullState = await this.buildCurrentFullState();

            // Reload the simple view with the stored parameters
            if (this.currentSimpleViewParams && this.previousFullState) {
                await this.treeProvider.reloadViewSimple(
                    [this.currentSimpleViewParams.issue],
                    this.currentSimpleViewParams.totalIssueCount,
                    this.currentSimpleViewParams.pageControls,
                    this.previousFullState
                );
            }
            return;
        }

        const state = await this.buildCurrentFullState(loading);

        await this.treeProvider.reloadView(state);

        let shouldShowIssueCount = this.treeProvider.isShowingIssues();
        let columnInfos = await getService(TeamViewIssuesListService.id).getIssueListStructure();
        let isSortSupported = columnInfos.some(columnInfo => {
            return columnInfo.getSupportssorting() === true;
        });
        
        await commands.executeCommand("setContext", SORT_VISIBLE_CONTEXT, (isSortSupported && shouldShowIssueCount));
        this.updateViewTitle(shouldShowIssueCount);
    }

    private async buildCurrentFullState(loading: boolean = false): Promise<TeamViewIssueFoundTreeState> {
        let issuesList = await getService(TeamViewIssuesListService.id).getIssues();
        let sourceList = await getService(IssueSourceConfigService.id).getConfiguredIssueSourceList();
        let possibleSelectedSource = getService(IssueSourceConfigService.id).getSelectedSource();
        let selectedSource;
        if (possibleSelectedSource && TEAM_VIEW_SERVERS.includes(possibleSelectedSource?.serverType)) {
            selectedSource = possibleSelectedSource;
        }

        const authenticationService = getService(AuthenticationService.id);
        let availableServers: ServerInfo[] = authenticationService.getAvailableTeamViewServerInfos();

        return {
            issuesList,
            availableServers,
            sourceList,
            selectedSource,
            loading,
        };
    }

    private async restorePreviousFullState(): Promise<void> {
        if (this.previousFullState) {
            // Reset simple view mode tracking
            this.isInSimpleViewMode = false;

            // Set context to indicate we're leaving simple view
            await commands.executeCommand('setContext', 'codesight.teamViewSimpleView', false);

            // Clear the tree first to reset expansion state
            await this.treeProvider.reloadView({
                ...this.previousFullState,
                issuesList: [],
                loading: true
            });

            // Small delay to allow tree to clear
            await new Promise(resolve => setTimeout(resolve, 50));

            // Get the most current state (not the stale previousFullState)
            const currentState = await this.buildCurrentFullState();

            // Reload with current state - all nodes will be collapsed
            await this.treeProvider.reloadView(currentState);

            // Clear both states
            this.previousFullState = undefined;
            this.currentSimpleViewParams = undefined;

            // Update title
            let shouldShowIssueCount = this.treeProvider.isShowingIssues();
            this.updateViewTitle(shouldShowIssueCount);
        } else {
            // Fallback to refresh if no previous state is available
            this.isInSimpleViewMode = false;
            this.currentSimpleViewParams = undefined;
            await commands.executeCommand('setContext', 'codesight.teamViewSimpleView', false);
            await this.showTreeViewSpinner();
            this.updateViewTitle();
            await getService(IssueSourceConfigService.id).refreshConfiguredSourceList();
            await getService(TeamViewIssueListFilterService.id).refreshCachedFilters();
            await getService(TeamViewIssuesListService.id).refreshIssues();
        }
    }

    async onIssueSourceSelected(): Promise<void> {
        let menuItems = await this.issueSourceSelect();
        let selectedItem = await getService(VsCodeInputService.id).showQuickPick(menuItems);
        if (!selectedItem) {
            // nothing was selected. Do nothing
            return Promise.resolve();
        }
        return selectedItem.onSelectedCallback();
    }

    private async issueSourceSelect(): Promise<(IssueSourceQuickPickItem | ServerSeparatorQuickPickItem)[]> {
        let sourceItems: (IssueSourceQuickPickItem | ServerSeparatorQuickPickItem)[] = [];
        let serverTypeToIssueSources = new Map<ServerType, IssueSourceQuickPickItem[]>();
        TEAM_VIEW_SERVERS.forEach(serverType => {
            serverTypeToIssueSources.set(serverType, []);
        });

        let configuredSources = await getService(IssueSourceConfigService.id).getConfiguredIssueSourceList();
        let selectedSource = getService(IssueSourceConfigService.id).getSelectedSource();
        configuredSources.forEach(source => {
            // todo: switch to source id comparison once controller changes are merged
            let isSourceSelected = selectedSource?.sourceID === source.sourceID;
            let sourceItem = new IssueSourceQuickPickItem(isSourceSelected, source, async () => {
                // eslint-disable-next-line @typescript-eslint/no-floating-promises
                commands.executeCommand(COMMAND_SELECT_SOURCE, source);
            });

            serverTypeToIssueSources.get(source.serverType)?.push(sourceItem);
        });

        for (const [serverType, issueSources] of serverTypeToIssueSources) {
            if (issueSources.length > 0) {
                sourceItems.push(new ServerSeparatorQuickPickItem(serverType));
                sourceItems = sourceItems.concat(issueSources);
            }
        }

        return sourceItems;
    }

    async onShowServerConfigSelected(): Promise<void> {
        let configItems: ServerConfigQuickPickItem[] = TEAM_VIEW_SERVERS.map(server => {
            return new ServerConfigQuickPickItem(server);
        });

        let selectedItem = await getService(VsCodeInputService.id).showQuickPick(configItems);
        if (!selectedItem) {
            // nothing was selected. Do nothing
            return Promise.resolve();
        }
        return selectedItem.onSelectedCallback();
    }

    async onSortIssuesSelected(): Promise<void> {
        let menuItems: TeamViewSortQuickPickItem[] = [];
        menuItems = await this.constructSortItems();
        let selectedItem = await getService(VsCodeInputService.id).showQuickPick(menuItems);
        if (!selectedItem) {
            // nothing was selected. Do nothing
            return Promise.resolve();
        }
        return selectedItem.onSelectedCallback();
    }

    async constructSortItems(): Promise<TeamViewSortQuickPickItem[]> {
        const filterService = getService(TeamViewIssueListFilterService.id);
        const issueService = getService(TeamViewIssuesListService.id);
        let selectedSource = getService(IssueSourceConfigService.id).getSelectedSource();
        let serverType = selectedSource!.serverType;
        let currentSortState = filterService.getSortState(serverType);

        let sortFunction = async (selectedSort: NewIssueSortState) => {
            await this.showTreeViewSpinner();
            await getService(IssueSelectionService.id).clearSelection(IssuesListIdentifier.TeamViewIssuesList);
            if (currentSortState.id === selectedSort.id) {
                // inverse the sort
                currentSortState.isAscending = !currentSortState.isAscending;
            } else {
                // sort descending by the new sort field
                currentSortState.isAscending = selectedSort.isDefaultSortAscending;
                currentSortState.sortName = selectedSort.sortName;
                currentSortState.id = selectedSort.id;
            }
            await filterService.persistSort(currentSortState, serverType);
            return issueService.refreshIssues();
        };

        let sortItems: TeamViewSortQuickPickItem[] = [
            new TeamViewSortQuickPickItem(localize("filter.menu.group.sorts", "Sorting"), "", () => {
                return Promise.resolve();
            })
        ];

        let sortOptions = await filterService.getSortOptions();
        sortOptions.forEach(option => {
            sortItems.push(new TeamViewSortQuickPickItem(`${currentSortState.id === option.id ? (currentSortState.isAscending ? "$(arrow-up)" : "$(arrow-down)") : ""}\t${localize("filter.selector.sort.text", "Sort:")} ${option.sortName}`, `${currentSortState.id === option.id ? localize("filter.invert.sort.description.text", "Click to invert sort order") : ""}`, () => {
                return sortFunction(option);
            }));
        });

        return sortItems;
    }

    async onShowRemoteErrorDetailsClicked(error: Error): Promise<void> {
        if (error) {
            let notification = createNotificationBasedOnControllerError(error);
            await getService(WebviewCoordinator.id).showDefaultNotification(notification);
        }
    }

    async onInverseSortSelected(): Promise<void> {
        await this.showTreeViewSpinner();
        await getService(IssueSelectionService.id).clearSelection(IssuesListIdentifier.TeamViewIssuesList);
        let selectedSource = getService(IssueSourceConfigService.id).getSelectedSource();
        let serverType = selectedSource!.serverType;
        const filterService = getService(TeamViewIssueListFilterService.id);
        let sortState = filterService.getSortState(serverType);
        sortState.isAscending = !sortState.isAscending;
        await filterService.persistSort(sortState, serverType);
        await getService(TeamViewIssuesListService.id).refreshIssues();
    }
    async showIssueDetailsLoading() {
        await getService(IssueSelectionService.id).clearSelection(IssuesListIdentifier.TeamViewIssuesList);
        await getService(WebviewCoordinator.id).showIssueDetailsForDomain(IssuesListIdentifier.TeamViewIssuesList);
    }

    async onIssueSelectedInTree(issueId: string, issuesList: IssuesListIdentifier, displayType: DisplayType): Promise<void> {
        await this.onSelectionInTree(issueId, displayType,
            async () => {
                await getService(EditorDecorationService.id).navigate(IssuesListIdentifier.TeamViewIssuesList, issueId, displayType);
            },
            async () => {
                await getService(IssueSelectionService.id).selectNewIssue(issueId, issuesList, displayType);
            });
    }

    async onOccurrenceSelectedInTree(selectedOccurrence: ContributingDetail): Promise<void> {
        let issueId = selectedOccurrence.getParentIssue().getIssueId();
        let occurrenceIndex = selectedOccurrence.getContributingDetailIndex();
        const displayType = selectedOccurrence.getParentIssue().getDisplayType();
        await this.onSelectionInTree(issueId, displayType,
            async () => {
                await getService(EditorDecorationService.id).navigate(IssuesListIdentifier.TeamViewIssuesList, issueId, displayType, occurrenceIndex);
            },
            async () => {
                await getService(IssueSelectionService.id).selectNewOccurrence(issueId, occurrenceIndex, IssuesListIdentifier.TeamViewIssuesList, displayType);
            });
    }

    async onEventSelectedInTree(selectedEvent: NewEvent): Promise<void> {
        let eventNumber = selectedEvent.getEventNumber();
        let occurrenceIndex = selectedEvent.getParentContributingDetail().getContributingDetailIndex();
        let issueId = selectedEvent.getParentIssue().getIssueId();
        const displayType = selectedEvent.getParentIssue().getDisplayType();
        let issueLocation = selectedEvent.getLocation();
        await this.onSelectionInTree(issueId, displayType,
            async () => {
                await getService(EditorDecorationService.id).navigate(IssuesListIdentifier.TeamViewIssuesList, issueId, displayType, occurrenceIndex, eventNumber, issueLocation);
            },
            async () => {
                await getService(IssueSelectionService.id).selectNewEvent(issueId, occurrenceIndex, eventNumber, IssuesListIdentifier.TeamViewIssuesList, displayType);
            });
    }

    async onSelectionInTree(issueId: string, displayType: DisplayType, navigateToIssueInFile: () => Promise<void>, selectIssue: () => Promise<void>) {
        await this.showIssueDetailsLoading();
        let issue = await getService(TeamViewIssuesListService.id).getIssue(issueId, displayType);

        let currentDetailsSelection = Date.now();
        this.latestDetailsSelection = currentDetailsSelection;


        await getService(TeamViewIssuesListService.id).loadDetailsAndEventsForIssue(issue);
        if (this.latestDetailsSelection <= currentDetailsSelection) {
            const isEditorMarkersEnabled = getService(MarkerService.id).getIsEditorMarkersEnabled();
            await selectIssue();
            await navigateToIssueInFile();
            if (!isEditorMarkersEnabled) {
                await getService(EditorDecorationService.id).addIssueDecorationToEditor([issue!]);
            }
            if (isFeatureFlagEnabled(ENV_CODESIGHT_EDITOR_MARKERS) && isEditorMarkersEnabled && getService(MarkerService.id).getCurrentMarkerView() !== MarkerView.Team) {
                await getService(IssueSelectionService.id).clearSelection(IssuesListIdentifier.LocalViewIssuesList);
                if (getService(ScanStatusCoordinator.id).getCurrentScanMode() === ScanMode.Auto) {
                    await getService(ViewProviderService.id).getOrCreateLocalViewPresenter().restorePreviousFullState();
                }
                await getService(MarkerService.id).setMarkerView(MarkerView.Team, true);
            }
            await getService(WebviewCoordinator.id).showIssueDetailsForDomain(IssuesListIdentifier.TeamViewIssuesList);
        }
    }

    async onFiltersChanged(): Promise<void> {
        await this.showTreeViewSpinner();
        await getService(IssueSelectionService.id).clearSelection(IssuesListIdentifier.TeamViewIssuesList);
        await getService(TeamViewIssuesListService.id).refreshIssues();
    }

    private initCommands() {
        this.commandDisposables.push(commands.registerCommand(TEAM_VIEW_TREE_ITEM_SELECTED_COMMAND_ID, async (issueId: string, issuesList: IssuesListIdentifier, displayType: DisplayType): Promise<void> => {
            await this.onIssueSelectedInTree(issueId, issuesList, displayType);
        }));

        this.commandDisposables.push(commands.registerCommand(TEAM_VIEW_TREE_OCCURRENCE_SELECTED_COMMAND_ID, async (occurrence: ContributingDetail) => {
            await this.onOccurrenceSelectedInTree(occurrence);
        }));

        this.commandDisposables.push(commands.registerCommand(TEAM_VIEW_TREE_EVENT_SELECTED_COMMAND_ID, async (event: NewEvent) => {
            await this.onEventSelectedInTree(event);
        }));

        this.commandDisposables.push(commands.registerCommand(REFRESH_REMOTE_ISSUES, async (clearIssueSelection: boolean = true) => {
            if (isFeatureFlagEnabled(ENV_CODESIGHT_EDITOR_MARKERS)) {
                if (clearIssueSelection) {
                    this.isInSimpleViewMode = false;
                    await getService(IssueSelectionService.id).clearSelection(IssuesListIdentifier.TeamViewIssuesList);
                    await vscode.commands.executeCommand('setContext', 'codesight.teamViewSimpleView', false);
                }
                this.latestDetailsSelection = Date.now();
                void getService(MarkerService.id).loadMarkersForActiveFile();
            } else {
                await getService(IssueSelectionService.id).clearSelection(IssuesListIdentifier.TeamViewIssuesList);
            }
            // Show spinner and refresh - trigger the "Refreshing issues list" message
            await this.showTreeViewSpinner();
            this.updateViewTitle();

            await getService(IssueSourceConfigService.id).refreshConfiguredSourceList();
            await getService(TeamViewIssueListFilterService.id).refreshCachedFilters();
            return getService(TeamViewIssuesListService.id).refreshIssues();
        }));

        this.commandDisposables.push(commands.registerCommand(COMMAND_TEAM_VIEW_RESTORE_FULL_LIST, async () => {
            this.latestDetailsSelection = Date.now();
            await getService(IssueSelectionService.id).clearSelection(IssuesListIdentifier.TeamViewIssuesList);
            void getService(MarkerService.id).loadMarkersForActiveFile();

            // Restore to previous full state managed by presenter
            await this.restorePreviousFullState();
        }));

        this.commandDisposables.push(commands.registerCommand(COMMAND_SHOW_CONFIGURED_SOURCES, () => {
            return this.onIssueSourceSelected();
        }));
        this.commandDisposables.push(commands.registerCommand(COMMAND_SHOW_ISSUE_SOURCE_SERVER_CONFIG, () => {
            return this.onShowServerConfigSelected();
        }));
        this.commandDisposables.push(commands.registerCommand(COMMAND_SORT_TEAM_VIEW_ISSUES, () => {
            return this.onSortIssuesSelected();
        }));
        this.commandDisposables.push(commands.registerCommand(COMMAND_SELECT_SOURCE, async (issueSource: RemoteIssueSource) => {
            await this.showTreeViewSpinner();
            return getService(IssueSourceConfigService.id).setSelectedSource(issueSource);
        }));
        this.commandDisposables.push(commands.registerCommand(COMMAND_SHOW_REMOTE_ISSUE_LIST_ERROR, (error: Error | IssueTreeItem) => {
            let err = error instanceof Error ? error : error.error;
            return this.onShowRemoteErrorDetailsClicked(err!);
        }));
        this.commandDisposables.push(commands.registerCommand(COMMAND_LOCK_REMOTE_ISSUE, async (treeNode?: any) => {
            if (treeNode && treeNode.issue) {
                const issue: NewIssue = treeNode.issue;
                const issueId = issue.getIssueId();
                const displayType = issue.getDisplayType();

                await this.onSelectionInTree(issueId, displayType,
                    async () => {
                        await getService(EditorDecorationService.id).navigate(IssuesListIdentifier.TeamViewIssuesList, issueId, displayType);
                    },
                    async () => {
                        await getService(IssueSelectionService.id).selectNewIssue(issueId, IssuesListIdentifier.TeamViewIssuesList, displayType);
                });

                await this.reloadTreeProviderSimple(issue);
                this.updateViewTitle(true);
                await this.revealTreeForIssue(issue);
            } else {
                getLogger().warn('No issue found in tree node');
            }
        }));
        this.commandDisposables.push(commands.registerCommand(COMMAND_OPEN_TEAM_VIEW_FILTER_VIEW__FILTERS_APPLIED, async () => {
            await getService(WebviewCoordinator.id).showTeamViewFilter();
        }));
        this.commandDisposables.push(commands.registerCommand(COMMAND_OPEN_TEAM_VIEW_FILTER_VIEW__NO_FILTERS_APPLIED, async () => {
            await getService(WebviewCoordinator.id).showTeamViewFilter();
        }));

        if (isFeatureFlagEnabled(ENV_CODESIGHT_EDITOR_MARKERS)) {
            this.commandDisposables.push(commands.registerCommand(COMMAND_OPEN_TEAM_VIEW_FILTER_VIEW__DISABLE_ACTIVE_FILE_FILTER, async () => {
                await this.toggleActiveFileFilter();
            }));
            this.commandDisposables.push(commands.registerCommand(COMMAND_OPEN_TEAM_VIEW_FILTER_VIEW__ENABLE_ACTIVE_FILE_FILTER, async () => {
                await this.toggleActiveFileFilter();
            }));
            this.commandDisposables.push(window.onDidChangeActiveTextEditor(this.debouncedHandleActiveEditorChange));
        }
    }

    private debouncedHandleActiveEditorChange = debounce(async (editor: TextEditor | undefined) => {
        try {
            const selectedSource = getService(IssueSourceConfigService.id).getSelectedSource();
            if (!selectedSource?.serverType) {
                return;
            }

            const reloadResult = shouldReloadForEditorChange(editor, this.lastActiveFilePath);
            if (!reloadResult.shouldReload) {
                return;
            }
            if (reloadResult.newFilePath !== undefined) {
                this.lastActiveFilePath = reloadResult.newFilePath;
            }

            const filterService = getService(TeamViewIssueListFilterService.id);
            const activeFileFilterEnabled = filterService.getActiveFileFilter(selectedSource.serverType);

            if (activeFileFilterEnabled) {
                await commands.executeCommand(REFRESH_REMOTE_ISSUES, !this.isInSimpleViewMode);
            }
        } catch (e) {
            getLogger().error('Failed to load team view issue list for active editor', e);
        }
    }, 300);


    public getTreeView() {
        return this.treeView;
    }

    public setLatestDetailsSelection(timestamp: number): void {
        this.latestDetailsSelection = timestamp;
    }

    public getLatestDetailsSelection(): number {
        return this.latestDetailsSelection;
    }

    private async toggleActiveFileFilter(): Promise<void> {
        const selectedSource = getService(IssueSourceConfigService.id).getSelectedSource();
        if (!selectedSource?.serverType) {
            return;
        }

        const filterService = getService(TeamViewIssueListFilterService.id);
        const currentState = filterService.getActiveFileFilter(selectedSource.serverType);
        await filterService.setActiveFileFilter(!currentState, selectedSource.serverType);

        await commands.executeCommand(REFRESH_REMOTE_ISSUES);
    }
}

class ServerConfigQuickPickItem implements QuickPickItem {
    label: string;
    serverType: ServerType;
    onSelectedCallback = () => Promise.resolve();

    constructor(serverType: ServerType) {
        this.serverType = serverType;
        this.label = `$(add)\tConfigure ${getServerName(serverType)} server`;
        this.onSelectedCallback = async () => {
            await this.openServerConfigView();
        };
    }

    async openServerConfigView() {
        switch (this.serverType) {
            case ServerType.POLARIS:
                await getService(WebviewCoordinator.id).showEditPolarisServerConfiguration();
                break;
            case ServerType.SOFTWARERISKMANAGER:
                await getService(WebviewCoordinator.id).showEditSRMServerConfiguration();
                break;
            case ServerType.COVERITYCONNECT:
            case ServerType.COVERITYONPOLARIS:
                await getService(WebviewCoordinator.id).showEditCoverityServerConfiguration();
                break;
        }
    }
}

