import { RefreshResultsRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_service_pb";
import { ValidateLLMKeyRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/configuration_service_pb";
import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { Disposable, WebviewPanel } from "vscode";
import { LocalizeFunc, loadMessageBundle } from "vscode-nls";
import { ProxyEventListener, ProxyEventService } from "../../services/ProxyEventService";
import { ControllerClientService } from "../../services/controllerClientService";
import { EntitlementService } from "../../services/entitlementService";
import { ScanMode, ScanStatusCoordinator } from "../../services/scanStatusCoordinator";
import { getService } from "../../services/serviceContainer";
import { VscodeContextService } from "../../services/vscodeContextService";
import { getLogger } from "../../utils/logger";
import { ProxyComponentCommandIds, handleProxyUpdate, openProxySettings } from "../../views/proxy/proxyConfigComponent";
import { WebviewCoordinator } from "../webviewCoordinator";
import { WebviewPresenter } from "../webviewPresenter";
import { SignalLLMKeyValidationViewCommandIds, SignalLLMKeyValidationViewProvider } from "./signalLLMKeyValidationViewProvider";

const localize: LocalizeFunc = loadMessageBundle();

export class SignalLLMKeyValidationViewPresenter implements WebviewPresenter, ProxyEventListener {
    private view: SignalLLMKeyValidationViewProvider;
    private onMessageFromWebviewDisposable: Disposable | undefined;

    constructor(panel: WebviewPanel) {
        this.view = getService(SignalLLMKeyValidationViewProvider.id);
        this.view.initView(panel);

        getService(ProxyEventService.id).addListener(this);

        this.onMessageFromWebviewDisposable = this.view.onMessageFromWebview(async message => {
            switch (message.command) {
                case SignalLLMKeyValidationViewCommandIds.VALIDATE_LLM_KEY:
                    await this.validateLLMKey(message.llmKey);
                    break;
                case ProxyComponentCommandIds.OPEN_PROXY_SETTINGS:
                    openProxySettings();
                    break;
                default:
                    getLogger().warn(`Received unexpected message ${message.command}`);
                    break;
            }

            return Promise.resolve();
        });
    }

    private async validateLLMKey(llmKey: string) {
        this.setLoadingState(localize('signal.llm.key.validation.inprogress', 'Validating LLM key'));
        
        try {
            const configService = await getService(ControllerClientService.id).getConfigurationServiceClient();
            const request = new ValidateLLMKeyRequest();
            request.setLlmkey(llmKey);
            request.setLlmuri(''); // Set empty URI as we only have the key from the input
            
            const response = await configService.validateLLMKey(request);
            
            if (response.getIsvalid()) {
                this.setSuccessState(localize('signal.llm.key.validation.success', 'LLM key validation successful'));
                // Call enableSignalProduct on success
                await this.enableSignalProduct();
                // Navigate back to Products and Licenses screen
                await getService(WebviewCoordinator.id).showInstalledToolsMessage();
            } else {
                const errorMessage = response.hasError() ? 
                    response.getError()?.getMessage() || response.getMessage() :
                    response.getMessage();
                this.setErrorState(
                    localize('signal.llm.key.validation.error', 'LLM key validation failed'), 
                    errorMessage || localize('signal.llm.key.validation.error.details', 'Please enter a valid LLM key')
                );
            }
        } catch (error) {
            getLogger().error('Error validating LLM key:', error);
            this.setErrorState(
                localize('signal.llm.key.validation.error', 'LLM key validation failed'),
                localize('signal.llm.key.validation.error.network', 'Unable to connect to validation service. Please check your network connection and try again.')
            );
        }
    }

    onProxyInformationUpdated(): void {
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        handleProxyUpdate(this.view);
    }

    public async parseNotification(message: NotificationMessage): Promise<void> {
        // Handle notifications if needed for Signal LLM key validation
        // Currently no specific notification handling required
    }

    public async initView() {
        this.reloadHtml();
        this.setLLMKeyPlaceholderText();
        await handleProxyUpdate(this.view);
    }

    private setLoadingState(localizedMessage: string) {
        this.view.postMessageToWebview({
            command: SignalLLMKeyValidationViewCommandIds.SET_STATUS,
            type: 'spin',
            message: localizedMessage,
        });

        this.enableValidateButton(false);
    }

    private setErrorState(errorHeader: string, errorMessage: string) {
        this.view.postMessageToWebview({
            command: SignalLLMKeyValidationViewCommandIds.SET_STATUS,
            type: 'error',
            header: errorHeader,
            message: errorMessage,
        });
        this.enableValidateButton(true);
    }

    private setSuccessState(saveMessage: string) {
        this.view.postMessageToWebview({
            command: SignalLLMKeyValidationViewCommandIds.SET_STATUS,
            type: 'success',
            header: saveMessage,
            message: '',
        });
        this.enableValidateButton(true);
    }

    private enableValidateButton(enable: boolean) {
        this.view.postMessageToWebview({
            command: SignalLLMKeyValidationViewCommandIds.ENABLE_BUTTON,
            enable: String(enable),
            primary: "true",
            buttonId: 'validateKey',
        });
    }

    private setLLMKeyPlaceholderText() {
        let entitlements = getService(EntitlementService.id).getCachedProductEntitlement();
        let signalEntitled = entitlements.isSignalEntitled();
        this.view.postMessageToWebview({
            command: SignalLLMKeyValidationViewCommandIds.SET_LLM_KEY_PLACEHOLDER,
            placeholder: signalEntitled ? '*************************' : localize('signal.llm.key.input.placeholder', 'Enter your LLM key'),
        });
    }

    private reloadHtml() {
        this.view.reloadHtml();
    }

    private async enableSignalProduct(): Promise<void> {
        try {
            const aiModeEnabled = getService(VscodeContextService.id).getPreservedAIMode() ?? false;
            const targetScanMode = aiModeEnabled ? ScanMode.Manual : ScanMode.Auto;
            await getService(ScanStatusCoordinator.id).changeScanMode(targetScanMode);
            if (getService(VscodeContextService.id).getPreservedScanFileScope() === undefined) {
                if (getService(VscodeContextService.id).getPreservedReferenceBranchConfig()) {
                    await getService(ScanStatusCoordinator.id).changeScanFileScope(RefreshResultsRequest.Tier.REFERENCEBRANCH);
                } else {
                    await getService(ScanStatusCoordinator.id).changeScanFileScope(RefreshResultsRequest.Tier.ALLUNCOMMITTED);
                }
            }
            
            getLogger().info('Signal product enabled successfully');
        } catch (error) {
            getLogger().error('Error enabling Signal product:', error);
        }
    }

    public dispose() {
        this.onMessageFromWebviewDisposable?.dispose();
        getService(ProxyEventService.id).removeListener(this);
    }
}