// this method is called when your extension is activated
// your extension is activated the very first time the command is executed
export async function activate(context: vscode.ExtensionContext) {
	// migrate working directory
	// Run the migration script to move the old data to the new location
	let workingDirMigrationFailed = false;
	let workingDirMigrationFailedError;
	let scriptPath = context.asAbsolutePath("/resources/migration/bd-migration-20241001.sh");
	if (isWindows()) {
		scriptPath = context.asAbsolutePath("/resources/migration/bd-migration-20241001.bat");
	}
	try {
		await runMigrationScript(scriptPath);
	} catch (error) {
		workingDirMigrationFailedError = error;
		workingDirMigrationFailed = true;		
    }
	setDefaultFeatureFlags();
	let treeItemDecoration = new TreeItemDecorationProvider();
	await treeItemDecoration.provideFileDecoration();
	vscode.workspace.onDidChangeWorkspaceFolders(async (e: vscode.WorkspaceFoldersChangeEvent) => {
		getService(CaptureProviderService.id).markAsStale();
		// Re-sync the context if the workspace changes so that the controller can pick up any
		// new projects that may have been added
		await getService(AnalysisContextObservationService.id).syncContext();
	});
	
	vscode.workspace.onDidChangeWorkspaceFolders(async (e: vscode.WorkspaceFoldersChangeEvent) => {
		if (e.removed.length > 0) {
			const remainingFolderPaths = getService(WorkspaceService.id).getWorkspaceFolders().map(f => f.uri.fsPath);
			await getService(ConfigurationService.id).initGitRepositoryPath(remainingFolderPaths);
			// Clean up stale git info for removed folders
			const gitInfoService = getService(GitInfoService.id);
			for (const removed of e.removed) {
				gitInfoService.removeGitRepositoryStatus(removed.uri.fsPath);
			}
			// Re-fetch git info for remaining folders so the git repo check
			// uses up-to-date status after the workspace transition
			const analysisContextObservationService = getService(AnalysisContextObservationService.id);
			for (const folderPath of remainingFolderPaths) {
				await analysisContextObservationService.fetchGitInfoForFolder(folderPath);
			}
		}
		// Refresh the local view so the folder selection node appears/disappears
		// when transitioning between single and multi-folder workspaces
		await vscode.commands.executeCommand(COMMAND_LOCAL_VIEW_REFRESH_RESULTS);
	});
	initServices(context);
	await getService(ExtensionConfigService.id).init(); // read configuration from extension config
	// eslint-disable-next-line @typescript-eslint/no-floating-promises
	getService(WarningMessageService.id).init();
	
	await initTempLogger(context.extensionPath);
	let logger = getLogger();
	logger.info("Service provider initialized");
	logger.info("Activating Code Sight Extension...");	
	// Check if we can run controller in blackduck home directory
	let blackduckHome: string = getService(ExtensionConfigService.id).getBlackDuckHomePath();
	logger.info(`Resolved Black Duck home to ${blackduckHome}`);
	let workingDirEstablished = false;
	try {
		await getService(ControllerClientService.id).testControllerConnection(blackduckHome);
		workingDirEstablished = true;
	} catch (error) {
		await getService(WebviewCoordinator.id).showCustomWorkingDirMessage();
		await getService(ProgressNotificationService.id).showCustomWorkingDirAlert(true);
		getService(ViewProviderService.id).getOrCreateSetupPresenter().showCustomWorkingDirNeededState();
	}
	await initLogger();
	logger = getLogger();
	if (workingDirMigrationFailed) {
		logger.error(`Working directory migration failed with error: ${workingDirMigrationFailedError}`);
		// eslint-disable-next-line @typescript-eslint/no-floating-promises
		getService(WarningMessageService.id).migrationScriptFailed();
	}
	// eslint-disable-next-line @typescript-eslint/no-floating-promises
	getService(WorkspaceService.id).init();
	getService(SigmaService.id).init();
	// If the workspace is empty, warn the user that Code Sight will not work optimally
	// Transitioning to/from an empty workspace re-activates the extension, so this does not need to be rechecked
	let workspaceFolders = getService(WorkspaceService.id).getWorkspaceFolders();
	let isEmptyWorkspace = workspaceFolders.length === 0;
	if (isEmptyWorkspace) {
		logger.warn("Code Sight activated in an empty workspace. This will impact Code Sight's ability to locate analysis tools or scan files");
	}
	logger.info("Initialize help view provider...");
	// initialize code sight help view
	context.subscriptions.push(
		vscode.window.registerWebviewViewProvider(CodeSightHelpViewProvider.viewType, 
			new CodeSightHelpViewProvider(context.extensionUri)),
		vscode.commands.registerCommand(COMMAND_OPEN_HELP, async () => {
			return getService(CsBrowserService.id).openLink(DOC_APP_ADDRESS)
		}),
	);
	if(isEmptyWorkspace && workingDirEstablished){
		logger.info("Initialize empty workspace state...");
		getService(ViewProviderService.id).getOrCreateSetupPresenter().showEmptyWorkspaceState();
		const codesightSetupStatusFocus = "codesight-setup-status.focus";
		context.subscriptions.push(
			vscode.commands.registerCommand(COMMAND_OPEN_PROXY_SETTINGS, async () => {
				return vscode.commands.executeCommand(codesightSetupStatusFocus);
			}),
			vscode.commands.registerCommand(COMMAND_OPEN_DETECT_CONFIG, async () => {
				return vscode.commands.executeCommand(codesightSetupStatusFocus);
			}),
			vscode.commands.registerCommand(COMMAND_OPEN_SIGMA_INSTALL_LOCATION, async () => {
				return vscode.commands.executeCommand(codesightSetupStatusFocus);
			}),
		);
		logger.info("Extension setup complete for empty workspace");
		return;
	}
	logger.info("Begin observing the current analysis context...");
	const editorMarkersEnabled = isFeatureFlagEnabled(ENV_CODESIGHT_EDITOR_MARKERS);
	await vscode.commands.executeCommand("setContext", "codesight.editorMarkersEnabled", editorMarkersEnabled);
	getService(AnalysisContextObservationService.id).observeCurrentContext().then(async () => {
		logger.info("Current Analysis context has been observed.");
		const folderPaths = getService(WorkspaceService.id).getWorkspaceFolders().map(f => f.uri.fsPath);
		await getService(ConfigurationService.id).initGitRepositoryPath(folderPaths);
		// Go through setup flow before adding scan triggers
		const setupService = getService(SetupService.id);
		const postSetupActions: SetupServiceListener = {
			onOnboardingComplete: async (): Promise<void> => {
				setupService.removeListener(postSetupActions);
				getService(EditorDecorationService.id).init();
				if (editorMarkersEnabled) {
					context.subscriptions.push(...await getService(MarkerService.id).init());
				}
				logger.info("Initializing custom views...");
				initViews();
				registerWebviewSerializers();
				return Promise.resolve();
			}
		};
		setupService.addListener(postSetupActions);
		
		await getService(PersistentStorageMigrationService.id).init();
		await getService(AuthenticationService.id).init();
		await getService(EntitlementService.id).init();
		await getService(SetupService.id).beginOnboarding();
	}).catch(error => {
		// do it again, until it works of max 100 times?
		logger.warn(`Error observing context: ${error}`);
	});
	
	logger.info("Setting up context subscriptions...");
	context.subscriptions.push(vscode.commands.registerCommand("codesight.copyTreeItem", async (clickedTreeItem: TreeNodeProvider) => {
		let treeItemDescriptions: string[] = [];
		if (clickedTreeItem instanceof IssueNode) {
			treeItemDescriptions.push(clickedTreeItem.issue.getCopyText());
		} else {
			const treeItem = await clickedTreeItem.getTreeItem();
			treeItemDescriptions.push(`${treeItem.label ?? ""} ${treeItem.description ?? ""}`);
		}
		await vscode.env.clipboard.writeText(treeItemDescriptions.join("\n"));
	}));
	context.subscriptions.push(vscode.commands.registerCommand(COPY_ALL_ISSUES_COMMAND_ID, async (clickedTreeItem: TreeNodeProvider) => {
		let copyTexts: string[] = [];
		if (clickedTreeItem instanceof SeparatorNode) {
			const issueListId = clickedTreeItem.getIssuesListId();
			let issues;
			if (issueListId === IssuesListIdentifier.LocalViewIssuesList) {
				issues = await getService(LocalViewIssuesListService.id).getIssues();
			} else if (issueListId === IssuesListIdentifier.TeamViewIssuesList) {
				issues = await getService(TeamViewIssuesListService.id).getIssues();
			} 
			issues?.forEach(issue => {
				copyTexts.push(issue.getCopyText());
			});
			await vscode.env.clipboard.writeText(copyTexts.join("\n"));
		}		
	}));
	context.subscriptions.push(vscode.commands.registerCommand(COMMAND_OPEN_ONBOARDING, async () => {
		return getService(SetupService.id).showCurrentSetupStep();
	}));
	context.subscriptions.push(vscode.commands.registerCommand(COMMAND_OPEN_PROXY_SETTINGS, async () => {
		return getService(WebviewCoordinator.id).showProxyView();
	}));
	context.subscriptions.push(vscode.commands.registerCommand(COMMAND_OPEN_CS_SETTINGS, async () => {
		return vscode.commands.executeCommand("workbench.action.openSettings", "codeSight");
	}));
	context.subscriptions.push(vscode.commands.registerCommand(COMMAND_OPEN_DETECT_CONFIG, async () => {
		return getService(WebviewCoordinator.id).showDetectConfigView();
	}));
	context.subscriptions.push(vscode.commands.registerCommand(COMMAND_OPEN_TEAM_VIEW_ISSUE_SOURCE_VIEW, async () => {
		return getService(WebviewCoordinator.id).showTeamViewIssueSourceView();
	}));
	context.subscriptions.push(vscode.commands.registerCommand(COMMAND_OPEN_SIGMA_INSTALL_LOCATION, async () => {
		return getService(WebviewCoordinator.id).showSigmaInstallLocationView();
	}));
	context.subscriptions.push(vscode.commands.registerCommand(COMMAND_OPEN_CUSTOM_WORKING_DIR, async () => {
		return getService(WebviewCoordinator.id).showCustomWorkingDirMessage();
	}));
	context.subscriptions.push(vscode.commands.registerCommand(COMMAND_LOCAL_VIEW_CANCEL_SCAN_ID, async () => {
		let localViewScanId = getService(ScanService.id).getLocalViewLastScanId();
		if (localViewScanId) {
			await getService(ScanService.id).cancelJob(localViewScanId);	
		}
	}));
	context.subscriptions.push(vscode.commands.registerCommand(COMMAND_SET_AUTO_MODE, async () => {
			await doLocalViewTurnOnAutoMode();
	}));
	context.subscriptions.push(vscode.commands.registerCommand(COMMAND_SET_MANUAL_MODE, async () => {
		await getService(ScanStatusCoordinator.id).changeScanMode(ScanMode.Manual);
	}));
	context.subscriptions.push(vscode.commands.registerCommand(COMMAND_SET_ACTIVE_FILE_SCOPE, async () => {
		await getService(ScanStatusCoordinator.id).changeScanFileScope(RefreshResultsRequest.Tier.FAST);
	}));
	context.subscriptions.push(vscode.commands.registerCommand(COMMAND_SET_CHANGED_FILE_SCOPE_ALL_UNCOMMITTED, async () => {
		await getService(ScanStatusCoordinator.id).changeScanFileScope(RefreshResultsRequest.Tier.ALLUNCOMMITTED);
	}));
	context.subscriptions.push(vscode.commands.registerCommand(COMMAND_SET_CHANGED_FILE_SCOPE_REFERENCE_BRANCH, async () => {
		await getService(ScanStatusCoordinator.id).changeScanFileScope(RefreshResultsRequest.Tier.REFERENCEBRANCH);
	}));
	context.subscriptions.push(vscode.commands.registerCommand(COMMAND_PAGER, async (pagerNode: PagerNode) => {
		await pagerNode.loadMore();
	}));
	let telemetryService = getService(TelemetryService.id);
	await telemetryService.init();
	
	logger.info("Setting up chat participant...");
	try {
		const chatParticipant = initializeChatParticipant(context);
		context.subscriptions.push(chatParticipant);
		logger.info("Chat participant initialized successfully");
	} catch (error) {
		logger.error(`Failed to initialize chat participant: ${error}`);
	}
	getLogger().info("Send startup event...");
	telemetryService.sendStartupEvent();
	logger.info("Extension setup complete");
}
async function runMigrationScript(scriptPath: string): Promise<string> {
	return new Promise<string>((resolve, reject) => {
		exec(scriptPath, { timeout: 20000 }, (error, stdout, stderr) => {
			if (error || stderr) {
				const message = error ? error.message : stderr;
				reject(message);
			} else {
				resolve("");
			}
		});
	});
}
export async function doLocalViewTurnOnAutoMode() {
	let isScanRunning = getService(ScanService.id).isLocalViewScanRunning();
	let isManualScanRunning = getService(ScanService.id).isLocalViewManualScanRunning();
	if (isScanRunning && isManualScanRunning) {
		await getService(WarningMessageService.id).warnBeforeAutoModeCancelsManualScan();
	} else {
		await getService(ScanStatusCoordinator.id).changeScanMode(ScanMode.Auto);
	}
}
export async function isAnyToolAvailable(): Promise<boolean> {
	let toolStateService = getService(ToolStateService.id);
	await toolStateService.refreshToolsFromController(false);
	let coverityInstalled = toolStateService.isCoverityInstalled();
	let sigmaInstalled = toolStateService.isSigmaInstalled();
	if (!coverityInstalled && !sigmaInstalled) {
		// eslint-disable-next-line @typescript-eslint/no-floating-promises
		getService(WarningMessageService.id).noToolIsInstalledWarning();
		return Promise.resolve(false);
	}
	return true;
}
function initViews(): void {
	let viewProviderService = getService(ViewProviderService.id);
	viewProviderService.getOrCreateExtensionStatusPresenter();
	viewProviderService.getOrCreateSetupPresenter();
	viewProviderService.getOrCreateTeamViewPresenter();
	viewProviderService.getOrCreateLocalViewPresenter();
}
function registerWebviewSerializers(): void {
	if (vscode.window.registerWebviewPanelSerializer) {
		// Make sure we register a serializer in activation event
		vscode.window.registerWebviewPanelSerializer(ViewType.ExportLogs, {
			async deserializeWebviewPanel(webviewPanel: vscode.WebviewPanel, _: any) {
				await getService(WebviewCoordinator.id).showExportLogs(webviewPanel);
			}
		});
		vscode.window.registerWebviewPanelSerializer(ViewType.ProxyView, {
			async deserializeWebviewPanel(webviewPanel: vscode.WebviewPanel, _: any) {
				await getService(WebviewCoordinator.id).showProxyView(webviewPanel);
			}
		});
	}
}
function setDefaultFeatureFlags() {
	const featureFlags = [
		ENV_CODESIGHT_DESKTOP_ENABLE_CONNECT_FILTERS, 
		ENV_CODESIGHT_DESKTOP_COVERITY_TEAM_VIEW, 
		ENV_CODESIGHT_DESKTOP_ENABLE_SRM_FILTERS, 
		ENV_CODESIGHT_DESKTOP_ENABLE_BRIDGE, 
		ENV_CODESIGHT_ENABLE_SNIPPET_SCAN, 
		ENV_CODESIGHT_ENABLE_CONNECT_COMPONENT_FILTER, 
		ENV_CODESIGHT_ENABLE_DIRECT_GUIDANCE, 
		ENV_CODESIGHT_GROUP_SIGMA_SECRETS, 
		ENV_CODESIGHT_ENABLE_ACTIVE_FILE_FILTERING,
		ENV_CODESIGHT_EDITOR_MARKERS,
		ENV_CODESIGHT_DESKTOP_COVERITY_DELETE_IDIRS,
		ENV_CODESIGHT_SIGNAL_VIEW
	];
	featureFlags.forEach(ff => {
		const value = getEnvVar(ff);
		if (value === undefined) {
			process.env[ff] = "true";
		}
	});
}
// this method is called when your extension is deactivated
export async function deactivate() {
	await getService(SigmaService.id).stopSigmaIfRunning();
}
