import { FileScanInfo } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_service_pb";
import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { Disposable, WebviewPanel, commands } from "vscode";
import { LocalizeFunc, loadMessageBundle } from "vscode-nls";
import { CsBrowserService } from "../../services/browserService";
import { getService } from "../../services/serviceContainer";
import { BD_ADDRESS, BD_QUICK_TOUR_ADDRESS, COVERITY_ADDRESS, COV_QUICK_TOUR_ADDRESS, CSSE_ADDRESS, CSSE_QUICK_TOUR_ADDRESS, DOC_APP_ADDRESS, POLARIS_ADDRESS, POLARIS_QUICK_TOUR_ADDRESS, SRM_ADDRESS } from "../../utils/constants";
import { OPEN_INSTALLED_TOOLS_MSG_COMMAND_ID } from "../extension-status/extensionStatusPresenter";
import { WebviewPresenter } from "../webviewPresenter";
import { WelcomeMessageViewProvider } from "./welcomeMessageViewProvider";

const localize: LocalizeFunc = loadMessageBundle();

export class WelcomeMessageViewPresenter implements WebviewPresenter {
    private readonly panel: WebviewPanel;
    private view: WelcomeMessageViewProvider;
    private onMessageFromWebviewDisposable: Disposable | undefined;
    protected scanInfoArray: FileScanInfo[];
    protected fullScanInfo: FileScanInfo;

    constructor(panel: WebviewPanel) {
        this.panel = panel;
        this.view = getService(WelcomeMessageViewProvider.id);
        this.view.initView(this.panel);
        this.scanInfoArray = [];
        this.fullScanInfo = new FileScanInfo();
    }

    public async parseNotification(message: NotificationMessage) {
    }

    public async initView() {
        this.view.initHtml();

        this.onMessageFromWebviewDisposable = this.view.onMessageFromWebview(async message => {
            switch (message.command) {
                case 'browse-polaris-link':
                    await getService(CsBrowserService.id).openLink(POLARIS_ADDRESS);
                    break;
                case 'browse-coverity-link':
                    await getService(CsBrowserService.id).openLink(COVERITY_ADDRESS);
                    break;
                case 'browse-bd-link':
                    await getService(CsBrowserService.id).openLink(BD_ADDRESS);
                    break;
                case 'browse-srm-link':
                    await getService(CsBrowserService.id).openLink(SRM_ADDRESS);
                    break;
                case 'browse-csse-link':
                    await getService(CsBrowserService.id).openLink(CSSE_ADDRESS);
                    break;
                case 'browse-pnl':
                    await commands.executeCommand(OPEN_INSTALLED_TOOLS_MSG_COMMAND_ID);
                    break;
                case 'browse-csse-quick-tour':
                    await getService(CsBrowserService.id).openLink(CSSE_QUICK_TOUR_ADDRESS);
                    break;
                case 'browse-cov-quick-tour':
                    await getService(CsBrowserService.id).openLink(COV_QUICK_TOUR_ADDRESS);
                    break;
                case 'browse-bd-quick-tour':
                    await getService(CsBrowserService.id).openLink(BD_QUICK_TOUR_ADDRESS);
                    break;
                case 'browse-polaris-quick-tour':
                    await getService(CsBrowserService.id).openLink(POLARIS_QUICK_TOUR_ADDRESS);
                    break;
                case 'browse-documentation':
                    await getService(CsBrowserService.id).openLink(DOC_APP_ADDRESS);
                    break;
            }
        });
    }

    public dispose() {
        this.onMessageFromWebviewDisposable?.dispose();
    }
}