import { GetConfigRequest } from '@codesight/codesight-controller-proto/controller_proto/v0/control_service_pb';
import { LicensedToolsConfig } from '@codesight/codesight-controller-proto/controller_proto/v0/licensed_tools_config_pb';
import { GetInstalledToolsRequest, GetInstalledToolsResponse } from '@codesight/codesight-controller-proto/controller_proto/v0/tool_service_pb';
import * as vscode from 'vscode';
import { CsseLicenseState } from '../models/csseLicenseInfo';
import { AnalysisContextService } from '../services/analysisContextService';
import { ControllerClientService } from '../services/controllerClientService';
import { EntitlementService, EntitlementServiceListener, EntitlementsChanged } from '../services/entitlementService';
import { InfoMessageService, WarningMessageService } from '../services/extensionMessageService';
import { ScanToolConfigListener, ScanToolConfigService } from '../services/scanToolConfigService';
import { ServiceId, getService } from '../services/serviceContainer';
import { SetupService, SetupServiceListener } from '../services/setupService';
import { SigmaClientService, SigmaLsConfig } from '../services/sigmaClientService';
import { ToolStateEnum, ToolStateService, ToolStateServiceListener, ToolTypeEnum } from '../services/toolStateService';
import { fileExists } from '../utils/fileUtils';
import { getLogger } from '../utils/logger';

export abstract class SigmaService {
    static readonly id: ServiceId<SigmaService> = { id: SigmaService.name };

    abstract init(): void;

    /**
     * Attempts to start the Sigma binary with the appropriate flags
     */
    abstract startSigma(): Promise<void>;

    /**
     * Attempts to stop the Sigma LS if Sigma is running
     */
    abstract stopSigmaIfRunning(): Promise<void>;
}


export class SigmaServiceImpl implements SigmaService, ScanToolConfigListener, ToolStateServiceListener, EntitlementServiceListener, SetupServiceListener {

    constructor() {
        getService(ScanToolConfigService.id).addListener(this);
        getService(ToolStateService.id).addListener(this);
        getService(EntitlementService.id).addListener(this);
        getService(SetupService.id).addListener(this);
    }

    dispose() {
        getService(ScanToolConfigService.id).removeListener(this);
        getService(ToolStateService.id).removeListener(this);
        getService(EntitlementService.id).removeListener(this);
        getService(SetupService.id).removeListener(this);
    }

    init(): void {
        getLogger().info("Initializing SigmaService...");
        // actually a no-op. The initialization happens in the constructor.
        // we just need an init method to call in the service interface to force construction
    }

    async startSigma(): Promise<void> {
        const logger = getLogger();
        logger.info("Preparing to launch Rapid Scan Static language server");
        let isEntitledToSigma = getService(EntitlementService.id).getCachedProductEntitlement().isSASTEntitled();
        let currentlyOnboarding = getService(SetupService.id).currentlyOnboarding();
        if (!isEntitledToSigma) {
            logger.info("Not entitled to launch Rapid Scan Static language server: Aborting Rapid Scan Static startup");
            return;
        }

        if (currentlyOnboarding) {
            logger.info("Extension is currently onboarding, Rapid Scan Static language server will be started when onboarding completes");
            return;
        }

        const isRestart = getService(SigmaClientService.id).isRunning();
        await this.stopSigmaIfRunning();
        let controllerConfigClient = await getService(ControllerClientService.id).getControlServiceClient();
        let contextService = getService(AnalysisContextService.id);
        let contextId = contextService.getAnalysisContextId();

        let configResponse = controllerConfigClient.getConfig(new GetConfigRequest());
        let currentConfig = (await configResponse).getConfig();

        let statusBarTimeout = 5000;

        if (!currentConfig || currentConfig.getConnectionconfigurationsList().length === 0) {
            logger.error("Could not locate the running controller address. Aborting Rapid Scan Static startup");
            return;
        }

        // Choose the first configured address returned by the controller. The controller is able to return multiple ports, but in practice
        // it does not, and the first address should accept a Sigma connection
        let controllerToolService = await getService(ControllerClientService.id).getToolServiceClient();
        let installedToolsRequest = new GetInstalledToolsRequest();
        installedToolsRequest.setContextid(contextId);
        let installedToolsResponse = controllerToolService.getInstalledTools(installedToolsRequest);
        let installedTools = (await installedToolsResponse).getInstalledtoolsList();

        let sigmaToolConfig = this.getSigmaToolConfig(installedTools);

        if (!sigmaToolConfig) {
            // This shouldn't happen, because we should only get here if the controller has set up a sigma location, but just in case....
            logger.error("No sigma installation found, not the sigma path was empty");
            return getService(WarningMessageService.id).noSigmaBinaryWarning();
        }

        let sigmaPath = sigmaToolConfig.getInstallpath();

        if (! await fileExists(sigmaPath)) {
            // configured/known sigma path does not exist. Prompt user to reconfigure
            return getService(WarningMessageService.id).sigmaPathDoesNotExist(sigmaPath);
        }

        const savedConfig = (await getService(ScanToolConfigService.id).getCodeSightScanConfig()).sigma;
        const sigmaScanConfig: SigmaLsConfig = {
            analyze_on_change: savedConfig.sigmaAnalyzeOnChange
        };

        vscode.window.setStatusBarMessage("Starting Rapid Scan Static LSP server...", statusBarTimeout);
        logger.info(`Starting sigma language server ${sigmaPath} ${sigmaToolConfig.getStartupargsList().join(" ")}`);
        await getService(SigmaClientService.id).startClient(sigmaPath, sigmaToolConfig.getStartupargsList(), sigmaScanConfig);

        if (!getService(SigmaClientService.id).isRunning()) {
            logger.error("Rapid Scan Static startup failed");
            vscode.window.setStatusBarMessage("Rapid Scan Static LSP server not available...", statusBarTimeout);

            return getService(WarningMessageService.id).failedToLaunchSigmaWarning(sigmaPath);
        } else if (isRestart) {

            // If we have restarted sigma, let the user know (so they have validation that their configuration change worked)
            return getService(InfoMessageService.id).sigmaLocationSuccess(sigmaPath);
        }
    }

    async stopSigmaIfRunning(): Promise<void> {
        return getService(SigmaClientService.id).stopClient();
    }

    async startSigmaIfNotRunning(): Promise<void> {
        const sigmaClientService = getService(SigmaClientService.id);
        const logger = getLogger();
        let sigmaInstalled = getService(ToolStateService.id).isSigmaInstalled();

        if (sigmaClientService.isRunning() || !sigmaInstalled) {
            logger.info("Sigma was not started as it is already running, or is not installed");
            return;
        }

        return this.startSigma();
    }

    async onToolConfigChanged(toolType: ToolTypeEnum): Promise<void> {
        if (toolType !== ToolTypeEnum.Sigma) {
            return Promise.resolve();
        }
        const scanConfig = (await getService(ScanToolConfigService.id).getCodeSightScanConfig()).sigma;
        const sigmaScanConfig: SigmaLsConfig = {
            analyze_on_change: scanConfig.sigmaAnalyzeOnChange,
        };
        return getService(SigmaClientService.id).updateConfiguration(sigmaScanConfig);
    }

    async onToolStateChanged(toolType: ToolTypeEnum, toolState: ToolStateEnum, toolVersion: string): Promise<void> {
    if (toolType === ToolTypeEnum.Sigma && toolState === ToolStateEnum.Available) {
            // we want to ensure that any current sigma instances are restarted on tool state change to properly reflect changes
            await this.stopSigmaIfRunning();
            return this.startSigmaIfNotRunning();
        }
    }

    async onEntitlementsChanged(entitlementsChanged: EntitlementsChanged): Promise<void> {
        if (!entitlementsChanged.didCsseLicenseInfoChange) {
            return;
        }

        let licenseInfo = getService(EntitlementService.id).getCachedProductEntitlement().getCsseLicense();

        if (licenseInfo.getState() !== CsseLicenseState.Valid) {
            await this.stopSigmaIfRunning();
        } else {
            await this.startSigmaIfNotRunning();
        }
    }

    async onSuggestedToolVersionChanged(tooltype: ToolTypeEnum, suggestedVersion: string): Promise<void> {
        // no-op
    }

    getSigmaToolConfig(installedTools: GetInstalledToolsResponse.InstalledToolInfo[]): LicensedToolsConfig | undefined {
        let paths = [];
        for (let tool of installedTools) {
            let foundTool = tool.getFoundtool();

            if (foundTool && foundTool.getType() === LicensedToolsConfig.Type.SIGMA) {
                if (tool.getActive()) {
                    return foundTool;
                }
                paths.push(foundTool);
            }
        }

        // If none of the tools have "isActive" flag, then return the first one
        if (paths.length > 0) {
            return paths[0];
        }
        return undefined;
    }

    async onOnboardingComplete(): Promise<void> {
        const logger = getLogger();
        logger.info("received onboardingComplete notice, attempting to start Rapid Scan Static language server");
        return this.startSigmaIfNotRunning();
    }
}
