import { Severity } from "@codesight/codesight-controller-proto/controller_proto/v0/severity_pb";
import { NewEvent, NewIssue } from "../models/newIssue";
import { IssueSelectionService } from "../services/issueSelectionService";
import { IssuesListIdentifier, LocalViewIssuesListService, TeamViewIssuesListService } from "../services/issuesService";
import { getService } from "../services/serviceContainer";
import { VscodeContextService } from "../services/vscodeContextService";
import { normalizeDriveLetter } from "./fileUtils";

export function getEventListInFile(event: NewEvent, filePath: string, events?: NewEvent[]): NewEvent[]{
    let e = events ?? [];
    let childEvents = event.getChildren();

    if (event.getFilePath() === filePath) {
        e.push(event);
    }

    childEvents.forEach(child => {
        getEventListInFile(child, filePath, e);
    });
    return e;
}

export async function getEventsInFile(identifier: IssuesListIdentifier, filepath: string, selectedIssue?: NewIssue): Promise<NewEvent[]> {
    filepath = normalizeDriveLetter(filepath);
    let events: NewEvent[] = [];
    let issues: NewIssue[] = [];
    if (identifier === IssuesListIdentifier.TeamViewIssuesList && selectedIssue) {
        // only fetch remote events if there's a selection
        issues = await getService(TeamViewIssuesListService.id).getIssues();
    } else if (identifier === IssuesListIdentifier.LocalViewIssuesList && selectedIssue) {
        issues = await getService(LocalViewIssuesListService.id).getIssues();
        issues = issues.concat(await getService(LocalViewIssuesListService.id).getLicenseAnalysisIssues());
    }

    issues.forEach((issue) => {
        if (issue instanceof NewIssue) {
            if (selectedIssue instanceof NewIssue && issue.getIssueId() === selectedIssue.getIssueId()) {
                const selectedOccurrence = getService(IssueSelectionService.id).getSelectedOccurrence(selectedIssue);
                selectedOccurrence?.getEventList().forEach(event => {
                    let eventsInFile = getEventListInFile(event, filepath);
                    eventsInFile.forEach(e => {
                        events.push(e)
                    });
                });
            }
        }
    });
    return events;
}

export async function getEventsFromIssues(selectedIssue: NewIssue, editorPath: string): Promise<NewEvent[]> {
    let events: NewEvent[] = [];
    const selectedOccurrence = getService(IssueSelectionService.id).getSelectedOccurrence(selectedIssue);
    selectedOccurrence?.getEventList().forEach(event => {
        let eventsInFile = getEventListInFile(event, editorPath);
        eventsInFile.forEach(e => {
            events.push(e)
        });
    });
    return events;
}


export function getSeverityText(severity: Severity): string {
    switch (severity) {
        case Severity.CRITICAL:
            return "Critical";
        case Severity.HIGH:
            return "High";
        case Severity.MEDIUM:
            return "Medium";
        case Severity.LOW:
            return "Low";
        case Severity.AUDIT:
            return "Audit";
        case Severity.INFO:
            return "Info";
        case Severity.UNSPECIFIED:
            return "Unspecified";
        default:
            return "Unknown";
    }
}

export function getSeverity(severity: string): Severity {
    switch (severity?.toLowerCase()) {
        case "info":
            return Severity.INFO;
        case "audit":
            return Severity.AUDIT;
        case "critical":
            return Severity.CRITICAL;
        case "high":
            return Severity.HIGH;
        case "medium":
            return Severity.MEDIUM;
        case "low":
            return Severity.LOW;
        case "unspecified":
            return Severity.UNSPECIFIED;
    }

    return Severity.UNKNOWN;
}

export function getIconPathForSeverity(severity: Severity): string {
    let contextService = getService(VscodeContextService.id);
    let severityText = getSeverityText(severity).toLowerCase();
    return contextService.getIconPath(severityText + ".svg", "impact");
}
