import { LicensedToolsConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/licensed_tools_config_pb";
import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { GetInstalledToolsRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/tool_service_pb";
import { commands } from "vscode";
import { AnalysisContextService } from "../services/analysisContextService";
import { ControllerClientService } from "../services/controllerClientService";
import { getService, ServiceId } from "../services/serviceContainer";
import { getLocalToolVersion, getSuggestedToolVersion, isBlackduckMessage, isCoverityMessage, isSigmaMessage, localToolsAvailable } from "../utils/notificationMessageUtils";

export const BLACK_DUCK_TOOL_AVAILABLE_CONTEXT = "codesight.bdToolAvailable";
export const COVERITY_TOOL_AVAILABLE_CONTEXT = "codesight.coverityInstalled";
export const SIGMA_TOOL_AVAILABLE_CONTEXT = "codesight.sigmaInstalled";

export enum ToolStateEnum {
    Unknown,
    Available,
    NotAvailable
}

export enum ToolTypeEnum {
    Coverity,
    Sigma,
    Blackduck
}

/**
 * The ToolStateService is responsible for tracking states of installed tools, and emitting
 * event in case of state change
 */
export abstract class ToolStateService {
    static readonly id: ServiceId<ToolStateService> = { id: ToolStateService.name };

    /**
     * Returns the state of given toolType in cached states 
     */
    abstract getStateForTool(toolType: ToolTypeEnum): ToolStateEnum;

    /**
     * Returns the version of given toolType in cached states. May be empty if the tool has not been found
     */
    abstract getVersionForTool(toolType: ToolTypeEnum): string;


    /**
     * Available tool states
     */
    abstract isCoverityInstalled(): boolean;
    abstract isSigmaInstalled(): boolean;
    abstract isBlackduckInstalled(): boolean;
    abstract isAnyToolInstalled(): boolean;
    abstract isToolStateLoading(): boolean;

    abstract isUpdateAvailable(toolType: ToolTypeEnum): boolean;

    abstract getSuggestedVersionForTool(toolType: ToolTypeEnum): string;

    /**
     * Update state for tool if it has changed
     */
    abstract updateToolState(notification: NotificationMessage): Promise<void>;

    abstract addListener(listener: ToolStateServiceListener): void;

    abstract removeListener(listener: ToolStateServiceListener): void;

    abstract refreshToolsFromController(checkForToolUpdates: boolean): Promise<void>;
}

export abstract class ToolStateServiceListener {
    abstract onToolStateChanged(toolType: ToolTypeEnum, toolState: ToolStateEnum, toolVersion: string): Promise<void>;
    abstract onSuggestedToolVersionChanged(tooltype: ToolTypeEnum, suggestedVersion: string): Promise<void>;
}

export class ToolStateServiceImpl implements ToolStateService {

    private coverityToolState: ToolStateEnum;
    private coverityVersion: string;
    private coveritySuggestedVersion: string;
    private sigmaToolState: ToolStateEnum;
    private sigmaVersion: string;
    private sigmaSuggestedVersion: string;

    private bdToolState: ToolStateEnum;
    private bdVersion: string;
    private bdSuggestedVersion: string;
    
    private toolStateListeners: ToolStateServiceListener[];


    constructor() {
        this.coverityToolState = ToolStateEnum.Unknown;
        this.bdToolState = ToolStateEnum.Unknown;
        this.sigmaToolState = ToolStateEnum.Unknown;
        this.coverityVersion = "";
        this.sigmaVersion = "";
        this.bdVersion = "";
        this.coveritySuggestedVersion = "";
        this.sigmaSuggestedVersion = "";
        this.bdSuggestedVersion = "";
        this.toolStateListeners = [];
    }

    isCoverityInstalled(): boolean {
        return this.getStateForTool(ToolTypeEnum.Coverity) === ToolStateEnum.Available;
    }

    isSigmaInstalled(): boolean {
        return this.getStateForTool(ToolTypeEnum.Sigma) === ToolStateEnum.Available;
    }

    isBlackduckInstalled(): boolean {
        return this.getStateForTool(ToolTypeEnum.Blackduck) === ToolStateEnum.Available;
    }

    isAnyToolInstalled(): boolean {
        return this.isCoverityInstalled() || this.isSigmaInstalled() || this.isBlackduckInstalled();
    }

    isToolStateLoading(): boolean {
        return this.getStateForTool(ToolTypeEnum.Coverity) === ToolStateEnum.Unknown || 
            this.getStateForTool(ToolTypeEnum.Sigma) === ToolStateEnum.Unknown ||
            this.getStateForTool(ToolTypeEnum.Blackduck) === ToolStateEnum.Unknown;
    }

    isUpdateAvailable(toolType: ToolTypeEnum): boolean {
        switch (toolType) {
            case ToolTypeEnum.Coverity:
                return this.coveritySuggestedVersion !== "";
            case ToolTypeEnum.Sigma:
                return this.sigmaSuggestedVersion !== "";
            case ToolTypeEnum.Blackduck:
                return this.bdSuggestedVersion !== "";
        }
    }

    getStateForTool(toolType: ToolTypeEnum): ToolStateEnum {
        switch (toolType) {
            case ToolTypeEnum.Coverity:
                return this.coverityToolState;
            case ToolTypeEnum.Sigma:
                return this.sigmaToolState;
            case ToolTypeEnum.Blackduck:
                return this.bdToolState;
        }
    }

    getVersionForTool(toolType: ToolTypeEnum): string {
        switch (toolType) {
            case ToolTypeEnum.Coverity:
                return this.coverityVersion;
            case ToolTypeEnum.Sigma:
                return this.sigmaVersion;
            case ToolTypeEnum.Blackduck:
                return this.bdVersion;
        }
    }

    getSuggestedVersionForTool(toolType: ToolTypeEnum): string {
        switch (toolType) {
            case ToolTypeEnum.Coverity:
                return this.coveritySuggestedVersion;
            case ToolTypeEnum.Sigma:
                return this.sigmaSuggestedVersion;
            case ToolTypeEnum.Blackduck:
                return this.bdSuggestedVersion;
        }
    }


    async setToolState(toolType: ToolTypeEnum, toolState: ToolStateEnum, toolVersion: string): Promise<void> {
        let promises: Promise<void>[] = [];
        switch (toolType) {
            case ToolTypeEnum.Coverity:
                if (this.coverityToolState !== toolState || this.coverityVersion !== toolVersion) {
                    // eslint-disable-next-line @typescript-eslint/no-floating-promises
                    commands.executeCommand('setContext', COVERITY_TOOL_AVAILABLE_CONTEXT, toolState === ToolStateEnum.Available);
                    this.coverityToolState = toolState;
                    this.coverityVersion = toolVersion;
                    this.toolStateListeners.forEach((listener) => {
                        promises.push(listener.onToolStateChanged(ToolTypeEnum.Coverity, this.coverityToolState, this.coverityVersion));
                    });
                }
                break;
            case ToolTypeEnum.Sigma:
                if (this.sigmaToolState !== toolState || this.sigmaVersion !== toolVersion) {
                    // eslint-disable-next-line @typescript-eslint/no-floating-promises
                    commands.executeCommand('setContext', SIGMA_TOOL_AVAILABLE_CONTEXT, toolState === ToolStateEnum.Available);
                    this.sigmaToolState = toolState;
                    this.sigmaVersion = toolVersion;
                    this.toolStateListeners.forEach((listener) => {
                        promises.push(listener.onToolStateChanged(ToolTypeEnum.Sigma, this.sigmaToolState, this.sigmaVersion));
                    });
                }
                break;
            case ToolTypeEnum.Blackduck:
                if (this.bdToolState !== toolState || this.bdVersion !== toolVersion) {
                    // eslint-disable-next-line @typescript-eslint/no-floating-promises
                    commands.executeCommand("setContext", BLACK_DUCK_TOOL_AVAILABLE_CONTEXT, toolState === ToolStateEnum.Available);                
                    this.bdToolState = toolState;
                    this.bdVersion = toolVersion;
                    this.toolStateListeners.forEach((listener) => {
                        promises.push(listener.onToolStateChanged(ToolTypeEnum.Blackduck, this.bdToolState, this.bdVersion));
                    });
                }
                break;
        }

        await Promise.all(promises);
    }

    async setSuggestedToolVersion(toolType: ToolTypeEnum, suggestedVersion: string) {
        let promises: Promise<void>[] = [];
        switch (toolType) {
            case ToolTypeEnum.Coverity:
                if (suggestedVersion !== this.coveritySuggestedVersion) {
                    this.coveritySuggestedVersion = suggestedVersion;
                    this.toolStateListeners.forEach((listener) => {
                        promises.push(listener.onSuggestedToolVersionChanged(ToolTypeEnum.Coverity, this.coveritySuggestedVersion));
                    });
                }
                break;
            case ToolTypeEnum.Sigma:
                if (suggestedVersion !== this.sigmaSuggestedVersion) {
                    this.sigmaSuggestedVersion = suggestedVersion;
                    this.toolStateListeners.forEach((listener) => {
                        promises.push(listener.onSuggestedToolVersionChanged(ToolTypeEnum.Sigma, this.sigmaSuggestedVersion));
                    });
                }
                break;
            case ToolTypeEnum.Blackduck:
                if (suggestedVersion !== this.bdSuggestedVersion) {
                    this.bdSuggestedVersion = suggestedVersion;
                    this.toolStateListeners.forEach((listener) => {
                        promises.push(listener.onSuggestedToolVersionChanged(ToolTypeEnum.Blackduck, this.bdSuggestedVersion));
                    });
                }
                break;
        }

        await Promise.all(promises);

    }

    async updateToolState(notification: NotificationMessage): Promise<void> {
        const isToolAvailable = localToolsAvailable(notification) ? ToolStateEnum.Available : ToolStateEnum.NotAvailable;
        const version = getLocalToolVersion(notification);
        const suggestedVersion = getSuggestedToolVersion(notification);
        let suggestedVersionPromise = Promise.resolve();
        let toolStatePromise = Promise.resolve();
        if (isSigmaMessage(notification)) {
            // update the suggested version
            if (this.sigmaSuggestedVersion !== suggestedVersion) {
                suggestedVersionPromise = this.setSuggestedToolVersion(ToolTypeEnum.Sigma, suggestedVersion);
            }
            // update the tool version
            if (this.sigmaToolState !== isToolAvailable || this.sigmaVersion !== version) {
                toolStatePromise = this.setToolState(ToolTypeEnum.Sigma, isToolAvailable, version);
            }
        } else if (isCoverityMessage(notification)) {
            // update the suggested version
            if (this.coveritySuggestedVersion !== suggestedVersion) {
                suggestedVersionPromise = this.setSuggestedToolVersion(ToolTypeEnum.Coverity, suggestedVersion);
            }

            // update the tool version
            if (this.coverityToolState !== isToolAvailable || this.coverityVersion !== version) {
                toolStatePromise = this.setToolState(ToolTypeEnum.Coverity, isToolAvailable, version);
            }
        } else if (isBlackduckMessage(notification)) {
            // update the suggested version
            if (this.bdSuggestedVersion !== suggestedVersion) {
                suggestedVersionPromise = this.setSuggestedToolVersion(ToolTypeEnum.Blackduck, suggestedVersion);
            }

            // update the tool version
            if (this.bdToolState !== isToolAvailable || this.bdVersion !== version) {
                toolStatePromise = this.setToolState(ToolTypeEnum.Blackduck, isToolAvailable, version);
            }
        }
        await Promise.all([suggestedVersionPromise, toolStatePromise]);
    }

async refreshToolsFromController(checkForToolUpdates: boolean): Promise<void> {
        const toolService = await getService(ControllerClientService.id).getToolServiceClient();
        const contextId = getService(AnalysisContextService.id).getAnalysisContextId();
        const installedToolsRequest = new GetInstalledToolsRequest();
        installedToolsRequest.setContextid(contextId);
        installedToolsRequest.setSkipsuggestedversioncheck(!checkForToolUpdates);
        const installedToolsResponse = await toolService.getInstalledTools(installedToolsRequest);
        let sigmaToolState = ToolStateEnum.NotAvailable;
        let coverityToolState = ToolStateEnum.NotAvailable;
        let bdToolState = ToolStateEnum.NotAvailable;
        let sigmaVersion: string | undefined;
        let coverityVersion: string | undefined;
        let bdVersion: string | undefined;
        let sigmaSuggestedVersion: string | undefined;
        let coveritySuggestedVersion: string | undefined;
        let bdSuggestedVersion: string | undefined;

        installedToolsResponse.getInstalledtoolsList().forEach(tool => {
            let toolType = tool.getFoundtool()?.getType();
            if (toolType === LicensedToolsConfig.Type.COVERITY) {
                coverityToolState = ToolStateEnum.Available;
                if (!coverityVersion || tool.getActive()) {
                    coverityVersion = tool.getFoundtool()?.getVersion();
                }

                if (tool.hasSuggestedtool() && tool.getActive()) {
                    coveritySuggestedVersion = tool.getSuggestedtool()?.getVersion();
                }
            } else if (toolType === LicensedToolsConfig.Type.SIGMA) {
                sigmaToolState = ToolStateEnum.Available;
                if (!sigmaVersion || tool.getActive()) {
                    sigmaVersion = tool.getFoundtool()?.getVersion();
                }

                if (tool.hasSuggestedtool() && tool.getActive()) {
                    sigmaSuggestedVersion = tool.getSuggestedtool()?.getVersion();
                }
            } else if (toolType === LicensedToolsConfig.Type.BLACKDUCK) {
                bdToolState = ToolStateEnum.Available;
                if (!bdVersion || tool.getActive()) {
                    bdVersion = tool.getFoundtool()?.getVersion();
                }

                if (tool.hasSuggestedtool() && tool.getActive()) {
                    bdSuggestedVersion = tool.getSuggestedtool()?.getVersion();
                }
            }
        });

        let sigmaSuggestedVersionPromise = Promise.resolve();
        let coveritySuggestedVersionPromise = Promise.resolve();
        let bdSuggestedVersionPromise = Promise.resolve();
        if (checkForToolUpdates) {
            sigmaSuggestedVersionPromise = this.setSuggestedToolVersion(ToolTypeEnum.Sigma, sigmaSuggestedVersion ? sigmaSuggestedVersion : "");
            coveritySuggestedVersionPromise = this.setSuggestedToolVersion(ToolTypeEnum.Coverity, coveritySuggestedVersion ? coveritySuggestedVersion : "");
            bdSuggestedVersionPromise = this.setSuggestedToolVersion(ToolTypeEnum.Blackduck, bdSuggestedVersion ? bdSuggestedVersion : "");
        }
        
        const updateCoverityState = this.setToolState(ToolTypeEnum.Coverity, coverityToolState, coverityVersion ? coverityVersion : "");
        const updateSigmaState = this.setToolState(ToolTypeEnum.Sigma, sigmaToolState, sigmaVersion ? sigmaVersion : "");
        const updateBdState = this.setToolState(ToolTypeEnum.Blackduck, bdToolState, bdVersion ? bdVersion : "");
        await Promise.all([sigmaSuggestedVersionPromise, coveritySuggestedVersionPromise, bdSuggestedVersionPromise,  updateCoverityState, updateSigmaState, updateBdState]);
    }

    addListener(listener: ToolStateServiceListener): void {
        this.toolStateListeners.push(listener);
    }
    removeListener(listener: ToolStateServiceListener): void {
        let index = this.toolStateListeners.indexOf(listener);
        if (index >= 0) {
            this.toolStateListeners.splice(index, 1);
        }
    }
}
