export function getViewSpinnerHTML(spinnerText: string): string {
    return /*html*/`
    <div class="absolute-center">
        <img class='spinner-icon' width='64' height='64'>
        <div class="text-bold">${spinnerText}</div>
    </div>`;
}

export function getViewSpinnerCSS(): string {
    return /*css*/`
    .absolute-center {
        position: absolute; 
        left: 50%; 
        top:50%; 
        transform: translate(-50%, -50%); 
        text-align: center;
    }
    `;
}