import { RefreshResultsRequest, RefreshStatus } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_service_pb";
import { commands } from "vscode";
import { CONTEXT_AI_ENABLED, CONTEXT_SIGNAL_VIEW } from "../utils/constants";
import { isChangedFileScanTier } from "../utils/fileScanInfoUtils";
import { EntitlementService } from "./entitlementService";
import { ScanConfigurationService } from "./scanConfigurationService";
import { ScanService } from "./scanService";
import { ServiceId, getService } from "./serviceContainer";
import { ToolStateService } from "./toolStateService";
import { VscodeContextService } from "./vscodeContextService";

export abstract class ScanStatusCoordinator {
    static readonly id: ServiceId<ScanStatusCoordinator> = { id: ScanStatusCoordinator.name };

    abstract addListener(listener: ScanStatusCoordinatorListener): void;

    abstract removeListener(listener: ScanStatusCoordinatorListener): void;

    /**
     * Sets/retrieves current scan mode: Auto/Manual
     */
    abstract getCurrentScanMode(): ScanMode;

    /**
     * Sets/retrieves current scan file scope for Signal: ChangedFiles/ActiveFile(FAST)
     */
    abstract getCurrentScanFileScope(): RefreshResultsRequest.Tier;
    
    abstract isCurrentScanFilesScopeChangedFiles(): boolean;

    abstract notifyListenersOfScanResultsReceived(notificationStatus: RefreshStatus): Promise<void>;

    abstract changeScanMode(mode: ScanMode): Promise<void>;

    abstract changeScanFileScope(fileScope: RefreshResultsRequest.Tier): Promise<void>;
}

export abstract class ScanStatusCoordinatorListener {
    abstract onScanResultReceived(notificationStatus: RefreshStatus): Promise<void>;
}

export enum SingleFileReloadReason {
    NewData,
    Filter,
    Sort,
}

export enum ScanMode {
    Auto,
    Manual,
}

export class ScanStatusCoordinatorImpl implements ScanStatusCoordinator {
    protected scanStatusListeners: ScanStatusCoordinatorListener[];
    private currentScanMode: ScanMode;
    private currentScanFileScope: RefreshResultsRequest.Tier;

    constructor() {
        this.scanStatusListeners = [];
        this.currentScanMode = this.getInitialScanModeValue();
        this.currentScanFileScope = this.getInitialScanFileScopeValue();
        void this.updateScanFileScopeContext(this.currentScanFileScope);
        void this.updateAutoScanContext(this.currentScanMode);
    }

    private getInitialScanModeValue(): ScanMode {
        let isSignalView = getService(EntitlementService.id).getCachedProductEntitlement().isSignalEntitled();
        const aiEnabled = getService(VscodeContextService.id).getPreservedAIMode() ?? false;
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        commands.executeCommand("setContext", CONTEXT_SIGNAL_VIEW, isSignalView);
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        commands.executeCommand("setContext", CONTEXT_AI_ENABLED, aiEnabled);
        // Priority 1: If AI mode is enabled, must use Project mode (Signal is a Project mode variant)
        if (isSignalView) {
            const aiModeEnabled = getService(VscodeContextService.id).getPreservedAIMode() ?? false;
            if (aiModeEnabled) {
                return ScanMode.Manual;
            }
        }

        // Priority 2: Use preserved scan mode if available
        let storedScanMode = getService(VscodeContextService.id).getPreservedScanMode();
        if (storedScanMode !== undefined) {
            return storedScanMode;
        }

        // Priority 3: Default based on tool availability
        const toolStateService = getService(ToolStateService.id);
        return toolStateService.isSigmaInstalled() ? ScanMode.Auto : ScanMode.Manual;
    }

    private getInitialScanFileScopeValue(): RefreshResultsRequest.Tier {
        let storedScanFileScope = getService(VscodeContextService.id).getPreservedScanFileScope();
        if (storedScanFileScope !== undefined) {
            return storedScanFileScope;
        }
        return RefreshResultsRequest.Tier.FAST;
    }

    public async changeScanMode(mode: ScanMode) {
        // cancel any currently running jobs
        let localViewScanId = getService(ScanService.id).getLocalViewLastScanId();
        if (localViewScanId) {
            await getService(ScanService.id).cancelJob(localViewScanId);
        }

        this.currentScanMode = mode;
        await this.updateAutoScanContext(mode);
        await getService(VscodeContextService.id).preserveScanMode(this.currentScanMode);
        await getService(ScanConfigurationService.id).notifyListenersOfScanModeChanged(mode);
    }

    public async changeScanFileScope(fileScope: RefreshResultsRequest.Tier) {
        let localViewScanId = getService(ScanService.id).getLocalViewLastScanId();
        if (localViewScanId) {
            await getService(ScanService.id).cancelJob(localViewScanId);
        }

        this.currentScanFileScope = fileScope;
        await this.updateScanFileScopeContext(fileScope);
        await getService(VscodeContextService.id).preserveScanFileScope(this.currentScanFileScope);
        await getService(ScanConfigurationService.id).notifyListenersOfScanFileScopeChanged(fileScope);
    }

    private async updateScanFileScopeContext(fileScope: RefreshResultsRequest.Tier) {
        await commands.executeCommand("setContext", "codesight.scanFilesScopeChangedFiles", isChangedFileScanTier(fileScope));
    }

    private async updateAutoScanContext(mode: ScanMode): Promise<void> {
        switch (mode) {
            case ScanMode.Manual:
                await commands.executeCommand("setContext", "codesight.scanMode", "manual");
                break;
            case ScanMode.Auto:
                await commands.executeCommand("setContext", "codesight.scanMode", "auto");
                break;
        }
    }

    public getCurrentScanMode(): ScanMode {
        return this.currentScanMode;
    }

    public getCurrentScanFileScope(): RefreshResultsRequest.Tier {
        return this.currentScanFileScope;
    }

    public isCurrentScanFilesScopeChangedFiles(): boolean {
        return isChangedFileScanTier(this.currentScanFileScope);
    }

    public addListener(listener: ScanStatusCoordinatorListener): void {
        this.scanStatusListeners.push(listener);
    }

    public removeListener(listener: ScanStatusCoordinatorListener): void {
        let index = this.scanStatusListeners.indexOf(listener);
        if (index >= 0) {
            this.scanStatusListeners.splice(index, 1);
        }
    }

    public async notifyListenersOfScanResultsReceived(notificationStatus: RefreshStatus) {
        let promises: Promise<void>[] = [];
        this.scanStatusListeners.forEach(listener => {
            promises.push(listener.onScanResultReceived(notificationStatus));
        });

        await Promise.all(promises);
    }
}