import { ServerType } from "@codesight/codesight-controller-proto/controller_proto/v0/server_info_pb";
import { GetCurrentUserRequest, GetCurrentUserResponse, UsersRequest, UsersResponse } from "@codesight/codesight-controller-proto/controller_proto/v1/user_service_pb";
import { getLogger } from "../utils/logger";
import { AnalysisContextService } from "./analysisContextService";
import { ControllerClientService } from "./controllerClientService";
import { getService, ServiceId } from "./serviceContainer";

const ERROR_MSG_SERVER: string = "getCurrentUser() called without a serverType";
export class UserService {
    static readonly id: ServiceId<UserService> = { id: UserService.name };

    async getUsers(searchString: string, serverType: ServerType | undefined): Promise<UsersResponse> {
        let userServiceClient = await getService(ControllerClientService.id).getUserServiceClient();

        if (!serverType) {
            getLogger().warn(ERROR_MSG_SERVER);
            return Promise.reject(ERROR_MSG_SERVER);
        }
        let request = new UsersRequest();
        request.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        request.setServertype(serverType);
        let filter = new UsersRequest.UserFilter();
        filter.setFilter(searchString);
        request.setFilter(filter);
        return userServiceClient.getUsers(request);
    }

    async getCurrentUser(serverType: ServerType | undefined): Promise<GetCurrentUserResponse> {
        let userServiceClient = await getService(ControllerClientService.id).getUserServiceClient();
        if (!serverType) {
            getLogger().warn(ERROR_MSG_SERVER);
            return Promise.reject(ERROR_MSG_SERVER);
        }
        let request = new GetCurrentUserRequest();
        request.setServertype(serverType);
        request.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        return userServiceClient.getCurrentUser(request);
    }
}