import { Uri } from "vscode";

export const MARKDOWN_NEWLINE = "  \n"; // two spaces and a \n triggers a line break in the hovers
export const MARKDOWN_DBL_NEWLINE = "\n\n"; // \n\n denotes the end of a list
export const MARKDOWN_SPACE = "&nbsp;";

// eslint-disable-next-line @typescript-eslint/no-var-requires
let md = require('markdown-it')();

export function getIconMarkdown(iconPath: string, description?: string, size?: number): string {
    // There is no way to determine if the current color theme is light or dark
    // This is an open VSCode issue, but it is going to wreak havoc on us, as we will end up showing white icons on a light background
    // https://github.com/microsoft/vscode/issues/46940
    //
    // There is a workaround here https://github.com/microsoft/vscode/issues/32813#issuecomment-468226840
    // but it is a huge hack...so hopefully they just fix this issue in the next release (where it is targeted)
    //
    // UD-3970 has been filed to deal with this

    // Use Uri.file() for all platforms as it properly handles path normalization,
    // encoding of spaces and special characters, and cross-platform compatibility
    const resolvedIconPath = Uri.file(iconPath).toString();

    const sizeAttribute = size ? `|width=${size}` : "";
    const altText = description ? ` "${description}"` : "";

    return `![](${resolvedIconPath}${sizeAttribute}${altText})`;
}

export function renderMarkdown(str: string): string {
    let value = md.render(str);
    return cleanMarkdown(value);
}

function cleanMarkdown(str: string): string {
    let cleaned = str;

    // markdown-it wraps unordered bullet points into <pre><code>
    // which results in bad layout
    if (cleaned.indexOf("<pre><code>*") > 0) {
        cleaned = cleaned.
            replace(/\*/g, "<li>").
            replace(/<pre><code>/g, "<ul>").
            replace(/<\/code><\/pre>/g, "</ul>");
    }
    
    return cleaned;
}