export interface TreeNodeProvider {
    getTreeItem(): TreeItem | Thenable<TreeItem>;
    getChildren(): TreeNodeProvider[];
    getParent(): TreeNodeProvider | undefined;
}

export class IssueTreeItem extends TreeItem {
    // stores errors that occur while loading remote issue details / events from a remote server
    error?: Error;
}

export class IssueNode implements TreeNodeProvider {
    issue: NewIssue;
    parent?: TreeNodeProvider;
    children: TreeNodeProvider[] = [];
    list: IssuesListIdentifier;
    diffFilter?: IssueDiffValue;
    isSignalMode: boolean;

    constructor(list: IssuesListIdentifier, issue: NewIssue, parent?: TreeNodeProvider, diffFilter?: IssueDiffValue, isSignalMode?: boolean) {
        this.list = list;
        this.issue = issue;
        this.parent = parent;
        this.diffFilter = diffFilter;
        this.isSignalMode = isSignalMode ?? false;
    }

    getTreeItem(): IssueTreeItem {
        let issueTreeItem = new IssueTreeItem("");
        issueTreeItem.label =  `${this.issue.getDisplayString()}`;
        let location = this.issue.getLocation();
        issueTreeItem.description = location ? `- ${location}` : "";
        issueTreeItem.id =  `${this.issue.getIssueId()}`;
        if (this.issue.getSeverity() !== Severity.UNKNOWN) {
            issueTreeItem.iconPath =  this.issue.getIconPathForSeverity();
        }
        issueTreeItem.tooltip =  getNewIssueTreeItemTooltip_Issue(this.issue);
        issueTreeItem.collapsibleState =  TreeItemCollapsibleState.Collapsed;
        let commandId = this.list === IssuesListIdentifier.LocalViewIssuesList ? LOCAL_VIEW_TREE_ITEM_SELECTED_COMMAND_ID : TEAM_VIEW_TREE_ITEM_SELECTED_COMMAND_ID;

        if (this.diffFilter === IssueDiffValue.NEW) {
            issueTreeItem.resourceUri = Uri.parse(`${NEW_DIFF_FILTER_RESOURCE_URI}:`);
        } else if (this.diffFilter === IssueDiffValue.FIXED) {
            issueTreeItem.resourceUri = Uri.parse(`${ABSENT_DIFF_FILTER_RESOURCE_URI}:`);
        } else if (this.isSignalMode) {
            issueTreeItem.resourceUri = Uri.parse(`${SIGNAL_RESOURCE_URI}:`);
        }
        issueTreeItem.command = {
            command: commandId,
            arguments: [this.issue.getIssueId(), this.list, this.issue.getDisplayType()],
            title: "Issue node selected" //not user facing
        };
        
        // Add context value to enable hover icon for issue items
        issueTreeItem.contextValue = getTreeItemContext(this.list === IssuesListIdentifier.LocalViewIssuesList ? ContextValue.lockLocalIssueItem : ContextValue.lockRemoteIssueItem);

        return issueTreeItem;
    }

    getChildren(): TreeNodeProvider[] {
        let eventInfo = this.issue.getEventInfo();
        let occurrences = this.issue.getEventInfo()?.getContributingDetails() ?? [];
        let childrenIdSet = new Set();

        if (eventInfo === undefined) {
            return [new DescriptionNode(localize('issues.children.loading', 'Loading...'))];
        } else if (eventInfo.hasError()) {
            let errorCommandId = this.list === IssuesListIdentifier.LocalViewIssuesList ? COMMAND_SHOW_LOCAL_VIEW_ISSUE_LIST_ERROR : COMMAND_SHOW_REMOTE_ISSUE_LIST_ERROR;
            return [new StatusNode(Status.Error, localize('issues.children.load.error', 'Failed to load data'), errorCommandId, eventInfo.getError()!),
            new DescriptionNode(localize('issues.children.load.view.error.trigger.reload', 'Collapse and expand the issue to try again')),
            new ButtonNode(localize('issues.children.load.view.error.label', 'View Error'), errorCommandId, {commandArgs: [eventInfo.getError()!]})];
        } else if (occurrences.length > 0) {
            this.children = [];
            if (occurrences.length > 1) {
                occurrences.forEach((occurrence) => {
                    let occurrenceNode = new OccurrenceNode(this.list, occurrence, this);
                    this.children.push(occurrenceNode);
                });
            } else if (occurrences.length === 1) {
                let occurrence = occurrences[0];
                occurrence.getEventList()?.forEach((event) => {
                    let eventNode = new EventNode(this.list, event, this);
                    let eventNodeId = eventNode.getTreeItem().id!;
                    if (!childrenIdSet.has(eventNodeId)) {
                        childrenIdSet.add(eventNodeId);
                        this.children.push(eventNode);
                    }
                });
            }
            return this.children;
        } else {
            return [new DescriptionNode(localize('issues.children.load.not.found', 'No contributing code events found'))];
        }
    }

    getParent() {
        return this.parent;
    }
}

export class OccurrenceNode implements TreeNodeProvider {
    occurrence: ContributingDetail;
    parent: TreeNodeProvider;
    children: TreeNodeProvider[] = [];
    list: IssuesListIdentifier;

    constructor(list: IssuesListIdentifier, occurrence: ContributingDetail, parent: TreeNodeProvider) {
        this.list = list;
        this.occurrence = occurrence;
        this.parent = parent;
        this.buildChildren();
    }

    buildChildren() {
        this.occurrence.getEventList().forEach((event) => {
            this.children.push(new EventNode(this.list, event, this));
        });
    }

    getChildren(): TreeNodeProvider[] {
        return this.children;
    }

    getParent(): TreeNodeProvider | undefined {
        return this.parent;
    }

    getTreeItem(): TreeItem {
        let issue = this.occurrence.getParentIssue();
        let commandId = this.list === IssuesListIdentifier.LocalViewIssuesList ? LOCAL_VIEW_TREE_OCCURRENCE_SELECTED_COMMAND_ID : TEAM_VIEW_TREE_OCCURRENCE_SELECTED_COMMAND_ID;

        const selectedOccurrence = getService(IssueSelectionService.id).getSelectedOccurrence(issue);
        const isSelected = selectedOccurrence?.getContributingDetailIndex() === this.occurrence.getContributingDetailIndex();
        
        const isMarkerIssue = issue.isMarkerIssue();
        
        const eventInfo = issue.getEventInfo();
        const displayText = eventInfo?.getContributingDetailDisplayText() ?? 'Contributing detail';
        
        return {
            label: `${displayText} ${this.occurrence.getContributingDetailIndex() + 1}`,
            id: this.occurrence.getIdentifier(),
            tooltip: getNewIssueTreeItemTooltip_Event(issue, this.occurrence.getMainEventFilePath(), this.occurrence.getMainEventLineNumber()),
            collapsibleState: (isSelected && isMarkerIssue) ? TreeItemCollapsibleState.Expanded : TreeItemCollapsibleState.Collapsed,
            contextValue: getTreeItemContext(ContextValue.copyable),
            command: {
                command: commandId,
                arguments: [this.occurrence],
                title: "Remote Occurrence Selected in Tree" //not user facing
            },
        };
    }
}

export class EventNode implements TreeNodeProvider {
    event: NewEvent;
    parent: TreeNodeProvider;
    list: IssuesListIdentifier;
    children: TreeNodeProvider[] = [];
    isLastNode: boolean = false;

    constructor(list: IssuesListIdentifier, event: NewEvent, parent: TreeNodeProvider) {
        this.list = list;
        this.event = event;
        this.parent = parent;
    }

    getParent(): TreeNodeProvider | undefined {
        return this.parent;
    }

    getChildren(): TreeNodeProvider[] {
        let children = this.event.getChildren();
        children.forEach((childEvent) => {
            let childEventNode = new EventNode(this.list, childEvent, this);
            this.children.push(childEventNode);
        });
        return this.children;
    }

    getTreeItem(): TreeItem {
        let contextService = getService(VscodeContextService.id);
        let commandId = this.list === IssuesListIdentifier.LocalViewIssuesList ? LOCAL_VIEW_TREE_EVENT_SELECTED_COMMAND_ID : TEAM_VIEW_TREE_EVENT_SELECTED_COMMAND_ID;
        this.isLastNode = this.event.getChildren().length === 0;
        let eventType = this.event.getEventType();

        let iconPath;
        let label;
        if (eventType === issue_pb.Event.Type.MAINEVENT) {
            iconPath = {
                light: contextService.getIconPath(`issue-selected-light.svg`, "gutter", "issue"),
                dark: contextService.getIconPath(`issue-selected-dark.svg`, "gutter", "issue"),
            };
            label = `E[${this.event.getEventNumber()}] - ${this.event.getLineNumber()}: ${this.event.getEventDescription()}`
        }
        else if (eventType === issue_pb.Event.Type.DIRECTDEPENDENCY || eventType === issue_pb.Event.Type.TRANSITIVEDEPENDENCY || eventType === issue_pb.Event.Type.UNDEFINEDEVENTTYPE) {
            if (!isFeatureFlagEnabled(ENV_CODESIGHT_EDITOR_MARKERS) && eventType !== issue_pb.Event.Type.UNDEFINEDEVENTTYPE) {
                // TODO: Remove section once editor markers flag is enabled by default
                let iconFileNameDark = eventType === issue_pb.Event.Type.DIRECTDEPENDENCY ? `direct-dark.svg` : `transitive-dark.svg`;
                let iconFileNameLight = eventType === issue_pb.Event.Type.DIRECTDEPENDENCY ? `direct-light.svg` : `transitive-light.svg`;
                iconPath = {
                    light: contextService.getIconPath(iconFileNameLight, "reference-style"),
                    dark: contextService.getIconPath(iconFileNameDark, "reference-style"),
                };
            }
            let lineNumber = this.event.getLineNumber();
            let path = this.event.getFilePath();
            let description;
            if (path && lineNumber) {
                let projectName = basename(dirname(path));
                let fileName = basename(path);
                description = `- ${projectName} > ${fileName} : ${localize("transitive.dependency.line.number", "Line {0}", lineNumber)}`
            }
            label = `[${this.event.getEventNumber()}] ${this.event.getEventDescription()} ${description ?? ''}`
        }
        else {
            iconPath = {
                light: contextService.getIconPath(`event-light.svg`, "gutter", "event"),
                dark: contextService.getIconPath(`event-dark.svg`, "gutter", "event"),
            };
            label = `E[${this.event.getEventNumber()}] - ${this.event.getLineNumber()}: ${this.event.getEventDescription()}`
        }

        // Check if we're in Signal mode by looking at the parent hierarchy
        let isSignalMode = this.isInSignalMode();

        let treeItem = new TreeItem(label, this.isLastNode ? TreeItemCollapsibleState.None : TreeItemCollapsibleState.Expanded);
        treeItem.id = this.event.getIdentifier();
        treeItem.iconPath = iconPath;
        treeItem.tooltip = getNewIssueTreeItemTooltip_Event(this.event.getParentContributingDetail().getParentIssue(), this.event.getFilePath(), this.event.getLineNumber(), this.event.getEventDescription());
        treeItem.contextValue = getTreeItemContext(ContextValue.copyable);
        treeItem.command = {
            command: commandId,
            arguments: [this.event],
            title: "Event Selected in Tree" //not user facing
        };

        // Add Signal highlighting for events
        if (isSignalMode) {
            treeItem.resourceUri = Uri.parse(`${SIGNAL_RESOURCE_URI}:`);
        }

        return treeItem;
    }

    private isInSignalMode(): boolean {
        // Check if parent is an IssueNode with Signal mode
        if (this.parent instanceof IssueNode) {
            return this.parent.isSignalMode;
        }

        // Check if parent is an OccurrenceNode, then check its parent (IssueNode)
        if (this.parent instanceof OccurrenceNode && this.parent.parent instanceof IssueNode) {
            return this.parent.parent.isSignalMode;
        }

        // For nested EventNodes, check recursively
        if (this.parent instanceof EventNode) {
            return this.parent.isInSignalMode();
        }

        return false;
    }
}


export class PagerNode implements TreeNodeProvider {
    parent?: TreeNodeProvider;
    page: () => Promise<void>;
    private reloadSelf: () => Promise<void>;
    isLoading;
    loadingLock = new Semaphore(0, 1);

    constructor(reloadSelf: () => Promise<void>, page: () => Promise<void>, parent?: TreeNodeProvider) {
        this.parent = parent;
        this.page = page;
        this.reloadSelf = reloadSelf;
        this.isLoading = false;
        this.loadingLock.release();
    }

    getTreeItem(): TreeItem {
        let iconPath;
        if (this.isLoading) {
            iconPath = {
                dark: getService(VscodeContextService.id).getIconPath("spinner-dark.svg", "general"),
                light: getService(VscodeContextService.id).getIconPath("spinner-light.svg", "general"),
            };
        } else {
            iconPath = {
                dark: getService(VscodeContextService.id).getIconPath("add_circle_dark.svg", "general"),
                light: getService(VscodeContextService.id).getIconPath("add_circle_light.svg", "general"),
            };
        }
        return {
            description: `Load More`,
            iconPath: iconPath,
            command: {
                title: "Load next page", // Not user facing
                command: COMMAND_PAGER,
                arguments: [this]
            },
        };
    }

    getChildren() {
        return [];
    }

    getParent() {
        return this.parent;
    }

    async loadMore(): Promise<void> {
        await this.loadingLock.wait();
        if (this.isLoading) {
            return;
        }
        this.isLoading = true;
        this.loadingLock.release();

        await this.reloadSelf();  // Show spinner immediately
        await this.page();        // Load data and trigger full refresh

        await this.loadingLock.wait();
        this.isLoading = false;
        this.loadingLock.release();
    }
}

export class IssueSourceSelectionNode implements TreeNodeProvider {
    private activeServers: ServerInfo[];
    private sourceList: RemoteIssueSource[];
    private selectedSource: RemoteIssueSource | undefined;
    
    constructor(activeServers: ServerInfo[], sourceList: RemoteIssueSource[], selectedSource: RemoteIssueSource | undefined) {
        this.activeServers = activeServers;
        this.sourceList = sourceList;
        this.selectedSource = selectedSource;
    }

    async getTreeItem(): Promise<TreeItem> {
        const notSelectedText = localize('team.view.issue.presenter.not.selected.text', 'Not selected');
        const notConfiguredText = localize('team.view.issue.presenter.not.configured.text', 'Click to configure');
        const sourceSelectionText = localize('team.view.issue.presenter.source.selection.text', 'Source');

        let sourceItem = new LinkTreeItem();
        sourceItem.label = `${sourceSelectionText}: [ ${notSelectedText} ]`;
        sourceItem.tooltip = notConfiguredText;

        // if a server connection exists without a configured source, 
        // navigate to source config view
        if ((this.activeServers.length !== 0) && !this.selectedSource) {
            sourceItem.command = {
                title: "Configure source", // Not user facing
                command: COMMAND_OPEN_TEAM_VIEW_ISSUE_SOURCE_VIEW
            };
            return sourceItem;
        }

        // handle source not configured state
        if (this.sourceList.length === 0 && !this.selectedSource) {
            sourceItem.command = {
                title: "Open server config", // Not user facing
                command: COMMAND_SHOW_ISSUE_SOURCE_SERVER_CONFIG
            };
            return sourceItem;
        }

        // show selected source
        sourceItem.label = `${sourceSelectionText}: [ ${this.selectedSource?.fullDisplayString ?? notSelectedText} ]`;
        sourceItem.tooltip = this.getSourceTooltip(this.selectedSource);
        sourceItem.command = {
            title: "Open source selection", // Not user facing
            command: COMMAND_SHOW_CONFIGURED_SOURCES
        };
        return sourceItem;
    }

    getSourceTooltip(source: RemoteIssueSource | undefined): string {
        if (!source) {
            return "";
        }

        let serverName = getServerName(source.serverType);
        return `${serverName}: ${source.fullDisplayString}`;
    }

    getChildren() {
        return [];
    }

    getParent() {
        return undefined;
    }
}

