export class SortNode implements TreeNodeProvider {
    parent?: TreeNodeProvider;
    sortState: NewIssueSortState;

    constructor(sortState: NewIssueSortState, parent?: TreeNodeProvider) {
        this.parent = parent;
        this.sortState = sortState;
    }

    getTreeItem(): TreeItem {
        let sortItem = new TreeItem("", TreeItemCollapsibleState.None);
        sortItem.description = localize("issues.view.sort.title", "Sort: {0}", this.sortState.getDisplayString());
        sortItem.contextValue = getTreeItemContext(
            ContextValue.copyable,
            this.sortState.isAscending ? ContextValue.teamViewSortStateAscending : ContextValue.teamViewSortStateDescending
        );
        sortItem.command = {
            command: COMMAND_SORT_TEAM_VIEW_ISSUES,
            title: "Sort" //not user facing
        };
        sortItem.iconPath = new ThemeIcon("noIcon"); // an incorrect path resulting in "Sort" being aligned with its "Source" sibling (which has an icon and is indented), under Team View
        return sortItem;
    }

    getChildren() {
        return [];
    }

    getParent() {
        return this.parent;
    }
}

export enum Status {
    Loading,
    Info,
    Error
}

// Error Message nodes
export class StatusNode implements TreeNodeProvider {
    private message: string;
    private status: Status;
    private commandId: string | undefined;
    private error: Error | undefined;
    private isSignalMode: boolean;

    constructor(status: Status, message: string, commandId?: string, error?: Error, isSignalMode?: boolean) {
        this.message = message;
        this.status = status;
        this.commandId = commandId;
        this.error = error;
        this.isSignalMode = isSignalMode ?? false;
    }

    getTreeItem(): IssueTreeItem {
        let iconPath;
        switch (this.status) {
            case Status.Loading:
                iconPath = {
                    light: getService(VscodeContextService.id).getIconPath("spinner-light.svg", "general"),
                    dark: getService(VscodeContextService.id).getIconPath("spinner-dark.svg", "general")
                };
                break;
            case Status.Error:
                iconPath = getService(VscodeContextService.id).getIconPath("severity-medium.svg", "severity");
                break;
            case Status.Info:
                iconPath = getService(VscodeContextService.id).getIconPath("severity-low.svg", "severity");
                break;
        }
        let item = new IssueTreeItem(this.message, TreeItemCollapsibleState.None);
        item.iconPath = iconPath;
        if (this.commandId) {
             item.command = {
                command: this.commandId,
                arguments: [this.error],
                title: 'status node', //not user facing
            };
        }
        
        if (this.error) {
            item.error = this.error;
            item.contextValue = getTreeItemContext(
                ContextValue.viewRemoteErrorDetails,
            );
        }

        // Add Signal highlighting for status nodes
        if (this.isSignalMode) {
            item.resourceUri = Uri.parse(`${SIGNAL_RESOURCE_URI}:`);
        }

        return item;
    }

    getChildren() {
        return [];
    }

    getParent() {
        return undefined;
    }
}

