export class ButtonNode implements TreeNodeProvider {
    private buttonText: string;
    private commandID: string;
    private options: ButtonNodeOptions;

    constructor(buttonText: string, commandID: string, options?: ButtonNodeOptions) {
        this.buttonText = buttonText;
        this.commandID = commandID;
        this.options = options ?? {};
    }

    getTreeItem(): IssueTreeItem {
        let item = new LinkTreeItem();
        item.label = `[ ${this.buttonText} ]`;
        if (this.options.themeIconId) {
            item.iconPath = new ThemeIcon(this.options.themeIconId, new ThemeColor(LINK_THEME_COLOR));
        }
        item.command = {
            command: this.commandID,
            arguments: this.options.commandArgs,
            title: "button node" //not user facing
        };
        return item;
    }

    getChildren() {
        return [];
    }

    getParent() {
        return undefined;
    }
}

export type ButtonNodeOptions = {
    commandArgs?: any[];
    themeIconId?: ThemeIconId;
}

export function getScanFileScopeString(fileScope: RefreshResultsRequest.Tier): string {
    switch (fileScope) {
        case RefreshResultsRequest.Tier.ALLUNCOMMITTED:
        case RefreshResultsRequest.Tier.REFERENCEBRANCH:
            return localize("issues.view.signal.file.scope.changed.files.title", "Code Changes");
        case RefreshResultsRequest.Tier.FAST:
            return localize("issues.view.signal.file.scope.active.title", "Active File");
        default:
            return localize("issues.view.signal.file.scope.select.title", "Select File Scope");
    }
}

export class TimerNode implements TreeNodeProvider {
    constructor(
        private isActive: boolean,
        private nextScanTime?: Date,
        private lastScanTime?: Date
    ) {}

    getTreeItem(): IssueTreeItem {
        let label: string;
        let tooltip: string;
        let iconPath: { light: string; dark: string };

        if (this.isActive) {
            const parts: string[] = [];
            if (this.nextScanTime) {
                parts.push(localize('timer.next.scan.compact', 'Next auto scan in {0}', getElapsedTimeSinceDateWithPrecision(this.nextScanTime)));
            }
            if (this.lastScanTime) {
                parts.push(localize('timer.last.scan.compact', 'Last scan {0}', getElapsedTimeSinceDateWithPrecision(this.lastScanTime)));
            }
            label = parts.length > 0 ? parts.join(' \u2022 ') : localize('timer.scheduled.scans', 'Scan Scheduled');
            tooltip = localize('timer.scheduled.scans.tooltip', 'Automatically run scans every 24 hours. Manual scans reset the timer.');
            iconPath = {
                light: getService(VscodeContextService.id).getIconPath("clock-light.svg", "general"),
                dark: getService(VscodeContextService.id).getIconPath("clock-dark.svg", "general")
            };
        } else {
            label = this.lastScanTime
                ? localize('timer.last.scan.disabled', 'Last scan {0} (Disabled)', getElapsedTimeSinceDateWithPrecision(this.lastScanTime))
                : localize('timer.scheduled.scans.disabled', 'Scheduled scans disabled');
            tooltip = localize('timer.scheduled.scans.disabled.tooltip', 'Automatic scan disabled. You can enable it in the Incremental Scan Configuration view');
            iconPath = {
                light: getService(VscodeContextService.id).getIconPath("clock-disabled-light.svg", "general"),
                dark: getService(VscodeContextService.id).getIconPath("clock-disabled-dark.svg", "general")
            };
        }

        const item = new IssueTreeItem(label, TreeItemCollapsibleState.None);
        item.iconPath = iconPath;
        item.tooltip = tooltip;
        return item;
    }

    getChildren(): TreeNodeProvider[] {
        return [];
    }

    getParent() {
        return undefined;
    }
}

export function getModeString(scanMode: ScanMode): string {
    switch (scanMode) {
        case ScanMode.Auto:
            return localize("issues.view.auto.title", "Incremental Scan");
        case ScanMode.Manual:
            return localize("issues.view.manual.title", "Project Scan");
    }
}

export function getNewIssueTreeItemTooltip_Issue(issue: NewIssue) {
    let markdown = new MarkdownString(``);
    markdown.isTrusted = true;

    let columnValuesMap = issue.getValuesMap();
    let columnNamesMap = issue.getColumnNamesMap();
    columnValuesMap.forEach ((value: string, key: string) => {
        let columnName = columnNamesMap.get(key);
        markdown.appendMarkdown(`**${columnName}:**`);
        markdown.appendMarkdown(MARKDOWN_SPACE);
        if (key === "severity") {
            markdown.appendMarkdown(getIconMarkdown(issue.getIconPathForSeverity()));
        } else {
            markdown.appendMarkdown(`${value}`);
        }        
        markdown.appendMarkdown(MARKDOWN_NEWLINE);
    });

    return markdown;
}

export function getNewIssueTreeItemTooltip_Event(issue: NewIssue, filePath?: string, lineNumber?: number, description?: string): MarkdownString {
    let markdown = new MarkdownString(``);
    markdown.isTrusted = true;

    markdown.appendMarkdown(description ? description : issue.getDisplayString());
    markdown.appendMarkdown(MARKDOWN_NEWLINE);
    markdown.appendMarkdown(MARKDOWN_NEWLINE);

    if (filePath && lineNumber) {
        let file = getBaseFileName(filePath);
        markdown.appendMarkdown(localize('issue.tooltip.file', '**File:**'));
        markdown.appendMarkdown(MARKDOWN_SPACE);
        markdown.appendMarkdown(`${file}:`);
        markdown.appendMarkdown(MARKDOWN_SPACE);
        markdown.appendMarkdown(lineNumber.toString());
        markdown.appendMarkdown(MARKDOWN_NEWLINE);
    }
    
    if (issue.getSeverity() !== Severity.UNKNOWN) {
        markdown.appendMarkdown(localize('issue.tooltip.severity', '**Severity:**'));
        markdown.appendMarkdown(MARKDOWN_SPACE);
        markdown.appendMarkdown(getIconMarkdown(issue.getIconPathForSeverity()));
        markdown.appendMarkdown(MARKDOWN_SPACE);
        markdown.appendMarkdown(`${webviewUtils.severityLocalizedText(issue.getSeverity())}`);
        markdown.appendMarkdown(MARKDOWN_NEWLINE);
    }

    return markdown;
}