import { ImportCSSELicenseRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/license_service_pb";
import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { Disposable, WebviewPanel } from "vscode";
import { LocalizeFunc, loadMessageBundle } from "vscode-nls";
import { ControllerClientService } from "../../services/controllerClientService";
import { getService } from "../../services/serviceContainer";
import { SetupService } from "../../services/setupService";
import { VsCodeInputService } from "../../services/vscodeInputService";
import { getLogger } from "../../utils/logger";
import { addDelay } from "../../utils/webviewUtils";
import { WebviewCoordinator } from "../../views/webviewCoordinator";
import { WebviewPresenter } from "../webviewPresenter";
import { LicenseViewCommandIds, LicenseViewProvider } from "./licenseViewProvider";
const localize: LocalizeFunc = loadMessageBundle();

export class LicenseViewPresenter implements WebviewPresenter {
    private readonly panel: WebviewPanel;
    private view: LicenseViewProvider;
    private isInstalledTools: boolean;
    private shouldContinueFlow: boolean;
    private onMessageFromWebviewDisposable: Disposable | undefined;

    constructor(panel: WebviewPanel, isInstalledTools: boolean, shouldContinueFlow?: boolean) {
        this.panel = panel;
        this.view = getService(LicenseViewProvider.id);
        this.view.initView(this.panel);
        this.isInstalledTools = isInstalledTools;
        this.shouldContinueFlow = shouldContinueFlow ? shouldContinueFlow : false;

        this.onMessageFromWebviewDisposable = this.view.onMessageFromWebview(async message => {
            const logger = getLogger();
            switch (message.command) {
                case LicenseViewCommandIds.VIEW_PREVIOUS:
                    if (this.isInstalledTools) {
                        await getService(WebviewCoordinator.id).showInstalledToolsMessage();
                    } else {
                        await getService(WebviewCoordinator.id).showRegistrationForm(this.isInstalledTools);
                    }
                    break;
                case LicenseViewCommandIds.VIEW_CHOOSE:
                    let licenseFile = await getService(VsCodeInputService.id).showOpenDialog({ canSelectFolders: false, canSelectMany: false });
                    if (!licenseFile || licenseFile.length < 1) {
                        logger.debug("No file selected from license view browser");
                        break;
                    }
                    this.view.postMessageToWebview({
                        command: LicenseViewCommandIds.SET_LICENSE_PATH,
                        value: licenseFile[0].fsPath,
                    });

                    return this.validateLicenseFileProvided(licenseFile[0].fsPath);
                default:
                    getLogger().warn(`Received unexpected message ${message.command}`);
                    break;
            }

            return Promise.resolve();
        });
    }

    private async validateLicenseFileProvided(path: string) {
        this.setLoadingState();
        
        const licenseService = await getService(ControllerClientService.id).getLicenseServiceClient();
        let request = new ImportCSSELicenseRequest();
        request.setFilepath(path);
        let response = await licenseService.importCSSELicense(request);

        let responseMessage = response.getMessage();
        if (response.getSuccess()) {
            this.setSuccessState(responseMessage);
            await addDelay(1000); // add a second delay

            // transition to next view
            if (this.isInstalledTools && this.shouldContinueFlow) {
                await getService(SetupService.id).beginEnableStandardEditionFlow();
            } else if (this.isInstalledTools && !this.shouldContinueFlow) {
                await getService(WebviewCoordinator.id).showInstalledToolsMessage();
            } else {
                await getService(SetupService.id).beginStandardEditionFlow();
            }
        } else {
            this.setErrorState(responseMessage);
        }
    }

    public async parseNotification(message: NotificationMessage) {
        // no-op
    }

    public async initView() {
        this.view.initHtml();
        this.setInitialState();
    }

    public dispose() {
        this.onMessageFromWebviewDisposable?.dispose();
    }

    private setInitialState() {
        this.view.postMessageToWebview({ 
            command: LicenseViewCommandIds.REMOVE_SPINNER
        });
        this.view.postMessageToWebview({ 
            command: LicenseViewCommandIds.SET_CONTINUE_ENABLED,
            enabled: "false"
        });
    }

    private setLoadingState() {
        this.view.postMessageToWebview({ 
            command: LicenseViewCommandIds.SET_STATUS,
            type: LicenseViewCommandIds.STATUS_LOADING,
            message: localize('license.view.loading', 'Validating...')
        });
        this.view.postMessageToWebview({
            command: LicenseViewCommandIds.SET_CONTINUE_ENABLED,
            enabled: "false",
        });
    }

    private setSuccessState(successMessage: string) {
        this.view.postMessageToWebview({ 
            command: LicenseViewCommandIds.SET_STATUS,
            type: LicenseViewCommandIds.STATUS_VALID,
            message: successMessage
        });
        this.view.postMessageToWebview({
            command: LicenseViewCommandIds.SET_PREVIOUS_ENABLED,
            enabled: "false",
        });
        this.view.postMessageToWebview({
            command: LicenseViewCommandIds.SET_CONTINUE_ENABLED,
            enabled: "true",
        });
        this.view.postMessageToWebview({ 
            command: LicenseViewCommandIds.ADD_SPINNER_CONTINUE
        });
    }

    private setErrorState(errorMessage: string) {
        this.view.postMessageToWebview({ 
            command: LicenseViewCommandIds.SET_STATUS,
            type: LicenseViewCommandIds.STATUS_INVALID,
            message: errorMessage
        });
        this.view.postMessageToWebview({
            command: LicenseViewCommandIds.SET_CONTINUE_ENABLED,
            enabled: "false",
        });
    }
}
