import { Event, EventEmitter, ProviderResult, TreeDataProvider, TreeItem } from "vscode";
import { Copyable } from "../../utils/interfaces";

export interface UpdatableTreeAction {
    interval: number;
    action: (items: IssuesFoundTreeItem[]) => void;
}

export interface IssuesFoundTreeProvider extends TreeDataProvider<IssuesFoundTreeItem> {

    /**
     * Set the data for the Issues Found Tree
     * Triggers a refresh of the tree
     *
     * @param rootTreeItems The root items of the tree
     * @param itemTrees An optional  map of tree items to their children. Any item which does not appear as a key in
     *                  this map is presumed to be a leaf node of the tree. Defaults to an empty map if no value is
     *                  passed in to this function.
     */
    setIssues(rootTreeItems: IssuesFoundTreeItem[], itemTrees?: Map<IssuesFoundTreeItem, IssuesFoundTreeItem[]>): void;

    /**
     * Sets an interval to update tree view every x milliseconds with given action
     *
     * @param interval number in milliseconds
     * @param action function to perform
     */
     setUpdateInterval(object: UpdatableTreeAction | undefined): void;
}

export class IssuesFoundTreeItem extends TreeItem implements Copyable {

    // a string to indicate to identify if one tree represents the same underlying data model as another
    // e.g. if two tree items are representing the same issue or event
    // should be set when comparing the label and description is insufficient for determining equality
    identifier?: string;

    // The ID of the represented issue. If the tree item does not represent an issue, this value will be undefined.
    issueId?: string;

    // The index of the represented occurrence. If the tree item does not represent an occurrence, this value will be undefined.
    occurrenceIndex?: number;

    // The tool type of the represented issue. Used for tool filter functionality.
    toolType?: string;

    // The file path of the represented issue. If the tree item does not represent an issue, this value will be undefined.
    filePath?: string;

    getCopyText() {
        return this.label + (this.description ? " " + this.description : "");
    }

    equals(item: IssuesFoundTreeItem): boolean {
        if (this.identifier) {
            // item is equal iff it has a matching identifier
            if (!item.identifier) {
                return false; // the TS compiler gets mad if I try to do this inline with the === check
            }
            return this.identifier === item.identifier;
        }

        // item is equal iff it doesn't have an identifier, and the labels and descriptions match
        return !item.identifier && this.label === item.label && this.description === item.description;
    }
}

export class IssuesFoundTreeProviderImpl implements IssuesFoundTreeProvider {

    private _onDidChangeTreeData: EventEmitter<IssuesFoundTreeItem | null> = new EventEmitter<IssuesFoundTreeItem | null>();
    readonly onDidChangeTreeData: Event<IssuesFoundTreeItem | null> = this._onDidChangeTreeData.event;


    protected rootItems: IssuesFoundTreeItem[];
    protected itemToChildrenMap: Map<IssuesFoundTreeItem, IssuesFoundTreeItem[]>;
    private updateTreeInterval: NodeJS.Timeout | undefined;

    constructor() {
        this.rootItems = [];
        this.itemToChildrenMap = new Map();
    }

    setIssues(rootTreeItems: IssuesFoundTreeItem[], itemTrees?: Map<IssuesFoundTreeItem, IssuesFoundTreeItem[]>): void {
        this.rootItems = rootTreeItems;
        this.itemToChildrenMap = itemTrees ? itemTrees : new Map<IssuesFoundTreeItem, IssuesFoundTreeItem[]>();
        this._onDidChangeTreeData.fire(null); // TODO: investigate only firing for changed elements UD-4144
    }

    setUpdateInterval(updatableInterface: UpdatableTreeAction | undefined): void {
        if (this.updateTreeInterval) {
            clearInterval(this.updateTreeInterval);
        }

        if (!updatableInterface) {
            return;
        }

        this.updateTreeInterval = setInterval(() => {
            updatableInterface.action(this.rootItems);
            this._onDidChangeTreeData.fire(null);
        }, updatableInterface.interval);
    }

    getTreeItem(element: IssuesFoundTreeItem): TreeItem | Thenable<TreeItem> {
        return element;
    }

    getChildren(element?: IssuesFoundTreeItem): ProviderResult<IssuesFoundTreeItem[]> {
        if (!element) {
            return this.rootItems;
        }
        if (!this.itemToChildrenMap.has(element)) {
            return [];
        }
        return this.itemToChildrenMap.get(element);
    }

    getParent(element: IssuesFoundTreeItem): ProviderResult<IssuesFoundTreeItem> {
        let result: IssuesFoundTreeItem | undefined;

        this.itemToChildrenMap.forEach((value: IssuesFoundTreeItem[], key: IssuesFoundTreeItem) => {
            if (result) {
                return;
            }
            for (let candidate of value) {
                if (element.equals(candidate)) {
                    result = key;
                    return;
                }
            }
        });

        return result;
    }
}