import { RefreshResultsRequest, RefreshStatus } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_service_pb";
import { GetConfigurationRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/configuration_service_pb";
import { window } from "vscode";
import { ENV_CODESIGHT_SIGNAL_TIMER } from "../utils/constants";
import { getEnvVar } from "../utils/environmentUtils";
import { isChangedFileScanTier } from "../utils/fileScanInfoUtils";
import { normalizeDriveLetter } from "../utils/fileUtils";
import { getLogger } from "../utils/logger";
import { AnalysisContextService } from "./analysisContextService";
import { ControllerClientService } from "./controllerClientService";
import { EntitlementService } from "./entitlementService";
import { WarningMessageService } from "./extensionMessageService";
import { GitInfoService } from "./gitInfoService";
import { ScanService } from "./scanService";
import { ScanStatusCoordinator } from "./scanStatusCoordinator";
import { ServiceId, getService } from "./serviceContainer";
import { VscodeContextService } from "./vscodeContextService";

export interface SignalTimerServiceListener {
    onTimerStateChanged(isTimerActive: boolean, nextScanTime: Date | undefined, lastScanTime: Date | undefined): Promise<void>;
    refreshTimerDisplay?(): Promise<void>;
}

export abstract class SignalTimerService {
    static readonly id: ServiceId<SignalTimerService> = { id: SignalTimerService.name };

    /**
     * Starts the timer if conditions are met (AI enabled, timer config enabled)
     */
    abstract startTimer(): Promise<void>;

    /**
     * Stops the timer
     */
    abstract stopTimer(): void;

    /**
     * Resets the timer (restarts countdown)
     */
    abstract resetTimer(): Promise<void>;

    /**
     * Returns whether timer is currently active
     */
    abstract isTimerActive(): boolean;

    /**
     * Returns the next scheduled scan time
     */
    abstract getNextScanTime(): Date | undefined;

    /**
     * Returns the last scan time
     */
    abstract getLastScanTime(): Date | undefined;

    /**
     * Returns the timer interval in milliseconds
     */
    abstract getTimerIntervalMs(): number;

    /**
     * Adds a listener for timer state changes
     */
    abstract addListener(listener: SignalTimerServiceListener): void;

    /**
     * Removes a listener for timer state changes
     */
    abstract removeListener(listener: SignalTimerServiceListener): void;

    /**
     * Called when scan results are received
     */
    abstract onScanCompleted(status: RefreshStatus.Status): Promise<void>;

    /**
     * Called when AI mode is enabled/disabled
     */
    abstract onAIModeChanged(enabled: boolean): Promise<void>;

    /**
     * Called when timer-based scan configuration is changed
     */
    abstract onTimerConfigChanged(enabled: boolean): Promise<void>;

    /**
     * Called when the scan file scope changes.
     * Stops the timer when switching to Active File scope; restarts it when switching back.
     */
    abstract onScanFileScopeChanged(fileScope: RefreshResultsRequest.Tier): Promise<void>;

    /**
     * Returns whether timer-based scans are configured (regardless of active state)
     */
    abstract isTimerBasedScanConfigured(): Promise<boolean>;

    /**
     * Returns whether timer-based scans should be considered enabled for UI purposes
     * This uses cached state to avoid race conditions with config changes
     */
    abstract isTimerBasedScanEnabledForUI(): boolean;

    /**
     * Restores last scan time from persistent storage on startup
     */
    abstract restoreLastScanTimeOnStartup(): Promise<void>;

    /**
     * Initializes the timer service
     */
    abstract init(): Promise<void>;

    /**
     * Disposes the timer service and stops all timers
     * Called when all listeners have been removed
     */
    abstract dispose(): void;

}

export class SignalTimerServiceImpl extends SignalTimerService {
    private timer: NodeJS.Timeout | undefined;
    private displayRefreshTimer: NodeJS.Timeout | undefined;
    private nextScanTime: Date | undefined;
    private lastScanTime: Date | undefined;
    private listeners: SignalTimerServiceListener[] = [];
    private readonly DEFAULT_TIMER_HOURS = 24;
    private readonly DISPLAY_REFRESH_INTERVAL_MS = 60 * 1000; // Refresh display every minute
    private cachedTimerConfigEnabled: boolean | undefined; // Cache to avoid race conditions

    async startTimer(): Promise<void> {
        const logger = getLogger();

        // Only start if Signal view and AI mode are enabled
        if (!this.shouldTimerBeActive()) {
            logger.debug("Timer conditions not met, not starting Signal timer");
            return;
        }

        // Check if timer-based scans are configured
        const isTimerBasedScanEnabled = await this.isTimerBasedScanConfigured();
        if (!isTimerBasedScanEnabled) {
            logger.debug("Timer-based scans not enabled in configuration, not starting Signal timer");
            return;
        }

        // Stop existing timer if running
        await this.stopTimer();

        const intervalMs = this.getTimerIntervalMs();
        this.nextScanTime = new Date(Date.now() + intervalMs);

        logger.info(`Starting Signal timer. Next scan scheduled for: ${this.nextScanTime.toISOString()}`);

        this.timer = setTimeout(async () => {
            await this.triggerSignalScan();
        }, intervalMs);

        await this.notifyListeners();
        this.startDisplayRefreshTimer();
    }

    /**
     * Starts the timer without checking configuration (used when config was just changed)
     */
    private async startTimerForced(): Promise<void> {
        const logger = getLogger();

        // Stop existing timer if running
        await this.stopTimer();

        const intervalMs = this.getTimerIntervalMs();
        this.nextScanTime = new Date(Date.now() + intervalMs);

        logger.info(`Starting Signal timer (forced). Next scan scheduled for: ${this.nextScanTime.toISOString()}`);

        this.timer = setTimeout(async () => {
            await this.triggerSignalScan();
        }, intervalMs);

        await this.notifyListeners();
        this.startDisplayRefreshTimer();
    }

    async stopTimer(): Promise<void> {
        const logger = getLogger();

        if (this.timer) {
            logger.info("Stopping Signal timer");
            clearTimeout(this.timer);
            // Don't clear lastScanTime - preserve it to show when last scan occurred
            // Keep display refresh timer running if we have lastScanTime to display

            this.timer = undefined;
            this.nextScanTime = undefined;

            await this.notifyListeners();
        }
    }

    async resetTimer(): Promise<void> {
        const logger = getLogger();
        logger.debug("Resetting Signal timer");

        if (this.timer) {
            await this.startTimer(); // This will stop the existing timer and start a new one
        }
    }

    isTimerActive(): boolean {
        return this.timer !== undefined;
    }

    getNextScanTime(): Date | undefined {
        return this.nextScanTime;
    }

    getLastScanTime(): Date | undefined {
        return this.lastScanTime;
    }

    getTimerIntervalMs(): number {
        const envValue = getEnvVar(ENV_CODESIGHT_SIGNAL_TIMER);
        let hours = this.DEFAULT_TIMER_HOURS;

        if (envValue) {
            const parsed = parseFloat(envValue);
            if (!isNaN(parsed) && parsed > 0) {
                hours = parsed;
            } else {
                getLogger().warn(`Invalid CODESIGHT_SIGNAL_TIMER value: ${envValue}. Using default ${this.DEFAULT_TIMER_HOURS} hours`);
            }
        }

        return hours * 60 * 60 * 1000; // Convert hours to milliseconds
    }

    addListener(listener: SignalTimerServiceListener): void {
        this.listeners.push(listener);
    }

    removeListener(listener: SignalTimerServiceListener): void {
        const index = this.listeners.indexOf(listener);
        if (index >= 0) {
            this.listeners.splice(index, 1);
        }

        // If no more listeners, dispose of timers
        if (this.listeners.length === 0) {
            getLogger().debug("No more listeners for SignalTimerService, disposing timers");
            this.dispose();
        }
    }

    async onScanCompleted(status: RefreshStatus.Status): Promise<void> {
        const logger = getLogger();
        logger.debug(`Signal scan status update: ${status}`);

        // Only reset timer when scan is finished
        if (status === RefreshStatus.Status.SUCCESS || 
            status === RefreshStatus.Status.FAILED || 
            status === RefreshStatus.Status.CANCELLED) {

            this.lastScanTime = new Date();
            logger.debug(`Signal scan finished with status: ${status}, resetting timer`);

            // Save last scan time
            await this.preserveLastScanTime();

            // Reset timer only when scan actually finishes
            if (this.isTimerActive()) {
                await this.resetTimer();
            }
        }
    }

    async onAIModeChanged(enabled: boolean): Promise<void> {
        const logger = getLogger();
        logger.debug(`AI mode changed to: ${enabled}`);

        if (enabled) {
            // AI was enabled, start timer if conditions are met
            await this.startTimer();
        } else {
            // AI was disabled, stop timer
            await this.stopTimer();
        }
    }

    async onScanFileScopeChanged(fileScope: RefreshResultsRequest.Tier): Promise<void> {
        const logger = getLogger();
        logger.debug(`Scan file scope changed to: ${fileScope}`);

        if (fileScope === RefreshResultsRequest.Tier.FAST) {
            // Active File scope — stop the timer
            await this.stopTimer();
        } else {
            // Code Changes scope — restart timer if it was configured
            await this.startTimer();
        }
    }

    async onTimerConfigChanged(enabled: boolean): Promise<void> {
        const logger = getLogger();
        logger.debug(`Timer-based scan configuration changed to: ${enabled}`);

        // Cache the new configuration state immediately
        this.cachedTimerConfigEnabled = enabled;

        if (enabled && this.shouldTimerBeActive()) {
            // Timer-based scans were enabled and conditions are met, start timer
            // Skip the config check since we know it was just changed
            await this.startTimerForced();
        } else {
            // Timer-based scans were disabled or conditions not met, stop timer
            await this.stopTimer();
        }

        // Always notify listeners when configuration changes, regardless of timer state
        // This ensures the UI reflects the configuration change immediately
        await this.notifyListeners();
    }

    private shouldTimerBeActive(): boolean {
        // Check if Signal view is enabled
        if (!getService(EntitlementService.id).getCachedProductEntitlement().isSignalEntitled()) {
            return false;
        }

        // Check if AI mode is enabled
        const aiModeEnabled = getService(VscodeContextService.id).getPreservedAIMode();
        return aiModeEnabled === true;
    }

    async isTimerBasedScanConfigured(): Promise<boolean> {
        try {
            const configServiceClient = await getService(ControllerClientService.id).getConfigurationServiceClient();
            const getConfigRequest = new GetConfigurationRequest();
            const configRequestFilter = new GetConfigurationRequest.Filter();
            configRequestFilter.setExcludeprojects(true);
            getConfigRequest.setFilter(configRequestFilter);
            getConfigRequest.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());

            const config = await configServiceClient.getConfiguration(getConfigRequest);
            const userConfig = config.getUserconfig();
            const signalConfig = userConfig?.getSignalconfig();

            const isEnabled = signalConfig?.getTimerbasedscan()?.getValue() || false;

            // Update cache with current configuration
            this.cachedTimerConfigEnabled = isEnabled;

            return isEnabled;
        } catch (error) {
            getLogger().error("Failed to get timer-based scan configuration", error);
            return false;
        }
    }

    isTimerBasedScanEnabledForUI(): boolean {
        // Use cached state if available (most reliable after config changes)
        if (this.cachedTimerConfigEnabled !== undefined) {
            return this.cachedTimerConfigEnabled;
        }

        // Fallback: if timer is currently active, assume it's enabled
        return this.isTimerActive();
    }

    private async triggerSignalScan(): Promise<void> {
        const logger = getLogger();

        try {
            logger.info("Timer triggered Signal scan");

            // Check if a scan is already running - don't start another
            const scanService = getService(ScanService.id);
            if (await scanService.isLocalViewSignalScanRunning()) {
                logger.info("Signal scan already running, skipping timer-triggered scan");
                await this.resetTimer();
                return;
            }

            // Get current file scope from scan status coordinator
            const fileScope = getService(ScanStatusCoordinator.id).getCurrentScanFileScope();
            let filePaths: string[] = [];

            // Determine file paths based on current file scope setting
            if (fileScope === RefreshResultsRequest.Tier.FAST) {
                // Active file (Fast) - send file paths
                let activeEditorFilePath = window.activeTextEditor?.document.uri.fsPath;
                if (!activeEditorFilePath) {
                    await this.resetTimer();
                    return getService(WarningMessageService.id).noFileOpenSingleFileScanWarning();
                }
                filePaths.push(normalizeDriveLetter(activeEditorFilePath));
            }
            // For Code Changes (ALLUNCOMMITTED or REFERENCEBRANCH) - don't send file paths
            // Mark scanning state immediately so the UI shows "Scan in progress" without
            // waiting for the controller's RUNNING notification to arrive.
            if (isChangedFileScanTier(fileScope)) {
                const gitInfoService = getService(GitInfoService.id);
                const response = await gitInfoService.checkGitRepoForChangedFiles();
                if (response && !await gitInfoService.handleGitRepoHasChangedFilesResponse(response)) {
                    await this.resetTimer();
                    return;
                }
                // Mark scanning state immediately so the UI shows "Scan in progress" without
                // waiting for the controller's RUNNING notification to arrive.
                await scanService.markSignalScanPending();
            }

            // Trigger the Signal scan with current file scope
            await scanService.requestSignalScan(filePaths, fileScope);
        } catch (error) {
            logger.error("Failed to trigger timer-based Signal scan", error);
            // On error, reset timer to try again later
            await this.resetTimer();
        }
    }

    async restoreLastScanTimeOnStartup(): Promise<void> {
        const stored = getService(VscodeContextService.id).getPreservedSignalLastScanTime();
        if (stored) {
            this.lastScanTime = stored;
            getLogger().debug(`Restored last scan time: ${stored.toISOString()}`);
        }
    }

    async init(): Promise<void> {
        const logger = getLogger();
        logger.debug("Initializing SignalTimerService");

        // Restore last scan time from storage
        await this.restoreLastScanTimeOnStartup();
    }

    dispose(): void {
        const logger = getLogger();
        logger.debug("Disposing SignalTimerService");

        // Stop main timer
        if (this.timer) {
            clearTimeout(this.timer);
            this.timer = undefined;
        }

        // Stop display refresh timer
        this.stopDisplayRefreshTimer();

        // Clear timing state
        this.nextScanTime = undefined;

        // Clear listeners array
        this.listeners = [];

        logger.debug("SignalTimerService disposed successfully");
    }

    private async preserveLastScanTime(): Promise<void> {
        if (this.lastScanTime) {
            await getService(VscodeContextService.id).preserveSignalLastScanTime(this.lastScanTime);
        }
    }

    private startDisplayRefreshTimer(): void {
        // Stop existing refresh timer if running
        this.stopDisplayRefreshTimer();

        // Start refresh timer if we have timer info to display (active timer or lastScanTime)
        if (this.isTimerActive() || this.lastScanTime) {
            this.displayRefreshTimer = setInterval(async () => {
                // Continue refreshing as long as we have timer info to display
                if (this.isTimerActive() || this.lastScanTime) {
                    await this.refreshTimerDisplay();
                } else {
                    this.stopDisplayRefreshTimer();
                }
            }, this.DISPLAY_REFRESH_INTERVAL_MS);
        }
    }

    private stopDisplayRefreshTimer(): void {
        if (this.displayRefreshTimer) {
            clearInterval(this.displayRefreshTimer);
            this.displayRefreshTimer = undefined;
        }
    }

    private async refreshTimerDisplay(): Promise<void> {
        const promises = this.listeners
            .filter(listener => listener.refreshTimerDisplay)
            .map(listener => listener.refreshTimerDisplay!());

        try {
            await Promise.all(promises);
        } catch (error) {
            getLogger().error("Error refreshing timer display", error);
        }
    }

    private async notifyListeners(): Promise<void> {
        const promises = this.listeners.map(listener => 
            listener.onTimerStateChanged(this.isTimerActive(), this.nextScanTime, this.lastScanTime)
        );

        try {
            await Promise.all(promises);
        } catch (error) {
            getLogger().error("Error notifying SignalTimerService listeners", error);
        }
    }
}