import { Webview } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { ServiceId } from "../../services/serviceContainer";
import { BUTTON_STYLING, getWebviewHead } from "../../utils/webviewUtils";
import { WebviewProvider } from "../webviewProvider";

const localize: LocalizeFunc = loadMessageBundle();

enum PROXY {
    systemProxy,
    noProxy,
    ManualProxy
}

export abstract class ProxyViewProvider extends WebviewProvider {
    static readonly id: ServiceId<ProxyViewProvider> = { id: ProxyViewProvider.name };

    abstract initHtml(): void;
}

export class ProxyViewProviderImpl extends ProxyViewProvider {
    constructor() {
        super();
    }

    public initHtml(): void {
        let systemProxyLabel = localize('proxy.systemProxy', 'Use System Proxy');
        let systemProxyTooltip = localize('proxy.systemProxyTooltip', 'Code Sight will use proxy server from environment variables, http_proxy and https_proxy, if set, otherwise proxy configuration from OS settings will be used.');

        let noProxyLabel = localize('proxy.noProxy', 'No Proxy');
        let noProxyTooltip = localize('proxy.noProxyTooltip', 'Code Sight will not use proxy settings');

        let manualProxyLabel = localize('proxy.manualProxy', 'Manual Proxy');
        let manualProxyTooltip = localize('proxy.manualProxyTooltip', 'Code Sight will use manual proxy settings');

        let httpLabel = localize('proxy.http', 'HTTP');
        let httpsLabel = localize('proxy.https', 'HTTPS');
        let hostnameLabel = localize('proxy.hostname', 'Host Name:');
        let portLabel = localize('proxy.port', 'Port Number:');
        let loginLabel = localize('proxy.login', 'Login:');
        let passwordLabel = localize('proxy.password', 'Password:');
        let passwordPlaceholder = localize('proxy.passwordPlaceholder', '*****');
        let proxyAuthLabel = localize('proxy.proxyAuth', 'Proxy authentication');

        let noProxyForLabel = localize('proxy.noProxyFor', 'No Proxy for:');
        let noProxyForExampleLabel = localize('proxy.noProxyForExample', 'Example: domain.com,192.168.4.1');
        let noProxyForTooltip = localize('proxy.noProxyForTooltip', 'List of hosts that should be excluded from proxying separated by commas');

        let saveSettingsLabel = localize('proxy.saveSettings', 'Save settings');


        // element ids
        let systemProxyId = 'systemProxy';
        let noProxyId = 'noProxy';
        let manualProxyId = 'manualProxy';

        let httpCheckboxId = 'httpCheckbox';
        let httpCheckboxLabelId = 'httpCheckboxLabel';
        let httpHostnameId = 'httpHostname';
        let httpPortId = 'httpPort';
        let httpAuthId = 'httpAuth';
        let httpUsernameId = 'httpUsername';
        let httpPasswordId = 'httpPassword';

        let httpsCheckboxId = 'httpsCheckbox';
        let httpsCheckboxLabelId = 'httpsCheckboxLabel';
        let httpsHostnameId = 'httpsHostname';
        let httpsPortId = 'httpsPort';
        let httpsAuthId = 'httpsAuth';
        let httpsUsernameId = 'httpsUsername';
        let httpsPasswordId = 'httpsPassword';

        let bypassListId = 'bypassList';

        let statusIconId = 'statusIcon';
        let statusMessageId = 'statusMessage';
        let errorIconClass = 'severity-high';
        let successIconClass = 'success-icon';
        let spinnerIconClass = 'spinner-icon';

        let html = `<!DOCTYPE html>
        <html lang="en">
        <head>
            ${this.head}
        </head>
        <style>
            ${this.style}
        </style>
        <body class="fixedView">
            <section class='column-flex-view'>
                <!--Use System Proxy radio button -->
                <div class='row'>
                    <input type='radio' name='proxyType' id='${systemProxyId}' value='${PROXY.systemProxy}' class='vertical-align-text-top' onchange="onRadioButtonClick(this)">
                    <label for='systemProxy'>${systemProxyLabel}</label>
                    <img class='hint-icon align-middle' title="${systemProxyTooltip}">
            
                <!--No Proxy radio button -->
                <div class='row'>
                    <input type='radio' name='proxyType' id='${noProxyId}' value='${PROXY.noProxy}' class='vertical-align-text-top' onchange="onRadioButtonClick(this)">
                    <label for='noProxy'>${noProxyLabel}</label>
                    <img class='hint-icon align-middle' title="${noProxyTooltip}">
                </div>
                
                <!--Manual Proxy radio button -->
                <div class='row'>
                    <input type='radio' name='proxyType' id='${manualProxyId}' value='${PROXY.ManualProxy}' class='vertical-align-text-top' onchange="onRadioButtonClick(this)">
                    <label for='manualProxy'>${manualProxyLabel}</label>
                    <img class='hint-icon align-middle' title="${manualProxyTooltip}">
                </div>
                
                <!--HTTP information -->
                <div id='httpDiv' class='row-flex-view info-section'>
                    <span style='min-width: 100px;'>
                        <input type="checkbox" id='${httpCheckboxId}' class='vertical-align-text-top' onchange="onHttpCheckboxClicked(this.checked)">
                        <label id='${httpCheckboxLabelId}' for='httpCheckbox'><strong>${httpLabel}</strong></label>
                    </span>
                    
                    <section class='column-flex-view host-port-section' data-http-info>
                        <div>
                            <label>${hostnameLabel}</label>
                            <input id='${httpHostnameId}'>
                        </div>
                        
                        <div>
                            <label>${portLabel}</label>
                            <input class='port' type='number' id='${httpPortId}'>
                        </div>
                        
                        <div>
                            <input type='checkbox' id='${httpAuthId}' onchange="onHttpAuthCheckboxChanged(this.checked)" />
                            <label for='httpAuth'>${proxyAuthLabel}</label>
                        </div>
                        
                        <div>
                            <label data-http-auth>${loginLabel}</label>
                            <input data-http-auth id='${httpUsernameId}'>
                        </div>
                        
                        <div>
                            <label data-http-auth>${passwordLabel}</label>
                            <input type='password' data-http-auth id='${httpPasswordId}'>
                        </div>
                    </section>
                </div>
                
                <!--HTTPS information -->
                <div class='row-flex-view info-section'>
                    <span style='min-width: 100px;'>
                        <input type="checkbox" id='${httpsCheckboxId}' class='vertical-align-text-top' onchange="onHttpsCheckboxClicked(this.checked)">
                        <label id='${httpsCheckboxLabelId}' for='httpsCheckbox'><strong>${httpsLabel}</strong></label>
                    </span>
                    
                    <section class='column-flex-view host-port-section' data-https-info>
                        <div>
                            <label>${hostnameLabel}</label>
                            <input id='${httpsHostnameId}'>
                        </div>
                        
                        <div>
                            <label>${portLabel}</label>
                            <input class='port' type='number' id='${httpsPortId}'>
                        </div>
                        
                        <div>
                            <input type='checkbox' id='${httpsAuthId}' onchange="onHttpsAuthCheckboxChanged(this.checked)" />
                            <label for='httpsAuth'>${proxyAuthLabel}</label>
                        </div>
                        
                        <div>
                            <label data-https-auth>${loginLabel}</label>
                            <input data-https-auth id='${httpsUsernameId}'>
                        </div>
                        
                        <div>
                            <label data-https-auth>${passwordLabel}</label>
                            <input type='password' data-https-auth id='${httpsPasswordId}'>
                        </div>
                    </section>
                </div>
                
                <!--No Proxy for section -->
                <div class='row-flex-view info-section' data-bypass-info>
                    <span style="min-width: 220px;">
                        <label>${noProxyForLabel}</label>
                        <img class='hint-icon align-middle' title="${noProxyForTooltip}">
                    </span>
                    
                    <span class='column-flex-view' style='flex-grow: 1;'>
                        <textarea rows="2" id='${bypassListId}' onkeyup='onBypassListChange(this);'></textarea>
                        <label>${noProxyForExampleLabel}</label>
                    </span>
                </div>
                
                <!-- Error section -->
                <div class='row row-flex-view outer-section'>
                    <img id='${statusIconId}' class='align-middle hidden' height='16' width='16'/>
                    <label id='${statusMessageId}' style='margin-left: 5px;'></label>
                </div>
                
                <!-- Save settings button -->
                <div class='row outer-section'>
                    <button class="button-small save-button" onclick="onSaveSettingsClick()">${saveSettingsLabel}</button>
                </div>
            </section>
        </body>
        <script>
            const vscode = acquireVsCodeApi();
        
            window.onload = () => {
                // Command handlers and Listeners
                window.addEventListener('message', event => {
                    const message = event.data;
                    switch (message.command) {
                        case '${ProxyViewCommandIds.SET_SYSTEM_PROXY_CHECKBOX}':
                            _setCheckbox('${systemProxyId}', message.value === "true");
                            break;
                        case '${ProxyViewCommandIds.SET_NO_PROXY_CHECKBOX}':
                            _setCheckbox('${noProxyId}', message.value === "true");
                            break;
                        case '${ProxyViewCommandIds.SET_MANUAL_PROXY_CHECKBOX}':
                            _setCheckbox('${manualProxyId}', message.value === "true");
                            break;
                        case '${ProxyViewCommandIds.SET_BYPASS_LIST}':
                            _setInput('${bypassListId}', message.value);
                            break;
                        
                        // http section
                        case '${ProxyViewCommandIds.SET_HTTP_VALUES}':
                            _setCheckbox('${httpCheckboxId}', message.enabled === "true");
                            _setInput('${httpHostnameId}', message.hostname);
                            _setInput('${httpPortId}', message.port);
                            _setCheckbox('${httpAuthId}', message.auth === "true");
                            _setInput('${httpUsernameId}', message.username);
                            if (message.username && message.auth === "true") {
                                _setPlaceholder('${httpPasswordId}', '${passwordPlaceholder}');
                            }

                            break;
                            
                        // https section
                        case '${ProxyViewCommandIds.SET_HTTPS_VALUES}':
                            _setCheckbox('${httpsCheckboxId}', message.enabled === "true");
                            _setInput('${httpsHostnameId}', message.hostname);
                            _setInput('${httpsPortId}', message.port);
                            _setCheckbox('${httpsAuthId}', message.auth === "true");
                            _setInput('${httpsUsernameId}', message.username);
                            if (message.username && message.auth === "true") {
                                _setPlaceholder('${httpsPasswordId}', '${passwordPlaceholder}');
                            }

                            break;
                            
                        case '${ProxyViewCommandIds.SET_STATUS_MESSAGE}':
                            _setStatusMessage(message.status, message.message);
                            break;
                        case '${ProxyViewCommandIds.CLEAR_STATUS_MESSAGE}':
                            _clearStatusMessage();
                            break;
                    }
                });
            };
            
            function onSaveSettingsClick(){
                let noProxy = document.getElementById('${noProxyId}').checked ? 'true' : 'false';
                let systemProxy = document.getElementById('${systemProxyId}').checked ? 'true' : 'false';
                
                let httpEnabled = document.getElementById('${httpCheckboxId}').checked ? 'true' : 'false';
                let httpHostname = document.getElementById('${httpHostnameId}').value;
                let httpPort = document.getElementById('${httpPortId}').value;
                let httpAuth = document.getElementById('${httpAuthId}').checked ? 'true' : 'false';
                let httpUsername = document.getElementById('${httpUsernameId}').value;
                let httpPassword = document.getElementById('${httpPasswordId}').value;
                
                let httpsEnabled = document.getElementById('${httpsCheckboxId}').checked ? 'true' : 'false';
                let httpsHostname = document.getElementById('${httpsHostnameId}').value;
                let httpsPort = document.getElementById('${httpsPortId}').value;
                let httpsAuth = document.getElementById('${httpsAuthId}').checked ? 'true' : 'false';
                let httpsUsername = document.getElementById('${httpsUsernameId}').value;
                let httpsPassword = document.getElementById('${httpsPasswordId}').value;

                // Clear watermark since the controller forgets the password if proxy auth is disabled
                if (httpAuth === "false") {
                    _setPlaceholder('${httpPasswordId}', '');
                }

                if (httpsAuth === "false") {
                    _setPlaceholder('${httpsPasswordId}', '');
                }
                
                let bypassList = document.getElementById('${bypassListId}').value;
                
                vscode.postMessage({
                    command: '${ProxyViewCommandIds.SAVE_SETTINGS}',
                    noProxy: noProxy,
                    systemProxy: systemProxy,
                    
                    httpEnabled: httpEnabled,
                    httpHostname: httpHostname,
                    httpPort: httpPort,
                    httpAuth: httpAuth,
                    httpUsername: httpUsername,
                    httpPassword: httpPassword,
                    
                    httpsEnabled: httpsEnabled,
                    httpsHostname: httpsHostname,
                    httpsPort: httpsPort,
                    httpsAuth: httpsAuth,
                    httpsUsername: httpsUsername,
                    httpsPassword: httpsPassword,
                    
                    bypassList: bypassList
                });
            }
        
            function onRadioButtonClick(el) {
                if (el.value == ${PROXY.noProxy} || el.value == ${PROXY.systemProxy}) {
                    // disable http section
                    document.getElementById("${httpCheckboxId}").setAttribute('disabled', true);
                    document.getElementById("${httpCheckboxLabelId}").setAttribute('disabled', true);
                    onHttpCheckboxClicked(false);
                    
                    // disable https section
                    document.getElementById("${httpsCheckboxId}").setAttribute('disabled', true);
                    document.getElementById("${httpsCheckboxLabelId}").setAttribute('disabled', true);
                    onHttpsCheckboxClicked(false);
                    
                    // disable proxy bypass section
                    for(let element of _getNoProxyElements()){
                        element.setAttribute('disabled', true);
                    }
                } else {
                    // enable http section
                    document.getElementById("${httpCheckboxId}").removeAttribute('disabled');
                    document.getElementById("${httpCheckboxLabelId}").removeAttribute('disabled');
                    onHttpCheckboxClicked(document.getElementById("${httpCheckboxId}").checked);
                    
                    // enable https section
                    document.getElementById("${httpsCheckboxId}").removeAttribute('disabled');
                    document.getElementById("${httpsCheckboxLabelId}").removeAttribute('disabled');
                    onHttpsCheckboxClicked(document.getElementById("${httpsCheckboxId}").checked);
                    
                    // enable proxy bypass section
                    for(let element of _getNoProxyElements()){
                        element.removeAttribute('disabled');
                    }
                }
            }
            
            function onHttpCheckboxClicked(checked) {
                if (checked) {
                    // enable all required elements
                    for(let element of _getHttpInfoElements()){
                        element.removeAttribute('disabled');
                    }
                    onHttpAuthCheckboxChanged(document.getElementById("${httpAuthId}").checked);
                } else {
                    // disable all http elements
                    for(let element of _getHttpInfoElements()){
                        element.setAttribute('disabled', true);
                    }
                    onHttpAuthCheckboxChanged(false);
                }
            }
            
            function onHttpsCheckboxClicked(checked) {
                if (checked) {
                    // enable all required elements
                    for(let element of _getHttpsInfoElements()){
                        element.removeAttribute('disabled');
                    }
                    onHttpsAuthCheckboxChanged(document.getElementById("${httpsAuthId}").checked);
                } else {
                    // disable all http elements
                    for(let element of _getHttpsInfoElements()){
                        element.setAttribute('disabled', true);
                    }
                    onHttpsAuthCheckboxChanged(false);
                }
            }
            
            function onHttpAuthCheckboxChanged(checked) {
                let elements = Array.from(document.querySelectorAll("[data-http-auth]"));
                for(let element of elements){
                    checked ? element.removeAttribute('disabled') : element.setAttribute('disabled', true);
                }
            }
            
            function onHttpsAuthCheckboxChanged(checked) {
                let elements = Array.from(document.querySelectorAll("[data-https-auth]"));
                for(let element of elements){
                    checked ? element.removeAttribute('disabled') : element.setAttribute('disabled', true);
                }
            }
            
            function onBypassListChange(el) {
                if (el.value.includes('\\n')){
                    el.value = el.value.replace('\\n','');
                }
            }
            
            // Helpers
            
            function _getHttpInfoElements(){
                let inputs = Array.from(document.querySelectorAll("[data-http-info] input:not([data-http-auth])"));
                let labels = Array.from(document.querySelectorAll("[data-http-info] label:not([data-http-auth])"));
                return inputs.concat(labels);
            }
            
            function _getHttpsInfoElements(){
                let inputs = Array.from(document.querySelectorAll("[data-https-info] input:not([data-https-auth])"));
                let labels = Array.from(document.querySelectorAll("[data-https-info] label:not([data-https-auth])"));
                return inputs.concat(labels);
            }
            
            function _getNoProxyElements(){
                let labels = Array.from(document.querySelectorAll("[data-bypass-info] label"));
                let inputs = Array.from(document.querySelectorAll("[data-bypass-info] textarea"));
                return inputs.concat(labels);
            }
            
            function _setCheckbox(id, value){
                let checkbox = document.getElementById(id);
                if (checkbox){
                    const e = new Event("change");
                    if (value){
                        checkbox.setAttribute('checked', true);       
                    } else {
                        checkbox.removeAttribute('checked');   
                    }
                    checkbox.dispatchEvent(e);
                }
            }
            
            function _setInput(id, value){
                let input = document.getElementById(id);
                if (input && input.value !== undefined){
                    input.value = value;
                }
            }

            function _setPlaceholder(id, value){
                let input = document.getElementById(id);
                if (input && input.value !== undefined){
                    input.placeholder = value;
                }
            }
            
            function _setStatusMessage(status, message){
                _clearStatusMessage();
                let iconEl = document.getElementById('${statusIconId}');
                iconEl.classList.remove('hidden');
                
                let labelEl = document.getElementById('${statusMessageId}');
                labelEl.innerHTML = message;
                switch (status){
                    case '${ProxyStatusMessageEnum.Loading}':
                        iconEl.classList.add('${spinnerIconClass}');
                        break;
                    case '${ProxyStatusMessageEnum.Success}':
                        iconEl.classList.add('${successIconClass}');
                        break;
                    case '${ProxyStatusMessageEnum.Error}':
                        iconEl.classList.add('${errorIconClass}');
                        labelEl.classList.add('red-text');
                        break;
                }
            }
            
            function _clearStatusMessage(){
                let iconEl = document.getElementById('${statusIconId}');
                let labelEl = document.getElementById('${statusMessageId}');
                iconEl.classList.remove('${errorIconClass}');
                iconEl.classList.remove('${successIconClass}');
                iconEl.classList.remove('${spinnerIconClass}');
                iconEl.classList.add('hidden');
                labelEl.classList.remove('red-text');
                labelEl.innerHTML = "";    
            }
        </script>`;

        this.webviewPanel!.webview.html = html;
    }

    protected getHead(webview: Webview): string {
        return getWebviewHead("Proxy Settings", webview);
    }

    protected getStyle(): string {
        return `
            .column-flex-view {
                display: flex;
                flex-direction: column;
            }
            
            .row-flex-view {
                display: flex;
                flex-direction: row;
            }
            
            input[type=checkbox] {
                margin-left: 0px;
            }
            
            input[type=radio], input[type=checkbox] {
                outline: none;
            }
            
            label {
                user-select: none;
            }
            
            .align-middle {
                vertical-align: middle;
            }
            
            .host-port-section {
                flex-grow: 1;
            }
            
            .host-port-section label {
                min-width: 120px;
            }
            
            .host-port-section div {
                margin: 2px 0 2px 0;
                display: flex;
                flex-grow: 1;
            }
            
            .host-port-section input {
                flex-grow: 4;
            }
            
            .host-port-section input.port {
                max-width: 80px;
            }
            
            .host-port-section input[type=checkbox] {
                flex-grow: 0;
            }
            
            div.row {
                margin-top: 10px;
            }
            
            div.info-section {
                margin: 10px 0 0 30px;
            }
            
            div.outer-section {
                margin-left: 3px;
                min-height: 20px; /* Need this so error message div doesn't disappear making save settings button jump up and down */
            }
            
            textarea {
                resize: none;
            }
            
            .vertical-align-text-top {
                vertical-align: text-top;
            }
            
            label[disabled] {
                opacity: 0.5;
            }
            
            .red-text {
                color: red;
            }
            
            .fixedView {
                max-width: 900px;
                min-width: 550px;
            }
            
            .save-button {
                min-width: 150px;
            }
            
            ${BUTTON_STYLING}

            input:focus::placeholder {
                color: transparent;
            }
        `;
    }
}

export namespace ProxyViewCommandIds {
    export const SET_SYSTEM_PROXY_CHECKBOX: string = "set-system-proxy-checkbox";
    export const SET_NO_PROXY_CHECKBOX: string = "set-no-proxy-checkbox";
    export const SET_MANUAL_PROXY_CHECKBOX: string = "set-manual-proxy-checkbox";

    export const SET_HTTP_VALUES: string = "set-http-values";
    export const SET_HTTPS_VALUES: string = "set-https-values";
    export const SET_BYPASS_LIST: string = "set-bypass-list";
    export const SET_STATUS_MESSAGE: string = "set-status-message";
    export const CLEAR_STATUS_MESSAGE: string = "clear-status-message";

    export const SAVE_SETTINGS: string = "save-settings";
}

export enum ProxyStatusMessageEnum {
    Loading = "Loading",
    Success = "Success",
    Error = "Error"
}