import { RefreshStatus } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_service_pb";

export function refreshStatusToReadable(status: RefreshStatus.Status): string {
    switch (status) {
        case RefreshStatus.Status.CANCELLED:
            return "Cancelled";
        case RefreshStatus.Status.FAILED:
            return "Failed";
        case RefreshStatus.Status.FINALIZING:
            return "Finalizing";
        case RefreshStatus.Status.PREPARING:
            return "Preparing";
        case RefreshStatus.Status.QUEUED:
            return "Queued";
        case RefreshStatus.Status.RUNNING:
            return "Running";
        case RefreshStatus.Status.SUCCESS:
            return "Success";
        default:
            return status.toString();
    }
}

export function refreshReasonToReadable(reason: RefreshStatus.Reason): string {
    switch (reason) {
        case RefreshStatus.Reason.DISMISSSTATUSCHANGED:
            return "Dismiss status changed";
        case RefreshStatus.Reason.GENERATESUMMARIES:
            return "Generate summaries";
        case RefreshStatus.Reason.INVALIDSETTINGS:
            return "Invalid settings";
        case RefreshStatus.Reason.JOBNOTFOUND:
            return "Job not found";
        case RefreshStatus.Reason.NEWFULLRESULTSAVAILABLE:
            return "New full results available";
        case RefreshStatus.Reason.REFRESHRESULTS:
            return "Refresh results";
        case RefreshStatus.Reason.SYNCREQUIRED:
            return "Sync required";
        case RefreshStatus.Reason.UNKNOWNANALYSISCONTEXT:
            return "Unknown analysis context";
        default:
            return reason.toString();
    }
}