import { CsseLicenseState } from "../../../../src/models/csseLicenseInfo";

export type AutoModeSpecificError = {
    noSASTEntitlement?: boolean,
    noSigmaInstalled?: boolean,
    noSnippetScanEntitlement?: boolean
    invalidCSSELicense?: CsseLicenseState
    noSignalEntitlement?: boolean
} | undefined;

export type AutoScanConfigProps = {
    licenseAnalysisEnabledState: LicenseAnalysisEnabledState,
    sigmaScanOnType: boolean,
    signalScanConfig: SignalScanConfigState,
    entitlementErrors: AutoModeSpecificError;
};

export interface LicenseAnalysisEnabledState {
    isEnabled: boolean;
    isEnabledOnOpen: boolean | undefined;
    isEnabledOnSave: boolean | undefined;
}

export interface SignalScanConfigState {
    isTimerBasedScansEnabled: boolean;
    isDataFlowScansEnabled: boolean;
    isOversightScansEnabled: boolean;
    isCompareAgainstReferenceBranch: boolean;
    referenceBranchName: string;
    isScanEntireContentChangedFilesEnabled: boolean;
}

export enum AutoScanConfigCommands {
    REFRESH_SIGMA_SCAN_ON_TYPE_STATE = "refreshSigmaScanOnTypeState",
    REFRESH_LICENSE_ANALYSIS_STATE = "refreshLicenseAnalysisEnabledState",
    REFRESH_SIGNAL_SCAN_CONFIG_STATE = "refreshSignalScanConfigState",
    REFRESH_ENTITLEMENTS = "refreshEntitlements",
    APPLY_CHANGES_RESULT = "applyChangesResult",
    APPLY_CHANGES_FAILED = "applyChangesFailed",
}

export enum LicenseAnalysisTrigger {
    Open,
    Save
}