import { GlobPattern, Uri, workspace, WorkspaceFolder, WorkspaceFoldersChangeEvent } from "vscode";
import { getLogger } from '../utils/logger';
import { WarningMessageService } from "./extensionMessageService";
import { getService, ServiceId } from "./serviceContainer";

export abstract class WorkspaceService {
    static readonly id: ServiceId<WorkspaceService> = { id: WorkspaceService.name };

    abstract init(): Promise<void>;

    /**
     * @returns the name of the currently open workspace. `undefined` if no workspace folders have been opened
     */
    abstract getWorkspaceName(): string | undefined;

    /**
     * @returns the list of currently opened workspace folders
     */
    abstract getWorkspaceFolders(): Readonly<WorkspaceFolder[]>;

    /**
     * @returns The root of the workspace. In the case of a multi-root workspace this will be the workspace definition file. If a single root workspace, it will be the root of the single project. `undefined` if no folders are open
     */
    abstract getWorkspaceLocation(): Uri | undefined;

    /**
     * @returns The workspace folder that contains a given uri.
     */
    abstract getWorkspaceFolder(uri: Uri): WorkspaceFolder | undefined;

    /**
     * Searches for files matching the `include` pattern, and not matching the `exclude` pattern, in all workspace folders
     * See the `findFiles` function on https://code.visualstudio.com/api/references/vscode-api#workspace 
     */
    abstract findFileInWorkspace(include: GlobPattern, exclude?: GlobPattern, maxResults?: number): Promise<Uri[]>;
}

export class WorkspaceServiceImpl extends WorkspaceService {

    async init(): Promise<void> {
        getLogger().info("Initializing WorkspaceService...");
        workspace.onDidChangeWorkspaceFolders(async (e: WorkspaceFoldersChangeEvent) => {
            await getService(WarningMessageService.id).workspaceFoldersChanged();
        });
        // On plugin activation, the first workspace folders changed event is missed because we aren't yet registered to the event.
        await getService(WarningMessageService.id).workspaceFoldersChanged();
    }

    getWorkspaceName(): string | undefined {
        return workspace.name;
    }

    getWorkspaceLocation(): Uri | undefined {
        if (workspace.workspaceFile) {
            return workspace.workspaceFile;
        }
        // check if it is a single root workspace
        if (workspace.workspaceFolders) {
            return workspace.workspaceFolders[0].uri;
        }
        // no projects are open in the workspace
        return undefined;
    }

    getWorkspaceFolder(uri: Uri): WorkspaceFolder | undefined {
        return workspace.getWorkspaceFolder(uri);
    }

    getWorkspaceFolders(): Readonly<WorkspaceFolder[]> {
        let workspaceFolders = workspace.workspaceFolders;
        return workspaceFolders ? workspaceFolders : [];
    }

    async findFileInWorkspace(include: GlobPattern, exclude?: GlobPattern, maxResults?: number): Promise<Uri[]> {
        return workspace.findFiles(include, exclude, maxResults);
    }
}