export interface LocalViewTreeProvider extends ReloadableTreeDataProvider<TreeNodeProvider> {
    reloadView(state: LocalViewState): Promise<void>;
    reloadViewSimple(issuesList: NewIssue[], totalIssueCount: number | undefined, pageControls: PageControls, mode: ScanMode, explicitCategoryName: string | undefined, baseState: LocalViewState): Promise<void>;
    refreshTimerNode(): Promise<void>;
    isShowingIssues(): boolean;
    isShowingLicenseIssues(): boolean;
}

export class LocalViewTreeProviderImpl implements LocalViewTreeProvider {
    private _onDidChangeTreeData: EventEmitter<TreeNodeProvider | null> = new EventEmitter<TreeNodeProvider | null>();
    readonly onDidChangeTreeData: Event<TreeNodeProvider | null> = this._onDidChangeTreeData.event;
    protected viewLock = new Semaphore(0, 1);

    private root_nodes: TreeNodeProvider[];
    private issuesShown: boolean;
    private licenseIssuesShown: boolean;
    private renderer: LocalViewStateRenderer;


    constructor() {
        this.issuesShown = false;
        this.licenseIssuesShown = false;
        this.root_nodes = [];
        this.renderer = new LocalViewStateRenderer(this.reloadNode.bind(this));
        this.viewLock.release();
    }

    isShowingIssues(): boolean {
        return this.issuesShown;
    }

    isShowingLicenseIssues(): boolean {
        return this.licenseIssuesShown;
    }
    
    getTreeItem(node: TreeNodeProvider): TreeItem | Thenable<TreeItem> {
        return node.getTreeItem();
    }

    getChildren(node?: TreeNodeProvider): ProviderResult<TreeNodeProvider[]> {
        if (!node) {
            return this.root_nodes;
        }
        return node?.getChildren();
    }

    getParent(element: TreeNodeProvider): ProviderResult<TreeNodeProvider> {
        return element.getParent();
    }
    
    async reloadNode(node: TreeNodeProvider | null) {
        this._onDidChangeTreeData.fire(node);
    }

    async refreshTimerNode(): Promise<void> {
        await this.renderer.refreshTimerNode();
    }


    async reloadViewSimple(issuesList: NewIssue[], totalIssueCount: number | undefined, pageControls: PageControls, mode: ScanMode, explicitCategoryName: string | undefined, baseState: LocalViewState) {
        // Extract the focused issue (should be single item)
        const focusedIssue = issuesList[0];
        if (!focusedIssue) {
            getLogger().error('reloadViewSimple called with empty issues list');
            return this.reloadView(baseState);
        }

        // Build SimpleViewState
        const simpleState: SimpleViewState = {
            type: LocalViewStateType.SimpleView,
            scanMode: mode,
            pageControls,
            focusedIssue,
            categoryName: explicitCategoryName,
            baseState: baseState as Exclude<NormalOperationState, SimpleViewState>,
        };

        await this.reloadView(simpleState);
    }

    async reloadView(state: LocalViewState) {
        try {
            await this.viewLock.wait();

            // Use new renderer
            this.root_nodes = this.renderer.render(state);

            // Update flags (renderer sets these)
            this.issuesShown = this.renderer.issuesShown;
            this.licenseIssuesShown = this.renderer.licenseIssuesShown;

            return this.reloadNode(null);
        } catch(e) {
            getLogger().info('Unexpected error occurred while reloading Local view\nException: ', e);
        } finally {
            this.viewLock.release();
        }
    }

}

export interface AutoScanState {
    scanRunning: boolean;
    categoryIssuesList?: CategoryItems[];
    issuesList: NewIssue[];
    totalIssueCount: number | undefined;
    errors?: AutoScanErrorState
}

export interface AutoScanErrorState {
    status: RefreshStatus.Status,
    date: Date | undefined
}

export class ResultTypeNode implements TreeNodeProvider {
    resultsTitle: string;
    scanRunning: boolean;
    categoryIssuesList?: CategoryItems[];
    issuesList: NewIssue[];
    issueCount: number | undefined;
    scanErrors: AutoScanErrorState | undefined;
    children: TreeNodeProvider[] = [];
    isSignalMode: boolean;

    constructor(title: string, scanState: AutoScanState, isSignalMode: boolean = false) {
        this.resultsTitle = title;
        this.scanRunning = scanState.scanRunning || false;
        this.issuesList = scanState.issuesList ?? [];
        this.categoryIssuesList = scanState.categoryIssuesList ?? [];
        this.scanErrors = scanState.errors;
        this.issueCount = scanState.totalIssueCount ? scanState.totalIssueCount : 0;
        this.isSignalMode = isSignalMode;
    }

    async getTreeItem(): Promise<TreeItem> {
        const issueCountString = (this.scanRunning || (!this.issueCount || this.issueCount === 0)) ? '' : (this.issueCount > 1 ? `(${this.issueCount} issues)` : `(${this.issueCount} issue)`);
        const resultTypeTreeItem = new TreeItem(`${localize("auto.scan.issues.result.type.title", `${this.resultsTitle} ${issueCountString}`)}`,  TreeItemCollapsibleState.Expanded);
        resultTypeTreeItem.id = this.resultsTitle;
        
        // Add Signal highlighting for category names
        if (this.isSignalMode) {
            resultTypeTreeItem.resourceUri = Uri.parse(`${SIGNAL_RESOURCE_URI}:`);
        }

        return resultTypeTreeItem;
    }

    getChildren(): TreeNodeProvider[] {
        this.children = [];
        if (this.scanRunning) {
            this.children.push(new IssueListLoadingNode());
            return this.children;
        } else if (this.scanErrors) {
            let { status, date } = this.scanErrors;
            this.children.push(new ScanStatusNode(status, date)); // add error node
        } else if (this.issueCount === 0) {
            let message: TreeNodeProvider[] = [];
            message.push(new StatusNode(Status.Info, localize('local.view.no.issues.node.text', 'None Detected'), undefined, undefined, this.isSignalMode));
            this.children = message;
        } else if (this.categoryIssuesList && this.categoryIssuesList.length > 0) {
            this.categoryIssuesList.forEach(item => {
                item.issuesList.forEach(issue => {
                    this.children.push(new IssueNode(IssuesListIdentifier.LocalViewIssuesList, issue, undefined, undefined, this.isSignalMode));
                });
            });
        } else {
            this.issuesList.forEach(issue => {
                this.children.push(new IssueNode(IssuesListIdentifier.LocalViewIssuesList, issue, undefined, undefined, this.isSignalMode));
            });
        }
        
        return this.children;
    }

    getParent() {
        return undefined;
    }
}


export class SearchFilterNode implements TreeNodeProvider {
    searchValue: string;
    constructor(value: string) {
        this.searchValue = value;
    }

    async getTreeItem(): Promise<TreeItem> {
        const searchFilterItem = new TreeItem("");
        searchFilterItem.description = localize("local.view.search.field.title", "Search: '{0}'", this.searchValue);
        searchFilterItem.contextValue = getTreeItemContext(ContextValue.copyable, ContextValue.search);
        return searchFilterItem;
    }

    getChildren(): TreeNodeProvider[] {
        return [];
    }

    getParent() {
        return undefined;
    }
}

export class ScanFileScopeNode implements TreeNodeProvider {
    fileScope: RefreshResultsRequest.Tier;

    constructor(fileScope: RefreshResultsRequest.Tier) {
        this.fileScope = fileScope;
    }

    async getTreeItem(): Promise<TreeItem> {
        const fileScopeTreeItem = new LinkTreeItem();
        fileScopeTreeItem.collapsibleState = TreeItemCollapsibleState.None;

        const fileScopeLabel = getScanFileScopeString(this.fileScope);

        fileScopeTreeItem.label = `${localize("issues.view.signal.file.scope.title", "Scope:")} [ ${fileScopeLabel} ]`;
        fileScopeTreeItem.command = {
            command: FILE_SCOPE_SELECT_COMMAND_ID,
            title: "Show file scope select" // not user facing
        };
        return fileScopeTreeItem;
    }

    getChildren() {
        return [];
    }

    getParent() {
        return undefined;
    }
}

