export class ReferenceBranchSelectionNode implements TreeNodeProvider {
    appliedDiffFilter: IssueDiffValue;
    referenceBranch: ReferenceBranch | undefined;

    constructor(filter: IssueDiffValue, referenceBranch: ReferenceBranch | undefined) {
        this.appliedDiffFilter = filter;
        this.referenceBranch = referenceBranch;
    }

    async getTreeItem(): Promise<TreeItem> {
        const issueCompareTreeItem = new LinkTreeItem();
        issueCompareTreeItem.collapsibleState = this.referenceBranch?.name ? TreeItemCollapsibleState.Expanded : TreeItemCollapsibleState.None;
        issueCompareTreeItem.command = {
            command: COMMAND_SET_REFERENCE_BRANCH,
            title: "show reference selection branch" // not user facing
        };
        const fullReferenceBranchName =  this.referenceBranch?.name || NOT_CONFIGURED_TEXT;
        issueCompareTreeItem.label = `${localize("local.view.compare.with.field.title", "Compare with:")} [ ${fullReferenceBranchName} ]`;
        issueCompareTreeItem.tooltip = localize('local.view.compare.with.field.tooltip', 'Compares local results against the selected reference branch');
        return issueCompareTreeItem;
    }

    getChildren(): TreeNodeProvider[] {
        if (this.referenceBranch) {
            return [new DiffSourceFilterNode(this.appliedDiffFilter)];
        }
        return [];
    }

    getParent() {
        return undefined;
    }
}

export class DiffSourceFilterNode implements TreeNodeProvider {
    appliedDiffFilter: IssueDiffValue;
    constructor(filter: IssueDiffValue) {
        this.appliedDiffFilter = filter;
    }
    async getTreeItem(): Promise<TreeItem> {
        const diffFilterItem = new TreeItem("");
        diffFilterItem.description = localize("issues.view.scope.title", "Show: {0}", getDiffSourceDisplayString(this.appliedDiffFilter));
        let scopeContext = getContextValuesForDiffSourceFilterState(this.appliedDiffFilter);
        scopeContext = scopeContext.concat(ContextValue.copyable);
        diffFilterItem.contextValue = getTreeItemContext(...scopeContext);
        return diffFilterItem;
    }

    getChildren(): TreeNodeProvider[] {
        return [];
    }

    getParent() {
        return undefined;
    }
}

export class ScanResultsNode implements TreeNodeProvider {
    private scanInfo:  FileScanInfo | undefined;
    constructor(scanInfo: FileScanInfo | undefined) {
        this.scanInfo = scanInfo;
    }
    async getTreeItem(): Promise<TreeItem> {
        const scanResultItem = new LinkTreeItem();
        scanResultItem.command = {
            command: COMMAND_SHOW_SCAN_RESULTS,
            title: "Show scan result selections", // not user facing
        };

        if (this.scanDate()) {
            scanResultItem.tooltip = this.scanDate();
        }
        scanResultItem.label = `${localize("local.view.scan.results.title", "Viewing results from:")} [ ${this.configName()} ]`;

        return scanResultItem;
    }

    scanDate(): string | undefined {
        let scanDate: string | undefined;
        if (this.scanInfo?.getAnalysistime()) {
            scanDate = getPrettyLocalDateTimeString(this.scanInfo?.getAnalysistime()!.toDate());
        }
        return scanDate;
    }

    configName(): string {
        return this.scanInfo?.getScanconfig()?.getConfigid()?.getName() ?? NO_RESULTS_TEXT;
    }

    getChildren() {
        return [];
    }

    getParent() {
        return undefined;
    }
}

export type ScanStatusConfig =
    | { type: 'configName'; value: string }
    | { type: 'customText'; value: string }
    | undefined;

export class ScanStatusNode implements TreeNodeProvider {
    scanStatus: RefreshStatus.Status;
    scanDate: Date | undefined;
    config: ScanStatusConfig;

    constructor(scanStatus: RefreshStatus.Status, scanDate?: Date, config?: ScanStatusConfig) {
        this.scanStatus = scanStatus;
        this.scanDate = scanDate;
        this.config = config;
    }

    async getTreeItem(): Promise<TreeItem> {
        if (isRunningState(this.scanStatus)) {
            return this.getRunningState();
        } else if (this.scanStatus === RefreshStatus.Status.CANCELLED) {
            return this.getCancelledState();
        } else if (this.scanStatus === RefreshStatus.Status.FAILED) {
            return this.getFailedState();
        }

        return new IssuesFoundTreeItem(""); // should not hit this
    }

    getRunningState(): TreeItem {
        const contextService = getService(VscodeContextService.id);
        let title: string;

        if (this.config?.type === 'configName') {
            title = localize('issue.local.view.scan.result.running.title', 'Running a scan for configuration `{0}`', this.config.value);
        } else if (this.config?.type === 'customText') {
            title = this.config.value;
        } else {
            title = localize('issue.local.view.scan.running.default', 'Scan in progress');
        }

        const scanStateItem = new IssuesFoundTreeItem(title);
        scanStateItem.iconPath = {
            light: contextService.getIconPath('spinner-light.svg', 'general'),
            dark: contextService.getIconPath('spinner-dark.svg', 'general')
        };
        scanStateItem.contextValue = getTreeItemContext(ContextValue.viewLocalViewScanDetails, ContextValue.copyable);
        scanStateItem.getCopyText = () => { return title; };
        scanStateItem.command = {
            command: COMMAND_VIEW_LOCAL_VIEW_SCAN_DETAILS,
            title: "show scan details" //not user facing
        };
        return scanStateItem;
    }

    getCancelledState(): TreeItem {
        const contextService = getService(VscodeContextService.id);
        let title = localize('issue.sca.scan.canceled', 'Last scan manually cancelled');
        const scanStateItem = new IssuesFoundTreeItem(title);
        scanStateItem.iconPath = {
            light: contextService.getIconPath('cancelled-light.svg', 'scan'),
            dark: contextService.getIconPath('cancelled-dark.svg', 'scan')
        };
        scanStateItem.contextValue = getTreeItemContext(ContextValue.copyable);
        scanStateItem.getCopyText = () => { return title; };
        return scanStateItem;
    }

    async getFailedState(): Promise<TreeItem> {
        const contextService = getService(VscodeContextService.id);
        let title = SCAN_FAILED_TEXT;
        const scanStateItem = new IssuesFoundTreeItem(title);
        scanStateItem.description = SCAN_FAILED_DETAILS_TEXT;
        scanStateItem.iconPath = contextService.getIconPath('severity-high.svg', 'severity');
        scanStateItem.contextValue = getTreeItemContext(ContextValue.viewLocalViewScanDetails, ContextValue.copyable);
        scanStateItem.getCopyText = () => { return title; };
        scanStateItem.identifier = "local.view.scan.failure.id"; 
        scanStateItem.tooltip = formatDate(this.scanDate!, "MMM Do YYYY H:mm:ss");
        scanStateItem.command = {
            command: COMMAND_VIEW_LOCAL_VIEW_SCAN_DETAILS, // Open L3 errors
            title: "open error details" //not user facing
        };
        return scanStateItem;
    }

    getChildren() {
        return [];
    }

    getParent() {
        return undefined;
    }
}
