import { Webview } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { ServiceId } from "../../services/serviceContainer";
import { getViewSpinnerCSS, getViewSpinnerHTML } from "../../utils/components/spinnerComponents";
import { DOCUMENTATION_ADDRESS_ROOT } from "../../utils/constants";
import { isOSX } from "../../utils/environmentUtils";
import { BUTTON_STYLING, getWebviewHead } from "../../utils/webviewUtils";
import { WebviewProvider } from "../webviewProvider";
import { IssueSourceTableRow } from "./teamViewIssueSourceViewPresenter";

const localize: LocalizeFunc = loadMessageBundle();

export namespace TeamViewIssueSourceCommandIds {
    export const EDIT_SOURCES = "team.view.issue.source.view.edit.sources";
    export const CONNECT_POLARIS = "team.view.issue.source.view.connect.polaris";
    export const CONNECT_SRM = "team.view.issue.source.view.connect.srm";
    export const CONNECT_COVERITY = "team.view.issue.source.view.connect.coverity";
}

export abstract class TeamViewIssueSourceViewProvider extends WebviewProvider {
    static readonly id: ServiceId<TeamViewIssueSourceViewProvider> = { id: TeamViewIssueSourceViewProvider.name };

    abstract initLoading(): void;
    abstract initHtml(data: IssueSourceTableRow[]): void;
    abstract dispose(): Promise<void>;
}

export class TeamViewIssueSourceViewProviderImpl extends TeamViewIssueSourceViewProvider {
    /**
     * Tabulator uses Ctrl + c as copy key for OSX
     * in other OSX applications the copy key is command + c
     * that is why we are changing the copy binding for OSX
     */
    private getCopyKeyBindings(): string {
        if (isOSX()) {
            return "meta + 67";
        }
        return "ctrl + 67";
    }

    public initLoading(): void {
        let text = localize("issue.sources.view.loading", "Loading Sources...");
        let html = /*html*/`
        <html>
            <head>
                ${this.head}
            </head>       
            <style>
                ${this.style}
                ${getViewSpinnerCSS()}
            </style>
            <body>
                ${getViewSpinnerHTML(text)}
            </body>
        </html>`;

        this.webviewPanel!.webview.html = html;
    }

    public initHtml(data: IssueSourceTableRow[]): void {
        let tabulatorCss = this.getNodeModulePath('tabulator-tables', 'dist', 'css', 'tabulator.min.css');
        let tabulatorJs = this.getNodeModulePath('tabulator-tables', 'dist', 'js', 'tabulator.min.js');
        let copyKey = this.getCopyKeyBindings();

        const connectPolarisText = localize('teamViewIssueSourceView.connectPolaris.text', 'Connect to Polaris');
        const connectSRMText = localize('teamViewIssueSourceView.connectSRM.text', 'Connect to Software Risk Manager (SRM)');
        const connectCoverityText = localize('teamViewIssueSourceView.connectCoverity.text', 'Connect to Coverity Connect / Coverity On Polaris');
        const docsLink = DOCUMENTATION_ADDRESS_ROOT + "preferences/r_code_sight_preferences_sources_config.html";

        let minHeightClass = "no-min-height";
        if (data.length === 0) {
            minHeightClass = "set-min-height";
        }

        let html = /*html*/`<html>
                    <link href="${tabulatorCss}" rel="stylesheet">
                    <script type="text/javascript" src="${tabulatorJs}"></script>
                    <head>
                        ${ this.head }
                    </head>
                    <style>
                        ${ this.style }
                    </style>
                    <body id="view-wrapper">
                        <div class='box' style="margin-bottom: 13px;">
                            <img class='blackduck-icon float-left' width="28" height="28"/>
                            <h2 class='float-left margin-left'>${ localize('custom.working.dir.message.content.title', 'Team View Configuration') }</h2>
                        </div>

                        <div>
                            <h3 style="margin-top: 0px;">${localize('team.view.issue.source.view.header', 'Team View Result Sources')}</h3>
                            <p>${localize('team.view.issue.source.view.desc.one', 'Authenticated servers will show in the list for which you can configure projects to view results from')}. ${localize('team.view.issue.source.view.desc.two', 'For more information, please read')} <a href="${docsLink}">${localize('team.view.issue.source.view.desc.three', 'our documentation')}</a>. </p>
                        </div>

                        <div class="${minHeightClass}" id="configuration-table"></div>

                        <script>
                            const vscode = acquireVsCodeApi();
                            window.onload = () => {
                                document.querySelectorAll(".button-link").forEach(link => {
                                    link.onclick = () => {
                                        vscode.postMessage({
                                            command: link.id,
                                        });
                    
                                        return false;
                                    };
                                });
                            };

                            window.addEventListener('message', event => {
                                const message = event.data;
                                switch (message.command) {
                                    case 'some.command':
                                        break;
                                }
                            });

                            function sourceTooltip(e, cell, onRendered) {
                                return "<div class='tooltip-style'>" + cell.getValue() + "</div>";
                            }

                            function sourceFormatter(cell, formatterParams, onRendered) {
                                let configuredSources = cell.getValue();
                                if (!configuredSources) {
                                    return "<div class='placeholder-style'>${localize('teamViewIssueSourceView.noSourceConfiguration.placeholderText', '(No result source configured)')}</div>";
                                }
                                return "<div>" + configuredSources + "</div>";
                            }

                            function editButtonTooltip(e, cell, onRendered) {
                                return "<div class='tooltip-style'>${localize('teamViewIssueSourceView.editConf.tooltip', 'Edit Source')}</div>";
                            }
            
                            function editButtonFormatter(cell, formatterParams, onRendered) {
                                return "<img style='cursor: pointer;' class='edit-icon' width='16' height='16'>";
                            }

                            function handleEditButtonClick(e, cell) {
                                let data = cell.getData();
                                vscode.postMessage({
                                    command: '${TeamViewIssueSourceCommandIds.EDIT_SOURCES}',
                                    serverType: data.id,
                                });
                            }                

                            var noConnectionElement = "<p id='no-connection-text'>${localize('teamViewIssueSourceView.noServerConnections.text', 'No Server Connections')}</p>";
                            var connectPolarisElement = "<a class='button-link server-link-style' id='${TeamViewIssueSourceCommandIds.CONNECT_POLARIS}' href='#' title='${connectPolarisText}' class='server-link-style'>${connectPolarisText}..</a>";
                            var connectSRMElement = "<a class='button-link server-link-style' id='${TeamViewIssueSourceCommandIds.CONNECT_SRM}' href='#' title='${connectSRMText}' class='server-link-style'>${connectSRMText}..</a>";
                            var connectCoverityElement = "<a class='button-link server-link-style' id='${TeamViewIssueSourceCommandIds.CONNECT_COVERITY}' href='#' title='${connectCoverityText}' class='server-link-style'>${connectCoverityText}..</a>";
                            var placeholderText = noConnectionElement + connectPolarisElement + "<br>" + connectSRMElement + "<br>" + connectCoverityElement

                            var table = new Tabulator("#configuration-table", {
                                placeholder: placeholderText,
                                layout: "fitColumns",
                                movableColumns: false,
                                resizableRows: false,
                                data: ${JSON.stringify(data)},
                                keybindings: {
                                    "copyToClipboard" : "${copyKey}"
                                },
                                clipboard: true,
                                clipboardCopyConfig:{
                                    columnHeaders:false,
                                    columnGroups:false,
                                    rowGroups:false,
                                    columnCalcs:false,
                                    dataTree:true,
                                    formatCells:false
                                },
                                columns: [ //Define Table Columns
                                    {
                                        title: "${localize('teamViewIssueSourceView.server.column', 'Server')}",
                                        field: "serverName",
                                        formatter:"plaintext",
                                        resizable: false
                                    },
                                    {
                                        title: "${localize('teamViewIssueSourceView.source.column', 'Source')}",
                                        field: "sourceReferenceDisplayText",
                                        tooltip: sourceTooltip,
                                        formatter: sourceFormatter,
                                        resizable: false                                    
                                    },
                                    {
                                        title: "${localize('teamViewIssueSourceView.edit.column', 'Edit')}",
                                        field: "editButton",
                                        formatter: editButtonFormatter,
                                        cellClick: handleEditButtonClick,
                                        tooltip: editButtonTooltip,
                                        width: 60,
                                        hozAlign:"center",
                                        resizable: false
                                    }
                                ],
                            });

                            function handleButtonClick(button) {
                                vscode.postMessage({
                                    command: button.id,
                                });
                            }

                            window.onresize = function() {
                                table.redraw();
                            };
                        </script>
                    </body>
                    </html>
        `;

        this.webviewPanel!.webview.html = html;
    }

    protected getHead(webview: Webview): string {
        return getWebviewHead("Team View Result Sources", webview);
    }

    protected getStyle(): string {
        return `
        ${BUTTON_STYLING}

        body {
            display: flex;
            flex-direction: column;
            height: 100vh;
        }
        
        .body-text {
            margin-top: 0px;
            margin-bottom: 7px;
        }

        #no-connection-text {
            margin-top: 0px;
            margin-bottom: 5px;
        }

        .server-link-style {
            font-weight: normal;
            font-size: small;
        }

        .tooltip-style {
            color: var(--vscode-editor-background);
        }

        .vscode-dark .placeholder-style {
            color: var(--vscode-editor-inactiveSelectionBackground);
        }

        .vscode-high-contrast .placeholder-style {
            color: var(--vscode-editor-inactiveSelectionBackground);
        }

        .vscode-light .placeholder-style {
            color: var(--vscode-editor-foreground);
        }

        .no-min-height {
            min-height: 0;
        }

        .set-min-height {
            min-height: 30%;
        }
        
        /* Tabulator settings */
        #configuration-table {
            width: 75%;
            margin-bottom: 15px;
        }

        .tabulator-row-odd {
            background: var(--vscode-editor-background);
            color: var(--vscode-editor-foreground);
        }

        .tabulator-row.tabulator-row-odd:hover {
            background: var(--vscode-editor-background);
            cursor: default;
        }

        .tabulator-row.tabulator-row-even {
            background: var(--vscode-editor-background);
            color: var(--vscode-editor-foreground);
            filter: brightness(95%);
        }

        .vscode-dark .tabulator-row.tabulator-row-even {
            background: var(--vscode-editor-background);
            color: var(--vscode-editor-foreground);
            filter: brightness(125%);
        }

        .tabulator-row.tabulator-row-even:hover {
            background: var(--vscode-editor-background);
            cursor: default;
        }

        a:link {
            color: var(--vscode-textLink-foreground);
        }

        a:visited {
            color: var(--vscode-textLink-activeForeground);
        }

        a:hover {
            color: var(--vscode-textLink-activeForeground);
        }

        .tabulator .tabulator-header .tabulator-col {
            background: var(--vscode-editor-background);
            color: var(--vscode-editor-foreground);
            filter: brightness(85%);
            border-color: var(--vscode-editorGroup-border);
        }

        .vscode-dark .tabulator .tabulator-header .tabulator-col {
            background: var(--vscode-editor-background);
            color: var(--vscode-editor-foreground);
            filter: brightness(125%);
            border-color: var(--vscode-editorGroup-border);
        }

        .vscode-dark .tabulator .tabulator-header:hover .tabulator-col:hover {
            background: var(--vscode-editor-background);
        }

        .tabulator .tabulator-header:hover .tabulator-col:hover {
            background: var(--vscode-editor-background);
        }

        .tabulator .tabulator-header .tabulator-footer {
            background: var(--vscode-editor-background);
            filter: brightness(85%);
        }

        .tabulator .tabulator-header {
            border-color: var(--vscode-editorGroup-border);
            font-weight: normal;
        }

        .vscode-dark .tabulator .tabulator-footer {
            background: var(--vscode-editor-background);
            filter: brightness(125%);
        }

        .tabulator .tabulator-footer .tabulator-page {
            color: var(--vscode-editor-foreground);
        }

        .tabulator {
            background-color: var(--vscode-editor-background);
            border-color: var(--vscode-editorGroup-border);
        }

        .tabulator-row .tabulator-cell {
            border-color: var(--vscode-editorGroup-border);
        }

        .tabulator-row:last-of-type {
            border-bottom: 1px solid;
            border-color: var(--vscode-editorGroup-border);
        }
        `;
    }

    dispose(): Promise<void> {
        return this.webviewPanel?.dispose();
    }
}