import { UserConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/config_pb";
import { StringValue, ValueSource } from "@codesight/codesight-controller-proto/controller_proto/v0/config_types_pb";
import { GetConfigurationRequest, UpdateConfigurationRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/configuration_service_pb";
import { LicensedToolsConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/licensed_tools_config_pb";
import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import { GetInstalledToolsRequest, ModifyToolInstallationsRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/tool_service_pb";
import { Disposable, QuickPickItem, Uri, WebviewPanel } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { AnalysisContextService } from "../../services/analysisContextService";
import { ControllerClientService } from "../../services/controllerClientService";
import { getService } from "../../services/serviceContainer";
import { SetupService, SetupStep } from "../../services/setupService";
import { ToolStateService, ToolTypeEnum } from "../../services/toolStateService";
import { ViewProviderService } from "../../services/viewProviderService";
import { VsCodeInputService } from "../../services/vscodeInputService";
import { fileExists, isFile, normalizeDriveLetter } from "../../utils/fileUtils";
import { getLogger } from "../../utils/logger";
import { WebviewCoordinator } from "../../views/webviewCoordinator";
import { WebviewPresenter } from "../../views/webviewPresenter";
import { SigmaInstallPathViewProvider, SigmaInstallViewCommandIds } from "./sigmaInstallPathViewProvider";

const localize: LocalizeFunc = loadMessageBundle();

export class SigmaInstallPathViewPresenter implements WebviewPresenter {
    private readonly panel: WebviewPanel;
    private view: SigmaInstallPathViewProvider;
    private onMessageFromWebviewDisposable: Disposable | undefined;
    private isInstalledToolsMessage: boolean;
    private isOnboardingFlow: boolean;
    private initiallyConfiguredValue : string|undefined;
    private currentlyConfiguredValue : string|undefined;

    constructor(panel: WebviewPanel, isOnboardingFlow: boolean, isInstalledToolsMessage: boolean) {
        this.panel = panel;
        this.isOnboardingFlow = isOnboardingFlow;
        this.isInstalledToolsMessage = isInstalledToolsMessage;
        this.view = getService(SigmaInstallPathViewProvider.id);
        this.view.initView(this.panel);
        
        const logger = getLogger();
        this.onMessageFromWebviewDisposable = this.view.onMessageFromWebview(async message => {
            switch (message.command) {
                case SigmaInstallViewCommandIds.VIEW_PREV:
                    if (this.isOnboardingFlow) {
                        await getService(SetupService.id).showSetupStep(SetupStep.DownloadError);
                        break;
                    } else if (this.isInstalledToolsMessage) {
                        await getService(WebviewCoordinator.id).showInstalledToolsMessage();
                        break;
                    }
                    return this.view.dispose();
                case SigmaInstallViewCommandIds.VIEW_APPLY:
                    await this.apply();
                    break;
                case SigmaInstallViewCommandIds.VIEW_BROWSE:
                    return this.handleBrowse();
                case SigmaInstallViewCommandIds.VIEW_FILE_CHANGED:
                    return this.handleSigmaPathModified(message.value);
                default:
                    logger.warn(`Received unexpected message ${message.command}`);
                    break;
            }

            return Promise.resolve();
        });
    }

    private setLoadingState() {
        this.view.postMessageToWebview({ 
            command: SigmaInstallViewCommandIds.SET_STATUS,
            type: SigmaInstallViewCommandIds.STATUS_LOADING,
            message: localize('sigma.location.view.loading', 'Validating...')
        });
        this.view.postMessageToWebview({
            command: SigmaInstallViewCommandIds.SET_CONTINUE_ENABLED,
            enabled: "false",
        });
    }

    private async setInitialValue() {
        this.setLoadingState();
        const userConfig = await this.getUserConfiguration();
        let configuredLocation = userConfig?.getSigmaconfig()?.getInstallationlocation()?.getValue();
        configuredLocation = configuredLocation ? configuredLocation : "";

        this.view.postMessageToWebview({ 
            command: SigmaInstallViewCommandIds.SET_CONTINUE_ENABLED,
            enabled: "false"
        });
        
        this.view.postMessageToWebview({ 
            command: SigmaInstallViewCommandIds.SET_INITIAL_VALUE,
            value: configuredLocation
        });

        this.view.postMessageToWebview({ 
            command: SigmaInstallViewCommandIds.SET_FILE,
            value: configuredLocation
        });
        this.initiallyConfiguredValue = configuredLocation;
        
        return this.handleSigmaPathModified(configuredLocation ? configuredLocation : "");
    }

    private async handleSigmaPathModified(value:string) {
        this.setLoadingState();
        
        if(!value){
            // if value is empty, clear status message
            this.view.postMessageToWebview({ 
                command: SigmaInstallViewCommandIds.SET_STATUS,
                type: SigmaInstallViewCommandIds.STATUS_CLEAR,
                message: ""
            });
            return;
        }

        const sigmaVersion = await this.validateSigmaPath(value);

        if(!sigmaVersion){
            return;
        }

        this.currentlyConfiguredValue = value; 
        if(this.currentlyConfiguredValue !== this.initiallyConfiguredValue){
            this.view.postMessageToWebview({ 
                command: SigmaInstallViewCommandIds.SET_STATUS,
                type: SigmaInstallViewCommandIds.STATUS_VALID,
                message: `${localize("sigma.file.valid.prefix", "Rapid Scan Static Version ")} ${sigmaVersion} ${localize("sigma.file.valid.prefix",  "detected")}`,
            });
            this.view.postMessageToWebview({
                command: SigmaInstallViewCommandIds.SET_CONTINUE_ENABLED,
                enabled: "true",
            });
        } else {
            this.view.postMessageToWebview({ 
                command: SigmaInstallViewCommandIds.SET_STATUS,
                type: SigmaInstallViewCommandIds.STATUS_VALID,
                message: localize("current.sigma.location.valid", "Currently configured Rapid Scan Static location. Version ") + sigmaVersion,
            });
        }
    }

    private async validateSigmaPath(value:string) {
        const logger = getLogger();

        if(!await fileExists(value)){
            this.view.postMessageToWebview({ 
                command: SigmaInstallViewCommandIds.SET_STATUS,
                type: SigmaInstallViewCommandIds.STATUS_INVALID,
                message: localize("sigma.file.invalid.not.exist", "Provided path does not exist")
            });
            return null;
        }

        if(!isFile(value)){
            this.view.postMessageToWebview({ 
                command: SigmaInstallViewCommandIds.SET_STATUS,
                type: SigmaInstallViewCommandIds.STATUS_INVALID,
                message: localize("sigma.file.invalid.dir", "Provided path is a directory. Please provide a path directly to the Rapid Scan Static executable")
            });
            return null;
        }

        const invalidSigmaLocationMessage = localize("sigma.failed.to.add", "Could not determine version of Rapid Scan Static. Please ensure the path specified is a Rapid Scan Static binary");
        
        const toolService = await getService(ControllerClientService.id).getToolServiceClient();
        const addToolRequest = new ModifyToolInstallationsRequest();
        addToolRequest.setAction(ModifyToolInstallationsRequest.Action.ADD);
        const licensedToolConfig = new LicensedToolsConfig();
        let path = normalizeDriveLetter(value);
        licensedToolConfig.setInstallpath(path);
        licensedToolConfig.setType(LicensedToolsConfig.Type.SIGMA);
        addToolRequest.setToolconfig(licensedToolConfig);
        const addToolResponse = await toolService.modifyToolInstallations(addToolRequest);
        const addToolError = addToolResponse.getError();
        if(addToolError) {
            logger.error("Error adding known Rapid Scan Static installation: " + addToolError.getMessage());
            this.view.postMessageToWebview({ 
                command: SigmaInstallViewCommandIds.SET_STATUS,
                type: SigmaInstallViewCommandIds.STATUS_INVALID,
                message: invalidSigmaLocationMessage,
            });
            return null;
        }
    
        // retrieve the tool from the known installations so that we can display the version
        const getToolsRequest = new GetInstalledToolsRequest();
        getToolsRequest.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        getToolsRequest.setSkipsuggestedversioncheck(true);
        const installedTools = await toolService.getInstalledTools(getToolsRequest);
        let sigmaVersion = "";
        installedTools.getInstalledtoolsList().forEach(tool=>{
            const foundTool = tool.getFoundtool();
            if(!foundTool){
                return;
            }
            if(foundTool.getType() === LicensedToolsConfig.Type.SIGMA && foundTool.getInstallpath() === value){
                sigmaVersion = foundTool.getVersion();
            }
        });

        if(!sigmaVersion){
            logger.error(`Added Rapid Scan Static install location ${value} not returned by controller as known install`);
            this.view.postMessageToWebview({ 
                command: SigmaInstallViewCommandIds.SET_STATUS,
                type: SigmaInstallViewCommandIds.STATUS_INVALID,
                message: invalidSigmaLocationMessage,
            });
            return null;
        }

        return sigmaVersion;
    }
    

    public async parseNotification(message: NotificationMessage) {
        // no-op
    }

    public async initView() {
        // show previous/continue buttons when we're in setup flow
        this.view.reloadHtml(this.isInstalledToolsMessage || this.isOnboardingFlow);
        return this.setInitialValue();
    }

    public dispose() {
        this.onMessageFromWebviewDisposable?.dispose();
    }

    private async getUserConfiguration() : Promise<UserConfig|undefined> {
        const configServiceClient = await getService(ControllerClientService.id).getConfigurationServiceClient();
        const getConfigRequest = new GetConfigurationRequest();
        const configRequestFilter = new GetConfigurationRequest.Filter();
        configRequestFilter.setExcludeprojects(true);
        getConfigRequest.setFilter(configRequestFilter);
        getConfigRequest.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        let config = await configServiceClient.getConfiguration(getConfigRequest);
        return config.getUserconfig();
    }

    private async apply() {
        const logger = getLogger();

        if(this.currentlyConfiguredValue !== undefined && this.initiallyConfiguredValue !== this.currentlyConfiguredValue) {
            this.view.postMessageToWebview({ 
                command: SigmaInstallViewCommandIds.SET_CONTINUE_ENABLED,
                enabled: "false"
            });

            const sigmaVersion = await this.validateSigmaPath(this.currentlyConfiguredValue);
            if (!sigmaVersion) {
                this.view.postMessageToWebview({ 
                    command: SigmaInstallViewCommandIds.REMOVE_SPINNER,
                });

                return;
            }

            const newValue = new StringValue();
            newValue.setValue(this.currentlyConfiguredValue);
            const source = new ValueSource();
            source.setType(ValueSource.Type.CODE_SIGHT_USER);
            newValue.setSource(source);
            const userConfig = await this.getUserConfiguration();
            userConfig?.getSigmaconfig()?.setInstallationlocation(newValue);

            const configService = await getService(ControllerClientService.id).getConfigurationServiceClient();
            const request = new UpdateConfigurationRequest();
            request.setUserconfig(userConfig);
            await configService.updateConfiguration(request);

            // remove setup error messages from notifications list since tool setup was successful
            await getService(ViewProviderService.id).getOrCreateExtensionStatusPresenter().removeSetupErrorNotification(ToolTypeEnum.Sigma);
            
            await getService(ToolStateService.id).refreshToolsFromController(true);
            logger.info("User configured sigma path updated to " + this.currentlyConfiguredValue);
            this.view.postMessageToWebview({ 
                command: SigmaInstallViewCommandIds.REMOVE_SPINNER,
            });
        }

        if (this.isOnboardingFlow) {
            await getService(SetupService.id).continueFlow();
        } else if (this.isInstalledToolsMessage) {
            await getService(WebviewCoordinator.id).showInstalledToolsMessage();
        } else {
            await this.initView();
        }
    }

    private async handleBrowse() {
        
        // get known installations
        const toolService = await getService(ControllerClientService.id).getToolServiceClient();
        const contextId = getService(AnalysisContextService.id).getAnalysisContextId();
        const installedToolsRequest = new GetInstalledToolsRequest();
        installedToolsRequest.setContextid(contextId);
        installedToolsRequest.setSkipsuggestedversioncheck(true);
        const installedToolsResponse = await toolService.getInstalledTools(installedToolsRequest);
        const installedSigmaTools : LicensedToolsConfig[]= [];
        let activeSigmaTool : LicensedToolsConfig| undefined;
        installedToolsResponse.getInstalledtoolsList().forEach(response=>{
            if(response.getFoundtool()?.getType() !== LicensedToolsConfig.Type.SIGMA){
                return;
            }
            let foundTool = response.getFoundtool();
            if(!foundTool){
                return;
            }
            if(response.getActive()){
                activeSigmaTool = foundTool;
            } else {
                installedSigmaTools.push(foundTool);
            }
        });

        const quickPickItems : SigmaPathQuickPickItem[] = [];
        // create a row item for each
        if(!activeSigmaTool && installedSigmaTools.length === 0){
            // no sigma installations
            const noKnownInstallItem : SigmaPathQuickPickItem = {
                label: `$(add) ${localize("sigma.location.select.none", "No current Rapid Scan Static installation")}`,
                alwaysShow : true,
                detail : localize("sigma.location.select.browse1", "Click to browse for a Rapid Scan Static install"),
                picked: true,
                getPathForItem: async()=>{
                    const uri = await this.showBrowse();
                    return uri ? normalizeDriveLetter(uri.fsPath) : "";
                }
            };
            
            quickPickItems.push(noKnownInstallItem);
        } else {
            const versionString = localize("sigma.location.select.version", "Version");
            if(activeSigmaTool){
                quickPickItems.push({
                    label : `$(check) ${activeSigmaTool.getInstallpath()}`,
                    alwaysShow : true,
                    description : `${versionString} ${activeSigmaTool.getVersion()}`,
                    detail : localize("sigma.location.select.current", "Current Version"),
                    picked: false,
                    getPathForItem: async()=>{
                        return activeSigmaTool ? activeSigmaTool.getInstallpath() : "";
                    }
                });
            }
            installedSigmaTools.forEach(foundTool=>{
                quickPickItems.push({
                    label : `${foundTool.getInstallpath()}`,
                    alwaysShow : true,
                    description : `${versionString} ${foundTool.getVersion()}`,
                    picked: false,
                    getPathForItem: async()=>{
                        return foundTool.getInstallpath();
                    }
                });
            });
            quickPickItems.push({
                label : `$(add) ${localize("sigma.location.select.browse2", "Browse for Rapid Scan Static installation")}`,
                alwaysShow : true,
                picked: false,
                getPathForItem: async()=>{
                    const uri = await this.showBrowse();
                    return uri ? normalizeDriveLetter(uri.fsPath) : "";
                }
            });
        }

        // display to the user
        const selectedItem = await getService(VsCodeInputService.id).showQuickPick(quickPickItems);
        if (!selectedItem){
            return;
        }

        // handle path modified
        const selectedPath = await selectedItem.getPathForItem();
        if(!selectedPath){
            return;
        }
        this.view.postMessageToWebview({ 
            command: SigmaInstallViewCommandIds.SET_FILE,
            value: selectedPath,
        });
        return this.handleSigmaPathModified(selectedPath);    
    }

    private async showBrowse(): Promise<Uri|undefined>{
        let chosenFile = await getService(VsCodeInputService.id).showOpenDialog({canSelectFolders:false, canSelectMany:false});
        if(!chosenFile || chosenFile.length < 1){
            getLogger().debug("No file selected from Rapid Scan Static selection browser");
            return;
        }
        return chosenFile[0];
    }
}

interface SigmaPathQuickPickItem extends QuickPickItem {
    getPathForItem: () => Promise<string>;
}