import { LicenseAnalysisEnabledState, LicenseAnalysisTrigger } from "@webview-model/models/views/autoScanConfigModel";
import { TextDocument } from "vscode";
import { normalizeDriveLetter } from "../utils/fileUtils";
import { EntitlementService } from "./entitlementService";
import { ScanService } from "./scanService";
import { ScanStatusCoordinator } from "./scanStatusCoordinator";
import { getService, ServiceId } from "./serviceContainer";
import { VscodeContextService } from "./vscodeContextService";

export abstract class LicenseAnalysisService {
    static readonly id: ServiceId<LicenseAnalysisService> = { id: LicenseAnalysisService.name };
    protected localViewAutoLicenseScanTrigger: LicenseAnalysisTrigger | undefined;
    protected lastFilePathScanned: string = '';
	public abstract onLicenseAnalysisEvent(document: TextDocument, licenseAnalysisEnabledState: LicenseAnalysisEnabledState, trigger: LicenseAnalysisTrigger, onScanTriggered: () => Promise<void>): Promise<boolean>;
    abstract isLicenseScanEnabled(): LicenseAnalysisEnabledState;
    abstract setLicenseScanTrigger(trigger: LicenseAnalysisTrigger | undefined): void;
    abstract getLicenseScanTrigger(): LicenseAnalysisTrigger | undefined;
    abstract setLicenseScanLastFilePath(filePath: string): void;
    abstract getLicenseScanLastFilePath(): string;
}

export class LicenseAnalysisServiceImpl extends LicenseAnalysisService {
    public async onLicenseAnalysisEvent(document: TextDocument, licenseAnalysisEnabledState: LicenseAnalysisEnabledState, trigger: LicenseAnalysisTrigger, onScanTriggered: () => Promise<void>): Promise<boolean> {
        if (getService(ScanStatusCoordinator.id).isCurrentScanFilesScopeChangedFiles()) {
            return false;
        }

        let licenseScanEntitled = getService(EntitlementService.id).getCachedProductEntitlement().isSnippetScanEntitled();
        if (licenseScanEntitled && licenseAnalysisEnabledState.isEnabled &&
            (licenseAnalysisEnabledState.isEnabledOnOpen && trigger === LicenseAnalysisTrigger.Open) ||
            (licenseAnalysisEnabledState.isEnabledOnSave && trigger === LicenseAnalysisTrigger.Save)) {
            if (document && document.fileName && (document.fileName !== this.getLicenseScanLastFilePath() || trigger === LicenseAnalysisTrigger.Save)) {
                let scanService = getService(ScanService.id);
                let localViewScanId = scanService.getLocalViewLastScanId();
                let fileName = normalizeDriveLetter(document.fileName);
                await scanService.cancelJob(localViewScanId!);
                this.setLicenseScanTrigger(trigger);
                this.setLicenseScanLastFilePath(document.fileName);
                await onScanTriggered();
                await getService(ScanService.id).requestLicenseAnalysisScan(fileName);
                return true;
            }
        }
        return false;
    }

    isLicenseScanEnabled(): LicenseAnalysisEnabledState {
        const vsCodeContextService = getService(VscodeContextService.id);
        const preservedLicenseAnalysisEnabledState = vsCodeContextService.getPreservedLicenseAnalysisEnabled();
        const isEnabled = (preservedLicenseAnalysisEnabledState.isEnabled && (preservedLicenseAnalysisEnabledState.isEnabledOnOpen || preservedLicenseAnalysisEnabledState.isEnabledOnSave)) || false
        const isEnabledOnOpen = preservedLicenseAnalysisEnabledState.isEnabledOnOpen;
        const isEnabledOnSave = preservedLicenseAnalysisEnabledState.isEnabledOnSave;
        return { isEnabled, isEnabledOnOpen, isEnabledOnSave};
    }

    setLicenseScanTrigger(trigger: LicenseAnalysisTrigger | undefined) {
        this.localViewAutoLicenseScanTrigger = trigger;
    }

    getLicenseScanTrigger(): LicenseAnalysisTrigger | undefined {
        return this.localViewAutoLicenseScanTrigger;
    }

    setLicenseScanLastFilePath(filePath: string) {
        this.lastFilePathScanned = filePath;
    }

    getLicenseScanLastFilePath(): string {
        return this.lastFilePathScanned;
    }
}
