import { Webview } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { ServiceId } from "../../services/serviceContainer";
import { DOC_APP_ADDRESS } from "../../utils/constants";
import * as webviewUtils from "../../utils/webviewUtils";
import { getProxyScript } from "../../views/proxy/proxyConfigComponent";
import { WebviewProvider } from "../webviewProvider";

const localize: LocalizeFunc = loadMessageBundle();

export namespace SignalLLMKeyValidationViewCommandIds {
    export const VALIDATE_LLM_KEY = "validate-llm-key";
    
    export const SET_STATUS = "set-status";
    export const CLEAR_STATUS = "clear-status";
    export const ENABLE_BUTTON = "enable-button";
    export const SET_LLM_KEY_PLACEHOLDER = "set-llm-key-placeholder";
}

const validateKeyText = localize('signal.llm.key.validate.button', 'Save');

export abstract class SignalLLMKeyValidationViewProvider extends WebviewProvider {
    static readonly id: ServiceId<SignalLLMKeyValidationViewProvider> = { id: SignalLLMKeyValidationViewProvider.name };
    
    abstract reloadHtml(): void;
}

export class SignalLLMKeyValidationViewProviderImpl extends SignalLLMKeyValidationViewProvider {

    public reloadHtml() {
        let body = this.getBody();
        let script = this.getScript();

        let html = /*html*/`<!DOCTYPE html>
            <html lang="en">
            <head>
            ${this.head}
            </head>
            <style>
            ${this.style}
            </style>
            <body>
                ${body}
                <script>
                    const vscode = acquireVsCodeApi();

                    function handleValidateKey() {
                        vscode.postMessage({
                            command: '${SignalLLMKeyValidationViewCommandIds.VALIDATE_LLM_KEY}',
                            llmKey: document.querySelector('input[name="llmKey"]').value
                        });
                    }
                    
                    function updateButtonState() {
                        let shouldEnable = isFilled('llmKey');
                        enableButton('validateKey', shouldEnable, true);
                    }

                    function isFilled(field) {
                        var input = document.getElementById(field).value;
                        if (input !== "") return true;
                        return false;
                    }

                    function enableButton(buttonId, shouldEnable, primary) {
                        let secondaryText = primary ? "" : "-secondary";
                        if (shouldEnable) {
                            document.getElementById(buttonId).classList.remove("button-disabled" + secondaryText);
                            document.getElementById(buttonId).removeAttribute("disabled");
                        } else {
                            document.getElementById(buttonId).classList.add("button-disabled" + secondaryText);
                            document.getElementById(buttonId).setAttribute("disabled", "");
                        }
                    }

                    function showStatusMessage(header, message, type) {
                        let actionStatusId = '#status';
                        let actionStatusTextId = '#statusText';
                        let actionStatusHeaderId = '#statusHeader';
                        let statusImgId = '#statusImg';
                        let icon;
                        switch (type) {
                            case "success":
                                icon = "success-icon";
                                document.getElementById("troubleshootingLink").classList.add('hidden');
                                break;
                            case "error":
                                icon = "severity-high";
                                document.getElementById("troubleshootingLink").classList.remove('hidden');
                                break;
                            case "spin":
                                icon = "spinner-icon";
                                document.getElementById("troubleshootingLink").classList.add('hidden');
                                break;
                        }

                        document.querySelector(actionStatusId).classList.remove('hidden');
                        if (header) {
                            document.querySelector(actionStatusHeaderId).innerHTML = header;
                            document.querySelector(actionStatusHeaderId).classList.remove('hidden');
                        }
                        document.querySelector(actionStatusTextId).innerHTML = message;
                        let statusImg = document.querySelector(statusImgId);
                        statusImg.className = "";
                        statusImg.classList.add(icon);
                    }

                    function clearStatusMessage() {
                        document.querySelector('#status').classList.add('hidden');
                        document.querySelector('#statusText').innerHTML = "";
                        document.querySelector('#statusHeader').innerHTML = "";
                        document.getElementById("statusHeader").classList.add('hidden');
                        document.querySelector('#statusImg').className = "";
                        document.getElementById("troubleshootingLink").classList.add('hidden');
                    }

                    window.addEventListener('message', event => {
                        const message = event.data;
                        switch (message.command) {
                            case '${SignalLLMKeyValidationViewCommandIds.SET_STATUS}':
                                clearStatusMessage();
                                showStatusMessage(message.header, message.message, message.type);
                                break;
                            case '${SignalLLMKeyValidationViewCommandIds.CLEAR_STATUS}':
                                clearStatusMessage();
                                break;
                            case '${SignalLLMKeyValidationViewCommandIds.ENABLE_BUTTON}':
                                let enabled = message.enable === "true";
                                let primary = message.primary === "true";
                                enableButton(message.buttonId, enabled, primary);
                                break;
                            case '${SignalLLMKeyValidationViewCommandIds.SET_LLM_KEY_PLACEHOLDER}':
                                let placeholder = message.placeholder;
                                document.getElementById("llmKey").setAttribute("placeholder", placeholder);
                        }
                    });

                    ${getProxyScript()}

                    ${script}
                </script>
            </body>
            </html>`;

        // Clear and set HTML to ensure updates
        this.webviewPanel!.webview.html = "";
        this.webviewPanel!.webview.html = html;
    }

    protected getHead(webview: Webview): string {
        return webviewUtils.getWebviewHead("Signal", webview);
    }

    protected getStyle(): string {
        return /*css*/`
        /* Full-width inputs */
        input[type=text], input[type=password] {
            padding: 12px 20px;
            margin: 8px 0;
            box-sizing: border-box;
        }

        ${webviewUtils.BUTTON_STYLING}

        .step-title { 
            display: flex;
            gap: 1rem;
            align-items: center;
        }

        .step-title hr { 
            flex-grow: 1;
            opacity: 0.2;
            border: 1px solid var(--vscode-settings-textInputForeground);
        }

        .validation-grid {
            display: grid;
            grid-gap: 0.7rem;
            align-items: center;
            grid-template-columns: [col] 75px [col] 225px [col] 1px [col] 25px [col] auto;
            grid-template-rows: repeat(3, [row] auto);
            padding-bottom: 2.5rem;
        }

        .button-grid {
            display: grid;
            grid-gap: 0.7rem;
            align-items: start;
            grid-template-columns: [col] 190px [col] auto;
            grid-template-rows: repeat(2, [row] auto);
            padding-bottom: 2.5rem;
        }

        .inner-box {
            display: flex;
            align-items: start;
        }
        
        .inner-box :first-child {
            flex-shrink: 0;
            min-width: 1.5rem;
        }

        #statusHeader {
            margin: 0;
            padding: 0;
        }

        #statusText {
            margin: 0;
            padding: 0;
        }

        .validate-button {
            min-width: 175px;
        }

        #signalLLMKeyValidation-wrapper {
            min-width: 500px;
            max-width: 900px;
        }

        #status {
        }

        .vertical {
            align-self: stretch;
            opacity: 0.2;
            border: 1px solid var(--vscode-settings-textInputForeground);
        }

        `;
    }

    private getBody() {
        return /*html*/`
            <div class="box">
                <img class="blackduck-icon float-left" width="28" height="28">
                <h2 class="float-left margin-left">${localize('signal.llm.key.validation.title', 'Signal')}</h2>
            </div>
            <div id="signalLLMKeyValidation-wrapper">
                <form id="llm-key-form">
                    <div>
                        <div class="validation-grid">
                            <label style="grid-column: col / span 3; grid-row: row 1;" for="llmKey">
                                <b>${localize('signal.llm.key.input.label', 'Black Duck LLM Key')}:</b>
                            </label>
                            <input style="grid-column: col / span 2; grid-row: row 2;" 
                                   id="llmKey" 
                                   type="password" 
                                   name="llmKey" 
                                   placeholder="${localize('signal.llm.key.placeholder', 'Enter your LLM key')}"
                                   required/>

                            <div style="grid-column: col; grid-row: row 3;">
                                <div style="display: flex; align-items: flex-end;">
                                    <label><b>${localize('auth.proxy.title', 'Proxy')}:</b></label>
                                    <img class="margin-left hint-icon" title="${localize('auth.proxy.hint', 'Proxy settings are optional. If your organization uses a proxy, click \'here\' to add or edit Code Sight\'s proxy settings.')}" width="15" height="15"/>
                                </div>
                            </div> 
                            <span style="grid-column: col 2; grid-row: row 3;" id='proxyStatusLabel'></span>
                            <div style="grid-column: col 3; grid-row: row 3;" class="vertical"></div>   
                            <div style="grid-column: col 4 / span 2; grid-row: row 3;">
                                <a href="#" onclick="onConfigureProxyClick();">${localize('auth.configureProxy.title', 'Configure Proxy')}</a>
                            </div>
                        </div>

                        <div class="button-grid">
                            <button id="validateKey" 
                                    style="grid-column: col 1; grid-row: row 1;" 
                                    class="button-small button-disabled validate-button" 
                                    type="button" 
                                    data-text="${validateKeyText}" 
                                    onclick="handleValidateKey();" 
                                    disabled>
                                ${validateKeyText}
                            </button>

                            <div id="status" style="grid-column: col 2; grid-row: row 1 / span 2;" class="hidden inner-box">
                                <img id="statusImg" width=25 height=25>
                                <div class="margin-left">
                                    <h3 id="statusHeader"></h3>
                                    <b id="statusText"></b>
                                    <a id="troubleshootingLink" href="${DOC_APP_ADDRESS}">
                                        ${localize('signal.llm.key.validation.troubleshooting.link', 'Troubleshooting help')}
                                    </a>
                                </div>
                            </div>
                        </div>
                    </div>
                </form>
            </div>`;
    }

    private getScript(): string {
        return /*javascript*/`
            window.onload = function() {
                updateButtonState(); // update button state for auto-filled fields
                document.getElementById("llm-key-form").addEventListener("keyup", function() {
                    updateButtonState();
                    clearStatusMessage();
                });
                
                // Enable validation on Enter key
                document.getElementById("llmKey").addEventListener("keypress", function(event) {
                    if (event.key === "Enter") {
                        event.preventDefault();
                        if (!document.getElementById("validateKey").disabled) {
                            handleValidateKey();
                        }
                    }
                });
            }`;
    }
}