import { CheckLicenseResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/license_service_pb";
import { ServerType } from "@codesight/codesight-controller-proto/controller_proto/v0/server_info_pb";
import { CsseLicenseInfo, CsseLicenseState } from "../models/csseLicenseInfo";
import { Comparable } from "../utils/interfaces";

export class Entitlement {
    private csseEntitlement: boolean;
    private csseLicenseInfo: CsseLicenseInfo;
    private coverityEntitlement: boolean;
    private blackDuckEntitlement: boolean;
    private polarisEntitlement: boolean;
    private srmEntitlement: boolean;
    private scaEntitlement: boolean;
    private sastEntitlement: boolean;
    private signalEntitlement: boolean;
    private snippetScanEntitlement: boolean;
    private coverityToolInstalled: boolean;
    private sigmaToolInstalled: boolean;
    private blackDuckToolInstalled: boolean;
    private coverityAuthentication: Authentication | undefined;
    private blackDuckAuthentication: Authentication | undefined;

    constructor(
        csseEntitlement: boolean,
        csseLicenseInfo: CsseLicenseInfo,
        coverityEntitlement: boolean,
        blackDuckEntitlement: boolean,
        polarisEntitlement: boolean,
        srmEntitlement: boolean,
        scaEntitlement: boolean,
        sastEntitlement: boolean,
        signalEntitlement: boolean,
        snippetScanEntitlement: boolean,
        coverityToolInstalled: boolean,
        sigmaToolInstalled: boolean,
        blackDuckToolInstalled: boolean,
        coverityAuthentication: Authentication | undefined,
        blackDuckAuthentication: Authentication | undefined
    ) {
        this.csseEntitlement = csseEntitlement;
        this.csseLicenseInfo = csseLicenseInfo;
        this.coverityEntitlement = coverityEntitlement;
        this.blackDuckEntitlement = blackDuckEntitlement;
        this.polarisEntitlement = polarisEntitlement;
        this.srmEntitlement = srmEntitlement;
        this.scaEntitlement = scaEntitlement;
        this.sastEntitlement = sastEntitlement;
        this.signalEntitlement = signalEntitlement;
        this.snippetScanEntitlement = snippetScanEntitlement;
        this.coverityToolInstalled = coverityToolInstalled;
        this.sigmaToolInstalled = sigmaToolInstalled;
        this.blackDuckToolInstalled = blackDuckToolInstalled;
        this.coverityAuthentication = coverityAuthentication;
        this.blackDuckAuthentication = blackDuckAuthentication;
    }

    static createDefault(): Entitlement {
        return new Entitlement(
            false,
            new CsseLicenseInfo(false, false, undefined, CheckLicenseResponse.LicenseState.NOLICENSE),
            false, false, false, false, false, false, false, false, false, false, false, undefined, undefined
        );
    }

    isCsseEntitled(): boolean {
        return this.csseEntitlement;
    }

    isCoverityEntitled(): boolean {
        return this.coverityEntitlement;
    }

    isBlackDuckEntitled(): boolean {
        return this.blackDuckEntitlement;
    }

    isPolarisEntitled(): boolean {
        return this.polarisEntitlement;
    }

    isSignalEntitled(): boolean {
        return this.signalEntitlement;
    }

    isSRMEntitled(): boolean {
        return this.srmEntitlement;
    }

    isSCAEntitled(): boolean {
        return this.scaEntitlement;
    }

    isSASTEntitled(): boolean {
        return this.sastEntitlement;
    }

    isSnippetScanEntitled(): boolean {
        return this.snippetScanEntitlement;
    }

    isSigmaReadyToScan(): boolean {
        return this.isSASTEntitled() && this.sigmaToolInstalled;
    }

    isBlackDuckReadyToScan(): boolean {
        return this.isSCAEntitled() && this.blackDuckToolInstalled;
    }

    isCoverityReadyToScan(): boolean {
        return this.isCoverityEntitled() && this.coverityToolInstalled;
    }

    isAnyProductEntitled(): boolean {
        return this.isSCAEntitled() || this.isSASTEntitled() || this.isPolarisEntitled() || this.isSignalEntitled();
    }

    isCsseLicenseValid(): boolean {
        return CsseLicenseState.Valid === this.csseLicenseInfo?.getState();
    }

    getCoverityAuthentication(): Authentication | undefined {
        return this.coverityAuthentication;
    }

    getBlackDuckAuthentication(): Authentication | undefined {
        return this.blackDuckAuthentication;
    }

    getCsseLicense(): CsseLicenseInfo {
        return this.csseLicenseInfo;
    }

    hasCsseLicense(): boolean {
        return !(this.csseLicenseInfo.getState() === CsseLicenseState.NoLicense || this.csseLicenseInfo.getState() === CsseLicenseState.Unknown);
    }
}

export class Authentication implements Comparable<Authentication> {
    private serverType: ServerType;
    private serverURL: string;
    private isSuccessful: boolean;

    constructor(serverType: ServerType, serverURL: string, isSuccessful: boolean) {
        this.serverType = serverType;
        this.serverURL = serverURL;
        this.isSuccessful = isSuccessful;
    }

    getServerType(): ServerType {
        return this.serverType;
    }

    getServerURL(): string {
        return this.serverURL;
    }

    getIsSuccessful(): boolean {
        return this.isSuccessful;
    }

    equals(obj: Authentication): boolean {
        return (obj.getServerType() === this.getServerType() &&
            obj.getServerURL() === this.getServerURL() &&
            obj.getIsSuccessful() === this.getIsSuccessful());
    }
}
