import { Webview } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { ServiceId } from "../../services/serviceContainer";
import { SUPPORT_ADDRESS } from "../../utils/constants";
import { BUTTON_STYLING, getWebviewHead } from "../../utils/webviewUtils";
import { WebviewProvider } from "../webviewProvider";

const localize: LocalizeFunc = loadMessageBundle();

export namespace EmailVerificationViewCommandIds {
    export const VIEW_REFRESH_LICENSE_STATUS = "refresh-license-status";
    export const VIEW_RESEND_VERIFICATION_EMAIL = "resend-verification-email";
    export const VIEW_PREVIOUS_BUTTON = "previous-button";
    export const VIEW_CLOSE_BUTTON = "close-button";

    export const SET_EMAIL_ADDRESS = "set-email-address";
    export const UPDATE_RESEND_BUTTON_STATE = "set-remove-resend-button-loading-state";
    export const ENABLE_BUTTON = "enable-button";
    export const UPDATE_LICENSE_STATUS = "update-license-status";

    export const EMAIL_ADDRESS_CONTENT = "email-address-div-content";
    export const VERIFICATION_STATUS_CONTENT = "verification-status-div-content";
}

export abstract class EmailVerificationMessageViewProvider extends WebviewProvider {
    static readonly id: ServiceId<EmailVerificationMessageViewProvider> = { id: EmailVerificationMessageViewProvider.name };

    abstract initHtml(hasTransition?: boolean): void;
    abstract dispose(): Promise<void>;
}

export class EmailVerificationMessageViewProviderImpl extends EmailVerificationMessageViewProvider {
    constructor() {
        super();
    }

    public initHtml(hasTransition?: boolean): void {
        const messageTitle: string = localize("email.verification.message.title", "Please verify your email");
        const contactSupportLinkText = localize('email.verification.message.contact support', 'contact support');
        const messageDescription1 = localize("email.verification.message.description.one", "You will be able to start a Standard Edition scan once your email is verified. Please");
        const messageDescription2 = localize("email.verification.message.description.two", "if you need to change your signup email.");
        const messageDescription3 = localize("email.verification.message.description.three", "If the verification link doesn't arrive, check your junk folder or resend the verification email.");
        const loadingText = localize('email.verification.view.loading.text', 'Loading');
        
        let html = `<html>
                    <head>
                        ${this.head}
                    </head>
                    <style>
                        ${this.style}
                    </style>
                    <body class='fixedView'>
                        <div class='box'>
                            <img class='blackduck-icon float-left' width="28" height="28"/>
                            <h2 class='float-left margin-left'>${messageTitle}</h2>
                        </div>
                        <p class="descriptions">${messageDescription1} <a href="${SUPPORT_ADDRESS}">${contactSupportLinkText}</a> ${messageDescription2}</p>
                        <p class="descriptions">${messageDescription3}</p>
                        <div class="trial-div">
                            <div id="trial-details-div">
                                <div style="display: flex;">
                                    <img class="severity-low" id="info-icon">
                                    <h3 style="margin-left: 7px;">${localize('email.verification.view.trial.details.header', 'Your Trial Information')}</h3>
                                </div>
                                <div class="display-flex">
                                    <p class="text-bold">${localize('email.verification.view.verification.status.header', 'Verification status:')}</p>
                                    <div id="${EmailVerificationViewCommandIds.VERIFICATION_STATUS_CONTENT}" class="display-flex header-content">
                                        <img class='spinner-icon margin-left status-icon'> 
                                        <p>${loadingText}</p>
                                    </div>
                                </div>
                                <div class="display-flex">
                                    <p class="text-bold">${localize('email.verification.view.email.header', 'Email:')}</p>
                                    <div id="${EmailVerificationViewCommandIds.EMAIL_ADDRESS_CONTENT}" class="display-flex header-content">
                                        <img class='spinner-icon margin-left status-icon'> 
                                        <p>${loadingText}</p>
                                    </div>
                                </div>
                            </div>
                            <div id="refresh-license-div">
                                <button class="button-style" id="${EmailVerificationViewCommandIds.VIEW_REFRESH_LICENSE_STATUS}" onclick="handleButtonClick(this);" type="button"><img class="refresh-icon-white button-disabled" disabled> ${localize('email.verification.view.refresh.license.button.text', 'Refresh Verification Status')}</button>
                            </div>
                        </div>
                        <br>
                        ${this.getButtonElement(hasTransition)}
                        <button class="button-style prev-close-buttons" id="${EmailVerificationViewCommandIds.VIEW_RESEND_VERIFICATION_EMAIL}" onclick="handleButtonClick(this);" type="button"><img class="envelope-icon-white"> ${localize('email.verification.view.resend.verification.button.text', 'Resend Verification Email')}</button>
                        <script>
                            const vscode = acquireVsCodeApi();

                            window.onload = () => {
                                document.querySelectorAll(".button-link").forEach(link => {
                                    link.onclick = () => {
                                        vscode.postMessage({
                                            command: link.id,
                                        });
                    
                                        return false;
                                    };
                                });
                            };

                            window.addEventListener('message', event => {
                                const message = event.data;
                                switch (message.command) {
                                    case "${EmailVerificationViewCommandIds.UPDATE_LICENSE_STATUS}":
                                        updateVerificationStatus(message.status);
                                        break;
                                    case "${EmailVerificationViewCommandIds.SET_EMAIL_ADDRESS}":
                                        document.querySelector("#${EmailVerificationViewCommandIds.EMAIL_ADDRESS_CONTENT}").innerHTML = "<p style='margin-left: 7px;'>" + message.value + "</p>";
                                        break;
                                    case "${EmailVerificationViewCommandIds.UPDATE_RESEND_BUTTON_STATE}":
                                        setResendButtonLoadingState(message.loading);
                                        break;
                                    case "${EmailVerificationViewCommandIds.ENABLE_BUTTON}":
                                        enableButton(message.id, message.enable);
                                        break;
                                }

                                document.querySelectorAll("a").forEach(link => {
                                    link.onclick = () => {
                                        vscode.postMessage({
                                            command: link.id,
                                        });
                    
                                        return false;
                                    };
                                });
                            });

                            function enableButton(id, enable) {
                                const button = document.getElementById(id);
                                if (enable === "true") {
                                    button.classList.remove("button-disabled");
                                    button.removeAttribute("disabled");
                                } else {
                                    button.classList.add("button-disabled");
                                    button.setAttribute("disabled", "");
                                }
                            }

                            function setResendButtonLoadingState(loading) {
                                const button = document.getElementById("${EmailVerificationViewCommandIds.VIEW_RESEND_VERIFICATION_EMAIL}");
                                let content;
                                if (loading === "true") {
                                    content = "<img class='spinner-icon'>";
                                } else {
                                    content = "<img class='envelope-icon-white'>";
                                }

                                content += " Resend Email Verification";

                                button.innerHTML = content;
                            }

                            function updateVerificationStatus(status) {
                                let icon;
                                let text;

                                switch(status) {
                                    case "success":
                                        icon = "<img class='success-icon margin-left status-icon'>";
                                        text = "<p>Verified</p>";
                                        break;
                                    case "failure":
                                        icon = "<img class='severity-medium margin-left status-icon'>";
                                        text = "<p>Not Verified</p>";
                                        break;
                                    case "loading":
                                        icon = "<img class='spinner-icon margin-left status-icon'>";
                                        text = "<p>Loading</p>";
                                        break;
                                }

                                let verificationStatusDiv = document.querySelector("#${EmailVerificationViewCommandIds.VERIFICATION_STATUS_CONTENT}");
                                verificationStatusDiv.innerHTML = icon + text;
                            }

                            function handleButtonClick(button) {
                                vscode.postMessage({
                                    command: button.id,
                                });
                            }

                            function addSpinner(button) {
                                let spinner = "<img class='spinner-icon margin-left' width='20' height='20'>";
                                button.innerHTML += spinner;
                                button.setAttribute("disabled", "");
                            }
                        </script>
                    </body>
                    </html>
        `;

        this.webviewPanel!.webview.html = html;
    }

    protected getButtonElement(hasTransition?: boolean) {
        if (hasTransition) {
            return `<button class="button-style prev-close-buttons" id="${EmailVerificationViewCommandIds.VIEW_PREVIOUS_BUTTON}" onclick="handleButtonClick(this); addSpinner(this);" type="button">${localize('email.verification.view.close.button.text', '< Previous')}</button>`;
        }

        return `<button class="button-style prev-close-buttons" id="${EmailVerificationViewCommandIds.VIEW_CLOSE_BUTTON}" onclick="handleButtonClick(this); addSpinner(this);" type="button">${localize('email.verification.view.previous.button.text', 'Close')}</button>`;
    }

    dispose(): Promise<void> {
        return this.webviewPanel?.dispose();
    }

    protected getHead(webview: Webview): string {
        return getWebviewHead("Please verify your email", webview);
    }

    protected getStyle(): string {
        return `
        ${BUTTON_STYLING}
        
        .fixedView {
            max-width: 900px;
            min-width: 550px;
            margin-bottom: 40px;
        }

        .header-content {
            margin-left: 5px;
            margin-top: 0px;
        }

        .display-flex {
            display: flex;
        }

        .trial-div {
            display: flex;
            justify-content: space-between;
            border: solid;
            border-width: thin;
            border-color: var(--vscode-editor-foreground);
            margin-bottom: 1px;
            margin-right: 30px;
            max-width: 770px;
            min-height: 110px;
            padding: 0px 25px 22px 25px;
        }

        #info-icon {
            width: 20px;
        }

        .refresh-icon-white {
            width: 17px;
        }

        .status-icon {
            width: 17px;
            margin-right: 4px;
            margin-top: 2px;
            margin-left: 3px;
        }

        .descriptions {
            margin-bottom: 20px;
        }

        img {
            vertical-align:middle;
        }

        #${EmailVerificationViewCommandIds.VIEW_REFRESH_LICENSE_STATUS} {
            padding: 10px 10px;
            height: 40px;
            width: 200px;
            font-size: small;
            margin-top: 12px;
        }
        
        .envelope-icon-white {
            width: 17px;
        }

        .prev-close-buttons {
            padding: 10px 10px;
            height: 40px;
            width: 250px;
            margin-bottom: 5px;
            font-size: small;
            margin-top: 12px;
        }

        .button-style {
            background-color: #008CBA;
            border: none;
            color: white;
            text-align: center;
            text-decoration: none;
            display: inline-block;
            font-size: 14px;
            cursor: pointer;
        }

        .spinner-div .button-style{
            padding: 10px 25px;
        }
        `;
    }
}
