    private getInitialStepBody(userName: string, url: string, isEditServerConfig?: boolean): string {
        let initialStepDescription = localize('auth.initial.step.description', 'The extension needs to authenticate your account for activities such as downloading, updating scan engines, accessing central scans, and supporting collaboration.');
        let usernameHint = localize('auth.uname.hint', "This is your email address for your organization or your user name. If your credentials aren't working, please contact your organization's administrator.");
        let urlHint = localize('auth.url.hint', "You may have received an automated welcome email with your company's server URL listed. If not, please contact your administrator for server information.");
        let nextButtonText = isEditServerConfig ? changeCredentialsButtonText : continueButtonText;
        let nextButtonSpinningText = isEditServerConfig ? changeCredentialsButtonSpinningText : continueButtonSpinningText;

        let buttonArea = `<button id="continue" class="button-full button-disabled" type="button" data-text="${nextButtonText}" data-spinning-text="${nextButtonSpinningText}" onclick="handleFormContent('continue-url'); addSpinner(this);" disabled>${nextButtonText}</button>`;
        if (!isEditServerConfig) {
            buttonArea = `<div class="box">
                <button id="view-previous" class="button-half" type="button" onclick="handleFormContent('view-previous');">&lt ${localize('auth.button.previous', 'Previous')}</button>
                <button id="continue" class="button-half button-disabled" type="button" data-text="${nextButtonText}" data-spinning-text="${nextButtonSpinningText}" onclick="handleFormContent('continue-url'); addSpinner(this);" disabled>${nextButtonText}</button>
            </div>`;
        }

        return `
            <div class='box'>
                <img class='blackduck-icon float-left' width="28" height="28"/>
                <h2 class='float-left margin-left'>${this.title}</h2>
            </div>
            <div id="auth-wrapper">
                <div class='box'>
                    <p id='status-left' class='float-left active-status'>${localize('auth.uname.title', 'Email / User Name')}</p>
                    <p id='status-right' class='float-left inactive-status'>...</p>
                </div>
                <div>
                    <p id="description" class="center">${initialStepDescription}</p>
                </div>
                <form id="initial-step-form">
                    <div>
                        <div class='box'>
                            <label for="uname"><b>${localize('auth.uname.title', 'Email / User Name')}:</b></label>
                            <img class="margin-left hint-icon" title="${usernameHint}" width="15" height="15"/>
                        </div>
                        <input id="uname" type="text" value="${userName}" name="uname">

                        <div id="url-box" class='box'>
                            <label for="url"><b>${localize('auth.url.title', 'Server URL')}:</b></label>
                            <img class="margin-left hint-icon" title="${urlHint}" width="15" height="15"/>
                        </div>

                        <input id="url" type="url" value="${url}" name="url">
                        
                        ${getProxyStatusBody()}
                        
                        <div id="status" class="hidden box-centered">
                            <img id="statusImg" width="15" height="15"/>
                            <div class="margin-left">
                                <b id="statusText"></b>
                                <a id="troubleshootingLink" href="${DOC_APP_ADDRESS}">
                                    ${localize('auth.status.troubleshootingLink', 'Troubleshooting help')}
                                </a>
                            </div>
                        </div>
                        
                        ${buttonArea}                        
                    </div>
                </form>
            </div>`;
    }

    private getInitialStepScript(): string {
        return `
            let stepFields = ['uname', 'url'];
            updateContinueButtonState(stepFields); // update button state for auto-filled fields
            document.getElementById("initial-step-form").addEventListener("keyup", function() {
                updateContinueButtonState(stepFields);
                clearStatusMessage()
            });`;
    }

