    private getPasswordOrAuthKeyScript(): string {
        let querySelector = '".browse-cc"';
        let command = '"browseCC"';
        return `
            let browseLinks = document.querySelectorAll(${querySelector});
            window.onload = function() {
                ${querySelector}
                browseLinks.forEach(function(link) {
                    link.onclick = function() {
                        vscode.postMessage({
                            command: ${command}
                        });

                        return false;
                    }
                });
            }
            document.getElementById("password-or-authkey-step-form").addEventListener("change", function() {
                if (document.getElementById("authkeyOption").checked) {
                    updateContinueButtonState(['authkey']);
                }
            });
            document.getElementById("password-or-authkey-step-form").addEventListener("keyup", function() {
                if (document.getElementById("passwdOption").checked) {
                    updateContinueButtonState(['passwd']);
                }
            });
            `;
    }

