import * as licenseServiceGrpc from "@codesight/codesight-controller-proto/controller_proto/v0/license_service_grpc_pb";
import { CheckLicenseRequest, CheckLicenseResponse, GetEntitlementsRequest, GetEntitlementsResponse, GetRegistrationInfoRequest, ImportCSSELicenseRequest, ImportCSSELicenseResponse, RegistrationInfo, ResendTrialEmailRequest, ResendTrialEmailResponse, TrialRequest, TrialResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/license_service_pb";
import { credentials } from "@grpc/grpc-js";
import { getGrpcLimit } from '../utils/environmentUtils';

/**
 * Defines the interface points with the controller's `RegisterService`
 */
export interface LicenseServiceClient {
    registerTrial(request: TrialRequest): Promise<TrialResponse>;
    checkLicense(request: CheckLicenseRequest): Promise<CheckLicenseResponse>;
    getRegistrationInfo(request: GetRegistrationInfoRequest): Promise<RegistrationInfo>;
    importCSSELicense(request: ImportCSSELicenseRequest): Promise<ImportCSSELicenseResponse>;
    resendTrialEmail(request: ResendTrialEmailRequest): Promise<ResendTrialEmailResponse>;
    getEntitlementRequest(getEntitlementRequest: GetEntitlementsRequest): Promise<GetEntitlementsResponse>;
}

export class LicenseServiceClientImpl implements LicenseServiceClient {
    private client: licenseServiceGrpc.LicenseServiceClient;

    constructor(connectionAddress: string) {
        this.client = new licenseServiceGrpc.LicenseServiceClient(connectionAddress, credentials.createInsecure(), { 'grpc.max_receive_message_length': getGrpcLimit(), 'grpc.enable_http_proxy': 0 });
    }

    async checkLicense(request: CheckLicenseRequest): Promise<CheckLicenseResponse> {
        return new Promise<CheckLicenseResponse>((resolve, reject) => {
            this.client.checkLicense(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }

    async importCSSELicense(request: ImportCSSELicenseRequest): Promise<ImportCSSELicenseResponse> {
        return new Promise<ImportCSSELicenseResponse>((resolve, reject) => {
            this.client.importCSSELicense(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }

    async registerTrial(request: TrialRequest): Promise<TrialResponse> {
        return new Promise<TrialResponse>((resolve, reject) => {
            this.client.requestTrial(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }

    async getRegistrationInfo(request: GetRegistrationInfoRequest): Promise<RegistrationInfo> {
        return new Promise<RegistrationInfo>((resolve, reject) => {
            this.client.getRegistrationInfo(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }

    async resendTrialEmail(request: ResendTrialEmailRequest): Promise<ResendTrialEmailResponse> {
        return new Promise<ResendTrialEmailResponse>((resolve, reject) => {
            this.client.resendTrialEmail(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }

    async getEntitlementRequest(request: GetEntitlementsRequest): Promise<GetEntitlementsResponse> {
        return new Promise<GetEntitlementsResponse>((resolve, reject) => {
            this.client.getEntitlements(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }
}