import { AuthenticationMethodRequest, AuthenticationRequest, AuthenticationResponse, GetActiveServerInfoRequest, ServerInfoFilter, TestServerConnectionRequest, TestServerConnectionResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/configuration_service_pb";
import { AuthenticationMethod, ServerInfo, ServerType } from "@codesight/codesight-controller-proto/controller_proto/v0/server_info_pb";
import { AuthModel } from "../models/authModel";
import { TEAM_VIEW_SERVERS } from "../utils/constants";
import { getLogger } from '../utils/logger';
import { AnalysisContextService } from "./analysisContextService";
import { ControllerClientService } from "./controllerClientService";
import { ServiceId, getService } from "./serviceContainer";

/**
 * The authentication service is responsible for handling authentication requests to the controller.
 */
export abstract class AuthenticationService {
    static readonly id: ServiceId<AuthenticationService> = { id: AuthenticationService.name };

    abstract init(): Promise<void>;

    /**
     * Determines the authentication type for the server specified by the passed in auth model. Returns a promise
     * wrapped auth type response which contains the authentication method, server type, and error message if present.
     *
     * @param model the model to query (uses url / username)
     */
    abstract determineAuthType(model: AuthModel): Promise<AuthTypeResponse>;

    /**
     * Authenticates with the server specified in the passed in auth model.
     *
     * @param model the model to authenticate to
     */
    abstract authenticate(model: AuthModel): Promise<string>;

    /**
     * Returns updated server info for given server or undefined if server not found
     */
    abstract fetchServerInfo(serverType: ServerType): Promise<ServerInfo | undefined>;

    /**
     * Returns cached team view server information
     */
    abstract getAvailableTeamViewServerInfos(): ServerInfo[];

    /**
     * Returns cached server information based on server type
     */
    abstract getServerInfo(serverType: ServerType): ServerInfo | undefined;

    /**
     * 
     * @param serverType 
     * 
     * Returns `true` if the provided server type has a valid connection
     */
    abstract hasValidServerConnectionAsync(serverType: ServerType): Promise<boolean>;

    /**
     * Tests server connection status with supplied serverInfo
     * If nothing is supplied, uses the active server info instead
     */
    abstract testServerConnection(serverInfo: ServerInfo): Promise<TestServerConnectionResponse>;

    /**
     * Register a listener, which should be notified of auth changes
     */
    abstract addListener(listener: AuthenticationServiceListener): void;

    /**
     * Unregister a listener, which should no longer be notified of auth changes
     */
    abstract removeListener(listener: AuthenticationServiceListener): void;
}

export interface AuthenticationServiceListener {
    onAuthenticated(serverType: ServerType): Promise<void>;
}

export interface AuthTypeResponse {
    authMethod: AuthenticationMethod;
    serverType: ServerType;
    errorMessage: string;
}

export class AuthenticationServiceImpl extends AuthenticationService {
    protected authenticationServiceListeners: AuthenticationServiceListener[] = [];    
    protected serverMap: Map<ServerType, ServerInfo> = new Map<ServerType, ServerInfo>();

    async init() {
        getLogger().info("Initializing AuthenticationService...");
        await Promise.all([
            this.fetchAndCacheServerInfo([ServerType.POLARIS]),
            this.fetchAndCacheServerInfo([ServerType.SOFTWARERISKMANAGER]),
            this.fetchAndCacheServerInfo([ServerType.BLACKDUCKHUB]),
            this.fetchAndCacheServerInfo([ServerType.COVERITYONPOLARIS, ServerType.COVERITYCONNECT])]);
    }

    async determineAuthType(model: AuthModel): Promise<AuthTypeResponse> {
        let configService = await getService(ControllerClientService.id).getConfigurationServiceClient();
        let request = new AuthenticationMethodRequest();
        let serverInfo = new ServerInfo();
        let authInfo = new ServerInfo.AuthInfo();

        authInfo.setUsername(model.getUserName());
        serverInfo.setUrl(model.getUrl());
        serverInfo.setAuthinfo(authInfo);
        serverInfo.setType(model.getServerType());
        request.setServerinfo(serverInfo);
        request.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());

        let response = await configService.queryAuthenticationMethod(request);
        return {
            authMethod: response.getAuthmethod(),
            serverType: response.getServertype(),
            errorMessage: response.getMessage()
        };
    }

    async authenticate(model: AuthModel): Promise<string> {
        let configService = await getService(ControllerClientService.id).getConfigurationServiceClient();
        let authenticationRequest = new AuthenticationRequest();
        let serverInfo = new ServerInfo();
        let authInfo = new ServerInfo.AuthInfo();

        authInfo.setUsername(model.getUserName());
        let authMethod = model.getAuthMethod();
        authInfo.setMethod(authMethod);
        if (model.getServerType() === ServerType.COVERITYCONNECT && authMethod === AuthenticationMethod.TOKEN) {
            authInfo.setKeyfile(model.getAuthkey());
        } else {
            authInfo.setKey(model.getPassword());
        }

        serverInfo.setType(model.getServerType());
        serverInfo.setUrl(model.getUrl());
        serverInfo.setAuthinfo(authInfo);

        authenticationRequest.setContextid(getService(AnalysisContextService.id).getAnalysisContextId());
        authenticationRequest.setServerinfo(serverInfo);

        let response = await configService.authenticate(authenticationRequest);

        if (response.getStatus() !== AuthenticationResponse.Status.SUCCESS) {
            return response.getStatusmessage();
        }

        await this.fetchAndCacheServerInfo([serverInfo.getType()]);
        await this.onAuthenticated(model.getServerType());

        return "";
    }

    private clearCachedServerInfo(testedServerTypes: ServerType[]) {
        testedServerTypes.forEach((s) => {
            this.serverMap.delete(s);
        });
    }

    private updateCachedServerInfo(serverInfo: ServerInfo | undefined, testedServerTypes?: ServerType[]) {
        if (serverInfo === undefined) {
            this.clearCachedServerInfo(testedServerTypes ?? []);
        } else {
            let serverType = serverInfo.getType();
            this.serverMap.set(serverType, serverInfo);
        }
    }

    async onAuthenticated(serverType: ServerType): Promise<void> {
        let promises: Promise<void>[] = [];
        this.authenticationServiceListeners.forEach((listener) => {
            promises.push(listener.onAuthenticated(serverType));
        });
        await Promise.all(promises);
    }

    private async fetchAndCacheServerInfo(serverTypes: ServerType[]) {
        let client = await getService(ControllerClientService.id).getConfigurationServiceClient();
        let request = new GetActiveServerInfoRequest();
        let analysisContextService = getService(AnalysisContextService.id);
        request.setContextid(analysisContextService.getAnalysisContextId());
        request.setProjectrootpath(analysisContextService.getContextRoot());

        let serverInfoFilter = new ServerInfoFilter();
        serverTypes.forEach(server => {
            serverInfoFilter.addServertypes(server);
        });
        request.setFilter(serverInfoFilter);

        let serverInfoResponse = await client.getActiveServerInfo(request);
        let serverInfo = serverInfoResponse.getServerinfo();

        this.updateCachedServerInfo(serverInfo, serverTypes);
    }

    async fetchServerInfo(serverType: ServerType): Promise<ServerInfo | undefined> {
        await this.fetchAndCacheServerInfo([serverType]);
        return this.serverMap.get(serverType);
    }

    getAvailableTeamViewServerInfos(): ServerInfo[] {
        let availableServers: ServerInfo[] = [];
        TEAM_VIEW_SERVERS.forEach(server => {
            let serverInfo = this.getServerInfo(server);
            if (serverInfo) {
                availableServers.push(serverInfo);
            }
       });
       return availableServers;
    }

    getServerInfo(serverType: ServerType): ServerInfo | undefined {
        return this.serverMap.get(serverType);
    }

    async testServerConnection(serverInfo: ServerInfo): Promise<TestServerConnectionResponse> {
        let client = await getService(ControllerClientService.id).getConfigurationServiceClient();
        let analysisContextService = getService(AnalysisContextService.id);

        let request = new TestServerConnectionRequest();
        request.setServerinfo(serverInfo);
        request.setContextid(analysisContextService.getAnalysisContextId());
        return client.testServerConnection(request);
    }

    private sanitizeServerInfo(serverInfo: ServerInfo) {
        let authInfo = serverInfo.getAuthinfo();
        let sanitizedAuthInfo = new ServerInfo.AuthInfo();
        if (authInfo !== undefined) {
            sanitizedAuthInfo.setUsername(authInfo.getUsername());
            serverInfo.setAuthinfo(sanitizedAuthInfo);
        }
    }

    addListener(listener: AuthenticationServiceListener): void {
        this.authenticationServiceListeners.push(listener);
    }

    removeListener(listener: AuthenticationServiceListener): void {
        let index = this.authenticationServiceListeners.indexOf(listener);
        if (index >= 0) {
            this.authenticationServiceListeners.splice(index, 1);
        }
    }

    async hasValidServerConnectionAsync(serverType: ServerType): Promise<boolean> {
        let info = this.serverMap.get(serverType);
        if(info === undefined) {
            return false;
        }
        let status = await this.testServerConnection(info);
        return status.getStatus() === TestServerConnectionResponse.Status.SUCCESS;
    }
}

