    async constructSortItems(): Promise<SortQuickPickItem[]> {
        const localViewFilterService = getService(LocalViewIssueListFilterService.id);
        const localViewIssueService = getService(LocalViewIssuesListService.id);
        const scanType = await localViewIssueService.getSelectedResultScanType();
        let currentSortState = localViewFilterService.getSortState(scanType?.getType());

        let sortFunction = async (selectedSort: NewIssueSortState) => {
            await this.showTreeViewSpinner();
            if (currentSortState.id === selectedSort.id) {
                // inverse the sort
                currentSortState.isAscending = !currentSortState.isAscending;
            } else {
                // sort descending by the new sort field
                currentSortState.isAscending = selectedSort.isDefaultSortAscending;
                currentSortState.sortName = selectedSort.sortName;
                currentSortState.id = selectedSort.id;
            }
            await localViewFilterService.persistSort(currentSortState, scanType?.getType());
            return this.showSpinnerAndRefreshIssues();
        };

        let sortItems: SortQuickPickItem[] = [
            new SortQuickPickItem(localize("filter.menu.group.sorts", "Sorting"), "", () => {
                return Promise.resolve();
            })
        ];

        let sortOptions = await localViewFilterService.getSortOptions();
        sortOptions.forEach(option => {
            let column = new ColumnInfo();
            column.setId(option.id);
            column.setName(option.sortName);
            sortItems.push(new SortQuickPickItem(`${currentSortState.id === option.id ? (currentSortState.isAscending ? "$(arrow-up)" : "$(arrow-down)") : ""}\t${localize("filter.selector.sort.text", "Sort:")} ${option.sortName}`, `${currentSortState.id === option.id ? localize("filter.invert.sort.description.text", "Click to invert sort order") : ""}`, () => {
                return sortFunction(option);
            }));
        });

        return sortItems;
    }

