    async onSelectionInTree(issueId: string, displayType: DisplayType, navigateToIssueInFile: () => Promise<void>, selectIssue: () => Promise<void>) {
        let localViewIssuesListService = getService(LocalViewIssuesListService.id);
        await this.showIssueDetailsLoading();
        let issue = await localViewIssuesListService.getIssue(issueId, displayType);
        if (issue) {
            await localViewIssuesListService.loadDetailsAndEventsForIssue(issue);
        }
        let selectedScanType = await localViewIssuesListService.getSelectedResultScanType();
        localViewIssuesListService.setPreviousSelectedScanType(selectedScanType);

        let currentDetailsSelection = Date.now();
        this.latestDetailsSelection = currentDetailsSelection;

        if (this.latestDetailsSelection <= currentDetailsSelection) {
            const isEditorMarkersEnabled = getService(MarkerService.id).getIsEditorMarkersEnabled();
            await selectIssue();
            if (!issue?.isAbsentIssue()) {
                await navigateToIssueInFile();
            }

            if (!isEditorMarkersEnabled) {
                await getService(EditorDecorationService.id).addIssueDecorationToEditor([issue!]);
            }

            if (isFeatureFlagEnabled(ENV_CODESIGHT_EDITOR_MARKERS) && isEditorMarkersEnabled && getService(MarkerService.id).getCurrentMarkerView() !== MarkerView.Local) {
                await getService(IssueSelectionService.id).clearSelection(IssuesListIdentifier.TeamViewIssuesList);
                await getService(MarkerService.id).setMarkerView(MarkerView.Local, true);
            }
            await getService(WebviewCoordinator.id).showIssueDetailsForDomain(IssuesListIdentifier.LocalViewIssuesList);
        }
    }

