    public async revealTreeForEvent(localViewEvent: NewEvent) {
        let issue = localViewEvent.getParentIssue();
        let eventType = localViewEvent.getEventType();
        let revealIssue = new IssueNode(IssuesListIdentifier.LocalViewIssuesList, issue, undefined, undefined, false);
        let revealOccurrence = new OccurrenceNode(IssuesListIdentifier.LocalViewIssuesList, localViewEvent.getParentContributingDetail(), revealIssue);

        let revealEvent;
        if (issue.getEventInfo()?.getContributingDetails() && issue.getEventInfo()?.getContributingDetails().length === 1) {
            revealEvent = new EventNode(IssuesListIdentifier.LocalViewIssuesList, localViewEvent, revealIssue);
        } else {
            revealEvent = new EventNode(IssuesListIdentifier.LocalViewIssuesList, localViewEvent, revealOccurrence);
        }

        let isDirectOrTransitive = (eventType === Event.Type.DIRECTDEPENDENCY || eventType === Event.Type.TRANSITIVEDEPENDENCY);
        await this.treeView.reveal(revealEvent, {
            select: !(isDirectOrTransitive), // do not select or focus if direct or transitive dependency (SCA Issues with no main event)
            focus: !(isDirectOrTransitive),
        });
    }

 public async revealTreeForIssue(issue: NewIssue) {
        let revealIssue = new IssueNode(IssuesListIdentifier.LocalViewIssuesList, issue, undefined, undefined, false);
        const visible = this.treeView.visible;
        let timeout = 0;
        // for Incremental scans, if Code Sight tab is not in view and a file is scanned, "IssueNode" is not constructed and an error occurs if we try to reveal the non-existent IssueNode;
        // so, we ensure the view is visible before revealing the issue
        if (!visible) {
            await commands.executeCommand('workbench.view.extension.codesight');
            timeout = 50;
        }

        setTimeout(async () => {
            try {
                await this.treeView.reveal(revealIssue, {
                    select: false,
                    focus: true,
                    expand: true,
                });
            } catch (error) {
                getLogger().error("Error revealing issue:", error);
            }
        }, timeout); // the timeout allows the tree to load before revealing the issue
    }

    public async revealTreeForOccurrence(issue: NewIssue, detail: ContributingDetail): Promise<void> {
        let revealIssue = new IssueNode(IssuesListIdentifier.LocalViewIssuesList, issue, undefined, undefined, false);
        let revealOccurrence = new OccurrenceNode(IssuesListIdentifier.LocalViewIssuesList, detail, revealIssue);

        await this.treeView.reveal(revealOccurrence, {
            select: false,
            focus: true,
            expand: true,
        });
    }

