    async onEntitlementsChanged(entitlementsChanged: EntitlementsChanged): Promise<void> {
        if (entitlementsChanged.didSignalEntitlementChange) {
            let signalEntitled = getService(EntitlementService.id).getCachedProductEntitlement().isSignalEntitled();
            await commands.executeCommand("setContext", CONTEXT_SIGNAL_VIEW, getService(EntitlementService.id).getCachedProductEntitlement().isSignalEntitled());
            if (signalEntitled) {
                await this.enableAIMode();
            } else {
                await this.disableAIMode();
            }
        }
        await this.reloadTreeProvider();
    }

