    async onScanResultReceived(notificationStatus: RefreshStatus): Promise<void> {
        const status = notificationStatus.getStatus();
        const scanSource = notificationStatus.getScansource();
        const scanType = notificationStatus.getScantype();
        const toolType = notificationStatus.getTooltype();
        const tier = notificationStatus.getTier();
        const scanMode = getService(ScanStatusCoordinator.id).getCurrentScanMode();
        const isSignalMode = getService(EntitlementService.id).getCachedProductEntitlement().isSignalEntitled()
            && (getService(VscodeContextService.id).getPreservedAIMode() ?? false);
        const isAutoOrSignalMode = scanMode === ScanMode.Auto || isSignalMode;
        const isChangedFilesScope = isAutoOrSignalMode && getService(ScanStatusCoordinator.id).isCurrentScanFilesScopeChangedFiles();

        // These prevent stale results from flashing during async notification races.
        // They only apply in auto/signal modes where changed-file scans occur.

        if (isAutoOrSignalMode) {
            // In multi-folder workspaces, ignore changed-file notifications for a different folder
            if (isChangedFileScanTier(tier)) {
                const currentGitRepoPath = await getService(ConfigurationService.id).getConfiguredGitRepositoryPath();
                if (currentGitRepoPath !== undefined && notificationStatus.getGitrepositorypath() !== currentGitRepoPath) {
                    await this.reloadTreeProvider();
                    return;
                }
            }

            // Ignore non-changed-file tier notifications (e.g., FAST or UNKNOWNTIER from sigma
            // reporting service) when viewing changed-files scope
            if (isChangedFilesScope && !isChangedFileScanTier(tier)) {
                return;
            }

            // Ignore intermediate statuses (QUEUED, SCANNING) for changed-file scans to prevent
            // races where their reloadTreeProvider() completes after a subsequent SUCCESS
            // notification's showTreeViewSpinner(), briefly flashing stale results
            if (isChangedFilesScope && isChangedFileScanTier(tier) &&
                status !== RefreshStatus.Status.RUNNING &&
                status !== RefreshStatus.Status.SUCCESS &&
                status !== RefreshStatus.Status.FAILED &&
                status !== RefreshStatus.Status.CANCELLED) {
                return;
            }
        }

        // Update Signal timer (including last scan time) before refreshing the tree,
        // so the state builder picks up the updated time when rendering.
        if (toolType === LicensedToolsConfig.Type.SIGNAL) {
            await getService(SignalTimerService.id).onScanCompleted(status);
        }

        const scanService = getService(ScanService.id);
        const isScanModeMatch = scanService.doesScanModeMatch(scanSource);
        let didRefreshResults = false;

        if (ScanResultHandlers.isSignalInAIMode(getService(EntitlementService.id).getCachedProductEntitlement().isSignalEntitled(), getService(VscodeContextService.id).getPreservedAIMode(), toolType)) {
            // Signal AI scan: only refresh results on success, otherwise just reload tree for status update
            if (status === RefreshStatus.Status.SUCCESS) {
                await this.commandExecutor.executeCommand(COMMAND_LOCAL_VIEW_REFRESH_RESULTS, false);
                didRefreshResults = true;
            }
        } else if (ScanResultHandlers.isAutoScanFailureRequiringRefresh(isScanModeMatch, scanSource, status)) {
            // Auto scan failure: refresh to clear loading state
            await this.commandExecutor.executeCommand(COMMAND_LOCAL_VIEW_REFRESH_RESULTS, false);
            didRefreshResults = true;
        } else if (status === RefreshStatus.Status.SUCCESS && isScanModeMatch) {
            // Successful scan with matching mode
            const isManualScan = scanSource === FileScanInfo.Source.MANUAL;
            const selectedResultsType = getService(LocalViewIssuesListService.id).getCachedSelectedResultType();

            if (ScanResultHandlers.hasScanTypeChanged(isManualScan, scanType, selectedResultsType)) {
                // Scan type changed in project mode: notify instead of auto-refreshing
                await getService(InfoMessageService.id).newResultsAvailableMessage(scanType!);
            } else {
                await this.commandExecutor.executeCommand(COMMAND_LOCAL_VIEW_REFRESH_RESULTS, false);
                didRefreshResults = true;
            }
        }

        if (!didRefreshResults) {
            await this.reloadTreeProvider();
            await getService(ScanResultsExportService.id).updateExportAvailability();
        }
    }


