    private debouncedHandleActiveEditorChange = debounce(async (editor: TextEditor | undefined) => {
        try {
            const currentScanMode = getService(ScanStatusCoordinator.id).getCurrentScanMode();
            if (currentScanMode !== ScanMode.Manual) {
                return;
            }

            const reloadResult = shouldReloadForEditorChange(editor, this.lastManualActiveFilePath);
            if (!reloadResult.shouldReload) {
                return;
            }
            if (reloadResult.newFilePath !== undefined) {
                this.lastManualActiveFilePath = reloadResult.newFilePath;
            }

            const filterService = getService(LocalViewIssueListFilterService.id);
            const localViewIssueService = getService(LocalViewIssuesListService.id);
            const scanType = await localViewIssueService.getSelectedResultScanType(currentScanMode);
            const activeFileFilterEnabled = filterService.getActiveFileFilter(scanType?.getType());

            if (activeFileFilterEnabled) {
                await commands.executeCommand(COMMAND_LOCAL_VIEW_REFRESH_RESULTS, !this.isInSimpleViewMode);
            }
        } catch (e) {
            getLogger().error('Failed to load local view issue list for active editor', e);
        }
    }, 300);


    private async toggleActiveFileFilter(): Promise<void> {
        const currentScanMode = getService(ScanStatusCoordinator.id).getCurrentScanMode();
        if (currentScanMode !== ScanMode.Manual) {
            getLogger().warn("toggleActiveFileFilter: Active file filter is only available in project scan mode");
            return;
        }

        const filterService = getService(LocalViewIssueListFilterService.id);
        const localViewIssueService = getService(LocalViewIssuesListService.id);
        const scanType = await localViewIssueService.getSelectedResultScanType(currentScanMode);
        const currentState = filterService.getActiveFileFilter(scanType?.getType());
        await filterService.setActiveFileFilter(!currentState, scanType?.getType());

        await commands.executeCommand(COMMAND_LOCAL_VIEW_REFRESH_RESULTS);
    }

    async onTimerStateChanged(isTimerActive: boolean, nextScanTime: Date | undefined, lastScanTime: Date | undefined): Promise<void> {
        // Timer state changed - reload the tree view to show updated timer information
        await this.reloadTreeProvider();
    }

    async refreshTimerDisplay(): Promise<void> {
        // Refresh only the timer node to update display times
        await this.treeProvider.refreshTimerNode();
    }
