import { Webview } from "vscode";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { ServiceId } from "../../services/serviceContainer";
import { BUTTON_STYLING, getWebviewHead } from "../../utils/webviewUtils";
import { WebviewProvider } from "../webviewProvider";

const localize: LocalizeFunc = loadMessageBundle();

export abstract class RegistrationFormViewProvider extends WebviewProvider {
    static readonly id: ServiceId<RegistrationFormViewProvider> = { id: RegistrationFormViewProvider.name };

    abstract initHtml(countryOptions: string, isInstalledTools: boolean): void;
}
export class RegistrationFormViewProviderImpl extends RegistrationFormViewProvider {
    constructor() {
        super();
    }

    public initHtml(countryOptions: string, isInstalledTools: boolean): void {
        const registrationScreenTitle: string = localize("registration.screen.title", "Choose a Product");
        const standardEditionTitle: string = localize('registration.form.csse.header.text', 'Code Sight Standard Edition Free Trial');
        const csseImgClass: string = "code-sight-standard-edition";
        const regImgClass: string = "blackduck-icon";
        
        let html = /*html*/`<html>
                    <head>
                        ${ this.head }
                    </head>
                    <style>
                        ${ this.style }
                    </style>
                    <body class='fixedView'>
                        <div class='box'>
                            <img class='${ isInstalledTools ? csseImgClass : regImgClass } float-left standard-icon-size'/>
                            <h2 class='float-left margin-left'>${ isInstalledTools ? standardEditionTitle : registrationScreenTitle }</h2>
                        </div>
                        <br>
                        <div style="display:flex;">
                            ${this.getEnterpriseToolSection(isInstalledTools)}
                            <div class="verticalLine"></div>
                            <div>
                                <div>
                                    ${isInstalledTools ? "" :
                                        `<div style="display:flex; align-items:center;">
                                            <img class='code-sight-standard-edition'/>
                                            <h2 style="margin-left: 10px;">${standardEditionTitle}</h2>
                                        </div>`
                                    }
                                    <p id="descriptionText">${localize('registration.form.csse.text', 'Standard Edition provides fast Code Analysis and Open Source Analysis.')}</p>
                                    <p style="margin-top: 0px;">${localize('registration.form.csse.text.three', 'Free to try. No credit card required.')}</p>
                                </div>
                                ${this.showAddLicenseSection(isInstalledTools)}
                                <form class='form' id='formID' onsubmit="return handleFormContent()">
                                    <label for="first_name"><b>${localize('registration.form.first.name', 'First Name')}:*</b></label>
                                    <input class="inputBox" type="text" id="first_name" name="first_name" required>

                                    <label for="last_name"><b>${localize('registration.form.last.name', 'Last Name')}:*</b></label>
                                    <input class="inputBox" type="text" id="last_name" name="last_name" required>

                                    <label for="company_name"><b>${localize('registration.form.company.name', 'Company Name')}:</b></label>
                                    <input class="inputBox" type="text" id="company_name" name="company_name">

                                    <label for="country_name"><b>${localize('registration.form.country', 'Country')}:*</b></label>
                                    <select id="country_name" name="country_name" required>
                                    <option value="" disabled selected>${localize('registration.form.country.placeholder', 'Select your country')}</option>
                                    ${countryOptions}
                                    </select>

                                    <label for="email"><b>${localize('registration.form.email', 'Email')}:*</b></label>
                                    <input class="inputBox" type="email" id="email" name="email" required>
                                    <label class="emailVerificationText">${localize('registration.form.email.footnote', 'A verification link will be sent to this email')}</label>

                                    <!-- todo: add link action -->
                                    <div style="margin-bottom: 3px; display:flex; margin-top: 7px;">
                                        <input style="agreementBox" type="checkbox" id="agreement_checkbox" name="agreement_checkbox" required>
                                        <div style="margin-top: 1px; margin-left: 4px;"><label for="agreement_checkbox">${localize('registration.form.agreement.part.one', 'I have read and accept the')} <a href="https://www.blackduck.com/content/dam/black-duck/en-us/legal/esela/2024/eSELA-v2024.2-(NAM)-Approved.pdf">${localize('registration.form.agreement.part.two', 'license terms')}</a></label></div>
                                    </div>

                                    <label class="agreementText">${localize('registration.form.agreement.footnote.part.one', 'During trial period we collect usage data in order to operate our service')}.</label>
                                    <label class="agreementText">${localize('registration.form.agreement.footnote.part.two', 'Black Duck will not sell your information to third parties')}.</label>
                                    
                                    <div id="status" class="hidden box">
                                        <img id="statusImg" width="15" height="15"/>
                                        <div style="margin-left: 10px;"><b id="statusText"></b></div>
                                    </div>

                                    ${this.getViewButtons(isInstalledTools)}
                                </form>
                            </div>
                        </div>
                        <script>
                            const vscode = acquireVsCodeApi();

                            window.onload = () => {
                                const addLicenseLink = document.querySelector("#${RegistrationViewCommandIds.VIEW_ADD_LICENSE}");
                                
                                addLicenseLink.onclick = () => {
                                    vscode.postMessage({
                                        command: '${RegistrationViewCommandIds.VIEW_ADD_LICENSE}',
                                    });
                                    return false;
                                };
                            };

                            window.addEventListener('message', event => {
                                const message = event.data;
                                switch (message.command) {
                                    case '${RegistrationViewCommandIds.SET_STATUS}':
                                        showStatusMessage(message.message, message.type);
                                        break;
                                    case '${RegistrationViewCommandIds.SET_CONTINUE_ENABLED}':
                                        enableStartTrialButton(message.enabled);
                                        break;
                                }
                            });

                            function handleFormContent() {
                                vscode.postMessage({
                                    command: '${RegistrationViewCommandIds.VIEW_SUBMIT}',
                                    firstName: document.querySelector('input[name="first_name"]').value,
                                    lastName: document.querySelector('input[name="last_name"]').value,
                                    companyName: document.querySelector('input[name="company_name"]').value,
                                    country: document.querySelector('select[name="country_name"]').value,
                                    email: document.querySelector('input[name="email"]').value
                                });

                                return false; // prevent the form from disappearing
                            }

                            function handleButtonClick(button) {
                                vscode.postMessage({
                                    command: button.id,
                                });
                            }

                            function addSpinner(button) {
                                let spinner = "<img class='spinner-icon margin-left' width='20' height='20'>";
                                button.innerHTML += spinner;
                                button.setAttribute("disabled", "");
                                button.classList.add("button-disabled");
                            }

                            function enableStartTrialButton(enable) {
                                const button = document.getElementById("start-trial");
                                if (enable === "true") {
                                    button.classList.remove("button-disabled");
                                    button.removeAttribute("disabled");
                                } else {
                                    button.classList.add("button-disabled");
                                    button.setAttribute("disabled", "");
                                }
                            }

                            function showStatusMessage(message, type) {
                                let icon;
                                switch (type) {
                                    case "${RegistrationViewCommandIds.STATUS_LOADING}":
                                        icon = "spinner-icon";
                                        break;
                                    case "${RegistrationViewCommandIds.STATUS_INVALID}":
                                        icon = "severity-high";
                                        break;
                                    case "${RegistrationViewCommandIds.STATUS_VALID}":
                                        icon = "success-icon";
                                        break;
                                }
        
                                document.querySelector("#status").classList.remove('hidden');
                                document.querySelector("#statusText").innerHTML = message;
                                let statusImg = document.querySelector("#statusImg");
        
                                statusImg.className = "";
                                statusImg.classList.add(icon);

                                const proxySettingsLink = document.querySelector("#${RegistrationViewCommandIds.VIEW_PROXY_SETTINGS}");
                                proxySettingsLink.onclick = () => {
                                    vscode.postMessage({
                                    command: '${RegistrationViewCommandIds.VIEW_PROXY_SETTINGS}',
                                });
                                return false;
                                }
                            }
                        </script>
                    </body>
                    </html>
        `;

        this.webviewPanel!.webview.html = html;
    }

    protected getSignalProductHtml() {
        return `<div class="box">
                    <img class='tool-signal tool-img'/>
                    <h2 style="margin-left: 10px;">${localize('registration.form.existing.signal.user.text', 'Existing Signal user?')}</h2>
                </div>
                <p class="product-desc">${localize('registration.form.existing.signal.user.text', 'Signal users can use their existing LLM Key to get started.')}</p>
                <a class="product-link" id="${RegistrationViewCommandIds.VIEW_ENABLE_SIGNAL}" href="#" onclick="handleButtonClick(this); addSpinner(this);">${localize('registration.form.enable.signal.text', 'Validate LLM Key')}</a>
            </div>
            <div class="spaced-tile">`
    }

    protected getEnterpriseToolSection(isInstalledTools: boolean) {
        if (isInstalledTools) {
            return "";
        }

        return /*html*/`
                <div>
                    <div>
                        ${this.getSignalProductHtml()}
                        <div class="box">
                            <img class='tool-polaris tool-img'/>
                            <h2 style="margin-left: 10px;">${localize('registration.form.existing.polaris.user.text', 'Existing Polaris user?')}</h2>
                        </div>
                        <p class="product-desc">${localize('registration.form.existing.polaris.user.text', 'Polaris users can connect to a Polaris server to get started.')}</p>
                        <a class="product-link" id="${RegistrationViewCommandIds.VIEW_ENABLE_POLARIS}" href="#" onclick="handleButtonClick(this); addSpinner(this);">${localize('registration.form.enable.polaris.text', 'Connect to Polaris')}</a>
                    </div>
                    <div class="spaced-tile">
                        <div class="box">
                            <img class='tool-coverity tool-img'/>
                            <h2 style="margin-left: 10px; width: 250px;">${localize('registration.form.existing.coverity.user.text', 'Existing Coverity Connect / Coverity on Polaris user?')}</h2>
                        </div>
                        <p class="product-desc">${localize('registration.form.existing.coverity.user.text', 'Coverity users can connect to a Coverity Connect or Coverity on Polaris server to get started.')}</p>
                        <a class="product-link" href="#" id="${RegistrationViewCommandIds.VIEW_ENABLE_COVERITY}" type="button" onclick="handleButtonClick(this); addSpinner(this);">${localize('registration.form.enable.coverity.text', 'Connect to Coverity Connect / Coverity on Polaris')}</a>
                    </div>
                    <div class="spaced-tile">
                        <div class="box">
                            <img class='tool-blackduck tool-img'/>
                            <h2 style="margin-left: 10px;">${localize('registration.form.existing.bd.user.text', 'Existing Black Duck SCA user?')}</h2>
                        </div>
                        <p class="product-desc">${localize('registration.form.existing.bd.user.text.one', 'Black Duck SCA users can connect to a Black Duck SCA server to get started.')}</p>
                        <a class="product-link" href="#" id="${RegistrationViewCommandIds.VIEW_ENABLE_BD}" type="button" onclick="handleButtonClick(this); addSpinner(this);">${localize('registration.form.enable.bd.text', 'Connect to Black Duck SCA')}</a>
                    </div>
                    <div class="spaced-tile">
                        <div class="box">
                            <img class='tool-srm tool-img'/>
                            <h2 style="margin-left: 10px; width: 250px;">${localize('registration.form.existing.srm.user.text', 'Existing Software Risk Manager (SRM) user?')}</h2>
                        </div>
                        <p class="product-desc">${localize('registration.form.existing.srm.user.text', 'SRM users can connect to a SRM server to get started.')}</p>
                        <a class="product-link" id="${RegistrationViewCommandIds.VIEW_ENABLE_SRM}" href="#" onclick="handleButtonClick(this); addSpinner(this);">${localize('registration.form.enable.srm.text', 'Connect to SRM')}</a>
                    </div>
                </div>
                `;
    }

    protected showAddLicenseSection(isInstalledTools: boolean) {
        const addLicenseLinkText: string = localize('registration.form.add.license.text.two', 'Add License');
        
        if (isInstalledTools) {
            return "";
        }

        return `<div>
                    <p id="licenseText" class="text-bold">${localize('registration.form.add.license.text.one', 'Already have a license?')} <a id="${RegistrationViewCommandIds.VIEW_ADD_LICENSE}" href="#" title="${addLicenseLinkText}">${addLicenseLinkText}</a></p>
                </div>
                <br>`;
    }

    protected getViewButtons(isInstalledTools: boolean) {
        if (!isInstalledTools) {
            return `<button id="start-trial" type="submit" form="formID">${localize('registration.form.trial.text', 'Start Trial')}</button>`;
        }

        return `<div class="box">
                    <button id="${RegistrationViewCommandIds.VIEW_PREVIOUS}" class="button button-half" onclick="handleButtonClick(this); addSpinner(this);" type="button">< ${localize('registration.form.button.previous', 'Previous')}</button>
                    <button id="start-trial" class="button button-half" type="submit" form="formID">${localize('registration.form.trial.text', 'Start Trial')}</button>
                </div>`;
    }

    protected getHead(webview: Webview): string {
        return getWebviewHead("CSSE Registration", webview);
    }

    protected getStyle(): string {
        const codeSightIconDark = this.getIconPath('installed-tools', 'product_icon_codesight_dark_theme.png');
        const codeSightIconLight = this.getIconPath('installed-tools', 'product_icon_codesight_light_theme.png');

        return /*css*/`
        ${BUTTON_STYLING}

        form {
            display:flex;
            flex-direction: column;
        }

        label {
            margin-bottom: 5px;
        }

        #descriptionText {
            margin-bottom: 10px;
            max-width: 490px;
            line-height: 20px;
        }

        #licenseText {
            max-width: 440px;
            border-style: solid;
            border-color: var(--vscode-editor-foreground);
            border-width: thin;
            padding: 10px;
            margin-bottom: 5px;
            margin-top: 20px;
        }

        #country_name {
            max-width: 465px;
        }

        .headerStyle {
            margin-top: 3px;
        }

        .inputBox, select {
            padding: 5px;
            margin-bottom: 15px;
            max-width: 450px;
        }

        .agreementBox {
            margin-top: 2px;
        }

        .agreementText {
            font-style: italic;
            font-size: xx-small;
            margin-bottom: 3px;
            margin-left: 23px;
        }

        .emailVerificationText {
            font-style: italic;
            font-size: xx-small;
            margin-bottom: 13px;
            margin-top: -12px;
        }

        .verticalLine {
            border-left: 6px solid;
            border-width: thin;
            margin-left: 50px;
            margin-right: 30px;
        }

        button {
            color: var(--vscode-button-secondaryForeground);
            background: var(--vscode-button-secondaryBackground);
            border-width: 1px;
            border-style: solid;
            border-color: var(--vscode-editor-background);
            text-align: center;
            text-decoration: none;
            display: inline-block;
            font-size: medium;
            cursor: pointer;
            width: 150px;
            padding: 10px;
            margin-top: 15px;
            font-weight: bold;
        }

        button:hover {
            background-color: var(--vscode-button-secondaryHoverBackground);
        }

        .product-desc {
            width: 275px;
            margin-top: 3px;
        }

        .product-link {
            font-size: medium;
        }

        .button-disabled {
            opacity: 0.7;
        }

        .fixedView {
            max-width: 1100px;
            min-width: 550px;
        }

        #status {
            margin-top: 30px;
            max-width: 400px;
        }

        .tool-img {
            width: 50px;
            height: 45px;
        }

        .code-sight-standard-edition {
            width: 50px;
            height: 45px;
        }

        .spaced-tile {
            margin-top: 30px;
        }
        `;
    }
}

export namespace RegistrationViewCommandIds{
    export const VIEW_ENABLE_COVERITY = "enable-coverity";
    export const VIEW_ENABLE_SRM = "enable-srm";
    export const VIEW_ENABLE_POLARIS = "enable-polaris";
    export const VIEW_ENABLE_SIGNAL = "enable-signal";
    export const VIEW_ENABLE_BD = "enable-bd";
    export const VIEW_SUBMIT = 'submit-form';
    export const VIEW_ADD_LICENSE = 'add-license';
    export const VIEW_PROXY_SETTINGS = 'proxy-settings';
    export const VIEW_PREVIOUS = 'previous-button';
    
    export const SET_STATUS = "set-status";
    export const SET_CONTINUE_ENABLED = "continue-enabled";

    export const STATUS_LOADING="spin";
    export const STATUS_VALID="valid";
    export const STATUS_INVALID="invalid";
}
