import * as telemetryServiceGrpc from "@codesight/codesight-controller-proto/controller_proto/v0/telemetry_service_grpc_pb";
import { TrackRequest, TrackResponse, UpdateTelemetryConfigRequest, UpdateTelemetryConfigResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/telemetry_service_pb";
import { credentials } from "@grpc/grpc-js";
import * as vscode from "vscode";
import { EXTENSION_ID } from "../utils/constants";
import { getGrpcLimit } from '../utils/environmentUtils';
/**
 * Defines the interface points with the controller's `TelemetryService`
 */
export interface TelemetryServiceClient {
    track(event: TrackRequest.Event): Promise<TrackResponse>;

    updateTelemetryConfig(request: UpdateTelemetryConfigRequest): Promise<UpdateTelemetryConfigResponse>;
}

export class TelemetryServiceClientImpl implements TelemetryServiceClient {
    private client: telemetryServiceGrpc.TelemetryClient;

    constructor(connectionAddress: string) {
        this.client = new telemetryServiceGrpc.TelemetryClient(connectionAddress, credentials.createInsecure(), {'grpc.max_receive_message_length': getGrpcLimit(), 'grpc.enable_http_proxy': 0});
    }

    track(event: TrackRequest.Event): Promise<TrackResponse> {
        let trackRequest = new TrackRequest();
        trackRequest.setEvent(event);
        trackRequest.setDataList(this.getDataPoints());

        return new Promise<TrackResponse>((resolve, reject) => {
            this.client.track(trackRequest, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }

    async updateTelemetryConfig(updateRequest: UpdateTelemetryConfigRequest): Promise<UpdateTelemetryConfigResponse> {
        return new Promise<UpdateTelemetryConfigResponse>((resolve, reject) => {
            this.client.updateTelemetryConfig(updateRequest, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }

    private getDataPoints(): TrackRequest.Data[] {
        let dataList: TrackRequest.Data[] = [];

        dataList.push(this.createData(TrackRequest.Data.Key.IDE, "vscode"));
        dataList.push(this.createData(TrackRequest.Data.Key.IDEVERSION, vscode.version));
        dataList.push(this.createData(TrackRequest.Data.Key.PLUGINVERSION, vscode.extensions.getExtension(EXTENSION_ID)!.packageJSON.version));

        return dataList;
    }

    private createData(key: TrackRequest.Data.Key, value: string): TrackRequest.Data {
        let data = new TrackRequest.Data();

        data.setKey(key);
        data.setValue(value);

        return data;
    }
}