import { ENV_BLACKDUCK_HOME, ENV_SYNOPSYS_HOME } from '../utils/constants';
import { getDefaultBlackDuckHomePath, getEnvVar, getExtensionConfigFilePath, getExtensionLogPath } from "../utils/environmentUtils";
import { createDir, fileExists, isFile, readFileToString, writeToFile } from "../utils/fileUtils";
import { getLogger } from '../utils/logger';
import { ControllerClientService } from './controllerClientService';
import { ServiceId, getService } from "./serviceContainer";

export abstract class ExtensionConfigService {
    static readonly id: ServiceId<ExtensionConfigService> = { id: ExtensionConfigService.name };

    /**
     * Read workspace directory in code_sight_plugin.json and cache it
     * Caches the configured path if it exists, an empty string otherwise
     */
    abstract init(): Promise<void>;

    /**
     * Updates workspace directory path in code_sight_plugin.json
     * Also creates the file if it doesn't exist
     * @returns an error string if something goes wrong, an empty string otherwise
     */
    abstract configureWorkspaceDir(newWorkspaceDir: string): Promise<string>;

    /**
     * @returns the cached working directory path
     */
    abstract getConfiguredWorkspaceDir(): string;

    /**
     * Runs validations on the new directory path provided
     */
    abstract validateProvidedPath(newWorkspaceDir: string): Promise<string>;

    /**
     * Paths affected by working directory configuration
     * Don't move to environmentUtils to avoid circular dependency issues
     */
    abstract getBlackDuckHomePath(): string;
    abstract getExtensionLogPath(): Promise<string>;
}

export const CODE_SIGHT_CONF_FILE_PATH = getExtensionConfigFilePath();

interface CodeSightConfig {
    workingDirectory: string;
}

export class ExtensionConfigServiceImpl implements ExtensionConfigService {
    private customWorkingDirPath = "";

    async init(): Promise<void> {
        try {
            let codeSightConfig: CodeSightConfig = await this.getCodeSightConf();
            this.customWorkingDirPath = codeSightConfig.workingDirectory;
        } catch (error) {
            // logger not initialized yet
        }
    }

    async configureWorkspaceDir(newWorkspaceDir: string): Promise<string> {
        try {
            // make sure we can write to new dir
            let err = await this.validateProvidedPath(newWorkspaceDir);
            if (err) {
                getLogger().warn(` Error ocurred while fetching configured workspace dir, err: ${ err }`);
                return err;
            }

            // create Black Duck directory if it doesn't exist
            let defaultBlackDuckDir = getDefaultBlackDuckHomePath();
            let blackDuckDirExists: boolean = await fileExists(defaultBlackDuckDir);
            if (!blackDuckDirExists) {
                await createDir(defaultBlackDuckDir);
            }

            // create the conf file if it doesn't exist
            let confExists: boolean = await fileExists(CODE_SIGHT_CONF_FILE_PATH);
            if (!confExists) {
                let newConfigFile: CodeSightConfig = {
                    workingDirectory: ""
                };
                await writeToFile(CODE_SIGHT_CONF_FILE_PATH, JSON.stringify(newConfigFile, null, '\t'));
            }

            // update the conf file
            let codeSightConfig: CodeSightConfig = await this.getCodeSightConf();
            codeSightConfig.workingDirectory = newWorkspaceDir;
            await writeToFile(CODE_SIGHT_CONF_FILE_PATH, JSON.stringify(codeSightConfig, null, '\t'));

            // save the new dir path
            this.customWorkingDirPath = newWorkspaceDir;
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        } catch (error: any) {
            getLogger().warn(` Error ocurred while fetching configured workspace dir, err: ${ error }`);
            return error;
        }

        return "";
    }

    async validateProvidedPath(newWorkspaceDir: string): Promise<string> {
        let doesDirExist: boolean = await fileExists(newWorkspaceDir);
        if (!doesDirExist) {
            return "Provided path does not exist";
        } else if (isFile(newWorkspaceDir)) {
            return "Provided path is not a directory";
        }

        try {
            await getService(ControllerClientService.id).testControllerConnection(newWorkspaceDir);
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        } catch (error: any) {
            return error;
        }

        return "";
    }

    private async getCodeSightConf(): Promise<CodeSightConfig> {
        let err: string;
        if (await fileExists(CODE_SIGHT_CONF_FILE_PATH)) {
            let configFileContents = await readFileToString(CODE_SIGHT_CONF_FILE_PATH);
            try {
                return JSON.parse(configFileContents);
            } catch (error) {
                err = `Couldn't parse the extension config file, err: ${ error }`;
            }
        } else {
            err = "code_sight_plugin.json doesn't exist";
        }

        return Promise.reject(err);
    }

    getBlackDuckHomePath(): string {
        let bdHome = getEnvVar(ENV_BLACKDUCK_HOME);
        let synHome = getEnvVar(ENV_SYNOPSYS_HOME);

        // only return default path if there is no configured dir and no env variable
        if (this.customWorkingDirPath) {
            return this.customWorkingDirPath;
        } else if (bdHome) {
            return bdHome;
        } else if (synHome) {
            return synHome;
        }

        return getDefaultBlackDuckHomePath();
    }

    async getExtensionLogPath(): Promise<string> {
        let rootDir = this.getBlackDuckHomePath();
        return getExtensionLogPath(rootDir);
    }

    getConfiguredWorkspaceDir(): string {
        return this.customWorkingDirPath;
    }
}