import { window } from "vscode";
import { DidChangeConfigurationNotification, Executable, LanguageClient, LanguageClientOptions, ServerOptions } from "vscode-languageclient/node";
import { getLogger } from '../utils/logger';
import { ServiceId } from "./serviceContainer";

const outputChannel = window.createOutputChannel("Rapid Scan Static LSP Trace");

// the keys in this interface need to match the keys expected by the LS. See https://blackduck.atlassian.net/wiki/spaces/DESKTOP/pages/23682372/Sigma+Configurations+Custom+Messages
export interface SigmaLsConfig {
    analyze_on_change: boolean;
}

export abstract class SigmaClientService {
    static readonly id: ServiceId<SigmaClientService> = { id: SigmaClientService.name };

    abstract startClient(sigmaPath: string, cmdLineOptions: string[], config: SigmaLsConfig): Promise<void>;

    abstract stopClient(): Promise<void>;

    abstract isRunning(): boolean;

    abstract updateConfiguration(config: SigmaLsConfig): void;
}

export class SigmaClientServiceImpl extends SigmaClientService {

    private client: LanguageClient | undefined;

    async startClient(sigmaPath: string, cmdLineOptions: string[], config: SigmaLsConfig): Promise<void> {
        if (this.isRunning()) {
            return;
        }
        const run: Executable = {
            command: sigmaPath,
            args: cmdLineOptions,
            options: {},
        };
        const serverOptions: ServerOptions = {
            run,
            debug: run,
        };
        const clientOptions: LanguageClientOptions = {
            documentSelector: [{ scheme: "file" }],
            diagnosticCollectionName: "sigma",
            initializationOptions: config,
            outputChannel,
            middleware: {
                executeCommand: async (command, args, next) => {
                    return next(command, args);
                }
            }
        };

        this.client = new LanguageClient(
            "sigma",
            "Black Duck Rapid Scan Static LSP Server",
            serverOptions,
            clientOptions
        );
        this.client.start();
        return this.client.onReady();
    }

    async stopClient(): Promise<void> {
        const logger = getLogger();
        if (this.isRunning() && this.client) {
            try {
                logger.info('Stopping Rapid Scan Static language server');
                await this.client.stop();
            } catch (e) {
                logger.warn('Error while stopping language server');
                logger.warn(e);
            }
        }
    }

    isRunning(): boolean {
        return this.client !== undefined && this.client.needsStop();
    }

    updateConfiguration(config: SigmaLsConfig) {
        if (this.client) {
            this.client.sendNotification(DidChangeConfigurationNotification.type, { settings: config });
        }
    }
}
