import * as userServiceGrpc from "@codesight/codesight-controller-proto/controller_proto/v1/user_service_grpc_pb";
import { GetCurrentUserRequest, GetCurrentUserResponse, UsersRequest, UsersResponse } from "@codesight/codesight-controller-proto/controller_proto/v1/user_service_pb";
import { credentials } from "@grpc/grpc-js";
import { getGrpcLimit } from "../utils/environmentUtils";

/**
 * Defines the interface points with the controller's `UserService`
 */
export interface UserServiceClient {
    getUsers(request: UsersRequest): Promise<UsersResponse>;
    getCurrentUser(request: GetCurrentUserRequest): Promise<GetCurrentUserResponse>;
}

export class UserServiceClientImpl implements UserServiceClient {
    private client_v1: userServiceGrpc.UserServiceClient;

    constructor(connectionAddress: string) {
        this.client_v1 = new userServiceGrpc.UserServiceClient(connectionAddress, credentials.createInsecure(), {'grpc.max_receive_message_length': getGrpcLimit(), 'grpc.enable_http_proxy': 0})
    }

    getUsers(request: UsersRequest): Promise<UsersResponse> {
        return new Promise<UsersResponse>((resolve, reject) => {
            this.client_v1.getUsers(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }

    getCurrentUser(request: GetCurrentUserRequest): Promise<GetCurrentUserResponse> {
        return new Promise<GetCurrentUserResponse>((resolve, reject) => {
            this.client_v1.getCurrentUser(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }
}