/**
 * Builder class for constructing LocalView states in a type-safe manner.
 * This replaces the monolithic buildCurrentFullState() method with
 * focused, type-safe methods for each state type.
 */
export class LocalViewStateBuilder {
    constructor(private pageControls: PageControls) {}

    /**
     * Common services used across multiple state builders.
     * Cached as a getter to avoid repeated service lookups.
     */
    private get services() {
        return {
            scanStatusCoordinator: getService(ScanStatusCoordinator.id),
            entitlements: getService(EntitlementService.id),
            vscodeContext: getService(VscodeContextService.id),
            scanConfig: getService(ScanConfigurationService.id),
            issues: getService(LocalViewIssuesListService.id),
            filter: getService(LocalViewIssueListFilterService.id),
            scan: getService(ScanService.id),
            licenseAnalysis: getService(LicenseAnalysisService.id),
            signalTimer: getService(SignalTimerService.id),
            workspace: getService(WorkspaceService.id),
            configuration: getService(ConfigurationService.id),
            gitInfo: getService(GitInfoService.id),
        };
    }

    /**
     * Main entry point for building the current state.
     * This method coordinates the state building process and
     * ensures the correct state type is returned.
     *
     * @param loading - Optional flag to force loading state
     * @returns The appropriate LocalViewState based on current conditions
     */
    async buildCurrentState(loading?: boolean): Promise<LocalViewState> {
        const scanMode = this.services.scanStatusCoordinator.getCurrentScanMode();
        const entitlements = this.services.entitlements.getCachedProductEntitlement();

        // Check for view-level errors first (highest priority)
        const viewError = this.checkViewLevelError(entitlements, scanMode);
        if (viewError) {
            return viewError;
        }

        const aiEnabled = this.services.vscodeContext.getPreservedAIMode() ?? false;
        const isSignalMode = getService(EntitlementService.id).getCachedProductEntitlement().isSignalEntitled() && aiEnabled;

        // Check for mode-specific errors (only in Incremental mode currently)
        if (scanMode === ScanMode.Auto) {
            const modeError = this.checkAutoModeError(entitlements);
            if (modeError) {
                return modeError;
            }
        }

        // Check if changed-files scope requires a git repository (only relevant for Auto mode or when AI is enabled)
        if ((scanMode === ScanMode.Auto) || aiEnabled) {
            const gitRepoError = await this.checkNotAGitRepository(scanMode, isSignalMode);
            if (gitRepoError) {
                return gitRepoError;
            }
        }

        if (scanMode === ScanMode.Auto) {
            if (this.services.scanStatusCoordinator.isCurrentScanFilesScopeChangedFiles()) {
                return this.buildAutoChangedFilesModeState(loading);
            }
            return this.buildAutoModeState(loading);
        } else if (isSignalMode) {
            return this.buildSignalModeState(loading);
        } else {
            return this.buildManualModeState(loading);
        }
    }

    /**
     * Checks for view-level errors that hide the entire view.
     * These include entitlement issues and license problems.
     */
    private checkViewLevelError(entitlements: Entitlement, scanMode: ScanMode): ViewLevelErrorState | undefined {
        if (!entitlements.isAnyProductEntitled()) {
            if (entitlements.hasCsseLicense() && !entitlements.isCsseLicenseValid()) {
                return {
                    type: LocalViewStateType.ViewLevelError,
                    scanMode,
                    pageControls: this.pageControls,
                    error: {
                        kind: 'invalidCSSELicense',
                        licenseState: entitlements.getCsseLicense().getState()
                    }
                };
            } else {
                return {
                    type: LocalViewStateType.ViewLevelError,
                    scanMode,
                    pageControls: this.pageControls,
                    error: {
                        kind: 'noProductEntitlement'
                    }
                };
            }
        }
        return undefined;
    }

    /**
     * Checks for Incremental mode specific errors.
     * Currently only checks for missing scan tools.
     */
    private checkAutoModeError(entitlements: Entitlement): ModeSpecificErrorState | undefined {
        const isSignalReady = entitlements.isSigmaReadyToScan();
        const isSASTEntitled = entitlements.isSASTEntitled();
        const isBlackDuckEntitled = entitlements.isBlackDuckEntitled();

        if ((!isSASTEntitled || !isSignalReady) && !isBlackDuckEntitled) {
            const isSignalEnabled = getService(EntitlementService.id).getCachedProductEntitlement().isSignalEntitled();
            const scanFileScope = isSignalEnabled ? this.services.scanStatusCoordinator.getCurrentScanFileScope() : undefined;
            return {
                type: LocalViewStateType.ModeSpecificError,
                scanMode: ScanMode.Auto,
                pageControls: this.pageControls,
                scanFileScope,
                error: {
                    kind: 'noInstalledTools'
                }
            };
        }
        return undefined;
    }

    /**
     * Checks if the current scan file scope requires a git repository but the workspace is not one.
     * Applies to both Sigma (non AI Incremental) and Signal (AI incremental) modes when using changed-files scopes.
     */
    private async checkNotAGitRepository(scanMode: ScanMode, isSignalMode: boolean): Promise<ModeSpecificErrorState | undefined> {
        const scanFileScope = this.services.scanStatusCoordinator.getCurrentScanFileScope();
        const isChangedFilesScope = scanFileScope === RefreshResultsRequest.Tier.ALLUNCOMMITTED
            || scanFileScope === RefreshResultsRequest.Tier.REFERENCEBRANCH;

        if (!isChangedFilesScope) {
            return undefined;
        }

        const selectedFolder = await this.getSelectedFolder(scanFileScope);
        const workspaceFolders = this.services.workspace.getWorkspaceFolders();
        const isMultiFolderWorkspace = workspaceFolders.length > 1;

        let folderToCheck: string;
        if (isMultiFolderWorkspace) {
            if (!selectedFolder || selectedFolder.status !== 'configured') {
                return undefined;
            }
            folderToCheck = selectedFolder.path;
        } else if (workspaceFolders.length === 1) {
            // In single-folder workspaces, use the actual workspace folder path
            // (not getContextRoot() which may return the workspace file path)
            folderToCheck = workspaceFolders[0].uri.fsPath;
        } else {
            return undefined;
        }

        const isGitRepo = this.services.gitInfo.isGitRepository(folderToCheck);

        if (isGitRepo === false) {
            return {
                type: LocalViewStateType.ModeSpecificError,
                scanMode: isSignalMode ? ScanMode.Auto : scanMode,
                pageControls: this.pageControls,
                scanFileScope,
                selectedFolder,
                error: {
                    kind: 'notAGitRepository'
                }
            };
        }

        return undefined;
    }

    /**
     * Builds the state for Manual scan mode.
     * Project mode has several distinct states based on scan status.
     */
    private async buildManualModeState(loading?: boolean): Promise<ManualModeState> {
        const { selectedScanType, selectedScanInfo } = await this.services.issues.getAvailableScanInfos();
        const selectedScanConfig = this.services.scanConfig.getSelectedScanConfig();
        const appliedDiffFilter = this.services.filter.getAppliedDiffSourceFilter(selectedScanType?.getType());
        const hasFiltersApplied = this.services.filter.getHasFiltersApplied();
        const searchFilter = this.services.filter.getSearchFilterValue();
        const selectedReferenceBranch = this.services.scanConfig.getSelectedReferenceBranch();
        const lastScanStatus = getScanStatus(selectedScanInfo);

        const baseManualState = {
            scanMode: ScanMode.Manual as const,
            pageControls: this.pageControls,
            selectedScanType,
            selectedScanInfo,
            appliedDiffFilter,
            hasFiltersApplied,
            searchFilter,
            selectedReferenceBranch,
        };

        if (lastScanStatus && isRunningState(lastScanStatus)) {
            const state: ManualModeLoadingState = {
                ...baseManualState,
                type: LocalViewStateType.ManualLoading,
                lastScanStatus: lastScanStatus,
                selectedScanConfig: selectedScanConfig || {
                    name: selectedScanInfo?.getScanconfig()?.getConfigid()?.getName() ?? '',
                    configId: selectedScanInfo?.getScanconfig()?.getConfigid()!,
                    scope: selectedScanInfo?.getScanconfig()?.getScanmode()?.getMode()!,
                    scanType: selectedScanInfo?.getScanconfig()?.getScantype()!,
                    supportsDiffing: selectedScanInfo?.getScanconfig()?.getScantype()?.getSupportsdiffing() ?? false,
                    scanConfigRef: selectedScanInfo?.getScanconfig()!
                },
                lastScanConfigName: selectedScanInfo?.getScanconfig()?.getConfigid()?.getName() ?? '',
                loadingReason: 'scanning',
            };
            return state;
        }

        // Check for loading flag (used when refreshing results)
        if (loading && lastScanStatus === RefreshStatus.Status.SUCCESS && selectedScanConfig) {
            const state: ManualModeLoadingState = {
                ...baseManualState,
                type: LocalViewStateType.ManualLoading,
                lastScanStatus: RefreshStatus.Status.SUCCESS,
                selectedScanConfig,
                lastScanConfigName: selectedScanConfig.name,
                loadingReason: 'refreshing',
            };
            return state;
        }

        // If no usable scan types for project mode, but Signal is entitled, prompt user to switch to Incremental.
        const scanTypeResp = getService(ScanConfigurationService.id).getScanTypes();
        const scanTypes = scanTypeResp?.getScantypesList();
        if ((!scanTypes || scanTypes.length === 0) && getService(EntitlementService.id).getCachedProductEntitlement().isSignalEntitled()) {
            const state: ManualModeNoScanTypesState = {
                ...baseManualState,
                type: LocalViewStateType.ManualNoScanTypes,
                lastScanStatus: undefined,
            };
            return state;
        }

        // If no scan type is selected (not viewing results) or no last scan status, show "No Scan" state
        if (!selectedScanType || !lastScanStatus) {
            const state: ManualModeNoScanState = {
                ...baseManualState,
                type: LocalViewStateType.ManualNoScan,
                lastScanStatus: undefined,
            };
            return state;
        }

        if (lastScanStatus === RefreshStatus.Status.CANCELLED) {
            const state: ManualModeScanCancelledState = {
                ...baseManualState,
                type: LocalViewStateType.ManualScanCancelled,
                lastScanStatus: RefreshStatus.Status.CANCELLED,
            };
            return state;
        }

        if (lastScanStatus === RefreshStatus.Status.FAILED) {
            const state: ManualModeScanFailedState = {
                ...baseManualState,
                type: LocalViewStateType.ManualScanFailed,
                lastScanStatus: RefreshStatus.Status.FAILED,
                lastScanDate: selectedScanInfo?.getAnalysistime()?.toDate() ?? new Date(),
                lastScanConfigName: selectedScanInfo?.getScanconfig()?.getConfigid()?.getName() ?? '',
            };
            return state;
        }

        const pagingError = this.pageControls.pagingError();
        if (pagingError) {
            const state: ManualModePagingErrorState = {
                ...baseManualState,
                type: LocalViewStateType.ManualPagingError,
                lastScanStatus: RefreshStatus.Status.SUCCESS,
                pagingError,
            };
            return state;
        }

        const issuesList = await this.services.issues.getIssues();
        const totalIssueCount = this.services.issues.getTotalIssueCount();

        if (!totalIssueCount || totalIssueCount === 0 || issuesList.length === 0) {
            const state: ManualModeNoResultsState = {
                ...baseManualState,
                type: LocalViewStateType.ManualNoResults,
                lastScanStatus: RefreshStatus.Status.SUCCESS,
            };
            return state;
        }

        const state: ManualModeResultsState = {
            ...baseManualState,
            type: LocalViewStateType.ManualResults,
            lastScanStatus: RefreshStatus.Status.SUCCESS,
            issuesList,
            totalIssueCount, // Now guaranteed to be a number
        };
        return state;
    }

    /**
     * Returns the selected workspace folder for multi-folder workspaces with changed-files scope.
     * Returns undefined if not applicable (single-folder or non-changed-files scope).
     */
    private async getSelectedFolder(scanFileScope: RefreshResultsRequest.Tier | undefined): Promise<WorkspaceFolderSelection | undefined> {
        const isChangedFilesScope = scanFileScope === RefreshResultsRequest.Tier.ALLUNCOMMITTED || scanFileScope === RefreshResultsRequest.Tier.REFERENCEBRANCH;
        if (!isChangedFilesScope) {
            return undefined;
        }

        const workspaceFolders = this.services.workspace.getWorkspaceFolders();
        if (workspaceFolders.length <= 1) {
            return undefined;
        }

        const folderPaths = workspaceFolders.map(folder => folder.uri.fsPath);
        const configuredPath = await this.services.configuration.getConfiguredGitRepositoryPath();
        const effectivePath = configuredPath || folderPaths[0];
        const folderIndex = folderPaths.indexOf(effectivePath);
        const name = folderIndex >= 0 ? workspaceFolders[folderIndex].name : effectivePath;
        return { status: 'configured', name, path: effectivePath };
    }

    /**
     * Builds the state for Incremental scan mode.
     * Incremental mode continuously scans open files and shows real-time results.
     */
    private async buildAutoModeState(loading?: boolean): Promise<AutoModeState> {
        const entitlements = this.services.entitlements.getCachedProductEntitlement();

        const autoRapidScanEntitled = entitlements.isSigmaReadyToScan();
        const autoLicenseScanEntitled = entitlements.isSnippetScanEntitled();
        const autoLicenseScanEnabled = this.services.licenseAnalysis.isLicenseScanEnabled();

        const searchFilter = this.services.filter.getSearchFilterValue();
        const isSignalEnabled = getService(EntitlementService.id).getCachedProductEntitlement().isSignalEntitled();
        const scanFileScope = isSignalEnabled ? this.services.scanStatusCoordinator.getCurrentScanFileScope() : undefined;
        const selectedFolder = await this.getSelectedFolder(scanFileScope);

        const baseAutoState = {
            scanMode: ScanMode.Auto as const,
            pageControls: this.pageControls,
            scanFileScope,
            searchFilter,
            selectedFolder,
        };

        if (loading) {
            const state: AutoModeScanningState = {
                ...baseAutoState,
                type: LocalViewStateType.AutoScanning,
                rapidScan: autoRapidScanEntitled ? {
                    scanning: true
                } : undefined,
                licenseScan: (autoLicenseScanEntitled && autoLicenseScanEnabled?.isEnabled) ? {
                    scanning: true
                } : undefined,
            };
            return state;
        }

        if (window.visibleTextEditors.length === 0 && !window.activeTextEditor) {
            const state: AutoModeNoEditorsState = {
                ...baseAutoState,
                type: LocalViewStateType.AutoNoEditors,
            };
            return state;
        }

        const autoRapidScanRunning = this.services.scan.isLocalViewAutoRapidScanRunning();
        const autoLicenseScanRunning = this.services.scan.isLocalViewAutoLicenseScanRunning();

        // Always fetch results to support showing results as they arrive
        const issuesList = await this.services.issues.getIssues();
        const totalIssueCount = this.services.issues.getTotalIssueCount();
        const categoryItems = this.services.issues.getCategoryItemsList();

        const licenseIssuesList = await this.services.issues.getLicenseAnalysisIssues();
        const totalLicenseIssueCount = this.services.issues.getTotalLicenseIssueCount();

        const { selectedScanInfo } = await this.services.issues.getAvailableScanInfos();
        const lastScanStatus = this.services.scan.getLocalViewLastScanStatus();

        const hasRapidResults = totalIssueCount && totalIssueCount > 0;
        const hasLicenseResults = totalLicenseIssueCount && totalLicenseIssueCount > 0;

        // Use AutoModeScanningState when both scans are running AND we have no results yet
        const bothScansRunning = autoRapidScanRunning && autoLicenseScanRunning;
        const noResultsYet = !hasRapidResults && !hasLicenseResults;

        if (bothScansRunning && noResultsYet) {
            const state: AutoModeScanningState = {
                ...baseAutoState,
                type: LocalViewStateType.AutoScanning,
                rapidScan: autoRapidScanEntitled ? {
                    scanning: autoRapidScanRunning
                } : undefined,
                licenseScan: (autoLicenseScanEntitled && autoLicenseScanEnabled?.isEnabled) ? {
                    scanning: autoLicenseScanRunning
                } : undefined,
            };
            return state;
        }

        if (!hasRapidResults && !hasLicenseResults && !autoRapidScanRunning && !autoLicenseScanRunning) {
            const state: AutoModeNoResultsState = {
                ...baseAutoState,
                type: LocalViewStateType.AutoNoResults,
                hasScanInfo: selectedScanInfo !== undefined,
                rapidScan: autoRapidScanEntitled ? {
                    scanning: false
                } : undefined,
                licenseScan: (autoLicenseScanEntitled && autoLicenseScanEnabled?.isEnabled) ? {
                    scanning: false
                } : undefined,
            };
            return state;
        }

        // This allows us to show results from completed scans while other scans are still running
        const hasCategories = categoryItems && categoryItems.length > 0;

        const state: AutoModeResultsState = {
            ...baseAutoState,
            type: LocalViewStateType.AutoResults,
            rapidScan: autoRapidScanEntitled ? {
                scanning: autoRapidScanRunning,
                categoryIssues: hasCategories ? categoryItems : undefined,
                flatIssues: !hasCategories ? issuesList : undefined,
                totalIssueCount: totalIssueCount ?? 0,
            } : undefined,
            licenseScan: (autoLicenseScanEntitled && autoLicenseScanEnabled?.isEnabled) ? {
                scanning: autoLicenseScanRunning,
                issues: licenseIssuesList,
                totalIssueCount: totalLicenseIssueCount ?? 0,
                lastScanStatus: lastScanStatus,
                lastScanDate: selectedScanInfo?.getAnalysistime()?.toDate() ?? new Date(),
            } : undefined,
        };
        return state;
    }

    /**
     * Builds the state for Auto changed-files mode.
     * Follows Signal's simpler pattern: single status node, always categorized results,
     * no license scan categories.
     */
    private async buildAutoChangedFilesModeState(loading?: boolean): Promise<AutoChangedFilesModeState> {
        const searchFilter = this.services.filter.getSearchFilterValue();
        const scanFileScope = this.services.scanStatusCoordinator.getCurrentScanFileScope();
        const selectedFolder = await this.getSelectedFolder(scanFileScope);

        const baseState = {
            scanMode: ScanMode.Auto as const,
            pageControls: this.pageControls,
            scanFileScope: scanFileScope!,
            searchFilter,
            selectedFolder,
        };

        if (loading) {
            const state: AutoChangedFilesLoadingState = {
                ...baseState,
                type: LocalViewStateType.AutoChangedFilesLoading,
                loadingReason: 'refreshing',
            };
            return state;
        }

        if (this.services.scan.isChangedFileScanCancelling()) {
            const state: AutoChangedFilesScanCancellingState = {
                ...baseState,
                type: LocalViewStateType.AutoChangedFilesScanCancelling,
            };
            return state;
        }

        if (await this.services.scan.isLocalViewAutoChangedFileScanRunning()) {
            const state: AutoChangedFilesScanningState = {
                ...baseState,
                type: LocalViewStateType.AutoChangedFilesScanning,
            };
            return state;
        }

        const { selectedScanInfo } = await this.services.issues.getAvailableScanInfos();
        const scanInfoStatus = getScanStatus(selectedScanInfo);

        if (scanInfoStatus === RefreshStatus.Status.FAILED) {
            const state: AutoChangedFilesScanFailedState = {
                ...baseState,
                type: LocalViewStateType.AutoChangedFilesScanFailed,
                lastScanStatus: RefreshStatus.Status.FAILED,
                lastScanDate: selectedScanInfo?.getAnalysistime()?.toDate() ?? new Date(),
            };
            return state;
        }

        if (scanInfoStatus === RefreshStatus.Status.CANCELLED) {
            const state: AutoChangedFilesScanCancelledState = {
                ...baseState,
                type: LocalViewStateType.AutoChangedFilesScanCancelled,
            };
            return state;
        }

        const totalIssueCount = this.services.issues.getTotalIssueCount();

        // totalIssueCount is undefined when clearIssues() has run but loadPage() hasn't completed yet.
        // In that case, show loading state to avoid a flash of "no results" during the refresh cycle.
        if (totalIssueCount === undefined) {
            const state: AutoChangedFilesLoadingState = {
                ...baseState,
                type: LocalViewStateType.AutoChangedFilesLoading,
                loadingReason: 'refreshing',
            };
            return state;
        }

        const issuesList = await this.services.issues.getIssues();
        const categoryItems = this.services.issues.getCategoryItemsList();

        if (totalIssueCount === 0 || issuesList.length === 0) {
            const state: AutoChangedFilesNoResultsState = {
                ...baseState,
                type: LocalViewStateType.AutoChangedFilesNoResults,
                hasScanInfo: selectedScanInfo !== undefined,
            };
            return state;
        }

        const state: AutoChangedFilesResultsState = {
            ...baseState,
            type: LocalViewStateType.AutoChangedFilesResults,
            categoryIssues: categoryItems,
            totalIssueCount,
        };
        return state;
    }

    /**
     * Builds the state for Signal (AI-powered) scan mode.
     * Signal mode is a special Project mode variant with AI capabilities.
     */
    private async buildSignalModeState(loading?: boolean): Promise<SignalModeState> {
        const { selectedScanType, selectedScanInfo } = await this.services.issues.getAvailableScanInfos();
        const lastScanStatus = getScanStatus(selectedScanInfo);
        const searchFilter = this.services.filter.getSearchFilterValue();
        let scanFileScope = this.services.scanStatusCoordinator.getCurrentScanFileScope();

        // Only include timer info when in Code Changes scope — hide timer node for Active File scope
        const isTimerConfiguredForUI = this.services.signalTimer.isTimerBasedScanEnabledForUI();
        const isTimerRunning = this.services.signalTimer.isTimerActive();

        const timerInfo = scanFileScope !== RefreshResultsRequest.Tier.FAST ? {
            isActive: isTimerConfiguredForUI,
            nextScanTime: isTimerRunning ? this.services.signalTimer.getNextScanTime() : undefined,
            lastScanTime: this.services.signalTimer.getLastScanTime(),
        } : undefined;

        const selectedFolder = await this.getSelectedFolder(scanFileScope);

        const baseSignalState = {
            scanMode: ScanMode.Manual as const,
            pageControls: this.pageControls,
            scanFileScope: scanFileScope,
            searchFilter,
            selectedScanType,
            timerInfo,
            selectedFolder,
        };

        // Check if we're in a loading state first (UI refresh, not scan)
        if (loading) {
            const state: SignalModeLoadingState = {
                ...baseSignalState,
                type: LocalViewStateType.SignalLoading,
                loadingReason: 'refreshing',
            };
            return state;
        }

        // For Signal scans, determine scan progress based on actual scan state
        let scanRunning = false;
        const currentScanFileScope = this.services.scanStatusCoordinator.getCurrentScanFileScope();

        if (currentScanFileScope === RefreshResultsRequest.Tier.FAST) {
            // For FAST tier, only show scan progress for the currently active file
            const activeFilePath = window.activeTextEditor?.document.uri.fsPath;
            if (activeFilePath) {
                const normalizedActiveFilePath = normalizeDriveLetter(activeFilePath);
                scanRunning = this.services.scan.isLocalViewSignalScanRunningForFile(normalizedActiveFilePath);
            }
        } else {
            // For ALLUNCOMMITTED/REFERENCEBRANCH, show scan progress regardless of active file
            scanRunning = await this.services.scan.isLocalViewSignalScanRunning();
        }

        if (this.services.scan.isSignalScanCancelling()) {
            const state: SignalModeScanCancellingState = {
                ...baseSignalState,
                type: LocalViewStateType.SignalScanCancelling,
            };
            return state;
        }

        if (scanRunning) {
            const state: SignalModeScanningState = {
                ...baseSignalState,
                type: LocalViewStateType.SignalScanning,
                lastScanDate: selectedScanInfo?.getAnalysistime()?.toDate(),
            };
            return state;
        }

        if (lastScanStatus === RefreshStatus.Status.FAILED) {
            const state: SignalModeScanFailedState = {
                ...baseSignalState,
                type: LocalViewStateType.SignalScanFailed,
                lastScanStatus: RefreshStatus.Status.FAILED,
                lastScanDate: selectedScanInfo?.getAnalysistime()?.toDate() ?? new Date(),
            };
            return state;
        }

        if (lastScanStatus === RefreshStatus.Status.CANCELLED) {
            if (currentScanFileScope === RefreshResultsRequest.Tier.FAST) {
                const activeFilePath = window.activeTextEditor?.document.uri.fsPath;
                if (activeFilePath) {
                    const normalizedActiveFilePath = normalizeDriveLetter(activeFilePath);
                    const lastScannedFilePath = getService(ScanService.id).getLastSignalScanFilePath();
                    if (lastScannedFilePath !== normalizedActiveFilePath) {
                        const state: SignalModeNoResultsState = {
                            ...baseSignalState,
                            type: LocalViewStateType.SignalNoResults,
                            hasScanInfo: selectedScanInfo !== undefined,
                            activeFileNotScanned: true,
                        };
                        return state;
                    }
                }
            }
            const state: SignalModeScanCancelledState = {
                ...baseSignalState,
                type: LocalViewStateType.SignalScanCancelled,
            };
            return state;
        }

        const categoryItems = this.services.issues.getCategoryItemsList();
        const totalIssueCount = this.services.issues.getTotalIssueCount();

        if (!totalIssueCount || totalIssueCount === 0 || !categoryItems || categoryItems.length === 0) {
            let activeFileNotScanned: boolean | undefined;
            if (currentScanFileScope === RefreshResultsRequest.Tier.FAST) {
                const activeFilePath = window.activeTextEditor?.document.uri.fsPath;
                if (activeFilePath) {
                    const normalizedActiveFilePath = normalizeDriveLetter(activeFilePath);
                    const lastScannedFilePath = getService(ScanService.id).getLastSignalScanFilePath();
                    activeFileNotScanned = lastScannedFilePath !== normalizedActiveFilePath;
                }
            }
            const state: SignalModeNoResultsState = {
                ...baseSignalState,
                type: LocalViewStateType.SignalNoResults,
                hasScanInfo: selectedScanInfo !== undefined,
                activeFileNotScanned,
            };
            return state;
        }

        const state: SignalModeResultsState = {
            ...baseSignalState,
            type: LocalViewStateType.SignalResults,
            categoryIssues: categoryItems,
            totalIssueCount,
        };
        return state;
    }
}
