/**
 * Wrap a "get" call to the container, using the generic type of the ServiceID to enforce return type safety
*/
export function getService<T>(serviceId: ServiceId<T>): T {
    return container.get(serviceId.id);
}

/**
 * ID class for a Service
 * Every Service should contain a ServiceId, with the generic type set to the type of the containing service
 * e.g:

abstract class TestService {
    static readonly id:ServiceId<TestService> = {
        id:TestService.name
    };
}

 * This allows us to request services based on ServiceID, and enforce type safety in service retrieval
 * e.g:
let testService = serviceContainer.get(TestService.id);
 * The TS Compiler knows testService is of type "TestService"
 *
 * this is as opposed to:
let testService : TestService = serviceContainer.container.get("testServiceId")
 * the TS compiler needs the cast to  "TestService" to infer the service type
*/
export interface ServiceId<T> {
    id: string;
}

// Allow direct access to the container
// Where possible, it is recommended that services are retrieved via `getService`, for type safety
export { container };

export namespace TestAccess {
    // eslint-disable-next-line no-inner-declarations
    export function setServiceContainer(testContainer: ContainerBuilder) {
        container = testContainer;
    }
}
