import { ScanConfig } from "@codesight/codesight-controller-proto/controller_proto/v0/scan_config_pb";
import { CheckScanResultsExistRequest, ExportScanResultsRequest, GetScanResultsInfoRequest } from "@codesight/codesight-controller-proto/controller_proto/v1/export_scan_results_service_pb";
import { getLogger } from "../utils/logger";
import { AnalysisContextService } from "./analysisContextService";
import { ControllerClientService } from "./controllerClientService";
import { ServiceId, getService } from "./serviceContainer";

export interface ScanResultsInfo {
    scanResultsDir: string;
    scanResultsFilePath: string;
    exportFileName: string;
}

export abstract class ExportScanResultsService {
    static readonly id: ServiceId<ExportScanResultsService> = { id: ExportScanResultsService.name };
    abstract getScanResultsInfo(scanType: ScanConfig.ScanType): Promise<ScanResultsInfo>;
    abstract checkScanResultsExist(scanType: ScanConfig.ScanType): Promise<boolean>;
    abstract exportScanResults(scanType: ScanConfig.ScanType, exportPath: string, fileName: string,): Promise<boolean>;
    abstract isScanTypeSupported(scanType: ScanConfig.ScanType.Type): boolean;
}

export class ExportScanResultsServiceImpl extends ExportScanResultsService {
    async getScanResultsInfo(scanType: ScanConfig.ScanType): Promise<ScanResultsInfo> {
        try {
            const exportClient = await getService(ControllerClientService.id).getExportScanResultsServiceClient();
            const contextId = getService(AnalysisContextService.id).getAnalysisContextId();

            const request = new GetScanResultsInfoRequest();
            request.setContextid(contextId);
            request.setScantype(scanType);
            
            const response = await exportClient.getScanResultsInfo(request);
            
            const error = response.getError();
            if (error && error.getMessage()) {
                throw new Error(`Failed to get scan results info: ${error.getMessage()}`);
            }
          
            return {
                scanResultsDir: response.getScanresultsdir(),
                scanResultsFilePath: response.getScanresultsfilepath(),
                exportFileName: response.getExportfilename()
            };
        } catch (error) {
            getLogger().error('Failed to get scan results info from controller', error);
            throw error;
        }
    }

    async checkScanResultsExist(scanType: ScanConfig.ScanType): Promise<boolean> {
        try {
            const exportClient = await getService(ControllerClientService.id).getExportScanResultsServiceClient();
            const contextId = getService(AnalysisContextService.id).getAnalysisContextId();

            const request = new CheckScanResultsExistRequest();
            request.setContextid(contextId);
            request.setScantype(scanType);
            
            const response = await exportClient.checkScanResultsExist(request);
            
            const error = response.getError();
            if (error && error.getMessage()) {
                getLogger().warn(`Error checking scan results existence: ${error.getMessage()}`);
                return false;
            }
            
            return response.getScanresultsexist();
        } catch (error) {
            getLogger().error('Failed to check scan results existence from controller', error);
            return false;
        }
    }

    async exportScanResults(scanType: ScanConfig.ScanType, exportPath: string, fileName: string, ): Promise<boolean> {
        try {
            const exportClient = await getService(ControllerClientService.id).getExportScanResultsServiceClient();
            const contextId = getService(AnalysisContextService.id).getAnalysisContextId();

            const request = new ExportScanResultsRequest();
            request.setContextid(contextId);
            request.setScantype(scanType);
            request.setExportfilepath(exportPath);
            request.setExportfilename(fileName);
           
        
            const response = await exportClient.exportScanResults(request);
            
            const error = response.getError();
            if (error && error.getMessage()) {
                getLogger().error(`Failed to export scan results: ${error.getMessage()}`);
                return false;
            }
            
            return true;
        } catch (error) {
            getLogger().error('Failed to export scan results from controller', error);
            return false;
        }
    }

    isScanTypeSupported(scanType: ScanConfig.ScanType.Type): boolean {
        return this.supportedScanTypes.includes(scanType);
    }

    private readonly supportedScanTypes: ScanConfig.ScanType.Type[] = [
        ScanConfig.ScanType.Type.BLACKDUCK,
        ScanConfig.ScanType.Type.COVERITY,
        ScanConfig.ScanType.Type.COVERITYCLI,
        ScanConfig.ScanType.Type.SIGMA,
        ScanConfig.ScanType.Type.POLARIS,
    ];

    private readonly unsupportedScanTypes: ScanConfig.ScanType.Type[] = [
        ScanConfig.ScanType.Type.SIGNAL,
    ];
}