import { AnalysisContext } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_context_pb";
import { createHash } from "crypto";
import { normalizeDriveLetter } from '../utils/fileUtils';
import { CaptureProviderService } from "./captureProviderService";
import { getService, ServiceId } from "./serviceContainer";
import { WorkspaceService } from "./workspaceService";


/**
 * Service for the creation of the analysis context for the current workspace
 */
export abstract class AnalysisContextService {
    static readonly id: ServiceId<AnalysisContextService> = { id: AnalysisContextService.name };

    /**
     * Get the analysis context id for the current workspace
     */
    abstract getAnalysisContextId(): AnalysisContext.Id;

    /**
     * Construct an analysis context for the current workspace
     */
    abstract buildAnalysisContext(): AnalysisContext;

    /**
     * Gets the root of the analysis context or "" if no workspace is open
     */
    abstract getContextRoot(): string;

}

export class AnalysisContextServiceImpl extends AnalysisContextService {

    getAnalysisContextId(): AnalysisContext.Id {
        let workspaceService = getService(WorkspaceService.id);
        let workspaceName = workspaceService.getWorkspaceName();
        let workspaceLocation = workspaceService.getWorkspaceLocation();
        let contextId = new AnalysisContext.Id();
        if (!workspaceName || !workspaceLocation) {
            // no folders are open in the workspace
            contextId.setValue("empty-workspace");
            return contextId;
        }
        contextId.setValue(workspaceLocation.path);
        return contextId;
    }

    buildAnalysisContext(): AnalysisContext {
        let analysisContext = new AnalysisContext();
        let ref = new AnalysisContext.Ref();
        let captureConfig = getService(CaptureProviderService.id).buildCaptureConfiguration();
        analysisContext.setCapturesettings(captureConfig);

        let acVersion = new AnalysisContext.Version();
        let hash = createHash('sha256');
        hash.update(captureConfig.serializeBinary());
        acVersion.setValue(hash.digest('hex'));

        ref.setVersion(acVersion);
        ref.setId(this.getAnalysisContextId());
        analysisContext.setRef(ref);
        let contextRoot = getService(WorkspaceService.id).getWorkspaceLocation();

        if (contextRoot) {
            let path = normalizeDriveLetter(contextRoot.fsPath);
            analysisContext.setContextroot(path);
        }

        return analysisContext;
    }

    getContextRoot(): string {
        let workspaceLocation = getService(WorkspaceService.id).getWorkspaceLocation();

        if (workspaceLocation) {
            return normalizeDriveLetter(workspaceLocation.fsPath);
        }

        return "";
    }
}