import { CancelRequest, CancelResponse, MonitorEventNotificationRequest, MonitorResultsNotification, MonitorResultsRequest, RefreshResultsRequest, RefreshResultsResponse, StatusRequest, StatusResponse, SyncAnalysisContextRequest, SyncAnalysisContextResponse } from "@codesight/codesight-controller-proto/controller_proto/v0/analysis_service_pb";
import { NotificationMessage } from "@codesight/codesight-controller-proto/controller_proto/v0/notification_message_pb";
import * as analysisServiceGrpc from "@codesight/codesight-controller-proto/controller_proto/v1/analysis_service_grpc_pb";
import { GetScanInfoRequest, GetScanInfoResponse } from '@codesight/codesight-controller-proto/controller_proto/v1/analysis_service_pb';
import { ClientReadableStream, credentials } from '@grpc/grpc-js';
import { getGrpcLimit } from '../utils/environmentUtils';

/**
 * Defines the interface points with the controller's `AnalysisService`
 */
export interface AnalysisServiceClient {
    /**
	 * Synchronize context with Controller, so it could be referenced by using a contextId and version
     * Instead of needing to resupply the context with every call
	 */
    syncAnalysisContext(request: SyncAnalysisContextRequest): Promise<SyncAnalysisContextResponse>;

    /**
	 * Ensure results are up to date for a selected set of files.
	 * This will perform any required actions to ensure the analysis results are up to date for the provided file set.
	 */
    refreshResults(request: RefreshResultsRequest): Promise<RefreshResultsResponse>;

    /**
	 * Get current processing (analysis) status for a given Context
	 */
    getStatus(request: StatusRequest): Promise<StatusResponse>;

	/**
	 * Cancel running or queued jobs
	 */
    cancelJobs(cancelRequest: CancelRequest): Promise<CancelResponse>;

    /**
	 * Retrieve all available file scan results related to a scan type
	 */
    getScanInfo(request: GetScanInfoRequest): Promise<GetScanInfoResponse>;

    /**
	 * Create a channel to monitor a set of the results associated with (produced by) AnalysisContext
	 * If results set associated with a AnalysisContext on a controller changes (for example, new results arrived from
	 * the underlying scan) it will notify all monitoring channels that results set have changed, and clients
	 * will request issues through GetResults().
	 * This channel is represented by returning a never-ending stream (array, list)
	 * of ResultsStatus notifications encapsulated in MonitorResultsNotification
	 */
    monitorResults(request: MonitorResultsRequest): Promise<ClientReadableStream<MonitorResultsNotification>>;

    /**
     * Create a channel to monitor for notification messages from the controller.
     */
    monitorNotifications(request: MonitorEventNotificationRequest): Promise<ClientReadableStream<NotificationMessage>>;
}

export class AnalysisServiceClientImpl implements AnalysisServiceClient {
    private client: analysisServiceGrpc.AnalysisServiceClient;
    private address: string;

    constructor(connectionAddress: string) {
        this.client = new analysisServiceGrpc.AnalysisServiceClient(connectionAddress, credentials.createInsecure(), {'grpc.max_receive_message_length': getGrpcLimit(), 'grpc.enable_http_proxy': 0});
        this.address = connectionAddress;
    }

    syncAnalysisContext(request: SyncAnalysisContextRequest): Promise<SyncAnalysisContextResponse> {
        return new Promise<SyncAnalysisContextResponse>((resolve, reject) => {
            this.client.syncAnalysisContext(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }

    refreshResults(request: RefreshResultsRequest): Promise<RefreshResultsResponse> {
        return new Promise<RefreshResultsResponse>((resolve, reject) => {
            this.client.refreshResults(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }

    getStatus(request: StatusRequest): Promise<StatusResponse> {
        return new Promise<StatusResponse>((resolve, reject) => {
            this.client.getStatus(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }

    cancelJobs(request: CancelRequest): Promise<CancelResponse> {
        return new Promise<CancelResponse>((resolve, reject) => {
            this.client.cancel(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }

    getScanInfo(request: GetScanInfoRequest): Promise<GetScanInfoResponse> {
        return new Promise<GetScanInfoResponse>((resolve, reject) => {
            this.client.getScanInfo(request, (error, response) => {
                error ? reject(error) : resolve(response);
            });
        });
    }

    monitorNotifications(request: MonitorEventNotificationRequest): Promise<ClientReadableStream<NotificationMessage>> {
        return Promise.resolve(this.client.monitorEventNotifications(request));
    }

    monitorResults(request: MonitorResultsRequest): Promise<ClientReadableStream<MonitorResultsNotification>> {
        return Promise.resolve(this.client.monitorResults(request));
    }

}