import { Semaphore } from "prex";

/**
 * Debounce utility function that delays the execution of a function until after a specified wait time
 * has elapsed since the last time it was invoked. Useful for preventing excessive API calls or UI updates.
 * 
 * @param func The function to debounce
 * @param wait The number of milliseconds to delay
 * @returns A debounced version of the original function
 */
export function debounce<T extends (...args: any[]) => void>(func: T, wait: number): (...args: Parameters<T>) => void {
    let timeout: NodeJS.Timeout;
    return function(this: any, ...args: Parameters<T>) {
        clearTimeout(timeout);
        timeout = setTimeout(() => func.apply(this, args), wait);
    };
}

/**
 * A construct to solve the problem of "I want to run a task at most every X ms, know when a given job completes, and get the result"
 * 
 * When a job is queued, if it has been at least X ms since the last time the job was run, the job will be run immediately
 * 
 * If it has been less than X ms, a new job will be added to the queue.
 *  Jobs waiting in the queue will be merged.
 *  A job waiting in the queue will be started once the X ms has elapsed since the previous job was started.
 * 
 * Callers can await queueJob() to determine when the queued job has completed, and to get its result 
 */
 export class ThenableBatch<T> {
    private readonly runEveryXms:number;
    private readonly job:()=> Promise<T>;

    private addedDuringTimeout : ((t:T)=>void)[] = [];
    private timeoutRunning :boolean = false;
    
    private lock = new Semaphore(1, 1);

    constructor(runEveryXms:number, job:()=> Promise<T> ){
        this.runEveryXms = runEveryXms;
        this.job = job;
    }

    public async queueJob() : Promise<T>{
        await this.lock.wait();
        if(this.timeoutRunning){
            let onComplete : (t:T)=> void = (t:T)=>{};
            const promise = new Promise<T>(resolve=>{
                onComplete = (t:T)=>{
                    resolve(t);
                };
            });
            this.addedDuringTimeout.push(onComplete);
            this.lock.release();
            return promise;
        } else {
            // run the job right away. Start a timeout
            this.startTimeout();
            this.lock.release();
            return this.job();
        }
    }

    private startTimeout() {
        this.timeoutRunning = true;
        this.createTimeout(()=>{
            this.runQueue();
        });
    }

    // This is abstracted to allow for replacement in testing
    protected createTimeout(callback:()=>void){
        setTimeout(callback, this.runEveryXms);
    }

    private runQueue() {
        // eslint-disable-next-line @typescript-eslint/no-floating-promises
        this.lock.wait().then(()=>{
            this.timeoutRunning = false;
            if(this.addedDuringTimeout.length !== 0){
                const currentRunBatch = this.addedDuringTimeout;
                this.addedDuringTimeout = [];
                this.startTimeout();
                // eslint-disable-next-line @typescript-eslint/no-floating-promises
                this.job().then((value:T)=>{
                    currentRunBatch.forEach(resolve=>{
                        resolve(value);
                    });
                });
            }
            this.lock.release();
        });
    }
}


/**
 * A construct to solve the problem:
 * - I have a job that is running too frequently, and I wan't to put some constraints on how often it is called.
 * - I don't need it to run more than every X ms, and I don't need two to run concurrently.
 * - I don't care when it completes, or what the result is.
 *
 * An example task that benefited from this construct is getResults(). Some scans can produce new results multiple times a
 * seconds. Calling getResults() at this frequency hurts performance. Batching the calls with this construct Reduced the
 * number of getResults() calls & improves performance.
 *
 * When a job is queued, if it has not been X ms since the last time the job was run, or if a previous call to the job is
 * still running, then the job will be queued. Jobs in the queue will be merged and will run as soon as the timeout expires
 * and the previous job completes. Conversely, if it has been X ms since the last time the job was run, and any previous call
 * to the job is terminated, then the new job will run immediately.
 */

enum Trigger {
    Timeout,
    JobCompleted
}

 export class Batch {
    private readonly runEveryXms:number;
    private readonly job:()=> void;

    private jobTrigger: Trigger | undefined;
    private timeoutRunning : boolean = false;
    private jobRunning : boolean = false;

    constructor(runEveryXms:number, job:()=> void ){
        this.runEveryXms = runEveryXms;
        this.job = job;
    }

    public batchJob(){
        if (!this.timeoutRunning && !this.jobRunning) {
            // eslint-disable-next-line @typescript-eslint/no-floating-promises
            this.runJob();
        } else if (this.timeoutRunning) {
            this.jobTrigger = Trigger.Timeout;
        } else {
            this.jobTrigger = Trigger.JobCompleted;
        }
    }

    private startTimeout() {
        this.timeoutRunning = true;
        this.createTimeout(()=>{
            this.timeoutRunning = false;
            if (this.jobTrigger === Trigger.Timeout) {
                if (this.jobRunning) {
                    this.jobTrigger = Trigger.JobCompleted;
                } else {
                    this.jobTrigger = undefined;
                    // eslint-disable-next-line @typescript-eslint/no-floating-promises
                    this.runJob();
                }
            }
        });
    }

    protected async runJob() {
        this.jobRunning = true;
        this.startTimeout();
        await this.job();
        if (this.jobTrigger === Trigger.JobCompleted) {
            this.jobTrigger = undefined;
            // eslint-disable-next-line @typescript-eslint/no-floating-promises
            this.runJob();
        } else {
            this.jobRunning = false;
        }
    }

    // This is abstracted to allow for replacement in testing
    protected createTimeout(callback:()=>void){
        setTimeout(callback, this.runEveryXms);
    }
}