import { GetRegistrationInfoRequest } from "@codesight/codesight-controller-proto/controller_proto/v0/license_service_pb";
import { ControllerClientService } from "../services/controllerClientService";
import { getService, ServiceId } from "../services/serviceContainer";
import { getLogger } from "../utils/logger";

export abstract class LicenseService {
    static readonly id: ServiceId<LicenseService> = { id: LicenseService.name };

    /**
     * Returns the email address user has registered with
     */
    abstract getRegistrationEmail(): Promise<string>;
}

export class LicenseServiceImpl implements LicenseService {
    async getRegistrationEmail(): Promise<string> {
        const licenseServiceClient = await getService(ControllerClientService.id).getLicenseServiceClient();
        let emailAddress = "";
        try {
            let registrationInfo = await licenseServiceClient.getRegistrationInfo(new GetRegistrationInfoRequest());
            emailAddress = registrationInfo.getEmailaddress();
        } catch (error) {
            getLogger().warn(`getRegistrationInfo call resulted in an error, err=${error}`);
        }

        return emailAddress;
    }
}
