/**
 * Generates an HTML head section with the given title and with the given webview's content security policy
 *
 * @param title the title to show
 * @param webview the webview to generate the security policy for
 */
export function getWebviewHead(title: string, webview: Webview) {
    return `
    <meta http-equiv="Content-Security-Policy" content="default-src 'self' ${webview.cspSource}; script-src ${webview.cspSource} 'self' 'unsafe-inline' https:; style-src ${webview.cspSource} 'self' 'unsafe-inline' https:; img-src 'self' ${webview.cspSource} data:"/>
    <title>${title}</title>`;
}

