export function severityLocalizedText(severity: Severity): string {
    switch (severity) {
        case Severity.CRITICAL:
            return localize("issue.tooltip.severity.critical", "Critical");
        case Severity.HIGH:
            return localize("issue.tooltip.severity.high", "High");
        case Severity.MEDIUM:
            return localize("issue.tooltip.severity.medium", "Medium");
        case Severity.LOW:
            return localize("issue.tooltip.severity.low", "Low");
        case Severity.AUDIT:
            return localize("issue.tooltip.severity.audit", "Audit");
        case Severity.INFO:
            return localize("issue.tooltip.severity.info", "Info");
        case Severity.UNSPECIFIED:
            return localize("issue.tooltip.severity.unspecified", "Unspecified");
        default:
            getLogger().warn("attempt to find localized text for unknown severity type");
            return "";
    }
}

export function referenceStyleLocalizedText(referenceStyle: Component.ReferenceStyle): string {
    let rsText: string;
    switch (referenceStyle) {
        case Component.ReferenceStyle.DIRECT:
            rsText = localize("issue.tooltip.referencestyle.direct", "Direct");
            break;
        case Component.ReferenceStyle.TRANSITIVE:
            rsText = localize("issue.tooltip.referencestyle.transitive", "Transitive");
            break;
        default:
            getLogger().warn("attempt to find localized text for unknown reference style");
            rsText = "";
            break;
    }

    return rsText;
}

export function issueCategoryLocalizedText(category: CategoryItems.CategoryName): string {
    let categoryName: string;
    switch (category) {
        case CategoryItems.CategoryName.SECRETS:
            categoryName = localize("issue.category.secrets", "Secrets");
            break;
        case CategoryItems.CategoryName.VULNERABILITIES:
            categoryName = localize("issue.category.vulnerabilities", "Vulnerabilities");
            break;
        default:
            getLogger().warn("attempt to find localized text for unknown category");
            categoryName = "";
            break;
    }

    return categoryName;
}

export function escapeHTMLTags(text: string | undefined): string {
    if (text) {
        return text.replace("<", "&lt;").replace(">", "&gt;");
    }
    return "";
}

export async function addDelay(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms)); // add a delay in milliseconds
}

