import { TextEditor } from 'vscode';
import { normalizeDriveLetter } from './fileUtils';

/**
 * Checks if the editor is a non-file editor that should not trigger certain operations.
 * Returns true for editors with non-file URI schemes or without file system paths.
 *
 * @param editor The VS Code text editor
 * @returns true if the editor is a non-file editor, false otherwise
 */
export function isNonFileEditor(editor: TextEditor): boolean {
    const uri = editor.document.uri;

    // Skip non-file schemes
    if (uri.scheme !== 'file') {
        return true;
    }

    // Skip if no file path
    if (!uri.fsPath) {
        return true;
    }

    return false;
}

/**
 * Determines if a component should reload based on the active editor change.
 * This is the common logic pattern used across marker service and issue list presenters.
 *
 * @param editor The current active text editor (may be undefined)
 * @param lastActiveFilePath The previously tracked file path
 * @returns Object containing shouldReload decision and newFilePath to track
 */
export function shouldReloadForEditorChange(
    editor: TextEditor | undefined,
    lastActiveFilePath: string | undefined
): { shouldReload: boolean; newFilePath: string | undefined } {
    // Handle no active editor
    if (!editor) {
        return { shouldReload: false, newFilePath: undefined };
    }

    // Exclude non-file editors (webviews, settings, output panels, etc.)
    if (isNonFileEditor(editor)) {
        return { shouldReload: false, newFilePath: undefined };
    }

    // Compare normalized file paths
    const currentPath = normalizeDriveLetter(editor.document.uri.fsPath);
    if (!currentPath) {
        // Empty fsPath - likely a webview or virtual document
        return { shouldReload: false, newFilePath: undefined };
    }

    // Check if file path actually changed
    const shouldReload = currentPath !== lastActiveFilePath;

    return { shouldReload, newFilePath: currentPath };
}