import { getFirstContentTitle } from "../../utils/notificationMessageUtils";
import { loadMessageBundle, LocalizeFunc } from "vscode-nls";
import { ServiceId } from "../../services/serviceContainer";
import { NotificationViewProviderBase, NotificationViewProviderBaseImpl } from "./notificationViewProviderBase";

const localize: LocalizeFunc = loadMessageBundle();

export abstract class NotificationViewProvider extends NotificationViewProviderBase {

    static readonly id: ServiceId<NotificationViewProvider> = { id: NotificationViewProvider .name };
}

export class NotificationViewProviderImpl extends NotificationViewProviderBaseImpl implements NotificationViewProvider {
    isScanDetailsView: boolean = false;

    async loadState() {
        // no-op
    }

    getViewTitle(): string {
        let notificationMessageTitle = "";

        if (this.notificationMessage !== undefined) {
            notificationMessageTitle = getFirstContentTitle(this.notificationMessage);
            if (notificationMessageTitle === "") {
                notificationMessageTitle = this.notificationMessage.getDescription();
            }
        }

        return notificationMessageTitle;
    }

    getViewIcon(): string {
        return this.getMessageSeverityClass(this.notificationMessage);
    }

    getViewContent(): string {
        let html = "";
        if (this.notificationMessage !== undefined) {
            html += this.getNotificationMessageContent(this.notificationMessage.getAdditionalcontentList(), 0);
        }

        return html;
    }
}