import { IssueDiffValue } from "@codesight/codesight-controller-proto/controller_proto/v1/issues_service_pb";

export enum ContextValue {
    copyable = "copyable",
    copyAllIssues = "copyAllIssues",
    teamViewSortStateAscending = "teamViewSortStateUp",
    teamViewSortStateDescending = "teamViewSortStateDown",
    scopeState = "scopeState",
    search = "search",
    sourceFilter = "sourceFilter",
    diffSourceAllSelected = "selectedDiffSourceAll",
    diffSourceNewSelected = "selectedDiffSourceNew",
    diffSourceFixedSelected = "selectedDiffSourceFixed",
    cancellableJob = "cancellableScanJob",
    openOnboarding = "openOnboarding",
    editCoverityServerInfo = "editCoverityServerInfo",
    editBlackDuckServerInfo = "editBlackDuckServerInfo",
    editPolarisServerInfo = "editPolarisServerInfo",
    editSRMServerInfo = "editSRMServerInfo",
    exportLogs = "exportLogs",
    scannable = "scannable",
    viewRemoteErrorDetails = "viewRemoteErrorDetails",
    viewLocalViewScanDetails = "viewLocalViewScanDetails",
    lockLocalIssueItem = "lockLocalIssueItem",
    lockRemoteIssueItem = "lockRemoteIssueItem"
}

export function getTreeItemContext(...contextValues: (ContextValue | undefined)[]): string {
    // Remove undefined and cast to ContextValue[]
    contextValues
        .filter((a) => a === undefined)
        .map((a) => <ContextValue>a);

    if (!contextValues) {
        return "";
    }
    return "codesight:" + contextValues.join(":");
}

export function getContextValuesForDiffSourceFilterState(diffFilter: IssueDiffValue | undefined): ContextValue[] {
    switch (diffFilter) {
        case IssueDiffValue.NEW:
            return [ContextValue.scopeState, ContextValue.diffSourceNewSelected];
        case IssueDiffValue.FIXED:
            return [ContextValue.scopeState, ContextValue.diffSourceFixedSelected];
        case IssueDiffValue.ALL:
        default:
            return [ContextValue.scopeState, ContextValue.diffSourceAllSelected];
    }
}